(* ========================================================================= *)
(* pc_moi_s35_minc: Moise GTM 47, Sec 35.1, Lemma 3 (p.251) in tube form:    *)
(* the annulus swap ANNULUS_SWAP (the term MOI_S35_ANNULUS_SWAP of           *)
(* pc_moi_s35_stmt.ml), as MOI_S5C_ANNULUS_SWAP_SPLIT with the sphere split  *)
(* MOI_SCH3_SPHERE_SPLIT as an antecedent (pc_moi_s35_all.ml discharges it). *)
(* ========================================================================= *)

needs "src/pc_moi_s35_stmt.ml";;
needs "src/pc_moi_sch3_stmt.ml";;
needs "src/pc_moi_sch3_amb2.ml";;
needs "src/pc_moi_s27.ml";;
needs "src/pc_moi_fnd_m3a.ml";;
needs "src/pc_moi_ptri.ml";;

prioritize_real();;
type_invention_error := true;;

(* Tactic helpers: act on the first assumption matching a pattern.          *)

let MOI_S5C_ASM (pat:term) (ttac:thm_tactic) : tactic =
  FIRST_ASSUM (fun th -> if can (term_match [] pat) (concl th) then ttac th
                         else failwith "MOI_S5C_ASM");;

let MOI_S5C_XASM (pat:term) (ttac:thm_tactic) : tactic =
  FIRST_X_ASSUM (fun th -> if can (term_match [] pat) (concl th) then ttac th
                           else failwith "MOI_S5C_XASM");;

(* Does the conclusion of th have the named constant as its head operator?  *)

let MOI_S5C_HEAD (s:string) (th:thm) =
  try fst(dest_const(fst(strip_comb(concl th)))) = s with Failure _ -> false;;

(* Real arithmetic using only the unquantified assumptions about one var.   *)

let MOI_S5C_VARITH (v:term) : tactic =
  REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th -> free_in v (concl th) &&
                                                 not(is_forall(concl th))))) THEN
  REAL_ARITH_TAC;;

(* ------------------------------------------------------------------------- *)
(* 1. The square annulus model of pl_annulus_with_ends, sup norm squares.   *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_IN_SQI = prove
 (`!r (x:real^2).
     x IN interval[--vector[r;r],vector[r;r]] <=>
     max (abs(x$1)) (abs(x$2)) <= r`,
  REWRITE_TAC[IN_INTERVAL; DIMINDEX_2; FORALL_2; VECTOR_NEG_COMPONENT;
              VECTOR_2] THEN REAL_ARITH_TAC);;

let MOI_S5C_IN_SQO = prove
 (`!r (x:real^2).
     x IN interval(--vector[r;r],vector[r;r]) <=>
     max (abs(x$1)) (abs(x$2)) < r`,
  REWRITE_TAC[IN_INTERVAL; DIMINDEX_2; FORALL_2; VECTOR_NEG_COMPONENT;
              VECTOR_2] THEN REAL_ARITH_TAC);;

let MOI_S5C_SQ_INTERIOR = prove
 (`!r. &0 < r
       ==> ~(interior(interval[--vector[r;r]:real^2,vector[r;r]]) = {})`,
  GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[INTERIOR_CLOSED_INTERVAL;
    GSYM MEMBER_NOT_EMPTY] THEN
  EXISTS_TAC `vec 0:real^2` THEN REWRITE_TAC[MOI_S5C_IN_SQO; VEC_COMPONENT] THEN
  ASM_REAL_ARITH_TAC);;

let MOI_S5C_SQ_RF = prove
 (`!r (x:real^2).
     &0 < r
     ==> (x IN relative_frontier(interval[--vector[r;r],vector[r;r]]) <=>
          max (abs(x$1)) (abs(x$2)) = r)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[RELATIVE_FRONTIER_NONEMPTY_INTERIOR; MOI_S5C_SQ_INTERIOR] THEN
  REWRITE_TAC[FRONTIER_CLOSED_INTERVAL; IN_DIFF; MOI_S5C_IN_SQI;
              MOI_S5C_IN_SQO] THEN REAL_ARITH_TAC);;

let MOI_S5C_IN_SQANN = prove
 (`!x:real^2.
     x IN interval[--vector[&2;&2],vector[&2;&2]] DIFF
          interval(--vector[&1;&1],vector[&1;&1]) <=>
     &1 <= max (abs(x$1)) (abs(x$2)) /\ max (abs(x$1)) (abs(x$2)) <= &2`,
  REWRITE_TAC[IN_DIFF; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO] THEN REAL_ARITH_TAC);;

let MOI_S5C_SQANN_POLYHEDRON = prove
 (`pl_polyhedron(interval[--vector[&2;&2],vector[&2;&2]] DIFF
                 interval(--vector[&1;&1],vector[&1;&1]):real^2->bool)`,
  SUBGOAL_THEN
   `interval[--vector[&2;&2],vector[&2;&2]] DIFF
    interval(--vector[&1;&1],vector[&1;&1]):real^2->bool =
    (interval[vector[-- &2;-- &2],vector[-- &1;&2]] UNION
     interval[vector[&1;-- &2],vector[&2;&2]]) UNION
    (interval[vector[-- &1;-- &2],vector[&1;-- &1]] UNION
     interval[vector[-- &1;&1],vector[&1;&2]])`
  SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_UNION; MOI_S5C_IN_SQANN; IN_INTERVAL;
                DIMINDEX_2; FORALL_2; VECTOR_2] THEN
    REWRITE_TAC[REAL_LE_MAX; REAL_MAX_LE; REAL_ABS_BOUNDS;
                REAL_ARITH `&1 <= abs x <=> &1 <= x \/ &1 <= --x`] THEN
    REAL_ARITH_TAC;
    REPEAT(MATCH_MP_TAC PL_POLYHEDRON_UNION THEN CONJ_TAC) THEN
    MATCH_MP_TAC POLYTOPE_IMP_PL_POLYHEDRON THEN REWRITE_TAC[POLYTOPE_INTERVAL]]);;

let MOI_S5C_CONVEX_CONE_RF = prove
 (`!t (b:real^N).
     convex t /\ compact t /\ b IN relative_interior t /\ ~(t = {b})
     ==> ~(b IN relative_frontier t) /\
         (!x y. x IN relative_frontier t /\ y IN relative_frontier t /\
                y IN segment[b,x] ==> y = x) /\
         UNIONS {segment[b,x] | x IN relative_frontier t} = t`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[relative_frontier; IN_DIFF] THEN ASM_REWRITE_TAC[];
    ASM_MESON_TAC[MOI_CON_RF_SEGMENT];
    REWRITE_TAC[GSYM SUBSET_ANTISYM_EQ; SUBSET; IN_UNIONS; EXISTS_IN_GSPEC] THEN
    CONJ_TAC THENL
     [X_GEN_TAC `y:real^N` THEN
      DISCH_THEN(X_CHOOSE_THEN `x:real^N` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `segment[b:real^N,x] SUBSET t` MP_TAC THENL
       [MATCH_MP_TAC SEGMENT_SUBSET_CONVEX THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[RELATIVE_INTERIOR_SUBSET; SUBSET; relative_frontier;
                      IN_DIFF; COMPACT_IMP_CLOSED; CLOSURE_CLOSED];
        ASM SET_TAC[]];
      X_GEN_TAC `y:real^N` THEN DISCH_TAC THEN
      MP_TAC(ISPECL [`t:real^N->bool`; `b:real^N`; `y:real^N`]
        SEGMENT_TO_RELATIVE_FRONTIER) THEN
      ASM_SIMP_TAC[COMPACT_IMP_BOUNDED] THEN MESON_TAC[]]]);;

let SPDR6_MAX_ABS_EQ = prove
 (`!a b r. &0 <= r
           ==> (max (abs a) (abs b) = r <=>
                a = r /\ --r <= b /\ b <= r \/ b = r /\ --r <= a /\ a <= r \/
                a = --r /\ --r <= b /\ b <= r \/ b = --r /\ --r <= a /\ a <= r)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[REAL_ARITH `max x y = r <=> x = r /\ y <= r \/ y = r /\ x <= r`;
              REAL_ABS_BOUNDS] THEN
  ASM_SIMP_TAC[REAL_ARITH `&0 <= r ==> (abs a = r <=> a = r \/ a = --r)`] THEN
  CONV_TAC TAUT);;

let MOI_S5C_SQ_RF_POLYHEDRON = prove
 (`!r. &0 < r
       ==> pl_polyhedron
             (relative_frontier(interval[--vector[r;r],vector[r;r]]):real^2->bool)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `relative_frontier(interval[--vector[r;r],vector[r;r]]):real^2->bool =
    (interval[vector[--r;--r],vector[--r;r]] UNION
     interval[vector[r;--r],vector[r;r]]) UNION
    (interval[vector[--r;--r],vector[r;--r]] UNION
     interval[vector[--r;r],vector[r;r]])`
  SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `x:real^2` THEN
    ASM_SIMP_TAC[MOI_S5C_SQ_RF] THEN
    REWRITE_TAC[IN_UNION; IN_INTERVAL; DIMINDEX_2; FORALL_2; VECTOR_2] THEN
    ASM_SIMP_TAC[SPDR6_MAX_ABS_EQ; REAL_LT_IMP_LE] THEN
    REWRITE_TAC[REAL_LE_ANTISYM; REAL_ARITH
     `(--r = (x:real^2)$1 <=> x$1 = --r) /\ (r = x$1 <=> x$1 = r) /\
      (--r = x$2 <=> x$2 = --r) /\ (r = x$2 <=> x$2 = r)`] THEN
    CONV_TAC TAUT;
    REPEAT(MATCH_MP_TAC PL_POLYHEDRON_UNION THEN CONJ_TAC) THEN
    MATCH_MP_TAC POLYTOPE_IMP_PL_POLYHEDRON THEN REWRITE_TAC[POLYTOPE_INTERVAL]]);;

let MOI_S5C_REAL_MAX_LMUL = prove
 (`!r a b. &0 <= r ==> max (r * a) (r * b) = r * max a b`,
  REPEAT STRIP_TAC THEN ASM_CASES_TAC `r = &0` THEN
  ASM_REWRITE_TAC[REAL_MUL_LZERO; REAL_MAX_ACI] THEN
  SUBGOAL_THEN `&0 < r` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[real_max] THEN ASM_SIMP_TAC[REAL_LE_LMUL_EQ] THEN
  COND_CASES_TAC THEN REWRITE_TAC[]);;

let MOI_S5C_N2_CMUL = prove
 (`!r (x:real^2).
     &0 <= r
     ==> max (abs((r % x)$1)) (abs((r % x)$2)) = r * max (abs(x$1)) (abs(x$2))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[VECTOR_MUL_COMPONENT; REAL_ABS_MUL] THEN
  ASM_SIMP_TAC[REAL_ARITH `&0 <= r ==> abs r = r`; MOI_S5C_REAL_MAX_LMUL]);;

let MOI_S5C_SQ_CONE_FACTS = prove
 (`!r. &0 < r
       ==> ~((vec 0:real^2) IN relative_frontier(interval[--vector[r;r],vector[r;r]])) /\
           (!x y. x IN relative_frontier(interval[--vector[r;r],vector[r;r]]) /\
                  y IN relative_frontier(interval[--vector[r;r],vector[r;r]]) /\
                  y IN segment[vec 0,x] ==> y = x) /\
           UNIONS {segment[vec 0,x] | x IN
                   relative_frontier(interval[--vector[r;r]:real^2,vector[r;r]])} =
           interval[--vector[r;r],vector[r;r]]`,
  GEN_TAC THEN DISCH_TAC THEN MATCH_MP_TAC MOI_S5C_CONVEX_CONE_RF THEN
  REWRITE_TAC[CONVEX_INTERVAL; COMPACT_INTERVAL] THEN CONJ_TAC THENL
   [ASM_SIMP_TAC[RELATIVE_INTERIOR_NONEMPTY_INTERIOR; MOI_S5C_SQ_INTERIOR] THEN
    REWRITE_TAC[INTERIOR_CLOSED_INTERVAL; MOI_S5C_IN_SQO; VEC_COMPONENT] THEN
    ASM_REAL_ARITH_TAC;
    REWRITE_TAC[EXTENSION; IN_SING; NOT_FORALL_THM] THEN
    EXISTS_TAC `vector[r;r]:real^2` THEN
    REWRITE_TAC[MOI_S5C_IN_SQI; CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2;
                VEC_COMPONENT] THEN ASM_REAL_ARITH_TAC]);;

let MOI_S5C_IN_RF2 = prove
 (`!x:real^2. x IN relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]) <=>
              max (abs(x$1)) (abs(x$2)) = &2`,
  GEN_TAC THEN MATCH_MP_TAC MOI_S5C_SQ_RF THEN REAL_ARITH_TAC);;

let MOI_S5C_IN_RF1 = prove
 (`!x:real^2. x IN relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]) <=>
              max (abs(x$1)) (abs(x$2)) = &1`,
  GEN_TAC THEN MATCH_MP_TAC MOI_S5C_SQ_RF THEN REAL_ARITH_TAC);;

(* Radial (conewise) extension of a PL self-homeomorphism of the outer      *)
(* square to the square annulus.                                             *)

let MOI_S5C_RADEXT = prove
 (`!(h:real^2->real^2) h'.
     pl_homeomorphism
       (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]),
        relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])) (h,h')
     ==> ?H H'.
           pl_homeomorphism
             (interval[--vector[&2;&2],vector[&2;&2]] DIFF
              interval(--vector[&1;&1],vector[&1;&1]),
              interval[--vector[&2;&2],vector[&2;&2]] DIFF
              interval(--vector[&1;&1],vector[&1;&1])) (H,H') /\
           (!x. x IN relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])
                ==> H x = h x) /\
           (!x. x IN relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])
                ==> H x = inv(&2) % h(&2 % x))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `R2 = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]):real^2->bool` THEN
  MP_TAC(SPEC `&2` MOI_S5C_SQ_CONE_FACTS) THEN
  ANTS_TAC THENL [REAL_ARITH_TAC; ASM_REWRITE_TAC[]] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`R2:real^2->bool`; `R2:real^2->bool`; `vec 0:real^2`;
                 `vec 0:real^2`; `h:real^2->real^2`; `h':real^2->real^2`]
    MOI_CON_CONE_MAP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [EXPAND_TAC "R2" THEN MATCH_MP_TAC MOI_S5C_SQ_RF_POLYHEDRON THEN
      REAL_ARITH_TAC;
      REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN EXISTS_TAC `vector[&2;&2]:real^2` THEN
      EXPAND_TAC "R2" THEN REWRITE_TAC[MOI_S5C_IN_RF2; VECTOR_2] THEN REAL_ARITH_TAC];
    ASM_REWRITE_TAC[]] THEN
  ABBREV_TAC `cm = moi_con_conemap R2 (vec 0:real^2) (vec 0:real^2) h` THEN
  ABBREV_TAC `cm' = moi_con_conemap R2 (vec 0:real^2) (vec 0:real^2) h'` THEN
  STRIP_TAC THEN
  SUBGOAL_THEN
   `!y:real^2 r. y IN R2 /\ &0 <= r /\ r <= &1 ==> cm(r % y) = r % (h:real^2->real^2) y`
  (LABEL_TAC "cmf") THENL
   [REPEAT STRIP_TAC THEN EXPAND_TAC "cm" THEN
    MP_TAC(ISPECL [`R2:real^2->bool`; `vec 0:real^2`; `vec 0:real^2`;
                   `h:real^2->real^2`; `y:real^2`; `r:real`] MOI_CON_CONEMAP_EQ) THEN
    ASM_REWRITE_TAC[VECTOR_SUB_RZERO; VECTOR_ADD_LID]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:real^2. z IN interval[--vector[&2;&2],vector[&2;&2]]
               ==> ?y r. y IN R2 /\ &0 <= r /\ r <= &1 /\ z = r % y`
  (LABEL_TAC "cone") THENL
   [GEN_TAC THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`R2:real^2->bool`; `vec 0:real^2`; `z:real^2`] MOI_CON_IN_CONE) THEN
    ASM_REWRITE_TAC[VECTOR_SUB_RZERO; VECTOR_ADD_LID] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:real^2 r. y IN R2 /\ &0 <= r
                 ==> max (abs((r % y)$1)) (abs((r % y)$2)) = &2 * r`
  (LABEL_TAC "nrm") THENL
   [REPEAT STRIP_TAC THEN ASM_SIMP_TAC[MOI_S5C_N2_CMUL] THEN
    UNDISCH_TAC `(y:real^2) IN R2` THEN EXPAND_TAC "R2" THEN REWRITE_TAC[MOI_S5C_IN_RF2] THEN
    DISCH_THEN SUBST1_TAC THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(!y. y IN R2 ==> (h:real^2->real^2) y IN R2) /\
                (!y. y IN R2 ==> (h':real^2->real^2) y IN R2) /\
                (!y. y IN R2 ==> h(h' y) = y)`
  (LABEL_TAC "hh") THENL
   [UNDISCH_TAC `pl_homeomorphism (R2,R2) (h:real^2->real^2,h')` THEN
    REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (cm:real^2->real^2)
      (interval[--vector[&2;&2],vector[&2;&2]] DIFF
       interval(--vector[&1;&1],vector[&1;&1])) =
    interval[--vector[&2;&2],vector[&2;&2]] DIFF
    interval(--vector[&1;&1],vector[&1;&1])`
  (LABEL_TAC "img") THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE] THEN X_GEN_TAC `z:real^2` THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `x:real^2` (CONJUNCTS_THEN2 SUBST1_TAC ASSUME_TAC)) THEN
      USE_THEN "cone" (MP_TAC o SPEC `x:real^2`) THEN ANTS_TAC THENL
       [UNDISCH_TAC `x IN interval[--vector[&2;&2],vector[&2;&2]] DIFF
                     interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN SET_TAC[];
        ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `y:real^2` (X_CHOOSE_THEN `r:real`
        STRIP_ASSUME_TAC)) THEN
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      SUBGOAL_THEN `(h:real^2->real^2) y IN R2` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      USE_THEN "cmf" (fun th -> SIMP_TAC[th; ASSUME `(y:real^2) IN R2`;
         ASSUME `&0 <= r`; ASSUME `r <= &1`]) THEN
      UNDISCH_TAC `r % y IN interval[--vector[&2;&2],vector[&2;&2]] DIFF
                     interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
      REWRITE_TAC[MOI_S5C_IN_SQANN] THEN
      USE_THEN "nrm" (fun th -> SIMP_TAC[th; ASSUME `(y:real^2) IN R2`;
         ASSUME `(h:real^2->real^2) y IN R2`; ASSUME `&0 <= r`]) THEN
      REAL_ARITH_TAC;
      DISCH_TAC THEN
      USE_THEN "cone" (MP_TAC o SPEC `z:real^2`) THEN ANTS_TAC THENL
       [UNDISCH_TAC `z IN interval[--vector[&2;&2],vector[&2;&2]] DIFF
                     interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN SET_TAC[];
        ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `w:real^2` (X_CHOOSE_THEN `r:real`
        STRIP_ASSUME_TAC)) THEN
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      EXISTS_TAC `r % (h':real^2->real^2) w` THEN
      SUBGOAL_THEN `(h':real^2->real^2) w IN R2 /\ h(h' w) = w` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      USE_THEN "cmf" (fun th -> SIMP_TAC[th; ASSUME `(h':real^2->real^2) w IN R2`;
         ASSUME `&0 <= r`; ASSUME `r <= &1`]) THEN
      ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `r % w IN interval[--vector[&2;&2],vector[&2;&2]] DIFF
                     interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
      REWRITE_TAC[MOI_S5C_IN_SQANN] THEN
      USE_THEN "nrm" (fun th -> SIMP_TAC[th; ASSUME `(w:real^2) IN R2`;
         ASSUME `(h':real^2->real^2) w IN R2`; ASSUME `&0 <= r`])];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`cm:real^2->real^2`; `cm':real^2->real^2`] THEN
  REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN
     `pl_homeomorphism
        (interval[--vector[&2;&2],vector[&2;&2]] DIFF
         interval(--vector[&1;&1],vector[&1;&1]),
         IMAGE (cm:real^2->real^2) (interval[--vector[&2;&2],vector[&2;&2]] DIFF
         interval(--vector[&1;&1],vector[&1;&1]))) (cm,cm')`
    MP_TAC THENL [ALL_TAC; USE_THEN "img" SUBST1_TAC THEN REWRITE_TAC[]] THEN
    MATCH_MP_TAC MOI_S27_PLH_RESTRICT THEN
    EXISTS_TAC `interval[--vector[&2;&2],vector[&2;&2]]:real^2->bool` THEN
    EXISTS_TAC `interval[--vector[&2;&2],vector[&2;&2]]:real^2->bool` THEN
    ASM_SIMP_TAC[LOCALLY_POLYHEDRAL_PL_POLYHEDRON; MOI_S5C_SQANN_POLYHEDRON] THEN
    SET_TAC[];
    ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real^2` THEN
    SIMP_TAC[MOI_S5C_SQ_RF; REAL_LT_01] THEN DISCH_TAC THEN
    SUBGOAL_THEN `&2 % (x:real^2) IN R2` ASSUME_TAC THENL
     [EXPAND_TAC "R2" THEN REWRITE_TAC[MOI_S5C_IN_RF2] THEN
      SIMP_TAC[MOI_S5C_N2_CMUL; REAL_ARITH `&0 <= &2`] THEN ASM_REWRITE_TAC[] THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
    USE_THEN "cmf" (MP_TAC o SPECL [`&2 % (x:real^2)`; `inv(&2)`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[VECTOR_MUL_ASSOC; REAL_ARITH `inv(&2) * &2 = &1`; VECTOR_MUL_LID]]);;

let MOI_S5C_PL_LINEAR = prove
 (`!(s:real^M->bool) (l:real^M->real^N).
     locally_polyhedral s /\ linear l ==> pl_map_on s l`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`s:real^M->bool`; `l:real^M->real^N`; `vec 0:real^N`]
    PL_MAP_ON_AFFINE) THEN
  ASM_REWRITE_TAC[VECTOR_ADD_RID; ETA_AX]);;

let MOI_S5C_SQ_RF_SCALE = prove
 (`!r c. &0 < r /\ &0 < c
         ==> pl_homeomorphism
               (relative_frontier(interval[--vector[r;r],vector[r;r]]):real^2->bool,
                relative_frontier(interval[--vector[c * r;c * r],vector[c * r;c * r]]))
               ((\x. c % x),(\x. inv c % x))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC HOMEOMORPHISM_IMP_PL_HOMEOMORPHISM THEN
  SUBGOAL_THEN `&0 < c * r` ASSUME_TAC THENL
   [ASM_MESON_TAC[REAL_LT_MUL]; ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^2. inv c % c % x = x /\ c % inv c % x = x` ASSUME_TAC THENL
   [ASM_SIMP_TAC[VECTOR_MUL_ASSOC; REAL_MUL_LINV; REAL_MUL_RINV; REAL_LT_IMP_NZ;
                 VECTOR_MUL_LID]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(!x:real^2. max (abs((c % x)$1)) (abs((c % x)$2)) = c * max (abs(x$1)) (abs(x$2))) /\
    (!x:real^2. max (abs((inv c % x)$1)) (abs((inv c % x)$2)) =
                inv c * max (abs(x$1)) (abs(x$2)))`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[MOI_S5C_N2_CMUL; REAL_LT_IMP_LE; REAL_LE_INV_EQ]; ALL_TAC] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[homeomorphism] THEN
    SIMP_TAC[CONTINUOUS_ON_CMUL; CONTINUOUS_ON_ID] THEN
    ASM_SIMP_TAC[EXTENSION; IN_IMAGE; MOI_S5C_SQ_RF] THEN CONJ_TAC THEN
    X_GEN_TAC `x:real^2` THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `y:real^2` STRIP_ASSUME_TAC) THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN EXISTS_TAC `inv c % (x:real^2)` THEN ASM_REWRITE_TAC[] THEN
      ASM_SIMP_TAC[REAL_MUL_ASSOC; REAL_MUL_LINV; REAL_LT_IMP_NZ; REAL_MUL_LID];
      DISCH_THEN(X_CHOOSE_THEN `y:real^2` STRIP_ASSUME_TAC) THEN ASM_REWRITE_TAC[] THEN
      ASM_SIMP_TAC[REAL_MUL_ASSOC; REAL_MUL_LINV; REAL_LT_IMP_NZ; REAL_MUL_LID];
      DISCH_TAC THEN EXISTS_TAC `c % (x:real^2)` THEN ASM_REWRITE_TAC[]];
    MATCH_MP_TAC MOI_S5C_PL_LINEAR THEN
    ASM_SIMP_TAC[LOCALLY_POLYHEDRAL_PL_POLYHEDRON; MOI_S5C_SQ_RF_POLYHEDRON] THEN
    REWRITE_TAC[linear; VECTOR_MUL_ASSOC; VECTOR_ADD_LDISTRIB] THEN
    REWRITE_TAC[REAL_MUL_SYM]]);;

let MOI_S5C_IMAGE_EQ = prove
 (`!(f:A->B) g s. (!x. x IN s ==> f x = g x) ==> IMAGE f s = IMAGE g s`,
  SET_TAC[]);;

let MOI_S5C_ANN_INNER = prove
 (`!(a:real^N->bool) j0 j1 (p:real^2->real^N) p'.
     pl_annulus_with_ends a j0 j1 /\
     pl_homeomorphism (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]),j0) (p,p')
     ==> ?f g. pl_homeomorphism
                 (interval[--vector[&2;&2],vector[&2;&2]] DIFF
                  interval(--vector[&1;&1],vector[&1;&1]),a) (f,g) /\
               (!x. x IN relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])
                    ==> f x = p x) /\
               j0 = IMAGE f (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) /\
               j1 = IMAGE f (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_annulus_with_ends] THEN
  DISCH_THEN(CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
  DISCH_THEN(X_CHOOSE_THEN `f0:real^2->real^N`
    (X_CHOOSE_THEN `g0:real^N->real^2`
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN SUBST_ALL_TAC)))) THEN
  ABBREV_TAC `R1 = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]):real^2->bool` THEN
  ABBREV_TAC `R2 = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]):real^2->bool` THEN
  SUBGOAL_THEN `(R1:real^2->bool) SUBSET
                interval[--vector[&2;&2],vector[&2;&2]] DIFF
                interval(--vector[&1;&1],vector[&1;&1])` ASSUME_TAC THENL
   [EXPAND_TAC "R1" THEN REWRITE_TAC[SUBSET; MOI_S5C_IN_RF1; MOI_S5C_IN_SQANN] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `pl_homeomorphism (IMAGE (f0:real^2->real^N) R1,R1:real^2->bool) (g0,f0)` ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC MOI_S27_PLH_RESTRICT THEN
    MAP_EVERY EXISTS_TAC [`interval[--vector[&2;&2],vector[&2;&2]] DIFF
                  interval(--vector[&1;&1],vector[&1;&1]):real^2->bool`; `a:real^N->bool`] THEN
    ASM_REWRITE_TAC[] THEN EXPAND_TAC "R1" THEN
    SIMP_TAC[LOCALLY_POLYHEDRAL_PL_POLYHEDRON; MOI_S5C_SQ_RF_POLYHEDRON; REAL_LT_01] THEN
    REWRITE_TAC[SUBSET; MOI_S5C_IN_RF1; MOI_S5C_IN_SQANN] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `pl_homeomorphism (R2:real^2->bool,R1) ((\x. inv(&2) % x),(\x. inv(inv(&2)) % x)) /\
                pl_homeomorphism (R1:real^2->bool,R2) ((\x. &2 % x),(\x. inv(&2) % x))`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["R1"; "R2"] THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`&2`; `inv(&2)`] MOI_S5C_SQ_RF_SCALE);
      MP_TAC(SPECL [`&1`; `&2`] MOI_S5C_SQ_RF_SCALE)] THEN
    CONV_TAC REAL_RAT_REDUCE_CONV THEN REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `h = (\x. &2 % x) o (g0:real^N->real^2) o (p:real^2->real^N) o (\x. inv(&2) % x)` THEN
  ABBREV_TAC `h' = (((\x. inv(inv(&2)) % x) o (p':real^N->real^2)) o (f0:real^2->real^N)) o (\x. inv(&2) % x)` THEN
  SUBGOAL_THEN `pl_homeomorphism (R2:real^2->bool,R2) (h,h')` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["h"; "h'"] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `R1:real^2->bool` THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `IMAGE (f0:real^2->real^N) R1` THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `R1:real^2->bool` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`h:real^2->real^2`; `h':real^2->real^2`] MOI_S5C_RADEXT) THEN
  ASM_REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  MAP_EVERY X_GEN_TAC [`H:real^2->real^2`; `H':real^2->real^2`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x:real^2. x IN R1 ==> (H:real^2->real^2) x = g0((p:real^2->real^N) x)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN ASM_SIMP_TAC[] THEN EXPAND_TAC "h" THEN
    REWRITE_TAC[o_THM; VECTOR_MUL_ASSOC] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
    REWRITE_TAC[VECTOR_MUL_LID]; ALL_TAC] THEN
  PRINT_GOAL_TAC THEN
  MAP_EVERY EXISTS_TAC [`(f0:real^2->real^N) o (H:real^2->real^2)`;
                        `(H':real^2->real^2) o (g0:real^N->real^2)`] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[homeomorphism] o CONJUNCT1 o
    REWRITE_RULE[pl_homeomorphism] o
    check (fun th -> can (term_match [] `pl_homeomorphism (R1:real^2->bool,IMAGE (f0:real^2->real^N) R1) (p,p')`) (concl th))) THEN
  SUBGOAL_THEN `!x. x IN R1 ==> ((f0:real^2->real^N) o (H:real^2->real^2)) x = p x`
  ASSUME_TAC THENL
   [X_GEN_TAC `x:real^2` THEN DISCH_TAC THEN REWRITE_TAC[o_THM] THEN
    SUBGOAL_THEN `(H:real^2->real^2) x = g0((p:real^2->real^N) x)` SUBST1_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(p:real^2->real^N) x IN IMAGE f0 (R1:real^2->bool)` ASSUME_TAC THENL
     [UNDISCH_TAC `IMAGE (p:real^2->real^N) R1 = IMAGE f0 R1` THEN
      UNDISCH_TAC `(x:real^2) IN R1` THEN SET_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `IMAGE (f0:real^2->real^N)
                    (interval[--vector[&2;&2],vector[&2;&2]] DIFF
                     interval(--vector[&1;&1],vector[&1;&1])) = a /\
                  (!y. y IN a ==> f0((g0:real^N->real^2) y) = y)` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `pl_homeomorphism
        (interval[--vector[&2;&2],vector[&2;&2]] DIFF
         interval(--vector[&1;&1],vector[&1;&1]),a) (f0:real^2->real^N,g0)` THEN
      SIMP_TAC[pl_homeomorphism; homeomorphism]; ALL_TAC] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    UNDISCH_TAC `(p:real^2->real^N) x IN IMAGE f0 (R1:real^2->bool)` THEN
    UNDISCH_TAC `(R1:real^2->bool) SUBSET
                  interval[--vector[&2;&2],vector[&2;&2]] DIFF
                  interval(--vector[&1;&1],vector[&1;&1])` THEN
    UNDISCH_TAC `IMAGE (f0:real^2->real^N)
                    (interval[--vector[&2;&2],vector[&2;&2]] DIFF
                     interval(--vector[&1;&1],vector[&1;&1])) = a` THEN
    SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
    EXISTS_TAC `interval[--vector[&2;&2],vector[&2;&2]] DIFF
                interval(--vector[&1;&1],vector[&1;&1]):real^2->bool` THEN
    ASM_REWRITE_TAC[];
    TRANS_TAC EQ_TRANS `IMAGE (p:real^2->real^N) R1` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      MATCH_MP_TAC MOI_S5C_IMAGE_EQ THEN
      ASM_MESON_TAC[]];
    REWRITE_TAC[IMAGE_o] THEN AP_TERM_TAC THEN
    TRANS_TAC EQ_TRANS `IMAGE (h:real^2->real^2) R2` THEN CONJ_TAC THENL
     [UNDISCH_TAC `pl_homeomorphism (R2:real^2->bool,R2) (h,h')` THEN
      SIMP_TAC[pl_homeomorphism; homeomorphism];
      MATCH_MP_TAC MOI_S5C_IMAGE_EQ THEN
      ASM_MESON_TAC[]]]);;

let MOI_S5C_ANN_OUTER = prove
 (`!(a:real^N->bool) j0 j1 (p:real^2->real^N) p'.
     pl_annulus_with_ends a j0 j1 /\
     pl_homeomorphism (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]),j1) (p,p')
     ==> ?f g. pl_homeomorphism
                 (interval[--vector[&2;&2],vector[&2;&2]] DIFF
                  interval(--vector[&1;&1],vector[&1;&1]),a) (f,g) /\
               (!x. x IN relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])
                    ==> f x = p x) /\
               j0 = IMAGE f (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) /\
               j1 = IMAGE f (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_annulus_with_ends] THEN
  DISCH_THEN(CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
  DISCH_THEN(X_CHOOSE_THEN `f0:real^2->real^N`
    (X_CHOOSE_THEN `g0:real^N->real^2`
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN SUBST_ALL_TAC)))) THEN
  ABBREV_TAC `R1 = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]):real^2->bool` THEN
  ABBREV_TAC `R2 = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]):real^2->bool` THEN
  SUBGOAL_THEN `(R2:real^2->bool) SUBSET
                interval[--vector[&2;&2],vector[&2;&2]] DIFF
                interval(--vector[&1;&1],vector[&1;&1])` ASSUME_TAC THENL
   [EXPAND_TAC "R2" THEN REWRITE_TAC[SUBSET; MOI_S5C_IN_RF2; MOI_S5C_IN_SQANN] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `pl_homeomorphism (IMAGE (f0:real^2->real^N) R2,R2:real^2->bool) (g0,f0)` ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN
    MATCH_MP_TAC MOI_S27_PLH_RESTRICT THEN
    MAP_EVERY EXISTS_TAC [`interval[--vector[&2;&2],vector[&2;&2]] DIFF
                  interval(--vector[&1;&1],vector[&1;&1]):real^2->bool`; `a:real^N->bool`] THEN
    ASM_REWRITE_TAC[] THEN EXPAND_TAC "R2" THEN
    SIMP_TAC[LOCALLY_POLYHEDRAL_PL_POLYHEDRON; MOI_S5C_SQ_RF_POLYHEDRON;
             REAL_ARITH `&0 < &2`];
    ALL_TAC] THEN
  SUBGOAL_THEN `pl_homeomorphism (R2:real^2->bool,R1) ((\x. inv(&2) % x),(\x. inv(inv(&2)) % x)) /\
                pl_homeomorphism (R1:real^2->bool,R2) ((\x. &2 % x),(\x. inv(&2) % x))`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["R1"; "R2"] THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`&2`; `inv(&2)`] MOI_S5C_SQ_RF_SCALE);
      MP_TAC(SPECL [`&1`; `&2`] MOI_S5C_SQ_RF_SCALE)] THEN
    CONV_TAC REAL_RAT_REDUCE_CONV THEN REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `h = (g0:real^N->real^2) o (p:real^2->real^N)` THEN
  ABBREV_TAC `h' = (p':real^N->real^2) o (f0:real^2->real^N)` THEN
  SUBGOAL_THEN `pl_homeomorphism (R2:real^2->bool,R2) (h,h')` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["h"; "h'"] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `IMAGE (f0:real^2->real^N) R2` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`h:real^2->real^2`; `h':real^2->real^2`] MOI_S5C_RADEXT) THEN
  ASM_REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  MAP_EVERY X_GEN_TAC [`H:real^2->real^2`; `H':real^2->real^2`] THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC [`(f0:real^2->real^N) o (H:real^2->real^2)`;
                        `(H':real^2->real^2) o (g0:real^N->real^2)`] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[homeomorphism] o CONJUNCT1 o
    REWRITE_RULE[pl_homeomorphism] o
    check (fun th -> can (term_match [] `pl_homeomorphism (R2:real^2->bool,IMAGE (f0:real^2->real^N) R2) (p,p')`) (concl th))) THEN
  SUBGOAL_THEN `!x. x IN R2 ==> ((f0:real^2->real^N) o (H:real^2->real^2)) x = p x`
  ASSUME_TAC THENL
   [X_GEN_TAC `x:real^2` THEN DISCH_TAC THEN REWRITE_TAC[o_THM] THEN
    SUBGOAL_THEN `(H:real^2->real^2) x = g0((p:real^2->real^N) x)` SUBST1_TAC THENL
     [ASM_SIMP_TAC[] THEN EXPAND_TAC "h" THEN REWRITE_TAC[o_THM]; ALL_TAC] THEN
    SUBGOAL_THEN `(p:real^2->real^N) x IN IMAGE f0 (R2:real^2->bool)` ASSUME_TAC THENL
     [UNDISCH_TAC `IMAGE (p:real^2->real^N) R2 = IMAGE f0 R2` THEN
      UNDISCH_TAC `(x:real^2) IN R2` THEN SET_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `IMAGE (f0:real^2->real^N)
                    (interval[--vector[&2;&2],vector[&2;&2]] DIFF
                     interval(--vector[&1;&1],vector[&1;&1])) = a /\
                  (!y. y IN a ==> f0((g0:real^N->real^2) y) = y)` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `pl_homeomorphism
        (interval[--vector[&2;&2],vector[&2;&2]] DIFF
         interval(--vector[&1;&1],vector[&1;&1]),a) (f0:real^2->real^N,g0)` THEN
      SIMP_TAC[pl_homeomorphism; homeomorphism]; ALL_TAC] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    UNDISCH_TAC `(p:real^2->real^N) x IN IMAGE f0 (R2:real^2->bool)` THEN
    UNDISCH_TAC `(R2:real^2->bool) SUBSET
                  interval[--vector[&2;&2],vector[&2;&2]] DIFF
                  interval(--vector[&1;&1],vector[&1;&1])` THEN
    UNDISCH_TAC `IMAGE (f0:real^2->real^N)
                    (interval[--vector[&2;&2],vector[&2;&2]] DIFF
                     interval(--vector[&1;&1],vector[&1;&1])) = a` THEN
    SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
    EXISTS_TAC `interval[--vector[&2;&2],vector[&2;&2]] DIFF
                interval(--vector[&1;&1],vector[&1;&1]):real^2->bool` THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[IMAGE_o] THEN AP_TERM_TAC THEN
    TRANS_TAC EQ_TRANS
      `IMAGE (\x. inv(&2) % x) (IMAGE (h:real^2->real^2) (IMAGE (\x. &2 % x) R1))` THEN
    CONJ_TAC THENL
     [SUBGOAL_THEN `IMAGE (\x:real^2. &2 % x) R1 = R2 /\ IMAGE (h:real^2->real^2) R2 = R2 /\
                    IMAGE (\x:real^2. inv(&2) % x) R2 = R1`
        (fun th -> REWRITE_TAC[th]) THEN
      REPEAT CONJ_TAC THENL
       [UNDISCH_TAC `pl_homeomorphism (R1:real^2->bool,R2) ((\x. &2 % x),(\x. inv(&2) % x))`;
        UNDISCH_TAC `pl_homeomorphism (R2:real^2->bool,R2) (h,h')`;
        UNDISCH_TAC `pl_homeomorphism (R2:real^2->bool,R1) ((\x. inv(&2) % x),(\x. inv(inv(&2)) % x))`] THEN
      SIMP_TAC[pl_homeomorphism; homeomorphism];
      REWRITE_TAC[GSYM IMAGE_o] THEN CONV_TAC SYM_CONV THEN
      MATCH_MP_TAC MOI_S5C_IMAGE_EQ THEN ASM_SIMP_TAC[o_THM]];
    TRANS_TAC EQ_TRANS `IMAGE (p:real^2->real^N) R2` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      MATCH_MP_TAC MOI_S5C_IMAGE_EQ THEN ASM_MESON_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* 2. Planar PL annuli: cells and their boundary extensions, convex          *)
(* polygons as PL 2-cells, nested triangles, the planar annulus theorem.    *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_CELL_EXT = prove
 (`!n (d:real^N->bool) j (d':real^N->bool) j' h h'.
     pl_cell_with_boundary n d j /\ pl_cell_with_boundary n d' j' /\
     pl_homeomorphism (j,j') (h,h')
     ==> ?f g. pl_homeomorphism (d,d') (f,g) /\ (!x. x IN j ==> f x = h x)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_cell_with_boundary] THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (X_CHOOSE_THEN `k:real^N->bool` (X_CHOOSE_THEN `p:real^N->real^N`
     (X_CHOOSE_THEN `q:real^N->real^N` STRIP_ASSUME_TAC)))
   (CONJUNCTS_THEN2
   (X_CHOOSE_THEN `k':real^N->bool` (X_CHOOSE_THEN `p':real^N->real^N`
     (X_CHOOSE_THEN `q':real^N->real^N` STRIP_ASSUME_TAC))) ASSUME_TAC)) THEN
  REPEAT(FIRST_X_ASSUM(SUBST_ALL_TAC o check (is_var o lhs o concl))) THEN
  SUBGOAL_THEN `pl_homeomorphism (relative_frontier k,IMAGE (p:real^N->real^N) (relative_frontier k)) (p,q) /\
                pl_homeomorphism (relative_frontier k',IMAGE (p':real^N->real^N) (relative_frontier k')) (p',q')`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S27_PLH_RESTRICT THENL
     [MAP_EVERY EXISTS_TAC [`k:real^N->bool`; `d:real^N->bool`];
      MAP_EVERY EXISTS_TAC [`k':real^N->bool`; `d':real^N->bool`]] THEN
    (ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
      [ASM_MESON_TAC[RELATIVE_FRONTIER_SUBSET; SIMPLEX_IMP_CLOSED]; ALL_TAC] THEN
     MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
     MATCH_MP_TAC MOI_CMB_PL_POLYHEDRON_RELATIVE_FRONTIER THEN
     ASM_MESON_TAC[SIMPLEX_IMP_POLYTOPE]);
    ALL_TAC] THEN
  MP_TAC(ISPECL [`k:real^N->bool`; `k':real^N->bool`; `n:num`;
                 `((q':real^N->real^N) o (h:real^N->real^N)) o (p:real^N->real^N)`;
                 `(q:real^N->real^N) o (h':real^N->real^N) o (p':real^N->real^N)`]
    PL_HOMEOMORPHISM_CONE_EXTENSION) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
    EXISTS_TAC `IMAGE (p:real^N->real^N) (relative_frontier k)` THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
    EXISTS_TAC `IMAGE (p':real^N->real^N) (relative_frontier k')` THEN
    ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `TT:real^N->real^N` (X_CHOOSE_THEN `TT':real^N->real^N`
    STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`((p':real^N->real^N) o (TT:real^N->real^N)) o (q:real^N->real^N)`;
                        `(p:real^N->real^N) o (TT':real^N->real^N) o (q':real^N->real^N)`] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `k:real^N->bool` THEN
    CONJ_TAC THENL [ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN ASM_REWRITE_TAC[];
                    ALL_TAC] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `k':real^N->bool` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[FORALL_IN_IMAGE; o_THM] THEN X_GEN_TAC `y:real^N` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(q:real^N->real^N) ((p:real^N->real^N) y) = y` SUBST1_TAC THENL
   [UNDISCH_TAC `pl_homeomorphism (k:real^N->bool,d:real^N->bool) (p:real^N->real^N,q)` THEN
    REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN
    ASM_MESON_TAC[RELATIVE_FRONTIER_SUBSET; SIMPLEX_IMP_CLOSED; SUBSET]; ALL_TAC] THEN
  ASM_SIMP_TAC[o_THM] THEN
  SUBGOAL_THEN `(h:real^N->real^N) ((p:real^N->real^N) y) IN IMAGE (p':real^N->real^N) (relative_frontier k')`
  ASSUME_TAC THENL
   [UNDISCH_TAC `pl_homeomorphism (IMAGE (p:real^N->real^N) (relative_frontier k),
                                   IMAGE (p':real^N->real^N) (relative_frontier k')) (h:real^N->real^N,h')` THEN
    REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN
    UNDISCH_TAC `(y:real^N) IN relative_frontier k` THEN SET_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `pl_homeomorphism (relative_frontier k':real^N->bool,IMAGE (p':real^N->real^N) (relative_frontier k')) (p',q':real^N->real^N)` THEN
  REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN ASM_MESON_TAC[]);;

let MOI_S5C_CELL_EXT2 = prove
 (`!n (d:real^M->bool) j (d':real^N->bool) j' (h:real^M->real^N) h'.
     pl_cell_with_boundary n d j /\ pl_cell_with_boundary n d' j' /\
     pl_homeomorphism (j,j') (h,h')
     ==> ?f g. pl_homeomorphism (d,d') (f,g) /\ (!x. x IN j ==> f x = h x)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_cell_with_boundary] THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (X_CHOOSE_THEN `k:real^M->bool` (X_CHOOSE_THEN `p:real^M->real^M`
     (X_CHOOSE_THEN `q:real^M->real^M` STRIP_ASSUME_TAC)))
   (CONJUNCTS_THEN2
   (X_CHOOSE_THEN `k':real^N->bool` (X_CHOOSE_THEN `p':real^N->real^N`
     (X_CHOOSE_THEN `q':real^N->real^N` STRIP_ASSUME_TAC))) ASSUME_TAC)) THEN
  REPEAT(FIRST_X_ASSUM(SUBST_ALL_TAC o check (is_var o lhs o concl))) THEN
  SUBGOAL_THEN `pl_homeomorphism (relative_frontier k,IMAGE (p:real^M->real^M) (relative_frontier k)) (p,q) /\
                pl_homeomorphism (relative_frontier k',IMAGE (p':real^N->real^N) (relative_frontier k')) (p',q')`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S27_PLH_RESTRICT THENL
     [MAP_EVERY EXISTS_TAC [`k:real^M->bool`; `d:real^M->bool`];
      MAP_EVERY EXISTS_TAC [`k':real^N->bool`; `d':real^N->bool`]] THEN
    (ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
      [ASM_MESON_TAC[RELATIVE_FRONTIER_SUBSET; SIMPLEX_IMP_CLOSED]; ALL_TAC] THEN
     MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
     MATCH_MP_TAC MOI_CMB_PL_POLYHEDRON_RELATIVE_FRONTIER THEN
     ASM_MESON_TAC[SIMPLEX_IMP_POLYTOPE]);
    ALL_TAC] THEN
  MP_TAC(ISPECL [`k:real^M->bool`; `k':real^N->bool`; `n:num`;
                 `((q':real^N->real^N) o (h:real^M->real^N)) o (p:real^M->real^M)`;
                 `(q:real^M->real^M) o (h':real^N->real^M) o (p':real^N->real^N)`]
    PL_HOMEOMORPHISM_CONE_EXTENSION) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
    EXISTS_TAC `IMAGE (p:real^M->real^M) (relative_frontier k)` THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
    EXISTS_TAC `IMAGE (p':real^N->real^N) (relative_frontier k')` THEN
    ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `TT:real^M->real^N` (X_CHOOSE_THEN `TT':real^N->real^M`
    STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`((p':real^N->real^N) o (TT:real^M->real^N)) o (q:real^M->real^M)`;
                        `(p:real^M->real^M) o (TT':real^N->real^M) o (q':real^N->real^N)`] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `k:real^M->bool` THEN
    CONJ_TAC THENL [ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN ASM_REWRITE_TAC[];
                    ALL_TAC] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `k':real^N->bool` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[FORALL_IN_IMAGE; o_THM] THEN X_GEN_TAC `y:real^M` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(q:real^M->real^M) ((p:real^M->real^M) y) = y` SUBST1_TAC THENL
   [UNDISCH_TAC `pl_homeomorphism (k:real^M->bool,d:real^M->bool) (p:real^M->real^M,q)` THEN
    REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN
    ASM_MESON_TAC[RELATIVE_FRONTIER_SUBSET; SIMPLEX_IMP_CLOSED; SUBSET]; ALL_TAC] THEN
  ASM_SIMP_TAC[o_THM] THEN
  SUBGOAL_THEN `(h:real^M->real^N) ((p:real^M->real^M) y) IN IMAGE (p':real^N->real^N) (relative_frontier k')`
  ASSUME_TAC THENL
   [UNDISCH_TAC `pl_homeomorphism (IMAGE (p:real^M->real^M) (relative_frontier k),
                                   IMAGE (p':real^N->real^N) (relative_frontier k')) (h:real^M->real^N,h')` THEN
    REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN
    UNDISCH_TAC `(y:real^M) IN relative_frontier k` THEN SET_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `pl_homeomorphism (relative_frontier k':real^N->bool,IMAGE (p':real^N->real^N) (relative_frontier k')) (p',q':real^N->real^N)` THEN
  REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN ASM_MESON_TAC[]);;

let MOI_S5C_STAR_RF0 = prove
 (`!P:real^N->bool.
     polytope P /\ vec 0 IN interior P
     ==> pl_sphere (dimindex(:N) - 1) (relative_frontier P)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC MOI_CMB_STAR_SHAPED_PL_SPHERE_0 THEN
  SUBGOAL_THEN `(vec 0:real^N) IN relative_interior P` ASSUME_TAC THENL
   [ASM_MESON_TAC[INTERIOR_SUBSET_RELATIVE_INTERIOR; SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `convex(P:real^N->bool) /\ bounded P` STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[POLYTOPE_IMP_CONVEX; POLYTOPE_IMP_BOUNDED]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MOI_CMB_PL_POLYHEDRON_RELATIVE_FRONTIER THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[relative_frontier; IN_DIFF] THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `u:real^N` THEN DISCH_TAC THEN REWRITE_TAC[EXISTS_UNIQUE_THM] THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL [`P:real^N->bool`; `vec 0:real^N`; `u:real^N`]
        RAY_TO_RELATIVE_FRONTIER) THEN
      ASM_REWRITE_TAC[VECTOR_ADD_LID] THEN ANTS_TAC THENL
       [MATCH_MP_TAC(SET_RULE `s = UNIV ==> (x:real^N) IN s`) THEN
        MATCH_MP_TAC AFFINE_HULL_NONEMPTY_INTERIOR THEN ASM SET_TAC[];
        MESON_TAC[]];
      MAP_EVERY X_GEN_TAC [`r1:real`; `r2:real`] THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`P:real^N->bool`; `r1 % u:real^N`; `r2 % u:real^N`; `r1 / r2`]
        MOI_CMB_RAY_FRONTIER_UNIQUE) THEN
      ASM_SIMP_TAC[REAL_LT_DIV; VECTOR_MUL_ASSOC; REAL_DIV_RMUL; REAL_LT_IMP_NZ] THEN
      ASM_SIMP_TAC[REAL_EQ_LDIV_EQ; REAL_MUL_LID]]]);;

let MOI_S5C_POLYTOPE_CELL = prove
 (`!P:real^2->bool.
     polytope P /\ ~(interior P = {})
     ==> pl_cell_with_boundary 2 P (relative_frontier P)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `m:real^2` o GEN_REWRITE_RULE I [GSYM MEMBER_NOT_EMPTY]) THEN
  SUBGOAL_THEN `pl_sphere 1 (relative_frontier P:real^2->bool)` MP_TAC THENL
   [MP_TAC(ISPEC `IMAGE (\x:real^2. --m + x) P` MOI_S5C_STAR_RF0) THEN
    REWRITE_TAC[DIMINDEX_2; ARITH_RULE `2 - 1 = 1`] THEN ANTS_TAC THENL
     [ASM_SIMP_TAC[POLYTOPE_TRANSLATION_EQ; INTERIOR_TRANSLATION] THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `m:real^2` THEN
      ASM_REWRITE_TAC[] THEN VECTOR_ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[RELATIVE_FRONTIER_TRANSLATION] THEN DISCH_TAC THEN
    MATCH_MP_TAC PL_SPHERE_PL_HOMEOMORPHIC THEN
    MAP_EVERY EXISTS_TAC [`IMAGE (\x:real^2. --m + x) (relative_frontier P)`;
                          `(\x:real^2. m + x)`; `(\x:real^2. --m + x)`] THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOI_CMB_TRANSLATION_PL_HOMEOMORPHISM THEN
    MATCH_MP_TAC MOI_CMB_PL_POLYHEDRON_RELATIVE_FRONTIER THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[pl_sphere; ARITH_RULE `1 + 1 = 2`] THEN
  DISCH_THEN(X_CHOOSE_THEN `k:real^2->bool` (X_CHOOSE_THEN `f:real^2->real^2`
    (X_CHOOSE_THEN `g:real^2->real^2` STRIP_ASSUME_TAC))) THEN
  MP_TAC(ISPECL [`k:real^2->bool`; `&2:int`] MOI_CON_SIMPLEX_RF_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN INT_ARITH_TAC; STRIP_TAC] THEN
  MP_TAC(ISPECL [`P:real^2->bool`; `m:real^2`] MOI_S5C_CONVEX_CONE_RF) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[POLYTOPE_IMP_CONVEX; POLYTOPE_IMP_COMPACT] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[INTERIOR_SUBSET_RELATIVE_INTERIOR; SUBSET];
      DISCH_THEN SUBST_ALL_TAC THEN
      UNDISCH_TAC `(m:real^2) IN interior {m}` THEN
      REWRITE_TAC[INTERIOR_SING; NOT_IN_EMPTY]];
    STRIP_TAC] THEN
  MP_TAC(ISPECL [`relative_frontier k:real^2->bool`; `relative_frontier P:real^2->bool`;
                 `simplex_barycentre (k:real^2->bool)`; `m:real^2`;
                 `f:real^2->real^2`; `g:real^2->real^2`] MOI_CON_CONE_MAP) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  REWRITE_TAC[pl_cell_with_boundary] THEN
  MAP_EVERY EXISTS_TAC [`k:real^2->bool`;
    `moi_con_conemap (relative_frontier k) (simplex_barycentre k) (m:real^2) (f:real^2->real^2)`;
    `moi_con_conemap (relative_frontier P) (m:real^2) (simplex_barycentre k) (g:real^2->real^2)`] THEN
  ASM_REWRITE_TAC[] THEN
  UNDISCH_TAC `pl_homeomorphism (relative_frontier k:real^2->bool,relative_frontier P:real^2->bool) (f:real^2->real^2,g)` THEN
  REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN STRIP_TAC THEN
  TRANS_TAC EQ_TRANS `IMAGE (f:real^2->real^2) (relative_frontier k)` THEN
  CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC MOI_S5C_IMAGE_EQ THEN ASM_SIMP_TAC[]);;

(* The exit parameter of the ray from vec 0 through v from a convex body.   *)

let moi_s5c_lam = new_definition
 `moi_s5c_lam (t:real^N->bool) (v:real^N) =
    @r. &0 < r /\ r % v IN relative_frontier t`;;

let MOI_S5C_LAM = prove
 (`!(t:real^N->bool) v.
     convex t /\ compact t /\ vec 0 IN interior t /\ ~(v = vec 0)
     ==> &0 < moi_s5c_lam t v /\ moi_s5c_lam t v % v IN relative_frontier t /\
         (!r. &0 <= r ==> (r % v IN t <=> r <= moi_s5c_lam t v)) /\
         (!r. &0 <= r /\ r < moi_s5c_lam t v ==> r % v IN interior t)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(vec 0:real^N) IN relative_interior t /\ relative_interior t = interior t`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(TAUT `b /\ (b ==> a) ==> a /\ b`) THEN CONJ_TAC THENL
     [MATCH_MP_TAC RELATIVE_INTERIOR_NONEMPTY_INTERIOR THEN ASM SET_TAC[];
      DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`t:real^N->bool`; `vec 0:real^N`; `v:real^N`]
    RAY_TO_RELATIVE_FRONTIER) THEN
  ASM_SIMP_TAC[COMPACT_IMP_BOUNDED; VECTOR_ADD_LID] THEN ANTS_TAC THENL
   [MATCH_MP_TAC(SET_RULE `s = UNIV ==> (x:real^N) IN s`) THEN
    MATCH_MP_TAC AFFINE_HULL_NONEMPTY_INTERIOR THEN ASM SET_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `d:real` STRIP_ASSUME_TAC)] THEN
  SUBGOAL_THEN `moi_s5c_lam (t:real^N->bool) v = d` SUBST1_TAC THENL
   [REWRITE_TAC[moi_s5c_lam] THEN MATCH_MP_TAC SELECT_UNIQUE THEN
    X_GEN_TAC `r:real` THEN BETA_TAC THEN EQ_TAC THENL
     [STRIP_TAC THEN
      MP_TAC(ISPECL [`t:real^N->bool`; `r % v:real^N`; `d % v:real^N`; `r / d`]
        MOI_CMB_RAY_FRONTIER_UNIQUE) THEN
      ASM_SIMP_TAC[REAL_LT_DIV; VECTOR_MUL_ASSOC; REAL_DIV_RMUL; REAL_LT_IMP_NZ] THEN
      ASM_SIMP_TAC[REAL_EQ_LDIV_EQ; REAL_MUL_LID];
      DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `closure t = (t:real^N->bool)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[CLOSURE_CLOSED; COMPACT_IMP_CLOSED]; ALL_TAC] THEN
  (X_GEN_TAC `r:real` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN REWRITE_TAC[GSYM REAL_NOT_LT] THEN DISCH_TAC THEN
      MP_TAC(ISPECL [`t:real^N->bool`; `r % v:real^N`; `d / r`] MOI_CMB_RAY_INTERIOR) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `&0 < r` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      ASM_SIMP_TAC[REAL_LT_DIV; REAL_LT_LDIV_EQ; REAL_MUL_LID; VECTOR_MUL_ASSOC;
                   REAL_DIV_RMUL; REAL_LT_IMP_NZ] THEN
      UNDISCH_TAC `d % (v:real^N) IN relative_frontier t` THEN
      ASM_REWRITE_TAC[relative_frontier; IN_DIFF] THEN MESON_TAC[];
      DISCH_TAC THEN ASM_CASES_TAC `r:real = d` THENL
       [FIRST_X_ASSUM SUBST1_TAC THEN
        MP_TAC(ISPEC `t:real^N->bool` RELATIVE_FRONTIER_SUBSET) THEN
        ASM_SIMP_TAC[COMPACT_IMP_CLOSED] THEN
        UNDISCH_TAC `d % (v:real^N) IN relative_frontier t` THEN SET_TAC[];
        FIRST_X_ASSUM(MP_TAC o SPEC `r:real`) THEN
        ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
        MP_TAC(ISPEC `t:real^N->bool` INTERIOR_SUBSET) THEN SET_TAC[]]]));;

(* ------------------------------------------------------------------------- *)
(* 3. The standard triangle with centroid vec 0, its three cones and the     *)
(* rotation L permuting the vertices.                                        *)
(* ------------------------------------------------------------------------- *)

let moi_s5c_tri = new_definition
 `moi_s5c_tri = {x:real^2 | -- &1 <= x$1 /\ -- &1 <= x$2 /\ x$1 + x$2 <= &1}`;;

let moi_s5c_tri2 = new_definition
 `moi_s5c_tri2 = {x:real^2 | -- &2 <= x$1 /\ -- &2 <= x$2 /\ x$1 + x$2 <= &2}`;;

let moi_s5c_k12 = new_definition
 `moi_s5c_k12 = {x:real^2 | x$2 <= x$1 /\ x$1 + &2 * x$2 <= &0 /\ x$2 <= -- &1}`;;

let moi_s5c_k23 = new_definition
 `moi_s5c_k23 = {x:real^2 | &0 <= &2 * x$1 + x$2 /\ &0 <= x$1 + &2 * x$2 /\
                            &1 <= x$1 + x$2}`;;

let moi_s5c_k31 = new_definition
 `moi_s5c_k31 = {x:real^2 | x$1 <= x$2 /\ &2 * x$1 + x$2 <= &0 /\ x$1 <= -- &1}`;;

let moi_s5c_rot = new_definition
 `moi_s5c_rot (x:real^2) = vector[--(x$1) - x$2; x$1]:real^2`;;

let moi_s5c_irot = new_definition
 `moi_s5c_irot (x:real^2) = vector[x$2; --(x$1) - x$2]:real^2`;;

let MOI_S5C_INTERIOR_3HALF = prove
 (`!a1 a2 a3 (b1:real) b2 b3.
     ~(a1 = vec 0) /\ ~(a2 = vec 0) /\ ~(a3 = vec 0)
     ==> interior {x:real^N | a1 dot x <= b1 /\ a2 dot x <= b2 /\ a3 dot x <= b3} =
         {x | a1 dot x < b1 /\ a2 dot x < b2 /\ a3 dot x < b3}`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `{x:real^N | a1 dot x <= b1 /\ a2 dot x <= b2 /\ a3 dot x <= b3} =
    {x | a1 dot x <= b1} INTER {x | a2 dot x <= b2} INTER {x | a3 dot x <= b3}`
  SUBST1_TAC THENL [SET_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[INTERIOR_INTER; INTERIOR_HALFSPACE_LE] THEN SET_TAC[]);;

let MOI_S5C_TRI_INTERIOR = prove
 (`interior moi_s5c_tri = {x:real^2 | -- &1 < x$1 /\ -- &1 < x$2 /\ x$1 + x$2 < &1}`,
  MP_TAC(ISPECL [`vector[-- &1; &0]:real^2`; `vector[&0; -- &1]:real^2`;
                 `vector[&1; &1]:real^2`; `&1`; `&1`; `&1`] MOI_S5C_INTERIOR_3HALF) THEN
  REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2; VEC_COMPONENT; DOT_2] THEN
  ANTS_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[] `s = s' /\ t = t' ==> interior s = t ==> interior s' = (t':real^2->bool)`) THEN
  REWRITE_TAC[moi_s5c_tri; EXTENSION; IN_ELIM_THM] THEN REAL_ARITH_TAC);;

let MOI_S5C_TRI2_INTERIOR = prove
 (`interior moi_s5c_tri2 = {x:real^2 | -- &2 < x$1 /\ -- &2 < x$2 /\ x$1 + x$2 < &2}`,
  MP_TAC(ISPECL [`vector[-- &1; &0]:real^2`; `vector[&0; -- &1]:real^2`;
                 `vector[&1; &1]:real^2`; `&2`; `&2`; `&2`] MOI_S5C_INTERIOR_3HALF) THEN
  REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2; VEC_COMPONENT; DOT_2] THEN
  ANTS_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[] `s = s' /\ t = t' ==> interior s = t ==> interior s' = (t':real^2->bool)`) THEN
  REWRITE_TAC[moi_s5c_tri2; EXTENSION; IN_ELIM_THM] THEN REAL_ARITH_TAC);;

let MOI_S5C_TRI_HULL = prove
 (`moi_s5c_tri = convex hull {vector[-- &1;-- &1]:real^2, vector[&2;-- &1], vector[-- &1;&2]} /\
   moi_s5c_tri2 = convex hull {vector[-- &2;-- &2]:real^2, vector[&4;-- &2], vector[-- &2;&4]}`,
  REWRITE_TAC[CONVEX_HULL_3; moi_s5c_tri; moi_s5c_tri2; EXTENSION; IN_ELIM_THM] THEN
  CONJ_TAC THEN X_GEN_TAC `x:real^2` THEN
  REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_ADD_COMPONENT;
              VECTOR_MUL_COMPONENT; VECTOR_2] THEN
  EQ_TAC THENL
   [STRIP_TAC THEN MAP_EVERY EXISTS_TAC
     [`(&1 - (x:real^2)$1 - x$2) / &3`; `((x:real^2)$1 + &1) / &3`; `((x:real^2)$2 + &1) / &3`] THEN
    ASM_REAL_ARITH_TAC;
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    STRIP_TAC THEN MAP_EVERY EXISTS_TAC
     [`(&2 - (x:real^2)$1 - x$2) / &6`; `((x:real^2)$1 + &2) / &6`; `((x:real^2)$2 + &2) / &6`] THEN
    ASM_REAL_ARITH_TAC;
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC]);;

let MOI_S5C_TRI_FACTS = prove
 (`&2 simplex moi_s5c_tri /\ &2 simplex moi_s5c_tri2 /\
   polytope moi_s5c_tri /\ polytope moi_s5c_tri2 /\
   convex moi_s5c_tri /\ compact moi_s5c_tri /\
   convex moi_s5c_tri2 /\ compact moi_s5c_tri2 /\
   (vec 0:real^2) IN interior moi_s5c_tri /\
   moi_s5c_tri SUBSET interior moi_s5c_tri2`,
  SUBGOAL_THEN `&2 simplex moi_s5c_tri /\ &2 simplex moi_s5c_tri2` STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[MOI_S5C_TRI_HULL; MOI_PL2_SIMPLEX_2] THEN CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`vector[-- &1;-- &1]:real^2`; `vector[&2;-- &1]:real^2`;
                            `vector[-- &1;&2]:real^2`];
      MAP_EVERY EXISTS_TAC [`vector[-- &2;-- &2]:real^2`; `vector[&4;-- &2]:real^2`;
                            `vector[-- &2;&4]:real^2`]] THEN
    REWRITE_TAC[COLLINEAR_3_2D; VECTOR_2] THEN CONV_TAC REAL_RAT_REDUCE_CONV;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT(CONJ_TAC THENL
   [ASM_MESON_TAC[SIMPLEX_IMP_POLYTOPE; SIMPLEX_IMP_CONVEX; SIMPLEX_IMP_COMPACT];
    ALL_TAC]) THEN
  REWRITE_TAC[MOI_S5C_TRI_INTERIOR; MOI_S5C_TRI2_INTERIOR] THEN
  REWRITE_TAC[moi_s5c_tri; SUBSET; IN_ELIM_THM; VEC_COMPONENT] THEN REAL_ARITH_TAC);;

let MOI_S5C_K_COVER = prove
