              IN_ELIM_THM] THEN REAL_ARITH_TAC);;

let MOI_S5C_K_INTERS = prove
 (`(!x:real^2. x IN moi_s5c_k12 /\ x IN moi_s5c_k23 <=>
              ?r. &1 <= r /\ x = r % vector[&2;-- &1]) /\
   (!x:real^2. x IN moi_s5c_k23 /\ x IN moi_s5c_k31 <=>
              ?r. &1 <= r /\ x = r % vector[-- &1;&2]) /\
   (!x:real^2. x IN moi_s5c_k31 /\ x IN moi_s5c_k12 <=>
              ?r. &1 <= r /\ x = r % vector[-- &1;-- &1])`,
  REWRITE_TAC[moi_s5c_k12; moi_s5c_k23; moi_s5c_k31; IN_ELIM_THM;
              CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_MUL_COMPONENT; VECTOR_2] THEN
  REPEAT CONJ_TAC THEN X_GEN_TAC `x:real^2` THEN EQ_TAC THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN TRY ASM_REAL_ARITH_TAC THENL
   [EXISTS_TAC `--((x:real^2)$2)` THEN ASM_REAL_ARITH_TAC;
    EXISTS_TAC `(x:real^2)$2 / &2` THEN ASM_REAL_ARITH_TAC;
    EXISTS_TAC `--((x:real^2)$1)` THEN ASM_REAL_ARITH_TAC]);;

let MOI_S5C_SEG_RAY = prove
 (`!(v:real^N) lam.
     &1 <= lam
     ==> !x. x IN segment[lam % v,v] <=> ?r. &1 <= r /\ r <= lam /\ x = r % v`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[IN_SEGMENT] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `lam - u * (lam - &1)` THEN ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(REAL_ARITH `u * (l - &1) <= &1 * (l - &1) ==> &1 <= l - u * (l - &1)`) THEN
      MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC(REAL_ARITH `&0 <= u * (l - &1) ==> l - u * (l - &1) <= l`) THEN
      MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
      VECTOR_ARITH_TAC];
    DISCH_THEN(X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC) THEN
    ASM_CASES_TAC `lam = &1` THENL
     [EXISTS_TAC `&0` THEN
      SUBGOAL_THEN `r = &1` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN TRY REAL_ARITH_TAC THEN
      VECTOR_ARITH_TAC;
      EXISTS_TAC `(lam - r) / (lam - &1)` THEN
      SUBGOAL_THEN `&0 < lam - &1` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      CONJ_TAC THENL [MATCH_MP_TAC REAL_LE_DIV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      CONJ_TAC THENL [ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      ASM_REWRITE_TAC[VECTOR_ARITH `(&1 - u) % (l % v) + u % v:real^N = (l - u * (l - &1)) % v`] THEN
      AP_THM_TAC THEN AP_TERM_TAC THEN
      ASM_SIMP_TAC[REAL_DIV_RMUL; REAL_LT_IMP_NZ] THEN REAL_ARITH_TAC]]);;

let MOI_S5C_SEG_V1V2 = prove
 (`!x:real^2. x IN segment[vector[-- &1;-- &1],vector[&2;-- &1]] <=>
