   [STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    STRIP_TAC THEN EXISTS_TAC `((x:real^2)$1 + &1) / &3` THEN ASM_REAL_ARITH_TAC]);;

let MOI_S5C_K12_INTERIOR = prove
 (`interior moi_s5c_k12 = {x:real^2 | x$2 < x$1 /\ x$1 + &2 * x$2 < &0 /\ x$2 < -- &1}`,
  MP_TAC(ISPECL [`vector[-- &1; &1]:real^2`; `vector[&1; &2]:real^2`;
                 `vector[&0; &1]:real^2`; `&0`; `&0`; `-- &1`] MOI_S5C_INTERIOR_3HALF) THEN
  REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2; VEC_COMPONENT; DOT_2] THEN
  ANTS_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[] `s = s' /\ t = t' ==> interior s = t ==> interior s' = (t':real^2->bool)`) THEN
  REWRITE_TAC[moi_s5c_k12; EXTENSION; IN_ELIM_THM] THEN REAL_ARITH_TAC);;

let MOI_S5C_K12_POLYHEDRON = prove
 (`polyhedron moi_s5c_k12`,
  SUBGOAL_THEN
   `moi_s5c_k12 = {x:real^2 | vector[-- &1; &1] dot x <= &0} INTER
                  {x | vector[&1; &2] dot x <= &0} INTER
                  {x | vector[&0; &1] dot x <= -- &1}`
