    REWRITE_TAC[POLYHEDRON_HALFSPACE_LE]]);;

let MOI_S5C_LAM_GT1 = prove
 (`!(t:real^N->bool) v.
     convex t /\ compact t /\ vec 0 IN interior t /\ ~(v = vec 0) /\ v IN interior t
     ==> &1 < moi_s5c_lam t v`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`t:real^N->bool`; `v:real^N`] MOI_S5C_LAM) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  REWRITE_TAC[GSYM REAL_NOT_LE] THEN DISCH_TAC THEN
  ASM_CASES_TAC `moi_s5c_lam (t:real^N->bool) v = &1` THENL
   [UNDISCH_TAC `moi_s5c_lam (t:real^N->bool) v % v IN relative_frontier t` THEN
    ASM_REWRITE_TAC[VECTOR_MUL_LID; relative_frontier; IN_DIFF] THEN
    SUBGOAL_THEN `relative_interior t = interior (t:real^N->bool)` SUBST1_TAC THENL
     [MATCH_MP_TAC RELATIVE_INTERIOR_NONEMPTY_INTERIOR THEN ASM SET_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    SUBGOAL_THEN `(&1 % (v:real^N)) IN t <=> &1 <= moi_s5c_lam t v` MP_TAC THENL
     [ASM_MESON_TAC[REAL_POS]; ALL_TAC] THEN
    REWRITE_TAC[VECTOR_MUL_LID] THEN
    SUBGOAL_THEN `(v:real^N) IN t` (fun th -> REWRITE_TAC[th]) THENL
     [ASM_MESON_TAC[INTERIOR_SUBSET; SUBSET]; ASM_REAL_ARITH_TAC]]);;

let MOI_S5C_PIECE12_RF = prove
 (`!t:real^2->bool.
     &2 simplex t /\ moi_s5c_tri SUBSET interior t
     ==> polytope (t INTER moi_s5c_k12) /\ ~(interior (t INTER moi_s5c_k12) = {}) /\
         &1 < moi_s5c_lam t (vector[-- &1;-- &1]) /\
         &1 < moi_s5c_lam t (vector[&2;-- &1]) /\
         relative_frontier (t INTER moi_s5c_k12) =
         (relative_frontier t INTER moi_s5c_k12) UNION
         segment[vector[-- &1;-- &1],vector[&2;-- &1]] UNION
         segment[moi_s5c_lam t (vector[-- &1;-- &1]) % vector[-- &1;-- &1],
                 vector[-- &1;-- &1]] UNION
         segment[moi_s5c_lam t (vector[&2;-- &1]) % vector[&2;-- &1],
                 vector[&2;-- &1]]`,
  GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `convex (t:real^2->bool) /\ compact t /\ polytope t` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[SIMPLEX_IMP_CONVEX; SIMPLEX_IMP_COMPACT; SIMPLEX_IMP_POLYTOPE];
    ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^2. x IN moi_s5c_tri ==> x IN interior t` ASSUME_TAC THENL
   [ASM SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vec 0:real^2) IN interior t` ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN REWRITE_TAC[moi_s5c_tri; IN_ELIM_THM; VEC_COMPONENT] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `v1 = vector[-- &1;-- &1]:real^2` THEN
  ABBREV_TAC `v2 = vector[&2;-- &1]:real^2` THEN
  ABBREV_TAC `m = vector[&1 / &2;-- &1]:real^2` THEN
  SUBGOAL_THEN `~(v1:real^2 = vec 0) /\ ~(v2:real^2 = vec 0) /\ ~(m:real^2 = vec 0) /\
                v1 IN interior t /\ v2 IN interior t /\ m IN interior t`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["v1"; "v2"; "m"] THEN
    REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2; VEC_COMPONENT] THEN
    CONV_TAC REAL_RAT_REDUCE_CONV THEN REPEAT CONJ_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    REWRITE_TAC[moi_s5c_tri; IN_ELIM_THM; VECTOR_2] THEN CONV_TAC REAL_RAT_REDUCE_CONV;
    ALL_TAC] THEN
  MAP_EVERY (fun (v,nm) -> MP_TAC(ISPECL [`t:real^2->bool`; v] MOI_S5C_LAM) THEN
                      ASM_REWRITE_TAC[] THEN
                      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
                        (CONJUNCTS_THEN2 (LABEL_TAC ("in_"^nm)) (LABEL_TAC ("int_"^nm))))) THEN
                      MP_TAC(ISPECL [`t:real^2->bool`; v] MOI_S5C_LAM_GT1) THEN
                      ASM_REWRITE_TAC[] THEN DISCH_TAC)
    [`v1:real^2`,"v1"; `v2:real^2`,"v2"; `m:real^2`,"m"] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `~(interior (t:real^2->bool) = {})` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN EXISTS_TAC `vec 0:real^2` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `relative_frontier (t:real^2->bool) = t DIFF interior t` ASSUME_TAC THENL
   [ASM_SIMP_TAC[RELATIVE_FRONTIER_NONEMPTY_INTERIOR; frontier; CLOSURE_CLOSED;
                 COMPACT_IMP_CLOSED];
    ALL_TAC] THEN
  SUBGOAL_THEN `interior (t INTER moi_s5c_k12) =
                interior t INTER {x:real^2 | x$2 < x$1 /\ x$1 + &2 * x$2 < &0 /\ x$2 < -- &1}`
  ASSUME_TAC THENL
   [REWRITE_TAC[INTERIOR_INTER; MOI_S5C_K12_INTERIOR]; ALL_TAC] THEN
  SUBGOAL_THEN `~(interior (t INTER moi_s5c_k12:real^2->bool) = {})` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER; IN_ELIM_THM] THEN
    EXISTS_TAC `((&1 + moi_s5c_lam t (m:real^2)) / &2) % m` THEN CONJ_TAC THENL
     [USE_THEN "int_m" MATCH_MP_TAC THEN
      UNDISCH_TAC `&1 < moi_s5c_lam t (m:real^2)` THEN REAL_ARITH_TAC;
      SUBGOAL_THEN `(m:real^2)$1 = &1 / &2 /\ m$2 = -- &1` STRIP_ASSUME_TAC THENL
       [EXPAND_TAC "m" THEN REWRITE_TAC[VECTOR_2]; ALL_TAC] THEN
      ASM_REWRITE_TAC[VECTOR_MUL_COMPONENT] THEN
      UNDISCH_TAC `&1 < moi_s5c_lam t (m:real^2)` THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  ASM_SIMP_TAC[POLYTOPE_INTER_POLYHEDRON; MOI_S5C_K12_POLYHEDRON] THEN
  ASM_SIMP_TAC[RELATIVE_FRONTIER_NONEMPTY_INTERIOR; frontier] THEN
  SUBGOAL_THEN `closure (t INTER moi_s5c_k12:real^2->bool) = t INTER moi_s5c_k12`
  SUBST1_TAC THENL
   [MATCH_MP_TAC CLOSURE_CLOSED THEN MATCH_MP_TAC CLOSED_INTER THEN
    ASM_SIMP_TAC[COMPACT_IMP_CLOSED; POLYHEDRON_IMP_CLOSED; MOI_S5C_K12_POLYHEDRON];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(v1:real^2)$1 = -- &1 /\ v1$2 = -- &1 /\ (v2:real^2)$1 = &2 /\ v2$2 = -- &1`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["v1"; "v2"] THEN REWRITE_TAC[VECTOR_2]; ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^2. x IN segment[v1,v2] <=> x$2 = -- &1 /\ -- &1 <= x$1 /\ x$1 <= &2`
  (LABEL_TAC "s12") THENL
   [MAP_EVERY EXPAND_TAC ["v1"; "v2"] THEN REWRITE_TAC[MOI_S5C_SEG_V1V2]; ALL_TAC] THEN
  SUBGOAL_THEN `(!x:real^2. x IN segment[moi_s5c_lam t v1 % v1,v1] <=>
                     ?r. &1 <= r /\ r <= moi_s5c_lam t v1 /\ x = r % v1) /\
                (!x:real^2. x IN segment[moi_s5c_lam t v2 % v2,v2] <=>
                     ?r. &1 <= r /\ r <= moi_s5c_lam t v2 /\ x = r % v2)`
  (CONJUNCTS_THEN2 (LABEL_TAC "r1") (LABEL_TAC "r2")) THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_SEG_RAY THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_DIFF; IN_INTER; IN_UNION; IN_ELIM_THM] THEN
  X_GEN_TAC `x:real^2` THEN
  REMOVE_THEN "s12" (fun th -> REWRITE_TAC[th]) THEN
  REMOVE_THEN "r1" (fun th -> REWRITE_TAC[th]) THEN
  REMOVE_THEN "r2" (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[moi_s5c_k12; IN_ELIM_THM] THEN EQ_TAC THENL
   [STRIP_TAC THEN ASM_CASES_TAC `(x:real^2) IN interior t` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(x:real^2)$2 = -- &1 \/ x$2 = x$1 \/ x$1 + &2 * x$2 = &0`
    STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `~((x:real^2) IN interior t /\
                     x$2 < x$1 /\ x$1 + &2 * x$2 < &0 /\ x$2 < -- &1)` THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      DISJ1_TAC THEN ASM_REAL_ARITH_TAC;
      DISJ2_TAC THEN DISJ1_TAC THEN EXISTS_TAC `--((x:real^2)$1)` THEN
      SUBGOAL_THEN `x = --((x:real^2)$1) % v1` ASSUME_TAC THENL
       [ASM_REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_MUL_COMPONENT] THEN
        ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "in_v1" (MP_TAC o SPEC `--((x:real^2)$1)`) THEN
      ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_MESON_TAC[];
      DISJ2_TAC THEN DISJ2_TAC THEN EXISTS_TAC `--((x:real^2)$2)` THEN
      SUBGOAL_THEN `x = --((x:real^2)$2) % v2` ASSUME_TAC THENL
       [ASM_REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_MUL_COMPONENT] THEN
        ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "in_v2" (MP_TAC o SPEC `--((x:real^2)$2)`) THEN
      ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_MESON_TAC[]];
    STRIP_TAC THENL
     [ASM_REWRITE_TAC[];
      SUBGOAL_THEN `(x:real^2) IN interior t` ASSUME_TAC THENL
       [FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> can (find_term ((=) `moi_s5c_tri`)) (concl th) && is_forall (concl th))) THEN
        REWRITE_TAC[moi_s5c_tri; IN_ELIM_THM] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      ASM_SIMP_TAC[REWRITE_RULE[SUBSET] INTERIOR_SUBSET] THEN ASM_REAL_ARITH_TAC;
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      USE_THEN "in_v1" (MP_TAC o SPEC `r:real`) THEN
      ANTS_TAC THENL [UNDISCH_TAC `&1 <= r` THEN REAL_ARITH_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[VECTOR_MUL_COMPONENT] THEN
      UNDISCH_TAC `&1 <= r` THEN REAL_ARITH_TAC;
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      USE_THEN "in_v2" (MP_TAC o SPEC `r:real`) THEN
      ANTS_TAC THENL [UNDISCH_TAC `&1 <= r` THEN REAL_ARITH_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[VECTOR_MUL_COMPONENT] THEN
      UNDISCH_TAC `&1 <= r` THEN REAL_ARITH_TAC]]);;

let MOI_S5C_JOIN3_VALUES = prove
 (`!a b c (d:real^N) s.
     &0 <= s /\ s <= &1
     ==> (linepath(a,b) ++ linepath(b,c) ++ linepath(c,d)) (lift(s / &2)) =
         linepath(a,b) (lift s) /\
         (linepath(a,b) ++ linepath(b,c) ++ linepath(c,d)) (lift((s + &2) / &4)) =
         linepath(b,c) (lift s) /\
         (linepath(a,b) ++ linepath(b,c) ++ linepath(c,d)) (lift((s + &3) / &4)) =
         linepath(c,d) (lift s)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[joinpaths; LIFT_DROP; GSYM LIFT_CMUL; GSYM LIFT_NUM; GSYM LIFT_SUB] THEN
  REWRITE_TAC[linepath; LIFT_DROP] THEN
  ASM_CASES_TAC `s = &0` THENL
   [ASM_REWRITE_TAC[] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN VECTOR_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `s / &2 <= &1 / &2 /\ ~((s + &2) / &4 <= &1 / &2) /\
                &2 * (s + &2) / &4 - &1 <= &1 / &2 /\ ~((s + &3) / &4 <= &1 / &2) /\
                ~(&2 * (s + &3) / &4 - &1 <= &1 / &2)`
  (fun th -> REWRITE_TAC[th]) THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_ARITH `&2 * s / &2 = s`;
              REAL_ARITH `&2 * (&2 * (s + &2) / &4 - &1) = s`;
              REAL_ARITH `&2 * (&2 * (s + &3) / &4 - &1) - &1 = s`]);;

let MOI_S5C_ARC3 = prove
 (`!a b c d:real^N.
     ~(a = b) /\ ~(b = c) /\ ~(c = d) /\
     segment[a,b] INTER (segment[b,c] UNION segment[c,d]) SUBSET {b} /\
     segment[b,c] INTER segment[c,d] SUBSET {c}
     ==> arc(linepath(a,b) ++ linepath(b,c) ++ linepath(c,d)) /\
         path_image(linepath(a,b) ++ linepath(b,c) ++ linepath(c,d)) =
         segment[a,b] UNION segment[b,c] UNION segment[c,d] /\
         pathstart(linepath(a,b) ++ linepath(b,c) ++ linepath(c,d)) = a /\
         pathfinish(linepath(a,b) ++ linepath(b,c) ++ linepath(c,d)) = d /\
         pl_map_on (interval[vec 0,vec 1])
                   (linepath(a,b) ++ linepath(b,c) ++ linepath(c,d))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!p q:real^N. pl_map_on (interval[vec 0,vec 1]) (linepath(p,q))`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN MATCH_MP_TAC MOI_PL2_PL_LINEPATH THEN
    REWRITE_TAC[MOI_PL2_LOCALLY_POLYHEDRAL_INTERVAL]; ALL_TAC] THEN
  ASM_SIMP_TAC[PATH_IMAGE_JOIN; PATHSTART_JOIN; PATHFINISH_JOIN;
               PATHSTART_LINEPATH; PATHFINISH_LINEPATH; PATH_IMAGE_LINEPATH;
               MOI_PL2_PL_JOINPATHS] THEN
  MATCH_MP_TAC ARC_JOIN THEN
  ASM_SIMP_TAC[ARC_LINEPATH; PATHSTART_JOIN; PATHFINISH_JOIN; PATH_IMAGE_JOIN;
               PATHSTART_LINEPATH; PATHFINISH_LINEPATH; PATH_IMAGE_LINEPATH] THEN
  MATCH_MP_TAC ARC_JOIN THEN
  ASM_SIMP_TAC[ARC_LINEPATH; PATHSTART_LINEPATH; PATHFINISH_LINEPATH;
               PATH_IMAGE_LINEPATH]);;

let MOI_S5C_CELL_BALL = prove
 (`!n (d:real^N->bool) j. pl_cell_with_boundary n d j ==> pl_ball n d`,
  REWRITE_TAC[pl_cell_with_boundary; pl_ball] THEN MESON_TAC[]);;

let MOI_S5C_LAM_UNIQUE = prove
 (`!(t:real^N->bool) v r.
     convex t /\ compact t /\ vec 0 IN interior t /\ ~(v = vec 0) /\
     &0 < r /\ r % v IN relative_frontier t
     ==> moi_s5c_lam t v = r`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`t:real^N->bool`; `v:real^N`] MOI_S5C_LAM) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(vec 0:real^N) IN relative_interior t` ASSUME_TAC THENL
   [ASM_MESON_TAC[INTERIOR_SUBSET_RELATIVE_INTERIOR; SUBSET]; ALL_TAC] THEN
  MP_TAC(ISPECL [`t:real^N->bool`; `moi_s5c_lam t (v:real^N) % v`; `r % v:real^N`;
                 `moi_s5c_lam t (v:real^N) / r`] MOI_CMB_RAY_FRONTIER_UNIQUE) THEN
  ASM_SIMP_TAC[REAL_LT_DIV; VECTOR_MUL_ASSOC; REAL_DIV_RMUL; REAL_LT_IMP_NZ] THEN
  ASM_SIMP_TAC[REAL_EQ_LDIV_EQ; REAL_MUL_LID]);;

let MOI_S5C_LAM_TRI2 = prove
 (`moi_s5c_lam moi_s5c_tri2 (vector[-- &1;-- &1]) = &2 /\
   moi_s5c_lam moi_s5c_tri2 (vector[&2;-- &1]) = &2 /\
   moi_s5c_lam moi_s5c_tri2 (vector[-- &1;&2]) = &2`,
  SUBGOAL_THEN `~(interior moi_s5c_tri2 = {}) /\ (vec 0:real^2) IN interior moi_s5c_tri2`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[MOI_S5C_TRI2_INTERIOR; GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    REWRITE_TAC[VEC_COMPONENT] THEN
    CONJ_TAC THENL [EXISTS_TAC `vec 0:real^2`; ALL_TAC] THEN
    REWRITE_TAC[VEC_COMPONENT] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `relative_frontier moi_s5c_tri2 =
                {x:real^2 | x IN moi_s5c_tri2 /\
                            ~(-- &2 < x$1 /\ -- &2 < x$2 /\ x$1 + x$2 < &2)}`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[RELATIVE_FRONTIER_NONEMPTY_INTERIOR; frontier; CLOSURE_CLOSED;
                 COMPACT_IMP_CLOSED; MOI_S5C_TRI2_INTERIOR; MOI_S5C_TRI_FACTS] THEN
    SET_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_LAM_UNIQUE THEN
  ASM_REWRITE_TAC[IN_ELIM_THM; moi_s5c_tri2; CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2;
                  VEC_COMPONENT; VECTOR_MUL_COMPONENT; MOI_S5C_TRI_FACTS] THEN
  CONV_TAC REAL_RAT_REDUCE_CONV);;

let MOI_S5C_H_SEGS = prove
 (`!l1 l2. &1 < l1 /\ &1 < l2
     ==> ~(l1 % vector[-- &1;-- &1] = vector[-- &1;-- &1]:real^2) /\
         ~(vector[-- &1;-- &1] = vector[&2;-- &1]:real^2) /\
         ~(vector[&2;-- &1] = l2 % vector[&2;-- &1]:real^2) /\
         segment[l1 % vector[-- &1;-- &1],vector[-- &1;-- &1]:real^2] INTER
         (segment[vector[-- &1;-- &1],vector[&2;-- &1]] UNION
          segment[vector[&2;-- &1],l2 % vector[&2;-- &1]])
         SUBSET {vector[-- &1;-- &1]} /\
         segment[vector[-- &1;-- &1],vector[&2;-- &1]:real^2] INTER
         segment[vector[&2;-- &1],l2 % vector[&2;-- &1]]
         SUBSET {vector[&2;-- &1]}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[SUBSET; IN_INTER; IN_UNION; IN_SING] THEN
  SUBGOAL_THEN
   `(!x:real^2. x IN segment[l1 % vector[-- &1;-- &1],vector[-- &1;-- &1]] <=>
                ?r. &1 <= r /\ r <= l1 /\ x = r % vector[-- &1;-- &1]) /\
    (!x:real^2. x IN segment[vector[&2;-- &1],l2 % vector[&2;-- &1]] <=>
                ?r. &1 <= r /\ r <= l2 /\ x = r % vector[&2;-- &1])`
  (fun th -> REWRITE_TAC[th; MOI_S5C_SEG_V1V2]) THENL
   [CONJ_TAC THENL [ALL_TAC; ONCE_REWRITE_TAC[SEGMENT_SYM]] THEN
    MATCH_MP_TAC MOI_S5C_SEG_RAY THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2; VECTOR_MUL_COMPONENT] THEN
  REPEAT CONJ_TAC THEN TRY(ASM_REAL_ARITH_TAC) THEN
  X_GEN_TAC `x:real^2` THEN REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_REAL_ARITH_TAC);;

let MOI_S5C_ARC_MATCH = prove
 (`!(d:real^2->bool) (d':real^2->bool) (h:real^1->real^2) (h':real^1->real^2).
     pl_ball 2 d /\ pl_ball 2 d' /\
     arc h /\ pl_map_on (interval[vec 0,vec 1]) h /\ path_image h SUBSET frontier d /\
     arc h' /\ pl_map_on (interval[vec 0,vec 1]) h' /\ path_image h' SUBSET frontier d'
     ==> ?f g. pl_homeomorphism (d,d') (f,g) /\
               !s. s IN interval[vec 0,vec 1] ==> f(h s) = h' s`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`d:real^2->bool`; `h:real^1->real^2`; `vec 0:real^2`;
                 `basis 1:real^2`; `basis 2:real^2`] MOI_PL2_BALL_BOUNDARY_ARC) THEN
  MP_TAC(ISPECL [`d':real^2->bool`; `h':real^1->real^2`; `vec 0:real^2`;
                 `basis 1:real^2`; `basis 2:real^2`] MOI_PL2_BALL_BOUNDARY_ARC) THEN
  SUBGOAL_THEN `~collinear{vec 0:real^2,basis 1,basis 2}` (fun th -> REWRITE_TAC[th]) THENL
   [SIMP_TAC[COLLINEAR_3_2D; BASIS_COMPONENT; VEC_COMPONENT; DIMINDEX_2; ARITH] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  MAP_EVERY X_GEN_TAC [`G:real^2->real^2`; `G':real^2->real^2`] THEN STRIP_TAC THEN
  MAP_EVERY X_GEN_TAC [`FF:real^2->real^2`; `FF':real^2->real^2`] THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC [`(G:real^2->real^2) o (FF':real^2->real^2)`;
                        `(FF:real^2->real^2) o (G':real^2->real^2)`] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
    EXISTS_TAC `convex hull {vec 0:real^2,basis 1,basis 2}` THEN
    ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  X_GEN_TAC `s:real^1` THEN DISCH_TAC THEN REWRITE_TAC[o_THM] THEN
  SUBGOAL_THEN `linepath(vec 0:real^2,basis 1) s IN convex hull {vec 0:real^2,basis 1,basis 2}`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(SET_RULE `!s t (x:real^2). s SUBSET t /\ x IN s ==> x IN t`) THEN
    EXISTS_TAC `segment[vec 0:real^2,basis 1]` THEN CONJ_TAC THENL
     [MATCH_MP_TAC SEGMENT_SUBSET_CONVEX THEN REWRITE_TAC[CONVEX_CONVEX_HULL] THEN
      CONJ_TAC THEN MATCH_MP_TAC HULL_INC THEN SET_TAC[];
      REWRITE_TAC[GSYM PATH_IMAGE_LINEPATH; path_image] THEN ASM SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(FF':real^2->real^2) (h(s:real^1)) = linepath(vec 0:real^2,basis 1) s`
  SUBST1_TAC THENL
   [SUBGOAL_THEN `(h:real^1->real^2) s = FF(linepath(vec 0:real^2,basis 1) s)` SUBST1_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `pl_homeomorphism (convex hull {vec 0:real^2,basis 1,basis 2},d:real^2->bool) (FF,FF')` THEN
    REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN ASM_MESON_TAC[];
    ASM_MESON_TAC[]]);;

let MOI_S5C_IMAGE_COMPL = prove
 (`!(f:A->B) s a h a' h' e e'.
     (!x y. x IN s /\ y IN s /\ f x = f y ==> x = y) /\ a UNION h SUBSET s /\
     IMAGE f (a UNION h) = a' UNION h' /\ IMAGE f h = h' /\
     a INTER h = e /\ a' INTER h' = e' /\ IMAGE f e = e'
     ==> IMAGE f a = a'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `a:A->bool = (a UNION h) DIFF (h DIFF e)` SUBST1_TAC THENL
   [ASM SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (f:A->B) ((a UNION h) DIFF (h DIFF e)) =
                IMAGE f (a UNION h) DIFF IMAGE f (h DIFF e)` SUBST1_TAC THENL
   [MATCH_MP_TAC IMAGE_DIFF_INJ_ALT THEN
    CONJ_TAC THENL [ASM_MESON_TAC[SUBSET]; ASM SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (f:A->B) (h DIFF e) = IMAGE f h DIFF IMAGE f e` SUBST1_TAC THENL
   [MATCH_MP_TAC IMAGE_DIFF_INJ_ALT THEN
    CONJ_TAC THENL [ASM_MESON_TAC[SUBSET; IN_UNION]; ASM SET_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN ASM SET_TAC[]);;

let MOI_S5C_LP_SCALE = prove
 (`!a b (v:real^N) u. linepath(a % v,b % v) (lift u) = ((&1 - u) * a + u * b) % v`,
  REWRITE_TAC[linepath; LIFT_DROP] THEN VECTOR_ARITH_TAC);;

let MOI_S5C_IN_UNIT = prove
 (`!u. lift u IN interval[vec 0,vec 1] <=> &0 <= u /\ u <= &1`,
  REWRITE_TAC[IN_INTERVAL_1; LIFT_DROP; DROP_VEC]);;

let MOI_S5C_TRI2_EDGE_INTER = prove
 (`segment[&2 % vector[-- &1;-- &1],&2 % vector[&2;-- &1]:real^2] INTER
   (segment[&2 % vector[-- &1;-- &1],vector[-- &1;-- &1]] UNION
    segment[vector[-- &1;-- &1],vector[&2;-- &1]] UNION
    segment[vector[&2;-- &1],&2 % vector[&2;-- &1]]) =
   {&2 % vector[-- &1;-- &1], &2 % vector[&2;-- &1]}`,
  SUBGOAL_THEN
   `(!x:real^2. x IN segment[&2 % vector[-- &1;-- &1],vector[-- &1;-- &1]] <=>
                ?r. &1 <= r /\ r <= &2 /\ x = r % vector[-- &1;-- &1]) /\
    (!x:real^2. x IN segment[vector[&2;-- &1],&2 % vector[&2;-- &1]] <=>
                ?r. &1 <= r /\ r <= &2 /\ x = r % vector[&2;-- &1]) /\
    (!x:real^2. x IN segment[&2 % vector[-- &1;-- &1],&2 % vector[&2;-- &1]] <=>
                x$2 = -- &2 /\ -- &2 <= x$1 /\ x$1 <= &4)`
  (fun th -> REWRITE_TAC[EXTENSION; IN_INTER; IN_UNION; IN_INSERT; NOT_IN_EMPTY; th;
                         MOI_S5C_SEG_V1V2]) THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC MOI_S5C_SEG_RAY THEN REAL_ARITH_TAC;
      ONCE_REWRITE_TAC[SEGMENT_SYM] THEN MATCH_MP_TAC MOI_S5C_SEG_RAY THEN REAL_ARITH_TAC;
      GEN_TAC THEN REWRITE_TAC[IN_SEGMENT; CART_EQ; DIMINDEX_2; FORALL_2;
        VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; VECTOR_2] THEN
      EQ_TAC THENL
       [STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
        STRIP_TAC THEN EXISTS_TAC `((x:real^2)$1 + &2) / &6` THEN ASM_REAL_ARITH_TAC]];
    ALL_TAC] THEN
  X_GEN_TAC `x:real^2` THEN
  REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_MUL_COMPONENT; VECTOR_2] THEN
  EQ_TAC THENL
   [STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
    FIRST [DISJ1_TAC THEN EXISTS_TAC `&2` THEN REAL_ARITH_TAC;
           DISJ2_TAC THEN EXISTS_TAC `&2` THEN REAL_ARITH_TAC]]);;

let MOI_S5C_PIECE12_MAP = prove
 (`!t:real^2->bool.
     &2 simplex t /\ moi_s5c_tri SUBSET interior t
     ==> ?f g. pl_homeomorphism (t INTER moi_s5c_k12,moi_s5c_tri2 INTER moi_s5c_k12) (f,g) /\
               (!x. x IN segment[vector[-- &1;-- &1],vector[&2;-- &1]] ==> f x = x) /\
               (!r. &1 <= r /\ r <= moi_s5c_lam t (vector[-- &1;-- &1])
                    ==> f(r % vector[-- &1;-- &1]) =
                        (&1 + (r - &1) / (moi_s5c_lam t (vector[-- &1;-- &1]) - &1)) %
                        vector[-- &1;-- &1]) /\
               (!r. &1 <= r /\ r <= moi_s5c_lam t (vector[&2;-- &1])
                    ==> f(r % vector[&2;-- &1]) =
                        (&1 + (r - &1) / (moi_s5c_lam t (vector[&2;-- &1]) - &1)) %
                        vector[&2;-- &1]) /\
               IMAGE f (relative_frontier t INTER moi_s5c_k12) =
               segment[&2 % vector[-- &1;-- &1],&2 % vector[&2;-- &1]]`,
  GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPEC `t:real^2->bool` MOI_S5C_PIECE12_RF) THEN ASM_REWRITE_TAC[] THEN
  STRIP_TAC THEN
  MP_TAC(SPEC `moi_s5c_tri2` MOI_S5C_PIECE12_RF) THEN
  REWRITE_TAC[MOI_S5C_TRI_FACTS; MOI_S5C_LAM_TRI2] THEN STRIP_TAC THEN
  ABBREV_TAC `l1 = moi_s5c_lam (t:real^2->bool) (vector[-- &1;-- &1])` THEN
  ABBREV_TAC `l2 = moi_s5c_lam (t:real^2->bool) (vector[&2;-- &1])` THEN
  ABBREV_TAC `v1 = vector[-- &1;-- &1]:real^2` THEN
  ABBREV_TAC `v2 = vector[&2;-- &1]:real^2` THEN
  SUBGOAL_THEN `relative_frontier moi_s5c_tri2 INTER moi_s5c_k12 =
                segment[&2 % v1,&2 % (v2:real^2)]` ASSUME_TAC THENL
   [SUBGOAL_THEN `~(interior moi_s5c_tri2 = {})` ASSUME_TAC THENL
     [REWRITE_TAC[MOI_S5C_TRI2_INTERIOR; GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      EXISTS_TAC `vec 0:real^2` THEN REWRITE_TAC[VEC_COMPONENT] THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    ASM_SIMP_TAC[RELATIVE_FRONTIER_NONEMPTY_INTERIOR; frontier; CLOSURE_CLOSED;
                 COMPACT_IMP_CLOSED; MOI_S5C_TRI_FACTS; MOI_S5C_TRI2_INTERIOR] THEN
    MAP_EVERY EXPAND_TAC ["v1"; "v2"] THEN
    REWRITE_TAC[EXTENSION; IN_INTER; IN_DIFF; IN_ELIM_THM; moi_s5c_tri2; moi_s5c_k12;
                IN_SEGMENT; CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_ADD_COMPONENT;
                VECTOR_MUL_COMPONENT; VECTOR_2] THEN
    X_GEN_TAC `x:real^2` THEN EQ_TAC THENL
     [STRIP_TAC THEN EXISTS_TAC `((x:real^2)$1 + &2) / &6` THEN ASM_REAL_ARITH_TAC;
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`l1:real`; `l2:real`] MOI_S5C_H_SEGS) THEN
  MP_TAC(ISPECL [`&2`; `&2`] MOI_S5C_H_SEGS) THEN
  ASM_REWRITE_TAC[REAL_ARITH `&1 < &2`] THEN REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`l1 % v1:real^2`; `v1:real^2`; `v2:real^2`; `l2 % v2:real^2`] MOI_S5C_ARC3) THEN
  MP_TAC(ISPECL [`&2 % v1:real^2`; `v1:real^2`; `v2:real^2`; `&2 % v2:real^2`] MOI_S5C_ARC3) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `h = linepath(l1 % v1,v1) ++ linepath(v1,v2) ++ linepath(v2,l2 % v2:real^2)` THEN
  ABBREV_TAC `h0 = linepath(&2 % v1,v1) ++ linepath(v1,v2) ++ linepath(v2,&2 % v2:real^2)` THEN
  SUBGOAL_THEN `frontier (t INTER moi_s5c_k12) = relative_frontier (t INTER moi_s5c_k12) /\
                frontier (moi_s5c_tri2 INTER moi_s5c_k12) =
                relative_frontier (moi_s5c_tri2 INTER moi_s5c_k12:real^2->bool)`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC RELATIVE_FRONTIER_NONEMPTY_INTERIOR THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`t INTER moi_s5c_k12:real^2->bool`; `moi_s5c_tri2 INTER moi_s5c_k12:real^2->bool`;
                 `h:real^1->real^2`; `h0:real^1->real^2`] MOI_S5C_ARC_MATCH) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC MOI_S5C_CELL_BALL THEN
      EXISTS_TAC `relative_frontier (t INTER moi_s5c_k12:real^2->bool)` THEN
      MATCH_MP_TAC MOI_S5C_POLYTOPE_CELL THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC MOI_S5C_CELL_BALL THEN
      EXISTS_TAC `relative_frontier (moi_s5c_tri2 INTER moi_s5c_k12:real^2->bool)` THEN
      MATCH_MP_TAC MOI_S5C_POLYTOPE_CELL THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[SEGMENT_SYM] THEN
      MATCH_MP_TAC(SET_RULE `(a:real^2->bool) SUBSET d /\ b SUBSET d /\ c SUBSET d
                             ==> a UNION b UNION c SUBSET d`) THEN
      REPEAT CONJ_TAC THEN SET_TAC[];
      REWRITE_TAC[SEGMENT_SYM] THEN
      MATCH_MP_TAC(SET_RULE `(a:real^2->bool) SUBSET d /\ b SUBSET d /\ c SUBSET d
                             ==> a UNION b UNION c SUBSET d`) THEN
      REPEAT CONJ_TAC THEN SET_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  MAP_EVERY X_GEN_TAC [`f:real^2->real^2`; `g:real^2->real^2`] THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC [`f:real^2->real^2`; `g:real^2->real^2`] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!u. &0 <= u /\ u <= &1
        ==> (h:real^1->real^2) (lift(u / &2)) = ((&1 - u) * l1 + u) % v1 /\
            h (lift((u + &2) / &4)) = linepath(v1,v2) (lift u) /\
            h (lift((u + &3) / &4)) = ((&1 - u) + u * l2) % v2 /\
            (h0:real^1->real^2) (lift(u / &2)) = ((&1 - u) * &2 + u) % v1 /\
            h0 (lift((u + &2) / &4)) = linepath(v1,v2) (lift u) /\
            h0 (lift((u + &3) / &4)) = ((&1 - u) + u * &2) % v2`
  (LABEL_TAC "hv") THENL
   [X_GEN_TAC `u:real` THEN DISCH_TAC THEN MAP_EVERY EXPAND_TAC ["h"; "h0"] THEN
    ASM_SIMP_TAC[MOI_S5C_JOIN3_VALUES] THEN
    REWRITE_TAC[linepath; LIFT_DROP] THEN REPEAT CONJ_TAC THEN VECTOR_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!s. s IN interval[vec 0,vec 1] ==> (f:real^2->real^2) ((h:real^1->real^2) s) = (h0:real^1->real^2) s`
  (LABEL_TAC "fh") THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_SEGMENT] THEN X_GEN_TAC `x:real^2` THEN
    DISCH_THEN(X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `x = linepath(v1:real^2,v2) (lift u)` SUBST1_TAC THENL
     [ASM_REWRITE_TAC[linepath; LIFT_DROP]; ALL_TAC] THEN
    REMOVE_THEN "hv" (MP_TAC o SPEC `u:real`) THEN ASM_REWRITE_TAC[] THEN
    STRIP_TAC THEN
    TRANS_TAC EQ_TRANS `(h0:real^1->real^2)(lift((u + &2) / &4))` THEN
    CONJ_TAC THENL [ALL_TAC; ASM_REWRITE_TAC[]] THEN
    GEN_REWRITE_TAC (LAND_CONV o RAND_CONV)
      [SYM(ASSUME `(h:real^1->real^2) (lift((u + &2) / &4)) = linepath(v1,v2:real^2) (lift u)`)] THEN
    REMOVE_THEN "fh" MATCH_MP_TAC THEN REWRITE_TAC[MOI_S5C_IN_UNIT] THEN
    ASM_REAL_ARITH_TAC;
    X_GEN_TAC `r:real` THEN STRIP_TAC THEN
    SUBGOAL_THEN `&0 < l1 - &1` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `((l1 - r) / (l1 - &1)) * (l1 - &1) = l1 - r /\
                  (l1 - r) / (l1 - &1) + (r - &1) / (l1 - &1) = &1 /\
                  &0 <= (l1 - r) / (l1 - &1) /\ (l1 - r) / (l1 - &1) <= &1`
    MP_TAC THENL
     [CONJ_TAC THENL [UNDISCH_TAC `&0 < l1 - &1` THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
      CONJ_TAC THENL [UNDISCH_TAC `&0 < l1 - &1` THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
      CONJ_TAC THENL [MATCH_MP_TAC REAL_LE_DIV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    ABBREV_TAC `u = (l1 - r) / (l1 - &1)` THEN STRIP_TAC THEN
    REMOVE_THEN "hv" (MP_TAC o SPEC `u:real`) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `r % v1 = (h:real^1->real^2) (lift(u / &2))` SUBST1_TAC THENL
     [ASM_REWRITE_TAC[] THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      UNDISCH_TAC `u * (l1 - &1) = l1 - r` THEN REAL_ARITH_TAC; ALL_TAC] THEN
    USE_THEN "fh" (MP_TAC o SPEC `lift(u / &2)`) THEN
    REWRITE_TAC[MOI_S5C_IN_UNIT] THEN ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[] THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    UNDISCH_TAC `u + (r - &1) / (l1 - &1) = &1` THEN REAL_ARITH_TAC;
    X_GEN_TAC `r:real` THEN STRIP_TAC THEN
    SUBGOAL_THEN `&0 < l2 - &1` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `((r - &1) / (l2 - &1)) * (l2 - &1) = r - &1 /\
                  &0 <= (r - &1) / (l2 - &1) /\ (r - &1) / (l2 - &1) <= &1`
    MP_TAC THENL
     [CONJ_TAC THENL [ASM_SIMP_TAC[REAL_DIV_RMUL; REAL_LT_IMP_NZ]; ALL_TAC] THEN
      CONJ_TAC THENL [MATCH_MP_TAC REAL_LE_DIV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    ABBREV_TAC `u = (r - &1) / (l2 - &1)` THEN STRIP_TAC THEN
    REMOVE_THEN "hv" (MP_TAC o SPEC `u:real`) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `r % v2 = (h:real^1->real^2) (lift((u + &3) / &4))` SUBST1_TAC THENL
     [ASM_REWRITE_TAC[] THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      UNDISCH_TAC `u * (l2 - &1) = r - &1` THEN REAL_ARITH_TAC; ALL_TAC] THEN
    USE_THEN "fh" (MP_TAC o SPEC `lift((u + &3) / &4)`) THEN
    REWRITE_TAC[MOI_S5C_IN_UNIT] THEN ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[] THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    REAL_ARITH_TAC;
    MATCH_MP_TAC MOI_S5C_IMAGE_COMPL THEN
    MAP_EVERY EXISTS_TAC
     [`t INTER moi_s5c_k12:real^2->bool`; `path_image(h:real^1->real^2)`;
      `path_image(h0:real^1->real^2)`; `{l1 % v1:real^2, l2 % v2}`;
      `{&2 % v1:real^2, &2 % v2}`] THEN
    MP_TAC(ISPECL [`t:real^2->bool`; `v1:real^2`] MOI_S5C_LAM) THEN
    MP_TAC(ISPECL [`t:real^2->bool`; `v2:real^2`] MOI_S5C_LAM) THEN
    SUBGOAL_THEN `!x:real^2. x IN moi_s5c_tri ==> x IN interior t` ASSUME_TAC THENL
     [UNDISCH_TAC `moi_s5c_tri SUBSET interior (t:real^2->bool)` THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `convex (t:real^2->bool) /\ compact t /\ vec 0 IN interior t /\
                  ~(v1 = vec 0) /\ ~(v2 = vec 0) /\
                  v1 IN interior t /\ v2 IN interior t /\
                  segment[v1,v2] SUBSET interior t`
    (fun th -> REWRITE_TAC[th] THEN STRIP_ASSUME_TAC th) THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC SIMPLEX_IMP_CONVEX THEN EXISTS_TAC `&2:int` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC SIMPLEX_IMP_COMPACT THEN EXISTS_TAC `&2:int` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      REWRITE_TAC[SUBSET] THEN REPEAT CONJ_TAC THEN
      TRY(X_GEN_TAC `x:real^2` THEN DISCH_TAC) THEN
      TRY(FIRST_ASSUM MATCH_MP_TAC) THEN
      MAP_EVERY EXPAND_TAC ["v1"; "v2"] THEN
      REWRITE_TAC[moi_s5c_tri; IN_ELIM_THM; CART_EQ; DIMINDEX_2; FORALL_2;
                  VECTOR_2; VEC_COMPONENT] THEN
      TRY REAL_ARITH_TAC THEN
      UNDISCH_TAC `(x:real^2) IN segment[v1,v2]` THEN
      MAP_EVERY EXPAND_TAC ["v1"; "v2"] THEN REWRITE_TAC[MOI_S5C_SEG_V1V2] THEN
      REAL_ARITH_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "in2") (LABEL_TAC "int2")))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "in1") (LABEL_TAC "int1")))) THEN
    SUBGOAL_THEN `(!x y. x IN t INTER moi_s5c_k12 /\ y IN t INTER moi_s5c_k12 /\
                         (f:real^2->real^2) x = f y ==> x = y) /\
                  IMAGE f (relative_frontier (t INTER moi_s5c_k12)) =
                  relative_frontier (moi_s5c_tri2 INTER moi_s5c_k12) /\
                  relative_frontier (t INTER moi_s5c_k12) SUBSET t INTER moi_s5c_k12`
    STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [UNDISCH_TAC `pl_homeomorphism (t INTER moi_s5c_k12,moi_s5c_tri2 INTER moi_s5c_k12)
                       (f:real^2->real^2,g)` THEN
        REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN MESON_TAC[];
        MP_TAC(ISPECL [`t INTER moi_s5c_k12:real^2->bool`;
                       `moi_s5c_tri2 INTER moi_s5c_k12:real^2->bool`;
                       `f:real^2->real^2`; `g:real^2->real^2`]
          MOI_PL2_HOMEOMORPHISM_FRONTIER) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
        ASM_SIMP_TAC[POLYTOPE_IMP_CLOSED] THEN
        UNDISCH_TAC `pl_homeomorphism (t INTER moi_s5c_k12,moi_s5c_tri2 INTER moi_s5c_k12)
                       (f:real^2->real^2,g)` THEN
        SIMP_TAC[pl_homeomorphism];
        MATCH_MP_TAC RELATIVE_FRONTIER_SUBSET THEN ASM_SIMP_TAC[POLYTOPE_IMP_CLOSED]];
      ALL_TAC] THEN
    SUBGOAL_THEN `IMAGE (f:real^2->real^2) (path_image h) = path_image h0` ASSUME_TAC THENL
     [REWRITE_TAC[path_image; GSYM IMAGE_o] THEN MATCH_MP_TAC MOI_S5C_IMAGE_EQ THEN
      REWRITE_TAC[o_THM] THEN USE_THEN "fh" ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(f:real^2->real^2) (l1 % v1) = &2 % v1 /\ f (l2 % v2) = &2 % v2`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPEC `vec 0:real^1` (ASSUME `!s. s IN interval[vec 0,vec 1]
                    ==> (f:real^2->real^2) ((h:real^1->real^2) s) = (h0:real^1->real^2) s`)) THEN
      MP_TAC(SPEC `vec 1:real^1` (ASSUME `!s. s IN interval[vec 0,vec 1]
                    ==> (f:real^2->real^2) ((h:real^1->real^2) s) = (h0:real^1->real^2) s`)) THEN
      REWRITE_TAC[ENDS_IN_UNIT_INTERVAL] THEN
      UNDISCH_TAC `pathstart (h:real^1->real^2) = l1 % v1` THEN
      UNDISCH_TAC `pathfinish (h:real^1->real^2) = l2 % v2` THEN
      UNDISCH_TAC `pathstart (h0:real^1->real^2) = &2 % v1` THEN
      UNDISCH_TAC `pathfinish (h0:real^1->real^2) = &2 % v2` THEN
      REWRITE_TAC[pathstart; pathfinish] THEN
      REPEAT(DISCH_THEN SUBST1_TAC) THEN SIMP_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `relative_frontier t INTER moi_s5c_k12 UNION
                  segment [l1 % v1,v1] UNION segment [v1,v2] UNION segment [v2,l2 % v2] =
                  relative_frontier (t INTER moi_s5c_k12) /\
                  segment [&2 % v1,&2 % v2] UNION
                  segment [&2 % v1,v1] UNION segment [v1,v2] UNION segment [v2,&2 % v2] =
                  relative_frontier (moi_s5c_tri2 INTER moi_s5c_k12:real^2->bool)`
    (fun th -> REWRITE_TAC[th]) THENL
     [MP_TAC(ASSUME `relative_frontier (moi_s5c_tri2 INTER moi_s5c_k12) =
        relative_frontier moi_s5c_tri2 INTER moi_s5c_k12 UNION segment [v1,v2] UNION
        segment [&2 % v1,v1] UNION segment [&2 % v2,v2:real^2]`) THEN
      MP_TAC(ASSUME `relative_frontier (t INTER moi_s5c_k12) =
        relative_frontier t INTER moi_s5c_k12 UNION segment [v1,v2] UNION
        segment [l1 % v1,v1] UNION segment [l2 % v2,v2:real^2]`) THEN
      MP_TAC(ASSUME `relative_frontier moi_s5c_tri2 INTER moi_s5c_k12 =
                     segment[&2 % v1,&2 % (v2:real^2)]`) THEN
      REWRITE_TAC[SEGMENT_SYM] THEN SET_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MP_TAC(ASSUME `IMAGE (f:real^2->real^2) (path_image h) = path_image h0`) THEN
      REWRITE_TAC[ASSUME `path_image (h:real^1->real^2) =
                    segment [l1 % v1,v1] UNION segment [v1,v2] UNION segment [v2,l2 % v2]`;
                  ASSUME `path_image (h0:real^1->real^2) =
                    segment [&2 % v1,v1] UNION segment [v1,v2] UNION segment [v2,&2 % v2]`];
      ALL_TAC] THEN
    REWRITE_TAC[IMAGE_CLAUSES] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [ALL_TAC;
      MAP_EVERY EXPAND_TAC ["v1"; "v2"] THEN REWRITE_TAC[MOI_S5C_TRI2_EDGE_INTER]] THEN
    SUBGOAL_THEN `!x:real^2. x IN relative_frontier t ==> ~(x IN interior t)` ASSUME_TAC THENL
     [REWRITE_TAC[relative_frontier; IN_DIFF] THEN
      SUBGOAL_THEN `relative_interior t = interior (t:real^2->bool)` SUBST1_TAC THENL
       [MATCH_MP_TAC RELATIVE_INTERIOR_NONEMPTY_INTERIOR THEN
        REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN EXISTS_TAC `vec 0:real^2` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MESON_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[EXTENSION; IN_INTER; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
    SUBGOAL_THEN
     `(!x:real^2. x IN segment[l1 % v1,v1] <=> ?r. &1 <= r /\ r <= l1 /\ x = r % v1) /\
      (!x:real^2. x IN segment[v2,l2 % v2] <=> ?r. &1 <= r /\ r <= l2 /\ x = r % v2)`
    (fun th -> REWRITE_TAC[th]) THENL
     [CONJ_TAC THENL [ALL_TAC; ONCE_REWRITE_TAC[SEGMENT_SYM]] THEN
      MATCH_MP_TAC MOI_S5C_SEG_RAY THEN ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    X_GEN_TAC `x:real^2` THEN EQ_TAC THENL
     [STRIP_TAC THENL
       [ASM_CASES_TAC `r:real = l1` THENL
         [DISJ1_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "int1" (MP_TAC o SPEC `r:real`) THEN
        ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
        FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th -> is_eq(concl th) && lhs(concl th) = `x:real^2`)) THEN
        MATCH_MP_TAC(TAUT `~p ==> p ==> q`) THEN
        MATCH_MP_TAC(ASSUME `!x:real^2. x IN relative_frontier t ==> ~(x IN interior t)`) THEN
        ASM_REWRITE_TAC[];
        SUBGOAL_THEN `(x:real^2) IN interior t` MP_TAC THENL
         [UNDISCH_TAC `(x:real^2) IN segment[v1,v2]` THEN
          UNDISCH_TAC `segment[v1,v2] SUBSET interior (t:real^2->bool)` THEN SET_TAC[];
          ALL_TAC] THEN
        MATCH_MP_TAC(TAUT `~p ==> p ==> q`) THEN
        MATCH_MP_TAC(ASSUME `!x:real^2. x IN relative_frontier t ==> ~(x IN interior t)`) THEN
        ASM_REWRITE_TAC[];
        ASM_CASES_TAC `r:real = l2` THENL
         [DISJ2_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "int2" (MP_TAC o SPEC `r:real`) THEN
        ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
        FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th -> is_eq(concl th) && lhs(concl th) = `x:real^2`)) THEN
        MATCH_MP_TAC(TAUT `~p ==> p ==> q`) THEN
        MATCH_MP_TAC(ASSUME `!x:real^2. x IN relative_frontier t ==> ~(x IN interior t)`) THEN
        ASM_REWRITE_TAC[]];
      STRIP_TAC THEN ASM_REWRITE_TAC[] THENL
       [CONJ_TAC THENL [ALL_TAC; DISJ1_TAC THEN EXISTS_TAC `l1:real` THEN
                                 REWRITE_TAC[REAL_LE_REFL] THEN ASM_REAL_ARITH_TAC];
        CONJ_TAC THENL [ALL_TAC; DISJ2_TAC THEN DISJ2_TAC THEN EXISTS_TAC `l2:real` THEN
                                 REWRITE_TAC[REAL_LE_REFL] THEN ASM_REAL_ARITH_TAC]] THEN
      MAP_EVERY EXPAND_TAC ["v1"; "v2"] THEN
      REWRITE_TAC[moi_s5c_k12; IN_ELIM_THM; VECTOR_MUL_COMPONENT; VECTOR_2] THEN
      ASM_REAL_ARITH_TAC]]);;

(* The rotation of order three permuting the vertices of moi_s5c_tri.        *)

let MOI_S5C_ROT_BASIC = prove
 (`linear moi_s5c_rot /\ linear moi_s5c_irot /\
   (!x. moi_s5c_rot (moi_s5c_irot x) = x) /\ (!x. moi_s5c_irot (moi_s5c_rot x) = x)`,
  REWRITE_TAC[linear; moi_s5c_rot; moi_s5c_irot; CART_EQ; DIMINDEX_2; FORALL_2;
              VECTOR_2; VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT] THEN
  REPEAT CONJ_TAC THEN REPEAT GEN_TAC THEN REAL_ARITH_TAC);;

let MOI_S5C_IMAGE_ROT = prove
 (`!s. IMAGE moi_s5c_rot s = {y | moi_s5c_irot y IN s}`,
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM] THEN
  MESON_TAC[MOI_S5C_ROT_BASIC]);;

let MOI_S5C_ROT_FACTS = prove
 (`moi_s5c_rot (vector[-- &1;-- &1]) = vector[&2;-- &1] /\
   moi_s5c_rot (vector[&2;-- &1]) = vector[-- &1;&2] /\
   moi_s5c_rot (vector[-- &1;&2]) = vector[-- &1;-- &1] /\
   IMAGE moi_s5c_rot moi_s5c_k12 = moi_s5c_k23 /\
   IMAGE moi_s5c_rot moi_s5c_k23 = moi_s5c_k31 /\
   IMAGE moi_s5c_rot moi_s5c_k31 = moi_s5c_k12 /\
   IMAGE moi_s5c_rot moi_s5c_tri = moi_s5c_tri /\
   IMAGE moi_s5c_rot moi_s5c_tri2 = moi_s5c_tri2`,
  REWRITE_TAC[MOI_S5C_IMAGE_ROT] THEN
  REWRITE_TAC[moi_s5c_rot; moi_s5c_irot; moi_s5c_k12; moi_s5c_k23; moi_s5c_k31;
              moi_s5c_tri; moi_s5c_tri2; EXTENSION; IN_ELIM_THM; CART_EQ;
              DIMINDEX_2; FORALL_2; VECTOR_2] THEN
  CONV_TAC REAL_RAT_REDUCE_CONV THEN REPEAT CONJ_TAC THEN GEN_TAC THEN REAL_ARITH_TAC);;

let moi_s5c_piece_ok = new_definition
 `moi_s5c_piece_ok (k:real^2->bool) u w <=>
    !t. &2 simplex t /\ moi_s5c_tri SUBSET interior t
        ==> ?f g. pl_homeomorphism (t INTER k,moi_s5c_tri2 INTER k) (f,g) /\
                  (!x. x IN segment[u,w] ==> f x = x) /\
                  (!r. &1 <= r /\ r <= moi_s5c_lam t u
                       ==> f(r % u) = (&1 + (r - &1) / (moi_s5c_lam t u - &1)) % u) /\
                  (!r. &1 <= r /\ r <= moi_s5c_lam t w
                       ==> f(r % w) = (&1 + (r - &1) / (moi_s5c_lam t w - &1)) % w) /\
                  IMAGE f (relative_frontier t INTER k) = segment[&2 % u,&2 % w]`;;

let MOI_S5C_LAM_LINEAR = prove
 (`!(l:real^N->real^N) s v.
     linear l /\ (!x y. l x = l y ==> x = y)
     ==> moi_s5c_lam (IMAGE l s) (l v) = moi_s5c_lam s v`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[moi_s5c_lam] THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `r:real` THEN
  MP_TAC(ISPECL [`l:real^N->real^N`; `s:real^N->bool`]
    RELATIVE_FRONTIER_INJECTIVE_LINEAR_IMAGE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  FIRST_ASSUM(fun th -> REWRITE_TAC[GSYM(MATCH_MP LINEAR_CMUL th)]) THEN
  AP_TERM_TAC THEN REWRITE_TAC[IN_IMAGE] THEN ASM_MESON_TAC[]);;

let MOI_S5C_ROT_INJ = prove
 (`(!x y. moi_s5c_rot x = moi_s5c_rot y ==> x = y) /\
   (!x y. moi_s5c_irot x = moi_s5c_irot y ==> x = y) /\
   (!s. IMAGE moi_s5c_irot (IMAGE moi_s5c_rot s) = s) /\
   (!s. IMAGE moi_s5c_rot (IMAGE moi_s5c_irot s) = s)`,
  REWRITE_TAC[GSYM IMAGE_o; o_DEF; MOI_S5C_ROT_BASIC; IMAGE_ID] THEN
  MESON_TAC[MOI_S5C_ROT_BASIC]);;

let MOI_S5C_ROT_PLH = prove
 (`!x:real^2->bool.
     polytope x
     ==> pl_homeomorphism (x,IMAGE moi_s5c_rot x) (moi_s5c_rot,moi_s5c_irot)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC HOMEOMORPHISM_IMP_PL_HOMEOMORPHISM THEN
  ASM_SIMP_TAC[MOI_S5C_PL_LINEAR; LOCALLY_POLYHEDRAL_POLYTOPE; MOI_S5C_ROT_BASIC] THEN
  REWRITE_TAC[homeomorphism] THEN
  SIMP_TAC[LINEAR_CONTINUOUS_ON; MOI_S5C_ROT_BASIC] THEN
  REWRITE_TAC[MOI_S5C_ROT_INJ; FORALL_IN_IMAGE] THEN MESON_TAC[MOI_S5C_ROT_BASIC]);;

let MOI_S5C_PIECE_ROT = prove
 (`!k u w. moi_s5c_piece_ok k u w /\ polyhedron k
           ==> moi_s5c_piece_ok (IMAGE moi_s5c_rot k) (moi_s5c_rot u) (moi_s5c_rot w)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[moi_s5c_piece_ok] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pk") ASSUME_TAC) THEN
  X_GEN_TAC `t:real^2->bool` THEN STRIP_TAC THEN
  MP_TAC MOI_S5C_ROT_BASIC THEN MP_TAC MOI_S5C_ROT_INJ THEN
  MP_TAC MOI_S5C_ROT_FACTS THEN REWRITE_TAC[IMP_CONJ] THEN
  REPEAT DISCH_TAC THEN
  USE_THEN "pk" (MP_TAC o SPEC `IMAGE moi_s5c_irot t`) THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`moi_s5c_irot`; `t:real^2->bool`; `&2:int`] SIMPLEX_LINEAR_IMAGE_EQ) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`moi_s5c_irot`; `t:real^2->bool`] INTERIOR_INJECTIVE_LINEAR_IMAGE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[SUBSET; IN_IMAGE] THEN X_GEN_TAC `x:real^2` THEN DISCH_TAC THEN
    EXISTS_TAC `moi_s5c_rot x` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(SET_RULE `!s t (y:real^2). s SUBSET t /\ y IN s ==> y IN t`) THEN
    EXISTS_TAC `moi_s5c_tri` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `IMAGE moi_s5c_rot moi_s5c_tri = moi_s5c_tri` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[IN_IMAGE] THEN
    EXISTS_TAC `x:real^2` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ALL_TAC THEN
  REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  MAP_EVERY X_GEN_TAC [`f:real^2->real^2`; `g:real^2->real^2`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `polytope (IMAGE moi_s5c_irot t INTER (k:real^2->bool)) /\
                polytope (moi_s5c_tri2 INTER (k:real^2->bool))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC POLYTOPE_INTER_POLYHEDRON THEN
    ASM_REWRITE_TAC[MOI_S5C_TRI_FACTS] THEN MATCH_MP_TAC POLYTOPE_LINEAR_IMAGE THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[SIMPLEX_IMP_POLYTOPE];
    ALL_TAC] THEN
  SUBGOAL_THEN `t INTER IMAGE moi_s5c_rot k =
                IMAGE moi_s5c_rot (IMAGE moi_s5c_irot t INTER k) /\
                moi_s5c_tri2 INTER IMAGE moi_s5c_rot k =
                IMAGE moi_s5c_rot (moi_s5c_tri2 INTER k) /\
                relative_frontier t INTER IMAGE moi_s5c_rot k =
                IMAGE moi_s5c_rot (relative_frontier (IMAGE moi_s5c_irot t) INTER k)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`moi_s5c_irot`; `t:real^2->bool`]
      RELATIVE_FRONTIER_INJECTIVE_LINEAR_IMAGE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    SUBGOAL_THEN `!s s':real^2->bool. IMAGE moi_s5c_rot (s INTER s') =
                                      IMAGE moi_s5c_rot s INTER IMAGE moi_s5c_rot s'`
    (fun th -> REWRITE_TAC[th]) THENL
     [REPEAT GEN_TAC THEN MATCH_MP_TAC IMAGE_INTER_INJ THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ASSUME `t INTER IMAGE moi_s5c_rot k =
                IMAGE moi_s5c_rot (IMAGE moi_s5c_irot t INTER k)`;
              ASSUME `moi_s5c_tri2 INTER IMAGE moi_s5c_rot k =
                IMAGE moi_s5c_rot (moi_s5c_tri2 INTER k)`;
              ASSUME `relative_frontier t INTER IMAGE moi_s5c_rot k =
                IMAGE moi_s5c_rot (relative_frontier (IMAGE moi_s5c_irot t) INTER k)`] THEN
  MAP_EVERY EXISTS_TAC [`moi_s5c_rot o (f:real^2->real^2) o moi_s5c_irot`;
                        `(moi_s5c_rot o (g:real^2->real^2)) o moi_s5c_irot`] THEN
  SUBGOAL_THEN `moi_s5c_lam t (moi_s5c_rot u) = moi_s5c_lam (IMAGE moi_s5c_irot t) u /\
                moi_s5c_lam t (moi_s5c_rot w) = moi_s5c_lam (IMAGE moi_s5c_irot t) w`
  (fun th -> REWRITE_TAC[th]) THENL
   [CONJ_TAC THEN
    GEN_REWRITE_TAC (LAND_CONV o LAND_CONV)
      [SYM(SPEC `t:real^2->bool` (ASSUME `!s. IMAGE moi_s5c_rot (IMAGE moi_s5c_irot s) = s`))] THEN
    MATCH_MP_TAC MOI_S5C_LAM_LINEAR THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[o_THM] THEN
  SUBGOAL_THEN `!r v. moi_s5c_irot (r % moi_s5c_rot v) = r % v /\
                      moi_s5c_rot (r % v) = r % moi_s5c_rot v`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN
    REWRITE_TAC[MATCH_MP LINEAR_CMUL (CONJUNCT1(CONJUNCT2 MOI_S5C_ROT_BASIC));
                MATCH_MP LINEAR_CMUL (CONJUNCT1 MOI_S5C_ROT_BASIC)] THEN
    REWRITE_TAC[MOI_S5C_ROT_BASIC];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
    EXISTS_TAC `moi_s5c_tri2 INTER (k:real^2->bool)` THEN
    ASM_SIMP_TAC[MOI_S5C_ROT_PLH] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
    EXISTS_TAC `IMAGE moi_s5c_irot t INTER (k:real^2->bool)` THEN
    ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN
    ASM_SIMP_TAC[MOI_S5C_ROT_PLH];
    REWRITE_TAC[MATCH_MP CLOSED_SEGMENT_LINEAR_IMAGE (CONJUNCT1 MOI_S5C_ROT_BASIC)] THEN
    REWRITE_TAC[FORALL_IN_IMAGE] THEN ASM_SIMP_TAC[];
    ASM_SIMP_TAC[];
    ASM_SIMP_TAC[];
    SUBGOAL_THEN
     `IMAGE (moi_s5c_rot o (f:real^2->real^2) o moi_s5c_irot)
        (IMAGE moi_s5c_rot (relative_frontier (IMAGE moi_s5c_irot t) INTER k)) =
      IMAGE moi_s5c_rot (IMAGE f (relative_frontier (IMAGE moi_s5c_irot t) INTER k))`
    SUBST1_TAC THENL
     [REWRITE_TAC[GSYM IMAGE_o] THEN MATCH_MP_TAC MOI_S5C_IMAGE_EQ THEN
      ASM_REWRITE_TAC[o_THM];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM(MATCH_MP CLOSED_SEGMENT_LINEAR_IMAGE (CONJUNCT1 MOI_S5C_ROT_BASIC))] THEN
    ASM_REWRITE_TAC[]]);;

let MOI_S5C_PIECES_OK = prove
 (`moi_s5c_piece_ok moi_s5c_k12 (vector[-- &1;-- &1]) (vector[&2;-- &1]) /\
   moi_s5c_piece_ok moi_s5c_k23 (vector[&2;-- &1]) (vector[-- &1;&2]) /\
   moi_s5c_piece_ok moi_s5c_k31 (vector[-- &1;&2]) (vector[-- &1;-- &1])`,
  SUBGOAL_THEN `moi_s5c_piece_ok moi_s5c_k12 (vector[-- &1;-- &1]) (vector[&2;-- &1])`
  ASSUME_TAC THENL
   [REWRITE_TAC[moi_s5c_piece_ok; MOI_S5C_PIECE12_MAP]; ALL_TAC] THEN
  SUBGOAL_THEN `polyhedron moi_s5c_k23 /\ polyhedron moi_s5c_k12` STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[MOI_S5C_K12_POLYHEDRON] THEN
    REWRITE_TAC[GSYM(CONJUNCT1(CONJUNCT2(CONJUNCT2(CONJUNCT2 MOI_S5C_ROT_FACTS))))] THEN
    MATCH_MP_TAC POLYHEDRON_LINEAR_IMAGE THEN
    REWRITE_TAC[MOI_S5C_ROT_BASIC; MOI_S5C_K12_POLYHEDRON];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`moi_s5c_k12`; `vector[-- &1;-- &1]:real^2`; `vector[&2;-- &1]:real^2`]
      MOI_S5C_PIECE_ROT);
    MP_TAC(ISPECL [`moi_s5c_k23`; `vector[&2;-- &1]:real^2`; `vector[-- &1;&2]:real^2`]
      MOI_S5C_PIECE_ROT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`moi_s5c_k12`; `vector[-- &1;-- &1]:real^2`; `vector[&2;-- &1]:real^2`]
        MOI_S5C_PIECE_ROT) THEN
      ASM_REWRITE_TAC[MOI_S5C_ROT_FACTS];
      ALL_TAC]] THEN
  ASM_REWRITE_TAC[MOI_S5C_ROT_FACTS]);;

(* ------------------------------------------------------------------------- *)
(* Restriction of PL homeomorphisms, PL homeomorphisms between PL            *)
(* spheres, the triangle gauge and the standard triangular annulus.         *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_PLH_RESTRICT = prove
 (`!(s:real^M->bool) (t:real^N->bool) f g s'.
     pl_homeomorphism (s,t) (f,g) /\ s' SUBSET s /\ locally_polyhedral s'
     ==> pl_homeomorphism (s',IMAGE f s') (f,g)`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 MP_TAC STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[pl_homeomorphism] THEN STRIP_TAC THEN
  SUBGOAL_THEN `homeomorphism (s',IMAGE f s') (f:real^M->real^N,g)` ASSUME_TAC THENL
   [MATCH_MP_TAC HOMEOMORPHISM_OF_SUBSETS THEN
    MAP_EVERY EXISTS_TAC [`s:real^M->bool`; `t:real^N->bool`] THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `IMAGE (f:real^M->real^N) s` THEN
    ASM_SIMP_TAC[IMAGE_SUBSET] THEN ASM_MESON_TAC[homeomorphism; SUBSET_REFL];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `pl_map_on s' (f:real^M->real^N)` ASSUME_TAC THENL
   [MATCH_MP_TAC PL_MAP_ON_SUBSET THEN EXISTS_TAC `s:real^M->bool` THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC PL_MAP_ON_HOMEOMORPHISM_INVERSE THEN
    MAP_EVERY EXISTS_TAC [`s':real^M->bool`; `f:real^M->real^N`] THEN
    ASM_REWRITE_TAC[]]);;

let MOI_S5C_SPHERE_PLH = prove
 (`!n (s:real^M->bool) (t:real^N->bool).
     pl_sphere n s /\ pl_sphere n t ==> ?f g. pl_homeomorphism (s,t) (f,g)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_sphere] THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (X_CHOOSE_THEN `k1:real^M->bool` (X_CHOOSE_THEN `f1:real^M->real^M`
     (X_CHOOSE_THEN `g1:real^M->real^M` STRIP_ASSUME_TAC)))
   (X_CHOOSE_THEN `k2:real^N->bool` (X_CHOOSE_THEN `f2:real^N->real^N`
     (X_CHOOSE_THEN `g2:real^N->real^N` STRIP_ASSUME_TAC)))) THEN
  MP_TAC(ISPECL [`k1:real^M->bool`; `k2:real^N->bool`; `&(n + 1):int`]
    MOI_FM3_SIMPLEX_PLH) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:real^M->real^N` (X_CHOOSE_THEN `q:real^N->real^M`
    STRIP_ASSUME_TAC)) THEN
  EXISTS_TAC `(f2:real^N->real^N) o ((p:real^M->real^N) o (g1:real^M->real^M))` THEN
  EXISTS_TAC `((f1:real^M->real^M) o (q:real^N->real^M)) o (g2:real^N->real^N)` THEN
  MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
  EXISTS_TAC `relative_frontier(k2:real^N->bool)` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
  EXISTS_TAC `relative_frontier(k1:real^M->bool)` THEN ASM_REWRITE_TAC[] THEN
  ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN ASM_REWRITE_TAC[]);;

(* The gauge of the standard triangle: tri = gauge <= 1, tri2 = gauge <= 2. *)

let moi_s5c_gam = new_definition
 `moi_s5c_gam (x:real^2) = max (--(x$1)) (max (--(x$2)) (x$1 + x$2))`;;

let MOI_S5C_GAM_FACTS = prove
 (`(!x:real^2. x IN moi_s5c_tri <=> moi_s5c_gam x <= &1) /\
   (!x:real^2. x IN moi_s5c_tri2 <=> moi_s5c_gam x <= &2) /\
   (!x:real^2. x IN interior moi_s5c_tri <=> moi_s5c_gam x < &1) /\
   (!x:real^2. x IN interior moi_s5c_tri2 <=> moi_s5c_gam x < &2) /\
   (!x:real^2. x IN relative_frontier moi_s5c_tri <=> moi_s5c_gam x = &1) /\
   (!x:real^2. x IN relative_frontier moi_s5c_tri2 <=> moi_s5c_gam x = &2) /\
   (!r x:real^2. &0 <= r ==> moi_s5c_gam (r % x) = r * moi_s5c_gam x)`,
  SUBGOAL_THEN
   `(!x:real^2. x IN moi_s5c_tri <=> moi_s5c_gam x <= &1) /\
    (!x:real^2. x IN moi_s5c_tri2 <=> moi_s5c_gam x <= &2) /\
    (!x:real^2. x IN interior moi_s5c_tri <=> moi_s5c_gam x < &1) /\
    (!x:real^2. x IN interior moi_s5c_tri2 <=> moi_s5c_gam x < &2)`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[MOI_S5C_TRI_INTERIOR; MOI_S5C_TRI2_INTERIOR; moi_s5c_tri;
                moi_s5c_tri2; IN_ELIM_THM; moi_s5c_gam] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `relative_frontier moi_s5c_tri = moi_s5c_tri DIFF interior moi_s5c_tri /\
                relative_frontier moi_s5c_tri2 = moi_s5c_tri2 DIFF interior moi_s5c_tri2`
  (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[relative_frontier] THEN
    SUBGOAL_THEN `~(interior moi_s5c_tri = {}) /\ ~(interior moi_s5c_tri2 = {})`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
      EXISTS_TAC `vec 0:real^2` THEN
      ASM_REWRITE_TAC[moi_s5c_gam; VEC_COMPONENT] THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    ASM_SIMP_TAC[RELATIVE_INTERIOR_NONEMPTY_INTERIOR] THEN
    MP_TAC MOI_S5C_TRI_FACTS THEN STRIP_TAC THEN
    ASM_SIMP_TAC[CLOSURE_CLOSED; COMPACT_IMP_CLOSED];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[IN_DIFF] THEN
  REPEAT CONJ_TAC THENL
   [REAL_ARITH_TAC; REAL_ARITH_TAC;
    REPEAT STRIP_TAC THEN
    REWRITE_TAC[moi_s5c_gam; VECTOR_MUL_COMPONENT; GSYM REAL_ADD_LDISTRIB;
                REAL_ARITH `--(r * x) = r * --x`] THEN
    ASM_SIMP_TAC[MOI_S5C_REAL_MAX_LMUL]]);;

(* The standard triangular annulus tri2 - int tri is a PL annulus with ends *)
(* rf tri and rf tri2: the cone extension (from 0) of a PL homeomorphism of *)
(* rf Q2 onto rf tri2 carries the square gauge to the triangle gauge.       *)

let MOI_S5C_STD_ANN = prove
 (`pl_annulus_with_ends (moi_s5c_tri2 DIFF interior moi_s5c_tri)
     (relative_frontier moi_s5c_tri) (relative_frontier moi_s5c_tri2)`,
  MP_TAC MOI_S5C_TRI_FACTS THEN STRIP_TAC THEN
  SUBGOAL_THEN `(vec 0:real^2) IN interior moi_s5c_tri2` ASSUME_TAC THENL
   [REWRITE_TAC[MOI_S5C_GAM_FACTS; moi_s5c_gam; VEC_COMPONENT] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pl_sphere 1 (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]):real^2->bool) /\
    pl_sphere 1 (relative_frontier moi_s5c_tri2)`
  MP_TAC THENL
   [CONJ_TAC THEN
    MATCH_MP_TAC(REWRITE_RULE[DIMINDEX_2; ARITH_RULE `2 - 1 = 1`]
      (INST_TYPE [`:2`,`:N`] MOI_S5C_STAR_RF0)) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[POLYTOPE_INTERVAL; INTERIOR_CLOSED_INTERVAL; MOI_S5C_IN_SQO;
                VEC_COMPONENT] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o MATCH_MP MOI_S5C_SPHERE_PLH) THEN
  DISCH_THEN(X_CHOOSE_THEN `r2:real^2->real^2` (X_CHOOSE_TAC `r2':real^2->real^2`)) THEN
  SUBGOAL_THEN
   `~((vec 0:real^2) IN relative_frontier moi_s5c_tri2) /\
    (!x y. x IN relative_frontier moi_s5c_tri2 /\ y IN relative_frontier moi_s5c_tri2 /\
           y IN segment[vec 0,x] ==> y = x) /\
    UNIONS {segment[vec 0,x] | x IN relative_frontier moi_s5c_tri2} = moi_s5c_tri2`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_CONVEX_CONE_RF THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `~(interior moi_s5c_tri2 = {})` ASSUME_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN EXISTS_TAC `vec 0:real^2` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[RELATIVE_INTERIOR_NONEMPTY_INTERIOR] THEN
    DISCH_THEN(MP_TAC o AP_TERM `\s:real^2->bool. vector[&2;&0]:real^2 IN s`) THEN
    REWRITE_TAC[IN_SING; MOI_S5C_GAM_FACTS; moi_s5c_gam; VECTOR_2; CART_EQ;
                DIMINDEX_2; FORALL_2; VEC_COMPONENT] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(SPEC `&2` MOI_S5C_SQ_CONE_FACTS) THEN REWRITE_TAC[REAL_OF_NUM_LT; ARITH] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]):real^2->bool`;
                 `relative_frontier moi_s5c_tri2:real^2->bool`;
                 `vec 0:real^2`; `vec 0:real^2`;
                 `r2:real^2->real^2`; `r2':real^2->real^2`] MOI_CON_CONE_MAP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC MOI_S5C_SQ_RF_POLYHEDRON THEN REAL_ARITH_TAC;
      REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN EXISTS_TAC `vector[&2;&0]:real^2` THEN
      REWRITE_TAC[MOI_S5C_IN_RF2; VECTOR_2] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `cm = moi_con_conemap
                (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))
                (vec 0:real^2) (vec 0:real^2) r2` THEN
  ABBREV_TAC `cm' = moi_con_conemap (relative_frontier moi_s5c_tri2)
                     (vec 0:real^2) (vec 0:real^2) r2'` THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `!x:real^2. x IN interval[--vector[&2;&2],vector[&2;&2]]
                ==> moi_s5c_gam (cm x) = max (abs(x$1)) (abs(x$2))`
  ASSUME_TAC THENL
   [X_GEN_TAC `x:real^2` THEN DISCH_TAC THEN
    SUBGOAL_THEN `x IN UNIONS {segment[vec 0:real^2,y] | y IN
                    relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])}`
    MP_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[MOI_CON_IN_CONE; VECTOR_ADD_LID; VECTOR_SUB_RZERO] THEN
    DISCH_THEN(X_CHOOSE_THEN `x0:real^2` (X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC)) THEN
    FIRST_X_ASSUM SUBST_ALL_TAC THEN
    MP_TAC(ISPECL [`relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]):real^2->bool`;
                   `vec 0:real^2`; `vec 0:real^2`;
                   `r2:real^2->real^2`; `x0:real^2`; `r:real`] MOI_CON_CONEMAP_EQ) THEN
    ASM_REWRITE_TAC[VECTOR_ADD_LID; VECTOR_SUB_RZERO] THEN DISCH_THEN SUBST1_TAC THEN
    SUBGOAL_THEN `max (abs((x0:real^2)$1)) (abs(x0$2)) = &2 /\
                  moi_s5c_gam ((r2:real^2->real^2) x0) = &2` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL [ASM_MESON_TAC[MOI_S5C_IN_RF2]; ALL_TAC] THEN
      SUBGOAL_THEN `(r2:real^2->real^2) x0 IN relative_frontier moi_s5c_tri2` MP_TAC THENL
       [SUBGOAL_THEN `IMAGE (r2:real^2->real^2)
                        (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])) =
                      relative_frontier moi_s5c_tri2` MP_TAC THENL
         [ASM_MESON_TAC[pl_homeomorphism; homeomorphism]; ALL_TAC] THEN
        REWRITE_TAC[EXTENSION; IN_IMAGE] THEN ASM_MESON_TAC[];
        REWRITE_TAC[MOI_S5C_GAM_FACTS]];
      ALL_TAC] THEN
    ASM_SIMP_TAC[MOI_S5C_N2_CMUL; MOI_S5C_GAM_FACTS];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (cm:real^2->real^2) (interval[--vector[&2;&2],vector[&2;&2]]) =
                moi_s5c_tri2 /\
                (!y. y IN moi_s5c_tri2
                     ==> cm' y IN interval[--vector[&2;&2],vector[&2;&2]] /\
                         (cm:real^2->real^2) (cm' y) = y)`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `pl_homeomorphism (interval [--vector [&2; &2],vector [&2; &2]],
                   moi_s5c_tri2) (cm:real^2->real^2,cm')` THEN
    REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!P. IMAGE (cm:real^2->real^2)
          {x | x IN interval[--vector[&2;&2],vector[&2;&2]] /\
               P(max (abs(x$1)) (abs(x$2)))} =
        {y | y IN moi_s5c_tri2 /\ P(moi_s5c_gam y)}`
  ASSUME_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM] THEN
    X_GEN_TAC `y:real^2` THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `x:real^2` STRIP_ASSUME_TAC) THEN
      ASM_SIMP_TAC[] THEN
      UNDISCH_TAC `IMAGE (cm:real^2->real^2) (interval[--vector[&2;&2],vector[&2;&2]]) =
                   moi_s5c_tri2` THEN
      REWRITE_TAC[EXTENSION; IN_IMAGE] THEN ASM_MESON_TAC[];
      STRIP_TAC THEN EXISTS_TAC `(cm':real^2->real^2) y` THEN
      SUBGOAL_THEN `max (abs(((cm':real^2->real^2) y)$1)) (abs((cm' y)$2)) =
                    moi_s5c_gam y`
      (fun th -> ASM_SIMP_TAC[th]) THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`interval[--vector[&2;&2],vector[&2;&2]]:real^2->bool`;
                 `moi_s5c_tri2:real^2->bool`;
                 `cm:real^2->real^2`; `cm':real^2->real^2`;
                 `interval[--vector[&2;&2],vector[&2;&2]] DIFF
                  interval(--vector[&1;&1],vector[&1;&1]):real^2->bool`]
         MOI_S5C_PLH_RESTRICT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[SUBSET_DIFF] THEN MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
    REWRITE_TAC[MOI_S5C_SQANN_POLYHEDRON];
    ALL_TAC] THEN
  DISCH_TAC THEN REWRITE_TAC[pl_annulus_with_ends] THEN
  MAP_EVERY EXISTS_TAC [`cm:real^2->real^2`; `cm':real^2->real^2`] THEN
  FIRST_X_ASSUM(fun th -> MP_TAC th) THEN
  FIRST_X_ASSUM(fun th -> MAP_EVERY (fun t -> MP_TAC(BETA_RULE(SPEC t th)))
     [`\r:real. &1 <= r`; `\r:real. r = &1`; `\r:real. r = &2`]) THEN
  SUBGOAL_THEN
   `interval[--vector[&2;&2],vector[&2;&2]] DIFF interval(--vector[&1;&1],vector[&1;&1]) =
    {x:real^2 | x IN interval[--vector[&2;&2],vector[&2;&2]] /\
                &1 <= max (abs(x$1)) (abs(x$2))} /\
    relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]) =
    {x:real^2 | x IN interval[--vector[&2;&2],vector[&2;&2]] /\
                max (abs(x$1)) (abs(x$2)) = &1} /\
    relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]) =
    {x:real^2 | x IN interval[--vector[&2;&2],vector[&2;&2]] /\
                max (abs(x$1)) (abs(x$2)) = &2} /\
    moi_s5c_tri2 DIFF interior moi_s5c_tri =
    {y | y IN moi_s5c_tri2 /\ &1 <= moi_s5c_gam y} /\
    relative_frontier moi_s5c_tri = {y | y IN moi_s5c_tri2 /\ moi_s5c_gam y = &1} /\
    relative_frontier moi_s5c_tri2 = {y | y IN moi_s5c_tri2 /\ moi_s5c_gam y = &2}`
  (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_DIFF; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO;
                MOI_S5C_IN_RF1; MOI_S5C_IN_RF2; MOI_S5C_GAM_FACTS] THEN
    REPEAT CONJ_TAC THEN GEN_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  REPEAT(DISCH_THEN SUBST1_TAC) THEN REWRITE_TAC[] THEN DISCH_THEN ACCEPT_TAC);;

let MOI_S5C_ANN_TRANSFER = prove
 (`!(a:real^M->bool) j0 j1 (a':real^N->bool) p q.
     pl_annulus_with_ends a j0 j1 /\ pl_homeomorphism (a,a') (p,q)
     ==> pl_annulus_with_ends a' (IMAGE p j0) (IMAGE p j1)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_annulus_with_ends] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `f:real^2->real^M`
    (X_CHOOSE_THEN `g:real^M->real^2` STRIP_ASSUME_TAC)) ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`(p:real^M->real^N) o (f:real^2->real^M)`;
                        `(g:real^M->real^2) o (q:real^N->real^M)`] THEN
  ASM_REWRITE_TAC[IMAGE_o] THEN MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
  EXISTS_TAC `a:real^M->bool` THEN ASM_REWRITE_TAC[]);;

(* Edges of the standard triangles in coordinates.                          *)

let MOI_S5C_TRI_EDGES = prove
 (`(!x:real^2. x IN segment[vector[&2;-- &1],vector[-- &1;&2]] <=>
               x$1 + x$2 = &1 /\ -- &1 <= x$1 /\ x$1 <= &2) /\
   (!x:real^2. x IN segment[vector[-- &1;&2],vector[-- &1;-- &1]] <=>
               x$1 = -- &1 /\ -- &1 <= x$2 /\ x$2 <= &2) /\
   (!x:real^2. x IN segment[&2 % vector[-- &1;-- &1],&2 % vector[&2;-- &1]] <=>
               x$2 = -- &2 /\ -- &2 <= x$1 /\ x$1 <= &4) /\
   (!x:real^2. x IN segment[&2 % vector[&2;-- &1],&2 % vector[-- &1;&2]] <=>
               x$1 + x$2 = &2 /\ -- &2 <= x$1 /\ x$1 <= &4) /\
   (!x:real^2. x IN segment[&2 % vector[-- &1;&2],&2 % vector[-- &1;-- &1]] <=>
               x$1 = -- &2 /\ -- &2 <= x$2 /\ x$2 <= &4)`,
  REPEAT CONJ_TAC THEN GEN_TAC THEN
  REWRITE_TAC[IN_SEGMENT; CART_EQ; DIMINDEX_2; FORALL_2;
    VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; VECTOR_2] THEN
  EQ_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  TRY ASM_REAL_ARITH_TAC THENL
   [EXISTS_TAC `(&2 - (x:real^2)$1) / &3`;
    EXISTS_TAC `(&2 - (x:real^2)$2) / &3`;
    EXISTS_TAC `((x:real^2)$1 + &2) / &6`;
    EXISTS_TAC `(&4 - (x:real^2)$1) / &6`;
    EXISTS_TAC `(&4 - (x:real^2)$2) / &6`] THEN
  ASM_REAL_ARITH_TAC);;

let MOI_S5C_RF_TRI_EDGES = prove
 (`relative_frontier moi_s5c_tri =
   segment[vector[-- &1;-- &1],vector[&2;-- &1]] UNION
   segment[vector[&2;-- &1],vector[-- &1;&2]] UNION
   segment[vector[-- &1;&2],vector[-- &1;-- &1]] /\
   relative_frontier moi_s5c_tri2 =
   segment[&2 % vector[-- &1;-- &1],&2 % vector[&2;-- &1]] UNION
   segment[&2 % vector[&2;-- &1],&2 % vector[-- &1;&2]] UNION
   segment[&2 % vector[-- &1;&2],&2 % vector[-- &1;-- &1]]`,
  REWRITE_TAC[EXTENSION; IN_UNION; MOI_S5C_GAM_FACTS; MOI_S5C_TRI_EDGES;
              MOI_S5C_SEG_V1V2; moi_s5c_gam] THEN
  CONJ_TAC THEN GEN_TAC THEN REAL_ARITH_TAC);;

let MOI_S5C_SPOKE_IMAGE = prove
 (`!(f:real^N->real^N) v lam.
     &1 < lam /\
     (!r. &1 <= r /\ r <= lam ==> f(r % v) = (&1 + (r - &1) / (lam - &1)) % v)
     ==> IMAGE f (segment[lam % v,v]) = segment[&2 % v,v]`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`v:real^N`; `lam:real`] MOI_S5C_SEG_RAY) THEN
  MP_TAC(ISPECL [`v:real^N`; `&2`] MOI_S5C_SEG_RAY) THEN
  ANTS_TAC THENL [REAL_ARITH_TAC; DISCH_TAC] THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; DISCH_TAC] THEN
  ASM_REWRITE_TAC[EXTENSION; IN_IMAGE] THEN X_GEN_TAC `y:real^N` THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `x:real^N` (CONJUNCTS_THEN2 SUBST1_TAC MP_TAC)) THEN
    DISCH_THEN(X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC) THEN
    ASM_SIMP_TAC[] THEN EXISTS_TAC `&1 + (r - &1) / (lam - &1)` THEN
    REWRITE_TAC[] THEN
    SUBGOAL_THEN `&0 <= (r - &1) / (lam - &1) /\ (r - &1) / (lam - &1) <= &1`
    MP_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_DIV THEN ASM_REAL_ARITH_TAC;
        ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_SUB_LT] THEN ASM_REAL_ARITH_TAC];
      REAL_ARITH_TAC];
    DISCH_THEN(X_CHOOSE_THEN `s:real` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `(&1 + (s - &1) * (lam - &1)) % (v:real^N)` THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `&1 <= &1 + (s - &1) * (lam - &1) /\
                    &1 + (s - &1) * (lam - &1) <= lam` STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MATCH_MP_TAC(REAL_ARITH `&0 <= x ==> &1 <= &1 + x`) THEN
          MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
          MATCH_MP_TAC(REAL_ARITH `x * (lam - &1) <= &1 * (lam - &1) ==>
                                   &1 + x * (lam - &1) <= lam`) THEN
          MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REAL_ARITH_TAC];
        ALL_TAC] THEN
      ASM_SIMP_TAC[] THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      SUBGOAL_THEN `~(lam - &1 = &0)` ASSUME_TAC THENL
       [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      ASM_SIMP_TAC[REAL_FIELD `~(l = &0) ==> ((&1 + x * l) - &1) / l = x`] THEN
      REAL_ARITH_TAC;
      EXISTS_TAC `&1 + (s - &1) * (lam - &1)` THEN REWRITE_TAC[] THEN CONJ_TAC THENL
       [MATCH_MP_TAC(REAL_ARITH `&0 <= x ==> &1 <= &1 + x`) THEN
        MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC(REAL_ARITH `x * (lam - &1) <= &1 * (lam - &1) ==>
                                 &1 + x * (lam - &1) <= lam`) THEN
        MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REAL_ARITH_TAC]]]);;

let MOI_S5C_T_SPOKE = prove
 (`!(t:real^N->bool) v.
     convex t /\ compact t /\ vec 0 IN interior t /\ ~(v = vec 0) /\
     &1 <= moi_s5c_lam t v
     ==> {x | x IN t /\ ?r. &1 <= r /\ x = r % v} = segment[moi_s5c_lam t v % v,v]`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`t:real^N->bool`; `v:real^N`] MOI_S5C_LAM) THEN ASM_REWRITE_TAC[] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`v:real^N`; `moi_s5c_lam (t:real^N->bool) v`] MOI_S5C_SEG_RAY) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  ASM_REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN GEN_TAC THEN EQ_TAC THENL
   [DISCH_THEN(CONJUNCTS_THEN2 MP_TAC (X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC)) THEN
    FIRST_X_ASSUM SUBST_ALL_TAC THEN
    ASM_SIMP_TAC[REAL_ARITH `&1 <= r ==> &0 <= r`] THEN DISCH_TAC THEN
    EXISTS_TAC `r:real` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC) THEN
    FIRST_X_ASSUM SUBST_ALL_TAC THEN
    ASM_SIMP_TAC[REAL_ARITH `&1 <= r ==> &0 <= r`] THEN
    EXISTS_TAC `r:real` THEN ASM_REWRITE_TAC[]]);;

let MOI_S5C_K_CLOSED = prove
 (`closed moi_s5c_k12 /\ closed moi_s5c_k23 /\ closed moi_s5c_k31`,
  SUBGOAL_THEN `closed moi_s5c_k12` ASSUME_TAC THENL
   [MATCH_MP_TAC POLYHEDRON_IMP_CLOSED THEN REWRITE_TAC[MOI_S5C_K12_POLYHEDRON];
    ALL_TAC] THEN
  MP_TAC(ISPEC `moi_s5c_rot` CLOSED_INJECTIVE_LINEAR_IMAGE) THEN
  REWRITE_TAC[MOI_S5C_ROT_BASIC; MOI_S5C_ROT_INJ] THEN DISCH_TAC THEN
  SUBGOAL_THEN `closed (IMAGE moi_s5c_rot moi_s5c_k12) /\
                closed (IMAGE moi_s5c_rot (IMAGE moi_s5c_rot moi_s5c_k12))` MP_TAC THENL
   [ASM_SIMP_TAC[]; REWRITE_TAC[MOI_S5C_ROT_FACTS] THEN ASM_SIMP_TAC[]]);;

(* Pasting the three cone pieces: a PL homeomorphism of t - int tri onto    *)
(* tri2 - int tri, the identity on rf tri, carrying rf t onto rf tri2.     *)

let MOI_S5C_NT0_MAP = prove
 (`!t:real^2->bool.
     &2 simplex t /\ moi_s5c_tri SUBSET interior t
     ==> ?G G'. pl_homeomorphism (t DIFF interior moi_s5c_tri,
                                  moi_s5c_tri2 DIFF interior moi_s5c_tri) (G,G') /\
                (!x. x IN relative_frontier moi_s5c_tri ==> G x = x) /\
                IMAGE G (relative_frontier t) = relative_frontier moi_s5c_tri2`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `convex (t:real^2->bool) /\ compact t /\ closed t` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[SIMPLEX_IMP_CONVEX; SIMPLEX_IMP_COMPACT; SIMPLEX_IMP_CLOSED];
    ALL_TAC] THEN
  MP_TAC MOI_S5C_TRI_FACTS THEN STRIP_TAC THEN
  SUBGOAL_THEN `(vec 0:real^2) IN interior t` ASSUME_TAC THENL
   [ASM_MESON_TAC[SUBSET; INTERIOR_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `vector[-- &1;-- &1] IN interior t /\ vector[&2;-- &1] IN interior t /\
                vector[-- &1;&2] IN interior (t:real^2->bool)` STRIP_ASSUME_TAC THENL
   [MP_TAC(ASSUME `moi_s5c_tri SUBSET interior (t:real^2->bool)`) THEN
    REWRITE_TAC[SUBSET] THEN DISCH_THEN(fun th -> REPEAT CONJ_TAC THEN MATCH_MP_TAC th) THEN
    REWRITE_TAC[MOI_S5C_GAM_FACTS; moi_s5c_gam; VECTOR_2] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&1 < moi_s5c_lam t (vector[-- &1;-- &1]) /\
                &1 < moi_s5c_lam t (vector[&2;-- &1]) /\
                &1 < moi_s5c_lam (t:real^2->bool) (vector[-- &1;&2])` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_LAM_GT1 THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2; VEC_COMPONENT] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!s:real^2->bool. convex s /\ compact s /\ vec 0 IN interior s /\
       &1 <= moi_s5c_lam s (vector[-- &1;-- &1]) /\
       &1 <= moi_s5c_lam s (vector[&2;-- &1]) /\
       &1 <= moi_s5c_lam s (vector[-- &1;&2])
       ==> (s INTER moi_s5c_k12) INTER (s INTER moi_s5c_k23) =
           segment[moi_s5c_lam s (vector[&2;-- &1]) % vector[&2;-- &1],vector[&2;-- &1]] /\
           (s INTER moi_s5c_k23) INTER (s INTER moi_s5c_k31) =
           segment[moi_s5c_lam s (vector[-- &1;&2]) % vector[-- &1;&2],vector[-- &1;&2]] /\
           (s INTER moi_s5c_k31) INTER (s INTER moi_s5c_k12) =
           segment[moi_s5c_lam s (vector[-- &1;-- &1]) % vector[-- &1;-- &1],
                   vector[-- &1;-- &1]]`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    REWRITE_TAC[SET_RULE `(s INTER a) INTER (s INTER b) =
                          {x:real^2 | x IN s /\ x IN a /\ x IN b}`] THEN
    REWRITE_TAC[MOI_S5C_K_INTERS] THEN REPEAT CONJ_TAC THEN
    MATCH_MP_TAC MOI_S5C_T_SPOKE THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2; VEC_COMPONENT] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `t:real^2->bool`) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `moi_s5c_tri2`) THEN
  ASM_SIMP_TAC[MOI_S5C_LAM_TRI2; REAL_LT_IMP_LE] THEN
  SUBGOAL_THEN `(vec 0:real^2) IN interior moi_s5c_tri2` ASSUME_TAC THENL
   [REWRITE_TAC[MOI_S5C_GAM_FACTS; moi_s5c_gam; VEC_COMPONENT] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[REAL_LE_REFL; REAL_ARITH `&1 <= &2`] THEN
  REPEAT STRIP_TAC THEN
  MP_TAC MOI_S5C_PIECES_OK THEN REWRITE_TAC[moi_s5c_piece_ok] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (MP_TAC o SPEC `t:real^2->bool`)
    (CONJUNCTS_THEN2 (MP_TAC o SPEC `t:real^2->bool`) (MP_TAC o SPEC `t:real^2->bool`))) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `f31:real^2->real^2` (X_CHOOSE_THEN `g31:real^2->real^2`
    STRIP_ASSUME_TAC)) THEN
  DISCH_THEN(X_CHOOSE_THEN `f23:real^2->real^2` (X_CHOOSE_THEN `g23:real^2->real^2`
    STRIP_ASSUME_TAC)) THEN
  DISCH_THEN(X_CHOOSE_THEN `f12:real^2->real^2` (X_CHOOSE_THEN `g12:real^2->real^2`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`t INTER moi_s5c_k12:real^2->bool`; `t INTER moi_s5c_k23:real^2->bool`;
                 `moi_s5c_tri2 INTER moi_s5c_k12:real^2->bool`;
                 `moi_s5c_tri2 INTER moi_s5c_k23:real^2->bool`;
                 `f12:real^2->real^2`; `g12:real^2->real^2`;
                 `f23:real^2->real^2`; `g23:real^2->real^2`]
         MOI_PL2_PL_HOMEOMORPHISM_UNION) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[CLOSED_INTER; MOI_S5C_K_CLOSED; COMPACT_IMP_CLOSED] THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL [`vector[&2;-- &1]:real^2`; `moi_s5c_lam (t:real^2->bool) (vector[&2;-- &1])`]
        MOI_S5C_SEG_RAY) THEN
      ANTS_TAC THENL [ASM_SIMP_TAC[REAL_LT_IMP_LE]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REPEAT STRIP_TAC THEN ASM_SIMP_TAC[];
      MATCH_MP_TAC MOI_S5C_SPOKE_IMAGE THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ABBREV_TAC `G1 = \x:real^2. if x IN t INTER moi_s5c_k12 then f12 x else f23 x:real^2` THEN
  ABBREV_TAC `G1' = \y:real^2. if y IN moi_s5c_tri2 INTER moi_s5c_k12 then g12 y
                               else g23 y:real^2` THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `(!x. x IN t INTER moi_s5c_k12 ==> (G1:real^2->real^2) x = f12 x) /\
                (!x. x IN t INTER moi_s5c_k23 ==> G1 x = f23 x)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "G1" THEN REWRITE_TAC[] THEN CONJ_TAC THENL
     [SIMP_TAC[]; ALL_TAC] THEN
    X_GEN_TAC `x:real^2` THEN DISCH_TAC THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `x IN (t INTER moi_s5c_k12) INTER (t INTER moi_s5c_k23)` MP_TAC THENL
     [UNDISCH_TAC `(x:real^2) IN t INTER moi_s5c_k12` THEN
      UNDISCH_TAC `(x:real^2) IN t INTER moi_s5c_k23` THEN
      REWRITE_TAC[IN_INTER] THEN SIMP_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`vector[&2;-- &1]:real^2`; `moi_s5c_lam (t:real^2->bool) (vector[&2;-- &1])`]
      MOI_S5C_SEG_RAY) THEN
    ANTS_TAC THENL [ASM_SIMP_TAC[REAL_LT_IMP_LE]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    STRIP_TAC THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^2. x IN ((t INTER moi_s5c_k12) UNION (t INTER moi_s5c_k23)) INTER
                             (t INTER moi_s5c_k31) ==> (G1:real^2->real^2) x = f31 x`
  ASSUME_TAC THENL
   [REWRITE_TAC[SET_RULE `((a:real^2->bool) UNION b) INTER c =
                          (c INTER a) UNION (b INTER c)`] THEN
X_GEN_TAC `x:real^2` THEN REWRITE_TAC[IN_UNION] THEN STRIP_TAC THENL
     [
      SUBGOAL_THEN `(x:real^2) IN t INTER moi_s5c_k12 /\
                    x IN segment[moi_s5c_lam (t:real^2->bool) (vector[-- &1;-- &1]) % vector[-- &1;-- &1],vector[-- &1;-- &1]]`
      STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN
        UNDISCH_TAC `(x:real^2) IN (t INTER moi_s5c_k31) INTER (t INTER moi_s5c_k12)` THENL
         [REWRITE_TAC[IN_INTER] THEN SIMP_TAC[]; ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      ASM_SIMP_TAC[] THEN
      UNDISCH_TAC `(x:real^2) IN segment[moi_s5c_lam (t:real^2->bool) (vector[-- &1;-- &1]) % vector[-- &1;-- &1],vector[-- &1;-- &1]]` THEN
      MP_TAC(ISPECL [`vector[-- &1;-- &1]:real^2`; `moi_s5c_lam (t:real^2->bool) (vector[-- &1;-- &1])`]
        MOI_S5C_SEG_RAY) THEN
      ANTS_TAC THENL [ASM_SIMP_TAC[REAL_LT_IMP_LE]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN ASM_SIMP_TAC[];
      SUBGOAL_THEN `(x:real^2) IN t INTER moi_s5c_k23 /\
                    x IN segment[moi_s5c_lam (t:real^2->bool) (vector[-- &1;&2]) % vector[-- &1;&2],vector[-- &1;&2]]`
      STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN
        UNDISCH_TAC `(x:real^2) IN (t INTER moi_s5c_k23) INTER (t INTER moi_s5c_k31)` THENL
         [REWRITE_TAC[IN_INTER] THEN SIMP_TAC[]; ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      ASM_SIMP_TAC[] THEN
      UNDISCH_TAC `(x:real^2) IN segment[moi_s5c_lam (t:real^2->bool) (vector[-- &1;&2]) % vector[-- &1;&2],vector[-- &1;&2]]` THEN
      MP_TAC(ISPECL [`vector[-- &1;&2]:real^2`; `moi_s5c_lam (t:real^2->bool) (vector[-- &1;&2])`]
        MOI_S5C_SEG_RAY) THEN
      ANTS_TAC THENL [ASM_SIMP_TAC[REAL_LT_IMP_LE]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`(t INTER moi_s5c_k12) UNION (t INTER moi_s5c_k23):real^2->bool`;
                 `t INTER moi_s5c_k31:real^2->bool`;
                 `(moi_s5c_tri2 INTER moi_s5c_k12) UNION
                  (moi_s5c_tri2 INTER moi_s5c_k23):real^2->bool`;
                 `moi_s5c_tri2 INTER moi_s5c_k31:real^2->bool`;
                 `G1:real^2->real^2`; `G1':real^2->real^2`;
                 `f31:real^2->real^2`; `g31:real^2->real^2`]
         MOI_PL2_PL_HOMEOMORPHISM_UNION) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[CLOSED_INTER; CLOSED_UNION; MOI_S5C_K_CLOSED; COMPACT_IMP_CLOSED] THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[SET_RULE `((a:real^2->bool) UNION b) INTER c =
                          (c INTER a) UNION (b INTER c)`] THEN
    REWRITE_TAC[IMAGE_UNION] THEN
      SUBGOAL_THEN
       `IMAGE (G1:real^2->real^2) ((t INTER moi_s5c_k31) INTER (t INTER moi_s5c_k12)) =
        IMAGE f12 ((t INTER moi_s5c_k31) INTER (t INTER moi_s5c_k12)) /\
        IMAGE G1 ((t INTER moi_s5c_k23) INTER (t INTER moi_s5c_k31)) =
        IMAGE f23 ((t INTER moi_s5c_k23) INTER (t INTER moi_s5c_k31))`
      (fun th -> REWRITE_TAC[th]) THENL
       [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_IMAGE_EQ THEN X_GEN_TAC `x:real^2` THEN
        REWRITE_TAC[IN_INTER] THEN STRIP_TAC THEN
        FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[IN_INTER];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN BINOP_TAC THEN MATCH_MP_TAC MOI_S5C_SPOKE_IMAGE THEN
      ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `G = \x:real^2. if x IN t INTER moi_s5c_k12 UNION t INTER moi_s5c_k23
                             then G1 x else f31 x:real^2` THEN
  ABBREV_TAC `G' = \y:real^2. if y IN moi_s5c_tri2 INTER moi_s5c_k12 UNION
                                      moi_s5c_tri2 INTER moi_s5c_k23
                              then G1' y else g31 y:real^2` THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `(!x. x IN t INTER moi_s5c_k12 ==> (G:real^2->real^2) x = f12 x) /\
                (!x. x IN t INTER moi_s5c_k23 ==> G x = f23 x) /\
                (!x. x IN t INTER moi_s5c_k31 ==> G x = f31 x)` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "G" THEN REWRITE_TAC[IN_UNION] THEN REPEAT CONJ_TAC THEN
    X_GEN_TAC `x:real^2` THEN DISCH_TAC THEN ASM_SIMP_TAC[] THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> is_forall(concl th) &&
      can (find_term (fun t -> t = `f31:real^2->real^2`)) (concl th) &&
      can (find_term (fun t -> t = `G1:real^2->real^2`)) (concl th))) THEN
    ASM_REWRITE_TAC[IN_INTER; IN_UNION] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[IN_INTER]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(t INTER moi_s5c_k12 UNION t INTER moi_s5c_k23) UNION t INTER moi_s5c_k31 =
                t DIFF interior moi_s5c_tri /\
                (moi_s5c_tri2 INTER moi_s5c_k12 UNION moi_s5c_tri2 INTER moi_s5c_k23) UNION
                moi_s5c_tri2 INTER moi_s5c_k31 = moi_s5c_tri2 DIFF interior moi_s5c_tri`
  (fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THENL
   [REWRITE_TAC[EXTENSION; IN_UNION; IN_INTER; IN_DIFF; MOI_S5C_K_COVER] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`G:real^2->real^2`; `G':real^2->real^2`] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `relative_frontier moi_s5c_tri SUBSET (t:real^2->bool)` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `moi_s5c_tri` THEN CONJ_TAC THENL
     [ASM_SIMP_TAC[relative_frontier; CLOSURE_CLOSED; COMPACT_IMP_CLOSED] THEN SET_TAC[];
      ASM_MESON_TAC[SUBSET_TRANS; INTERIOR_SUBSET]];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `x:real^2` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(x:real^2) IN t` ASSUME_TAC THENL [ASM SET_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `(x:real^2) IN relative_frontier moi_s5c_tri` THEN
    REWRITE_TAC[MOI_S5C_RF_TRI_EDGES; IN_UNION] THEN STRIP_TAC THENL
     [SUBGOAL_THEN `(x:real^2) IN t INTER moi_s5c_k12` (fun th -> ASM_SIMP_TAC[th]) THEN
      UNDISCH_TAC `(x:real^2) IN segment[vector[-- &1;-- &1],vector[&2;-- &1]]`;
      SUBGOAL_THEN `(x:real^2) IN t INTER moi_s5c_k23` (fun th -> ASM_SIMP_TAC[th]) THEN
      UNDISCH_TAC `(x:real^2) IN segment[vector[&2;-- &1],vector[-- &1;&2]]`;
      SUBGOAL_THEN `(x:real^2) IN t INTER moi_s5c_k31` (fun th -> ASM_SIMP_TAC[th]) THEN
      UNDISCH_TAC `(x:real^2) IN segment[vector[-- &1;&2],vector[-- &1;-- &1]]`] THEN
    ASM_REWRITE_TAC[IN_INTER; MOI_S5C_SEG_V1V2; MOI_S5C_TRI_EDGES; moi_s5c_k12;
                    moi_s5c_k23; moi_s5c_k31; IN_ELIM_THM] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `relative_frontier t =
                (relative_frontier t INTER moi_s5c_k12) UNION
                (relative_frontier t INTER moi_s5c_k23) UNION
                (relative_frontier (t:real^2->bool) INTER moi_s5c_k31)`
  SUBST1_TAC THENL
   [SUBGOAL_THEN `relative_frontier (t:real^2->bool) INTER interior moi_s5c_tri = {}`
    MP_TAC THENL
     [SUBGOAL_THEN `~(interior (t:real^2->bool) = {})` ASSUME_TAC THENL
       [ASM SET_TAC[]; ALL_TAC] THEN
      ASM_SIMP_TAC[relative_frontier; CLOSURE_CLOSED;
                   RELATIVE_INTERIOR_NONEMPTY_INTERIOR] THEN
      MP_TAC(ISPEC `moi_s5c_tri` INTERIOR_SUBSET) THEN ASM SET_TAC[];
      REWRITE_TAC[EXTENSION; IN_INTER; IN_UNION; NOT_IN_EMPTY] THEN
      MESON_TAC[MOI_S5C_K_COVER]];
    ALL_TAC] THEN
  REWRITE_TAC[IMAGE_UNION; MOI_S5C_RF_TRI_EDGES] THEN
  SUBGOAL_THEN `relative_frontier (t:real^2->bool) SUBSET t` ASSUME_TAC THENL
   [ASM_SIMP_TAC[relative_frontier; CLOSURE_CLOSED] THEN SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (G:real^2->real^2) (relative_frontier t INTER moi_s5c_k12) =
    IMAGE f12 (relative_frontier t INTER moi_s5c_k12) /\
    IMAGE G (relative_frontier t INTER moi_s5c_k23) =
    IMAGE f23 (relative_frontier t INTER moi_s5c_k23) /\
    IMAGE G (relative_frontier t INTER moi_s5c_k31) =
    IMAGE f31 (relative_frontier t INTER moi_s5c_k31)`
  (fun th -> ASM_REWRITE_TAC[th]) THEN
  REPEAT CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_IMAGE_EQ THEN
  X_GEN_TAC `x:real^2` THEN REWRITE_TAC[IN_INTER] THEN STRIP_TAC THEN
  FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[IN_INTER] THEN ASM SET_TAC[]);;

let MOI_S5C_NT0 = prove
 (`!t:real^2->bool.
     &2 simplex t /\ moi_s5c_tri SUBSET interior t
     ==> pl_annulus_with_ends (t DIFF interior moi_s5c_tri)
           (relative_frontier moi_s5c_tri) (relative_frontier t)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `t:real^2->bool` MOI_S5C_NT0_MAP) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `G:real^2->real^2` (X_CHOOSE_THEN `G':real^2->real^2`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC MOI_S5C_TRI_FACTS THEN STRIP_TAC THEN
  SUBGOAL_THEN `closed (t:real^2->bool)` ASSUME_TAC THENL
   [ASM_MESON_TAC[SIMPLEX_IMP_CLOSED]; ALL_TAC] THEN
  SUBGOAL_THEN `~(interior (t:real^2->bool) = {}) /\ ~(interior moi_s5c_tri = {})`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN EXISTS_TAC `vec 0:real^2` THEN
    ASM_MESON_TAC[SUBSET; INTERIOR_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN `relative_frontier moi_s5c_tri SUBSET t DIFF interior moi_s5c_tri /\
                relative_frontier t SUBSET t DIFF interior moi_s5c_tri`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[relative_frontier; CLOSURE_CLOSED; COMPACT_IMP_CLOSED;
                 RELATIVE_INTERIOR_NONEMPTY_INTERIOR] THEN
    MP_TAC(ISPEC `moi_s5c_tri` INTERIOR_SUBSET) THEN
    MP_TAC(ISPEC `t:real^2->bool` INTERIOR_SUBSET) THEN
    UNDISCH_TAC `moi_s5c_tri SUBSET interior (t:real^2->bool)` THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`moi_s5c_tri2 DIFF interior moi_s5c_tri:real^2->bool`;
                 `relative_frontier moi_s5c_tri:real^2->bool`;
                 `relative_frontier moi_s5c_tri2:real^2->bool`;
                 `t DIFF interior moi_s5c_tri:real^2->bool`;
                 `G':real^2->real^2`; `G:real^2->real^2`] MOI_S5C_ANN_TRANSFER) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[MOI_S5C_STD_ANN] THEN ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!u. u SUBSET t DIFF interior moi_s5c_tri
                    ==> IMAGE (G':real^2->real^2) (IMAGE G u) = u`
  ASSUME_TAC THENL
   [UNDISCH_TAC `pl_homeomorphism (t DIFF interior moi_s5c_tri,
                   moi_s5c_tri2 DIFF interior moi_s5c_tri) (G:real^2->real^2,G')` THEN
    REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (G:real^2->real^2) (relative_frontier moi_s5c_tri) =
                relative_frontier moi_s5c_tri`
  ASSUME_TAC THENL
   [UNDISCH_TAC `!x. x IN relative_frontier moi_s5c_tri ==> (G:real^2->real^2) x = x` THEN
    SET_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC EQ_IMP THEN BINOP_TAC THEN TRY AP_TERM_TAC THEN ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Affine normalisation of full-dimensional simplices, nested triangles      *)
(* and the planar annulus theorem (two nested PL circles bound a PL annulus).*)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_SIMPLEX_AFFINE_IMAGE = prove
 (`!n (l:real^N->real^N) y s.
     linear l /\ (!x y. l x = l y ==> x = y) /\ n simplex s
     ==> n simplex (IMAGE (\x. l x + y) s)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[simplex] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `c:real^N->bool` STRIP_ASSUME_TAC))) THEN
  EXISTS_TAC `IMAGE (\x:real^N. (l:real^N->real^N) x + y) c` THEN
  SUBGOAL_THEN `FINITE(c:real^N->bool)` ASSUME_TAC THENL
   [ASM_MESON_TAC[AFFINE_INDEPENDENT_IMP_FINITE]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN `IMAGE (\x:real^N. (l:real^N->real^N) x + y) c =
                  IMAGE (\x. y + x) (IMAGE l c)` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM IMAGE_o; o_DEF] THEN REWRITE_TAC[VECTOR_ADD_SYM]; ALL_TAC] THEN
    REWRITE_TAC[AFFINE_DEPENDENT_TRANSLATION_EQ] THEN
    MP_TAC(ISPECL [`l:real^N->real^N`; `c:real^N->bool`]
      AFFINE_DEPENDENT_LINEAR_IMAGE_EQ) THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `CARD(IMAGE (\x:real^N. (l:real^N->real^N) x + y) c) = CARD c`
    (fun th -> ASM_REWRITE_TAC[th]) THEN
    MATCH_MP_TAC CARD_IMAGE_INJ THEN
    ASM_REWRITE_TAC[VECTOR_ARITH `a + c:real^N = b + c <=> a = b`] THEN ASM_MESON_TAC[];
    ASM_SIMP_TAC[MOI_REAL_AFFINE_IMAGE_CONVEX_HULL]]);;

let MOI_S5C_AFF_FULL = prove
 (`!(s:real^N->bool) (t:real^N->bool).
     &(dimindex(:N)) simplex s /\ &(dimindex(:N)) simplex t
     ==> ?(l:real^N->real^N) y (l':real^N->real^N) y'.
                     linear l /\ linear l' /\
                     (!x. l'(l x + y) + y' = x) /\ (!x. l(l' x + y') + y = x) /\
                     IMAGE (\x. l x + y) s = t`,
  REPEAT GEN_TAC THEN REWRITE_TAC[simplex] THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (X_CHOOSE_THEN `V1:real^N->bool` STRIP_ASSUME_TAC)
   (X_CHOOSE_THEN `V2:real^N->bool` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `FINITE(V1:real^N->bool) /\ FINITE(V2:real^N->bool) /\ CARD V1 = CARD V2`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[AFFINE_INDEPENDENT_IMP_FINITE] THEN
    REWRITE_TAC[GSYM INT_OF_NUM_EQ] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`V1:real^N->bool`; `V2:real^N->bool`] CARD_EQ_BIJECTIONS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:real^N->real^N` (X_CHOOSE_THEN `b':real^N->real^N`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`V1:real^N->bool`; `b:real^N->real^N`] MOI_REAL_AFFINE_EXTEND_POINTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `l:real^N->real^N` (X_CHOOSE_THEN `y:real^N`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`V2:real^N->bool`; `b':real^N->real^N`] MOI_REAL_AFFINE_EXTEND_POINTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `l':real^N->real^N` (X_CHOOSE_THEN `y':real^N`
    STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`l:real^N->real^N`; `y:real^N`; `l':real^N->real^N`; `y':real^N`] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `affine hull (V1:real^N->bool) = (:real^N) /\
                affine hull (V2:real^N->bool) = (:real^N)` STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[GSYM AFF_DIM_EQ_FULL] THEN ASM_SIMP_TAC[AFF_DIM_AFFINE_INDEPENDENT] THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`(l':real^N->real^N) o (l:real^N->real^N)`; `\x:real^N. x`;
                   `(l':real^N->real^N) y + y'`; `vec 0:real^N`; `V1:real^N->bool`]
           MOI_REAL_AFFINE_EQ_ON_AFFINE_HULL) THEN
    ASM_SIMP_TAC[LINEAR_COMPOSE; LINEAR_ID; IN_UNIV; o_THM; VECTOR_ADD_RID] THEN
    ANTS_TAC THENL
     [X_GEN_TAC `v:real^N` THEN DISCH_TAC THEN
      SUBGOAL_THEN `(l':real^N->real^N) ((l:real^N->real^N) v) + l' y + y' =
                    l' (l v + y) + y'` SUBST1_TAC THENL
       [SIMP_TAC[ASSUME `linear(l':real^N->real^N)`; LINEAR_ADD] THEN VECTOR_ARITH_TAC;
        ALL_TAC] THEN
      ASM_SIMP_TAC[];
      DISCH_THEN(fun th -> X_GEN_TAC `x:real^N` THEN MP_TAC(SPEC `x:real^N` th)) THEN
      ASM_SIMP_TAC[LINEAR_ADD] THEN VECTOR_ARITH_TAC];
    MP_TAC(ISPECL [`(l:real^N->real^N) o (l':real^N->real^N)`; `\x:real^N. x`;
                   `(l:real^N->real^N) y' + y`; `vec 0:real^N`; `V2:real^N->bool`]
           MOI_REAL_AFFINE_EQ_ON_AFFINE_HULL) THEN
    ASM_SIMP_TAC[LINEAR_COMPOSE; LINEAR_ID; IN_UNIV; o_THM; VECTOR_ADD_RID] THEN
    ANTS_TAC THENL
     [X_GEN_TAC `v:real^N` THEN DISCH_TAC THEN
      SUBGOAL_THEN `(l:real^N->real^N) ((l':real^N->real^N) v) + l y' + y =
                    l (l' v + y') + y` SUBST1_TAC THENL
       [SIMP_TAC[ASSUME `linear(l:real^N->real^N)`; LINEAR_ADD] THEN VECTOR_ARITH_TAC;
        ALL_TAC] THEN
      ASM_SIMP_TAC[];
      DISCH_THEN(fun th -> X_GEN_TAC `x:real^N` THEN MP_TAC(SPEC `x:real^N` th)) THEN
      ASM_SIMP_TAC[LINEAR_ADD] THEN VECTOR_ARITH_TAC];
    MP_TAC(ISPECL [`\x:real^N. x`; `b:real^N->real^N`;
                   `\x:real^N. (l:real^N->real^N) x + y`;
                   `l:real^N->real^N`; `y:real^N`; `V1:real^N->bool`]
      MOI_REAL_IMAGE_SIMPLEX) THEN
    ASM_SIMP_TAC[IMAGE_ID] THEN DISCH_THEN SUBST1_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[EXTENSION; IN_IMAGE] THEN ASM_MESON_TAC[]]);;

(* An affine bijection of the ambient space carries annuli with ends to     *)
(* annuli with ends.                                                         *)

let MOI_S5C_ANN_AFFINE = prove
 (`!(a:real^N->bool) j0 j1 (l:real^N->real^N) y l' y'.
     pl_annulus_with_ends a j0 j1 /\ linear l /\ linear l' /\
     (!x. l'(l x + y) + y' = x) /\ (!x. l(l' x + y') + y = x)
     ==> pl_annulus_with_ends (IMAGE (\x. l x + y) a)
           (IMAGE (\x. l x + y) j0) (IMAGE (\x. l x + y) j1)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_annulus_with_ends] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `f:real^2->real^N`
    (X_CHOOSE_THEN `g:real^N->real^2` STRIP_ASSUME_TAC)) STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`(\x:real^N. (l:real^N->real^N) x + y) o (f:real^2->real^N)`;
                        `(g:real^N->real^2) o (\x:real^N. (l':real^N->real^N) x + y')`] THEN
  ASM_REWRITE_TAC[IMAGE_o] THEN MATCH_MP_TAC HOMEOMORPHISM_IMP_PL_HOMEOMORPHISM THEN
  FIRST_X_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[pl_homeomorphism] o check
    (MOI_S5C_HEAD "pl_homeomorphism")) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `a:real^N->bool` THEN
    ASM_REWRITE_TAC[homeomorphism] THEN ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC MOI_PLM_AFFINE_CONTINUOUS_ON THEN
      MAP_EVERY EXISTS_TAC [`l:real^N->real^N`; `y:real^N`] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM IMAGE_o; o_DEF] THEN ASM_REWRITE_TAC[IMAGE_ID];
      MATCH_MP_TAC MOI_PLM_AFFINE_CONTINUOUS_ON THEN
      MAP_EVERY EXISTS_TAC [`l':real^N->real^N`; `y':real^N`] THEN ASM_REWRITE_TAC[]];
    MATCH_MP_TAC PL_MAP_ON_COMPOSE THEN EXISTS_TAC `(:real^N)` THEN
    ASM_SIMP_TAC[PL_MAP_ON_AFFINE; LOCALLY_POLYHEDRAL_OPEN; OPEN_UNIV; SUBSET_UNIV]]);;

(* Nested triangles: s inside the interior of t bound an annulus.           *)

let MOI_S5C_NT = prove
 (`!s t:real^2->bool.
     &2 simplex s /\ &2 simplex t /\ s SUBSET interior t
     ==> pl_annulus_with_ends (t DIFF interior s) (relative_frontier s)
                              (relative_frontier t)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`s:real^2->bool`; `moi_s5c_tri`] MOI_S5C_AFF_FULL) THEN
  ASM_REWRITE_TAC[DIMINDEX_2; MOI_S5C_TRI_FACTS] THEN
  DISCH_THEN(X_CHOOSE_THEN `l:real^2->real^2` (X_CHOOSE_THEN `y:real^2`
    (X_CHOOSE_THEN `l':real^2->real^2` (X_CHOOSE_THEN `y':real^2`
      STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `(!x x'. (l:real^2->real^2) x = l x' ==> x = x') /\
                (!x x'. (l':real^2->real^2) x = l' x' ==> x = x')`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN REPEAT STRIP_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o AP_TERM `\v:real^2. (l':real^2->real^2) (v + y) + y'`);
      FIRST_X_ASSUM(MP_TAC o AP_TERM `\v:real^2. (l:real^2->real^2) (v + y') + y`)] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!u. IMAGE (\x:real^2. (l:real^2->real^2) x + y) (interior u) =
                    interior (IMAGE (\x. l x + y) u) /\
                    IMAGE (\x:real^2. (l:real^2->real^2) x + y) (relative_frontier u) =
                    relative_frontier (IMAGE (\x. l x + y) u)`
  ASSUME_TAC THENL
   [GEN_TAC THEN
    SUBGOAL_THEN `!v. IMAGE (\x:real^2. (l:real^2->real^2) x + y) v =
                      IMAGE (\x. y + x) (IMAGE l v)`
    (fun th -> REWRITE_TAC[th]) THENL
     [GEN_TAC THEN REWRITE_TAC[GSYM IMAGE_o; o_DEF; VECTOR_ADD_SYM]; ALL_TAC] THEN
    REWRITE_TAC[INTERIOR_TRANSLATION; RELATIVE_FRONTIER_TRANSLATION] THEN
    MP_TAC(ISPECL [`l:real^2->real^2`; `u:real^2->bool`]
      INTERIOR_INJECTIVE_LINEAR_IMAGE) THEN
    MP_TAC(ISPECL [`l:real^2->real^2`; `u:real^2->bool`]
      RELATIVE_FRONTIER_INJECTIVE_LINEAR_IMAGE) THEN
    ASM_REWRITE_TAC[] THEN REPEAT(DISCH_THEN SUBST1_TAC) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!u. IMAGE (\x:real^2. (l':real^2->real^2) x + y')
                      (IMAGE (\x. (l:real^2->real^2) x + y) u) = u`
  ASSUME_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[GSYM IMAGE_o; o_DEF] THEN ASM_REWRITE_TAC[IMAGE_ID];
    ALL_TAC] THEN
  ABBREV_TAC `t' = IMAGE (\x:real^2. (l:real^2->real^2) x + y) t` THEN
  SUBGOAL_THEN `&2 simplex (t':real^2->bool)` ASSUME_TAC THENL
   [EXPAND_TAC "t'" THEN MATCH_MP_TAC MOI_S5C_SIMPLEX_AFFINE_IMAGE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `moi_s5c_tri SUBSET interior (t':real^2->bool)` ASSUME_TAC THENL
   [SUBGOAL_THEN `interior (t':real^2->bool) =
                  IMAGE (\x:real^2. (l:real^2->real^2) x + y) (interior t)`
    SUBST1_TAC THENL [EXPAND_TAC "t'" THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(SUBST1_TAC o SYM o check (fun th -> concl th =
      `IMAGE (\x:real^2. (l:real^2->real^2) x + y) s = moi_s5c_tri`)) THEN
    MATCH_MP_TAC IMAGE_SUBSET THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPEC `t':real^2->bool` MOI_S5C_NT0) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o ISPECL [`l':real^2->real^2`; `y':real^2`; `l:real^2->real^2`;
    `y:real^2`] o MATCH_MP (REWRITE_RULE[IMP_CONJ] MOI_S5C_ANN_AFFINE)) THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EQ_IMP THEN
  FIRST_ASSUM(SUBST1_TAC o SYM o check (fun th -> concl th =
      `IMAGE (\x:real^2. (l:real^2->real^2) x + y) s = moi_s5c_tri`)) THEN
  EXPAND_TAC "t'" THEN
  SUBGOAL_THEN
   `IMAGE (\x:real^2. (l:real^2->real^2) x + y) t DIFF
    interior (IMAGE (\x. l x + y) s) =
    IMAGE (\x. l x + y) (t DIFF interior s)` SUBST1_TAC THENL
   [FIRST_ASSUM((fun th -> REWRITE_TAC[GSYM(CONJUNCT1(SPEC `s:real^2->bool` th))]) o
     check (fun th -> is_forall(concl th) && is_conj(snd(strip_forall(concl th))))) THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC IMAGE_DIFF_INJ THEN
    REWRITE_TAC[VECTOR_ARITH `a + c:real^2 = b + c <=> a = b`] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  FIRST_ASSUM((fun th -> REWRITE_TAC[GSYM(CONJUNCT2(SPEC `s:real^2->bool` th));
                                     GSYM(CONJUNCT2(SPEC `t:real^2->bool` th))]) o
     check (fun th -> is_forall(concl th) && is_conj(snd(strip_forall(concl th))))) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Jordan-Brouwer tools.  The first six lemmas restate lemmas of             *)
(* pc_moi_s35_minb (which is not loaded here) under MOI_S5C_ names.          *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_CONNECTED_SIDE = prove
 (`!s t:real^N->bool.
     connected t /\ DISJOINT s t ==> t SUBSET inside s \/ t SUBSET outside s`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`s:real^N->bool`; `t:real^N->bool`]
    INSIDE_OUTSIDE_INTERSECT_CONNECTED) THEN
  MP_TAC(ISPEC `s:real^N->bool` INSIDE_UNION_OUTSIDE) THEN
  ASM SET_TAC[]);;

let MOI_S5C_CLOPEN_CONNECTED = prove
 (`!c u:real^N->bool.
     connected c /\ open u /\ closure u INTER c SUBSET u /\ ~(u INTER c = {})
     ==> c SUBSET u`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [CONNECTED_CLOPEN]) THEN
  DISCH_THEN(MP_TAC o SPEC `u INTER c:real^N->bool`) THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [ONCE_REWRITE_TAC[INTER_COMM] THEN MATCH_MP_TAC OPEN_IN_OPEN_INTER THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[CLOSED_IN_CLOSED] THEN
      EXISTS_TAC `closure u:real^N->bool` THEN
      REWRITE_TAC[CLOSED_CLOSURE] THEN
      MP_TAC(ISPEC `u:real^N->bool` CLOSURE_SUBSET) THEN ASM SET_TAC[]];
    ASM SET_TAC[]]);;

let MOI_S5C_FILL_CHAR = prove
 (`!s x:real^N->bool.
     2 <= dimindex(:N) /\ s homeomorphic sphere(vec 0:real^N,&1) /\
     compact x /\ frontier x = s /\ ~(interior x = {})
     ==> interior x = inside s /\ x = s UNION inside s`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPEC `s:real^N->bool` JORDAN_INSIDE_OUTSIDE_GEN) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `interior x INTER (s:real^N->bool) = {}` ASSUME_TAC THENL
   [UNDISCH_TAC `frontier x = (s:real^N->bool)` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[frontier] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `closed(x:real^N->bool)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[COMPACT_IMP_CLOSED]; ALL_TAC] THEN
  SUBGOAL_THEN `x = interior x UNION (s:real^N->bool)` ASSUME_TAC THENL
   [UNDISCH_TAC `frontier x = (s:real^N->bool)` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    MP_TAC(ISPEC `x:real^N->bool` INTERIOR_SUBSET) THEN
    REWRITE_TAC[frontier] THEN ASM_SIMP_TAC[CLOSURE_CLOSED] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `closure(interior x) INTER ((:real^N) DIFF s) SUBSET interior x`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`interior x:real^N->bool`; `x:real^N->bool`]
      CLOSURE_MINIMAL) THEN
    ASM_REWRITE_TAC[INTERIOR_SUBSET] THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `bounded(interior x:real^N->bool)` ASSUME_TAC THENL
   [MATCH_MP_TAC BOUNDED_SUBSET THEN EXISTS_TAC `x:real^N->bool` THEN
    ASM_SIMP_TAC[COMPACT_IMP_BOUNDED; INTERIOR_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN `interior x INTER outside s:real^N->bool = {}` ASSUME_TAC THENL
   [ASM_CASES_TAC `interior x INTER outside s:real^N->bool = {}` THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`outside s:real^N->bool`; `interior x:real^N->bool`]
      MOI_S5C_CLOPEN_CONNECTED) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[OPEN_INTERIOR] THEN
      UNDISCH_TAC `closure(interior x) INTER ((:real^N) DIFF s) SUBSET
                   interior x` THEN
      UNDISCH_TAC `inside s UNION outside s = (:real^N) DIFF s` THEN
      SET_TAC[];
      ASM_MESON_TAC[BOUNDED_SUBSET]];
    ALL_TAC] THEN
  SUBGOAL_THEN `interior x = inside s:real^N->bool` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
     [UNDISCH_TAC `interior x INTER outside s:real^N->bool = {}` THEN
      UNDISCH_TAC `interior x INTER (s:real^N->bool) = {}` THEN
      UNDISCH_TAC `inside s UNION outside s = (:real^N) DIFF s` THEN
      SET_TAC[];
      MATCH_MP_TAC MOI_S5C_CLOPEN_CONNECTED THEN
      REWRITE_TAC[OPEN_INTERIOR] THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `closure(interior x) INTER ((:real^N) DIFF s) SUBSET
                   interior x` THEN
      UNDISCH_TAC `interior x INTER outside s:real^N->bool = {}` THEN
      UNDISCH_TAC `interior x INTER (s:real^N->bool) = {}` THEN
      UNDISCH_TAC `inside s UNION outside s = (:real^N) DIFF s` THEN
      UNDISCH_TAC `~(interior x:real^N->bool = {})` THEN
      SET_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  UNDISCH_TAC `x = interior x UNION (s:real^N->bool)` THEN
  UNDISCH_TAC `interior x = inside s:real^N->bool` THEN
  SET_TAC[]);;

let MOI_S5C_PL_BALL_3_FILL = prove
 (`!c:real^3->bool.
     pl_ball 3 c
     ==> pl_sphere 2 (frontier c) /\ compact c /\
         interior c = inside(frontier c) /\
         c = frontier c UNION inside(frontier c)`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `pl_sphere 2 (frontier c:real^3->bool)` ASSUME_TAC THENL
   [UNDISCH_TAC `pl_ball 3 (c:real^3->bool)` THEN
    REWRITE_TAC[pl_ball; pl_sphere; ARITH_RULE `2 + 1 = 3`] THEN
    MESON_TAC[MOI_SCD_BALL_BOUNDARY_PLH];
    ALL_TAC] THEN
  SUBGOAL_THEN `compact(c:real^3->bool)` ASSUME_TAC THENL
   [ASM_MESON_TAC[MOI_SCD_PL_BALL_FACTS]; ALL_TAC] THEN
  SUBGOAL_THEN `~(interior c:real^3->bool = {})` ASSUME_TAC THENL
   [UNDISCH_TAC `pl_ball 3 (c:real^3->bool)` THEN
    REWRITE_TAC[pl_ball; pl_homeomorphism] THEN
    DISCH_THEN(X_CHOOSE_THEN `k:real^3->bool` (X_CHOOSE_THEN `f:real^3->real^3`
      (X_CHOOSE_THEN `g:real^3->real^3` STRIP_ASSUME_TAC))) THEN
    FIRST_ASSUM(X_CHOOSE_TAC `b:real^3` o MATCH_MP MOI_FN1_SIMPLEX_3_INTERIOR) THEN
    MP_TAC(ISPECL [`k:real^3->bool`; `c:real^3->bool`; `f:real^3->real^3`;
                   `g:real^3->real^3`] MOI_FN1_HOMEOMORPHISM_INTERIOR) THEN
    ASM SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOI_S5C_FILL_CHAR THEN
  ASM_SIMP_TAC[MOI_SCD_PL_SPHERE_2_HOMEOMORPHIC; DIMINDEX_3; ARITH]);;

let MOI_S5C_PL_SPHERE_HOMEO = prove
 (`!n s:real^N->bool.
     pl_sphere n s /\ n + 1 = dimindex(:N)
     ==> s homeomorphic sphere(vec 0:real^N,&1)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_sphere] THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (X_CHOOSE_THEN `k:real^N->bool` (X_CHOOSE_THEN `f:real^N->real^N`
     (X_CHOOSE_THEN `g:real^N->real^N` STRIP_ASSUME_TAC))) ASSUME_TAC) THEN
  TRANS_TAC HOMEOMORPHIC_TRANS `relative_frontier k:real^N->bool` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[homeomorphic] THEN
    MAP_EVERY EXISTS_TAC [`g:real^N->real^N`; `f:real^N->real^N`] THEN
    ONCE_REWRITE_TAC[HOMEOMORPHISM_SYM] THEN
    ASM_MESON_TAC[pl_homeomorphism];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`k:real^N->bool`; `cball(vec 0:real^N,&1)`]
    HOMEOMORPHIC_RELATIVE_FRONTIERS_CONVEX_BOUNDED_SETS) THEN
  REWRITE_TAC[CONVEX_CBALL; BOUNDED_CBALL; RELATIVE_FRONTIER_CBALL;
              AFF_DIM_CBALL] THEN
  CONV_TAC REAL_RAT_REDUCE_CONV THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(ISPECL [`k:real^N->bool`; `&(n + 1):int`] SIMPLEX_IMP_COMPACT) THEN
  MP_TAC(ISPECL [`k:real^N->bool`; `&(n + 1):int`] SIMPLEX_IMP_CONVEX) THEN
  MP_TAC(ISPECL [`k:real^N->bool`; `&(n + 1):int`] AFF_DIM_SIMPLEX) THEN
  ASM_SIMP_TAC[COMPACT_IMP_BOUNDED]);;

let MOI_S5C_NESTED_INSIDE = prove
 (`!j1 j2:real^2->bool.
     j1 homeomorphic sphere(vec 0:real^2,&1) /\
     j2 homeomorphic sphere(vec 0:real^2,&1) /\ j1 SUBSET inside j2
     ==> inside j1 SUBSET inside j2 /\ outside j2 SUBSET outside j1 /\
         j2 SUBSET outside j1`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPEC `j1:real^2->bool` JORDAN_INSIDE_OUTSIDE_GEN) THEN
  ASM_REWRITE_TAC[DIMINDEX_2; LE_REFL] THEN STRIP_TAC THEN
  MP_TAC(ISPEC `j2:real^2->bool` JORDAN_INSIDE_OUTSIDE_GEN) THEN
  ASM_REWRITE_TAC[DIMINDEX_2; LE_REFL] THEN STRIP_TAC THEN
  SUBGOAL_THEN `connected(j1:real^2->bool) /\ connected(j2:real^2->bool) /\
                ~(j1 = {}) /\ ~(j2 = {})` STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `connected(sphere(vec 0:real^2,&1)) /\
                  ~(sphere(vec 0:real^2,&1) = {})` STRIP_ASSUME_TAC THENL
     [SIMP_TAC[CONNECTED_SPHERE; DIMINDEX_2; LE_REFL; SPHERE_EQ_EMPTY] THEN
      REAL_ARITH_TAC;
      ASM_MESON_TAC[HOMEOMORPHIC_CONNECTEDNESS; HOMEOMORPHIC_EMPTY]];
    ALL_TAC] THEN
  SUBGOAL_THEN `outside j2 SUBSET outside(j1:real^2->bool)` ASSUME_TAC THENL
   [REWRITE_TAC[SUBSET] THEN X_GEN_TAC `z:real^2` THEN DISCH_TAC THEN
    MATCH_MP_TAC UNBOUNDED_DISJOINT_IN_OUTSIDE THEN
    EXISTS_TAC `outside j2:real^2->bool` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `j1 SUBSET inside(j2:real^2->bool)` THEN
    UNDISCH_TAC `inside j2 INTER outside j2:real^2->bool = {}` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `j2 SUBSET outside(j1:real^2->bool)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`j1:real^2->bool`; `j2:real^2->bool`]
      MOI_S5C_CONNECTED_SIDE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPEC `j2:real^2->bool` INSIDE_NO_OVERLAP) THEN
      UNDISCH_TAC `j1 SUBSET inside(j2:real^2->bool)` THEN SET_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `~p ==> p \/ q ==> q`) THEN DISCH_TAC THEN
    SUBGOAL_THEN `outside j1 SUBSET outside(j2:real^2->bool)` ASSUME_TAC THENL
     [REWRITE_TAC[SUBSET] THEN X_GEN_TAC `z:real^2` THEN DISCH_TAC THEN
      MATCH_MP_TAC UNBOUNDED_DISJOINT_IN_OUTSIDE THEN
      EXISTS_TAC `outside j1:real^2->bool` THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `j2 SUBSET inside(j1:real^2->bool)` THEN
      UNDISCH_TAC `inside j1 INTER outside j1:real^2->bool = {}` THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `j1:real^2->bool = j2` ASSUME_TAC THENL
     [UNDISCH_TAC `frontier(outside j1):real^2->bool = j1` THEN
      UNDISCH_TAC `frontier(outside j2):real^2->bool = j2` THEN
      SUBGOAL_THEN `outside j1:real^2->bool = outside j2` SUBST1_TAC THENL
       [ASM SET_TAC[]; MESON_TAC[]];
      ALL_TAC] THEN
    UNDISCH_TAC `j1 SUBSET inside(j2:real^2->bool)` THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPEC `j2:real^2->bool` INSIDE_NO_OVERLAP) THEN
    UNDISCH_TAC `~(j2:real^2->bool = {})` THEN SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`j2:real^2->bool`; `inside j1:real^2->bool`]
    MOI_S5C_CONNECTED_SIDE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `j2 SUBSET outside(j1:real^2->bool)` THEN
    UNDISCH_TAC `inside j1 INTER outside j1:real^2->bool = {}` THEN SET_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `~q ==> p \/ q ==> p`) THEN DISCH_TAC THEN
  UNDISCH_TAC `outside j2 SUBSET outside(j1:real^2->bool)` THEN
  UNDISCH_TAC `inside j1 SUBSET outside(j2:real^2->bool)` THEN
  UNDISCH_TAC `inside j1 INTER outside j1:real^2->bool = {}` THEN
  UNDISCH_TAC `~(inside j1:real^2->bool = {})` THEN SET_TAC[]);;

(* Facts about a 2-simplex of the plane.                                    *)

let MOI_S5C_SIMPLEX2_FACTS = prove
 (`!t:real^2->bool.
     &2 simplex t
     ==> convex t /\ compact t /\ closed t /\ bounded t /\ ~(interior t = {}) /\
         inside(relative_frontier t) = interior t /\
         relative_frontier t UNION interior t = t /\
         relative_frontier t INTER interior t = {} /\
         relative_frontier t SUBSET t /\ interior t SUBSET t /\
         pl_sphere 1 (relative_frontier t) /\
         relative_frontier t homeomorphic sphere(vec 0:real^2,&1)`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `convex (t:real^2->bool) /\ compact t /\ closed t /\ bounded t`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[SIMPLEX_IMP_CONVEX; SIMPLEX_IMP_COMPACT; SIMPLEX_IMP_CLOSED;
                  COMPACT_IMP_BOUNDED];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(interior (t:real^2->bool) = {})` ASSUME_TAC THENL
   [SUBGOAL_THEN `affine hull (t:real^2->bool) = (:real^2)` ASSUME_TAC THENL
     [REWRITE_TAC[GSYM AFF_DIM_EQ_FULL; DIMINDEX_2] THEN
      ASM_MESON_TAC[AFF_DIM_SIMPLEX];
      ALL_TAC] THEN
    FIRST_ASSUM(SUBST1_TAC o SYM o MATCH_MP RELATIVE_INTERIOR_INTERIOR) THEN
    ASM_SIMP_TAC[RELATIVE_INTERIOR_EQ_EMPTY] THEN DISCH_THEN SUBST_ALL_TAC THEN
    UNDISCH_TAC `&2 simplex ({}:real^2->bool)` THEN
    DISCH_THEN(MP_TAC o MATCH_MP AFF_DIM_SIMPLEX) THEN
    REWRITE_TAC[AFF_DIM_EMPTY] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  ASM_SIMP_TAC[RELATIVE_FRONTIER_NONEMPTY_INTERIOR; INSIDE_FRONTIER_EQ_INTERIOR] THEN
  SUBGOAL_THEN `frontier (t:real^2->bool) UNION interior t = t` ASSUME_TAC THENL
   [ASM_SIMP_TAC[FRONTIER_UNION_INTERIOR; CLOSURE_CLOSED]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `pl_sphere 1 (frontier (t:real^2->bool))` ASSUME_TAC THENL
   [FIRST_ASSUM(SUBST1_TAC o SYM o MATCH_MP RELATIVE_FRONTIER_NONEMPTY_INTERIOR) THEN
    MATCH_MP_TAC PL_SPHERE_RELATIVE_FRONTIER_SIMPLEX THEN
    ASM_REWRITE_TAC[ARITH_RULE `1 + 1 = 2`];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[frontier] THEN SET_TAC[];
    ASM SET_TAC[];
    REWRITE_TAC[INTERIOR_SUBSET];
    MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC]);;

let MOI_S5C_ANN_POLYHEDRON = prove
 (`!(a:real^N->bool) j0 j1. pl_annulus_with_ends a j0 j1 ==> pl_polyhedron a`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_annulus_with_ends; pl_homeomorphism] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `a = IMAGE (f:real^2->real^N)
                 (interval[--vector[&2;&2],vector[&2;&2]] DIFF
                  interval(--vector[&1;&1],vector[&1;&1]))` SUBST1_TAC THENL
   [ASM_MESON_TAC[homeomorphism]; ALL_TAC] THEN
  MATCH_MP_TAC PL_POLYHEDRON_PL_IMAGE THEN ASM_REWRITE_TAC[MOI_S5C_SQANN_POLYHEDRON]);;

(* Annuli between nested Jordan curves are invariant under ambient PL        *)
(* homeomorphisms.                                                           *)

let MOI_S5C_ANN_AMBIENT = prove
 (`!(ff:real^N->real^N) gg k k'.
     pl_homeomorphism ((:real^N),(:real^N)) (ff,gg) /\
     pl_annulus_with_ends
       ((IMAGE ff k' UNION inside (IMAGE ff k')) DIFF inside (IMAGE ff k))
       (IMAGE ff k) (IMAGE ff k')
     ==> pl_annulus_with_ends ((k' UNION inside k') DIFF inside k) k k'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `homeomorphism ((:real^N),(:real^N)) (ff:real^N->real^N,gg)`
  ASSUME_TAC THENL [ASM_MESON_TAC[pl_homeomorphism]; ALL_TAC] THEN
  SUBGOAL_THEN `!s. IMAGE (gg:real^N->real^N) (IMAGE ff s) = s` ASSUME_TAC THENL
   [UNDISCH_TAC `homeomorphism ((:real^N),(:real^N)) (ff:real^N->real^N,gg)` THEN
    REWRITE_TAC[homeomorphism; IN_UNIV] THEN STRIP_TAC THEN
    REWRITE_TAC[GSYM IMAGE_o; o_DEF] THEN ASM_REWRITE_TAC[IMAGE_ID];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(IMAGE ff k' UNION inside (IMAGE ff k')) DIFF inside (IMAGE ff k) =
    IMAGE (ff:real^N->real^N) ((k' UNION inside k') DIFF inside k)`
  (fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THENL
   [FIRST_ASSUM(fun th -> REWRITE_TAC[GSYM(MATCH_MP MOI_SCD_INSIDE_HOMEOMORPHISM th)]) THEN
    REWRITE_TAC[GSYM IMAGE_UNION] THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC IMAGE_DIFF_INJ THEN
    UNDISCH_TAC `homeomorphism ((:real^N),(:real^N)) (ff:real^N->real^N,gg)` THEN
    REWRITE_TAC[homeomorphism; IN_UNIV] THEN MESON_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `R = (k' UNION inside k') DIFF inside (k:real^N->bool)` THEN
  MP_TAC(ISPECL
   [`IMAGE (ff:real^N->real^N) R`;
    `IMAGE (ff:real^N->real^N) k`; `IMAGE (ff:real^N->real^N) k'`;
    `R:real^N->bool`; `gg:real^N->real^N`; `ff:real^N->real^N`] MOI_S5C_ANN_TRANSFER) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(ISPECL [`(:real^N)`; `(:real^N)`; `gg:real^N->real^N`; `ff:real^N->real^N`;
                 `IMAGE (ff:real^N->real^N) R`] MOI_S5C_PLH_RESTRICT) THEN
  ANTS_TAC THENL
   [ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
    MATCH_MP_TAC MOI_S5C_ANN_POLYHEDRON THEN
    MAP_EVERY EXISTS_TAC [`IMAGE (ff:real^N->real^N) k`; `IMAGE (ff:real^N->real^N) k'`] THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

(* The planar annulus theorem: two nested PL circles bound a PL annulus.    *)

let MOI_S5C_ANN2 = prove
 (`!k k':real^2->bool.
     pl_sphere 1 k /\ pl_sphere 1 k' /\ k SUBSET inside k'
     ==> pl_annulus_with_ends ((k' UNION inside k') DIFF inside k) k k'`,
  REPEAT STRIP_TAC THEN
  MP_TAC(MATCH_MP MOI_SCD_AMB2 AMB2_VERTEX) THEN
  REWRITE_TAC[PL_SCHOENFLIES_2_AMBIENT_STATEMENT] THEN DISCH_TAC THEN
  FIRST_ASSUM(MP_TAC o SPECL [`k':real^2->bool`; `(:real^2)`]) THEN
  REWRITE_TAC[OPEN_UNIV; SUBSET_UNIV; IN_UNIV] THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `T1:real^2->bool` (X_CHOOSE_THEN `f1:real^2->real^2`
    (X_CHOOSE_THEN `g1:real^2->real^2` STRIP_ASSUME_TAC))) THEN
  MP_TAC(SPEC `T1:real^2->bool` MOI_S5C_SIMPLEX2_FACTS) THEN ASM_REWRITE_TAC[] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `homeomorphism ((:real^2),(:real^2)) (f1:real^2->real^2,g1)` ASSUME_TAC
  THENL [ASM_MESON_TAC[pl_homeomorphism]; ALL_TAC] THEN
  SUBGOAL_THEN `pl_sphere 1 (IMAGE (f1:real^2->real^2) k)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`k:real^2->bool`; `IMAGE (f1:real^2->real^2) k`; `f1:real^2->real^2`;
                   `g1:real^2->real^2`; `1`] MOI_FM3_PL_SPHERE_TRANSFER) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[DIMINDEX_2; ARITH_RULE `1 + 1 <= 2`] THEN
    MATCH_MP_TAC MOI_S5C_PLH_RESTRICT THEN
    MAP_EVERY EXISTS_TAC [`(:real^2)`; `(:real^2)`] THEN
    ASM_REWRITE_TAC[SUBSET_UNIV] THEN MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
    ASM_MESON_TAC[MOI_SCD_PL_SPHERE_POLYHEDRON];
    ALL_TAC] THEN
  SUBGOAL_THEN `(k:real^2->bool) homeomorphic sphere(vec 0:real^2,&1) /\
                (k':real^2->bool) homeomorphic sphere(vec 0:real^2,&1)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `inside k SUBSET inside (k':real^2->bool)` ASSUME_TAC THENL
   [ASM_MESON_TAC[MOI_S5C_NESTED_INSIDE]; ALL_TAC] THEN
  SUBGOAL_THEN `!s. IMAGE (f1:real^2->real^2) (inside s) = inside (IMAGE f1 s)`
  ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC MOI_SCD_INSIDE_HOMEOMORPHISM THEN
    EXISTS_TAC `g1:real^2->real^2` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (f1:real^2->real^2) (inside k') = interior T1` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (f1:real^2->real^2) k UNION inside (IMAGE f1 k) SUBSET interior T1`
  ASSUME_TAC THENL
   [SUBGOAL_THEN `inside (IMAGE (f1:real^2->real^2) k) = IMAGE f1 (inside k)`
    SUBST1_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[GSYM IMAGE_UNION] THEN
    FIRST_ASSUM(SUBST1_TAC o SYM o check (fun th -> concl th =
      `IMAGE (f1:real^2->real^2) (inside k') = interior T1`)) THEN
    MATCH_MP_TAC IMAGE_SUBSET THEN ASM SET_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`IMAGE (f1:real^2->real^2) k`;
                                `interior T1:real^2->bool`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[OPEN_INTERIOR]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `T2:real^2->bool` (X_CHOOSE_THEN `f2:real^2->real^2`
    (X_CHOOSE_THEN `g2:real^2->real^2` STRIP_ASSUME_TAC))) THEN
  MP_TAC(SPEC `T2:real^2->bool` MOI_S5C_SIMPLEX2_FACTS) THEN ASM_REWRITE_TAC[] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `homeomorphism ((:real^2),(:real^2)) (f2:real^2->real^2,g2)` ASSUME_TAC
  THENL [ASM_MESON_TAC[pl_homeomorphism]; ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (f2:real^2->real^2) (relative_frontier T1) = relative_frontier T1`
  ASSUME_TAC THENL
   [MATCH_MP_TAC EQ_TRANS THEN EXISTS_TAC `IMAGE (\x:real^2. x) (relative_frontier T1)` THEN
    CONJ_TAC THENL [ALL_TAC; REWRITE_TAC[IMAGE_ID]] THEN
    MATCH_MP_TAC MOI_S5C_IMAGE_EQ THEN REWRITE_TAC[] THEN
    X_GEN_TAC `x:real^2` THEN DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    MP_TAC(ASSUME `relative_frontier T1 INTER interior T1:real^2->bool = {}`) THEN
    UNDISCH_TAC `(x:real^2) IN relative_frontier T1` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `T2 SUBSET interior (T1:real^2->bool)` ASSUME_TAC THENL
   [SUBGOAL_THEN `T2 = IMAGE (f2:real^2->real^2)
                         (IMAGE f1 k UNION inside (IMAGE (f1:real^2->real^2) k))`
    SUBST1_TAC THENL
     [REWRITE_TAC[IMAGE_UNION] THEN
      FIRST_ASSUM((fun th -> REWRITE_TAC[MATCH_MP MOI_SCD_INSIDE_HOMEOMORPHISM th]) o
        check (fun th -> concl th =
          `homeomorphism ((:real^2),(:real^2)) (f2:real^2->real^2,g2)`)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `IMAGE (f2:real^2->real^2) (interior T1)` THEN
    ASM_SIMP_TAC[IMAGE_SUBSET] THEN REWRITE_TAC[SUBSET; FORALL_IN_IMAGE] THEN
    X_GEN_TAC `x:real^2` THEN DISCH_TAC THEN
    ASM_CASES_TAC `(f2:real^2->real^2) x IN interior T1` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(f2:real^2->real^2) (f2 x) = f2 x` MP_TAC THENL
     [ASM_SIMP_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `homeomorphism ((:real^2),(:real^2)) (f2:real^2->real^2,g2)` THEN
    REWRITE_TAC[homeomorphism; IN_UNIV] THEN STRIP_TAC THEN
    DISCH_THEN(MP_TAC o AP_TERM `g2:real^2->real^2`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN UNDISCH_TAC `~((f2:real^2->real^2) x IN interior T1)` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC MOI_S5C_ANN_AMBIENT THEN
  MAP_EVERY EXISTS_TAC [`(f2:real^2->real^2) o (f1:real^2->real^2)`;
                        `(g1:real^2->real^2) o (g2:real^2->real^2)`] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `(:real^2)` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[IMAGE_o] THEN
  SUBGOAL_THEN `(relative_frontier T1 UNION interior T1) DIFF interior T2 =
                T1 DIFF interior (T2:real^2->bool)` SUBST1_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC MOI_S5C_NT THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The collar of the level c (restated from pc_moi_s35_minb under             *)
(* MOI_S5C_ names).                                                           *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_NO_3DIM = prove
 (`!K (G:real^3->real^2) B.
     simplicial_complex K /\ UNIONS K = B /\ G continuous_on B /\
     (!x y. x IN B /\ y IN B /\ G x = G y ==> x = y)
     ==> !s. s IN K ==> aff_dim s <= &2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN X_GEN_TAC `s:real^3->bool` THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `convex(s:real^3->bool) /\ s SUBSET B` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [ASM_MESON_TAC[MOI_CON_SC_CONVEX]; ASM SET_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPEC `s:real^3->bool` AFF_DIM_LE_UNIV) THEN
  REWRITE_TAC[DIMINDEX_3] THEN
  ASM_CASES_TAC `aff_dim(s:real^3->bool) = &3` THENL
   [ALL_TAC; ASM_INT_ARITH_TAC] THEN
  MP_TAC(ISPEC `s:real^3->bool` AFF_DIM_NONEMPTY_INTERIOR_EQ) THEN
  ASM_REWRITE_TAC[DIMINDEX_3] THEN DISCH_TAC THEN
  SUBGOAL_THEN `dimindex(:3) <= dimindex(:2)` MP_TAC THENL
   [ALL_TAC; REWRITE_TAC[DIMINDEX_2; DIMINDEX_3] THEN ARITH_TAC] THEN
  MATCH_MP_TAC INVARIANCE_OF_DIMENSION THEN
  MAP_EVERY EXISTS_TAC [`G:real^3->real^2`; `interior s:real^3->bool`] THEN
  ASM_REWRITE_TAC[OPEN_INTERIOR] THEN
  MP_TAC(ISPEC `s:real^3->bool` INTERIOR_SUBSET) THEN DISCH_TAC THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `B:real^3->bool` THEN
    ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
    ASM SET_TAC[]]);;

let moi_s5c_collar = new_definition
 `moi_s5c_collar (B:real^3->bool) c d0 (Q:real^3->real->real^3) <=>
    &0 < d0 /\
    (!x t. x IN B /\ x$3 = c /\ abs t <= &1
           ==> Q x t IN B /\ (Q x t)$3 = c + t * d0) /\
    (!x. x IN B /\ x$3 = c ==> Q x (&0) = x) /\
    (!x t x' t'. x IN B /\ x$3 = c /\ abs t <= &1 /\
                 x' IN B /\ x'$3 = c /\ abs t' <= &1 /\ Q x t = Q x' t'
                 ==> x = x' /\ t = t') /\
    (!z. z IN B /\ abs(z$3 - c) <= d0
         ==> ?x t. x IN B /\ x$3 = c /\ abs t <= &1 /\ z = Q x t) /\
    (\p. Q (fstcart p) (drop(sndcart p))) continuous_on
    ({x | x IN B /\ x$3 = c} PCROSS interval[--vec 1,vec 1]) /\
    (!t. abs t <= &1 ==> pl_map_on {x | x IN B /\ x$3 = c} (\x. Q x t))`;;

let MOI_S5C_LEVEL_POLYHEDRON = prove
 (`!B c. pl_polyhedron B ==> pl_polyhedron {x:real^3 | x IN B /\ x$3 = c}`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP PL_POLYHEDRON_IMP_COMPACT) THEN
  DISCH_THEN(MP_TAC o MATCH_MP COMPACT_IMP_BOUNDED) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:real^3` (X_CHOOSE_TAC `b:real^3`) o
    MATCH_MP BOUNDED_SUBSET_CLOSED_INTERVAL) THEN
  SUBGOAL_THEN `{x:real^3 | x IN B /\ x$3 = c} =
                B INTER (interval[a,b] INTER {x | basis 3 dot x = c})`
  SUBST1_TAC THENL
   [SIMP_TAC[DOT_BASIS; DIMINDEX_3; ARITH] THEN
    UNDISCH_TAC `B SUBSET interval[a:real^3,b]` THEN SET_TAC[];
    MATCH_MP_TAC PL_POLYHEDRON_INTER THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC POLYTOPE_IMP_PL_POLYHEDRON THEN
    MATCH_MP_TAC POLYTOPE_INTER_POLYHEDRON THEN
    REWRITE_TAC[POLYTOPE_INTERVAL; POLYHEDRON_HYPERPLANE]]);;

(* MOI_S5C_PL_LINEAR (same statement) is proved earlier in this file. *)

let MOI_S5C_LIFT_AFFINE = prove
 (`!v:real^1. lift((drop v + &1) / &2) = inv(&2) % v + lift(inv(&2))`,
  REWRITE_TAC[GSYM DROP_EQ; DROP_ADD; DROP_CMUL; LIFT_DROP] THEN
  REAL_ARITH_TAC);;

let MOI_S5C_COLLAR_EXISTS = prove
 (`(!(k:(real^3->bool)->bool) c d.
     FINITE k /\ simplicial_complex k /\ (!s. s IN k ==> aff_dim s <= &2) /\
     c < d /\ (!v. {v} IN k ==> v$3 < c \/ d < v$3)
     ==> ?(f:real^(3,1)finite_sum->real^3) g.
           homeomorphism
             ({x | x IN UNIONS k /\ x$3 = c} PCROSS interval[vec 0:real^1,vec 1],
              {x | x IN UNIONS k /\ c <= x$3 /\ x$3 <= d}) (f,g) /\
           pl_map_on ({x | x IN UNIONS k /\ x$3 = c} PCROSS
                      interval[vec 0:real^1,vec 1]) f /\
           (!x s. x IN UNIONS k /\ x$3 = c /\ s IN interval[vec 0:real^1,vec 1]
                  ==> (f(pastecart x s))$3 = c + drop s * (d - c)) /\
           (!x. x IN UNIONS k /\ x$3 = c ==> f(pastecart x (vec 0)) = x))
   ==> !K B c d0.
         FINITE K /\ simplicial_complex K /\ (!s. s IN K ==> aff_dim s <= &2) /\
         UNIONS K = B /\ &0 < d0 /\ (!v. {v} IN K ==> d0 < abs(v$3 - c))
         ==> ?Q. moi_s5c_collar B c d0 Q`,
  DISCH_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`K:(real^3->bool)->bool`; `c - d0:real`;
                                `c + d0:real`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    X_GEN_TAC `v:real^3` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `v:real^3`) THEN ASM_REWRITE_TAC[] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[REAL_ARITH `(c + d0) - (c - d0) = &2 * d0`] THEN
  DISCH_THEN(X_CHOOSE_THEN `f:real^(3,1)finite_sum->real^3`
   (X_CHOOSE_THEN `g:real^3->real^(3,1)finite_sum` STRIP_ASSUME_TAC)) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[homeomorphism] o check (fun th ->
    try fst(dest_const(rator(rator(concl th)))) = "homeomorphism"
    with Failure _ -> false)) THEN
  SUBGOAL_THEN `!x:real^3. x IN B /\ x$3 = c
                ==> fstcart((g:real^3->real^(3,1)finite_sum) x) IN
                      {x | x IN B /\ x$3 = c - d0} /\
                    g x = pastecart (fstcart(g x)) (lift(&1 / &2))`
  (LABEL_TAC "gx") THENL
   [X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(x:real^3) IN {x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0}` ASSUME_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `&0 < d0` THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(g:real^3->real^(3,1)finite_sum) x IN
                  {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1]` MP_TAC THENL
     [ASM SET_TAC[]; ALL_TAC] THEN
    GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [GSYM PASTECART_FST_SND] THEN
    REWRITE_TAC[PASTECART_IN_PCROSS] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    GEN_REWRITE_TAC LAND_CONV [GSYM PASTECART_FST_SND] THEN
    REWRITE_TAC[PASTECART_INJ] THEN
    SUBGOAL_THEN `((f:real^(3,1)finite_sum->real^3)
                    (pastecart (fstcart ((g:real^3->real^(3,1)finite_sum) x))
                               (sndcart (g x))))$3 =
                  (c - d0) + drop(sndcart(g x)) * (&2 * d0)` MP_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN UNDISCH_TAC `fstcart
        ((g:real^3->real^(3,1)finite_sum) x) IN {x | x IN B /\ x$3 = c - d0}` THEN
      ASM_REWRITE_TAC[IN_ELIM_THM] THEN SIMP_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[PASTECART_FST_SND] THEN
    SUBGOAL_THEN `(f:real^(3,1)finite_sum->real^3) (g x) = x` SUBST1_TAC THENL
     [ASM SET_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[GSYM DROP_EQ; LIFT_DROP] THEN
    UNDISCH_TAC `&0 < d0` THEN CONV_TAC REAL_FIELD;
    ALL_TAC] THEN
  EXISTS_TAC `\x t. (f:real^(3,1)finite_sum->real^3)
                      (pastecart (fstcart((g:real^3->real^(3,1)finite_sum) x))
                                 (lift((t + &1) / &2)))` THEN
  REWRITE_TAC[moi_s5c_collar] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `!x t. x IN B /\ x$3 = c /\ abs t <= &1
                ==> pastecart (fstcart((g:real^3->real^(3,1)finite_sum) x))
                              (lift((t + &1) / &2)) IN
                    {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1]`
  (LABEL_TAC "pin") THENL
   [REPEAT STRIP_TAC THEN
    REWRITE_TAC[PASTECART_IN_PCROSS] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[IN_INTERVAL_1; DROP_VEC; LIFT_DROP] THEN
    UNDISCH_TAC `abs t <= &1` THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!z:real^(3,1)finite_sum.
                  z IN {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS
                       interval[vec 0:real^1,vec 1]
                  ==> (f:real^(3,1)finite_sum->real^3) z IN B`
  (LABEL_TAC "fB") THENL
   [X_GEN_TAC `z:real^(3,1)finite_sum` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(f:real^(3,1)finite_sum->real^3) z IN
                  {x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0}`
    MP_TAC THENL [ASM SET_TAC[]; SIMP_TAC[IN_ELIM_THM]];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "gx" (MP_TAC o SPEC `x:real^3`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; REWRITE_TAC[IN_ELIM_THM]] THEN
    STRIP_TAC THEN
    MP_TAC(SPECL [`fstcart((g:real^3->real^(3,1)finite_sum) x)`;
                  `lift((t + &1) / &2)`]
      (ASSUME `!x s. x IN B /\ x$3 = c - d0 /\ s IN interval[vec 0:real^1,vec 1]
                     ==> ((f:real^(3,1)finite_sum->real^3) (pastecart x s))$3 =
                         c - d0 + drop s * &2 * d0`)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[IN_INTERVAL_1; DROP_VEC; LIFT_DROP] THEN
      UNDISCH_TAC `abs t <= &1` THEN REAL_ARITH_TAC;
      DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[LIFT_DROP] THEN CONV_TAC REAL_RING];
    X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
    REWRITE_TAC[REAL_ADD_LID; REAL_ARITH `&1 / &2 = &1 / &2`] THEN
    USE_THEN "gx" (MP_TAC o SPEC `x:real^3`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(SUBST1_TAC o SYM o CONJUNCT2) THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
      try fst(dest_var(fst(dest_forall(concl th)))) = "y"
      with Failure _ -> false)) THEN
    REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `&0 < d0` THEN REAL_ARITH_TAC;
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    USE_THEN "gx" (fun th -> MP_TAC(SPEC `x:real^3` th) THEN
                             MP_TAC(SPEC `x':real^3` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
    USE_THEN "pin" (fun th -> MP_TAC(SPECL [`x:real^3`; `t:real`] th) THEN
                              MP_TAC(SPECL [`x':real^3`; `t':real`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
    SUBGOAL_THEN
     `pastecart (fstcart((g:real^3->real^(3,1)finite_sum) x))
                (lift((t + &1) / &2)) =
      pastecart (fstcart(g x')) (lift((t' + &1) / &2))`
    MP_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o AP_TERM `g:real^3->real^(3,1)finite_sum` o
        check (fun th -> try is_eq(concl th) &&
               fst(dest_var(rator(lhs(concl th)))) = "f" with Failure _ -> false)) THEN
      REWRITE_TAC[MATCH_MP (ASSUME `!z. z IN {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1] ==> (g:real^3->real^(3,1)finite_sum) ((f:real^(3,1)finite_sum->real^3) z) = z`) (ASSUME
        `pastecart (fstcart((g:real^3->real^(3,1)finite_sum) x))
                   (lift((t + &1) / &2)) IN {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1]`);
                  MATCH_MP (ASSUME `!z. z IN {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1] ==> (g:real^3->real^(3,1)finite_sum) ((f:real^(3,1)finite_sum->real^3) z) = z`) (ASSUME
        `pastecart (fstcart((g:real^3->real^(3,1)finite_sum) x'))
                   (lift((t' + &1) / &2)) IN {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1]`)];
      ALL_TAC] THEN
    REWRITE_TAC[PASTECART_INJ; LIFT_EQ] THEN STRIP_TAC THEN
    CONJ_TAC THENL [ALL_TAC; UNDISCH_TAC `(t + &1) / &2 = (t' + &1) / &2` THEN
                    REAL_ARITH_TAC] THEN
    SUBGOAL_THEN `(x:real^3) IN {x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0} /\ (x':real^3) IN {x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0}` STRIP_ASSUME_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `&0 < d0` THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(g:real^3->real^(3,1)finite_sum) x = g x'` MP_TAC THENL
     [ONCE_ASM_REWRITE_TAC[] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o AP_TERM `f:real^(3,1)finite_sum->real^3`) THEN
    REWRITE_TAC[MATCH_MP (ASSUME `!y. y IN {x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0} ==> (f:real^(3,1)finite_sum->real^3) ((g:real^3->real^(3,1)finite_sum) y) = y`) (ASSUME `(x:real^3) IN {x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0}`);
                MATCH_MP (ASSUME `!y. y IN {x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0} ==> (f:real^(3,1)finite_sum->real^3) ((g:real^3->real^(3,1)finite_sum) y) = y`) (ASSUME `(x':real^3) IN {x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0}`)];
    X_GEN_TAC `z:real^3` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(z:real^3) IN {x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0}` ASSUME_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `abs((z:real^3)$3 - c) <= d0` THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(g:real^3->real^(3,1)finite_sum) z IN {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1]` MP_TAC THENL
     [ASM SET_TAC[]; ALL_TAC] THEN
    GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [GSYM PASTECART_FST_SND] THEN
    REWRITE_TAC[PASTECART_IN_PCROSS; IN_ELIM_THM; IN_INTERVAL_1; DROP_VEC] THEN
    STRIP_TAC THEN
    ABBREV_TAC `y = fstcart((g:real^3->real^(3,1)finite_sum) z)` THEN
    ABBREV_TAC `sz = sndcart((g:real^3->real^(3,1)finite_sum) z)` THEN
    SUBGOAL_THEN `pastecart (y:real^3) (lift(&1 / &2)) IN {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1]` ASSUME_TAC THENL
     [REWRITE_TAC[PASTECART_IN_PCROSS; IN_ELIM_THM; IN_INTERVAL_1; DROP_VEC;
                  LIFT_DROP] THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    EXISTS_TAC `(f:real^(3,1)finite_sum->real^3) (pastecart y (lift(&1 / &2)))` THEN
    EXISTS_TAC `&2 * drop sz - &1` THEN
    USE_THEN "fB" (fun th -> REWRITE_TAC[MATCH_MP th (ASSUME
      `pastecart (y:real^3) (lift(&1 / &2)) IN {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1]`)]) THEN
    MP_TAC(SPECL [`y:real^3`; `lift(&1 / &2)`] (ASSUME `!x s. x IN B /\ x$3 = c - d0 /\ s IN interval[vec 0:real^1,vec 1] ==> ((f:real^(3,1)finite_sum->real^3) (pastecart x s))$3 = c - d0 + drop s * &2 * d0`)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[IN_INTERVAL_1; DROP_VEC; LIFT_DROP] THEN REAL_ARITH_TAC;
      DISCH_THEN SUBST1_TAC] THEN
    REWRITE_TAC[LIFT_DROP] THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [UNDISCH_TAC `&0 <= drop sz` THEN UNDISCH_TAC `drop sz <= &1` THEN
      REAL_ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[MATCH_MP (ASSUME `!z. z IN {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1] ==> (g:real^3->real^(3,1)finite_sum) ((f:real^(3,1)finite_sum->real^3) z) = z`) (ASSUME
      `pastecart (y:real^3) (lift(&1 / &2)) IN {x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1]`)] THEN
    REWRITE_TAC[FSTCART_PASTECART;
                REAL_ARITH `((&2 * x - &1) + &1) / &2 = x`; LIFT_DROP] THEN
    EXPAND_TAC "y" THEN EXPAND_TAC "sz" THEN REWRITE_TAC[PASTECART_FST_SND] THEN
    CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC(ASSUME `!y. y IN {x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0} ==> (f:real^(3,1)finite_sum->real^3) ((g:real^3->real^(3,1)finite_sum) y) = y`) THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN
     `(\p. (f:real^(3,1)finite_sum->real^3)
             (pastecart (fstcart((g:real^3->real^(3,1)finite_sum) (fstcart p)))
                        (lift((drop(sndcart p) + &1) / &2)))) =
      f o (\p. pastecart (fstcart(g (fstcart p)))
                         (lift((drop(sndcart (p:real^(3,1)finite_sum)) + &1) / &2)))`
    SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; o_THM]; ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
     [MATCH_MP_TAC CONTINUOUS_ON_PASTECART THEN CONJ_TAC THENL
       [MATCH_MP_TAC CONTINUOUS_ON_FSTCART THEN
        SUBGOAL_THEN `(\p. (g:real^3->real^(3,1)finite_sum)
                             (fstcart(p:real^(3,1)finite_sum))) =
                      g o fstcart` SUBST1_TAC THENL
         [REWRITE_TAC[FUN_EQ_THM; o_THM]; ALL_TAC] THEN
        MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN
        SIMP_TAC[LINEAR_CONTINUOUS_ON; LINEAR_FSTCART] THEN
        MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
        EXISTS_TAC `{x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0}` THEN ASM_REWRITE_TAC[] THEN
        REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; FORALL_IN_PCROSS;
                    FSTCART_PASTECART; IN_ELIM_THM] THEN
        REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
        UNDISCH_TAC `&0 < d0` THEN REAL_ARITH_TAC;
        REWRITE_TAC[MOI_S5C_LIFT_AFFINE] THEN
        MATCH_MP_TAC CONTINUOUS_ON_ADD THEN REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
        MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN
        SIMP_TAC[LINEAR_CONTINUOUS_ON; LINEAR_SNDCART]];
      MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `{x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1]` THEN
      ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; FORALL_IN_PCROSS;
                  FSTCART_PASTECART; SNDCART_PASTECART; IN_ELIM_THM] THEN
      MAP_EVERY X_GEN_TAC [`x:real^3`; `v:real^1`] THEN STRIP_TAC THEN
      USE_THEN "pin" (MP_TAC o SPECL [`x:real^3`; `drop v`]) THEN
      ANTS_TAC THENL [ALL_TAC; REWRITE_TAC[]] THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `(v:real^1) IN interval[--vec 1,vec 1]` THEN
      REWRITE_TAC[IN_INTERVAL_1; DROP_NEG; DROP_VEC] THEN REAL_ARITH_TAC];
    X_GEN_TAC `t:real` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(\x. (f:real^(3,1)finite_sum->real^3)
             (pastecart (fstcart((g:real^3->real^(3,1)finite_sum) x))
                        (lift((t + &1) / &2)))) =
      f o (\x. pastecart (fstcart(g x)) (lift((t + &1) / &2)))`
    SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; o_THM]; ALL_TAC] THEN
    SUBGOAL_THEN `locally_polyhedral {x:real^3 | x IN B /\ x$3 = c}`
    ASSUME_TAC THENL
     [MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
      MATCH_MP_TAC MOI_S5C_LEVEL_POLYHEDRON THEN
      REWRITE_TAC[PL_POLYHEDRON_EQ_SIMPLICIAL_COMPLEX] THEN
      EXISTS_TAC `K:(real^3->bool)->bool` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC PL_MAP_ON_COMPOSE THEN EXISTS_TAC `{x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1]` THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC PL_MAP_ON_PASTECART THEN
      ASM_SIMP_TAC[PL_MAP_ON_CONST] THEN
      SUBGOAL_THEN `(\x. fstcart((g:real^3->real^(3,1)finite_sum) x)) =
                    fstcart o g` SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM; o_THM]; ALL_TAC] THEN
      MATCH_MP_TAC PL_MAP_ON_COMPOSE THEN
      EXISTS_TAC `(:real^(3,1)finite_sum)` THEN
      SIMP_TAC[MOI_S5C_PL_LINEAR; LINEAR_FSTCART; LOCALLY_POLYHEDRAL_OPEN;
               OPEN_UNIV; SUBSET_UNIV] THEN
      MATCH_MP_TAC PL_MAP_ON_SUBSET THEN EXISTS_TAC `{x:real^3 | x IN B /\ c - d0 <= x$3 /\ x$3 <= c + d0}` THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MATCH_MP_TAC PL_MAP_ON_HOMEOMORPHISM_INVERSE THEN
        EXISTS_TAC `{x:real^3 | x IN B /\ x$3 = c - d0} PCROSS interval[vec 0:real^1,vec 1]` THEN
        EXISTS_TAC `f:real^(3,1)finite_sum->real^3` THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
        ASM_REWRITE_TAC[] THEN UNDISCH_TAC `&0 < d0` THEN REAL_ARITH_TAC];
      REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; IN_ELIM_THM] THEN
      X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
      USE_THEN "pin" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Theta-curve lemmas for spheres, disk replacement, inside transfer,        *)
(* sphere-disk lemmas (restated from pc_moi_s35_minb under MOI_S5C_ names).  *)
(* ------------------------------------------------------------------------- *)

let moi_s5c_flat = new_definition
 `moi_s5c_flat (t:real^N->bool) a3 o3 <=>
    !z. z IN o3
        ==> ?u u1 u2. open u /\ z IN u /\ u INTER t SUBSET a3 /\
                      u DIFF a3 = u1 UNION u2 /\ connected u1 /\ connected u2 /\
                      u INTER a3 SUBSET closure u1 INTER closure u2`;;

let MOI_S5C_COMPONENT_ABSORB = prove
 (`!g u1 w x:real^N.
     connected u1 /\ u1 SUBSET g /\ w IN u1 /\ w IN connected_component g x
     ==> u1 SUBSET connected_component g x`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(SUBST1_TAC o SYM o MATCH_MP CONNECTED_COMPONENT_EQ) THEN
  MATCH_MP_TAC CONNECTED_COMPONENT_MAXIMAL THEN ASM_REWRITE_TAC[]);;

let MOI_S5C_THETA_ADJ = prove
 (`!t a3 o3 (q:real^N).
     a3 SUBSET t /\ o3 SUBSET a3 /\ connected o3 /\ moi_s5c_flat t a3 o3
     ==> closure(connected_component ((:real^N) DIFF t) q) INTER o3 = {} \/
         o3 SUBSET closure(connected_component ((:real^N) DIFF t) q)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[moi_s5c_flat] THEN STRIP_TAC THEN
  ABBREV_TAC `Q = connected_component ((:real^N) DIFF t) q` THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [CONNECTED_CLOPEN]) THEN
  DISCH_THEN(MP_TAC o SPEC `o3 INTER closure Q:real^N->bool`) THEN
  ANTS_TAC THENL
   [ALL_TAC; SET_TAC[]] THEN
  CONJ_TAC THENL [ALL_TAC; SIMP_TAC[CLOSED_IN_CLOSED_INTER; CLOSED_CLOSURE]] THEN
  ONCE_REWRITE_TAC[OPEN_IN_SUBOPEN] THEN X_GEN_TAC `z:real^N` THEN
  REWRITE_TAC[IN_INTER] THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `z:real^N`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:real^N->bool` (X_CHOOSE_THEN `u1:real^N->bool`
    (X_CHOOSE_THEN `u2:real^N->bool` STRIP_ASSUME_TAC))) THEN
  EXISTS_TAC `o3 INTER u:real^N->bool` THEN
  ASM_SIMP_TAC[OPEN_IN_OPEN_INTER; IN_INTER] THEN
  SUBGOAL_THEN `~(u INTER (Q:real^N->bool) = {})` MP_TAC THENL
   [MP_TAC(ISPECL [`u:real^N->bool`; `Q:real^N->bool`]
      OPEN_INTER_CLOSURE_EQ_EMPTY) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    UNDISCH_TAC `(z:real^N) IN u` THEN
    UNDISCH_TAC `(z:real^N) IN closure Q` THEN SET_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:real^N` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `~((w:real^N) IN t)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(:real^N) DIFF t`; `q:real^N`]
      CONNECTED_COMPONENT_SUBSET) THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u1:real^N->bool) SUBSET (:real^N) DIFF t /\
                (u2:real^N->bool) SUBSET (:real^N) DIFF t`
  STRIP_ASSUME_TAC THENL [ASM SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(w:real^N) IN u1 \/ w IN u2` STRIP_ASSUME_TAC THENL
   [ASM SET_TAC[];
    MP_TAC(ISPECL [`(:real^N) DIFF t`; `u1:real^N->bool`; `w:real^N`; `q:real^N`]
      MOI_S5C_COMPONENT_ABSORB) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o MATCH_MP SUBSET_CLOSURE) THEN
    ASM SET_TAC[];
    MP_TAC(ISPECL [`(:real^N) DIFF t`; `u2:real^N->bool`; `w:real^N`; `q:real^N`]
      MOI_S5C_COMPONENT_ABSORB) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o MATCH_MP SUBSET_CLOSURE) THEN
    ASM SET_TAC[]]);;

let MOI_S5C_PIGEON3 = prove
 (`!c1 c2 c3 v1 v2:A->bool.
     DISJOINT c1 c2 /\ DISJOINT c1 c3 /\ DISJOINT c2 c3 /\
     (v1 SUBSET c1 /\ ~(v1 = {}) \/ v2 SUBSET c1 /\ ~(v2 = {})) /\
     (v1 SUBSET c2 /\ ~(v1 = {}) \/ v2 SUBSET c2 /\ ~(v2 = {})) /\
     (v1 SUBSET c3 /\ ~(v1 = {}) \/ v2 SUBSET c3 /\ ~(v2 = {}))
     ==> F`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[DISJOINT; GSYM MEMBER_NOT_EMPTY] THEN
  REPEAT STRIP_TAC THEN ASM SET_TAC[]);;

let MOI_S5C_FLAT_COMPONENT = prove
 (`!t a3 u u1 u2 z (x:real^N).
     a3 SUBSET t /\ open u /\ z IN u /\ u INTER t SUBSET a3 /\
     u DIFF a3 = u1 UNION u2 /\
     connected u1 /\ connected u2 /\
     z IN closure(connected_component ((:real^N) DIFF t) x)
     ==> u1 SUBSET connected_component ((:real^N) DIFF t) x /\ ~(u1 = {}) \/
         u2 SUBSET connected_component ((:real^N) DIFF t) x /\ ~(u2 = {})`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `Q = connected_component ((:real^N) DIFF t) x` THEN
  SUBGOAL_THEN `~(u INTER (Q:real^N->bool) = {})` MP_TAC THENL
   [MP_TAC(ISPECL [`u:real^N->bool`; `Q:real^N->bool`]
      OPEN_INTER_CLOSURE_EQ_EMPTY) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    UNDISCH_TAC `(z:real^N) IN u` THEN
    UNDISCH_TAC `(z:real^N) IN closure Q` THEN SET_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:real^N` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(Q:real^N->bool) SUBSET (:real^N) DIFF t` ASSUME_TAC THENL
   [EXPAND_TAC "Q" THEN REWRITE_TAC[CONNECTED_COMPONENT_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `(w:real^N) IN u1 \/ w IN u2` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `u DIFF a3 = (u1 UNION u2):real^N->bool` THEN
    UNDISCH_TAC `u INTER t SUBSET (a3:real^N->bool)` THEN
    UNDISCH_TAC `a3 SUBSET (t:real^N->bool)` THEN
    UNDISCH_TAC `(Q:real^N->bool) SUBSET (:real^N) DIFF t` THEN
    UNDISCH_TAC `(w:real^N) IN Q` THEN UNDISCH_TAC `(w:real^N) IN u` THEN
    SET_TAC[];
    DISJ1_TAC THEN CONJ_TAC THENL
     [EXPAND_TAC "Q" THEN MATCH_MP_TAC MOI_S5C_COMPONENT_ABSORB THEN
      EXISTS_TAC `w:real^N` THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `u DIFF a3 = (u1 UNION u2):real^N->bool` THEN
      UNDISCH_TAC `u INTER t SUBSET (a3:real^N->bool)` THEN SET_TAC[];
      UNDISCH_TAC `(w:real^N) IN u1` THEN SET_TAC[]];
    DISJ2_TAC THEN CONJ_TAC THENL
     [EXPAND_TAC "Q" THEN MATCH_MP_TAC MOI_S5C_COMPONENT_ABSORB THEN
      EXISTS_TAC `w:real^N` THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `u DIFF a3 = (u1 UNION u2):real^N->bool` THEN
      UNDISCH_TAC `u INTER t SUBSET (a3:real^N->bool)` THEN SET_TAC[];
      UNDISCH_TAC `(w:real^N) IN u2` THEN SET_TAC[]]]);;

let MOI_S5C_THETA_TWO = prove
 (`!t a3 o3 x1 x2 (x3:real^N).
     a3 SUBSET t /\ moi_s5c_flat t a3 o3 /\ ~(o3 = {}) /\
     o3 SUBSET closure(connected_component ((:real^N) DIFF t) x1) /\
     o3 SUBSET closure(connected_component ((:real^N) DIFF t) x2) /\
     o3 SUBSET closure(connected_component ((:real^N) DIFF t) x3) /\
     DISJOINT (connected_component ((:real^N) DIFF t) x1)
              (connected_component ((:real^N) DIFF t) x2) /\
     DISJOINT (connected_component ((:real^N) DIFF t) x1)
              (connected_component ((:real^N) DIFF t) x3) /\
     DISJOINT (connected_component ((:real^N) DIFF t) x2)
              (connected_component ((:real^N) DIFF t) x3)
     ==> F`,
  REPEAT GEN_TAC THEN REWRITE_TAC[moi_s5c_flat] THEN STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `z:real^N` o
    REWRITE_RULE[GSYM MEMBER_NOT_EMPTY] o check (is_neg o concl)) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `z:real^N`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:real^N->bool` (X_CHOOSE_THEN `u1:real^N->bool`
    (X_CHOOSE_THEN `u2:real^N->bool` STRIP_ASSUME_TAC))) THEN
  MATCH_MP_TAC(ISPECL [`connected_component ((:real^N) DIFF t) x1`;
                       `connected_component ((:real^N) DIFF t) x2`;
                       `connected_component ((:real^N) DIFF t) x3`;
                       `u1:real^N->bool`; `u2:real^N->bool`] MOI_S5C_PIGEON3) THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
  MATCH_MP_TAC MOI_S5C_FLAT_COMPONENT THEN
  MAP_EVERY EXISTS_TAC [`a3:real^N->bool`; `u:real^N->bool`; `z:real^N`] THEN
  ASM_REWRITE_TAC[] THEN ASM SET_TAC[]);;

let MOI_S5C_CONN_SUB = prove
 (`!c e1 e2:real^N->bool.
     connected c /\ c SUBSET e1 UNION e2 /\ open e1 /\ open e2 /\
     e1 INTER e2 = {} /\ ~(c INTER e2 = {})
     ==> c SUBSET e2`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`e1 UNION e2:real^N->bool`; `c:real^N->bool`;
                 `e1:real^N->bool`; `e2:real^N->bool`]
    MOI_FN1_CONNECTED_SEPARATION) THEN
  ASM_REWRITE_TAC[SUBSET_REFL] THEN ASM SET_TAC[]);;

let MOI_S5C_FLAT_ADJ_POINT = prove
 (`!t a3 u u1 u2 z (w:real^N).
     a3 SUBSET t /\ z IN u /\ z IN a3 /\ u INTER t SUBSET a3 /\
     u DIFF a3 = u1 UNION u2 /\ connected u1 /\ connected u2 /\
     u INTER a3 SUBSET closure u1 INTER closure u2 /\ w IN u /\ ~(w IN a3)
     ==> z IN closure(connected_component ((:real^N) DIFF t) w)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(u1:real^N->bool) SUBSET (:real^N) DIFF t /\
                (u2:real^N->bool) SUBSET (:real^N) DIFF t`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `u DIFF a3 = (u1 UNION u2):real^N->bool` THEN
    UNDISCH_TAC `u INTER t SUBSET (a3:real^N->bool)` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(w:real^N) IN u1 \/ w IN u2` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `u DIFF a3 = (u1 UNION u2):real^N->bool` THEN
    UNDISCH_TAC `(w:real^N) IN u` THEN UNDISCH_TAC `~((w:real^N) IN a3)` THEN
    SET_TAC[];
    MP_TAC(ISPECL [`(:real^N) DIFF t`; `u1:real^N->bool`; `w:real^N`]
      CONNECTED_COMPONENT_MAXIMAL);
    MP_TAC(ISPECL [`(:real^N) DIFF t`; `u2:real^N->bool`; `w:real^N`]
      CONNECTED_COMPONENT_MAXIMAL)] THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o MATCH_MP SUBSET_CLOSURE) THEN
  UNDISCH_TAC `u INTER a3 SUBSET closure u1 INTER closure (u2:real^N->bool)` THEN
  UNDISCH_TAC `(z:real^N) IN u` THEN UNDISCH_TAC `(z:real^N) IN a3` THEN
  SET_TAC[]);;

let MOI_S5C_THETA_SPLIT = prove
 (`!a1 a2 a3 k P N I23 X23 CX CY:real^N->bool.
     closed a1 /\ closed a2 /\ closed a3 /\
     a1 INTER a2 = k /\ a1 INTER a3 = k /\ a2 INTER a3 = k /\
     connected (a3 DIFF k) /\ ~(a3 DIFF k = {}) /\
     moi_s5c_flat (a1 UNION a2 UNION a3) a3 (a3 DIFF k) /\
     open P /\ open N /\ connected P /\ P INTER N = {} /\
     P UNION N = (:real^N) DIFF (a1 UNION a2) /\
     a3 DIFF k SUBSET P /\
     open I23 /\ open X23 /\ connected I23 /\ ~(I23 = {}) /\
     I23 INTER X23 = {} /\
     I23 UNION X23 = (:real^N) DIFF (a2 UNION a3) /\
     a2 UNION a3 SUBSET closure I23 /\
     I23 SUBSET P /\ DISJOINT I23 (a1 UNION a2) /\
     open CX /\ open CY /\ CX INTER CY = {} /\
     CX UNION CY = (:real^N) DIFF (a1 UNION a3) /\
     a3 SUBSET closure CY /\
     (N UNION (a2 DIFF k) UNION I23) INTER (P INTER X23) = {} /\
     (N UNION (a2 DIFF k) UNION I23) UNION (P INTER X23) =
       (:real^N) DIFF (a1 UNION a3) /\
     N UNION (a2 DIFF k) UNION I23 SUBSET CX
     ==> N UNION (a2 DIFF k) UNION I23 = CX /\ P INTER X23 = CY`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `G = (:real^N) DIFF (a1 UNION a2 UNION a3)` THEN
  SUBGOAL_THEN `open(G:real^N->bool)` ASSUME_TAC THENL
   [EXPAND_TAC "G" THEN REWRITE_TAC[GSYM closed] THEN
    ASM_SIMP_TAC[CLOSED_UNION];
    ALL_TAC] THEN
  SUBGOAL_THEN `CY SUBSET P INTER (X23:real^N->bool)` ASSUME_TAC THENL
   [UNDISCH_TAC `CX INTER CY:real^N->bool = {}` THEN
    UNDISCH_TAC `CX UNION CY = (:real^N) DIFF (a1 UNION a3)` THEN
    UNDISCH_TAC `(N UNION (a2 DIFF k) UNION I23) UNION (P INTER X23) =
                 (:real^N) DIFF (a1 UNION a3)` THEN
    UNDISCH_TAC `N UNION (a2 DIFF k) UNION I23 SUBSET (CX:real^N->bool)` THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `P INTER (X23:real^N->bool) SUBSET G` ASSUME_TAC THENL
   [EXPAND_TAC "G" THEN
    UNDISCH_TAC `P UNION N = (:real^N) DIFF (a1 UNION a2)` THEN
    UNDISCH_TAC `I23 UNION X23 = (:real^N) DIFF (a2 UNION a3)` THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `G SUBSET (N UNION I23) UNION P INTER (X23:real^N->bool)`
  ASSUME_TAC THENL
   [EXPAND_TAC "G" THEN
    UNDISCH_TAC `P UNION N = (:real^N) DIFF (a1 UNION a2)` THEN
    UNDISCH_TAC `I23 UNION X23 = (:real^N) DIFF (a2 UNION a3)` THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(N UNION I23) INTER P INTER (X23:real^N->bool) = {}`
  ASSUME_TAC THENL
   [UNDISCH_TAC `P INTER N:real^N->bool = {}` THEN
    UNDISCH_TAC `I23 INTER X23:real^N->bool = {}` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `G SUBSET (CX UNION CY:real^N->bool)` ASSUME_TAC THENL
