      ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      UNDISCH_TAC `(z:real^N) IN u` THEN UNDISCH_TAC `(z:real^N) IN a3 DIFF k` THEN
      UNDISCH_TAC `a3 SUBSET closure(CY:real^N->bool)` THEN SET_TAC[];
