    ALL_TAC] THEN
  STRIP_TAC THENL
   [DISJ1_TAC THEN MATCH_MP_TAC MOI_S5C_THETA_SPLIT THEN
    MAP_EVERY EXISTS_TAC [`a1:real^N->bool`; `a3:real^N->bool`] THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
