    ALL_TAC] THEN
  SUBGOAL_THEN
   `(!y:real^2. y IN moi_s5c_tr <=>
                &1 <= y$1 /\ y$1 <= &2 /\ y$2 <= y$1 /\ --(y$2) <= y$1) /\
    (!y:real^2. y IN T1 <=>
                &1 <= y$2 /\ y$2 <= &2 /\ --(y$1) <= y$2 /\ y$1 <= y$2) /\
    (!y:real^2. y IN T2 <=>
                &1 <= --(y$1) /\ --(y$1) <= &2 /\ --(y$2) <= --(y$1) /\ y$2 <= --(y$1)) /\
    (!y:real^2. y IN T3 <=>
                &1 <= --(y$2) /\ --(y$2) <= &2 /\ y$1 <= --(y$2) /\ --(y$1) <= --(y$2))`
  (LABEL_TAC "sec") THENL
   [MAP_EVERY EXPAND_TAC ["T3"; "T2"; "T1"] THEN REWRITE_TAC[MOI_S5C_SECTORS];
    ALL_TAC] THEN
  SUBGOAL_THEN
