    ((moi_s5c_tr UNION T1) UNION T2) INTER T3 =
    segment[vector[&1;-- &1],vector[&2;-- &2]] UNION
    segment[vector[-- &1;-- &1],vector[-- &2;-- &2]] /\
    ((moi_s5c_tr UNION T1) UNION T2) UNION T3 =
    interval[--vector[&2;&2],vector[&2;&2]] DIFF
    interval(--vector[&1;&1],vector[&1;&1]):real^2->bool`
