    REPEAT CONJ_TAC THEN GEN_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`moi_s5c_tr`; `T1:real^2->bool`; `moi_s5c_tr`; `T1:real^2->bool`;
