      MATCH_MP_TAC MOI_S5C_REFLECT_SEG THEN REWRITE_TAC[MOI_S5C_SQ_SEGS] THEN
      X_GEN_TAC `y:real^2` THEN STRIP_TAC THEN ASM_SIMP_TAC[] THEN
      REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2; VECTOR_ADD_COMPONENT;
                  VECTOR_SUB_COMPONENT] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  ABBREV_TAC `G1 = \x:real^2. if x IN moi_s5c_tr then (s0:real^2->real^2) x else s1 x` THEN
  ABBREV_TAC `G1' = \x:real^2. if x IN moi_s5c_tr then (s0':real^2->real^2) x
                               else s1' x` THEN
  DISCH_TAC THEN
  SUBGOAL_THEN
   `!y:real^2. y$1 = --(y$2) /\ &1 <= y$2 /\ y$2 <= &2
