let moi_s5c_otube = new_definition
 `moi_s5c_otube =
    {x:real^3 | &3 / &16 < moi_s35_n x /\ moi_s35_n x < &5 / &16 /\
                abs(x$3) < &1 / &32}`;;

let MOI_S5C_OTUBE = prove
 (`open moi_s5c_otube /\ moi_s5c_otube SUBSET moi_s35_ttube /\
