    ALL_TAC] THEN
  SUBGOAL_THEN `moi_s5c_otube SUBSET moi_s35_ttube` ASSUME_TAC THENL
   [REWRITE_TAC[moi_s5c_otube; moi_s35_ttube; SUBSET; IN_ELIM_THM] THEN
