        try fst(dest_const(rator(rator(concl th)))) = "pl_homeomorphism"
        with Failure _ -> false)) THEN
    FIRST_X_ASSUM(SUBST1_TAC o SYM o check (fun th ->
      try rhs(concl th) = `B:real^3->bool` &&
