 (`!(B:real^3->bool) c d0 Q k s a b.
     compact B /\ moi_s5c_collar B c d0 Q /\
     open_in (subtopology euclidean {x | x IN B /\ x$3 = c}) k /\
     (s = &1 \/ s = -- &1) /\ -- &1 <= a /\ a < b /\ b <= &1
     ==> open_in (subtopology euclidean B) {Q x (s * u) | x IN k /\ a < u /\ u < b}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
  REWRITE_TAC[MOI_S5C_SIDE_FLIP] THEN MATCH_MP_TAC MOI_S5C_COLLAR_OPEN THEN
  MAP_EVERY EXISTS_TAC [`c:real`; `d0:real`] THEN ASM_REWRITE_TAC[] THEN
  ASM_REAL_ARITH_TAC);;

let MOI_S5C_SIDE_CONN = prove
 (`!(B:real^3->bool) c d0 Q k s a b.
     moi_s5c_collar B c d0 Q /\ k SUBSET {x | x IN B /\ x$3 = c} /\
     connected k /\ (s = &1 \/ s = -- &1) /\ -- &1 <= a /\ b <= &1
     ==> connected {Q x (s * u) | x IN k /\ a < u /\ u < b} /\
         connected {Q x (s * u) | x IN k /\ a <= u /\ u <= b}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
  REWRITE_TAC[MOI_S5C_SIDE_FLIP; REAL_MUL_LID] THEN REWRITE_TAC[MOI_S5C_REAL_INTERVALS] THEN
  CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_COLLAR_CONN0 THEN
  MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `c:real`; `d0:real`] THEN
  ASM_REWRITE_TAC[] THEN
  SIMP_TAC[CONVEX_CONNECTED; CONVEX_INTERVAL] THEN
  REWRITE_TAC[SUBSET; IN_INTERVAL_1; DROP_NEG; DROP_VEC; LIFT_DROP] THEN
  UNDISCH_TAC `-- &1 <= a` THEN UNDISCH_TAC `b <= &1` THEN REAL_ARITH_TAC);;

let MOI_S5C_SIDE_COMPACT = prove
 (`!(B:real^3->bool) c d0 Q k s a b.
     moi_s5c_collar B c d0 Q /\ k SUBSET {x | x IN B /\ x$3 = c} /\
     compact k /\ (s = &1 \/ s = -- &1) /\ -- &1 <= a /\ b <= &1
     ==> compact {Q x (s * u) | x IN k /\ a <= u /\ u <= b}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
  REWRITE_TAC[MOI_S5C_SIDE_FLIP; REAL_MUL_LID] THEN REWRITE_TAC[MOI_S5C_REAL_INTERVALS] THEN
  MATCH_MP_TAC MOI_S5C_COLLAR_COMPACT0 THEN
  MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `c:real`; `d0:real`] THEN
  ASM_REWRITE_TAC[COMPACT_INTERVAL] THEN
  REWRITE_TAC[SUBSET; IN_INTERVAL_1; DROP_NEG; DROP_VEC; LIFT_DROP] THEN
  UNDISCH_TAC `-- &1 <= a` THEN UNDISCH_TAC `b <= &1` THEN REAL_ARITH_TAC);;

let MOI_S5C_LIFT_LINEAR = prove
 (`!c. moi_s35_lift c =
       (\y. (\y:real^2. vector[y$1; y$2; &0]:real^3) y + vector[&0; &0; c]) /\
       linear (\y:real^2. vector[y$1; y$2; &0]:real^3) /\
       (!y z. (\y:real^2. vector[y$1; y$2; &0]:real^3) y =
              (\y:real^2. vector[y$1; y$2; &0]:real^3) z ==> y = z)`,
  GEN_TAC THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; moi_s35_lift] THEN
    SIMP_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3; VECTOR_ADD_COMPONENT] THEN
    REAL_ARITH_TAC;
    REWRITE_TAC[linear] THEN
    SIMP_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3; VECTOR_ADD_COMPONENT;
             VECTOR_MUL_COMPONENT] THEN
    REAL_ARITH_TAC;
    SIMP_TAC[CART_EQ; DIMINDEX_3; DIMINDEX_2; FORALL_3; FORALL_2; VECTOR_3]]);;

let MOI_S5C_LIFT_SPHERE = prove
 (`!c j. pl_sphere 1 j ==> pl_sphere 1 (IMAGE (moi_s35_lift c) j)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `c:real` MOI_S5C_LIFT_LINEAR) THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC MOI_S5C_SPHERE_AFFINE THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

let MOI_S5C_LIFT_CELL = prove
 (`!c e j. pl_cell_with_boundary 2 e j
           ==> pl_cell_with_boundary 2 (IMAGE (moi_s35_lift c) e)
                                       (IMAGE (moi_s35_lift c) j)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `c:real` MOI_S5C_LIFT_LINEAR) THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC MOI_S5C_CELL_AFFINE THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

let MOI_S5C_PROJ_FACTS = prove
 (`linear moi_s5c_proj /\
   (!x y:real^3. x$3 = y$3 /\ moi_s5c_proj x = moi_s5c_proj y ==> x = y) /\
   (!x:real^3. max (abs((moi_s5c_proj x)$1)) (abs((moi_s5c_proj x)$2)) =
               moi_s35_n x)`,
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[linear; moi_s5c_proj] THEN
    SIMP_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2; VECTOR_ADD_COMPONENT;
             VECTOR_MUL_COMPONENT];
    REWRITE_TAC[moi_s5c_proj] THEN
    SIMP_TAC[CART_EQ; DIMINDEX_2; DIMINDEX_3; FORALL_2; FORALL_3; VECTOR_2] THEN
    MESON_TAC[];
    REWRITE_TAC[moi_s5c_proj; moi_s35_n] THEN SIMP_TAC[VECTOR_2]]);;

let MOI_S5C_CELL_POLYHEDRON = prove
 (`!n (e:real^N->bool) j. pl_cell_with_boundary n e j ==> pl_polyhedron e`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_cell_with_boundary] THEN
  DISCH_THEN(X_CHOOSE_THEN `k:real^N->bool` (X_CHOOSE_THEN `f:real^N->real^N`
    (X_CHOOSE_THEN `g:real^N->real^N` STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN `e = IMAGE (f:real^N->real^N) k` SUBST1_TAC THENL
   [ASM_MESON_TAC[pl_homeomorphism; homeomorphism]; ALL_TAC] THEN
  MATCH_MP_TAC PL_POLYHEDRON_PL_IMAGE THEN CONJ_TAC THENL
   [MATCH_MP_TAC POLYTOPE_IMP_PL_POLYHEDRON THEN ASM_MESON_TAC[SIMPLEX_IMP_POLYTOPE];
    ASM_MESON_TAC[pl_homeomorphism]]);;

let MOI_S5C_FINITE_COMPONENTS_UNIONS = prove
 (`!f:(real^N->bool)->bool.
     FINITE f /\ (!c. c IN f ==> connected c) ==> FINITE (components (UNIONS f))`,
  REWRITE_TAC[IMP_CONJ] THEN MATCH_MP_TAC FINITE_INDUCT_STRONG THEN
  REWRITE_TAC[UNIONS_0; UNIONS_INSERT; COMPONENTS_EMPTY; FINITE_EMPTY;
              FORALL_IN_INSERT] THEN
  REPEAT STRIP_TAC THEN MATCH_MP_TAC FINITE_COMPONENTS_UNION THEN
  CONJ_TAC THENL [ALL_TAC; FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]] THEN
  ASM_CASES_TAC `x:real^N->bool = {}` THEN
  ASM_REWRITE_TAC[COMPONENTS_EMPTY; FINITE_EMPTY] THEN
  SUBGOAL_THEN `components(x:real^N->bool) = {x}` SUBST1_TAC THENL
   [ASM_REWRITE_TAC[COMPONENTS_EQ_SING]; REWRITE_TAC[FINITE_SING]]);;

let MOI_S5C_FINITE_COMP_HALF = prove
 (`!(K:(real^N->bool)->bool) H.
     FINITE K /\ (!s. s IN K ==> convex s) /\ convex H
     ==> FINITE (components (UNIONS K INTER H))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `UNIONS K INTER H = UNIONS {s INTER H | (s:real^N->bool) IN K}`
  SUBST1_TAC THENL
   [REWRITE_TAC[INTER_UNIONS] THEN AP_TERM_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC MOI_S5C_FINITE_COMPONENTS_UNIONS THEN
  ASM_SIMP_TAC[SIMPLE_IMAGE; FINITE_IMAGE; FORALL_IN_IMAGE] THEN
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CONVEX_CONNECTED THEN
  MATCH_MP_TAC CONVEX_INTER THEN ASM_SIMP_TAC[]);;

let MOI_S5C_COMPONENTS_PARTITION = prove
 (`!f:(real^N->bool)->bool.
     FINITE f /\ (!c. c IN f ==> closed c /\ connected c /\ ~(c = {})) /\
     (!c c'. c IN f /\ c' IN f /\ ~(c = c') ==> DISJOINT c c')
     ==> components (UNIONS f) = f`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC COMPONENTS_UNIQUE THEN REWRITE_TAC[] THEN
  X_GEN_TAC `c:real^N->bool` THEN DISCH_TAC THEN
  REPEAT CONJ_TAC THENL [ASM_MESON_TAC[]; ASM_MESON_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `c':real^N->bool` THEN STRIP_TAC THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `DISJOINT (c:real^N->bool) (UNIONS (f DELETE c))` ASSUME_TAC THENL
   [REWRITE_TAC[DISJOINT; INTER_UNIONS; EMPTY_UNIONS; FORALL_IN_GSPEC; IN_DELETE] THEN
    X_GEN_TAC `t:real^N->bool` THEN STRIP_TAC THEN
    REWRITE_TAC[GSYM DISJOINT] THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`c':real^N->bool`; `c:real^N->bool`;
                 `UNIONS (f DELETE (c:real^N->bool))`] MOI_S5C_CONN_TWO_CLOSED) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CLOSED_UNIONS THEN ASM_SIMP_TAC[FINITE_DELETE; IN_DELETE];
      UNDISCH_TAC `(c':real^N->bool) SUBSET UNIONS f` THEN SET_TAC[];
      UNDISCH_TAC `DISJOINT (c:real^N->bool) (UNIONS (f DELETE c))` THEN SET_TAC[]];
    ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `?y:real^N. y IN c` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[MEMBER_NOT_EMPTY]; ALL_TAC] THEN
  UNDISCH_TAC `DISJOINT (c:real^N->bool) (UNIONS (f DELETE c))` THEN
  UNDISCH_TAC `(c':real^N->bool) SUBSET UNIONS (f DELETE c)` THEN
  UNDISCH_TAC `(c:real^N->bool) SUBSET c'` THEN
  UNDISCH_TAC `(y:real^N) IN c` THEN SET_TAC[]);;

let MOI_S5C_CELL_CONNECTED = prove
 (`!n (e:real^N->bool) j. pl_cell_with_boundary n e j ==> connected e`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_cell_with_boundary] THEN
  DISCH_THEN(X_CHOOSE_THEN `k:real^N->bool` (X_CHOOSE_THEN `f:real^N->real^N`
    (X_CHOOSE_THEN `g:real^N->real^N` STRIP_ASSUME_TAC))) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[homeomorphism] o CONJUNCT1 o
    GEN_REWRITE_RULE I [pl_homeomorphism]) THEN
  FIRST_X_ASSUM(SUBST1_TAC o SYM o check (fun th ->
    try rhs(concl th) = `e:real^N->bool` with Failure _ -> false)) THEN
  MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[SIMPLEX_IMP_CONVEX; CONVEX_CONNECTED]);;

(* ------------------------------------------------------------------------- *)
(* The model hypotheses and output of the annulus swap, transport of         *)
(* PL cells between spaces, and the passage from edge_conf to the model.     *)
(* ------------------------------------------------------------------------- *)

let moi_s5c_clause = new_definition
 `moi_s5c_clause (X:real^3->bool) <=>
    ?k0. k0 IN components X /\
         !k. k IN components X /\ ~(k = k0) ==> k SUBSET moi_s35_ttube`;;

let moi_s5c_hyp = new_definition
 `moi_s5c_hyp (B:real^3->bool) c <=>
    (!k. k IN components {x | x IN B /\ x$3 = c} ==> moi_s35_ess c k) /\
    2 <= CARD (components {x | x IN B /\ x$3 = c}) /\
    (!k. k IN components {x | x IN B /\ x$3 = c}
         ==> ~(?d. pl_cell_with_boundary 2 d k /\ d SUBSET B)) /\
    moi_s5c_clause {x | x IN B /\ x$3 <= c} /\
    moi_s5c_clause {x | x IN B /\ c <= x$3}`;;

let MOI_S5C_SIMPLEX2_R3 = prove
 (`&2 simplex (convex hull {vec 0:real^3, basis 1, basis 2})`,
  REWRITE_TAC[MOI_PL2_SIMPLEX_2] THEN
  MAP_EVERY EXISTS_TAC [`vec 0:real^3`; `basis 1:real^3`; `basis 2:real^3`] THEN
  REWRITE_TAC[COLLINEAR_LEMMA_ALT; DE_MORGAN_THM; NOT_EXISTS_THM] THEN
  CONJ_TAC THENL
   [ONCE_REWRITE_TAC[EQ_SYM_EQ] THEN SIMP_TAC[BASIS_NONZERO; DIMINDEX_3; ARITH];
    X_GEN_TAC `u:real` THEN DISCH_THEN(MP_TAC o AP_TERM `\x:real^3. x$2`) THEN
    SIMP_TAC[VECTOR_ADD_COMPONENT; VECTOR_SUB_COMPONENT; VECTOR_MUL_COMPONENT;
             VEC_COMPONENT; BASIS_COMPONENT; DIMINDEX_3; ARITH] THEN
    REAL_ARITH_TAC]);;

let MOI_S5C_CELL_PLH = prove
 (`!n (e:real^M->bool) j (e':real^N->bool) h h'.
     pl_cell_with_boundary n e j /\ pl_homeomorphism (e,e') (h,h') /\
     (?k:real^N->bool. &n simplex k)
     ==> pl_cell_with_boundary n e' (IMAGE h j)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_cell_with_boundary] THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `k1:real^M->bool` (X_CHOOSE_THEN `F1:real^M->real^M`
      (X_CHOOSE_THEN `G1:real^M->real^M` STRIP_ASSUME_TAC)))
    (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_TAC `k2:real^N->bool`))) THEN
  MP_TAC(ISPECL [`k2:real^N->bool`; `k1:real^M->bool`; `&n:int`] MOI_FM3_SIMPLEX_PLH) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:real^N->real^M` (X_CHOOSE_THEN `q:real^M->real^N`
    STRIP_ASSUME_TAC)) THEN
  EXISTS_TAC `k2:real^N->bool` THEN
  EXISTS_TAC `(h:real^M->real^N) o (F1:real^M->real^M) o (p:real^N->real^M)` THEN
  EXISTS_TAC `((q:real^M->real^N) o (G1:real^M->real^M)) o (h':real^N->real^M)` THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `e:real^M->bool` THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
    EXISTS_TAC `k1:real^M->bool` THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[IMAGE_o] THEN
    SUBGOAL_THEN `IMAGE (p:real^N->real^M) (relative_frontier k2) = relative_frontier k1`
      (fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[pl_homeomorphism; homeomorphism]]);;
let MOI_S5C_LEVEL_DIST = prove
 (`!(B:real^3->bool) W c.
     compact B /\ open W /\ {x | x IN B /\ x$3 = c} SUBSET W
     ==> ?d. &0 < d /\ !x. x IN B /\ abs(x$3 - c) <= d ==> x IN W`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`IMAGE (\x:real^3. lift(x$3)) (B DIFF W)`; `lift c`]
    SEPARATE_POINT_CLOSED) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC COMPACT_IMP_CLOSED THEN MATCH_MP_TAC COMPACT_CONTINUOUS_IMAGE THEN
      ASM_SIMP_TAC[COMPACT_DIFF; CONTINUOUS_ON_LIFT_COMPONENT; DIMINDEX_3; ARITH];
      REWRITE_TAC[IN_IMAGE; IN_DIFF; LIFT_EQ] THEN
      UNDISCH_TAC `{x | x IN B /\ x$3 = c} SUBSET (W:real^3->bool)` THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[FORALL_IN_IMAGE; IN_DIFF; DIST_LIFT] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `d / &2` THEN ASM_REWRITE_TAC[REAL_HALF] THEN
  X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3`) THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `(x:real^3) IN W` THEN ASM_REWRITE_TAC[] THEN
  ASM_REAL_ARITH_TAC);;

let MOI_S5C_VERTEX_GAP = prove
 (`!(K:(real^3->bool)->bool) c.
     FINITE K /\ (!v. {v} IN K ==> ~(v$3 = c))
     ==> ?e. &0 < e /\ !v. {v} IN K ==> e <= abs(v$3 - c)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`IMAGE (\x:real^3. lift(x$3)) {v | {v} IN K}`; `lift c`]
    SEPARATE_POINT_CLOSED) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_IMP_CLOSED THEN MATCH_MP_TAC FINITE_IMAGE THEN
      MATCH_MP_TAC FINITE_IMAGE_INJ THEN ASM_REWRITE_TAC[] THEN SET_TAC[];
      REWRITE_TAC[IN_IMAGE; IN_ELIM_THM; LIFT_EQ] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[FORALL_IN_IMAGE; IN_ELIM_THM; DIST_LIFT] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `e:real` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `v:real^3` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `v:real^3`) THEN ASM_REWRITE_TAC[] THEN
  REAL_ARITH_TAC);;
let MOI_S5C_SETUP = prove
 (mk_imp(MOI_S35_SLAB_PRODUCT,
 `!phi xa xb ww b b0 b1 c.
     moi_s35_edge_conf phi xa xb ww b b0 b1 c /\
     FINITE (components (moi_s35_circles phi b c)) /\
     (!k. k IN components (moi_s35_circles phi b c)
          ==> ?j:real^2->bool. pl_sphere 1 j /\ k = IMAGE (moi_s35_lift c) j) /\
     (!k. k IN components (moi_s35_circles phi b c)
          ==> (moi_s35_ess c k <=>
               ~(?d. pl_cell_with_boundary 2 d (IMAGE phi k) /\ d SUBSET b))) /\
     (!k. k IN components (moi_s35_circles phi b c) ==> moi_s35_ess c k) /\
     2 <= CARD (components (moi_s35_circles phi b c))
     ==> ?K FF GG Q d0 psi.
           moi_s5c_mset {x | x IN moi_s35_dom /\ phi x IN b} K FF GG Q c d0 /\
           moi_s5c_hyp {x | x IN moi_s35_dom /\ phi x IN b} c /\
           pl_homeomorphism ({x | x IN moi_s35_dom /\ phi x IN b},b) (phi,psi) /\
           IMAGE phi (IMAGE FF (relative_frontier
             (interval[--vector[&1;&1]:real^2,vector[&1;&1]]))) = b0 /\
           IMAGE phi (IMAGE FF (relative_frontier
             (interval[--vector[&2;&2]:real^2,vector[&2;&2]]))) = b1`),
  DISCH_TAC THEN
  MAP_EVERY X_GEN_TAC [`phi:real^3->real^3`; `xa:real^3->bool`; `xb:real^3->bool`;
    `ww:real^3->bool`; `b:real^3->bool`; `b0:real^3->bool`; `b1:real^3->bool`;
    `c:real`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 MP_TAC STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[moi_s35_edge_conf] THEN STRIP_TAC THEN
  ABBREV_TAC `B = {x | x IN moi_s35_dom /\ (phi:real^3->real^3) x IN b}` THEN
  SUBGOAL_THEN `moi_s35_circles (phi:real^3->real^3) b c = {x | x IN B /\ x$3 = c}`
  (fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th]) THEN ASSUME_TAC th) THENL
   [EXPAND_TAC "B" THEN REWRITE_TAC[moi_s35_circles; IN_ELIM_THM; CONJ_ASSOC];
    ALL_TAC] THEN
  SUBGOAL_THEN `{x | x IN moi_s35_dom /\ (phi:real^3->real^3) x IN b /\ x$3 <= c} =
                {x | x IN B /\ x$3 <= c} /\
                {x | x IN moi_s35_dom /\ (phi:real^3->real^3) x IN b /\ c <= x$3} =
                {x | x IN B /\ c <= x$3}`
  (fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THENL
   [EXPAND_TAC "B" THEN REWRITE_TAC[IN_ELIM_THM; CONJ_ASSOC]; ALL_TAC] THEN
  MP_TAC(ISPECL [`phi:real^3->real^3`; `b:real^3->bool`] MOI_S5C_B_SUB) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `compact(B:real^3->bool) /\ pl_polyhedron(B:real^3->bool)`
  STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `pl_polyhedron(B:real^3->bool)` ASSUME_TAC THENL
     [REWRITE_TAC[PL_POLYHEDRON_EQ_SIMPLICIAL_COMPLEX] THEN ASM_MESON_TAC[];
      ASM_SIMP_TAC[PL_POLYHEDRON_IMP_COMPACT]];
    ALL_TAC] THEN
  SUBGOAL_THEN `B SUBSET moi_s35_dom` ASSUME_TAC THENL
   [EXPAND_TAC "B" THEN SET_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `phi:real^3->real^3`] MOI_S5C_PL_EMBED) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC PL_MAP_ON_SUBSET THEN EXISTS_TAC `moi_s35_dom` THEN
      ASM_SIMP_TAC[LOCALLY_POLYHEDRAL_PL_POLYHEDRON];
      ASM SET_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `psi:real^3->real^3`) THEN
  FIRST_ASSUM(MP_TAC o REWRITE_RULE[pl_annulus_with_ends] o check
    (MOI_S5C_HEAD "pl_annulus_with_ends")) THEN
  DISCH_THEN(X_CHOOSE_THEN `f:real^2->real^3` (X_CHOOSE_THEN `g:real^3->real^2`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN
   `pl_homeomorphism
      (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
       interval(--vector[&1;&1]:real^2,vector[&1;&1]),B)
      ((psi:real^3->real^3) o (f:real^2->real^3),(g:real^3->real^2) o (phi:real^3->real^3))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `b:real^3->bool` THEN
    ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!y. y IN b ==> (phi:real^3->real^3) (psi y) = y` ASSUME_TAC THENL
   [UNDISCH_TAC `pl_homeomorphism (B,b) ((phi:real^3->real^3),(psi:real^3->real^3))` THEN
    REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN CONV_TAC TAUT;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (f:real^2->real^3) (relative_frontier
      (interval[--vector[&1;&1]:real^2,vector[&1;&1]])) SUBSET b /\
    IMAGE (f:real^2->real^3) (relative_frontier
      (interval[--vector[&2;&2]:real^2,vector[&2;&2]])) SUBSET b`
  STRIP_ASSUME_TAC THENL
   [MP_TAC MOI_S5C_A0_FACTS THEN
    FIRST_ASSUM(MP_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[homeomorphism] o
      CONJUNCT1 o REWRITE_RULE[pl_homeomorphism] o check (fun th ->
      concl th = `pl_homeomorphism
        (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
         interval(--vector[&1;&1]:real^2,vector[&1;&1]),b) (f:real^2->real^3,g)`)) THEN
    SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`k:(real^3->bool)->bool`; `c:real`] MOI_S5C_VERTEX_GAP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `e:real` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `{x | x IN B /\ x$3 = c} SUBSET
    {x | &3 / &16 < moi_s35_n x /\ moi_s35_n x < &5 / &16 /\ x$3 = c}`
  ASSUME_TAC THENL
   [UNDISCH_TAC `moi_s35_circles (phi:real^3->real^3) b c = {x | x IN B /\ x$3 = c}` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN MATCH_MP_TAC MOI_S5C_CIRCLES_FLAT THEN
    MAP_EVERY EXISTS_TAC [`xa:real^3->bool`; `xb:real^3->bool`] THEN
    ASM_SIMP_TAC[MOI_S5C_PL_BALL_3_FILL; COMPACT_IMP_CLOSED] THEN
    FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `moi_s5c_otube`; `c:real`] MOI_S5C_LEVEL_DIST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[MOI_S5C_OTUBE] THEN
    UNDISCH_TAC `{x | x IN B /\ x$3 = c} SUBSET
      {x | &3 / &16 < moi_s35_n x /\ moi_s35_n x < &5 / &16 /\ x$3 = c}` THEN
    UNDISCH_TAC `abs c <= &1 / &512` THEN
    REWRITE_TAC[SUBSET; IN_ELIM_THM; moi_s5c_otube] THEN
    MESON_TAC[REAL_ARITH `abs c <= &1 / &512 ==> abs c < &1 / &32`];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d1:real` STRIP_ASSUME_TAC) THEN
  ABBREV_TAC `d0 = min (e / &2) (min d1 (&1 / &64))` THEN
  SUBGOAL_THEN `&0 < d0 /\ d0 < e /\ d0 <= d1 /\ d0 <= &1 / &64` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "d0" THEN
    MAP_EVERY UNDISCH_TAC [`&0 < e`; `&0 < d1`] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!s. s IN k ==> aff_dim (s:real^3->bool) <= &2` ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_NO_3DIM THEN
    MAP_EVERY EXISTS_TAC [`(g:real^3->real^2) o (phi:real^3->real^3)`; `B:real^3->bool`] THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC
     `pl_homeomorphism
        (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
         interval(--vector[&1;&1]:real^2,vector[&1;&1]),B)
        ((psi:real^3->real^3) o (f:real^2->real^3),(g:real^3->real^2) o (phi:real^3->real^3))` THEN
    REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN MAP_EVERY X_GEN_TAC [`x:real^3`; `y:real^3`] THEN
    STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o AP_TERM `(psi:real^3->real^3) o (f:real^2->real^3)`) THEN
    ASM_SIMP_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`k:(real^3->bool)->bool`; `B:real^3->bool`; `c:real`; `d0:real`]
    (MATCH_MP MOI_S5C_COLLAR_EXISTS (ASSUME MOI_S35_SLAB_PRODUCT))) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN X_GEN_TAC `v:real^3` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `v:real^3` o check (fun th ->
      concl th = `!v. {v} IN k ==> e <= abs((v:real^3)$3 - c)`)) THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `Q:real^3->real->real^3`) THEN
  MAP_EVERY EXISTS_TAC
   [`k:(real^3->bool)->bool`; `(psi:real^3->real^3) o (f:real^2->real^3)`;
    `(g:real^3->real^2) o (phi:real^3->real^3)`; `Q:real^3->real->real^3`;
    `d0:real`; `psi:real^3->real^3`] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!s. s SUBSET relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
                 relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])
        ==> IMAGE (phi:real^3->real^3) (IMAGE ((psi:real^3->real^3) o (f:real^2->real^3)) s) =
            IMAGE f s`
  ASSUME_TAC THENL
   [GEN_TAC THEN DISCH_TAC THEN
    MATCH_MP_TAC(SET_RULE
     `(!y. y IN s ==> (p:real^3->real^3) (q y) = (r:real^2->real^3) y)
      ==> IMAGE p (IMAGE q s) = IMAGE r s`) THEN
    REWRITE_TAC[o_THM] THEN X_GEN_TAC `y:real^2` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
      concl th = `!y. y IN b ==> (phi:real^3->real^3) (psi y) = y`)) THEN
    MAP_EVERY UNDISCH_TAC
     [`IMAGE (f:real^2->real^3) (relative_frontier
        (interval[--vector[&1;&1]:real^2,vector[&1;&1]])) SUBSET b`;
      `IMAGE (f:real^2->real^3) (relative_frontier
        (interval[--vector[&2;&2]:real^2,vector[&2;&2]])) SUBSET b`;
      `(y:real^2) IN s`] THEN
    UNDISCH_TAC
     `s SUBSET relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
               relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])` THEN
    SET_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[moi_s5c_mset] THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [X_GEN_TAC `v:real^3` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `v:real^3` o check (fun th ->
        concl th = `!v. {v} IN k ==> e <= abs((v:real^3)$3 - c)`)) THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
        concl th = `!x. x IN B /\ abs((x:real^3)$3 - c) <= d1 ==> x IN moi_s5c_otube`)) THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
      X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
      UNDISCH_TAC `DISJOINT (b0 UNION b1) (IMAGE (phi:real^3->real^3) moi_s35_ttube)` THEN
      ASM_REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
      DISCH_THEN(MP_TAC o SPEC `(phi:real^3->real^3) x`) THEN
      ASM_SIMP_TAC[FUN_IN_IMAGE] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC
        `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
         relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])` o check
        (fun th -> is_forall(concl th) && free_in `psi:real^3->real^3` (concl th) &&
                   free_in `f:real^2->real^3` (concl th))) THEN
      REWRITE_TAC[SUBSET_REFL; IMAGE_UNION] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN
      UNDISCH_TAC `(x:real^3) IN
        IMAGE ((psi:real^3->real^3) o (f:real^2->real^3))
          (relative_frontier (interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION
        IMAGE ((psi:real^3->real^3) o (f:real^2->real^3))
          (relative_frontier (interval[--vector[&2;&2]:real^2,vector[&2;&2]]))` THEN
      SET_TAC[]];
    REWRITE_TAC[moi_s5c_hyp; moi_s5c_clause] THEN ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [X_GEN_TAC `kk:real^3->bool` THEN DISCH_TAC THEN
      DISCH_THEN(X_CHOOSE_THEN `d:real^3->bool` STRIP_ASSUME_TAC) THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `kk:real^3->bool` o check (fun th ->
        try free_in `moi_s35_ess c` (concl th) &&
            is_eq (rand (snd (strip_forall (concl th)))) with Failure _ -> false)) THEN
      ASM_SIMP_TAC[] THEN
      EXISTS_TAC `IMAGE (phi:real^3->real^3) d` THEN CONJ_TAC THENL
       [MATCH_MP_TAC MOI_S5C_CELL_TRANSPORT THEN
        MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `b:real^3->bool`; `psi:real^3->real^3`] THEN
        ASM_REWRITE_TAC[];
        UNDISCH_TAC `IMAGE (phi:real^3->real^3) B = b` THEN
        UNDISCH_TAC `d SUBSET (B:real^3->bool)` THEN SET_TAC[]];
      ASM_MESON_TAC[];
      ASM_MESON_TAC[]];
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> is_forall(concl th) &&
      free_in `psi:real^3->real^3` (concl th) && free_in `f:real^2->real^3` (concl th))) THEN
    SET_TAC[];
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> is_forall(concl th) &&
      free_in `psi:real^3->real^3` (concl th) && free_in `f:real^2->real^3` (concl th))) THEN
    SET_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The theta argument in final form, tube facts, transfer of closures       *)
(* and flat pieces through phi, and the output predicate of the model.     *)
(* ------------------------------------------------------------------------- *)

(* The theta argument for the annulus swap in its final form: S = a1 + a2   *)
(* and S' = a1 + a3 are 2-spheres, a2 + a3 bounds the region W (a solid   *)
(* torus in the application).  Then the fills of S and S' agree off the   *)
(* closure of W.                                                          *)

let MOI_S5C_JB_CLOSURE = prove
 (`!s:real^3->bool.
     pl_sphere 2 s
     ==> open (inside s) /\ open (outside s) /\ connected (inside s) /\
         connected (outside s) /\ inside s INTER outside s = {} /\
         inside s UNION outside s = (:real^3) DIFF s /\
         s SUBSET closure (inside s) /\ s SUBSET closure (outside s) /\
         bounded (inside s) /\ ~bounded (outside s)`,
  GEN_TAC THEN DISCH_THEN(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_PLSPH_JB) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY UNDISCH_TAC
   [`frontier(inside s:real^3->bool) = s`; `frontier(outside s:real^3->bool) = s`] THEN
  REWRITE_TAC[frontier] THEN SET_TAC[]);;

let MOI_S5C_THETA_APPLY = prove
 (`!S S' a1 a2 a3 k (W:real^3->bool).
     pl_sphere 2 S /\ pl_sphere 2 S' /\ S = a1 UNION a2 /\ S' = a1 UNION a3 /\
     closed a1 /\ closed a2 /\ closed a3 /\
     a1 INTER a2 = k /\ a1 INTER a3 = k /\ a2 INTER a3 = k /\
     connected (a2 DIFF k) /\ ~(a2 DIFF k = {}) /\
     connected (a3 DIFF k) /\ ~(a3 DIFF k = {}) /\
     moi_s5c_flat (a1 UNION a2 UNION a3) a3 (a3 DIFF k) /\
     open W /\ connected W /\ ~(W = {}) /\ bounded W /\
     closure W = W UNION a2 UNION a3 /\ DISJOINT W (a1 UNION a2 UNION a3)
     ==> (S' UNION inside S') DIFF closure W = (S UNION inside S) DIFF closure W`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP MOI_S5C_JB_CLOSURE (ASSUME `pl_sphere 2 (S:real^3->bool)`)) THEN
  MP_TAC(MATCH_MP MOI_S5C_JB_CLOSURE (ASSUME `pl_sphere 2 (S':real^3->bool)`)) THEN
  UNDISCH_TAC `S:real^3->bool = a1 UNION a2` THEN
  UNDISCH_TAC `S':real^3->bool = a1 UNION a3` THEN
  DISCH_THEN SUBST1_TAC THEN DISCH_THEN SUBST1_TAC THEN
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `DISJOINT (a1 UNION a2) (a3 DIFF k:real^3->bool)` ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`a1 INTER a3:real^3->bool = k`; `a2 INTER a3:real^3->bool = k`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `open((:real^3) DIFF closure W) /\
    W INTER ((:real^3) DIFF closure W) = {} /\
    W UNION ((:real^3) DIFF closure W) = (:real^3) DIFF (a2 UNION a3) /\
    a2 UNION a3 SUBSET closure W /\ DISJOINT W (a1 UNION a2:real^3->bool) /\
    bounded(closure W)`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[GSYM closed; CLOSED_CLOSURE] THEN ASM_SIMP_TAC[BOUNDED_CLOSURE] THEN
    MP_TAC(ISPEC `W:real^3->bool` CLOSURE_SUBSET) THEN
    UNDISCH_TAC `DISJOINT W (a1 UNION a2 UNION a3:real^3->bool)` THEN
    UNDISCH_TAC `closure W = W UNION a2 UNION a3:real^3->bool` THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `bounded(a2:real^3->bool) /\ bounded(a3:real^3->bool)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC BOUNDED_SUBSET THEN
    EXISTS_TAC `closure W:real^3->bool` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `a2 UNION a3 SUBSET closure(W:real^3->bool)` THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`a1 UNION a2:real^3->bool`; `a3 DIFF k:real^3->bool`]
    MOI_S5C_CONNECTED_SIDE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [MP_TAC(ISPECL [`a1:real^3->bool`; `a2:real^3->bool`; `a3:real^3->bool`;
                   `k:real^3->bool`; `inside(a1 UNION a2):real^3->bool`;
                   `outside(a1 UNION a2):real^3->bool`; `W:real^3->bool`;
                   `(:real^3) DIFF closure W`; `inside(a1 UNION a3):real^3->bool`;
                   `outside(a1 UNION a3):real^3->bool`] MOI_S5C_THETA_HALF) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
     [MP_TAC(ISPECL [`outside(a1 UNION a2):real^3->bool`;
                     `inside(a1 UNION a3):real^3->bool`] BOUNDED_SUBSET) THEN
      ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `outside (a1 UNION a2) UNION (a2 DIFF k) UNION W =
                   inside (a1 UNION a3):real^3->bool` THEN SET_TAC[];
      UNDISCH_TAC `inside (a1 UNION a2) INTER ((:real^3) DIFF (W UNION a2 UNION a3)) =
                   inside (a1 UNION a3)` THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN SET_TAC[]];
    MP_TAC(ISPECL [`a1:real^3->bool`; `a2:real^3->bool`; `a3:real^3->bool`;
                   `k:real^3->bool`; `outside(a1 UNION a2):real^3->bool`;
                   `inside(a1 UNION a2):real^3->bool`; `W:real^3->bool`;
                   `(:real^3) DIFF closure W`; `inside(a1 UNION a3):real^3->bool`;
                   `outside(a1 UNION a3):real^3->bool`] MOI_S5C_THETA_HALF) THEN
    SUBGOAL_THEN
     `outside (a1 UNION a2) INTER inside (a1 UNION a2):real^3->bool = {} /\
      outside (a1 UNION a2) UNION inside (a1 UNION a2) = (:real^3) DIFF (a1 UNION a2)`
    STRIP_ASSUME_TAC THENL
     [MAP_EVERY UNDISCH_TAC
       [`inside (a1 UNION a2) INTER outside (a1 UNION a2):real^3->bool = {}`;
        `inside (a1 UNION a2) UNION outside (a1 UNION a2) =
         (:real^3) DIFF (a1 UNION a2)`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
     [UNDISCH_TAC `inside (a1 UNION a2) UNION (a2 DIFF k) UNION W =
                   inside (a1 UNION a3):real^3->bool` THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN SET_TAC[];
      MP_TAC(ISPECL [`outside(a1 UNION a2):real^3->bool`;
                     `inside(a1 UNION a3) UNION (W UNION a2 UNION a3):real^3->bool`]
        BOUNDED_SUBSET) THEN
      ASM_REWRITE_TAC[BOUNDED_UNION] THEN
      UNDISCH_TAC `outside (a1 UNION a2) INTER ((:real^3) DIFF (W UNION a2 UNION a3)) =
                   inside (a1 UNION a3)` THEN SET_TAC[]]]);;
(* Elementary facts about the tubes and the transfer of closures, insides   *)
(* and flat pieces through the chart phi.                                  *)

let MOI_S5C_TUBES = prove
 (`closed moi_s35_ttube /\ bounded moi_s35_ttube /\ compact moi_s35_ttube /\
   moi_s35_ttube SUBSET interior moi_s35_stube /\
   closure moi_s5c_otube SUBSET moi_s35_ttube /\
   moi_s35_ttube SUBSET moi_s5c_u /\ moi_s35_ttube SUBSET moi_s35_cube /\
   interior moi_s35_stube SUBSET moi_s35_dom /\
   interior moi_s35_stube SUBSET moi_s5c_u`,
  SUBGOAL_THEN `closed moi_s35_ttube` ASSUME_TAC THENL
   [SUBGOAL_THEN
     `moi_s35_ttube =
      (({x:real^3 | x$1 >= &3 / &16} UNION {x | x$1 <= --(&3 / &16)}) UNION
       ({x | x$2 >= &3 / &16} UNION {x | x$2 <= --(&3 / &16)})) INTER
      (({x | x$1 >= --(&5 / &16)} INTER {x | x$1 <= &5 / &16}) INTER
       ({x | x$2 >= --(&5 / &16)} INTER {x | x$2 <= &5 / &16}) INTER
       ({x | x$3 >= --(&1 / &32)} INTER {x | x$3 <= &1 / &32}))`
    SUBST1_TAC THENL
     [REWRITE_TAC[moi_s35_ttube; moi_s35_n; EXTENSION; IN_UNION; IN_INTER;
                  IN_ELIM_THM; real_ge] THEN
      GEN_TAC THEN REAL_ARITH_TAC;
      REPEAT(MATCH_MP_TAC CLOSED_INTER ORELSE MATCH_MP_TAC CLOSED_UNION THEN
             CONJ_TAC) THEN
      REWRITE_TAC[CLOSED_HALFSPACE_COMPONENT_LE; CLOSED_HALFSPACE_COMPONENT_GE]];
    ALL_TAC] THEN
  SUBGOAL_THEN `bounded moi_s35_ttube` ASSUME_TAC THENL
   [MATCH_MP_TAC BOUNDED_SUBSET THEN EXISTS_TAC `moi_s35_cube` THEN
    REWRITE_TAC[moi_s35_cube; BOUNDED_INTERVAL] THEN
    REWRITE_TAC[moi_s35_ttube; moi_s35_n; SUBSET; IN_ELIM_THM; IN_INTERVAL;
                DIMINDEX_3; FORALL_3; VECTOR_NEG_COMPONENT; VEC_COMPONENT] THEN
    GEN_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `open {x:real^3 | &1 / &8 < moi_s35_n x /\ moi_s35_n x < &3 / &8 /\
                     abs(x$3) < &1 / &16}`
  ASSUME_TAC THENL
   [SUBGOAL_THEN
     `{x:real^3 | &1 / &8 < moi_s35_n x /\ moi_s35_n x < &3 / &8 /\
                  abs(x$3) < &1 / &16} =
      (({x:real^3 | x$1 > &1 / &8} UNION {x | x$1 < --(&1 / &8)}) UNION
       ({x | x$2 > &1 / &8} UNION {x | x$2 < --(&1 / &8)})) INTER
      (({x | x$1 > --(&3 / &8)} INTER {x | x$1 < &3 / &8}) INTER
       ({x | x$2 > --(&3 / &8)} INTER {x | x$2 < &3 / &8}) INTER
       ({x | x$3 > --(&1 / &16)} INTER {x | x$3 < &1 / &16}))`
    SUBST1_TAC THENL
     [REWRITE_TAC[moi_s35_n; EXTENSION; IN_UNION; IN_INTER; IN_ELIM_THM; real_gt] THEN
      GEN_TAC THEN REAL_ARITH_TAC;
      REPEAT(MATCH_MP_TAC OPEN_INTER ORELSE MATCH_MP_TAC OPEN_UNION THEN
             CONJ_TAC) THEN
      REWRITE_TAC[OPEN_HALFSPACE_COMPONENT_LT; OPEN_HALFSPACE_COMPONENT_GT]];
    ALL_TAC] THEN
  SUBGOAL_THEN `moi_s35_ttube SUBSET interior moi_s35_stube` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `{x:real^3 | &1 / &8 < moi_s35_n x /\ moi_s35_n x < &3 / &8 /\
                            abs(x$3) < &1 / &16}` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[moi_s35_ttube; SUBSET; IN_ELIM_THM] THEN GEN_TAC THEN REAL_ARITH_TAC;
      MATCH_MP_TAC INTERIOR_MAXIMAL THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[moi_s35_stube; SUBSET; IN_ELIM_THM] THEN GEN_TAC THEN
      REAL_ARITH_TAC];
    ALL_TAC] THEN
  ASM_SIMP_TAC[COMPACT_EQ_BOUNDED_CLOSED] THEN
  MP_TAC MOI_S5C_U_FACTS THEN MP_TAC MOI_S5C_OTUBE THEN
  MP_TAC(ISPEC `moi_s35_stube` INTERIOR_SUBSET) THEN
  REPEAT STRIP_TAC THENL
   [MATCH_MP_TAC CLOSURE_MINIMAL THEN ASM_REWRITE_TAC[];
    ASM SET_TAC[];
    REWRITE_TAC[moi_s35_ttube; moi_s35_cube; moi_s35_n; SUBSET; IN_ELIM_THM;
                IN_INTERVAL; DIMINDEX_3; FORALL_3; VECTOR_NEG_COMPONENT;
                VEC_COMPONENT] THEN
    GEN_TAC THEN REAL_ARITH_TAC;
    ASM SET_TAC[];
    ASM SET_TAC[]]);;

let MOI_S5C_PHI_CLOSURE = prove
 (`!(phi:real^3->real^3) U.
     pl_map_on moi_s35_dom phi /\ bounded U /\ closure U SUBSET moi_s35_dom
     ==> closure (IMAGE phi U) = IMAGE phi (closure U)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(phi:real^3->real^3) continuous_on closure U` ASSUME_TAC THENL
   [ASM_MESON_TAC[PL_MAP_ON_IMP_CONTINUOUS_ON; CONTINUOUS_ON_SUBSET]; ALL_TAC] THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [MATCH_MP_TAC CLOSURE_MINIMAL THEN CONJ_TAC THENL
     [MP_TAC(ISPEC `U:real^3->bool` CLOSURE_SUBSET) THEN SET_TAC[];
      MATCH_MP_TAC COMPACT_IMP_CLOSED THEN MATCH_MP_TAC COMPACT_CONTINUOUS_IMAGE THEN
      ASM_REWRITE_TAC[COMPACT_CLOSURE]];
    MATCH_MP_TAC IMAGE_CLOSURE_SUBSET THEN
    ASM_REWRITE_TAC[CLOSED_CLOSURE; CLOSURE_SUBSET]]);;

let MOI_S5C_INSIDE_SUBSET_FILL = prove
 (`!s t:real^N->bool. s SUBSET t ==> inside s SUBSET t UNION inside t`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP OUTSIDE_MONO) THEN
  REWRITE_TAC[INSIDE_OUTSIDE] THEN SET_TAC[]);;

let MOI_S5C_HALFBALL_CLOSURE = prove
 (`!z:real^3 r x.
     x IN ball(z,r) /\ x$3 = z$3
     ==> x IN closure {y | y IN ball(z,r) /\ z$3 < y$3} /\
         x IN closure {y | y IN ball(z,r) /\ y$3 < z$3}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_BALL] THEN STRIP_TAC THEN
  SUBGOAL_THEN `!e. &0 < e ==> ?t. &0 < t /\ t < e /\ dist(z:real^3,x) + t < r`
  ASSUME_TAC THENL
   [X_GEN_TAC `e:real` THEN DISCH_TAC THEN
    EXISTS_TAC `min (e / &2) ((r - dist(z:real^3,x)) / &2)` THEN
    MAP_EVERY UNDISCH_TAC [`&0 < e`; `dist(z:real^3,x) < r`] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!t. &0 < t ==> norm(t % basis 3:real^3) = t` ASSUME_TAC THENL
   [SIMP_TAC[NORM_MUL; NORM_BASIS; DIMINDEX_3; ARITH; REAL_MUL_RID] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[CLOSURE_APPROACHABLE; IN_ELIM_THM; IN_BALL] THEN
  CONJ_TAC THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `t:real` STRIP_ASSUME_TAC o C MATCH_MP
    (ASSUME `&0 < e`)) THENL
   [EXISTS_TAC `x + t % basis 3:real^3`; EXISTS_TAC `x - t % basis 3:real^3`] THEN
  REWRITE_TAC[VECTOR_ADD_COMPONENT; VECTOR_SUB_COMPONENT; VECTOR_MUL_COMPONENT] THEN
  SIMP_TAC[BASIS_COMPONENT; DIMINDEX_3; ARITH; REAL_MUL_RID] THEN
  REWRITE_TAC[NORM_ARITH `dist(x + y:real^3,x) = norm y /\ dist(x - y:real^3,x) = norm y`] THEN
  ASM_SIMP_TAC[] THEN REPEAT CONJ_TAC THEN TRY(ASM_REAL_ARITH_TAC) THEN
  MATCH_MP_TAC REAL_LET_TRANS THEN EXISTS_TAC `dist(z:real^3,x) + t` THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`z:real^3`; `x:real^3`; `t % basis 3:real^3`] (NORM_ARITH
    `!z x y:real^3. dist(z,x + y) <= dist(z,x) + norm y /\
                    dist(z,x - y) <= dist(z,x) + norm y`)) THEN
  ASM_SIMP_TAC[]);;

let MOI_S5C_FLAT_TRANSFER = prove
 (`!(phi:real^3->real^3) S b B N' kk0 a1 a2.
     pl_map_on moi_s35_dom phi /\
     (!x y. x IN moi_s35_dom /\ y IN moi_s35_dom /\ phi x = phi y ==> x = y) /\
     S INTER IMAGE phi moi_s35_ttube SUBSET b /\ IMAGE phi B = b /\
     B SUBSET moi_s35_dom /\ N' SUBSET moi_s35_dom /\ a1 UNION a2 = S /\
     (!z. z IN N' DIFF kk0
          ==> ?r. &0 < r /\ ball(z,r) SUBSET moi_s5c_otube /\ ball(z,r) INTER B = {} /\
                  !x. x IN ball(z,r) ==> (x IN N' <=> x$3 = z$3))
     ==> moi_s5c_flat (a1 UNION a2 UNION IMAGE phi N') (IMAGE phi N')
                      (IMAGE phi (N' DIFF kk0))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC MOI_S5C_TUBES THEN MP_TAC MOI_S5C_OTUBE THEN REPEAT STRIP_TAC THEN
  REWRITE_TAC[moi_s5c_flat; FORALL_IN_IMAGE] THEN X_GEN_TAC `z:real^3` THEN
  DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `z:real^3` o check (fun th ->
    is_forall(concl th) && free_in `kk0:real^3->bool` (concl th))) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `ball(z:real^3,r) SUBSET moi_s35_dom /\
                closure(ball(z:real^3,r)) SUBSET moi_s35_dom /\
                ball(z:real^3,r) SUBSET moi_s5c_u` STRIP_ASSUME_TAC THENL
   [MP_TAC MOI_S5C_U_FACTS THEN
    MP_TAC(ISPECL [`ball(z:real^3,r)`; `moi_s5c_otube`] SUBSET_CLOSURE) THEN
    ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(phi:real^3->real^3) continuous_on closure(ball(z,r))` ASSUME_TAC THENL
   [ASM_MESON_TAC[PL_MAP_ON_IMP_CONTINUOUS_ON; CONTINUOUS_ON_SUBSET]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`IMAGE (phi:real^3->real^3) (ball(z,r))`;
    `IMAGE (phi:real^3->real^3) {y | y IN ball(z,r) /\ z$3 < y$3}`;
    `IMAGE (phi:real^3->real^3) {y | y IN ball(z,r) /\ y$3 < z$3}`] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MOI_S5C_PHI_OPEN THEN ASM_REWRITE_TAC[OPEN_BALL];
    MATCH_MP_TAC FUN_IN_IMAGE THEN ASM_REWRITE_TAC[CENTRE_IN_BALL];
    REWRITE_TAC[GSYM UNION_ASSOC] THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[SUBSET; IN_INTER; IN_UNION; IN_IMAGE] THEN X_GEN_TAC `y:real^3` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `x:real^3` STRIP_ASSUME_TAC) MP_TAC) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `~((phi:real^3->real^3) x IN S)` ASSUME_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(phi:real^3->real^3) x IN b` MP_TAC THENL
       [UNDISCH_TAC `S INTER IMAGE (phi:real^3->real^3) moi_s35_ttube SUBSET b` THEN
        REWRITE_TAC[SUBSET; IN_INTER] THEN DISCH_THEN MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[] THEN MATCH_MP_TAC FUN_IN_IMAGE THEN ASM SET_TAC[];
        ALL_TAC] THEN
      UNDISCH_TAC `IMAGE (phi:real^3->real^3) B = b` THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[IN_IMAGE] THEN
      DISCH_THEN(X_CHOOSE_THEN `x':real^3` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `x':real^3 = x` SUBST_ALL_TAC THENL
       [FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> is_forall(concl th) &&
          free_in `moi_s35_dom` (concl th) && free_in `phi:real^3->real^3` (concl th))) THEN
        ASM SET_TAC[];
        UNDISCH_TAC `ball(z:real^3,r) INTER B = {}` THEN ASM SET_TAC[]];
      ASM_REWRITE_TAC[]];
    REWRITE_TAC[EXTENSION; IN_DIFF; IN_UNION; IN_IMAGE; IN_ELIM_THM] THEN
    X_GEN_TAC `y:real^3` THEN EQ_TAC THENL
     [DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `x:real^3` STRIP_ASSUME_TAC)
        ASSUME_TAC) THEN
      SUBGOAL_THEN `~((x:real^3)$3 = (z:real^3)$3)` MP_TAC THENL
       [DISCH_TAC THEN
        FIRST_X_ASSUM(MP_TAC o check (fun th -> is_neg(concl th) &&
          free_in `y:real^3` (concl th))) THEN
        REWRITE_TAC[] THEN EXISTS_TAC `x:real^3` THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[];
        ALL_TAC] THEN
      DISCH_THEN(DISJ_CASES_TAC o MATCH_MP (REAL_ARITH
        `~(a = b) ==> b < a \/ a < b`)) THENL
       [DISJ1_TAC; DISJ2_TAC] THEN EXISTS_TAC `x:real^3` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `x:real^3` STRIP_ASSUME_TAC)) THEN
      (CONJ_TAC THENL [EXISTS_TAC `x:real^3` THEN ASM_REWRITE_TAC[]; ALL_TAC]) THEN
      DISCH_THEN(X_CHOOSE_THEN `x':real^3` STRIP_ASSUME_TAC) THEN
      (SUBGOAL_THEN `x':real^3 = x` SUBST_ALL_TAC THENL
        [FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> is_forall(concl th) &&
           free_in `moi_s35_dom` (concl th) && free_in `phi:real^3->real^3` (concl th))) THEN
         ASM SET_TAC[];
         ALL_TAC]) THEN
      (SUBGOAL_THEN `(x:real^3)$3 = (z:real^3)$3` MP_TAC THENL
        [ASM_MESON_TAC[]; ASM_REAL_ARITH_TAC])];
    MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN CONJ_TAC THENL
     [MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
      EXISTS_TAC `closure(ball(z:real^3,r))` THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPEC `ball(z:real^3,r)` CLOSURE_SUBSET) THEN SET_TAC[];
      MATCH_MP_TAC CONVEX_CONNECTED THEN
      REWRITE_TAC[SET_RULE `{y:real^3 | y IN s /\ P y} = s INTER {y | P y}`] THEN
      MATCH_MP_TAC CONVEX_INTER THEN REWRITE_TAC[CONVEX_BALL] THEN
      REWRITE_TAC[REAL_ARITH `(a:real) < b <=> b > a`; CONVEX_HALFSPACE_COMPONENT_GT]];
    MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN CONJ_TAC THENL
     [MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
      EXISTS_TAC `closure(ball(z:real^3,r))` THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPEC `ball(z:real^3,r)` CLOSURE_SUBSET) THEN SET_TAC[];
      MATCH_MP_TAC CONVEX_CONNECTED THEN
      REWRITE_TAC[SET_RULE `{y:real^3 | y IN s /\ P y} = s INTER {y | P y}`] THEN
      MATCH_MP_TAC CONVEX_INTER THEN
      REWRITE_TAC[CONVEX_BALL; CONVEX_HALFSPACE_COMPONENT_LT]];
    REWRITE_TAC[SUBSET; IN_INTER; IN_IMAGE] THEN X_GEN_TAC `y:real^3` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `x:real^3` STRIP_ASSUME_TAC)
      (X_CHOOSE_THEN `x':real^3` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `x':real^3 = x` SUBST_ALL_TAC THENL
     [FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> is_forall(concl th) &&
        free_in `moi_s35_dom` (concl th) && free_in `phi:real^3->real^3` (concl th))) THEN
      ASM SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(x:real^3)$3 = (z:real^3)$3` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`z:real^3`; `r:real`; `x:real^3`] MOI_S5C_HALFBALL_CLOSURE) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[IN_INTER] THEN CONJ_TAC THEN
    MATCH_MP_TAC(SET_RULE `!x s t. x IN s /\ IMAGE (f:real^3->real^3) s SUBSET t
                                   ==> f x IN t`) THENL
     [EXISTS_TAC `closure {y | y IN ball(z,r) /\ (z:real^3)$3 < y$3}`;
      EXISTS_TAC `closure {y | y IN ball(z,r) /\ y$3 < (z:real^3)$3}`] THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC IMAGE_CLOSURE_SUBSET THEN
    REWRITE_TAC[CLOSED_CLOSURE; CLOSURE_SUBSET] THEN
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
    EXISTS_TAC `closure(ball(z:real^3,r))` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SUBSET_CLOSURE THEN SET_TAC[]]);;

(* The output of the model construction: the new                            *)
(* annulus B' = (B INTER B') UNION N' with the removed annulus Rem, the new  *)
(* planar annulus N' (both in the open tube, meeting the rest along kk0),  *)
(* the region U between them, the triangulation, the circles and (7).      *)

let moi_s5c_out = new_definition
 `moi_s5c_out (B:real^3->bool) (FF:real^2->real^3) c B' Rem N' U kk0 <=>
    pl_annulus_with_ends B'
      (IMAGE FF (relative_frontier (interval[--vector[&1;&1]:real^2,vector[&1;&1]])))
      (IMAGE FF (relative_frontier (interval[--vector[&2;&2]:real^2,vector[&2;&2]]))) /\
    B' SUBSET interior moi_s35_stube /\
    compact Rem /\ compact N' /\ compact (B INTER B') /\
    Rem SUBSET B /\ Rem SUBSET moi_s35_ttube /\ N' SUBSET moi_s5c_otube /\
    (B INTER B') UNION Rem = B /\ (B INTER B') UNION N' = B' /\
    (B INTER B') INTER Rem = kk0 /\ (B INTER B') INTER N' = kk0 /\ Rem INTER N' = kk0 /\
    connected (Rem DIFF kk0) /\ ~(Rem DIFF kk0 = {}) /\
    connected (N' DIFF kk0) /\ ~(N' DIFF kk0 = {}) /\
    (!z. z IN N' DIFF kk0
         ==> ?r. &0 < r /\ ball(z,r) SUBSET moi_s5c_otube /\ ball(z,r) INTER B = {} /\
                 !x. x IN ball(z,r) ==> (x IN N' <=> x$3 = z$3)) /\
    open U /\ connected U /\ ~(U = {}) /\ U SUBSET moi_s5c_otube /\
    U INTER B = {} /\ U INTER (Rem UNION N') = {} /\
    closure U = U UNION Rem UNION N' /\
    (!x. x IN closure U /\ x$3 = c
         ==> &3 / &16 < moi_s35_n x /\ moi_s35_n x < &5 / &16) /\
    (?L. FINITE L /\ simplicial_complex L /\ UNIONS L = B' /\
         !v. {v} IN L ==> ~(v$3 = c)) /\
    CARD (components {x | x IN B' /\ x$3 = c}) <
    CARD (components {x | x IN B /\ x$3 = c}) /\
    moi_s5c_clause {x | x IN B' /\ x$3 <= c} /\
    moi_s5c_clause {x | x IN B' /\ c <= x$3}`;;

(* ------------------------------------------------------------------------- *)
(* Set operations under injective maps, ends of annuli, and the caps        *)
(* of the sphere S along the ends of the annulus b (from SPHERE_SPLIT).     *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_IMAGE_INJ_OPS = prove
 (`!(f:real^3->real^3) D X Y.
     (!x y. x IN D /\ y IN D /\ f x = f y ==> x = y) /\ X SUBSET D /\ Y SUBSET D
     ==> IMAGE f X INTER IMAGE f Y = IMAGE f (X INTER Y) /\
         IMAGE f X DIFF IMAGE f Y = IMAGE f (X DIFF Y) /\
         (IMAGE f X SUBSET IMAGE f Y <=> X SUBSET Y) /\
         (!x. x IN D ==> (f x IN IMAGE f X <=> x IN X))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT CONJ_TAC THENL
   [ASM SET_TAC[]; ASM SET_TAC[]; ASM SET_TAC[]; ASM SET_TAC[]]);;

let MOI_S5C_ANN_ENDS_SUBSET = prove
 (`!(a:real^N->bool) j0 j1. pl_annulus_with_ends a j0 j1 ==> j0 SUBSET a /\ j1 SUBSET a`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_annulus_with_ends; pl_homeomorphism; homeomorphism] THEN
  STRIP_TAC THEN MP_TAC MOI_S5C_A0_FACTS THEN ASM SET_TAC[]);;

let MOI_S5C_ABS_SET_TAC (tms:term list) : tactic =
  MAP_EVERY (fun t -> SPEC_TAC(t, genvar(type_of t))) tms THEN SET_TAC[];;

(* Square bands (the points x with max(|x1|,|x2|) in iv) for an interval iv  *)
(* of positive reals                                                          *)
(* are connected (four convex sectors with pairwise overlapping corners).   *)

let MOI_S5C_SECTOR_CONVEX = prove
 (`!iv (f:real^2->real) (g:real^2->real).
     (!s t u. s IN iv /\ t IN iv /\ s <= u /\ u <= t ==> u IN iv) /\
     (!x y u v. f(u % x + v % y) = u * f x + v * f y) /\
     (!x y u v. g(u % x + v % y) = u * g x + v * g y)
     ==> convex {x:real^2 | f x IN iv /\ abs(g x) <= f x}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[convex; IN_ELIM_THM] THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`x:real^2`; `y:real^2`; `u:real`; `v:real`] THEN STRIP_TAC THEN
  CONJ_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN
    MAP_EVERY EXISTS_TAC [`min (f (x:real^2)) (f (y:real^2))`;
                          `max (f (x:real^2)) (f (y:real^2))`] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[real_min] THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[real_max] THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `u * min (f (x:real^2)) (f (y:real^2)) <= u * f (x:real^2) /\
                  v * min (f (x:real^2)) (f (y:real^2)) <= v * f (y:real^2) /\
                  u * f (x:real^2) <= u * max (f (x:real^2)) (f (y:real^2)) /\
                  v * f (y:real^2) <= v * max (f (x:real^2)) (f (y:real^2))`
    MP_TAC THENL
     [REPEAT CONJ_TAC THEN MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
      REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `min (f (x:real^2)) (f (y:real^2)) =
      u * min (f (x:real^2)) (f (y:real^2)) + v * min (f (x:real^2)) (f (y:real^2)) /\
      max (f (x:real^2)) (f (y:real^2)) =
      u * max (f (x:real^2)) (f (y:real^2)) + v * max (f (x:real^2)) (f (y:real^2))`
    MP_TAC THENL
     [REWRITE_TAC[GSYM REAL_ADD_RDISTRIB] THEN ASM_REWRITE_TAC[REAL_MUL_LID];
      REAL_ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `u * abs(g (x:real^2)) + v * abs(g (y:real^2))` THEN CONJ_TAC THENL
   [MATCH_MP_TAC(REAL_ARITH `abs a <= a' /\ abs b <= b' ==> abs(a + b) <= a' + b'`) THEN
    REWRITE_TAC[REAL_ABS_MUL] THEN ASM_SIMP_TAC[REAL_ARITH `&0 <= u ==> abs u = u`] THEN
    REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_LE_ADD2 THEN CONJ_TAC THEN MATCH_MP_TAC REAL_LE_LMUL THEN
    ASM_REWRITE_TAC[]]);;

let MOI_S5C_NBAND_CONNECTED = prove
 (`!iv. (!s t u. s IN iv /\ t IN iv /\ s <= u /\ u <= t ==> u IN iv) /\
       (!t. t IN iv ==> &0 < t) /\ ~(iv = {})
       ==> connected {x:real^2 | max (abs(x$1)) (abs(x$2)) IN iv}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`iv:real->bool`; `\x:real^2. x$1`; `\x:real^2. x$2`] MOI_S5C_SECTOR_CONVEX) THEN
  MP_TAC(ISPECL [`iv:real->bool`; `\x:real^2. x$2`; `\x:real^2. x$1`] MOI_S5C_SECTOR_CONVEX) THEN
  MP_TAC(ISPECL [`iv:real->bool`; `\x:real^2. --(x$1)`; `\x:real^2. x$2`]
    MOI_S5C_SECTOR_CONVEX) THEN
  MP_TAC(ISPECL [`iv:real->bool`; `\x:real^2. --(x$2)`; `\x:real^2. x$1`]
    MOI_S5C_SECTOR_CONVEX) THEN
  ASM_REWRITE_TAC[VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT] THEN
  REWRITE_TAC[REAL_ARITH `--(u * a + v * b) = u * --a + v * --b`] THEN
  REPEAT DISCH_TAC THEN
  SUBGOAL_THEN
   `{x:real^2 | max (abs(x$1)) (abs(x$2)) IN iv} =
    (({x | x$1 IN iv /\ abs(x$2) <= x$1} UNION {x | x$2 IN iv /\ abs(x$1) <= x$2}) UNION
     {x | --(x$1) IN iv /\ abs(x$2) <= --(x$1)}) UNION
    {x | --(x$2) IN iv /\ abs(x$1) <= --(x$2)}`
  SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_UNION; IN_ELIM_THM] THEN X_GEN_TAC `x:real^2` THEN
    EQ_TAC THENL
     [DISCH_TAC THEN
      MP_TAC(REAL_ARITH
       `!a b. max (abs a) (abs b) = a /\ abs b <= a \/
              max (abs a) (abs b) = b /\ abs a <= b \/
              max (abs a) (abs b) = --a /\ abs b <= --a \/
              max (abs a) (abs b) = --b /\ abs a <= --b`) THEN
      DISCH_THEN(MP_TAC o SPECL [`(x:real^2)$1`; `(x:real^2)$2`]) THEN
      STRIP_TAC THEN
      UNDISCH_TAC `max (abs((x:real^2)$1)) (abs(x$2)) IN iv` THEN ASM_REWRITE_TAC[] THEN
      DISCH_TAC THEN ASM_REWRITE_TAC[];
      STRIP_TAC THENL
       [SUBGOAL_THEN `max (abs((x:real^2)$1)) (abs(x$2)) = x$1` (fun th -> ASM_REWRITE_TAC[th]);
        SUBGOAL_THEN `max (abs((x:real^2)$1)) (abs(x$2)) = x$2` (fun th -> ASM_REWRITE_TAC[th]);
        SUBGOAL_THEN `max (abs((x:real^2)$1)) (abs(x$2)) = --(x$1)`
          (fun th -> ASM_REWRITE_TAC[th]);
        SUBGOAL_THEN `max (abs((x:real^2)$1)) (abs(x$2)) = --(x$2)`
          (fun th -> ASM_REWRITE_TAC[th])] THEN
      FIRST_X_ASSUM(MP_TAC o check (fun th -> is_neg(concl th) = false &&
        (try fst(dest_const(rator(rator(concl th)))) = "IN" with Failure _ -> false))) THEN
      DISCH_THEN(fun th -> MP_TAC th THEN ASSUME_TAC th) THEN
      DISCH_THEN(MP_TAC o MATCH_MP (ASSUME `!t. t IN (iv:real->bool) ==> &0 < t`)) THEN
      ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `t:real` o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY] o check
    (fun th -> is_neg(concl th))) THEN
  SUBGOAL_THEN `&0 < t` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  REPEAT(MATCH_MP_TAC CONNECTED_UNION THEN REPEAT CONJ_TAC) THEN
  TRY(MATCH_MP_TAC CONVEX_CONNECTED THEN FIRST_ASSUM ACCEPT_TAC) THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER; IN_UNION; IN_ELIM_THM] THENL
   [EXISTS_TAC `vector[t;t]:real^2`;
    EXISTS_TAC `vector[--t;t]:real^2`;
    EXISTS_TAC `vector[--t;--t]:real^2`] THEN
  ASM_REWRITE_TAC[VECTOR_2; REAL_NEG_NEG] THEN ASM_REAL_ARITH_TAC);;

let MOI_S5C_SPHERE_PLH = prove
 (`!n (s:real^M->bool) (t:real^N->bool) h h'.
     pl_sphere n s /\ pl_homeomorphism (s,t) (h,h') /\
     (?k:real^N->bool. &(n + 1) simplex k)
     ==> pl_sphere n t`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_sphere] THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `k1:real^M->bool` (X_CHOOSE_THEN `F1:real^M->real^M`
      (X_CHOOSE_THEN `G1:real^M->real^M` STRIP_ASSUME_TAC)))
    (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_TAC `k2:real^N->bool`))) THEN
  MP_TAC(ISPECL [`k2:real^N->bool`; `k1:real^M->bool`; `&(n + 1):int`] MOI_FM3_SIMPLEX_PLH) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:real^N->real^M` (X_CHOOSE_THEN `q:real^M->real^N`
    STRIP_ASSUME_TAC)) THEN
  EXISTS_TAC `k2:real^N->bool` THEN
  EXISTS_TAC `(h:real^M->real^N) o (F1:real^M->real^M) o (p:real^N->real^M)` THEN
  EXISTS_TAC `((q:real^M->real^N) o (G1:real^M->real^M)) o (h':real^N->real^M)` THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `s:real^M->bool` THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN
  EXISTS_TAC `relative_frontier k1:real^M->bool` THEN ASM_REWRITE_TAC[]);;

let MOI_S5C_ANN_PARTS = prove
 (`!(a:real^N->bool) j0 j1.
     pl_annulus_with_ends a j0 j1
     ==> j0 SUBSET a /\ j1 SUBSET a /\ j0 INTER j1 = {} /\ compact a /\
         connected (a DIFF j0) /\ connected (a DIFF j1) /\
         connected (a DIFF (j0 UNION j1)) /\ ~(a DIFF (j0 UNION j1) = {}) /\
         connected j0 /\ connected j1`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ANN_COMPACT) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ANN_ENDS_SUBSET) THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[pl_annulus_with_ends] o check
    (MOI_S5C_HEAD "pl_annulus_with_ends")) THEN
  DISCH_THEN(X_CHOOSE_THEN `f:real^2->real^N` (X_CHOOSE_THEN `g:real^N->real^2`
    STRIP_ASSUME_TAC)) THEN
  FIRST_X_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[homeomorphism] o CONJUNCT1 o
    REWRITE_RULE[pl_homeomorphism] o check (MOI_S5C_HEAD "pl_homeomorphism")) THEN
  SUBGOAL_THEN
   `!iv. (!s t u. s IN iv /\ t IN iv /\ s <= u /\ u <= t ==> u IN iv) /\
         (!t. t IN iv ==> &1 <= t /\ t <= &2) /\ ~(iv = {})
         ==> connected (IMAGE (f:real^2->real^N)
                         {x:real^2 | max (abs(x$1)) (abs(x$2)) IN iv})`
  (LABEL_TAC "band0") THENL
   [GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
      EXISTS_TAC `interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                  interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
      ASM_REWRITE_TAC[SUBSET; IN_ELIM_THM; MOI_S5C_IN_SQANN] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC MOI_S5C_NBAND_CONNECTED THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[REAL_ARITH `&1 <= t ==> &0 < t`]];
    ALL_TAC] THEN
  ABBREV_TAC `A0 = interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                   interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
  SUBGOAL_THEN
   `!X Y. X SUBSET A0 /\ Y SUBSET A0
          ==> IMAGE (f:real^2->real^N) X DIFF IMAGE f Y = IMAGE f (X DIFF Y) /\
              IMAGE (f:real^2->real^N) X INTER IMAGE f Y = IMAGE f (X INTER Y)`
  (LABEL_TAC "injf") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    UNDISCH_TAC `!x. x IN A0 ==> (g:real^N->real^2) ((f:real^2->real^N) x) = x` THEN
    MAP_EVERY UNDISCH_TAC [`X SUBSET (A0:real^2->bool)`; `Y SUBSET (A0:real^2->bool)`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `A0 = {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | &1 <= t /\ t <= &2}} /\
    relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) =
    {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &1}} /\
    relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) =
    {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &2}}`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "A0" THEN
    REWRITE_TAC[EXTENSION; IN_ELIM_THM; MOI_S5C_IN_SQANN; MOI_S5C_IN_RF1; MOI_S5C_IN_RF2];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!P Q. {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | P t}} DIFF
          {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | Q t}} =
          {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | P t /\ ~Q t}}`
  ASSUME_TAC THENL [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_DIFF] THEN MESON_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `IMAGE (f:real^2->real^N) A0 = a` THEN DISCH_THEN(SUBST_ALL_TAC o SYM) THEN
  REPEAT(FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th -> is_var(lhs(concl th)) &&
    (lhs(concl th) = `j0:real^N->bool` || lhs(concl th) = `j1:real^N->bool`)))) THEN
  SUBGOAL_THEN
   `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) SUBSET A0 /\
    relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) SUBSET A0 /\
    A0 DIFF relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) SUBSET A0`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[ASSUME `A0 = {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | &1 <= t /\ t <= &2}}`;
      ASSUME `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &1}}`;
      ASSUME `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &2}}`] THEN
    REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_DIFF] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!iv. (!s t u. s IN iv /\ t IN iv /\ s <= u /\ u <= t ==> u IN iv) /\
         (!t. t IN iv ==> &1 <= t /\ t <= &2) /\ (?t. t IN iv)
         ==> connected (IMAGE (f:real^2->real^N)
                         {x:real^2 | max (abs(x$1)) (abs(x$2)) IN iv})`
  (LABEL_TAC "band") THENL
   [GEN_TAC THEN STRIP_TAC THEN USE_THEN "band0" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    USE_THEN "injf" (MP_TAC o SPECL
      [`relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])`;
       `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(SUBST1_TAC o CONJUNCT2) THEN
    REWRITE_TAC[IMAGE_EQ_EMPTY] THEN
    REWRITE_TAC[ASSUME `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &1}}`;
      ASSUME `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &2}}`] THEN
    REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM; NOT_IN_EMPTY] THEN REAL_ARITH_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    USE_THEN "injf" (MP_TAC o SPECL
      [`A0:real^2->bool`;
       `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])`]) THEN
    ANTS_TAC THENL [REWRITE_TAC[SUBSET_REFL] THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(SUBST1_TAC o CONJUNCT1) THEN
    REWRITE_TAC[ASSUME `A0 = {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | &1 <= t /\ t <= &2}}`;
      ASSUME `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &1}}`] THEN
    REWRITE_TAC[ASSUME `!P Q. {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | P t}} DIFF
          {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | Q t}} =
          {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | P t /\ ~Q t}}`] THEN
    USE_THEN "band" MATCH_MP_TAC THEN REWRITE_TAC[IN_ELIM_THM] THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; EXISTS_TAC `&3 / &2` THEN REAL_ARITH_TAC];
    USE_THEN "injf" (MP_TAC o SPECL
      [`A0:real^2->bool`;
       `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])`]) THEN
    ANTS_TAC THENL [REWRITE_TAC[SUBSET_REFL] THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(SUBST1_TAC o CONJUNCT1) THEN
    REWRITE_TAC[ASSUME `A0 = {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | &1 <= t /\ t <= &2}}`;
      ASSUME `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &2}}`] THEN
    REWRITE_TAC[ASSUME `!P Q. {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | P t}} DIFF
          {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | Q t}} =
          {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | P t /\ ~Q t}}`] THEN
    USE_THEN "band" MATCH_MP_TAC THEN REWRITE_TAC[IN_ELIM_THM] THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; EXISTS_TAC `&3 / &2` THEN REAL_ARITH_TAC];
    SUBGOAL_THEN
     `IMAGE (f:real^2->real^N) A0 DIFF
      (IMAGE f (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION
       IMAGE f (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))) =
      IMAGE f {x:real^2 | max (abs(x$1)) (abs(x$2)) IN
                          {t | (&1 <= t /\ t <= &2) /\ ~(t = &1) /\ ~(t = &2)}}`
    SUBST1_TAC THENL
     [REWRITE_TAC[SET_RULE `(s:real^N->bool) DIFF (t UNION u) = (s DIFF t) DIFF u`] THEN
      USE_THEN "injf" (MP_TAC o SPECL
       [`A0:real^2->bool`;
        `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])`]) THEN
      ANTS_TAC THENL [REWRITE_TAC[SUBSET_REFL] THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o CONJUNCT1) THEN
      USE_THEN "injf" (MP_TAC o SPECL
       [`A0 DIFF relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])`;
        `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o CONJUNCT1) THEN AP_TERM_TAC THEN
      REWRITE_TAC[ASSUME `A0 = {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | &1 <= t /\ t <= &2}}`; ASSUME `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &1}}`; ASSUME `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &2}}`] THEN
      REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_DIFF] THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "band" MATCH_MP_TAC THEN REWRITE_TAC[IN_ELIM_THM] THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; EXISTS_TAC `&3 / &2` THEN REAL_ARITH_TAC];
    SUBGOAL_THEN
     `IMAGE (f:real^2->real^N) A0 DIFF
      (IMAGE f (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION
       IMAGE f (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))) =
      IMAGE f {x:real^2 | max (abs(x$1)) (abs(x$2)) IN
                          {t | (&1 <= t /\ t <= &2) /\ ~(t = &1) /\ ~(t = &2)}}`
    SUBST1_TAC THENL
     [REWRITE_TAC[SET_RULE `(s:real^N->bool) DIFF (t UNION u) = (s DIFF t) DIFF u`] THEN
      USE_THEN "injf" (MP_TAC o SPECL
       [`A0:real^2->bool`;
        `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])`]) THEN
      ANTS_TAC THENL [REWRITE_TAC[SUBSET_REFL] THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o CONJUNCT1) THEN
      USE_THEN "injf" (MP_TAC o SPECL
       [`A0 DIFF relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])`;
        `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o CONJUNCT1) THEN AP_TERM_TAC THEN
      REWRITE_TAC[ASSUME `A0 = {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | &1 <= t /\ t <= &2}}`; ASSUME `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &1}}`; ASSUME `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &2}}`] THEN
      REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_DIFF] THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[IMAGE_EQ_EMPTY] THEN REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    EXISTS_TAC `vector[&3 / &2; &0]:real^2` THEN REWRITE_TAC[VECTOR_2] THEN
    REAL_ARITH_TAC;
    REWRITE_TAC[ASSUME `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &1}}`] THEN
    USE_THEN "band" MATCH_MP_TAC THEN REWRITE_TAC[IN_ELIM_THM] THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; EXISTS_TAC `&1` THEN REAL_ARITH_TAC];
    REWRITE_TAC[ASSUME `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) =
              {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &2}}`] THEN
    USE_THEN "band" MATCH_MP_TAC THEN REWRITE_TAC[IN_ELIM_THM] THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; EXISTS_TAC `&2` THEN REAL_ARITH_TAC]]);;

let MOI_S5C_ANN_END_SPHERES = prove
 (`!(a:real^N->bool) j0 j1.
     pl_annulus_with_ends a j0 j1 /\ (?k:real^N->bool. &2 simplex k)
     ==> pl_sphere 1 j0 /\ pl_sphere 1 j1`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
  REWRITE_TAC[pl_annulus_with_ends] THEN
  DISCH_THEN(X_CHOOSE_THEN `f:real^2->real^N` (X_CHOOSE_THEN `g:real^N->real^2`
    STRIP_ASSUME_TAC)) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!r. r = &1 \/ r = &2
        ==> pl_sphere 1 (IMAGE (f:real^2->real^N)
              (relative_frontier(interval[--vector[r;r]:real^2,vector[r;r]])))`
  (fun th -> MESON_TAC[th]) THEN
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `&0 < r` ASSUME_TAC THENL
   [FIRST_X_ASSUM DISJ_CASES_TAC THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`1`;
    `relative_frontier(interval[--vector[r;r]:real^2,vector[r;r]])`;
    `IMAGE (f:real^2->real^N)
       (relative_frontier(interval[--vector[r;r]:real^2,vector[r;r]]))`;
    `f:real^2->real^N`; `g:real^N->real^2`] MOI_S5C_SPHERE_PLH) THEN
  DISCH_THEN MATCH_MP_TAC THEN
  ASM_SIMP_TAC[MOI_S5C_SQ_JORDAN; ARITH_RULE `1 + 1 = 2`] THEN
  MATCH_MP_TAC MOI_S5C_PLH_RESTRICT THEN
  EXISTS_TAC `interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
              interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
  EXISTS_TAC `a:real^N->bool` THEN ASM_REWRITE_TAC[] THEN
  ASM_SIMP_TAC[LOCALLY_POLYHEDRAL_PL_POLYHEDRON; MOI_S5C_SQ_RF_POLYHEDRON] THEN
  FIRST_X_ASSUM(DISJ_CASES_THEN SUBST1_TAC) THEN REWRITE_TAC[MOI_S5C_A0_FACTS]);;

let MOI_S5C_ANN_OPEN_INTERIOR = prove
 (`!(a:real^2->bool) j0 j1.
     pl_annulus_with_ends a j0 j1 ==> open (a DIFF (j0 UNION j1))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_annulus_with_ends] THEN
  DISCH_THEN(X_CHOOSE_THEN `f:real^2->real^2` (X_CHOOSE_THEN `g:real^2->real^2`
    STRIP_ASSUME_TAC)) THEN
  FIRST_X_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[homeomorphism] o CONJUNCT1 o
    REWRITE_RULE[pl_homeomorphism] o check (MOI_S5C_HEAD "pl_homeomorphism")) THEN
  ABBREV_TAC `A0 = interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                   interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
  SUBGOAL_THEN
   `A0 DIFF (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
             relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) =
    interval(--vector[&2;&2]:real^2,vector[&2;&2]) DIFF
    interval[--vector[&1;&1]:real^2,vector[&1;&1]] /\
    relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) SUBSET A0 /\
    relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) SUBSET A0`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "A0" THEN
    REWRITE_TAC[EXTENSION; SUBSET; IN_DIFF; IN_UNION; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO;
                MOI_S5C_IN_RF1; MOI_S5C_IN_RF2] THEN
    REPEAT CONJ_TAC THEN GEN_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `a DIFF (j0 UNION j1) =
    IMAGE (f:real^2->real^2)
      (interval(--vector[&2;&2]:real^2,vector[&2;&2]) DIFF
       interval[--vector[&1;&1]:real^2,vector[&1;&1]])`
  SUBST1_TAC THENL
   [FIRST_X_ASSUM(SUBST1_TAC o SYM o check (fun th ->
      try lhs(concl th) = `A0 DIFF (relative_frontier(interval[--vector[&1;&1]:real^2,
         vector[&1;&1]]) UNION relative_frontier(interval[--vector[&2;&2]:real^2,
         vector[&2;&2]]))` with Failure _ -> false)) THEN
    MAP_EVERY UNDISCH_TAC
     [`IMAGE (f:real^2->real^2) A0 = a`;
      `j0 = IMAGE (f:real^2->real^2)
              (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))`;
      `j1 = IMAGE (f:real^2->real^2)
              (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`;
      `!x. x IN A0 ==> (g:real^2->real^2) ((f:real^2->real^2) x) = x`;
      `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) SUBSET A0`;
      `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) SUBSET A0`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC INVARIANCE_OF_DOMAIN THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `A0:real^2->bool` THEN
    ASM_REWRITE_TAC[] THEN EXPAND_TAC "A0" THEN
    REWRITE_TAC[SUBSET; IN_DIFF; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO] THEN REAL_ARITH_TAC;
    MATCH_MP_TAC OPEN_DIFF THEN REWRITE_TAC[OPEN_INTERVAL; CLOSED_INTERVAL];
    MAP_EVERY X_GEN_TAC [`x:real^2`; `y:real^2`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(x:real^2) IN A0 /\ (y:real^2) IN A0` STRIP_ASSUME_TAC THENL
     [MAP_EVERY UNDISCH_TAC
       [`(x:real^2) IN interval(--vector[&2;&2],vector[&2;&2]) DIFF
                       interval[--vector[&1;&1],vector[&1;&1]]`;
        `(y:real^2) IN interval(--vector[&2;&2],vector[&2;&2]) DIFF
                       interval[--vector[&1;&1],vector[&1;&1]]`] THEN
      EXPAND_TAC "A0" THEN REWRITE_TAC[IN_DIFF; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO] THEN
      REAL_ARITH_TAC;
      ASM_MESON_TAC[]]]);;

(* A PL annulus a in a planar 2-simplex k0 whose first end is the boundary  *)
(* of k0 is exactly the region of k0 outside its second end c1.             *)

let MOI_S5C_PLANAR_COLLAR = prove
 (`!(k0:real^2->bool) a c1.
     &2 simplex k0 /\ pl_annulus_with_ends a (relative_frontier k0) c1 /\ a SUBSET k0
     ==> pl_sphere 1 c1 /\ c1 SUBSET interior k0 /\ inside c1 SUBSET interior k0 /\
         a = k0 DIFF inside c1 /\ a INTER (c1 UNION inside c1) = c1 /\
         a UNION (c1 UNION inside c1) = k0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_SIMPLEX2_FACTS) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ANN_PARTS) THEN
  MP_TAC(ISPECL [`a:real^2->bool`; `relative_frontier k0:real^2->bool`; `c1:real^2->bool`]
    MOI_S5C_ANN_END_SPHERES) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `k0:real^2->bool` THEN ASM_REWRITE_TAC[];
    STRIP_TAC] THEN
  SUBGOAL_THEN `c1 SUBSET interior(k0:real^2->bool)` ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`c1 SUBSET (a:real^2->bool)`; `a SUBSET (k0:real^2->bool)`;
      `relative_frontier k0 INTER (c1:real^2->bool) = {}`;
      `relative_frontier k0 UNION interior k0 = (k0:real^2->bool)`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `inside c1 SUBSET interior(k0:real^2->bool)` ASSUME_TAC THENL
   [MATCH_MP_TAC INSIDE_SUBSET_CONVEX THEN ASM_SIMP_TAC[CONVEX_INTERIOR]; ALL_TAC] THEN
  SUBGOAL_THEN `(c1:real^2->bool) homeomorphic sphere(vec 0:real^2,&1)` ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPEC `c1:real^2->bool` JORDAN_INSIDE_OUTSIDE_GEN) THEN
  ASM_REWRITE_TAC[DIMINDEX_2; LE_REFL] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:real^2->bool) INTER inside c1 = {}` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`c1:real^2->bool`; `a DIFF c1:real^2->bool`] MOI_S5C_CONNECTED_SIDE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN SET_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `(p ==> F) /\ (q ==> r) ==> p \/ q ==> r`) THEN CONJ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `~(relative_frontier k0:real^2->bool = {})` MP_TAC THENL
       [DISCH_TAC THEN
        UNDISCH_TAC `relative_frontier (k0:real^2->bool) homeomorphic sphere(vec 0:real^2,&1)` THEN
        ASM_REWRITE_TAC[HOMEOMORPHIC_EMPTY; SPHERE_EQ_EMPTY] THEN REAL_ARITH_TAC;
        ALL_TAC] THEN
      MAP_EVERY UNDISCH_TAC
       [`a DIFF c1 SUBSET inside(c1:real^2->bool)`;
        `relative_frontier k0 SUBSET (a:real^2->bool)`;
        `relative_frontier k0 INTER (c1:real^2->bool) = {}`;
        `inside c1 SUBSET interior(k0:real^2->bool)`;
        `relative_frontier k0 INTER interior k0 = ({}:real^2->bool)`] THEN
      SET_TAC[];
      MP_TAC(ISPEC `c1:real^2->bool` INSIDE_NO_OVERLAP) THEN
      MAP_EVERY UNDISCH_TAC [`inside c1 INTER outside c1:real^2->bool = {}`] THEN
      SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:real^2->bool) = k0 DIFF inside c1` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
     [MAP_EVERY UNDISCH_TAC [`a SUBSET (k0:real^2->bool)`;
                             `(a:real^2->bool) INTER inside c1 = {}`] THEN SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`c1:real^2->bool`; `relative_frontier k0:real^2->bool`] MOI_S5C_ANN2) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o MATCH_MP MOI_S5C_ANN_PARTS) THEN
    ABBREV_TAC `R = (k0:real^2->bool) DIFF inside c1` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(a:real^2->bool) SUBSET R` ASSUME_TAC THENL
     [EXPAND_TAC "R" THEN
      MAP_EVERY UNDISCH_TAC [`a SUBSET (k0:real^2->bool)`;
                             `(a:real^2->bool) INTER inside c1 = {}`] THEN SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`a:real^2->bool`; `relative_frontier k0:real^2->bool`; `c1:real^2->bool`]
      MOI_S5C_ANN_OPEN_INTERIOR) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    SUBGOAL_THEN `a DIFF (relative_frontier k0 UNION c1) =
                  R DIFF (c1 UNION relative_frontier (k0:real^2->bool))` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [CONNECTED_CLOPEN] o check (fun th ->
        concl th = `connected (R DIFF (c1 UNION relative_frontier (k0:real^2->bool)))`)) THEN
      DISCH_THEN(MP_TAC o SPEC `a DIFF (relative_frontier k0 UNION c1):real^2->bool`) THEN
      ANTS_TAC THENL
       [CONJ_TAC THENL
         [MATCH_MP_TAC OPEN_SUBSET THEN ASM_REWRITE_TAC[] THEN
          UNDISCH_TAC `(a:real^2->bool) SUBSET R` THEN SET_TAC[];
          SUBGOAL_THEN `a DIFF (relative_frontier k0 UNION c1):real^2->bool =
                        (R DIFF (c1 UNION relative_frontier k0)) INTER a`
          SUBST1_TAC THENL
           [UNDISCH_TAC `(a:real^2->bool) SUBSET R` THEN SET_TAC[];
            MATCH_MP_TAC CLOSED_IN_CLOSED_INTER THEN ASM_SIMP_TAC[COMPACT_IMP_CLOSED]]];
        ALL_TAC] THEN
      UNDISCH_TAC `~(a DIFF (relative_frontier k0 UNION c1):real^2->bool = {})` THEN
      MESON_TAC[];
      ALL_TAC] THEN
    MAP_EVERY UNDISCH_TAC
     [`a DIFF (relative_frontier k0 UNION c1) =
       R DIFF (c1 UNION relative_frontier (k0:real^2->bool))`;
      `c1 SUBSET (a:real^2->bool)`; `relative_frontier k0 SUBSET (a:real^2->bool)`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPEC `c1:real^2->bool` INSIDE_NO_OVERLAP) THEN
  MAP_EVERY UNDISCH_TAC
   [`c1 SUBSET interior(k0:real^2->bool)`; `inside c1 SUBSET interior(k0:real^2->bool)`;
    `interior k0 SUBSET (k0:real^2->bool)`] THEN
  SET_TAC[]);;

let MOI_S5C_CAPS = prove
 (mk_imp(MOI_SCH3_SPHERE_SPLIT,
  `!S (b:real^3->bool) b0 b1.
     pl_sphere 2 S /\ pl_annulus_with_ends b b0 b1 /\ b SUBSET S
     ==> ?D0 D1. pl_cell_with_boundary 2 D0 b0 /\ pl_cell_with_boundary 2 D1 b1 /\
                 D0 INTER b = b0 /\ D1 INTER b = b1 /\ D0 INTER D1 = {} /\
                 S = D0 UNION b UNION D1`),
  DISCH_THEN(LABEL_TAC "split") THEN
  MAP_EVERY X_GEN_TAC [`S:real^3->bool`; `b:real^3->bool`; `b0:real^3->bool`;
                       `b1:real^3->bool`] THEN
  STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ANN_PARTS) THEN
  MP_TAC(ISPECL [`b:real^3->bool`; `b0:real^3->bool`; `b1:real^3->bool`]
    MOI_S5C_ANN_END_SPHERES) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MESON_TAC[MOI_S5C_SIMPLEX2_R3]; STRIP_TAC] THEN
  SUBGOAL_THEN
   `?D0 E. pl_cell_with_boundary 2 D0 b0 /\ pl_cell_with_boundary 2 E (b0:real^3->bool) /\
           D0 UNION E = S /\ D0 INTER E = b0 /\ b SUBSET E`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "split" (MP_TAC o SPECL [`S:real^3->bool`; `b0:real^3->bool`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MAP_EVERY UNDISCH_TAC [`b0 SUBSET (b:real^3->bool)`; `b SUBSET (S:real^3->bool)`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `d1:real^3->bool` (X_CHOOSE_THEN `d2:real^3->bool`
      STRIP_ASSUME_TAC)) THEN
    MP_TAC(MATCH_MP MOI_S5C_CELL_COMPACT2 (ASSUME
      `pl_cell_with_boundary 2 (d1:real^3->bool) b0`)) THEN
    MP_TAC(MATCH_MP MOI_S5C_CELL_COMPACT2 (ASSUME
      `pl_cell_with_boundary 2 (d2:real^3->bool) b0`)) THEN
    REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`b DIFF b0:real^3->bool`; `d1:real^3->bool`; `d2:real^3->bool`]
      MOI_S5C_CONN_TWO_CLOSED) THEN
    ANTS_TAC THENL
     [ASM_SIMP_TAC[COMPACT_IMP_CLOSED] THEN
      MAP_EVERY UNDISCH_TAC
       [`d1 UNION d2:real^3->bool = S`; `d1 INTER d2:real^3->bool = b0`;
        `b SUBSET (S:real^3->bool)`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    STRIP_TAC THENL
     [MAP_EVERY EXISTS_TAC [`d2:real^3->bool`; `d1:real^3->bool`];
      MAP_EVERY EXISTS_TAC [`d1:real^3->bool`; `d2:real^3->bool`]] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY UNDISCH_TAC
     [`d1 UNION d2:real^3->bool = S`; `d1 INTER d2:real^3->bool = b0`;
      `b0 SUBSET (d1:real^3->bool)`; `b0 SUBSET (d2:real^3->bool)`] THEN
    TRY(UNDISCH_TAC `b DIFF b0 SUBSET (d1:real^3->bool)`) THEN
    TRY(UNDISCH_TAC `b DIFF b0 SUBSET (d2:real^3->bool)`) THEN
    SET_TAC[];
    ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o REWRITE_RULE[pl_cell_with_boundary] o check (fun th ->
    concl th = `pl_cell_with_boundary 2 (E:real^3->bool) b0`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `k:real^3->bool` (X_CHOOSE_THEN `F1:real^3->real^3`
    (X_CHOOSE_THEN `G1:real^3->real^3` STRIP_ASSUME_TAC))) THEN
  MP_TAC(ISPEC `k:real^3->bool` MOI_S27_SIMPLEX_FROM_PLANE) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `k0:real^2->bool` (X_CHOOSE_THEN `h:real^2->real^3`
    (X_CHOOSE_THEN `h':real^3->real^2` STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN
   `pl_homeomorphism (k0,E) ((F1:real^3->real^3) o (h:real^2->real^3),
                             (h':real^3->real^2) o (G1:real^3->real^3))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC PL_HOMEOMORPHISM_COMPOSE THEN EXISTS_TAC `k:real^3->bool` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `p0 = (F1:real^3->real^3) o (h:real^2->real^3)` THEN
  ABBREV_TAC `q0 = (h':real^3->real^2) o (G1:real^3->real^3)` THEN
  SUBGOAL_THEN `IMAGE (p0:real^2->real^3) (relative_frontier k0) = b0` ASSUME_TAC THENL
   [EXPAND_TAC "p0" THEN REWRITE_TAC[IMAGE_o] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[homeomorphism] o CONJUNCT1 o
    REWRITE_RULE[pl_homeomorphism] o check (fun th ->
    concl th = `pl_homeomorphism (k0,E) (p0:real^2->real^3,q0:real^3->real^2)`)) THEN
  MP_TAC(MATCH_MP MOI_S5C_SIMPLEX2_FACTS (ASSUME `&2 simplex (k0:real^2->bool)`)) THEN
  STRIP_TAC THEN
  SUBGOAL_THEN
   `pl_annulus_with_ends (IMAGE (q0:real^3->real^2) b) (relative_frontier k0)
                         (IMAGE q0 b1)`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`b:real^3->bool`; `b0:real^3->bool`; `b1:real^3->bool`;
                   `IMAGE (q0:real^3->real^2) b`; `q0:real^3->real^2`; `p0:real^2->real^3`]
      MOI_S5C_ANN_TRANSFER) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOI_S5C_PLH_RESTRICT THEN
      MAP_EVERY EXISTS_TAC [`E:real^3->bool`; `k0:real^2->bool`] THEN
      ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
      ASM_MESON_TAC[MOI_S5C_ANN_POLYHEDRON];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `(q <=> r) ==> q ==> r`) THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    UNDISCH_TAC `IMAGE (p0:real^2->real^3) (relative_frontier k0) = b0` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[GSYM IMAGE_o] THEN
    MATCH_MP_TAC(SET_RULE `(!x:real^2. x IN s ==> f x = x) ==> IMAGE f s = s`) THEN
    REWRITE_TAC[o_THM] THEN
    UNDISCH_TAC `relative_frontier k0 SUBSET (k0:real^2->bool)` THEN
    UNDISCH_TAC `!x. x IN k0 ==> (q0:real^3->real^2) ((p0:real^2->real^3) x) = x` THEN
    SET_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `c1 = IMAGE (q0:real^3->real^2) b1` THEN
  MP_TAC(ISPECL [`k0:real^2->bool`; `IMAGE (q0:real^3->real^2) b`; `c1:real^2->bool`]
    MOI_S5C_PLANAR_COLLAR) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `IMAGE (q0:real^3->real^2) E = k0` THEN
    UNDISCH_TAC `b SUBSET (E:real^3->bool)` THEN SET_TAC[];
    STRIP_TAC] THEN
  SUBGOAL_THEN `c1 UNION inside c1 SUBSET (k0:real^2->bool)` ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`c1 SUBSET interior(k0:real^2->bool)`; `inside c1 SUBSET interior(k0:real^2->bool)`;
      `interior k0 SUBSET (k0:real^2->bool)`] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (p0:real^2->real^3) c1 = b1 /\ IMAGE (p0:real^2->real^3) (IMAGE q0 b) = b`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `IMAGE (q0:real^3->real^2) b1 = c1` THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    MAP_EVERY UNDISCH_TAC
     [`!y. y IN E ==> (p0:real^2->real^3) ((q0:real^3->real^2) y) = y`;
      `b SUBSET (E:real^3->bool)`; `b1 SUBSET (b:real^3->bool)`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `D0:real^3->bool` THEN
  EXISTS_TAC `IMAGE (p0:real^2->real^3) (c1 UNION inside c1)` THEN
  REWRITE_TAC[SYM(ASSUME `b0 = IMAGE (F1:real^3->real^3) (relative_frontier k)`)] THEN
  MP_TAC(MATCH_MP MOI_S5C_CELL_COMPACT2 (ASSUME
    `pl_cell_with_boundary 2 (D0:real^3->bool) b0`)) THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `IMAGE (p0:real^2->real^3) (c1 UNION inside c1) INTER b = b1 /\
    IMAGE (p0:real^2->real^3) (c1 UNION inside c1) SUBSET E /\
    E = b UNION IMAGE (p0:real^2->real^3) (c1 UNION inside c1)`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [UNDISCH_TAC `IMAGE (p0:real^2->real^3) (IMAGE q0 b) = b` THEN
      DISCH_THEN(fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [SYM th]) THEN
      UNDISCH_TAC `IMAGE (p0:real^2->real^3) c1 = b1` THEN
      DISCH_THEN(fun th -> GEN_REWRITE_TAC RAND_CONV [SYM th]) THEN
      UNDISCH_TAC `IMAGE (q0:real^3->real^2) b INTER (c1 UNION inside c1) = c1` THEN
      UNDISCH_TAC `IMAGE (q0:real^3->real^2) b = k0 DIFF inside c1` THEN
      UNDISCH_TAC `c1 UNION inside c1 SUBSET (k0:real^2->bool)` THEN
      UNDISCH_TAC `!x. x IN k0 ==> (q0:real^3->real^2) ((p0:real^2->real^3) x) = x` THEN
      SET_TAC[];
      UNDISCH_TAC `IMAGE (p0:real^2->real^3) k0 = E` THEN
      UNDISCH_TAC `c1 UNION inside c1 SUBSET (k0:real^2->bool)` THEN SET_TAC[];
      UNDISCH_TAC `IMAGE (p0:real^2->real^3) k0 = E` THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      UNDISCH_TAC `IMAGE (p0:real^2->real^3) (IMAGE q0 b) = b` THEN
      DISCH_THEN(fun th -> GEN_REWRITE_TAC (RAND_CONV o LAND_CONV) [SYM th]) THEN
      REWRITE_TAC[GSYM IMAGE_UNION] THEN AP_TERM_TAC THEN
      UNDISCH_TAC `IMAGE (q0:real^3->real^2) b UNION c1 UNION inside c1 = k0` THEN
      SET_TAC[]];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    MP_TAC(ISPECL [`2`; `c1 UNION inside c1:real^2->bool`; `c1:real^2->bool`;
                   `IMAGE (p0:real^2->real^3) (c1 UNION inside c1)`;
                   `p0:real^2->real^3`; `q0:real^3->real^2`] MOI_S5C_CELL_PLH) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_SIMP_TAC[MOI_S5C_PLANE_DISK] THEN
    CONJ_TAC THENL [ALL_TAC; MESON_TAC[MOI_S5C_SIMPLEX2_R3]] THEN
    MATCH_MP_TAC MOI_S5C_PLH_RESTRICT THEN
    MAP_EVERY EXISTS_TAC [`k0:real^2->bool`; `E:real^3->bool`] THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
    MATCH_MP_TAC MOI_S5C_CELL_POLYHEDRON THEN
    MAP_EVERY EXISTS_TAC [`2`; `c1:real^2->bool`] THEN ASM_SIMP_TAC[MOI_S5C_PLANE_DISK];
    MAP_EVERY UNDISCH_TAC
     [`D0 INTER E:real^3->bool = b0`; `b SUBSET (E:real^3->bool)`;
      `b0 SUBSET (D0:real^3->bool)`; `b0 SUBSET (b:real^3->bool)`] THEN SET_TAC[];
    FIRST_ASSUM ACCEPT_TAC;
    MAP_EVERY UNDISCH_TAC
     [`D0 INTER E:real^3->bool = b0`;
      `IMAGE (p0:real^2->real^3) (c1 UNION inside c1) SUBSET E`;
      `IMAGE (p0:real^2->real^3) (c1 UNION inside c1) INTER b = b1`;
      `b0 SUBSET (b:real^3->bool)`; `b0 INTER b1:real^3->bool = {}`] THEN
    MOI_S5C_ABS_SET_TAC [`IMAGE (p0:real^2->real^3) (c1 UNION inside c1)`];
    MAP_EVERY UNDISCH_TAC
     [`D0 UNION E:real^3->bool = S`;
      `E = b UNION IMAGE (p0:real^2->real^3) (c1 UNION inside c1)`] THEN
    MOI_S5C_ABS_SET_TAC [`IMAGE (p0:real^2->real^3) (c1 UNION inside c1)`]]);;


(* ------------------------------------------------------------------------- *)
(* The circles of B read in the square annulus model: PL circles in        *)
(* the open square annulus around the inner square, totally ordered by     *)
(* nesting; minima and successors in finite strict total orders.           *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_JORDAN_NEST = prove
 (`!X Y:real^2->bool.
     X homeomorphic sphere(vec 0:real^2,&1) /\ Y homeomorphic sphere(vec 0:real^2,&1) /\
     DISJOINT X Y /\ ~(inside X INTER inside Y = {})
     ==> X SUBSET inside Y \/ Y SUBSET inside X`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `X:real^2->bool` JORDAN_INSIDE_OUTSIDE_GEN) THEN
  MP_TAC(ISPEC `Y:real^2->bool` JORDAN_INSIDE_OUTSIDE_GEN) THEN
  ASM_REWRITE_TAC[DIMINDEX_2; LE_REFL] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `connected(X:real^2->bool) /\ connected(Y:real^2->bool) /\
                ~(X:real^2->bool = {}) /\ ~(Y:real^2->bool = {})` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[CONNECTED_SPHERE; HOMEOMORPHIC_CONNECTEDNESS; DIMINDEX_2; LE_REFL;
                  HOMEOMORPHIC_EMPTY; SPHERE_EQ_EMPTY; REAL_ARITH `~(&1 < &0)`];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`Y:real^2->bool`; `X:real^2->bool`] MOI_S5C_CONNECTED_SIDE) THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_CONNECTED_SIDE) THEN
  ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[DISJOINT_SYM] THEN ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `inside Y:real^2->bool`] MOI_S5C_CONNECTED_SIDE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN UNDISCH_TAC `X SUBSET outside(Y:real^2->bool)` THEN
    UNDISCH_TAC `inside Y INTER outside Y:real^2->bool = {}` THEN SET_TAC[];
    ALL_TAC] THEN
  STRIP_TAC THENL
   [SUBGOAL_THEN `Y SUBSET X UNION inside(X:real^2->bool)` MP_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `closure(inside Y:real^2->bool)` THEN
      CONJ_TAC THENL
       [UNDISCH_TAC `frontier(inside Y:real^2->bool) = Y` THEN REWRITE_TAC[frontier] THEN
        SET_TAC[];
        MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `closure(inside X:real^2->bool)` THEN
        ASM_SIMP_TAC[SUBSET_CLOSURE] THEN
        UNDISCH_TAC `frontier(inside X:real^2->bool) = X` THEN
        MP_TAC(ISPEC `inside X:real^2->bool` INTERIOR_OPEN) THEN ASM_REWRITE_TAC[] THEN
        REWRITE_TAC[frontier] THEN SET_TAC[]];
      MAP_EVERY UNDISCH_TAC
       [`DISJOINT (X:real^2->bool) Y`; `Y SUBSET outside(X:real^2->bool)`;
        `inside X INTER outside X:real^2->bool = {}`; `~(Y:real^2->bool = {})`] THEN
      SET_TAC[]];
    MAP_EVERY UNDISCH_TAC
     [`~(inside X INTER inside Y:real^2->bool = {})`;
      `inside Y SUBSET outside(X:real^2->bool)`;
      `inside X INTER outside X:real^2->bool = {}`] THEN
    SET_TAC[]]);;

let MOI_S5C_FINITE_TOTAL_MIN = prove
 (`!(R:A->A->bool) s.
     FINITE s
     ==> ~(s = {}) /\
         (!x y z. x IN s /\ y IN s /\ z IN s /\ R x y /\ R y z ==> R x z) /\
         (!x y. x IN s /\ y IN s /\ ~(x = y) ==> R x y \/ R y x)
         ==> ?m. m IN s /\ !y. y IN s /\ ~(y = m) ==> R m y`,
  GEN_TAC THEN MATCH_MP_TAC FINITE_INDUCT_STRONG THEN REWRITE_TAC[NOT_INSERT_EMPTY] THEN
  MAP_EVERY X_GEN_TAC [`a:A`; `t:A->bool`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ih") STRIP_ASSUME_TAC) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tr") (LABEL_TAC "tot")) THEN
  ASM_CASES_TAC `t:A->bool = {}` THENL
   [EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN MESON_TAC[];
    ALL_TAC] THEN
  REMOVE_THEN "ih" MP_TAC THEN ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[IN_INSERT];
      USE_THEN "tot" MATCH_MP_TAC THEN ASM_REWRITE_TAC[IN_INSERT]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `~(m:A = a) /\ ~(a = m)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN DISCH_TAC THEN UNDISCH_TAC `~((a:A) IN t)` THEN
    UNDISCH_TAC `(m:A) IN t` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "tot" (MP_TAC o SPECL [`a:A`; `m:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[IN_INSERT]; ALL_TAC] THEN STRIP_TAC THENL
   [EXISTS_TAC `a:A` THEN REWRITE_TAC[IN_INSERT] THEN X_GEN_TAC `y:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 DISJ_CASES_TAC ASSUME_TAC) THENL
     [ASM_MESON_TAC[];
      ASM_CASES_TAC `y:A = m` THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `m:A` THEN
      ASM_REWRITE_TAC[IN_INSERT] THEN
      FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> is_forall(concl th) &&
        length(fst(strip_forall(concl th))) = 1)) THEN
      ASM_REWRITE_TAC[]];
    EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[IN_INSERT] THEN X_GEN_TAC `y:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 DISJ_CASES_TAC ASSUME_TAC) THENL
     [ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> is_forall(concl th) &&
        length(fst(strip_forall(concl th))) = 1)) THEN
      ASM_REWRITE_TAC[]]]);;

let MOI_S5C_MSET_FACTS = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0
     ==> (!x. x IN interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                   interval(--vector[&1;&1]:real^2,vector[&1;&1])
              ==> FF x IN B /\ GG ((FF:real^2->real^3) x) = x) /\
         (!y. y IN B ==> (GG:real^3->real^2) y IN
                           interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                           interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
                         FF (GG y) = y) /\
         IMAGE FF (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                   interval(--vector[&1;&1]:real^2,vector[&1;&1])) = B /\
         IMAGE GG B = interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                      interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
         FF continuous_on (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                           interval(--vector[&1;&1]:real^2,vector[&1;&1])) /\
         GG continuous_on B /\
         pl_homeomorphism (B,interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                             interval(--vector[&1;&1]:real^2,vector[&1;&1])) (GG,FF) /\
         compact B /\ &0 < d0 /\ moi_s5c_collar B c d0 Q /\
         compact {x:real^3 | x IN B /\ x$3 = c} /\
         {x:real^3 | x IN B /\ x$3 = c} SUBSET moi_s5c_otube /\
         {x:real^3 | x IN B /\ x$3 = c} SUBSET moi_s35_ttube /\
         pl_polyhedron B /\ B SUBSET interior moi_s35_stube /\
         DISJOINT
          (IMAGE FF (relative_frontier (interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION
           IMAGE FF (relative_frontier (interval[--vector[&2;&2]:real^2,vector[&2;&2]])))
          moi_s35_ttube /\
         FINITE (components {x:real^3 | x IN B /\ x$3 = c}) /\
         (!k. k IN components {x | x IN B /\ x$3 = c}
              ==> ?j:real^2->bool. pl_sphere 1 j /\ k = IMAGE (moi_s35_lift c) j) /\
         {x | x IN B /\ x$3 = c} SUBSET
         {x | &3 / &16 < moi_s35_n x /\ moi_s35_n x < &5 / &16 /\ x$3 = c} /\
         abs c <= &1 / &512 /\ d0 <= &1 / &64 /\
         {x | x IN B /\ abs(x$3 - c) <= d0} SUBSET moi_s5c_otube /\
         FINITE K /\ simplicial_complex K /\ UNIONS K = B /\
         (!s. s IN K ==> aff_dim s <= &2) /\ (!v. {v} IN K ==> d0 < abs(v$3 - c))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_BASIC) THEN
  FIRST_X_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mset] o check
    (MOI_S5C_HEAD "moi_s5c_mset")) THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[homeomorphism] o CONJUNCT1 o
    REWRITE_RULE[pl_homeomorphism] o check (MOI_S5C_HEAD "pl_homeomorphism")) THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [ASM SET_TAC[]; ASM SET_TAC[];
    ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN ASM_REWRITE_TAC[];
    MP_TAC MOI_S5C_OTUBE THEN ASM SET_TAC[]]);;

let MOI_S5C_SQC_BASIC = prove
 (`!B K FF GG Q c d0 k.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     k IN components {x | x IN B /\ x$3 = c}
     ==> k SUBSET B /\ compact k /\ connected k /\ ~(k = {}) /\
         (!x. x IN k ==> x$3 = c) /\ pl_sphere 1 k /\
         pl_sphere 1 (IMAGE (GG:real^3->real^2) k) /\
         IMAGE GG k homeomorphic sphere(vec 0:real^2,&1) /\
         IMAGE GG k SUBSET
           (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
            interval(--vector[&1;&1]:real^2,vector[&1;&1])) DIFF
           (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
            relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) /\
         interval(--vector[&1;&1],vector[&1;&1]) SUBSET inside (IMAGE GG k) /\
         relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) SUBSET
         inside (IMAGE GG k) /\
         IMAGE GG k UNION inside (IMAGE GG k) SUBSET
         interval(--vector[&2;&2],vector[&2;&2]) /\
         IMAGE (FF:real^2->real^3) (IMAGE GG k) = k`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  ABBREV_TAC `A0 = interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                   interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
  SUBGOAL_THEN `k SUBSET {x:real^3 | x IN B /\ x$3 = c}` ASSUME_TAC THENL
   [ASM_MESON_TAC[IN_COMPONENTS_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `connected (k:real^3->bool) /\ ~(k = {})` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[IN_COMPONENTS_CONNECTED; IN_COMPONENTS_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `pl_sphere 1 (k:real^3->bool)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `k:real^3->bool` o check (fun th -> is_forall(concl th) &&
      free_in `moi_s35_lift` (concl th))) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_SIMP_TAC[MOI_S5C_LIFT_SPHERE];
    ALL_TAC] THEN
  SUBGOAL_THEN `compact (k:real^3->bool)` ASSUME_TAC THENL
   [ASM_MESON_TAC[MOI_SCD_PL_SPHERE_POLYHEDRON; PL_POLYHEDRON_IMP_COMPACT]; ALL_TAC] THEN
  SUBGOAL_THEN `k SUBSET (B:real^3->bool) /\ (!x:real^3. x IN k ==> x$3 = c)`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `k SUBSET {x:real^3 | x IN B /\ x$3 = c}` THEN SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (FF:real^2->real^3) (IMAGE GG k) = k` ASSUME_TAC THENL
   [UNDISCH_TAC `!y. y IN B ==> (GG:real^3->real^2) y IN A0 /\ (FF:real^2->real^3) (GG y) = y` THEN
    UNDISCH_TAC `k SUBSET (B:real^3->bool)` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `pl_sphere 1 (IMAGE (GG:real^3->real^2) k)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`1`; `k:real^3->bool`; `IMAGE (GG:real^3->real^2) k`;
                   `GG:real^3->real^2`; `FF:real^2->real^3`] MOI_S5C_SPHERE_PLH) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[ARITH_RULE `1 + 1 = 2`] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC MOI_S5C_PLH_RESTRICT THEN
      MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `A0:real^2->bool`] THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
      ASM_MESON_TAC[MOI_SCD_PL_SPHERE_POLYHEDRON];
      MESON_TAC[MOI_S5C_TRI_FACTS]];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (GG:real^3->real^2) k homeomorphic sphere(vec 0:real^2,&1)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (GG:real^3->real^2) k SUBSET
    A0 DIFF (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
             relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`
  ASSUME_TAC THENL
   [REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; IN_DIFF; IN_UNION] THEN
    X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(x:real^3) IN B /\ x IN moi_s35_ttube` STRIP_ASSUME_TAC THENL
     [MAP_EVERY UNDISCH_TAC
       [`k SUBSET {x:real^3 | x IN B /\ x$3 = c}`;
        `{x:real^3 | x IN B /\ x$3 = c} SUBSET moi_s35_ttube`; `(x:real^3) IN k`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[GSYM IN_UNION] THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(x:real^3) IN IMAGE (FF:real^2->real^3)
        (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
         relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`
    MP_TAC THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `(GG:real^3->real^2) x` THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    UNDISCH_TAC `DISJOINT
      (IMAGE (FF:real^2->real^3) (relative_frontier (interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION
       IMAGE FF (relative_frontier (interval[--vector[&2;&2]:real^2,vector[&2;&2]])))
      moi_s35_ttube` THEN
    UNDISCH_TAC `(x:real^3) IN moi_s35_ttube` THEN
    REWRITE_TAC[IMAGE_UNION] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `A0 DIFF (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
                 relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) SUBSET
                interval(--vector[&2;&2],vector[&2;&2]) /\
                A0 INTER interval(--vector[&1;&1],vector[&1;&1]) = {}`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "A0" THEN
    REWRITE_TAC[SUBSET; EXTENSION; IN_DIFF; IN_UNION; IN_INTER; NOT_IN_EMPTY;
                MOI_S5C_IN_SQI; MOI_S5C_IN_SQO; MOI_S5C_IN_RF1; MOI_S5C_IN_RF2] THEN
    CONJ_TAC THEN GEN_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (GG:real^3->real^2) k UNION inside (IMAGE GG k) SUBSET
    interval(--vector[&2;&2],vector[&2;&2])`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(SET_RULE `(s:real^2->bool) SUBSET u /\ t SUBSET u ==> s UNION t SUBSET u`) THEN
    CONJ_TAC THENL [ASM SET_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC INSIDE_SUBSET_CONVEX THEN REWRITE_TAC[CONVEX_INTERVAL] THEN ASM SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC `IMAGE (GG:real^3->real^2) k` JORDAN_INSIDE_OUTSIDE_GEN) THEN
  ASM_REWRITE_TAC[DIMINDEX_2; LE_REFL] THEN STRIP_TAC THEN
  SUBGOAL_THEN `interval(--vector[&1;&1]:real^2,vector[&1;&1]) SUBSET
                inside (IMAGE (GG:real^3->real^2) k)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`IMAGE (GG:real^3->real^2) k`;
                   `interval(--vector[&1;&1]:real^2,vector[&1;&1])`]
      MOI_S5C_CONNECTED_SIDE) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[CONNECTED_INTERVAL] THEN
      MAP_EVERY UNDISCH_TAC
       [`IMAGE (GG:real^3->real^2) k SUBSET
         A0 DIFF (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
                  relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`;
        `A0 INTER interval(--vector[&1;&1]:real^2,vector[&1;&1]) = {}`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `(q ==> F) ==> p \/ q ==> p`) THEN DISCH_TAC THEN
    SUBGOAL_THEN `IMAGE (GG:real^3->real^2) k UNION inside (IMAGE GG k) SUBSET
                  (A0:real^2->bool)` MP_TAC THENL
     [EXPAND_TAC "A0" THEN
      MAP_EVERY UNDISCH_TAC
       [`IMAGE (GG:real^3->real^2) k UNION inside (IMAGE GG k) SUBSET
         interval(--vector[&2;&2],vector[&2;&2])`;
        `interval(--vector[&1;&1]:real^2,vector[&1;&1]) SUBSET
         outside (IMAGE (GG:real^3->real^2) k)`;
        `inside (IMAGE (GG:real^3->real^2) k) INTER outside (IMAGE GG k) = {}`;
        `IMAGE (GG:real^3->real^2) k SUBSET
         A0 DIFF (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
                  relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`;
        `A0 INTER interval(--vector[&1;&1]:real^2,vector[&1;&1]) = {}`] THEN
      MP_TAC(ISPECL [`--vector[&2;&2]:real^2`; `vector[&2;&2]:real^2`]
        INTERVAL_OPEN_SUBSET_CLOSED) THEN
      SET_TAC[];
      ALL_TAC] THEN
    ABBREV_TAC `D = IMAGE (GG:real^3->real^2) k UNION inside (IMAGE GG k)` THEN
