    SUBGOAL_THEN `pl_cell_with_boundary 2 (D:real^2->bool) (IMAGE (GG:real^3->real^2) k)`
    ASSUME_TAC THENL [EXPAND_TAC "D" THEN ASM_SIMP_TAC[MOI_S5C_PLANE_DISK]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `k:real^3->bool` o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
      REWRITE_RULE[moi_s5c_hyp] o check (MOI_S5C_HEAD "moi_s5c_hyp")) THEN
    ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `IMAGE (FF:real^2->real^3) D` THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`2`; `D:real^2->bool`; `IMAGE (GG:real^3->real^2) k`;
                     `IMAGE (FF:real^2->real^3) D`; `FF:real^2->real^3`;
                     `GG:real^3->real^2`] MOI_S5C_CELL_PLH) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
      CONJ_TAC THENL [ALL_TAC; MESON_TAC[MOI_S5C_SIMPLEX2_R3]] THEN
      MATCH_MP_TAC MOI_S5C_PLH_RESTRICT THEN
      MAP_EVERY EXISTS_TAC [`A0:real^2->bool`; `B:real^3->bool`] THEN
      ONCE_REWRITE_TAC[PL_HOMEOMORPHISM_SYM] THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
      MATCH_MP_TAC MOI_S5C_CELL_POLYHEDRON THEN
      MAP_EVERY EXISTS_TAC [`2`; `IMAGE (GG:real^3->real^2) k`] THEN ASM_REWRITE_TAC[];
      UNDISCH_TAC `D SUBSET (A0:real^2->bool)` THEN
      UNDISCH_TAC `!x. x IN A0 ==> (FF:real^2->real^3) x IN B /\ GG (FF x) = x` THEN
      SET_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`IMAGE (GG:real^3->real^2) k`;
                 `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])`]
    MOI_S5C_CONNECTED_SIDE) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [SUBGOAL_THEN
       `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) =
        {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | t = &1}}` SUBST1_TAC THENL
       [REWRITE_TAC[EXTENSION; IN_ELIM_THM; MOI_S5C_IN_RF1]; ALL_TAC] THEN
      MATCH_MP_TAC MOI_S5C_NBAND_CONNECTED THEN
      REWRITE_TAC[IN_ELIM_THM; GSYM MEMBER_NOT_EMPTY] THEN
      CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
      CONJ_TAC THENL [REAL_ARITH_TAC; EXISTS_TAC `&1` THEN REAL_ARITH_TAC];
      UNDISCH_TAC `IMAGE (GG:real^3->real^2) k SUBSET
         A0 DIFF (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
                  relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))` THEN
      SET_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(q ==> F) ==> p \/ q ==> p`) THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`outside (IMAGE (GG:real^3->real^2) k)`;
                 `interval(--vector[&1;&1]:real^2,vector[&1;&1])`]
    OPEN_INTER_CLOSURE_EQ_EMPTY) THEN
  SUBGOAL_THEN `closure(interval(--vector[&1;&1]:real^2,vector[&1;&1])) =
                interval[--vector[&1;&1],vector[&1;&1]]` SUBST1_TAC THENL
   [MATCH_MP_TAC CLOSURE_OPEN_INTERVAL THEN
    REWRITE_TAC[INTERVAL_NE_EMPTY; DIMINDEX_2; FORALL_2; VECTOR_NEG_COMPONENT;
                VECTOR_2] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT `~a /\ b ==> ~(a <=> b)`) THEN CONJ_TAC THENL
   [MP_TAC(MATCH_MP RELATIVE_FRONTIER_SUBSET
      (ISPECL [`--vector[&1;&1]:real^2`; `vector[&1;&1]:real^2`] CLOSED_INTERVAL)) THEN
    UNDISCH_TAC `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) SUBSET
                 outside (IMAGE (GG:real^3->real^2) k)` THEN
    SUBGOAL_THEN `~(relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) = {})`
    MP_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; MOI_S5C_IN_RF1] THEN
      EXISTS_TAC `vector[&1;&0]:real^2` THEN REWRITE_TAC[VECTOR_2] THEN REAL_ARITH_TAC;
      SET_TAC[]];
    MAP_EVERY UNDISCH_TAC
     [`interval(--vector[&1;&1]:real^2,vector[&1;&1]) SUBSET
       inside (IMAGE (GG:real^3->real^2) k)`;
      `inside (IMAGE (GG:real^3->real^2) k) INTER outside (IMAGE GG k) = {}`] THEN
    SET_TAC[]]);;

(* Nesting of the circles, in the square annulus model and in the plane.   *)

let MOI_S5C_SQC_NEST = prove
 (`!B K FF GG Q c d0 k k'.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     k IN components {x | x IN B /\ x$3 = c} /\
     k' IN components {x | x IN B /\ x$3 = c} /\ ~(k = k')
     ==> DISJOINT k k' /\
         DISJOINT (IMAGE (GG:real^3->real^2) k) (IMAGE GG k') /\
         (IMAGE GG k SUBSET inside (IMAGE GG k') \/
          IMAGE GG k' SUBSET inside (IMAGE GG k))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `k:real^3->bool`]
    MOI_S5C_SQC_BASIC) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `k':real^3->bool`]
    MOI_S5C_SQC_BASIC) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(STRIP_ASSUME_TAC) THEN DISCH_THEN(STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `DISJOINT (k:real^3->bool) k'` ASSUME_TAC THENL
   [REWRITE_TAC[DISJOINT] THEN ASM_MESON_TAC[COMPONENTS_NONOVERLAP]; ALL_TAC] THEN
  SUBGOAL_THEN `DISJOINT (IMAGE (GG:real^3->real^2) k) (IMAGE GG k')` ASSUME_TAC THENL
   [FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
    MAP_EVERY UNDISCH_TAC
     [`DISJOINT (k:real^3->bool) k'`; `k SUBSET (B:real^3->bool)`;
      `k' SUBSET (B:real^3->bool)`;
      `!y. y IN B ==> (GG:real^3->real^2) y IN
                        interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                        interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
                      (FF:real^2->real^3) (GG y) = y`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOI_S5C_JORDAN_NEST THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN EXISTS_TAC `vec 0:real^2` THEN
  SUBGOAL_THEN `(vec 0:real^2) IN interval(--vector[&1;&1],vector[&1;&1])` MP_TAC THENL
   [REWRITE_TAC[MOI_S5C_IN_SQO; VEC_COMPONENT] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM SET_TAC[]);;

let MOI_S5C_PLANE_NEST = prove
 (`!B K FF GG Q c d0 k k' j j'.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     k IN components {x | x IN B /\ x$3 = c} /\
     k' IN components {x | x IN B /\ x$3 = c} /\ ~(k = k') /\
     k = IMAGE (moi_s35_lift c) j /\ k' = IMAGE (moi_s35_lift c) j'
     ==> pl_sphere 1 j /\ pl_sphere 1 j' /\ DISJOINT j j' /\
         (!y. max (abs(y$1)) (abs(y$2)) <= &3 / &16 ==> y IN inside j) /\
         (!y. max (abs(y$1)) (abs(y$2)) <= &3 / &16 ==> y IN inside j') /\
         (j SUBSET inside j' \/ j' SUBSET inside j)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `moi_s35_ess c (k:real^3->bool) /\ moi_s35_ess c (k':real^3->bool)`
  MP_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o CONJUNCT1 o REWRITE_RULE[moi_s5c_hyp] o check
      (MOI_S5C_HEAD "moi_s5c_hyp")) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`c:real`; `IMAGE (moi_s35_lift c) j`; `j:real^2->bool`] MOI_S5C_ESS_LIFT) THEN
  MP_TAC(ISPECL [`c:real`; `IMAGE (moi_s35_lift c) j'`; `j':real^2->bool`] MOI_S5C_ESS_LIFT) THEN
  REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN DISCH_THEN SUBST1_TAC THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `DISJOINT (j:real^2->bool) j'` ASSUME_TAC THENL
   [SUBGOAL_THEN `DISJOINT (k:real^3->bool) k'` MP_TAC THENL
     [REWRITE_TAC[DISJOINT] THEN ASM_MESON_TAC[COMPONENTS_NONOVERLAP]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`c:real`; `j:real^2->bool`] MOI_S5C_PROJ_IMAGE_LIFT) THEN
    MP_TAC(ISPECL [`c:real`; `j':real^2->bool`] MOI_S5C_PROJ_IMAGE_LIFT) THEN
    SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOI_S5C_JORDAN_NEST THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC;
    MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN EXISTS_TAC `vec 0:real^2` THEN
    CONJ_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN REWRITE_TAC[VEC_COMPONENT] THEN
    REAL_ARITH_TAC]);;

(* The order of the circles in the square annulus model.                   *)

let moi_s5c_sql = new_definition
 `moi_s5c_sql (GG:real^3->real^2) k k' <=> IMAGE GG k SUBSET inside (IMAGE GG k')`;;

let MOI_S5C_SQL_ORDER = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c
     ==> (!k. k IN components {x | x IN B /\ x$3 = c} ==> ~moi_s5c_sql GG k k) /\
         (!k k' k''. k IN components {x | x IN B /\ x$3 = c} /\
                     k' IN components {x | x IN B /\ x$3 = c} /\
                     k'' IN components {x | x IN B /\ x$3 = c} /\
                     moi_s5c_sql GG k k' /\ moi_s5c_sql GG k' k''
                     ==> moi_s5c_sql GG k k'') /\
         (!k k'. k IN components {x | x IN B /\ x$3 = c} /\
                 k' IN components {x | x IN B /\ x$3 = c} /\ ~(k = k')
                 ==> moi_s5c_sql GG k k' \/ moi_s5c_sql GG k' k) /\
         (!k k'. k IN components {x | x IN B /\ x$3 = c} /\
                 k' IN components {x | x IN B /\ x$3 = c} /\ moi_s5c_sql GG k k'
                 ==> ~moi_s5c_sql GG k' k /\ ~(k = k'))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!k. k IN components {x | x IN B /\ x$3 = c}
        ==> ~(IMAGE (GG:real^3->real^2) k = {}) /\
            IMAGE GG k homeomorphic sphere(vec 0:real^2,&1)`
  ASSUME_TAC THENL
   [GEN_TAC THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `k:real^3->bool`]
      MOI_S5C_SQC_BASIC) THEN
    ASM_REWRITE_TAC[IMAGE_EQ_EMPTY] THEN SIMP_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[moi_s5c_sql] THEN
  SUBGOAL_THEN
   `!k k'. k IN components {x | x IN B /\ x$3 = c} /\
           k' IN components {x | x IN B /\ x$3 = c} /\
           IMAGE (GG:real^3->real^2) k SUBSET inside (IMAGE GG k')
           ==> ~(IMAGE (GG:real^3->real^2) k' SUBSET inside (IMAGE GG k)) /\
               inside (IMAGE GG k) SUBSET inside (IMAGE GG k')`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`IMAGE (GG:real^3->real^2) k`; `IMAGE (GG:real^3->real^2) k'`]
      MOI_S5C_NESTED_INSIDE) THEN
    ASM_SIMP_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPEC `IMAGE (GG:real^3->real^2) k` OUTSIDE_INSIDE) THEN
    MP_TAC(ISPEC `IMAGE (GG:real^3->real^2) k` INSIDE_NO_OVERLAP) THEN
    SUBGOAL_THEN `~(IMAGE (GG:real^3->real^2) k' = {})` MP_TAC THENL
     [ASM_SIMP_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `IMAGE (GG:real^3->real^2) k' SUBSET outside (IMAGE GG k)` THEN
    SET_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `k:real^3->bool` THEN DISCH_TAC THEN
    MP_TAC(ISPEC `IMAGE (GG:real^3->real^2) k` INSIDE_NO_OVERLAP) THEN
    SUBGOAL_THEN `~(IMAGE (GG:real^3->real^2) k = {})` MP_TAC THENL
     [ASM_SIMP_TAC[]; SET_TAC[]];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `inside (IMAGE (GG:real^3->real^2) k')` THEN ASM_SIMP_TAC[];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `k:real^3->bool`; `k':real^3->bool`] MOI_S5C_SQC_NEST) THEN
    ASM_SIMP_TAC[];
    REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [ASM_MESON_TAC[];
      DISCH_THEN SUBST_ALL_TAC THEN
      MP_TAC(ISPEC `IMAGE (GG:real^3->real^2) k'` INSIDE_NO_OVERLAP) THEN
      SUBGOAL_THEN `~(IMAGE (GG:real^3->real^2) k' = {})` MP_TAC THENL
       [ASM_SIMP_TAC[]; ASM SET_TAC[]]]]);;

let MOI_S5C_SQL_SUCC = prove
 (`!B K FF GG Q c d0 k.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     k IN components {x | x IN B /\ x$3 = c} /\
     (?k'. k' IN components {x | x IN B /\ x$3 = c} /\ moi_s5c_sql GG k k')
     ==> ?k'. k' IN components {x | x IN B /\ x$3 = c} /\ moi_s5c_sql GG k k' /\
              !k''. k'' IN components {x | x IN B /\ x$3 = c} /\
                    moi_s5c_sql GG k k'' /\ ~(k'' = k')
                    ==> moi_s5c_sql GG k' k''`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_SQL_ORDER) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`moi_s5c_sql (GG:real^3->real^2)`;
    `{k' | k' IN components {x:real^3 | x IN B /\ x$3 = c} /\ moi_s5c_sql GG k k'}`]
    MOI_S5C_FINITE_TOTAL_MIN) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `components {x:real^3 | x IN B /\ x$3 = c}` THEN
    CONJ_TAC THENL
     [ASM_MESON_TAC[MOI_S5C_MSET_FACTS]; SET_TAC[]];
    ALL_TAC] THEN
  ANTS_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM; GSYM MEMBER_NOT_EMPTY] THEN
    CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN CONJ_TAC THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[IN_ELIM_THM] THEN MESON_TAC[]);;

let MOI_S5C_SQL_PRED = prove
 (`!B K FF GG Q c d0 k.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     k IN components {x | x IN B /\ x$3 = c} /\
     (?k'. k' IN components {x | x IN B /\ x$3 = c} /\ moi_s5c_sql GG k' k)
     ==> ?k'. k' IN components {x | x IN B /\ x$3 = c} /\ moi_s5c_sql GG k' k /\
              !k''. k'' IN components {x | x IN B /\ x$3 = c} /\
                    moi_s5c_sql GG k'' k /\ ~(k'' = k')
                    ==> moi_s5c_sql GG k'' k'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_SQL_ORDER) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`\a b. moi_s5c_sql (GG:real^3->real^2) b a`;
    `{k' | k' IN components {x:real^3 | x IN B /\ x$3 = c} /\ moi_s5c_sql GG k' k}`]
    MOI_S5C_FINITE_TOTAL_MIN) THEN
  REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `components {x:real^3 | x IN B /\ x$3 = c}` THEN
    CONJ_TAC THENL
     [ASM_MESON_TAC[MOI_S5C_MSET_FACTS]; SET_TAC[]];
    ALL_TAC] THEN
  ANTS_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM; GSYM MEMBER_NOT_EMPTY] THEN
    CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN CONJ_TAC THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[IN_ELIM_THM] THEN MESON_TAC[]);;

let MOI_S5C_SQL_MINMAX = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c
     ==> (?k. k IN components {x | x IN B /\ x$3 = c} /\
              !k'. k' IN components {x | x IN B /\ x$3 = c} /\ ~(k' = k)
                   ==> moi_s5c_sql GG k k') /\
         (?k. k IN components {x | x IN B /\ x$3 = c} /\
              !k'. k' IN components {x | x IN B /\ x$3 = c} /\ ~(k' = k)
                   ==> moi_s5c_sql GG k' k)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_SQL_ORDER) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `FINITE (components {x:real^3 | x IN B /\ x$3 = c}) /\
                ~(components {x:real^3 | x IN B /\ x$3 = c} = {})` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [ASM_MESON_TAC[MOI_S5C_MSET_FACTS]; ALL_TAC] THEN
    DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[moi_s5c_hyp] o check
      (MOI_S5C_HEAD "moi_s5c_hyp")) THEN
    ASM_REWRITE_TAC[CARD_CLAUSES] THEN ARITH_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL [`moi_s5c_sql (GG:real^3->real^2)`;
      `components {x:real^3 | x IN B /\ x$3 = c}`] MOI_S5C_FINITE_TOTAL_MIN) THEN
    ASM_REWRITE_TAC[] THEN ANTS_TAC THENL [ASM_MESON_TAC[]; MESON_TAC[]];
    MP_TAC(ISPECL [`\a b. moi_s5c_sql (GG:real^3->real^2) b a`;
      `components {x:real^3 | x IN B /\ x$3 = c}`] MOI_S5C_FINITE_TOTAL_MIN) THEN
    ASM_REWRITE_TAC[] THEN ANTS_TAC THENL [ASM_MESON_TAC[]; MESON_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Planar regions between nested circles, and the sides of connected       *)
(* sets off the level c.                                                   *)
(* ------------------------------------------------------------------------- *)

let moi_s5c_rg = new_definition
 `moi_s5c_rg (X:real^2->bool) Y = (Y UNION inside Y) DIFF inside X`;;

let moi_s5c_rgo = new_definition
 `moi_s5c_rgo (X:real^2->bool) Y = inside Y DIFF (X UNION inside X)`;;

let MOI_S5C_CONN_OFF_LEVEL = prove
 (`!(s:real^3->bool) c.
     connected s /\ (!x. x IN s ==> ~(x$3 = c))
     ==> (!x. x IN s ==> c < x$3) \/ (!x. x IN s ==> x$3 < c)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(TAUT `(~p ==> q) ==> p \/ q`) THEN
  REWRITE_TAC[NOT_FORALL_THM; NOT_IMP; REAL_NOT_LT] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:real^3` STRIP_ASSUME_TAC) THEN
  X_GEN_TAC `y:real^3` THEN DISCH_TAC THEN
  REWRITE_TAC[GSYM REAL_NOT_LE] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`s:real^3->bool`; `x:real^3`; `y:real^3`; `c:real`; `3`]
    CONNECTED_IVT_COMPONENT) THEN
  ASM_REWRITE_TAC[DIMINDEX_3; ARITH] THEN ASM_MESON_TAC[]);;

let MOI_S5C_ANN_ENDS_CLOSURE = prove
 (`!(a:real^N->bool) j0 j1.
     pl_annulus_with_ends a j0 j1 ==> j0 UNION j1 SUBSET closure (a DIFF (j0 UNION j1))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ANN_PARTS) THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[pl_annulus_with_ends] o check
    (MOI_S5C_HEAD "pl_annulus_with_ends")) THEN
  DISCH_THEN(X_CHOOSE_THEN `f:real^2->real^N` (X_CHOOSE_THEN `g:real^N->real^2`
    STRIP_ASSUME_TAC)) THEN
  FIRST_X_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[homeomorphism] o CONJUNCT1 o
    REWRITE_RULE[pl_homeomorphism] o check (MOI_S5C_HEAD "pl_homeomorphism")) THEN
  ABBREV_TAC `A0 = interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                   interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
  ABBREV_TAC `S0 = interval(--vector[&2;&2]:real^2,vector[&2;&2]) DIFF
                   interval[--vector[&1;&1]:real^2,vector[&1;&1]]` THEN
  SUBGOAL_THEN
   `S0 SUBSET (A0:real^2->bool) /\ closure S0 SUBSET A0 /\
    relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
    relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) SUBSET closure S0 /\
    A0 DIFF (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
             relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) = S0`
  STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `S0 SUBSET (A0:real^2->bool) /\ closed (A0:real^2->bool)` STRIP_ASSUME_TAC THENL
     [MAP_EVERY EXPAND_TAC ["S0"; "A0"] THEN CONJ_TAC THENL
       [REWRITE_TAC[SUBSET; IN_DIFF; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO] THEN REAL_ARITH_TAC;
        MATCH_MP_TAC CLOSED_DIFF THEN REWRITE_TAC[CLOSED_INTERVAL; OPEN_INTERVAL]];
      ALL_TAC] THEN
    ASM_SIMP_TAC[CLOSURE_MINIMAL] THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_UNION; MOI_S5C_IN_RF1; MOI_S5C_IN_RF2] THEN
      X_GEN_TAC `y:real^2` THEN DISCH_TAC THEN
      SUBGOAL_THEN `norm(y:real^2) <= &4` ASSUME_TAC THENL
       [MP_TAC(ISPEC `y:real^2` NORM_LE_L1) THEN
        REWRITE_TAC[DIMINDEX_2; SUM_2] THEN UNDISCH_TAC
         `max (abs((y:real^2)$1)) (abs(y$2)) = &1 \/ max (abs(y$1)) (abs(y$2)) = &2` THEN
        REAL_ARITH_TAC;
        ALL_TAC] THEN
      REWRITE_TAC[CLOSURE_APPROACHABLE] THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
      ABBREV_TAC `t = min (e / &8) (&1 / &4)` THEN
      SUBGOAL_THEN `&0 < t /\ t <= e / &8 /\ t <= &1 / &4` STRIP_ASSUME_TAC THENL
       [EXPAND_TAC "t" THEN UNDISCH_TAC `&0 < e` THEN REAL_ARITH_TAC; ALL_TAC] THEN
      FIRST_X_ASSUM(DISJ_CASES_TAC o check (is_disj o concl)) THENL
       [EXISTS_TAC `(&1 + t) % y:real^2` THEN
        SUBGOAL_THEN `&0 <= &1 + t` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
        EXPAND_TAC "S0" THEN ASM_SIMP_TAC[IN_DIFF; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO;
          MOI_S5C_N2_CMUL] THEN
        REWRITE_TAC[dist; VECTOR_ARITH `(&1 + t) % y - y:real^2 = t % y`; NORM_MUL] THEN
        CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
        ASM_SIMP_TAC[REAL_ARITH `&0 < t ==> abs t = t`] THEN
        MATCH_MP_TAC REAL_LET_TRANS THEN EXISTS_TAC `t * &4` THEN CONJ_TAC THENL
         [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC];
        EXISTS_TAC `(&1 - t) % y:real^2` THEN
        SUBGOAL_THEN `&0 <= &1 - t` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
        EXPAND_TAC "S0" THEN ASM_SIMP_TAC[IN_DIFF; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO;
          MOI_S5C_N2_CMUL] THEN
        REWRITE_TAC[dist; VECTOR_ARITH `(&1 - t) % y - y:real^2 = --t % y`; NORM_MUL] THEN
        CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
        ASM_SIMP_TAC[REAL_ARITH `&0 < t ==> abs(--t) = t`] THEN
        MATCH_MP_TAC REAL_LET_TRANS THEN EXISTS_TAC `t * &4` THEN CONJ_TAC THENL
         [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC]];
      MAP_EVERY EXPAND_TAC ["S0"; "A0"] THEN
      REWRITE_TAC[EXTENSION; IN_DIFF; IN_UNION; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO;
                  MOI_S5C_IN_RF1; MOI_S5C_IN_RF2] THEN GEN_TAC THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `a DIFF (j0 UNION j1) = IMAGE (f:real^2->real^N) S0` SUBST1_TAC THENL
   [FIRST_X_ASSUM(SUBST1_TAC o SYM o check (fun th -> try rand(concl th) = `S0:real^2->bool`
      with Failure _ -> false)) THEN
    MAP_EVERY UNDISCH_TAC
     [`IMAGE (f:real^2->real^N) A0 = a`;
      `j0 = IMAGE (f:real^2->real^N)
              (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))`;
      `j1 = IMAGE (f:real^2->real^N)
              (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`;
      `!x. x IN A0 ==> (g:real^N->real^2) ((f:real^2->real^N) x) = x`] THEN
    MP_TAC MOI_S5C_A0_FACTS THEN ASM_REWRITE_TAC[] THEN SET_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `IMAGE (f:real^2->real^N) (closure S0)` THEN
  CONJ_TAC THENL
   [UNDISCH_TAC `j0 = IMAGE (f:real^2->real^N)
              (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))` THEN
    UNDISCH_TAC `j1 = IMAGE (f:real^2->real^N)
              (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))` THEN
    UNDISCH_TAC `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
                 relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) SUBSET
                 closure S0` THEN
    SET_TAC[];
    MATCH_MP_TAC IMAGE_CLOSURE_SUBSET THEN
    REWRITE_TAC[CLOSED_CLOSURE; CLOSURE_SUBSET] THEN
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `A0:real^2->bool` THEN
    ASM_REWRITE_TAC[]]);;

let MOI_S5C_RG_FACTS = prove
 (`!X Y:real^2->bool.
     pl_sphere 1 X /\ pl_sphere 1 Y /\ X SUBSET inside Y
     ==> pl_annulus_with_ends (moi_s5c_rg X Y) X Y /\
         moi_s5c_rgo X Y = moi_s5c_rg X Y DIFF (X UNION Y) /\
         connected (moi_s5c_rgo X Y) /\ ~(moi_s5c_rgo X Y = {}) /\
         open (moi_s5c_rgo X Y) /\ X UNION Y SUBSET closure (moi_s5c_rgo X Y) /\
         moi_s5c_rg X Y = moi_s5c_rgo X Y UNION X UNION Y /\
         compact (moi_s5c_rg X Y) /\
         moi_s5c_rgo X Y SUBSET inside Y /\ moi_s5c_rgo X Y SUBSET outside X /\
         DISJOINT (moi_s5c_rgo X Y) (X UNION Y) /\
         inside X SUBSET inside Y /\ X UNION inside X SUBSET inside Y /\
         Y SUBSET outside X`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(X:real^2->bool) homeomorphic sphere(vec 0:real^2,&1) /\
                (Y:real^2->bool) homeomorphic sphere(vec 0:real^2,&1)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_NESTED_INSIDE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_ANN2) THEN
  ASM_REWRITE_TAC[GSYM moi_s5c_rg] THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ANN_PARTS) THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP MOI_S5C_ANN_OPEN_INTERIOR) THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP MOI_S5C_ANN_ENDS_CLOSURE) THEN
  MP_TAC(ISPEC `X:real^2->bool` INSIDE_NO_OVERLAP) THEN
  MP_TAC(ISPEC `Y:real^2->bool` INSIDE_NO_OVERLAP) THEN
  MP_TAC(ISPEC `X:real^2->bool` OUTSIDE_INSIDE) THEN REPEAT DISCH_TAC THEN
  SUBGOAL_THEN `moi_s5c_rgo X Y = moi_s5c_rg X Y DIFF ((X:real^2->bool) UNION Y)`
  ASSUME_TAC THENL
   [REWRITE_TAC[moi_s5c_rg; moi_s5c_rgo] THEN
    MAP_EVERY UNDISCH_TAC
     [`X SUBSET inside(Y:real^2->bool)`; `inside X SUBSET inside(Y:real^2->bool)`;
      `inside Y INTER Y:real^2->bool = {}`; `inside X INTER X:real^2->bool = {}`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  ASM_SIMP_TAC[MOI_S5C_ANN_COMPACT; SET_RULE `(s:real^2->bool) DIFF t UNION t = s UNION t`] THEN
  REWRITE_TAC[moi_s5c_rg] THEN
  MAP_EVERY UNDISCH_TAC
   [`X SUBSET inside(Y:real^2->bool)`; `inside X SUBSET inside(Y:real^2->bool)`;
    `inside Y INTER Y:real^2->bool = {}`; `inside X INTER X:real^2->bool = {}`;
    `outside X = (:real^2) DIFF (X UNION inside X)`] THEN
  SET_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The two collar halves of a circle J of B lie on the two sides of         *)
(* its model circle GG J; regions between consecutive circles; their sides. *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_HALVES = prove
 (`!B K FF GG Q c d0 J.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c}
     ==> connected {Q x t | x IN J /\ &0 < t /\ t < &1} /\
         connected {Q x t | x IN J /\ -- &1 < t /\ t < &0} /\
         {Q x t | x IN J /\ &0 < t /\ t < &1} SUBSET B /\
         {Q x t | x IN J /\ -- &1 < t /\ t < &0} SUBSET B /\
         (!z. z IN {Q x t | x IN J /\ &0 < t /\ t < &1} ==> c < z$3) /\
         (!z. z IN {Q x t | x IN J /\ -- &1 < t /\ t < &0} ==> z$3 < c) /\
         open_in (subtopology euclidean B) {Q x t | x IN J /\ -- &1 < t /\ t < &1} /\
         {Q x t | x IN J /\ -- &1 < t /\ t < &1} =
         {Q x t | x IN J /\ &0 < t /\ t < &1} UNION J UNION
         {Q x t | x IN J /\ -- &1 < t /\ t < &0}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
    MOI_S5C_SQC_BASIC) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `J SUBSET {x:real^3 | x IN B /\ x$3 = c}` ASSUME_TAC THENL
   [ASM SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(!x t. x IN J /\ abs t <= &1
           ==> (Q:real^3->real->real^3) x t IN B /\ (Q x t)$3 = c + t * d0) /\
    (!x. x IN J ==> Q x (&0) = x)`
  STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_collar] o check
      (MOI_S5C_HEAD "moi_s5c_collar")) THEN
    CONJ_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    ASM SET_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MOI_S5C_COLLAR_CONN_OPEN THEN
    MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `c:real`; `d0:real`] THEN
    ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
    MATCH_MP_TAC MOI_S5C_COLLAR_CONN_OPEN THEN
    MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `c:real`; `d0:real`] THEN
    ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
    REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[REAL_ARITH `&0 < t /\ t < &1 ==> abs t <= &1`];
    REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[REAL_ARITH `-- &1 < t /\ t < &0 ==> abs t <= &1`];
    REWRITE_TAC[IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `((Q:real^3->real->real^3) x t)$3 = c + t * d0` SUBST1_TAC THENL
     [ASM_MESON_TAC[REAL_ARITH `&0 < t /\ t < &1 ==> abs t <= &1`]; ALL_TAC] THEN
    MATCH_MP_TAC(REAL_ARITH `&0 < x ==> c < c + x`) THEN MATCH_MP_TAC REAL_LT_MUL THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `((Q:real^3->real->real^3) x t)$3 = c + t * d0` SUBST1_TAC THENL
     [ASM_MESON_TAC[REAL_ARITH `-- &1 < t /\ t < &0 ==> abs t <= &1`]; ALL_TAC] THEN
    MATCH_MP_TAC(REAL_ARITH `&0 < --t * d ==> c + t * d < c`) THEN
    MATCH_MP_TAC REAL_LT_MUL THEN ASM_REAL_ARITH_TAC;
    MP_TAC(ISPECL [`B:real^3->bool`; `c:real`; `d0:real`; `Q:real^3->real->real^3`;
                   `J:real^3->bool`; `-- &1`; `&1`] MOI_S5C_COLLAR_OPEN) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
    MATCH_MP_TAC MOI_S5C_COMPONENT_OPEN_IN THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[EXTENSION; IN_UNION; IN_ELIM_THM] THEN X_GEN_TAC `z:real^3` THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `t:real` STRIP_ASSUME_TAC)) THEN
      ASM_CASES_TAC `t = &0` THENL
       [DISJ2_TAC THEN DISJ1_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
      DISJ_CASES_TAC(REAL_ARITH `&0 < t \/ t < &0 \/ t = &0`) THENL
       [DISJ1_TAC THEN MAP_EVERY EXISTS_TAC [`x:real^3`; `t:real`] THEN ASM_REWRITE_TAC[];
        DISJ2_TAC THEN DISJ2_TAC THEN MAP_EVERY EXISTS_TAC [`x:real^3`; `t:real`] THEN
        ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC];
      DISCH_THEN(DISJ_CASES_THEN2
        (X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `t:real` STRIP_ASSUME_TAC))
        (DISJ_CASES_THEN2 ASSUME_TAC
          (X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `t:real` STRIP_ASSUME_TAC)))) THENL
       [MAP_EVERY EXISTS_TAC [`x:real^3`; `t:real`] THEN ASM_REWRITE_TAC[] THEN
        ASM_REAL_ARITH_TAC;
        MAP_EVERY EXISTS_TAC [`z:real^3`; `&0`] THEN ASM_SIMP_TAC[] THEN REAL_ARITH_TAC;
        MAP_EVERY EXISTS_TAC [`x:real^3`; `t:real`] THEN ASM_REWRITE_TAC[] THEN
        ASM_REAL_ARITH_TAC]]]);;

let MOI_S5C_HALF_CLOSURE = prove
 (`!B K FF GG Q c d0 J.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c}
     ==> J SUBSET closure {Q x t | x IN J /\ &0 < t /\ t < &1} /\
         J SUBSET closure {Q x t | x IN J /\ -- &1 < t /\ t < &0}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  SUBGOAL_THEN `J SUBSET {x:real^3 | x IN B /\ x$3 = c}` ASSUME_TAC THENL
   [ASM_MESON_TAC[IN_COMPONENTS_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `!x. x IN J ==> (Q:real^3->real->real^3) x (&0) = x` ASSUME_TAC THENL
   [FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_collar] o check
      (MOI_S5C_HEAD "moi_s5c_collar")) THEN
    REPEAT STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM SET_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THEN REWRITE_TAC[SUBSET; CLOSURE_APPROACHABLE] THEN
  X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `c:real`; `d0:real`; `Q:real^3->real->real^3`;
                 `x:real^3`] MOI_S5C_COLLAR_TCONT) THEN
  (ANTS_TAC THENL [ASM SET_TAC[]; ALL_TAC]) THEN
  REWRITE_TAC[continuous_on] THEN DISCH_THEN(MP_TAC o SPEC `vec 0:real^1`) THEN
  REWRITE_TAC[IN_INTERVAL_1; DROP_VEC; DROP_NEG] THEN
  CONV_TAC REAL_RAT_REDUCE_CONV THEN DISCH_THEN(MP_TAC o SPEC `e:real`) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dl:real` STRIP_ASSUME_TAC) THEN
  ABBREV_TAC `t = min (dl / &2) (&1 / &2)` THEN
  (SUBGOAL_THEN `&0 < t /\ t < dl /\ t < &1` STRIP_ASSUME_TAC THENL
    [EXPAND_TAC "t" THEN UNDISCH_TAC `&0 < dl` THEN REAL_ARITH_TAC; ALL_TAC]) THEN
  REWRITE_TAC[IN_ELIM_THM] THENL
   [EXISTS_TAC `(Q:real^3->real->real^3) x t` THEN CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`x:real^3`; `t:real`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `lift t`);
    EXISTS_TAC `(Q:real^3->real->real^3) x (--t)` THEN CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`x:real^3`; `--t`] THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `lift(--t)`)] THEN
  REWRITE_TAC[LIFT_DROP; DIST_LIFT; GSYM LIFT_NUM; DROP_VEC] THEN
  ASM_SIMP_TAC[] THEN
  (ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC]) THEN
  REWRITE_TAC[DIST_SYM]);;

let MOI_S5C_HALF_SIDES = prove
 (`!B K FF GG Q c d0 J.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c}
     ==> (IMAGE (GG:real^3->real^2) {Q x t | x IN J /\ &0 < t /\ t < &1} SUBSET
          outside (IMAGE GG J) /\
          IMAGE GG {Q x t | x IN J /\ -- &1 < t /\ t < &0} SUBSET inside (IMAGE GG J)) \/
         (IMAGE GG {Q x t | x IN J /\ &0 < t /\ t < &1} SUBSET inside (IMAGE GG J) /\
          IMAGE GG {Q x t | x IN J /\ -- &1 < t /\ t < &0} SUBSET outside (IMAGE GG J))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
    MOI_S5C_SQC_BASIC) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
    MOI_S5C_HALVES) THEN
  ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `Hp = {(Q:real^3->real->real^3) x t | x IN J /\ &0 < t /\ t < &1}` THEN
  ABBREV_TAC `Hm = {(Q:real^3->real->real^3) x t | x IN J /\ -- &1 < t /\ t < &0}` THEN
  ABBREV_TAC `NJ = {(Q:real^3->real->real^3) x t | x IN J /\ -- &1 < t /\ t < &1}` THEN
  DISCH_THEN(STRIP_ASSUME_TAC) THEN DISCH_THEN(STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPEC `IMAGE (GG:real^3->real^2) J` JORDAN_INSIDE_OUTSIDE_GEN) THEN
  ASM_REWRITE_TAC[DIMINDEX_2; LE_REFL] THEN STRIP_TAC THEN
  SUBGOAL_THEN `DISJOINT (IMAGE (GG:real^3->real^2) J) (IMAGE GG Hp) /\
                DISJOINT (IMAGE (GG:real^3->real^2) J) (IMAGE GG Hm)` STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `DISJOINT J (Hp:real^3->bool) /\ DISJOINT J (Hm:real^3->bool)`
    MP_TAC THENL
     [CONJ_TAC THEN REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
      X_GEN_TAC `z:real^3` THEN STRIP_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o SPEC `z:real^3` o check (fun th -> is_forall(concl th) &&
          free_in `Hp:real^3->bool` (concl th)));
        FIRST_X_ASSUM(MP_TAC o SPEC `z:real^3` o check (fun th -> is_forall(concl th) &&
          free_in `Hm:real^3->bool` (concl th)))] THEN
      ASM_SIMP_TAC[REAL_LT_REFL];
      ALL_TAC] THEN
    MAP_EVERY UNDISCH_TAC
     [`J SUBSET (B:real^3->bool)`; `Hp SUBSET (B:real^3->bool)`;
      `Hm SUBSET (B:real^3->bool)`;
      `!y. y IN B ==> (GG:real^3->real^2) y IN
                        interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                        interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
                      (FF:real^2->real^3) (GG y) = y`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`IMAGE (GG:real^3->real^2) J`; `IMAGE (GG:real^3->real^2) Hp`]
    MOI_S5C_CONNECTED_SIDE) THEN
  MP_TAC(ISPECL [`IMAGE (GG:real^3->real^2) J`; `IMAGE (GG:real^3->real^2) Hm`]
    MOI_S5C_CONNECTED_SIDE) THEN
  SUBGOAL_THEN `connected (IMAGE (GG:real^3->real^2) Hp) /\
                connected (IMAGE (GG:real^3->real^2) Hm)` (fun th -> REWRITE_TAC[th]) THENL
   [CONJ_TAC THEN MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `B:real^3->bool` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `?W. open W /\ IMAGE (GG:real^3->real^2) J SUBSET W /\
        W SUBSET IMAGE GG Hp UNION IMAGE GG J UNION IMAGE GG Hm`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`GG:real^3->real^2`; `FF:real^2->real^3`; `B:real^3->bool`;
      `interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
       interval(--vector[&1;&1]:real^2,vector[&1;&1])`; `NJ:real^3->bool`]
      HOMEOMORPHISM_IMP_OPEN_MAP) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[pl_homeomorphism]; ALL_TAC] THEN
    REWRITE_TAC[OPEN_IN_OPEN] THEN
    DISCH_THEN(X_CHOOSE_THEN `O:real^2->bool` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `O INTER (interval(--vector[&2;&2]:real^2,vector[&2;&2]) DIFF
                         interval[--vector[&1;&1]:real^2,vector[&1;&1]])` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC OPEN_INTER THEN ASM_REWRITE_TAC[] THEN MATCH_MP_TAC OPEN_DIFF THEN
      REWRITE_TAC[OPEN_INTERVAL; CLOSED_INTERVAL];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `interval(--vector[&2;&2]:real^2,vector[&2;&2]) DIFF
      interval[--vector[&1;&1]:real^2,vector[&1;&1]] =
      (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
       interval(--vector[&1;&1]:real^2,vector[&1;&1])) DIFF
      (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
       relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`
    SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_DIFF; IN_UNION; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO;
                  MOI_S5C_IN_RF1; MOI_S5C_IN_RF2] THEN GEN_TAC THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    UNDISCH_TAC `IMAGE (GG:real^3->real^2) NJ =
      (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
       interval(--vector[&1;&1]:real^2,vector[&1;&1])) INTER O` THEN
    UNDISCH_TAC `NJ = (Hp:real^3->bool) UNION J UNION Hm` THEN
    DISCH_THEN SUBST1_TAC THEN
    UNDISCH_TAC `IMAGE (GG:real^3->real^2) J SUBSET
      (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
       interval(--vector[&1;&1]:real^2,vector[&1;&1])) DIFF
      (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
       relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))` THEN
    REWRITE_TAC[IMAGE_UNION] THEN
    MOI_S5C_ABS_SET_TAC
     [`relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])`;
      `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])`;
      `interval[--vector[&2;&2]:real^2,vector[&2;&2]]`;
      `interval(--vector[&1;&1]:real^2,vector[&1;&1])`;
      `IMAGE (GG:real^3->real^2) Hp`; `IMAGE (GG:real^3->real^2) J`;
      `IMAGE (GG:real^3->real^2) Hm`];
    ALL_TAC] THEN
  SUBGOAL_THEN `?z:real^2. z IN IMAGE GG (J:real^3->bool)` STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[MEMBER_NOT_EMPTY; IMAGE_EQ_EMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:real^2) IN W /\ z IN closure(outside (IMAGE (GG:real^3->real^2) J)) /\
                z IN closure(inside (IMAGE (GG:real^3->real^2) J))` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM SET_TAC[];
      UNDISCH_TAC `frontier(outside (IMAGE (GG:real^3->real^2) J)) = IMAGE GG J` THEN
      REWRITE_TAC[frontier] THEN ASM SET_TAC[];
      UNDISCH_TAC `frontier(inside (IMAGE (GG:real^3->real^2) J)) = IMAGE GG J` THEN
      REWRITE_TAC[frontier] THEN ASM SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(W INTER outside (IMAGE (GG:real^3->real^2) J) = {}) /\
                ~(W INTER inside (IMAGE (GG:real^3->real^2) J) = {})`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`W:real^2->bool`; `outside (IMAGE (GG:real^3->real^2) J)`]
        OPEN_INTER_CLOSURE_EQ_EMPTY);
      MP_TAC(ISPECL [`W:real^2->bool`; `inside (IMAGE (GG:real^3->real^2) J)`]
        OPEN_INTER_CLOSURE_EQ_EMPTY)] THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN EXISTS_TAC `z:real^2` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(IMAGE (GG:real^3->real^2) Hp SUBSET inside (IMAGE GG J) /\
      IMAGE GG Hm SUBSET inside (IMAGE GG J)) /\
    ~(IMAGE (GG:real^3->real^2) Hp SUBSET outside (IMAGE GG J) /\
      IMAGE GG Hm SUBSET outside (IMAGE GG J))`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`W SUBSET IMAGE (GG:real^3->real^2) Hp UNION IMAGE GG J UNION IMAGE GG Hm`;
      `~(W INTER outside (IMAGE (GG:real^3->real^2) J) = {})`;
      `~(W INTER inside (IMAGE (GG:real^3->real^2) J) = {})`;
      `inside (IMAGE (GG:real^3->real^2) J) INTER outside (IMAGE GG J) = {}`] THEN
    MP_TAC(ISPEC `IMAGE (GG:real^3->real^2) J` INSIDE_NO_OVERLAP) THEN
    MP_TAC(ISPEC `IMAGE (GG:real^3->real^2) J` OUTSIDE_NO_OVERLAP) THEN
    MOI_S5C_ABS_SET_TAC [`IMAGE (GG:real^3->real^2) Hp`; `IMAGE (GG:real^3->real^2) Hm`;
                         `IMAGE (GG:real^3->real^2) J`; `inside (IMAGE (GG:real^3->real^2) J)`;
                         `outside (IMAGE (GG:real^3->real^2) J)`];
    ALL_TAC] THEN
  UNDISCH_TAC `~(IMAGE (GG:real^3->real^2) Hp SUBSET inside (IMAGE GG J) /\
                 IMAGE GG Hm SUBSET inside (IMAGE GG J))` THEN
  UNDISCH_TAC `~(IMAGE (GG:real^3->real^2) Hp SUBSET outside (IMAGE GG J) /\
                 IMAGE GG Hm SUBSET outside (IMAGE GG J))` THEN
  CONV_TAC TAUT);;

(* ------------------------------------------------------------------------- *)
(* Connected sets next to a circle lie in the adjacent region; sides        *)
(* of the regions between consecutive circles.                             *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_CONN_IN_RGO_OUT = prove
 (`!tt X Y:real^2->bool.
     connected tt /\ tt SUBSET outside X /\ DISJOINT tt Y /\ X SUBSET inside Y /\
     ~(X INTER closure tt = {}) /\ pl_sphere 1 Y
     ==> tt SUBSET moi_s5c_rgo X Y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(Y:real^2->bool) homeomorphic sphere(vec 0:real^2,&1)` ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPEC `Y:real^2->bool` JORDAN_INSIDE_OUTSIDE_GEN) THEN
  ASM_REWRITE_TAC[DIMINDEX_2; LE_REFL] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`Y:real^2->bool`; `tt:real^2->bool`] MOI_S5C_CONNECTED_SIDE) THEN
  ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[DISJOINT_SYM] THEN ASM_REWRITE_TAC[] THEN
  STRIP_TAC THENL
   [REWRITE_TAC[moi_s5c_rgo] THEN MP_TAC(ISPEC `X:real^2->bool` OUTSIDE_INSIDE) THEN
    UNDISCH_TAC `tt SUBSET outside(X:real^2->bool)` THEN
    UNDISCH_TAC `tt SUBSET inside(Y:real^2->bool)` THEN SET_TAC[];
    SUBGOAL_THEN `closure tt SUBSET Y UNION outside(Y:real^2->bool)` MP_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `closure(outside Y:real^2->bool)` THEN
      ASM_SIMP_TAC[SUBSET_CLOSURE] THEN
      UNDISCH_TAC `frontier(outside Y:real^2->bool) = Y` THEN
      MP_TAC(ISPEC `outside Y:real^2->bool` INTERIOR_OPEN) THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[frontier] THEN SET_TAC[];
      ALL_TAC] THEN
    MAP_EVERY UNDISCH_TAC
     [`~(X INTER closure tt:real^2->bool = {})`; `X SUBSET inside(Y:real^2->bool)`;
      `inside Y INTER outside Y:real^2->bool = {}`] THEN
    MP_TAC(ISPEC `Y:real^2->bool` INSIDE_NO_OVERLAP) THEN SET_TAC[]]);;

let MOI_S5C_CONN_IN_RGO_IN = prove
 (`!tt X Y:real^2->bool.
     connected tt /\ tt SUBSET inside Y /\ DISJOINT tt X /\ X SUBSET inside Y /\
     ~(Y INTER closure tt = {}) /\ pl_sphere 1 X /\ pl_sphere 1 Y
     ==> tt SUBSET moi_s5c_rgo X Y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(X:real^2->bool) homeomorphic sphere(vec 0:real^2,&1) /\
                (Y:real^2->bool) homeomorphic sphere(vec 0:real^2,&1)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPEC `X:real^2->bool` JORDAN_INSIDE_OUTSIDE_GEN) THEN
  ASM_REWRITE_TAC[DIMINDEX_2; LE_REFL] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_NESTED_INSIDE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `tt:real^2->bool`] MOI_S5C_CONNECTED_SIDE) THEN
  ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[DISJOINT_SYM] THEN ASM_REWRITE_TAC[] THEN
  STRIP_TAC THENL
   [SUBGOAL_THEN `closure tt SUBSET X UNION inside(X:real^2->bool)` MP_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `closure(inside X:real^2->bool)` THEN
      ASM_SIMP_TAC[SUBSET_CLOSURE] THEN
      UNDISCH_TAC `frontier(inside X:real^2->bool) = X` THEN
      MP_TAC(ISPEC `inside X:real^2->bool` INTERIOR_OPEN) THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[frontier] THEN SET_TAC[];
      ALL_TAC] THEN
    MAP_EVERY UNDISCH_TAC
     [`~(Y INTER closure tt:real^2->bool = {})`; `X SUBSET inside(Y:real^2->bool)`;
      `inside X SUBSET inside(Y:real^2->bool)`] THEN
    MP_TAC(ISPEC `Y:real^2->bool` INSIDE_NO_OVERLAP) THEN SET_TAC[];
    REWRITE_TAC[moi_s5c_rgo] THEN MP_TAC(ISPEC `X:real^2->bool` OUTSIDE_INSIDE) THEN
    UNDISCH_TAC `tt SUBSET outside(X:real^2->bool)` THEN
    UNDISCH_TAC `tt SUBSET inside(Y:real^2->bool)` THEN SET_TAC[]]);;

let MOI_S5C_MENTIONS (s:string) (tm:term) =
  can (find_term (fun t -> is_const t && fst(dest_const t) = s)) tm;;

let MOI_S5C_RGO_SIDE = prove
 (`!B K FF GG Q c d0 X Y.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     pl_sphere 1 X /\ pl_sphere 1 Y /\ X SUBSET inside Y /\
     moi_s5c_rgo X Y SUBSET
       interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
       interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
     (!J. J IN components {x | x IN B /\ x$3 = c}
          ==> DISJOINT (moi_s5c_rgo X Y) (IMAGE (GG:real^3->real^2) J))
     ==> connected (IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y)) /\
         IMAGE FF (moi_s5c_rgo X Y) SUBSET B /\
         ((!z. z IN IMAGE FF (moi_s5c_rgo X Y) ==> c < z$3) \/
          (!z. z IN IMAGE FF (moi_s5c_rgo X Y) ==> z$3 < c))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RG_FACTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(ASSUME_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2) THEN
  SUBGOAL_THEN `connected (IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y))` ASSUME_TAC THENL
   [MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
    EXISTS_TAC `interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y) SUBSET B` ASSUME_TAC THENL
   [UNDISCH_TAC `moi_s5c_rgo X Y SUBSET
       interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
       interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
    UNDISCH_TAC `!x. x IN interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                         interval(--vector[&1;&1]:real^2,vector[&1;&1])
                     ==> (FF:real^2->real^3) x IN B /\ GG (FF x) = x` THEN
    SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOI_S5C_CONN_OFF_LEVEL THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `w:real^2` THEN REPEAT DISCH_TAC THEN
  SUBGOAL_THEN `(FF:real^2->real^3) w IN {x:real^3 | x IN B /\ x$3 = c}` MP_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN ASM SET_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPEC `{x:real^3 | x IN B /\ x$3 = c}` UNIONS_COMPONENTS) THEN
  REWRITE_TAC[EXTENSION; IN_UNIONS] THEN
  DISCH_THEN(MP_TAC o SPEC `(FF:real^2->real^3) w`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `J:real^3->bool` STRIP_ASSUME_TAC) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `J:real^3->bool` o check (fun th -> is_forall(concl th) &&
    MOI_S5C_MENTIONS "moi_s5c_rgo" (concl th) && MOI_S5C_MENTIONS "DISJOINT" (concl th))) THEN
  ASM_REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `w:real^2`) THEN ASM_REWRITE_TAC[IN_IMAGE] THEN
  EXISTS_TAC `(FF:real^2->real^3) w` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(w:real^2) IN interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                              interval(--vector[&1;&1]:real^2,vector[&1;&1])` MP_TAC THENL
   [UNDISCH_TAC `moi_s5c_rgo X Y SUBSET
       interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
       interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
    UNDISCH_TAC `(w:real^2) IN moi_s5c_rgo X Y` THEN SET_TAC[];
    ALL_TAC] THEN
  UNDISCH_TAC `!x. x IN interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                       interval(--vector[&1;&1]:real^2,vector[&1;&1])
                   ==> (FF:real^2->real^3) x IN B /\ GG (FF x) = x` THEN
  MESON_TAC[]);;

let MOI_S5C_HALF_IMAGE = prove
 (`!B K FF GG Q c d0 J a b.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c} /\
     ((a = &0 /\ b = &1) \/ (a = -- &1 /\ b = &0))
     ==> connected (IMAGE (GG:real^3->real^2) {Q x t | x IN J /\ a < t /\ t < b}) /\
         IMAGE GG J SUBSET closure (IMAGE GG {Q x t | x IN J /\ a < t /\ t < b}) /\
         {Q x t | x IN J /\ a < t /\ t < b} SUBSET B /\
         DISJOINT (IMAGE GG {Q x t | x IN J /\ a < t /\ t < b}) (IMAGE GG J) /\
         DISJOINT (IMAGE GG {Q x t | x IN J /\ a < t /\ t < b})
           (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
            relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) /\
         (!J'. J' IN components {x | x IN B /\ x$3 = c}
               ==> DISJOINT (IMAGE GG {Q x t | x IN J /\ a < t /\ t < b}) (IMAGE GG J'))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ab")))) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  SUBGOAL_THEN
   `connected {(Q:real^3->real->real^3) x t | x IN J /\ a < t /\ t < b} /\
    {(Q:real^3->real->real^3) x t | x IN J /\ a < t /\ t < b} SUBSET B /\
    J SUBSET closure {(Q:real^3->real->real^3) x t | x IN J /\ a < t /\ t < b} /\
    (!z. z IN {(Q:real^3->real->real^3) x t | x IN J /\ a < t /\ t < b}
         ==> ~(z$3 = c)) /\
    (!t. a < t /\ t < b ==> abs t <= &1)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
      MOI_S5C_HALVES) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
      MOI_S5C_HALF_CLOSURE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(STRIP_ASSUME_TAC) THEN DISCH_THEN(STRIP_ASSUME_TAC) THEN
    REMOVE_THEN "ab" (DISJ_CASES_THEN (CONJUNCTS_THEN SUBST1_TAC)) THEN
    ASM_REWRITE_TAC[] THEN
    (CONJ_TAC THENL [ALL_TAC; REAL_ARITH_TAC]) THEN
    FIRST
     [MATCH_MP_TAC(MESON[REAL_LT_REFL]
        `(!z:real^3. z IN s ==> c < z$3) ==> !z. z IN s ==> ~(z$3 = c)`) THEN
      FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC(MESON[REAL_LT_REFL]
        `(!z:real^3. z IN s ==> z$3 < c) ==> !z. z IN s ==> ~(z$3 = c)`) THEN
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  ABBREV_TAC `H = {(Q:real^3->real->real^3) x t | x IN J /\ a < t /\ t < b}` THEN
  SUBGOAL_THEN `closure H SUBSET (B:real^3->bool)` ASSUME_TAC THENL
   [MATCH_MP_TAC CLOSURE_MINIMAL THEN ASM_SIMP_TAC[COMPACT_IMP_CLOSED]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `B:real^3->bool` THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `IMAGE (GG:real^3->real^2) (closure H)` THEN
    CONJ_TAC THENL [ASM_SIMP_TAC[IMAGE_SUBSET]; ALL_TAC] THEN
    MATCH_MP_TAC IMAGE_CLOSURE_SUBSET THEN
    REWRITE_TAC[CLOSED_CLOSURE; CLOSURE_SUBSET] THEN
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `B:real^3->bool` THEN
    ASM_REWRITE_TAC[];
    FIRST_ASSUM ACCEPT_TAC;
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
      MOI_S5C_SQC_BASIC) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MAP_EVERY UNDISCH_TAC
     [`H SUBSET (B:real^3->bool)`; `J SUBSET (B:real^3->bool)`;
      `!z:real^3. z IN H ==> ~(z$3 = c)`; `!x:real^3. x IN J ==> x$3 = c`;
      `!y. y IN B ==> (GG:real^3->real^2) y IN
                        interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                        interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
                      (FF:real^2->real^3) (GG y) = y`] THEN
    SET_TAC[];
    SUBGOAL_THEN `H SUBSET moi_s35_ttube` ASSUME_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `moi_s5c_otube` THEN
      REWRITE_TAC[MOI_S5C_OTUBE] THEN MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `{x:real^3 | x IN B /\ abs(x$3 - c) <= d0}` THEN ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "H" THEN REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
      X_GEN_TAC `z:real^3` THEN
      DISCH_THEN(X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `t:real` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(x:real^3) IN B /\ x$3 = c` STRIP_ASSUME_TAC THENL
       [UNDISCH_TAC `(x:real^3) IN J` THEN
        UNDISCH_TAC `J IN components {x:real^3 | x IN B /\ x$3 = c}` THEN
        DISCH_THEN(MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `abs t <= &1` ASSUME_TAC THENL
       [FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> is_forall(concl th) &&
          MOI_S5C_MENTIONS "real_abs" (concl th) &&
          length(fst(strip_forall(concl th))) = 1)) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      FIRST_ASSUM(MP_TAC o SPECL [`x:real^3`; `t:real`] o CONJUNCT1 o CONJUNCT2 o
        REWRITE_RULE[moi_s5c_collar] o check (MOI_S5C_HEAD "moi_s5c_collar")) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[REAL_ADD_SUB] THEN
      REWRITE_TAC[REAL_ABS_MUL] THEN
      SUBGOAL_THEN `abs d0 = d0` SUBST1_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_LID] THEN
      MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; IN_IMAGE] THEN
    X_GEN_TAC `w:real^2` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `z:real^3` STRIP_ASSUME_TAC) ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:real^3) IN moi_s35_ttube /\ z IN B` STRIP_ASSUME_TAC THENL
     [MAP_EVERY UNDISCH_TAC [`H SUBSET moi_s35_ttube`; `H SUBSET (B:real^3->bool)`;
                             `(z:real^3) IN H`] THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(z:real^3) IN IMAGE (FF:real^2->real^3)
       (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
        relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))` MP_TAC THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `w:real^2` THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `!y. y IN B ==> (GG:real^3->real^2) y IN
                        interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                        interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
                      (FF:real^2->real^3) (GG y) = y` THEN
      DISCH_THEN(MP_TAC o SPEC `z:real^3`) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
      ALL_TAC] THEN
    UNDISCH_TAC `DISJOINT
      (IMAGE (FF:real^2->real^3) (relative_frontier (interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION
       IMAGE FF (relative_frontier (interval[--vector[&2;&2]:real^2,vector[&2;&2]])))
      moi_s35_ttube` THEN
    UNDISCH_TAC `(z:real^3) IN moi_s35_ttube` THEN REWRITE_TAC[IMAGE_UNION] THEN SET_TAC[];
    X_GEN_TAC `J':real^3->bool` THEN DISCH_TAC THEN
    SUBGOAL_THEN `J' SUBSET {x:real^3 | x IN B /\ x$3 = c}` ASSUME_TAC THENL
     [ASM_MESON_TAC[IN_COMPONENTS_SUBSET]; ALL_TAC] THEN
    MAP_EVERY UNDISCH_TAC
     [`H SUBSET (B:real^3->bool)`; `J' SUBSET {x:real^3 | x IN B /\ x$3 = c}`;
      `!z:real^3. z IN H ==> ~(z$3 = c)`;
      `!y. y IN B ==> (GG:real^3->real^2) y IN
                        interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                        interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
                      (FF:real^2->real^3) (GG y) = y`] THEN
    SET_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The extended family of model circles (the two boundary squares and      *)
(* the circles GG J), its nesting order, consecutive pairs and regions.    *)
(* ------------------------------------------------------------------------- *)

let moi_s5c_ext = new_definition
 `moi_s5c_ext (B:real^3->bool) (GG:real^3->real^2) c (X:real^2->bool) <=>
    X = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]) \/
    X = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]) \/
    ?J. J IN components {x | x IN B /\ x$3 = c} /\ X = IMAGE GG J`;;

let moi_s5c_cons = new_definition
 `moi_s5c_cons (B:real^3->bool) (GG:real^3->real^2) c (X:real^2->bool) Y <=>
    moi_s5c_ext B GG c X /\ moi_s5c_ext B GG c Y /\ X SUBSET inside Y /\
    !W. moi_s5c_ext B GG c W ==> ~(X SUBSET inside W /\ W SUBSET inside Y)`;;

let MOI_S5C_EXT_FINITE = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0
     ==> FINITE {X | moi_s5c_ext B (GG:real^3->real^2) c X}`,
  REPEAT GEN_TAC THEN DISCH_THEN(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) INSERT
              relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) INSERT
              IMAGE (IMAGE (GG:real^3->real^2)) (components {x:real^3 | x IN B /\ x$3 = c})` THEN
  ASM_SIMP_TAC[FINITE_INSERT; FINITE_IMAGE] THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM; moi_s5c_ext; IN_INSERT; IN_IMAGE] THEN MESON_TAC[]);;

let MOI_S5C_EXT_ORDER = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c
     ==> (!X. moi_s5c_ext B (GG:real^3->real^2) c X
              ==> pl_sphere 1 X /\ X homeomorphic sphere(vec 0:real^2,&1) /\
                  ~(X = {}) /\
                  X SUBSET interval[--vector[&2;&2],vector[&2;&2]] DIFF
                           interval(--vector[&1;&1],vector[&1;&1])) /\
         (!X Y. moi_s5c_ext B GG c X /\ moi_s5c_ext B GG c Y /\ ~(X = Y)
                ==> DISJOINT X Y /\ (X SUBSET inside Y \/ Y SUBSET inside X)) /\
         (!X Y W. moi_s5c_ext B GG c X /\ moi_s5c_ext B GG c Y /\
                  moi_s5c_ext B GG c W /\ X SUBSET inside Y /\ Y SUBSET inside W
                  ==> X SUBSET inside W) /\
         (!X. moi_s5c_ext B GG c X ==> ~(X SUBSET inside X)) /\
         (!X Y. moi_s5c_ext B GG c X /\ moi_s5c_ext B GG c Y /\ X SUBSET inside Y
                ==> ~(Y SUBSET inside X) /\ ~(X = Y))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `R1 = relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])` THEN
  ABBREV_TAC `R2 = relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])` THEN
  SUBGOAL_THEN
   `pl_sphere 1 R1 /\ pl_sphere 1 R2 /\
    inside R1 = interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
    inside R2 = interval(--vector[&2;&2]:real^2,vector[&2;&2]) /\
    R1 SUBSET interval[--vector[&2;&2],vector[&2;&2]] DIFF
              interval(--vector[&1;&1],vector[&1;&1]) /\
    R2 SUBSET interval[--vector[&2;&2],vector[&2;&2]] DIFF
              interval(--vector[&1;&1],vector[&1;&1]) /\
    R1 SUBSET inside R2 /\ DISJOINT R1 R2 /\ ~(R1 = {}) /\ ~(R2 = {})`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["R1"; "R2"] THEN
    SIMP_TAC[MOI_S5C_SQ_JORDAN; REAL_ARITH `&0 < &1 /\ &0 < &2`] THEN
    REWRITE_TAC[MOI_S5C_A0_FACTS] THEN
    REWRITE_TAC[SUBSET; DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; MOI_S5C_IN_RF1;
                MOI_S5C_IN_RF2; MOI_S5C_IN_SQO; GSYM MEMBER_NOT_EMPTY] THEN
    REPEAT CONJ_TAC THENL
     [REAL_ARITH_TAC; REAL_ARITH_TAC;
      EXISTS_TAC `vector[&1;&0]:real^2` THEN REWRITE_TAC[VECTOR_2] THEN REAL_ARITH_TAC;
      EXISTS_TAC `vector[&2;&0]:real^2` THEN REWRITE_TAC[VECTOR_2] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!J. J IN components {x:real^3 | x IN B /\ x$3 = c}
        ==> pl_sphere 1 (IMAGE (GG:real^3->real^2) J) /\
            IMAGE GG J homeomorphic sphere(vec 0:real^2,&1) /\ ~(IMAGE GG J = {}) /\
            IMAGE GG J SUBSET interval[--vector[&2;&2],vector[&2;&2]] DIFF
                              interval(--vector[&1;&1],vector[&1;&1]) /\
            R1 SUBSET inside (IMAGE GG J) /\ IMAGE GG J SUBSET inside R2 /\
            DISJOINT R1 (IMAGE GG J) /\ DISJOINT R2 (IMAGE GG J)`
  (LABEL_TAC "circ") THENL
   [GEN_TAC THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
      MOI_S5C_SQC_BASIC) THEN
    ASM_REWRITE_TAC[IMAGE_EQ_EMPTY] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THEN TRY(ASM SET_TAC[]) THEN
    UNDISCH_TAC `IMAGE (GG:real^3->real^2) J UNION inside (IMAGE GG J) SUBSET
                 interval(--vector[&2;&2],vector[&2;&2])` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!X. moi_s5c_ext B (GG:real^3->real^2) c X
        ==> pl_sphere 1 X /\ X homeomorphic sphere(vec 0:real^2,&1) /\ ~(X = {}) /\
            X SUBSET interval[--vector[&2;&2],vector[&2;&2]] DIFF
                     interval(--vector[&1;&1],vector[&1;&1])`
  ASSUME_TAC THENL
   [GEN_TAC THEN ASM_REWRITE_TAC[moi_s5c_ext] THEN STRIP_TAC THEN ASM_SIMP_TAC[] THEN
    MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!X Y. moi_s5c_ext B (GG:real^3->real^2) c X /\ moi_s5c_ext B GG c Y /\ ~(X = Y)
          ==> DISJOINT X Y /\ (X SUBSET inside Y \/ Y SUBSET inside X)`
  ASSUME_TAC THENL
   [SUBGOAL_THEN
     `!J J'. J IN components {x:real^3 | x IN B /\ x$3 = c} /\
             J' IN components {x:real^3 | x IN B /\ x$3 = c} /\
             ~(IMAGE (GG:real^3->real^2) J = IMAGE GG J')
             ==> DISJOINT (IMAGE GG J) (IMAGE GG J') /\
                 (IMAGE GG J SUBSET inside (IMAGE GG J') \/
                  IMAGE GG J' SUBSET inside (IMAGE GG J))`
    ASSUME_TAC THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
        `J:real^3->bool`; `J':real^3->bool`] MOI_S5C_SQC_NEST) THEN
      ASM_REWRITE_TAC[] THEN ANTS_TAC THENL [ASM_MESON_TAC[]; SIMP_TAC[]];
      ALL_TAC] THEN
    REWRITE_TAC[moi_s5c_ext] THEN
    REWRITE_TAC[ASSUME `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) = R1`;
                ASSUME `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) = R2`] THEN
    UNDISCH_TAC `DISJOINT (R1:real^2->bool) R2` THEN
    UNDISCH_TAC `R1 SUBSET inside (R2:real^2->bool)` THEN
    USE_THEN "circ" MP_TAC THEN
    POP_ASSUM MP_TAC THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN
    DISCH_THEN(LABEL_TAC "nest") THEN DISCH_THEN(LABEL_TAC "circ") THEN
    REPEAT DISCH_TAC THEN REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2
      (REPEAT_TCL DISJ_CASES_THEN (fun th -> if is_exists(concl th)
         then X_CHOOSE_THEN `J1:real^3->bool` STRIP_ASSUME_TAC th else ASSUME_TAC th))
      (CONJUNCTS_THEN2
        (REPEAT_TCL DISJ_CASES_THEN (fun th -> if is_exists(concl th)
           then X_CHOOSE_THEN `J2:real^3->bool` STRIP_ASSUME_TAC th else ASSUME_TAC th))
        ASSUME_TAC)) THEN
    REPEAT(FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th -> is_eq(concl th) &&
      (lhs(concl th) = `X:real^2->bool` || lhs(concl th) = `Y:real^2->bool`)))) THEN
    FIRST
     [FIRST_X_ASSUM(MP_TAC o check (is_neg o concl)) THEN REWRITE_TAC[] THEN NO_TAC;
      ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[DISJOINT_SYM] THEN ASM_REWRITE_TAC[] THEN
      NO_TAC;
      USE_THEN "nest" (MP_TAC o SPECL [`J1:real^3->bool`; `J2:real^3->bool`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; SIMP_TAC[]] THEN
      NO_TAC;
      USE_THEN "circ" (MP_TAC o SPEC `J1:real^3->bool`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; MESON_TAC[DISJOINT_SYM]] THEN NO_TAC;
      USE_THEN "circ" (MP_TAC o SPEC `J2:real^3->bool`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; MESON_TAC[DISJOINT_SYM]] THEN NO_TAC];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `inside Y:real^2->bool` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`Y:real^2->bool`; `W:real^2->bool`] MOI_S5C_NESTED_INSIDE) THEN
    ASM_SIMP_TAC[];
    GEN_TAC THEN DISCH_TAC THEN MP_TAC(ISPEC `X:real^2->bool` INSIDE_NO_OVERLAP) THEN
    SUBGOAL_THEN `~(X:real^2->bool = {})` MP_TAC THENL [ASM_SIMP_TAC[]; SET_TAC[]];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_NESTED_INSIDE) THEN
    ASM_SIMP_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPEC `X:real^2->bool` INSIDE_NO_OVERLAP) THEN
    MP_TAC(ISPEC `X:real^2->bool` OUTSIDE_INSIDE) THEN
    SUBGOAL_THEN `~(X:real^2->bool = {}) /\ ~(Y:real^2->bool = {})` MP_TAC THENL
     [ASM_SIMP_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `Y SUBSET outside(X:real^2->bool)` THEN
    UNDISCH_TAC `X SUBSET inside(Y:real^2->bool)` THEN SET_TAC[]]);;

let MOI_S5C_EXT_ENDS = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c
     ==> moi_s5c_ext B (GG:real^3->real^2) c
           (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) /\
         moi_s5c_ext B GG c (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])) /\
         (!X. moi_s5c_ext B GG c X
              ==> X = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]) \/
                  relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]) SUBSET
                  inside X) /\
         (!X. moi_s5c_ext B GG c X
              ==> X = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]) \/
                  X SUBSET inside (relative_frontier(interval[--vector[&2;&2],
                                                              vector[&2;&2]]))) /\
         (!X. moi_s5c_ext B GG c X
              ==> ~(relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]) SUBSET
                    inside X) /\
                  ~(X SUBSET inside (relative_frontier(interval[--vector[&1;&1],
                                                                vector[&1;&1]]))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_EXT_ORDER) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `moi_s5c_ext B (GG:real^3->real^2) c
      (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) /\
    moi_s5c_ext B GG c (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))`
  STRIP_ASSUME_TAC THENL [REWRITE_TAC[moi_s5c_ext]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!X. moi_s5c_ext B (GG:real^3->real^2) c X
        ==> ~(relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) SUBSET
              inside X) /\
            ~(X SUBSET inside (relative_frontier(interval[--vector[&1;&1]:real^2,
                                                          vector[&1;&1]])))`
  ASSUME_TAC THENL
   [GEN_TAC THEN DISCH_TAC THEN CONJ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `inside X SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]]`
      ASSUME_TAC THENL
       [MATCH_MP_TAC INSIDE_SUBSET_CONVEX THEN REWRITE_TAC[CONVEX_INTERVAL] THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `X:real^2->bool` o check (fun th ->
          is_forall(concl th) && MOI_S5C_MENTIONS "pl_sphere" (concl th))) THEN
        ASM_REWRITE_TAC[] THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `open(inside(X:real^2->bool))` ASSUME_TAC THENL
       [MATCH_MP_TAC OPEN_INSIDE THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `X:real^2->bool` o check (fun th ->
          is_forall(concl th) && MOI_S5C_MENTIONS "pl_sphere" (concl th))) THEN
        ASM_REWRITE_TAC[] THEN
        MESON_TAC[COMPACT_IMP_CLOSED; MOI_SCD_PL_SPHERE_POLYHEDRON; PL_POLYHEDRON_IMP_COMPACT];
        ALL_TAC] THEN
      SUBGOAL_THEN `inside X SUBSET interior(interval[--vector[&2;&2]:real^2,vector[&2;&2]])`
      MP_TAC THENL [MATCH_MP_TAC INTERIOR_MAXIMAL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[INTERIOR_INTERVAL] THEN
      UNDISCH_TAC `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) SUBSET
                   inside X` THEN
      REWRITE_TAC[SUBSET; MOI_S5C_IN_RF2; MOI_S5C_IN_SQO] THEN
      DISCH_TAC THEN DISCH_THEN(MP_TAC o SPEC `vector[&2;&0]:real^2`) THEN
      ASM_SIMP_TAC[VECTOR_2] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `vector[&2;&0]:real^2`) THEN
      REWRITE_TAC[VECTOR_2] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN MESON_TAC[];
      DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `X:real^2->bool` o check (fun th ->
        is_forall(concl th) && MOI_S5C_MENTIONS "pl_sphere" (concl th))) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      UNDISCH_TAC `X SUBSET inside (relative_frontier(interval[--vector[&1;&1]:real^2,
                                                              vector[&1;&1]]))` THEN
      SIMP_TAC[MOI_S5C_SQ_JORDAN; REAL_LT_01] THEN
      UNDISCH_TAC `X SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                            interval(--vector[&1;&1],vector[&1;&1])` THEN
      UNDISCH_TAC `~(X:real^2->bool = {})` THEN SET_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THEN X_GEN_TAC `X:real^2->bool` THEN DISCH_TAC THENL
   [ASM_CASES_TAC `X = relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])` THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MP_TAC o SPECL
      [`X:real^2->bool`; `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])`] o
      check (fun th -> is_forall(concl th) && length(fst(strip_forall(concl th))) = 2 &&
             MOI_S5C_MENTIONS "DISJOINT" (concl th))) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ASM_CASES_TAC `X = relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])` THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MP_TAC o SPECL
      [`X:real^2->bool`; `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])`] o
      check (fun th -> is_forall(concl th) && length(fst(strip_forall(concl th))) = 2 &&
             MOI_S5C_MENTIONS "DISJOINT" (concl th))) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

let MOI_S5C_CONS_EXISTS = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c
     ==> (!X. moi_s5c_ext B (GG:real^3->real^2) c X /\
              ~(X = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))
              ==> ?Y. moi_s5c_cons B GG c X Y) /\
         (!Y. moi_s5c_ext B (GG:real^3->real^2) c Y /\
              ~(Y = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]))
              ==> ?X. moi_s5c_cons B GG c X Y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_EXT_ORDER) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_EXT_ENDS) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_EXT_FINITE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "fin") THEN
  DISCH_THEN(STRIP_ASSUME_TAC) THEN DISCH_THEN(STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[moi_s5c_cons] THEN CONJ_TAC THEN GEN_TAC THEN STRIP_TAC THENL
   [MP_TAC(ISPECL [`\a b:real^2->bool. a SUBSET inside b`;
      `{W | moi_s5c_ext B (GG:real^3->real^2) c W /\ X SUBSET inside W}`]
      MOI_S5C_FINITE_TOTAL_MIN);
    MP_TAC(ISPECL [`\a b:real^2->bool. b SUBSET inside a`;
      `{W | moi_s5c_ext B (GG:real^3->real^2) c W /\ W SUBSET inside Y}`]
      MOI_S5C_FINITE_TOTAL_MIN)] THEN
  REWRITE_TAC[] THEN
  (ANTS_TAC THENL
    [MATCH_MP_TAC FINITE_SUBSET THEN
     EXISTS_TAC `{X | moi_s5c_ext B (GG:real^3->real^2) c X}` THEN
     USE_THEN "fin" (fun th -> REWRITE_TAC[th]) THEN SET_TAC[];
     ALL_TAC]) THEN
  REWRITE_TAC[IN_ELIM_THM] THEN
  (ANTS_TAC THENL
    [REPEAT CONJ_TAC THENL
      [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN ASM_MESON_TAC[];
       ASM_MESON_TAC[];
       ASM_MESON_TAC[]];
     ALL_TAC]) THEN
  DISCH_THEN(X_CHOOSE_THEN `m:real^2->bool` STRIP_ASSUME_TAC) THENL
   [EXISTS_TAC `m:real^2->bool`; EXISTS_TAC `m:real^2->bool`] THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `W:real^2->bool` THEN DISCH_TAC THEN STRIP_TAC THEN
  ASM_MESON_TAC[]);;

let MOI_S5C_EXT_FILL = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c
     ==> !X. moi_s5c_ext B (GG:real^3->real^2) c X
             ==> interval[--vector[&1;&1],vector[&1;&1]] SUBSET X UNION inside X /\
                 inside X SUBSET interval[--vector[&2;&2],vector[&2;&2]]`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN GEN_TAC THEN REWRITE_TAC[moi_s5c_ext] THEN
  SUBGOAL_THEN
   `interval[--vector[&1;&1]:real^2,vector[&1;&1]] =
    relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
    interval(--vector[&1;&1],vector[&1;&1]) /\
    interval(--vector[&1;&1]:real^2,vector[&1;&1]) SUBSET
    interval[--vector[&1;&1],vector[&1;&1]] /\
    interval[--vector[&1;&1]:real^2,vector[&1;&1]] SUBSET
    interval(--vector[&2;&2],vector[&2;&2]) /\
    interval(--vector[&2;&2]:real^2,vector[&2;&2]) SUBSET
    interval[--vector[&2;&2],vector[&2;&2]]`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[EXTENSION; SUBSET; IN_UNION; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO;
                MOI_S5C_IN_RF1] THEN REPEAT CONJ_TAC THEN GEN_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THENL
   [ASM_SIMP_TAC[MOI_S5C_SQ_JORDAN; REAL_LT_01] THEN ASM SET_TAC[];
    ASM_SIMP_TAC[MOI_S5C_SQ_JORDAN; REAL_ARITH `&0 < &2`] THEN ASM SET_TAC[];
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
      MOI_S5C_SQC_BASIC) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MAP_EVERY UNDISCH_TAC
     [`interval(--vector[&1;&1]:real^2,vector[&1;&1]) SUBSET inside (IMAGE GG (J:real^3->bool))`;
      `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) SUBSET
       inside (IMAGE GG (J:real^3->bool))`;
      `IMAGE (GG:real^3->real^2) J UNION inside (IMAGE GG J) SUBSET
       interval(--vector[&2;&2],vector[&2;&2])`;
      `interval[--vector[&1;&1]:real^2,vector[&1;&1]] =
       relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
       interval(--vector[&1;&1],vector[&1;&1])`;
      `interval(--vector[&2;&2]:real^2,vector[&2;&2]) SUBSET
       interval[--vector[&2;&2],vector[&2;&2]]`] THEN
    SET_TAC[]]);;

let MOI_S5C_CONS_FACTS = prove
 (`!B K FF GG Q c d0 X Y.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_cons B (GG:real^3->real^2) c X Y
     ==> pl_sphere 1 X /\ pl_sphere 1 Y /\ X SUBSET inside Y /\
         moi_s5c_rgo X Y SUBSET
           interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
           interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
         (!W. moi_s5c_ext B GG c W ==> DISJOINT (moi_s5c_rgo X Y) W) /\
         (!J. J IN components {x | x IN B /\ x$3 = c}
              ==> DISJOINT (moi_s5c_rgo X Y) (IMAGE GG J)) /\
         (!X' Y'. moi_s5c_cons B GG c X' Y' /\ (X' = X \/ Y' = Y) ==> X' = X /\ Y' = Y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_EXT_ORDER) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_EXT_ENDS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "e1") (CONJUNCTS_THEN2 (LABEL_TAC "e2") (LABEL_TAC "e3"))))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sph") (CONJUNCTS_THEN2 (LABEL_TAC "tot")
    (CONJUNCTS_THEN2 (LABEL_TAC "tr") (CONJUNCTS_THEN2 (LABEL_TAC "irr") (LABEL_TAC "asym"))))) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_cons] o check
    (MOI_S5C_HEAD "moi_s5c_cons")) THEN
  USE_THEN "sph" (MP_TAC o SPEC `X:real^2->bool`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] THEN
  USE_THEN "sph" (MP_TAC o SPEC `Y:real^2->bool`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `!W. moi_s5c_ext B (GG:real^3->real^2) c W
                    ==> DISJOINT (moi_s5c_rgo X Y) W` ASSUME_TAC THENL
   [X_GEN_TAC `W:real^2->bool` THEN DISCH_TAC THEN
    REWRITE_TAC[moi_s5c_rgo] THEN
    ASM_CASES_TAC `W:real^2->bool = X` THENL
     [FIRST_X_ASSUM SUBST1_TAC THEN SET_TAC[]; ALL_TAC] THEN
    ASM_CASES_TAC `W:real^2->bool = Y` THENL
     [FIRST_X_ASSUM SUBST1_TAC THEN MP_TAC(ISPEC `Y:real^2->bool` INSIDE_NO_OVERLAP) THEN
      SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `W SUBSET inside (X:real^2->bool) \/ Y SUBSET inside (W:real^2->bool)`
    MP_TAC THENL
     [USE_THEN "tot" (MP_TAC o SPECL [`W:real^2->bool`; `X:real^2->bool`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "tot" (MP_TAC o SPECL [`W:real^2->bool`; `Y:real^2->bool`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(SPEC `W:real^2->bool` (ASSUME `!W. moi_s5c_ext B (GG:real^3->real^2) c W
                         ==> ~(X SUBSET inside W /\ W SUBSET inside Y)`)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      CONV_TAC TAUT;
      ALL_TAC] THEN
    DISCH_THEN DISJ_CASES_TAC THENL
     [POP_ASSUM MP_TAC THEN SET_TAC[];
      USE_THEN "sph" (MP_TAC o SPEC `W:real^2->bool`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] THEN
      MP_TAC(ISPECL [`Y:real^2->bool`; `W:real^2->bool`] MOI_S5C_NESTED_INSIDE) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      MP_TAC(ISPEC `Y:real^2->bool` OUTSIDE_INSIDE) THEN
      UNDISCH_TAC `W SUBSET outside (Y:real^2->bool)` THEN SET_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_EXT_FILL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th ->
      MP_TAC(SPEC `X:real^2->bool` th) THEN MP_TAC(SPEC `Y:real^2->bool` th)) THEN
    ASM_REWRITE_TAC[moi_s5c_rgo] THEN
    MP_TAC(ISPECL [`--vector[&1;&1]:real^2`; `vector[&1;&1]:real^2`]
      INTERVAL_OPEN_SUBSET_CLOSED) THEN
    SET_TAC[];
    X_GEN_TAC `J:real^3->bool` THEN DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    REWRITE_TAC[moi_s5c_ext] THEN DISJ2_TAC THEN DISJ2_TAC THEN
    EXISTS_TAC `J:real^3->bool` THEN ASM_REWRITE_TAC[];
    REPEAT GEN_TAC THEN REWRITE_TAC[moi_s5c_cons] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THENL
     [ASM_CASES_TAC `Y':real^2->bool = Y` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "tot" (MP_TAC o SPECL [`Y':real^2->bool`; `Y:real^2->bool`]) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      ASM_CASES_TAC `X':real^2->bool = X` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "tot" (MP_TAC o SPECL [`X':real^2->bool`; `X:real^2->bool`]) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]]);;

let MOI_S5C_CONS_DISJOINT = prove
 (`!B K FF GG Q c d0 X Y X' Y'.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_cons B (GG:real^3->real^2) c X Y /\ moi_s5c_cons B GG c X' Y' /\
     ~(X = X' /\ Y = Y')
     ==> DISJOINT (moi_s5c_rgo X Y) (moi_s5c_rg X' Y')`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_EXT_ORDER) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sph") (CONJUNCTS_THEN2 (LABEL_TAC "tot")
    (CONJUNCTS_THEN2 (LABEL_TAC "tr") (CONJUNCTS_THEN2 (LABEL_TAC "irr") (LABEL_TAC "asym"))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "cf") THEN
  FIRST_X_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_cons] o check (fun th ->
    concl th = `moi_s5c_cons B (GG:real^3->real^2) c X Y`)) THEN
  FIRST_X_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_cons] o check (fun th ->
    concl th = `moi_s5c_cons B (GG:real^3->real^2) c X' Y'`)) THEN
  SUBGOAL_THEN `~(X:real^2->bool = X')` ASSUME_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `Y':real^2->bool = Y` ASSUME_TAC THENL
     [USE_THEN "cf" (MP_TAC o SPECL [`X':real^2->bool`; `Y':real^2->bool`] o
        CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[moi_s5c_cons]; SIMP_TAC[]];
      UNDISCH_TAC `~((X:real^2->bool) = X' /\ (Y:real^2->bool) = Y')` THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  USE_THEN "tot" (MP_TAC o SPECL [`X:real^2->bool`; `X':real^2->bool`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_TAC o CONJUNCT2) THENL
   [SUBGOAL_THEN `moi_s5c_rgo X Y SUBSET inside (X':real^2->bool)` MP_TAC THENL
     [ASM_CASES_TAC `Y:real^2->bool = X'` THENL
       [ASM_REWRITE_TAC[moi_s5c_rgo] THEN SET_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `Y SUBSET inside (X':real^2->bool)` ASSUME_TAC THENL
       [USE_THEN "tot" (MP_TAC o SPECL [`Y:real^2->bool`; `X':real^2->bool`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(DISJ_CASES_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `X':real^2->bool` o check (fun th ->
          is_forall(concl th) && MOI_S5C_MENTIONS "moi_s5c_ext" (concl th) &&
          free_in `X:real^2->bool` (concl th) && free_in `Y:real^2->bool` (concl th))) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "sph" (MP_TAC o SPEC `Y:real^2->bool`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] THEN
      USE_THEN "sph" (MP_TAC o SPEC `X':real^2->bool`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] THEN
      MP_TAC(ISPECL [`Y:real^2->bool`; `X':real^2->bool`] MOI_S5C_NESTED_INSIDE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[moi_s5c_rgo] THEN SET_TAC[];
      REWRITE_TAC[moi_s5c_rg] THEN SET_TAC[]];
    SUBGOAL_THEN `moi_s5c_rg X' Y' SUBSET X UNION inside (X:real^2->bool)` MP_TAC THENL
     [ASM_CASES_TAC `Y':real^2->bool = X` THENL
       [ASM_REWRITE_TAC[moi_s5c_rg] THEN SET_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `Y' SUBSET inside (X:real^2->bool)` ASSUME_TAC THENL
       [USE_THEN "tot" (MP_TAC o SPECL [`Y':real^2->bool`; `X:real^2->bool`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(DISJ_CASES_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `X:real^2->bool` o check (fun th ->
          is_forall(concl th) && MOI_S5C_MENTIONS "moi_s5c_ext" (concl th) &&
          free_in `X':real^2->bool` (concl th) && free_in `Y':real^2->bool` (concl th))) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "sph" (MP_TAC o SPEC `Y':real^2->bool`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] THEN
      USE_THEN "sph" (MP_TAC o SPEC `X:real^2->bool`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] THEN
      MP_TAC(ISPECL [`Y':real^2->bool`; `X:real^2->bool`] MOI_S5C_NESTED_INSIDE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      UNDISCH_TAC `Y' SUBSET inside (X:real^2->bool)` THEN
      REWRITE_TAC[moi_s5c_rg] THEN SET_TAC[];
      REWRITE_TAC[moi_s5c_rgo] THEN SET_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Sides of the regions of consecutive pairs, alternation along each       *)
(* circle, the covering of the square annulus by the regions, and the      *)
(* components of the two half spaces of B as images of the regions.        *)
(* ------------------------------------------------------------------------- *)

let moi_s5c_sd = new_definition
 `moi_s5c_sd (FF:real^2->real^3) c s (X:real^2->bool) Y <=>
    !z. z IN IMAGE FF (moi_s5c_rgo X Y) ==> &0 < s * (z$3 - c)`;;

let MOI_S5C_EXT_DISJ = prove
 (`!B (GG:real^3->real^2) c (tt:real^2->bool) W.
     moi_s5c_ext B GG c W /\
     DISJOINT tt (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
                  relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) /\
     (!J'. J' IN components {x | x IN B /\ x$3 = c} ==> DISJOINT tt (IMAGE GG J'))
     ==> DISJOINT tt W`,
  REPEAT GEN_TAC THEN REWRITE_TAC[moi_s5c_ext] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN TRY(ASM SET_TAC[] THEN NO_TAC) THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

let MOI_S5C_TYPE = prove
 (`!B K FF GG Q c d0 X Y.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_cons B (GG:real^3->real^2) c X Y
     ==> (moi_s5c_sd FF c (&1) X Y \/ moi_s5c_sd FF c (-- &1) X Y) /\
         ~(moi_s5c_sd FF c (&1) X Y /\ moi_s5c_sd FF c (-- &1) X Y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RGO_SIDE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "side"))) THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RG_FACTS) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `?z:real^3. z IN IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y)`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `~(moi_s5c_rgo X Y:real^2->bool = {})` THEN SET_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[moi_s5c_sd] THEN CONJ_TAC THENL
   [USE_THEN "side" DISJ_CASES_TAC THENL
     [DISJ1_TAC THEN GEN_TAC THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `z':real^3`) THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
      DISJ2_TAC THEN GEN_TAC THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `z':real^3`) THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC];
    DISCH_THEN(CONJUNCTS_THEN (MP_TAC o SPEC `z:real^3`)) THEN
    ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC]);;

let MOI_S5C_ALT_HALF = prove
 (`!B K FF GG Q c d0 J W Y (H:real^3->bool).
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c} /\
     moi_s5c_cons B (GG:real^3->real^2) c W (IMAGE GG J) /\
     moi_s5c_cons B GG c (IMAGE GG J) Y /\
     connected (IMAGE GG H) /\ IMAGE GG J SUBSET closure (IMAGE GG H) /\
     H SUBSET B /\ DISJOINT (IMAGE GG H) (IMAGE GG J) /\
     DISJOINT (IMAGE GG H)
       (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
        relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) /\
     (!J'. J' IN components {x | x IN B /\ x$3 = c}
           ==> DISJOINT (IMAGE GG H) (IMAGE GG J'))
     ==> (IMAGE GG H SUBSET outside (IMAGE GG J)
          ==> H SUBSET IMAGE (FF:real^2->real^3) (moi_s5c_rgo (IMAGE GG J) Y)) /\
         (IMAGE GG H SUBSET inside (IMAGE GG J)
          ==> H SUBSET IMAGE FF (moi_s5c_rgo W (IMAGE GG J)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!y:real^3. y IN B ==> (FF:real^2->real^3) ((GG:real^3->real^2) y) = y`
  (LABEL_TAC "fg") THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
    DISCH_THEN(fun th -> MESON_TAC[th]);
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `W:real^2->bool`; `IMAGE (GG:real^3->real^2) J`] MOI_S5C_CONS_FACTS) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `IMAGE (GG:real^3->real^2) J`; `Y:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `DISJOINT (IMAGE (GG:real^3->real^2) H) W /\ DISJOINT (IMAGE GG H) Y`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_EXT_DISJ THEN
    MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `GG:real^3->real^2`; `c:real`] THEN
    ASM_MESON_TAC[moi_s5c_cons];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(IMAGE (GG:real^3->real^2) J INTER closure (IMAGE GG H) = {})`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `J:real^3->bool`] MOI_S5C_SQC_BASIC) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    UNDISCH_TAC `IMAGE (GG:real^3->real^2) J SUBSET closure (IMAGE GG H)` THEN
    UNDISCH_TAC `~(J:real^3->bool = {})` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!S:real^2->bool. IMAGE (GG:real^3->real^2) H SUBSET S
                ==> H SUBSET IMAGE (FF:real^2->real^3) S`
  ASSUME_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[SUBSET; IN_IMAGE] THEN DISCH_TAC THEN
    X_GEN_TAC `z:real^3` THEN DISCH_TAC THEN
    EXISTS_TAC `(GG:real^3->real^2) z` THEN CONJ_TAC THENL
     [CONV_TAC SYM_CONV THEN USE_THEN "fg" MATCH_MP_TAC THEN
      UNDISCH_TAC `(z:real^3) IN H` THEN UNDISCH_TAC `H SUBSET (B:real^3->bool)` THEN
      SET_TAC[];
      FIRST_X_ASSUM MATCH_MP_TAC THEN EXISTS_TAC `z:real^3` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  CONJ_TAC THEN DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THENL
   [MATCH_MP_TAC MOI_S5C_CONN_IN_RGO_OUT THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC MOI_S5C_CONN_IN_RGO_IN THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `~(IMAGE (GG:real^3->real^2) J INTER closure (IMAGE GG H) = {})` THEN
    REWRITE_TAC[INTER_COMM]]);;

let MOI_S5C_SD_POINT = prove
 (`!(FF:real^2->real^3) c X Y z.
     (moi_s5c_sd FF c (&1) X Y \/ moi_s5c_sd FF c (-- &1) X Y) /\
     z IN IMAGE FF (moi_s5c_rgo X Y)
     ==> (c < z$3 ==> moi_s5c_sd FF c (&1) X Y /\ ~moi_s5c_sd FF c (-- &1) X Y) /\
         (z$3 < c ==> moi_s5c_sd FF c (-- &1) X Y /\ ~moi_s5c_sd FF c (&1) X Y)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[moi_s5c_sd] THEN
  DISCH_THEN(CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
  STRIP_TAC THEN FIRST_ASSUM(MP_TAC o SPEC `z:real^3`) THEN ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  TRY(FIRST_X_ASSUM(MP_TAC o SPEC `z:real^3`) THEN ASM_REWRITE_TAC[]) THEN
  ASM_REAL_ARITH_TAC);;

let MOI_S5C_ALT = prove
