     ==> moi_s5c_ext B (GG:real^3->real^2) c (IMAGE GG J) /\
         ~(IMAGE GG J = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) /\
         ~(IMAGE GG J = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])) /\
         (?W. moi_s5c_cons B GG c W (IMAGE GG J)) /\
         (?Y. moi_s5c_cons B GG c (IMAGE GG J) Y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `moi_s5c_ext B (GG:real^3->real^2) c (IMAGE GG J)` ASSUME_TAC THENL
   [REWRITE_TAC[moi_s5c_ext] THEN DISJ2_TAC THEN DISJ2_TAC THEN
    EXISTS_TAC `J:real^3->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J:real^3->bool`] MOI_S5C_SQC_BASIC) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `~(IMAGE (GG:real^3->real^2) J = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) /\
    ~(IMAGE GG J = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPEC `J:real^3->bool` MEMBER_NOT_EMPTY) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_TAC `x0:real^3`) THEN
    UNDISCH_TAC
     `IMAGE (GG:real^3->real^2) J SUBSET
      (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
       interval(--vector[&1;&1]:real^2,vector[&1;&1])) DIFF
      (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
       relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))` THEN
    UNDISCH_TAC `(x0:real^3) IN J` THEN SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
