      EXISTS_TAC `{X | moi_s5c_ext B (GG:real^3->real^2) c X}` THEN CONJ_TAC THENL
       [MATCH_MP_TAC MOI_S5C_EXT_FINITE THEN
        MAP_EVERY EXISTS_TAC [`K:(real^3->bool)->bool`; `FF:real^2->real^3`;
                              `Q:real^3->real->real^3`; `d0:real`] THEN
        ASM_REWRITE_TAC[];
        EXPAND_TAC "S" THEN SET_TAC[]];
      EXPAND_TAC "S" THEN REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `(p:real^2) IN interval[--vector[&2;&2],vector[&2;&2]] DIFF
                                interval(--vector[&1;&1],vector[&1;&1])` THEN
      SET_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\X Y:real^2->bool. X SUBSET inside Y`; `S:(real^2->bool)->bool`]
    MOI_S5C_FINITE_TOTAL_MIN) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [UNDISCH_TAC `(R2:real^2->bool) IN S` THEN SET_TAC[];
      EXPAND_TAC "S" THEN REWRITE_TAC[IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
      USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `y:real^2->bool` THEN
      ASM_REWRITE_TAC[];
      EXPAND_TAC "S" THEN REWRITE_TAC[IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
      USE_THEN "tot" (MP_TAC o SPECL [`x:real^2->bool`; `y:real^2->bool`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; MESON_TAC[]]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:real^2->bool` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "min"))) THEN
  SUBGOAL_THEN `moi_s5c_ext B (GG:real^3->real^2) c m /\ (p:real^2) IN m UNION inside m`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `(m:real^2->bool) IN S` THEN EXPAND_TAC "S" THEN
    REWRITE_TAC[IN_ELIM_THM];
    ALL_TAC] THEN
  ASM_CASES_TAC `m:real^2->bool = R1` THENL
   [USE_THEN "succ" (MP_TAC o SPEC `R1:real^2->bool`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `Y:real^2->bool`) THEN
    MAP_EVERY EXISTS_TAC [`R1:real^2->bool`; `Y:real^2->bool`] THEN
    ASM_REWRITE_TAC[moi_s5c_rg] THEN
    SUBGOAL_THEN `(R1:real^2->bool) SUBSET inside Y` MP_TAC THENL
     [ASM_MESON_TAC[moi_s5c_cons]; ALL_TAC] THEN
    UNDISCH_TAC `(p:real^2) IN m UNION inside m` THEN
    UNDISCH_TAC `(p:real^2) IN interval[--vector[&2;&2],vector[&2;&2]] DIFF
                              interval(--vector[&1;&1],vector[&1;&1])` THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "pred" (MP_TAC o SPEC `m:real^2->bool`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `X:real^2->bool`) THEN
  MAP_EVERY EXISTS_TAC [`X:real^2->bool`; `m:real^2->bool`] THEN
  ASM_REWRITE_TAC[moi_s5c_rg] THEN
  SUBGOAL_THEN `moi_s5c_ext B (GG:real^3->real^2) c X /\ X SUBSET inside m`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[moi_s5c_cons]; ALL_TAC] THEN
  SUBGOAL_THEN `~((p:real^2) IN X UNION inside X)` MP_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(X:real^2->bool) IN S` ASSUME_TAC THENL
     [EXPAND_TAC "S" THEN REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "asym" (MP_TAC o SPECL [`X:real^2->bool`; `m:real^2->bool`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
    USE_THEN "min" (MP_TAC o SPEC `X:real^2->bool`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[]];
    UNDISCH_TAC `(p:real^2) IN m UNION inside m` THEN SET_TAC[]]);;

let MOI_S5C_REGION_FACTS = prove
 (`!B K FF GG Q c d0 X Y.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_cons B (GG:real^3->real^2) c X Y
     ==> moi_s5c_rg X Y SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                               interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
         IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y) SUBSET B /\
         compact (IMAGE FF (moi_s5c_rg X Y)) /\ connected (IMAGE FF (moi_s5c_rg X Y)) /\
         ~(IMAGE FF (moi_s5c_rg X Y) = {}) /\
         IMAGE FF (moi_s5c_rg X Y) SUBSET closure (IMAGE FF (moi_s5c_rgo X Y)) /\
         pl_annulus_with_ends (IMAGE FF (moi_s5c_rg X Y)) (IMAGE FF X) (IMAGE FF Y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  FIRST_ASSUM(ASSUME_TAC o CONJUNCT1 o REWRITE_RULE[moi_s5c_mset] o
    check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
    MOI_S5C_EXT_ORDER) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "sph" o CONJUNCT1) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_cons] o
    check (MOI_S5C_HEAD "moi_s5c_cons")) THEN
  USE_THEN "sph" (MP_TAC o SPEC `X:real^2->bool`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] THEN
  USE_THEN "sph" (MP_TAC o SPEC `Y:real^2->bool`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RG_FACTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (ASSUME_TAC o SYM)
      (CONJUNCTS_THEN2 ASSUME_TAC (K ALL_TAC))))))))) THEN
  ABBREV_TAC `A0 = interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                   interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
  SUBGOAL_THEN `moi_s5c_rg X Y SUBSET (A0:real^2->bool) /\
                moi_s5c_rgo X Y SUBSET moi_s5c_rg X Y`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`(X:real^2->bool) SUBSET A0`; `(Y:real^2->bool) SUBSET A0`;
                           `moi_s5c_rgo X Y SUBSET (A0:real^2->bool)`;
                           `moi_s5c_rgo X Y UNION X UNION Y = moi_s5c_rg X Y`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `closure (moi_s5c_rgo X Y) = moi_s5c_rg X Y` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
     [MATCH_MP_TAC CLOSURE_MINIMAL THEN ASM_SIMP_TAC[COMPACT_IMP_CLOSED];
      MP_TAC(ISPEC `moi_s5c_rgo X Y` CLOSURE_SUBSET) THEN
      MAP_EVERY UNDISCH_TAC [`X UNION Y SUBSET closure (moi_s5c_rgo X Y)`;
                             `moi_s5c_rgo X Y UNION X UNION Y = moi_s5c_rg X Y`] THEN
      SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(FF:real^2->real^3) continuous_on moi_s5c_rg X Y` ASSUME_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `A0:real^2->bool` THEN
    CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    UNDISCH_TAC `moi_s5c_rg X Y SUBSET (A0:real^2->bool)` THEN
    UNDISCH_TAC `IMAGE (FF:real^2->real^3) A0 = B` THEN SET_TAC[];
    MATCH_MP_TAC COMPACT_CONTINUOUS_IMAGE THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC CONNECTED_INTERMEDIATE_CLOSURE THEN
    EXISTS_TAC `moi_s5c_rgo X Y` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[ASSUME `closure (moi_s5c_rgo X Y) = moi_s5c_rg X Y`; SUBSET_REFL]];
    REWRITE_TAC[IMAGE_EQ_EMPTY] THEN
    MAP_EVERY UNDISCH_TAC [`~(moi_s5c_rgo X Y:real^2->bool = {})`;
                           `moi_s5c_rgo X Y SUBSET moi_s5c_rg X Y`] THEN
    SET_TAC[];
    REWRITE_TAC[SYM(ASSUME `closure (moi_s5c_rgo X Y) = moi_s5c_rg X Y`)] THEN
    MATCH_MP_TAC IMAGE_CLOSURE_SUBSET THEN
    REWRITE_TAC[CLOSED_CLOSURE; CLOSURE_SUBSET] THEN
    REWRITE_TAC[ASSUME `closure (moi_s5c_rgo X Y) = moi_s5c_rg X Y`] THEN
    FIRST_ASSUM ACCEPT_TAC;
    MATCH_MP_TAC MOI_S5C_ANN_TRANSFER THEN
    MAP_EVERY EXISTS_TAC [`moi_s5c_rg X Y`; `GG:real^3->real^2`] THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC MOI_S5C_PLH_RESTRICT THEN
    EXISTS_TAC `A0:real^2->bool` THEN EXISTS_TAC `B:real^3->bool` THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
    MATCH_MP_TAC MOI_S5C_ANN_POLYHEDRON THEN
    MAP_EVERY EXISTS_TAC [`X:real^2->bool`; `Y:real^2->bool`] THEN
    FIRST_ASSUM ACCEPT_TAC]);;

let MOI_S5C_CLOSED_SIDE = prove
 (`!s c. closed {z:real^3 | &0 <= s * (z$3 - c)}`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `{z:real^3 | &0 <= s * (z$3 - c)} = {z | (s % basis 3) dot z >= s * c}`
  SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; DOT_LMUL] THEN
    SIMP_TAC[DOT_BASIS; DIMINDEX_3; ARITH] THEN GEN_TAC THEN REAL_ARITH_TAC;
    REWRITE_TAC[CLOSED_HALFSPACE_GE]]);;

let MOI_S5C_REGION_SIDE = prove
 (`!B K FF GG Q c d0 s X Y.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_cons B (GG:real^3->real^2) c X Y /\ moi_s5c_sd FF c s X Y
     ==> IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y) SUBSET
         {x | x IN B /\ &0 <= s * (x$3 - c)}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_REGION_FACTS) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `closure (IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y)) SUBSET
                {z:real^3 | &0 <= s * (z$3 - c)}` MP_TAC THENL
   [MATCH_MP_TAC CLOSURE_MINIMAL THEN REWRITE_TAC[MOI_S5C_CLOSED_SIDE] THEN
    UNDISCH_TAC `moi_s5c_sd FF c s X Y` THEN
    REWRITE_TAC[moi_s5c_sd; SUBSET; IN_ELIM_THM] THEN
    MESON_TAC[REAL_LT_IMP_LE];
    MAP_EVERY UNDISCH_TAC
     [`IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y) SUBSET B`;
      `IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y) SUBSET
       closure (IMAGE FF (moi_s5c_rgo X Y))`] THEN
    REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]]);;

let MOI_S5C_RG_EQ = prove
 (`!X Y:real^2->bool.
     pl_sphere 1 X /\ pl_sphere 1 Y /\ X SUBSET inside Y
     ==> moi_s5c_rg X Y = moi_s5c_rgo X Y UNION X UNION Y`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(fun th -> ACCEPT_TAC(el 6 (CONJUNCTS(MATCH_MP MOI_S5C_RG_FACTS th)))));;

let MOI_S5C_SIDE_DISJ = prove
 (`!B K FF GG Q c d0 s X Y X' Y'.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ (s = &1 \/ s = -- &1) /\
     moi_s5c_cons B (GG:real^3->real^2) c X Y /\ moi_s5c_cons B GG c X' Y' /\
     moi_s5c_sd FF c s X Y /\ moi_s5c_sd FF c s X' Y' /\ ~(X = X' /\ Y = Y')
     ==> DISJOINT (moi_s5c_rg X Y) (moi_s5c_rg X' Y')`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC STRIP_ASSUME_TAC))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`; `X':real^2->bool`; `Y':real^2->bool`]
    MOI_S5C_CONS_DISJOINT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X':real^2->bool`; `Y':real^2->bool`; `X:real^2->bool`; `Y:real^2->bool`]
    MOI_S5C_CONS_DISJOINT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(LABEL_TAC "cf")] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
    MOI_S5C_EXT_ORDER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(LABEL_TAC "tot" o CONJUNCT1 o CONJUNCT2)] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
    MOI_S5C_EXT_ENDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(LABEL_TAC "ends")] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_cons] o
    check (fun th -> MOI_S5C_HEAD "moi_s5c_cons" th &&
                     free_in `X':real^2->bool` (concl th))) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_cons] o
    check (fun th -> MOI_S5C_HEAD "moi_s5c_cons" th &&
                     free_in `X:real^2->bool` (concl th))) THEN
  SUBGOAL_THEN `~(X:real^2->bool = X') /\ ~(Y:real^2->bool = Y')` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN DISCH_TAC THEN
    USE_THEN "cf" (MP_TAC o SPECL [`X':real^2->bool`; `Y':real^2->bool`] o
      last o CONJUNCTS) THEN
    ASM_REWRITE_TAC[moi_s5c_cons] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!X1 Y1 X2 Y2:real^2->bool.
      moi_s5c_cons B (GG:real^3->real^2) c X1 Y1 /\ moi_s5c_cons B GG c X2 Y2 /\
      moi_s5c_sd FF c s X1 Y1 /\ moi_s5c_sd FF c s X2 Y2 ==> ~(Y1 = X2)`
  (LABEL_TAC "nomid") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN DISCH_TAC THEN
    FIRST_X_ASSUM(SUBST_ALL_TAC o SYM o check (fun th -> concl th = `Y1:real^2->bool = X2`)) THEN
    SUBGOAL_THEN `?J. J IN components {x:real^3 | x IN B /\ x$3 = c} /\
                      (Y1:real^2->bool) = IMAGE (GG:real^3->real^2) J`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(ASSUME `moi_s5c_cons B (GG:real^3->real^2) c X1 Y1`) THEN
      MP_TAC(ASSUME `moi_s5c_cons B (GG:real^3->real^2) c Y1 Y2`) THEN
      REWRITE_TAC[moi_s5c_cons; moi_s5c_ext] THEN
      USE_THEN "ends" MP_TAC THEN REWRITE_TAC[moi_s5c_ext] THEN MESON_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `J:real^3->bool`; `X1:real^2->bool`; `Y2:real^2->bool`] MOI_S5C_ALT) THEN
    UNDISCH_TAC `(Y1:real^2->bool) = IMAGE (GG:real^3->real^2) J` THEN
    DISCH_THEN(SUBST_ALL_TAC) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `s:real`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(Y:real^2->bool = X') /\ ~(Y':real^2->bool = X)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN USE_THEN "nomid" MATCH_MP_TAC THENL
     [MAP_EVERY EXISTS_TAC [`X:real^2->bool`; `Y':real^2->bool`];
      MAP_EVERY EXISTS_TAC [`X':real^2->bool`; `Y:real^2->bool`]] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `DISJOINT (X:real^2->bool) X' /\ DISJOINT (Y:real^2->bool) Y' /\
                DISJOINT (Y:real^2->bool) X' /\ DISJOINT (X:real^2->bool) Y'`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN
    (W(fun (_,w) -> let a,b = dest_comb w in
       USE_THEN "tot" (MP_TAC o SPECL [rand a; b])) THEN
     ANTS_TAC THENL
      [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
       FIRST_ASSUM(ACCEPT_TAC o GSYM);
       DISCH_THEN(ACCEPT_TAC o CONJUNCT1)]);
    ALL_TAC] THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RG_EQ) THEN
  ANTS_TAC THENL [USE_THEN "cf" MP_TAC THEN MESON_TAC[]; DISCH_TAC] THEN
  MP_TAC(ISPECL [`X':real^2->bool`; `Y':real^2->bool`] MOI_S5C_RG_EQ) THEN
  ANTS_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `X':real^2->bool`; `Y':real^2->bool`] MOI_S5C_CONS_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; MESON_TAC[]];
    DISCH_TAC] THEN
  MAP_EVERY UNDISCH_TAC [`moi_s5c_rg X Y = moi_s5c_rgo X Y UNION X UNION Y`;
                         `moi_s5c_rg X' Y' = moi_s5c_rgo X' Y' UNION X' UNION Y'`] THEN
  MAP_EVERY UNDISCH_TAC
   [`DISJOINT (moi_s5c_rgo X Y) (moi_s5c_rg X' Y')`;
    `DISJOINT (moi_s5c_rgo X' Y') (moi_s5c_rg X Y)`;
    `DISJOINT (X:real^2->bool) X'`; `DISJOINT (Y:real^2->bool) Y'`;
    `DISJOINT (Y:real^2->bool) X'`; `DISJOINT (X:real^2->bool) Y'`] THEN
  MOI_S5C_ABS_SET_TAC [`moi_s5c_rgo X Y`; `moi_s5c_rgo X' Y'`;
                       `moi_s5c_rg X Y`; `moi_s5c_rg X' Y'`]);;

let MOI_S5C_SIDE_UNION = prove
 (`!B K FF GG Q c d0 s x.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ (s = &1 \/ s = -- &1) /\
     x IN B /\ &0 <= s * (x$3 - c)
     ==> ?X Y. moi_s5c_cons B (GG:real^3->real^2) c X Y /\ moi_s5c_sd FF c s X Y /\
               x IN IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "s") STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN
   `(GG:real^3->real^2) x IN interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                             interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
    (FF:real^2->real^3) (GG x) = x`
  STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^3` o CONJUNCT1 o CONJUNCT2) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!X Y. moi_s5c_cons B (GG:real^3->real^2) c X Y /\ moi_s5c_sd FF c s X Y /\
          GG x IN moi_s5c_rg X Y
          ==> ?X Y. moi_s5c_cons B GG c X Y /\ moi_s5c_sd FF c s X Y /\
                    x IN IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y)`
  (LABEL_TAC "fin") THENL
   [REPEAT STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`X:real^2->bool`; `Y:real^2->bool`] THEN
    ASM_REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `(GG:real^3->real^2) x` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `(GG:real^3->real^2) x`] MOI_S5C_COVER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `X:real^2->bool` (X_CHOOSE_THEN `Y:real^2->bool`
    STRIP_ASSUME_TAC)) THEN
  ASM_CASES_TAC `moi_s5c_sd FF c s (X:real^2->bool) Y` THENL
   [USE_THEN "fin" MATCH_MP_TAC THEN
    MAP_EVERY EXISTS_TAC [`X:real^2->bool`; `Y:real^2->bool`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_TYPE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  SUBGOAL_THEN `moi_s5c_sd FF c (--s) (X:real^2->bool) Y` ASSUME_TAC THENL
   [USE_THEN "s" (DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    REWRITE_TAC[REAL_NEG_NEG] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:real^3)$3 = c` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `--s:real`;
      `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_REGION_SIDE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[SUBSET; IN_ELIM_THM; FORALL_IN_IMAGE] THEN
    DISCH_THEN(MP_TAC o SPEC `(GG:real^3->real^2) x`) THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `&0 <= s * ((x:real^3)$3 - c)` THEN
    USE_THEN "s" (DISJ_CASES_THEN SUBST1_TAC) THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?J. J IN components {x:real^3 | x IN B /\ x$3 = c} /\ x IN J`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPEC `{x:real^3 | x IN B /\ x$3 = c}` UNIONS_COMPONENTS) THEN
    REWRITE_TAC[EXTENSION; IN_UNIONS] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^3`) THEN ASM_REWRITE_TAC[IN_ELIM_THM];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RG_EQ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J:real^3->bool`] MOI_S5C_ADJ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> let cs = CONJUNCTS th in
    ASSUME_TAC (el 0 cs) THEN X_CHOOSE_TAC `W:real^2->bool` (el 3 cs) THEN
    X_CHOOSE_TAC `Y2:real^2->bool` (el 4 cs)) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
    MOI_S5C_EXT_ORDER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(LABEL_TAC "tot" o CONJUNCT1 o CONJUNCT2)] THEN
  SUBGOAL_THEN `(GG:real^3->real^2) x IN X \/ GG x IN Y` MP_TAC THENL
   [SUBGOAL_THEN `~((GG:real^3->real^2) x IN moi_s5c_rgo X Y)` MP_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPEC `J:real^3->bool` o check (fun th ->
        is_forall(concl th) && free_in `moi_s5c_rgo X Y` (concl th) &&
        free_in `IMAGE (GG:real^3->real^2)` (concl th))) THEN
      ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `(x:real^3) IN J` THEN SET_TAC[];
      UNDISCH_TAC `(GG:real^3->real^2) x IN moi_s5c_rg X Y` THEN
      UNDISCH_TAC `moi_s5c_rg X Y = moi_s5c_rgo X Y UNION X UNION Y` THEN SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(GG:real^3->real^2) x IN IMAGE GG J` ASSUME_TAC THENL
   [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `x:real^3` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_cons] o
    check (fun th -> MOI_S5C_HEAD "moi_s5c_cons" th &&
                     free_in `X:real^2->bool` (concl th) &&
                     free_in `Y:real^2->bool` (concl th))) THEN
  STRIP_TAC THENL
   [SUBGOAL_THEN `X = IMAGE (GG:real^3->real^2) J` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN DISCH_TAC THEN
      USE_THEN "tot" (MP_TAC o SPECL [`X:real^2->bool`; `IMAGE (GG:real^3->real^2) J`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(MP_TAC o CONJUNCT1)] THEN
      MAP_EVERY UNDISCH_TAC [`(GG:real^3->real^2) x IN X`;
                             `(GG:real^3->real^2) x IN IMAGE GG J`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `J:real^3->bool`; `W:real^2->bool`; `Y:real^2->bool`] MOI_S5C_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(MP_TAC o SPEC `s:real`)] THEN
    ANTS_TAC THENL [USE_THEN "s" ACCEPT_TAC; DISCH_THEN(MP_TAC o CONJUNCT1)] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    USE_THEN "fin" MATCH_MP_TAC THEN
    MAP_EVERY EXISTS_TAC [`W:real^2->bool`; `IMAGE (GG:real^3->real^2) J`] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `W:real^2->bool`; `IMAGE (GG:real^3->real^2) J`] MOI_S5C_CONS_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
    MP_TAC(ISPECL [`W:real^2->bool`; `IMAGE (GG:real^3->real^2) J`] MOI_S5C_RG_EQ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST1_TAC] THEN
    UNDISCH_TAC `(GG:real^3->real^2) x IN IMAGE GG J` THEN SET_TAC[];
    SUBGOAL_THEN `Y = IMAGE (GG:real^3->real^2) J` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN DISCH_TAC THEN
      USE_THEN "tot" (MP_TAC o SPECL [`Y:real^2->bool`; `IMAGE (GG:real^3->real^2) J`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(MP_TAC o CONJUNCT1)] THEN
      MAP_EVERY UNDISCH_TAC [`(GG:real^3->real^2) x IN Y`;
                             `(GG:real^3->real^2) x IN IMAGE GG J`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `J:real^3->bool`; `X:real^2->bool`; `Y2:real^2->bool`] MOI_S5C_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(MP_TAC o SPEC `s:real`)] THEN
    ANTS_TAC THENL [USE_THEN "s" ACCEPT_TAC; DISCH_THEN(MP_TAC o CONJUNCT1)] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    USE_THEN "fin" MATCH_MP_TAC THEN
    MAP_EVERY EXISTS_TAC [`IMAGE (GG:real^3->real^2) J`; `Y2:real^2->bool`] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `IMAGE (GG:real^3->real^2) J`; `Y2:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
    MP_TAC(ISPECL [`IMAGE (GG:real^3->real^2) J`; `Y2:real^2->bool`] MOI_S5C_RG_EQ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST1_TAC] THEN
    UNDISCH_TAC `(GG:real^3->real^2) x IN IMAGE GG J` THEN SET_TAC[]]);;

let MOI_S5C_SIDE_COMPONENTS = prove
 (`!B K FF GG Q c d0 s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ (s = &1 \/ s = -- &1)
     ==> components {x | x IN B /\ &0 <= s * (x$3 - c)} =
         {IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y) | X,Y |
            moi_s5c_cons B (GG:real^3->real^2) c X Y /\ moi_s5c_sd FF c s X Y}`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "s"))) THEN
  ABBREV_TAC `FS = {IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y) | X,Y |
            moi_s5c_cons B (GG:real^3->real^2) c X Y /\ moi_s5c_sd FF c s X Y}` THEN
  SUBGOAL_THEN
   `!z:real^3->bool. z IN FS <=>
       ?X Y. moi_s5c_cons B (GG:real^3->real^2) c X Y /\ moi_s5c_sd FF c s X Y /\
             z = IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y)`
  (LABEL_TAC "fs") THENL
   [EXPAND_TAC "FS" THEN REWRITE_TAC[IN_ELIM_THM] THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `{x:real^3 | x IN B /\ &0 <= s * (x$3 - c)} = UNIONS FS` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_UNIONS] THEN X_GEN_TAC `x:real^3` THEN EQ_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `s:real`;
        `x:real^3`] MOI_S5C_SIDE_UNION) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `X:real^2->bool` (X_CHOOSE_THEN `Y:real^2->bool`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y)` THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`X:real^2->bool`; `Y:real^2->bool`] THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `t:real^3->bool` (CONJUNCTS_THEN2 MP_TAC ASSUME_TAC)) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `X:real^2->bool` (X_CHOOSE_THEN `Y:real^2->bool`
        STRIP_ASSUME_TAC)) THEN
      MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `s:real`;
        `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_REGION_SIDE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      UNDISCH_TAC `(x:real^3) IN t` THEN ASM_REWRITE_TAC[] THEN SET_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC MOI_S5C_COMPONENTS_PARTITION THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `IMAGE (\p. IMAGE (FF:real^2->real^3)
                     (moi_s5c_rg (FST p) (SND p)))
                ({X:real^2->bool | moi_s5c_ext B (GG:real^3->real^2) c X} CROSS
                 {X:real^2->bool | moi_s5c_ext B (GG:real^3->real^2) c X})` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_IMAGE THEN MATCH_MP_TAC FINITE_CROSS THEN
      CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_EXT_FINITE THEN
      MAP_EVERY EXISTS_TAC [`K:(real^3->bool)->bool`; `FF:real^2->real^3`;
                            `Q:real^3->real->real^3`; `d0:real`] THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[SUBSET; IN_IMAGE; EXISTS_PAIR_THM; IN_CROSS; IN_ELIM_THM] THEN
      REWRITE_TAC[moi_s5c_cons] THEN MESON_TAC[]];
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `t:real^3->bool` THEN
    DISCH_THEN(X_CHOOSE_THEN `X:real^2->bool` (X_CHOOSE_THEN `Y:real^2->bool`
      STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_REGION_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
    ASM_SIMP_TAC[COMPACT_IMP_CLOSED];
    ASM_REWRITE_TAC[] THEN MAP_EVERY X_GEN_TAC [`t:real^3->bool`; `t':real^3->bool`] THEN
    DISCH_THEN(CONJUNCTS_THEN2
      (X_CHOOSE_THEN `X:real^2->bool` (X_CHOOSE_THEN `Y:real^2->bool` STRIP_ASSUME_TAC))
      (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `X':real^2->bool` (X_CHOOSE_THEN `Y':real^2->bool` STRIP_ASSUME_TAC))
        ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `s:real`;
      `X:real^2->bool`; `Y:real^2->bool`; `X':real^2->bool`; `Y':real^2->bool`]
      MOI_S5C_SIDE_DISJ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN
      UNDISCH_TAC `~(t:real^3->bool = t')` THEN ASM_REWRITE_TAC[];
      DISCH_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_REGION_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o CONJUNCT1)] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `X':real^2->bool`; `Y':real^2->bool`] MOI_S5C_REGION_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o CONJUNCT1)] THEN
    FIRST_ASSUM(MP_TAC o CONJUNCT1 o MATCH_MP MOI_S5C_MSET_FACTS) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY UNDISCH_TAC
     [`moi_s5c_rg X Y SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                             interval(--vector[&1;&1]:real^2,vector[&1;&1])`;
      `moi_s5c_rg X' Y' SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                               interval(--vector[&1;&1]:real^2,vector[&1;&1])`;
      `DISJOINT (moi_s5c_rg X Y) (moi_s5c_rg X' Y')`] THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; IN_IMAGE; SUBSET] THEN
    MESON_TAC[]]);;

let MOI_S5C_CONS_ENDS = prove
 (`!B K FF GG Q c d0 X Y.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_cons B (GG:real^3->real^2) c X Y
     ==> ~(X = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])) /\
         ~(Y = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) /\
         (~(X = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]))
          ==> ?J. J IN components {x | x IN B /\ x$3 = c} /\ X = IMAGE GG J) /\
         (~(Y = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))
          ==> ?J. J IN components {x | x IN B /\ x$3 = c} /\ Y = IMAGE GG J)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
    MOI_S5C_EXT_ENDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> let e5 = last(CONJUNCTS th) in
    FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_cons] o
      check (MOI_S5C_HEAD "moi_s5c_cons")) THEN
    SUBGOAL_THEN
     `~(X = relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) /\
      ~(Y = relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN DISCH_THEN SUBST_ALL_TAC THENL
       [MP_TAC(SPEC `Y:real^2->bool` e5); MP_TAC(SPEC `X:real^2->bool` e5)] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC]) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THEN DISCH_TAC THENL
   [UNDISCH_TAC `moi_s5c_ext B (GG:real^3->real^2) c X`;
    UNDISCH_TAC `moi_s5c_ext B (GG:real^3->real^2) c Y`] THEN
  ASM_REWRITE_TAC[moi_s5c_ext]);;

let MOI_S5C_NOT_ONE = prove
 (`!B K FF GG Q c d0 X.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_cons B (GG:real^3->real^2) c
       (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) X /\
     moi_s5c_cons B GG c X (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?J1 J2. J1 IN components {x:real^3 | x IN B /\ x$3 = c} /\
                        J2 IN components {x:real^3 | x IN B /\ x$3 = c} /\ ~(J1 = J2)`
  STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[moi_s5c_hyp] o
      check (MOI_S5C_HEAD "moi_s5c_hyp")) THEN
    MATCH_MP_TAC(TAUT `(~p ==> ~q) ==> q ==> p`) THEN
    REWRITE_TAC[NOT_EXISTS_THM; NOT_LE] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ARITH_RULE `n <= 1 ==> n < 2`) THEN
    SUBGOAL_THEN `?a:real^3->bool. components {x:real^3 | x IN B /\ x$3 = c} SUBSET {a}`
    MP_TAC THENL
     [ASM_CASES_TAC `components {x:real^3 | x IN B /\ x$3 = c} = {}` THENL
       [ASM_REWRITE_TAC[EMPTY_SUBSET]; ALL_TAC] THEN
      FIRST_X_ASSUM(X_CHOOSE_TAC `a:real^3->bool` o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
      EXISTS_TAC `a:real^3->bool` THEN REWRITE_TAC[SUBSET; IN_SING] THEN
      ASM_MESON_TAC[];
      REWRITE_TAC[GSYM CARD_LE_1] THEN SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?J. J IN components {x:real^3 | x IN B /\ x$3 = c} /\
                    ~(IMAGE (GG:real^3->real^2) J = X)` STRIP_ASSUME_TAC THENL
   [ASM_CASES_TAC `IMAGE (GG:real^3->real^2) J1 = X` THENL
     [EXISTS_TAC `J2:real^3->bool` THEN ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
      MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
        `J1:real^3->bool`] MOI_S5C_SQC_BASIC) THEN
      MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
        `J2:real^3->bool`] MOI_S5C_SQC_BASIC) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o last o CONJUNCTS) THEN
      DISCH_THEN(fun th1 -> DISCH_THEN(fun th2 ->
        MP_TAC(last(CONJUNCTS th2)) THEN MP_TAC th1)) THEN
      UNDISCH_TAC `~(J1:real^3->bool = J2)` THEN MESON_TAC[];
      EXISTS_TAC `J1:real^3->bool` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J:real^3->bool`] MOI_S5C_ADJ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
    MOI_S5C_EXT_ENDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> let cs = CONJUNCTS th in
    MP_TAC(SPEC `IMAGE (GG:real^3->real^2) J` (el 2 cs)) THEN
    MP_TAC(SPEC `IMAGE (GG:real^3->real^2) J` (el 3 cs))) THEN
  ASM_REWRITE_TAC[] THEN REPEAT DISCH_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
    MOI_S5C_EXT_ORDER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`IMAGE (GG:real^3->real^2) J`; `X:real^2->bool`] o
    CONJUNCT1 o CONJUNCT2) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[moi_s5c_cons];
    DISCH_THEN(DISJ_CASES_TAC o CONJUNCT2)] THENL
   [UNDISCH_TAC `moi_s5c_cons B (GG:real^3->real^2) c
      (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) X` THEN
    REWRITE_TAC[moi_s5c_cons] THEN
    DISCH_THEN(MP_TAC o SPEC `IMAGE (GG:real^3->real^2) J` o last o CONJUNCTS) THEN
    ASM_REWRITE_TAC[];
    UNDISCH_TAC `moi_s5c_cons B (GG:real^3->real^2) c X
      (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))` THEN
    REWRITE_TAC[moi_s5c_cons] THEN
    DISCH_THEN(MP_TAC o SPEC `IMAGE (GG:real^3->real^2) J` o last o CONJUNCTS) THEN
    ASM_REWRITE_TAC[]]);;

let MOI_S5C_CONS_CIRCLES = prove
 (`!B K FF GG Q c d0 X Y.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_cons B (GG:real^3->real^2) c X Y
     ==> (~(X = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]))
          ==> ?J. J IN components {x | x IN B /\ x$3 = c} /\ X = IMAGE GG J) /\
         (~(Y = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))
          ==> ?J. J IN components {x | x IN B /\ x$3 = c} /\ Y = IMAGE GG J)`,
  MESON_TAC[MOI_S5C_CONS_ENDS]);;

let MOI_S5C_NO_GAP = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c
