   [FIRST_ASSUM(MP_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[moi_s5c_hyp] o
      check (MOI_S5C_HEAD "moi_s5c_hyp")) THEN
    REWRITE_TAC[MEMBER_NOT_EMPTY] THEN
    MATCH_MP_TAC(TAUT `(~p ==> ~q) ==> q ==> p`) THEN
    SIMP_TAC[CARD_CLAUSES] THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J:real^3->bool`] MOI_S5C_ADJ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
    MOI_S5C_EXT_ENDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> let cs = CONJUNCTS th in
    MP_TAC(SPEC `IMAGE (GG:real^3->real^2) J` (el 2 cs)) THEN
    MP_TAC(SPEC `IMAGE (GG:real^3->real^2) J` (el 3 cs))) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[moi_s5c_cons] THEN DISCH_THEN(MP_TAC o SPEC `IMAGE (GG:real^3->real^2) J` o
    last o CONJUNCTS) THEN
  ASM_REWRITE_TAC[]);;

let MOI_S5C_END_NOT_TTUBE = prove
 (`!B K FF GG Q c d0 X Y.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_cons B (GG:real^3->real^2) c X Y /\
     (X = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]) \/
      Y = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))
     ==> ~(IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y) SUBSET moi_s35_ttube)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "end")))) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RG_EQ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  SUBGOAL_THEN `~(relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) = {}) /\
                ~(relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) = {})`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; MOI_S5C_IN_RF1; MOI_S5C_IN_RF2] THEN CONJ_TAC THENL
     [EXISTS_TAC `vector[&1;&0]:real^2`; EXISTS_TAC `vector[&2;&0]:real^2`] THEN
    REWRITE_TAC[VECTOR_2] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (FF:real^2->real^3) X SUBSET IMAGE FF (moi_s5c_rg X Y) /\
                IMAGE (FF:real^2->real^3) Y SUBSET IMAGE FF (moi_s5c_rg X Y)`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC IMAGE_SUBSET THEN
    UNDISCH_TAC `moi_s5c_rg X Y = moi_s5c_rgo X Y UNION X UNION Y` THEN SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "end" (DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  MAP_EVERY UNDISCH_TAC
   [`DISJOINT
      (IMAGE (FF:real^2->real^3)
         (relative_frontier (interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION
       IMAGE FF (relative_frontier (interval[--vector[&2;&2]:real^2,vector[&2;&2]])))
      moi_s35_ttube`] THEN
  ASM SET_TAC[]);;

let MOI_S5C_CLAUSE_SIDE = prove
 (`!B K FF GG Q c d0 s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ (s = &1 \/ s = -- &1)
     ==> ?k0. k0 IN components {x:real^3 | x IN B /\ &0 <= s * (x$3 - c)} /\
              !k. k IN components {x | x IN B /\ &0 <= s * (x$3 - c)} /\ ~(k = k0)
                  ==> k SUBSET moi_s35_ttube`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 MP_TAC (DISJ_CASES_THEN SUBST1_TAC))) THEN
  REWRITE_TAC[moi_s5c_hyp; moi_s5c_clause;
              REAL_ARITH `&0 <= &1 * (x - c) <=> c <= x`;
              REAL_ARITH `&0 <= -- &1 * (x - c) <=> x <= c`] THEN
  MESON_TAC[]);;

let MOI_S5C_END_FACTS = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c
     ==> ?X1 Ym.
           moi_s5c_cons B (GG:real^3->real^2) c
             (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) X1 /\
           moi_s5c_cons B GG c Ym (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])) /\
           ~(X1 = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])) /\
           ~(Ym = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) /\
           (!s. (s = &1 \/ s = -- &1)
                ==> ~(moi_s5c_sd (FF:real^2->real^3) c s
                        (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) X1 /\
                      moi_s5c_sd FF c s Ym
                        (relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])))) /\
           (!s X Y. (s = &1 \/ s = -- &1) /\ moi_s5c_cons B GG c X Y /\
                    moi_s5c_sd FF c s X Y /\
                    ~(X = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) /\
                    ~(Y = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))
                    ==> IMAGE FF (moi_s5c_rg X Y) SUBSET moi_s35_ttube)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `R1 = relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])` THEN
  ABBREV_TAC `R2 = relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])` THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
    MOI_S5C_EXT_ENDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[] THEN STRIP_TAC] THEN
  SUBGOAL_THEN `~(R1:real^2->bool = R2)` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["R1"; "R2"] THEN
    REWRITE_TAC[EXTENSION; MOI_S5C_IN_RF1; MOI_S5C_IN_RF2] THEN
    DISCH_THEN(MP_TAC o SPEC `vector[&1;&0]:real^2`) THEN
    REWRITE_TAC[VECTOR_2] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
    MOI_S5C_CONS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[] THEN STRIP_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `R2:real^2->bool` o check (fun th ->
    is_forall(concl th) && free_in `R1:real^2->bool` (concl th) &&
    not(free_in `R2:real^2->bool` (concl th)) )) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `Ym:real^2->bool`) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `R1:real^2->bool` o check (fun th ->
    is_forall(concl th) && free_in `R2:real^2->bool` (concl th) &&
    not(free_in `R1:real^2->bool` (concl th)))) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `X1:real^2->bool`) THEN
  MAP_EVERY EXISTS_TAC [`X1:real^2->bool`; `Ym:real^2->bool`] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_NO_GAP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[] THEN DISCH_TAC] THEN
  SUBGOAL_THEN `~(X1:real^2->bool = R2) /\ ~(Ym:real^2->bool = R1)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN DISCH_THEN SUBST_ALL_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!s X Y X' Y'. (s = &1 \/ s = -- &1) /\
       moi_s5c_cons B (GG:real^3->real^2) c X Y /\ moi_s5c_cons B GG c X' Y' /\
       moi_s5c_sd FF c s X Y /\ moi_s5c_sd FF c s X' Y' /\ ~(X = X' /\ Y = Y')
       ==> DISJOINT (IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y)) (IMAGE FF (moi_s5c_rg X' Y')) /\
           ~(IMAGE FF (moi_s5c_rg X Y) = {})`
  (LABEL_TAC "dj") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `s:real`;
      `X:real^2->bool`; `Y:real^2->bool`; `X':real^2->bool`; `Y':real^2->bool`]
      MOI_S5C_SIDE_DISJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_REGION_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `X':real^2->bool`; `Y':real^2->bool`] MOI_S5C_REGION_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o CONJUNCT1)] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(MP_TAC o CONJUNCT1 o MATCH_MP MOI_S5C_MSET_FACTS) THEN
    MAP_EVERY UNDISCH_TAC
     [`moi_s5c_rg X Y SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                             interval(--vector[&1;&1]:real^2,vector[&1;&1])`;
      `moi_s5c_rg X' Y' SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                               interval(--vector[&1;&1]:real^2,vector[&1;&1])`;
      `DISJOINT (moi_s5c_rg X Y) (moi_s5c_rg X' Y')`] THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; IN_IMAGE; SUBSET] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!s X Y. (s = &1 \/ s = -- &1) /\ moi_s5c_cons B (GG:real^3->real^2) c X Y /\
            moi_s5c_sd FF c s X Y
            ==> IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y) IN
                components {x:real^3 | x IN B /\ &0 <= s * (x$3 - c)}`
  (LABEL_TAC "inc") THENL
   [REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `s:real`]
      MOI_S5C_SIDE_COMPONENTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST1_TAC] THEN
    REWRITE_TAC[IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC [`X:real^2->bool`; `Y:real^2->bool`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(IMAGE (FF:real^2->real^3) (moi_s5c_rg R1 X1) SUBSET moi_s35_ttube) /\
    ~(IMAGE (FF:real^2->real^3) (moi_s5c_rg Ym R2) SUBSET moi_s35_ttube)`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_END_NOT_TTUBE THEN
    MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `K:(real^3->bool)->bool`; `GG:real^3->real^2`;
      `Q:real^3->real->real^3`; `c:real`; `d0:real`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!s. (s = &1 \/ s = -- &1)
        ==> ~(moi_s5c_sd (FF:real^2->real^3) c s R1 X1 /\ moi_s5c_sd FF c s Ym R2)`
  (LABEL_TAC "opp") THENL
   [X_GEN_TAC `s:real` THEN DISCH_TAC THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `s:real`]
      MOI_S5C_CLAUSE_SIDE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `k0:real^3->bool` (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "k0"))) THEN
    USE_THEN "inc" (MP_TAC o SPECL [`s:real`; `R1:real^2->bool`; `X1:real^2->bool`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
    USE_THEN "inc" (MP_TAC o SPECL [`s:real`; `Ym:real^2->bool`; `R2:real^2->bool`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
    USE_THEN "dj" (MP_TAC o SPECL [`s:real`; `R1:real^2->bool`; `X1:real^2->bool`;
      `Ym:real^2->bool`; `R2:real^2->bool`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
    SUBGOAL_THEN `IMAGE (FF:real^2->real^3) (moi_s5c_rg R1 X1) = k0 /\
                  IMAGE (FF:real^2->real^3) (moi_s5c_rg Ym R2) = k0`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN DISCH_TAC THENL
       [USE_THEN "k0" (MP_TAC o SPEC `IMAGE (FF:real^2->real^3) (moi_s5c_rg R1 X1)`);
        USE_THEN "k0" (MP_TAC o SPEC `IMAGE (FF:real^2->real^3) (moi_s5c_rg Ym R2)`)] THEN
      ANTS_TAC THEN TRY(CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC) THEN
      DISCH_THEN(fun th -> UNDISCH_TAC (mk_neg(concl th)) THEN REWRITE_TAC[th]);
      ALL_TAC] THEN
    UNDISCH_TAC `DISJOINT (IMAGE (FF:real^2->real^3) (moi_s5c_rg R1 X1))
                          (IMAGE FF (moi_s5c_rg Ym R2))` THEN
    UNDISCH_TAC `~(IMAGE (FF:real^2->real^3) (moi_s5c_rg R1 X1) = {})` THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL [USE_THEN "opp" ACCEPT_TAC; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`s:real`; `X:real^2->bool`; `Y:real^2->bool`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `moi_s5c_sd (FF:real^2->real^3) c s R1 X1 \/ moi_s5c_sd FF c s Ym R2`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `R1:real^2->bool`; `X1:real^2->bool`] MOI_S5C_TYPE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `Ym:real^2->bool`; `R2:real^2->bool`] MOI_S5C_TYPE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
    USE_THEN "opp" (MP_TAC o SPEC `&1`) THEN
    USE_THEN "opp" (MP_TAC o SPEC `-- &1`) THEN
    REWRITE_TAC[] THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN SUBST1_TAC o check (fun th ->
      concl th = `s = &1 \/ s = -- &1`)) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `s:real`]
    MOI_S5C_CLAUSE_SIDE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `k0:real^3->bool` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "k0"))) THEN
  USE_THEN "inc" (MP_TAC o SPECL [`s:real`; `X:real^2->bool`; `Y:real^2->bool`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  USE_THEN "k0" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th ->
    is_disj(concl th) && free_in `X1:real^2->bool` (concl th))) THENL
   [USE_THEN "inc" (MP_TAC o SPECL [`s:real`; `R1:real^2->bool`; `X1:real^2->bool`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
    SUBGOAL_THEN `IMAGE (FF:real^2->real^3) (moi_s5c_rg R1 X1) = k0` ASSUME_TAC THENL
     [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN DISCH_TAC THEN
      USE_THEN "k0" (MP_TAC o SPEC `IMAGE (FF:real^2->real^3) (moi_s5c_rg R1 X1)`) THEN
      ANTS_TAC THEN TRY(CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC) THEN
      DISCH_THEN(fun th -> UNDISCH_TAC (mk_neg(concl th)) THEN REWRITE_TAC[th]);
      ALL_TAC] THEN
    USE_THEN "dj" (MP_TAC o SPECL [`s:real`; `X:real^2->bool`; `Y:real^2->bool`;
      `R1:real^2->bool`; `X1:real^2->bool`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[];
    USE_THEN "inc" (MP_TAC o SPECL [`s:real`; `Ym:real^2->bool`; `R2:real^2->bool`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
    SUBGOAL_THEN `IMAGE (FF:real^2->real^3) (moi_s5c_rg Ym R2) = k0` ASSUME_TAC THENL
     [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN DISCH_TAC THEN
      USE_THEN "k0" (MP_TAC o SPEC `IMAGE (FF:real^2->real^3) (moi_s5c_rg Ym R2)`) THEN
      ANTS_TAC THEN TRY(CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC) THEN
      DISCH_THEN(fun th -> UNDISCH_TAC (mk_neg(concl th)) THEN REWRITE_TAC[th]);
