    USE_THEN "dj" (MP_TAC o SPECL [`s:real`; `X:real^2->bool`; `Y:real^2->bool`;
      `Ym:real^2->bool`; `R2:real^2->bool`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
