let MOI_S5C_RR12 th =
  REWRITE_RULE[ASSUME `relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) = R1`;
               ASSUME `relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]) = R2`] th;;

let MOI_S5C_MIDDLE_UP = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c
     ==> ?X Y. moi_s5c_cons B (GG:real^3->real^2) c X Y /\
               moi_s5c_sd (FF:real^2->real^3) c (&1) X Y /\
               ~(X = relative_frontier(interval[--vector[&1;&1],vector[&1;&1]])) /\
               ~(Y = relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_END_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ABBREV_TAC `R1 = relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])` THEN
  ABBREV_TAC `R2 = relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])` THEN
  DISCH_THEN(X_CHOOSE_THEN `X1:real^2->bool` (X_CHOOSE_THEN `Ym:real^2->bool`
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "opp") (K ALL_TAC)))))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `R1:real^2->bool`; `X1:real^2->bool`] MOI_S5C_CONS_ENDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o MOI_S5C_RR12 o CONJUNCT1 o CONJUNCT2)] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `R1:real^2->bool`; `X1:real^2->bool`] MOI_S5C_CONS_CIRCLES) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(MP_TAC o CONJUNCT2)] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `J1:real^3->bool` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "e1" o SYM))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J1:real^3->bool`] MOI_S5C_ADJ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "e1" (fun e1 -> DISCH_THEN(X_CHOOSE_TAC `X2:real^2->bool` o
    REWRITE_RULE[e1] o last o CONJUNCTS)) THEN
  SUBGOAL_THEN `~(X2:real^2->bool = R2)` ASSUME_TAC THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `X1:real^2->bool`] MOI_S5C_NOT_ONE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J1:real^3->bool`; `R1:real^2->bool`; `X2:real^2->bool`] MOI_S5C_ALT) THEN
  USE_THEN "e1" (fun e1 -> REWRITE_TAC[e1]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `&1`) THEN REWRITE_TAC[] THEN
  DISCH_THEN(ASSUME_TAC o CONJUNCT1) THEN
  ASM_CASES_TAC `moi_s5c_sd (FF:real^2->real^3) c (&1) R1 X1` THENL
   [ALL_TAC;
    MAP_EVERY EXISTS_TAC [`X1:real^2->bool`; `X2:real^2->bool`] THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `~(X1:real^2->bool = R1)` THEN MESON_TAC[]] THEN
  SUBGOAL_THEN `~moi_s5c_sd (FF:real^2->real^3) c (&1) X1 X2` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X1:real^2->bool`; `X2:real^2->bool`] MOI_S5C_CONS_ENDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o MOI_S5C_RR12 o CONJUNCT1 o CONJUNCT2)] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X1:real^2->bool`; `X2:real^2->bool`] MOI_S5C_CONS_CIRCLES) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(MP_TAC o CONJUNCT2)] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `J2:real^3->bool` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "e2" o SYM))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J2:real^3->bool`] MOI_S5C_ADJ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "e2" (fun e2 -> DISCH_THEN(X_CHOOSE_TAC `X3:real^2->bool` o
    REWRITE_RULE[e2] o last o CONJUNCTS)) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J2:real^3->bool`; `X1:real^2->bool`; `X3:real^2->bool`] MOI_S5C_ALT) THEN
  USE_THEN "e2" (fun e2 -> REWRITE_TAC[e2]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `&1`) THEN REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o CONJUNCT1) THEN ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MAP_EVERY EXISTS_TAC [`X2:real^2->bool`; `X3:real^2->bool`] THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST_ALL_TAC THEN
  SUBGOAL_THEN `X2:real^2->bool = Ym` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `X2:real^2->bool`; `R2:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`Ym:real^2->bool`; `R2:real^2->bool`] o last o CONJUNCTS) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "opp" (MP_TAC o SPEC `&1`) THEN
  REWRITE_TAC[ASSUME `moi_s5c_sd (FF:real^2->real^3) c (&1) R1 X1`;
              ASSUME `moi_s5c_sd (FF:real^2->real^3) c (&1) Ym R2`]);;


(* ------------------------------------------------------------------------- *)
(* Sections of the collar (images of the level circles at other            *)
(* heights): PL circles at a level, essential in the plane and in the      *)
(* square annulus, nested in the plane like the circles, and the homotopy  *)
(* (Borsuk push) argument behind these facts.                              *)
(* ------------------------------------------------------------------------- *)

let moi_s5c_sec = new_definition
 `moi_s5c_sec (Q:real^3->real->real^3) (J:real^3->bool) t = IMAGE (\x. Q x t) J`;;

let MOI_S5C_LEVEL_PLH = prove
 (`!(S:real^3->bool) h.
     pl_polyhedron S /\ (!x. x IN S ==> x$3 = h)
     ==> pl_polyhedron (IMAGE moi_s5c_proj S) /\
         pl_homeomorphism (S,IMAGE moi_s5c_proj S) (moi_s5c_proj,moi_s35_lift h)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `pl_polyhedron (IMAGE moi_s5c_proj (S:real^3->bool))` ASSUME_TAC THENL
   [MATCH_MP_TAC PL_POLYHEDRON_LINEAR_IMAGE THEN ASM_REWRITE_TAC[MOI_S5C_PROJ_FACTS];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[pl_homeomorphism] THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[homeomorphism] THEN REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[MOI_S5C_PROJ_LIFT];
      SIMP_TAC[LINEAR_CONTINUOUS_ON; MOI_S5C_PROJ_FACTS];
      REWRITE_TAC[FORALL_IN_IMAGE] THEN ASM_SIMP_TAC[MOI_S5C_PROJ_LIFT];
      REWRITE_TAC[EXTENSION; IN_IMAGE] THEN X_GEN_TAC `x:real^3` THEN EQ_TAC THENL
       [DISCH_THEN(X_CHOOSE_THEN `y:real^2` (CONJUNCTS_THEN2 SUBST1_TAC
          (X_CHOOSE_THEN `z:real^3` STRIP_ASSUME_TAC))) THEN
        ASM_SIMP_TAC[MOI_S5C_PROJ_LIFT];
        DISCH_TAC THEN EXISTS_TAC `moi_s5c_proj x` THEN
        ASM_SIMP_TAC[MOI_S5C_PROJ_LIFT] THEN EXISTS_TAC `x:real^3` THEN
        ASM_REWRITE_TAC[]];
      MP_TAC(SPEC `h:real` MOI_S5C_LIFT_LINEAR) THEN
      DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC STRIP_ASSUME_TAC) THEN
      MATCH_MP_TAC CONTINUOUS_ON_ADD THEN REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
      ASM_SIMP_TAC[LINEAR_CONTINUOUS_ON]];
    MATCH_MP_TAC MOI_S5C_PL_LINEAR THEN
    ASM_SIMP_TAC[MOI_S5C_PROJ_FACTS; LOCALLY_POLYHEDRAL_PL_POLYHEDRON];
    MP_TAC(SPEC `h:real` MOI_S5C_LIFT_LINEAR) THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC STRIP_ASSUME_TAC) THEN
    MATCH_MP_TAC PL_MAP_ON_AFFINE THEN
    ASM_SIMP_TAC[LOCALLY_POLYHEDRAL_PL_POLYHEDRON]]);;

let MOI_S5C_COLLAR_FACTS = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0
     ==> &0 < d0 /\
         (!x t. x IN B /\ x$3 = c /\ abs t <= &1
                ==> (Q:real^3->real->real^3) x t IN B /\ (Q x t)$3 = c + t * d0) /\
         (!x. x IN B /\ x$3 = c ==> Q x (&0) = x) /\
         (!x t x' t'. x IN B /\ x$3 = c /\ abs t <= &1 /\
                      x' IN B /\ x'$3 = c /\ abs t' <= &1 /\ Q x t = Q x' t'
                      ==> x = x' /\ t = t') /\
         (!z. z IN B /\ abs(z$3 - c) <= d0
              ==> ?x t. x IN B /\ x$3 = c /\ abs t <= &1 /\ z = Q x t) /\
         (\p. Q (fstcart p) (drop(sndcart p))) continuous_on
         ({x | x IN B /\ x$3 = c} PCROSS interval[--vec 1,vec 1]) /\
         (!t. abs t <= &1 ==> pl_map_on {x | x IN B /\ x$3 = c} (\x. Q x t))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[moi_s5c_mset] THEN
  DISCH_THEN(MP_TAC o el 6 o CONJUNCTS) THEN REWRITE_TAC[moi_s5c_collar]);;

let MOI_S5C_MSET_SOME = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0
     ==> compact {x:real^3 | x IN B /\ x$3 = c} /\
         {x:real^3 | x IN B /\ abs(x$3 - c) <= d0} SUBSET moi_s5c_otube /\
         pl_homeomorphism
          (B,interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
             interval(--vector[&1;&1]:real^2,vector[&1;&1])) (GG,FF) /\
         DISJOINT
          (IMAGE (FF:real^2->real^3)
             (relative_frontier (interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION
           IMAGE FF (relative_frontier (interval[--vector[&2;&2]:real^2,vector[&2;&2]])))
          moi_s35_ttube /\
         (!y. y IN B ==> FF ((GG:real^3->real^2) y) = y) /\
         (!x. x IN interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                   interval(--vector[&1;&1]:real^2,vector[&1;&1])
              ==> FF x IN B /\ GG (FF x) = x)`,
  REPEAT GEN_TAC THEN DISCH_THEN(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  ASM_SIMP_TAC[]);;

let MOI_S5C_LEVEL_SLAB = prove
 (`!c t d0. abs t <= &1 /\ &0 < d0 ==> abs((c + t * d0) - c) <= d0`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_ADD_SUB; REAL_ABS_MUL] THEN
  ASM_SIMP_TAC[REAL_ARITH `&0 < d ==> abs d = d`] THEN
  REWRITE_TAC[REAL_ARITH `a * d <= d <=> &0 <= (&1 - a) * d`] THEN
  MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC);;

let MOI_S5C_SEC_BASIC = prove
 (`!B K FF GG Q c d0 J t.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c} /\ abs t <= &1
     ==> moi_s5c_sec Q J t SUBSET B /\
         (!z. z IN moi_s5c_sec Q J t ==> z$3 = c + t * d0) /\
         moi_s5c_sec Q J t SUBSET moi_s5c_otube /\
         compact (moi_s5c_sec Q J t) /\ connected (moi_s5c_sec Q J t) /\
         ~(moi_s5c_sec Q J t = {}) /\
         pl_sphere 1 (moi_s5c_sec Q J t) /\
         pl_sphere 1 (IMAGE moi_s5c_proj (moi_s5c_sec Q J t)) /\
         moi_s5c_sec Q J t =
         IMAGE (moi_s35_lift (c + t * d0)) (IMAGE moi_s5c_proj (moi_s5c_sec Q J t)) /\
         pl_sphere 1 (IMAGE (GG:real^3->real^2) (moi_s5c_sec Q J t)) /\
         IMAGE GG (moi_s5c_sec Q J t) SUBSET
           (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
            interval(--vector[&1;&1]:real^2,vector[&1;&1])) DIFF
