let MOI_S5C_PUSH_SEC = prove
 (`!B K FF GG Q c d0 J t (phi:real^3->real^2) (p:real^1->real^2).
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c} /\ abs t <= &1 /\
     phi continuous_on B /\
     (!x y. x IN J /\ y IN J /\ phi x = phi y ==> x = y) /\
     p continuous_on interval[vec 0,vec 1] /\
     (!s x. s IN interval[vec 0,vec 1] /\ x IN J
            ==> ~(phi((Q:real^3->real->real^3) x ((&1 - drop s) * t)) = p s)) /\
     p(vec 0) IN outside(IMAGE phi (moi_s5c_sec Q J t))
     ==> p(vec 1) IN outside(IMAGE phi J)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_COLLAR_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "cin")
    (CONJUNCTS_THEN2 (LABEL_TAC "c0") (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (LABEL_TAC "ccont") (K ALL_TAC))))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J:real^3->bool`] MOI_S5C_SQC_BASIC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  SUBGOAL_THEN `(J:real^3->bool) SUBSET {x | x IN B /\ x$3 = c}` ASSUME_TAC THENL
   [MATCH_MP_TAC IN_COMPONENTS_SUBSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`J:real^3->bool`;
    `\q:real^(1,3)finite_sum. (phi:real^3->real^2)
       ((Q:real^3->real->real^3) (sndcart q) ((&1 - drop(fstcart q)) * t))`;
    `p:real^1->real^2`] MOI_S5C_PUSH_OUTSIDE) THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART; DROP_VEC] THEN
  REWRITE_TAC[REAL_SUB_RZERO; REAL_SUB_REFL; REAL_MUL_LID; REAL_MUL_LZERO] THEN
  SUBGOAL_THEN `IMAGE (\x. (phi:real^3->real^2) ((Q:real^3->real->real^3) x (&0))) J =
                IMAGE phi J /\
                IMAGE (\x. (phi:real^3->real^2) ((Q:real^3->real->real^3) x t)) J =
                IMAGE phi (moi_s5c_sec Q J t)`
  (fun th -> REWRITE_TAC[th]) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC IMAGE_EQ THEN REWRITE_TAC[] THEN X_GEN_TAC `x:real^3` THEN
      DISCH_TAC THEN AP_TERM_TAC THEN USE_THEN "c0" MATCH_MP_TAC THEN
      UNDISCH_TAC `(x:real^3) IN J` THEN
      UNDISCH_TAC `(J:real^3->bool) SUBSET {x | x IN B /\ x$3 = c}` THEN SET_TAC[];
      REWRITE_TAC[moi_s5c_sec; GSYM IMAGE_o; o_DEF]];
    ALL_TAC] THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ALL_TAC;
    MAP_EVERY X_GEN_TAC [`x:real^3`; `y:real^3`] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
      is_forall(concl th) && free_in `phi:real^3->real^2` (concl th) &&
      length(fst(strip_forall(concl th))) = 2)) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(Q:real^3->real->real^3) x (&0) = x /\ Q y (&0) = y`
     (fun th -> ASM_MESON_TAC[th]) THEN
    CONJ_TAC THEN USE_THEN "c0" MATCH_MP_TAC THEN
    UNDISCH_TAC `(J:real^3->bool) SUBSET {x | x IN B /\ x$3 = c}` THEN
    ASM SET_TAC[]] THEN
  SUBGOAL_THEN
   `(\q:real^(1,3)finite_sum. (phi:real^3->real^2)
       ((Q:real^3->real->real^3) (sndcart q) ((&1 - drop(fstcart q)) * t))) =
    phi o (\p:real^(3,1)finite_sum. Q (fstcart p) (drop(sndcart p))) o
    (\q:real^(1,3)finite_sum. pastecart (sndcart q) (lift t - t % fstcart q))`
  SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; FSTCART_PASTECART; SNDCART_PASTECART] THEN
    GEN_TAC THEN REWRITE_TAC[DROP_SUB; DROP_CMUL; LIFT_DROP] THEN
    AP_TERM_TAC THEN AP_TERM_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (\q:real^(1,3)finite_sum. pastecart (sndcart q) (lift t - t % fstcart q))
          (interval[vec 0,vec 1] PCROSS J) SUBSET
    {x:real^3 | x IN B /\ x$3 = c} PCROSS interval[--vec 1:real^1,vec 1]`
  ASSUME_TAC THENL
   [REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; FORALL_IN_PCROSS; PASTECART_IN_PCROSS;
                FSTCART_PASTECART; SNDCART_PASTECART] THEN
    MAP_EVERY X_GEN_TAC [`s:real^1`; `x:real^3`] THEN STRIP_TAC THEN CONJ_TAC THENL
     [UNDISCH_TAC `(J:real^3->bool) SUBSET {x | x IN B /\ x$3 = c}` THEN ASM SET_TAC[];
      UNDISCH_TAC `(s:real^1) IN interval[vec 0,vec 1]` THEN
      REWRITE_TAC[IN_INTERVAL_1; DROP_SUB; DROP_CMUL; LIFT_DROP; DROP_NEG; DROP_VEC] THEN
      UNDISCH_TAC `abs t <= &1` THEN
      SPEC_TAC(`drop s`,`u:real`) THEN GEN_TAC THEN
      REPEAT DISCH_TAC THEN
      SUBGOAL_THEN `abs(t - t * u) <= &1` MP_TAC THENL
       [REWRITE_TAC[REAL_ARITH `t - t * u = t * (&1 - u)`; REAL_ABS_MUL] THEN
        MATCH_MP_TAC(REAL_ARITH `x <= &1 * &1 ==> x <= &1`) THEN
        MATCH_MP_TAC REAL_LE_MUL2 THEN REWRITE_TAC[REAL_ABS_POS] THEN ASM_REAL_ARITH_TAC;
        REAL_ARITH_TAC]];
    ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
     [MATCH_MP_TAC CONTINUOUS_ON_PASTECART THEN CONJ_TAC THENL
       [SIMP_TAC[LINEAR_CONTINUOUS_ON; LINEAR_SNDCART];
        MATCH_MP_TAC CONTINUOUS_ON_SUB THEN REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
        MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN
        SIMP_TAC[LINEAR_CONTINUOUS_ON; LINEAR_FSTCART]];
      MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
      EXISTS_TAC `{x:real^3 | x IN B /\ x$3 = c} PCROSS interval[--vec 1:real^1,vec 1]` THEN
      ASM_REWRITE_TAC[]];
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `B:real^3->bool` THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[IMAGE_o] THEN
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `IMAGE (\p:real^(3,1)finite_sum. (Q:real^3->real->real^3) (fstcart p)
                        (drop(sndcart p)))
                ({x:real^3 | x IN B /\ x$3 = c} PCROSS interval[--vec 1:real^1,vec 1])` THEN
    CONJ_TAC THENL [MATCH_MP_TAC IMAGE_SUBSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; FORALL_IN_PCROSS; FSTCART_PASTECART;
                SNDCART_PASTECART; IN_ELIM_THM] THEN
    MAP_EVERY X_GEN_TAC [`x:real^3`; `v:real^1`] THEN STRIP_TAC THEN
    USE_THEN "cin" (MP_TAC o SPECL [`x:real^3`; `drop v`]) THEN
    ANTS_TAC THENL [ALL_TAC; SIMP_TAC[]] THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `(v:real^1) IN interval[--vec 1:real^1,vec 1]` THEN
    REWRITE_TAC[IN_INTERVAL_1; DROP_NEG; DROP_VEC] THEN REAL_ARITH_TAC]);;

let MOI_S5C_SEC_DISJ = prove
 (`!B K FF GG Q c d0 J J' t t'.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c} /\
     J' IN components {x | x IN B /\ x$3 = c} /\
     abs t <= &1 /\ abs t' <= &1 /\ (~(J = J') \/ ~(t = t'))
     ==> DISJOINT (moi_s5c_sec Q J t) (moi_s5c_sec Q J' t')`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ne"))))))) THEN
  SUBGOAL_THEN `(J:real^3->bool) SUBSET {x | x IN B /\ x$3 = c} /\
                (J':real^3->bool) SUBSET {x | x IN B /\ x$3 = c}` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC IN_COMPONENTS_SUBSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(J:real^3->bool = J') ==> DISJOINT J J'` ASSUME_TAC THENL
   [DISCH_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `J:real^3->bool`; `J':real^3->bool`] MOI_S5C_SQC_NEST) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]];
    ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
    MATCH_MP MOI_S5C_COLLAR_FACTS o check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
  DISCH_TAC THEN
  REWRITE_TAC[moi_s5c_sec; DISJOINT; EXTENSION; IN_INTER; IN_IMAGE; NOT_IN_EMPTY] THEN
  X_GEN_TAC `z:real^3` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `x:real^3` STRIP_ASSUME_TAC)
    (X_CHOOSE_THEN `x':real^3` STRIP_ASSUME_TAC)) THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`x:real^3`; `t:real`; `x':real^3`; `t':real`] o
    check (fun th -> is_forall(concl th) && length(fst(strip_forall(concl th))) = 4)) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [ASM SET_TAC[]; ASM SET_TAC[]; ASM SET_TAC[]; ASM SET_TAC[];
      ASM_MESON_TAC[]];
    STRIP_TAC] THEN
  SUBGOAL_THEN `J:real^3->bool = J'` ASSUME_TAC THENL
   [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN DISCH_TAC THEN
    UNDISCH_TAC `~(J:real^3->bool = J') ==> DISJOINT J J'` THEN ASM_REWRITE_TAC[] THEN
    ASM SET_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th -> concl th = `J:real^3->bool = J'`)) THEN
  FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th -> concl th = `t:real = t'`)) THEN
  USE_THEN "ne" MP_TAC THEN REWRITE_TAC[]);;

let MOI_S5C_NOT_IN_PUSH = prove
