        ALL_TAC] THEN
      MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
       [ALL_TAC; SIMP_TAC[LINEAR_CONTINUOUS_ON; MOI_S5C_PROJ_FACTS]] THEN
      MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
       [MATCH_MP_TAC CONTINUOUS_ON_SUB THEN REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
        MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN REWRITE_TAC[CONTINUOUS_ON_ID];
        ALL_TAC] THEN
      MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
      EXISTS_TAC `interval[--vec 1:real^1,vec 1]` THEN CONJ_TAC THENL
       [MATCH_MP_TAC MOI_S5C_COLLAR_TCONT THEN
        MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `c:real`; `d0:real`] THEN
        CONJ_TAC THENL [ASM_MESON_TAC[moi_s5c_mset]; ASM_MESON_TAC[]];
        REWRITE_TAC[SUBSET; FORALL_IN_IMAGE] THEN X_GEN_TAC `s:real^1` THEN DISCH_TAC THEN
        MP_TAC(ISPECL [`s:real^1`; `t:real`] MOI_S5C_UNIT_PARAM) THEN
        ASM_REWRITE_TAC[IN_INTERVAL_1; DROP_SUB; DROP_CMUL; LIFT_DROP; DROP_NEG;
                        DROP_VEC] THEN
        REAL_ARITH_TAC];
      MAP_EVERY X_GEN_TAC [`s:real^1`; `x:real^3`] THEN STRIP_TAC THEN
      USE_THEN "sep" MATCH_MP_TAC THEN ASM_SIMP_TAC[MOI_S5C_UNIT_PARAM];
      REWRITE_TAC[DROP_VEC; REAL_SUB_RZERO; REAL_MUL_LID] THEN
      MATCH_MP_TAC MOI_S5C_NOT_IN_PUSH THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[moi_s5c_sec; GSYM IMAGE_o; IN_IMAGE; o_THM] THEN
      DISCH_THEN(X_CHOOSE_THEN `x:real^3` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `x':real^3` STRIP_ASSUME_TAC))) THEN
      USE_THEN "sep" (MP_TAC o SPECL [`x':real^3`; `y:real^3`; `t:real`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; REWRITE_TAC[]] THEN
      MAP_EVERY UNDISCH_TAC
       [`moi_s5c_proj ((Q:real^3->real->real^3) y t) = moi_s5c_proj x`;
        `x = (Q:real^3->real->real^3) x' t`] THEN
      MESON_TAC[]];
    BETA_TAC THEN REWRITE_TAC[DROP_VEC; REAL_SUB_REFL; REAL_MUL_LZERO] THEN
    SUBGOAL_THEN `(Q:real^3->real->real^3) y (&0) = y` SUBST1_TAC THENL
     [FIRST_ASSUM(MP_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
        MATCH_MP MOI_S5C_COLLAR_FACTS o check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    DISCH_TAC THEN
    MP_TAC(ISPEC `IMAGE moi_s5c_proj J'` INSIDE_INTER_OUTSIDE) THEN
    MAP_EVERY UNDISCH_TAC
     [`IMAGE moi_s5c_proj J SUBSET inside (IMAGE moi_s5c_proj J')`;
      `moi_s5c_proj y IN outside (IMAGE moi_s5c_proj J')`; `(y:real^3) IN J`] THEN
    SET_TAC[]]);;

let MOI_S5C_COLLAR_APPROACH = prove
 (`!B K FF GG Q c d0 x sg a b u0.
     moi_s5c_mset B K FF GG Q c d0 /\ x IN B /\ x$3 = c /\
     (sg = &1 \/ sg = -- &1) /\ &0 <= a /\ a < b /\ b <= &1 /\ (u0 = a \/ u0 = b)
     ==> (Q:real^3->real->real^3) x (sg * u0) IN
         closure {Q x (sg * u) | u | a < u /\ u < b}`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "sg")
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "u0")))))))) THEN
  SUBGOAL_THEN `abs sg = &1` ASSUME_TAC THENL
   [USE_THEN "sg" (DISJ_CASES_THEN SUBST1_TAC) THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[CLOSURE_APPROACHABLE; IN_ELIM_THM] THEN
  X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `c:real`; `d0:real`; `Q:real^3->real->real^3`;
                 `x:real^3`] MOI_S5C_COLLAR_TCONT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [moi_s5c_mset] o
      check (MOI_S5C_HEAD "moi_s5c_mset")) THEN SIMP_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[continuous_on] THEN DISCH_THEN(MP_TAC o SPEC `lift(sg * u0)`) THEN
  REWRITE_TAC[IN_INTERVAL_1; DROP_VEC; DROP_NEG; LIFT_DROP] THEN
  ANTS_TAC THENL
   [REWRITE_TAC[REAL_ARITH `-- &1 <= x /\ x <= &1 <=> abs x <= &1`; REAL_ABS_MUL] THEN
    ASM_REWRITE_TAC[REAL_MUL_LID] THEN
    USE_THEN "u0" (DISJ_CASES_THEN SUBST1_TAC) THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dl:real` STRIP_ASSUME_TAC) THEN
  ABBREV_TAC `w = min (dl / &2) ((b - a) / &2)` THEN
  SUBGOAL_THEN `&0 < w /\ w < dl /\ a + w < b /\ a < b - w` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w" THEN MAP_EVERY UNDISCH_TAC [`&0 < dl`; `a < b`] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  ABBREV_TAC `u = if u0 = a then a + w else b - w` THEN
  SUBGOAL_THEN `a < u /\ u < b /\ abs(u - u0) < dl` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "u" THEN USE_THEN "u0" (DISJ_CASES_THEN SUBST1_TAC) THEN
    REWRITE_TAC[] THEN TRY COND_CASES_TAC THEN
    REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th -> let tm = concl th in
      not(is_forall tm) && not(can (find_term is_cond) tm) &&
      not(MOI_S5C_MENTIONS "real_min" tm)))) THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  EXISTS_TAC `(Q:real^3->real->real^3) x (sg * u)` THEN CONJ_TAC THENL
   [EXISTS_TAC `u:real` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `lift(sg * u)`) THEN
  REWRITE_TAC[LIFT_DROP; DIST_LIFT] THEN ONCE_REWRITE_TAC[DIST_SYM] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  REWRITE_TAC[REAL_ARITH `-- &1 <= x /\ x <= &1 <=> abs x <= &1`; REAL_ABS_MUL;
              GSYM REAL_SUB_LDISTRIB] THEN
  ASM_REWRITE_TAC[REAL_MUL_LID] THEN ASM_REAL_ARITH_TAC);;


(* ------------------------------------------------------------------------- *)
(* Collar strips between a circle and one of its sections, and their        *)
(* identification with regions of the square annulus.                      *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_CINJ = prove
 (`!B K FF GG Q c d0 x t x' t'.
     moi_s5c_mset B K FF GG Q c d0 /\
     x IN B /\ x$3 = c /\ abs t <= &1 /\ x' IN B /\ x'$3 = c /\ abs t' <= &1 /\
     (Q:real^3->real->real^3) x t = Q x' t'
     ==> x = x' /\ t = t'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`x:real^3`; `t:real`; `x':real^3`; `t':real`] o
    CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o MATCH_MP MOI_S5C_COLLAR_FACTS) THEN
  ASM_REWRITE_TAC[]);;

let MOI_S5C_STRIP_FACTS = prove
 (`!B K FF GG Q c d0 J sg s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c} /\ (sg = &1 \/ sg = -- &1) /\
     &0 < s /\ s < &1
     ==> connected {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 < u /\ u < s} /\
         ~({Q x (sg * u) | x IN J /\ &0 < u /\ u < s} = {}) /\
         open_in (subtopology euclidean B) {Q x (sg * u) | x IN J /\ &0 < u /\ u < s} /\
         compact {Q x (sg * u) | x IN J /\ &0 <= u /\ u <= s} /\
         {Q x (sg * u) | x IN J /\ &0 <= u /\ u <= s} SUBSET B /\
         {Q x (sg * u) | x IN J /\ &0 <= u /\ u <= s} =
           {Q x (sg * u) | x IN J /\ &0 < u /\ u < s} UNION J UNION
           moi_s5c_sec Q J (sg * s) /\
         J SUBSET closure {Q x (sg * u) | x IN J /\ &0 < u /\ u < s} /\
         moi_s5c_sec Q J (sg * s) SUBSET closure {Q x (sg * u) | x IN J /\ &0 < u /\ u < s} /\
         DISJOINT {Q x (sg * u) | x IN J /\ &0 < u /\ u < s} J /\
         DISJOINT {Q x (sg * u) | x IN J /\ &0 < u /\ u < s} (moi_s5c_sec Q J (sg * s)) /\
         DISJOINT J (moi_s5c_sec Q J (sg * s)) /\
         {Q x (sg * u) | x IN J /\ &0 < u /\ u < s} UNION moi_s5c_sec Q J (sg * s) SUBSET
           {Q x (sg * u) | x IN J /\ &0 < u /\ u < &1}`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "sg") STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `abs sg = &1` ASSUME_TAC THENL
   [USE_THEN "sg" (DISJ_CASES_THEN SUBST1_TAC) THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J:real^3->bool`] MOI_S5C_SQC_BASIC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  SUBGOAL_THEN `(J:real^3->bool) SUBSET {x | x IN B /\ x$3 = c}` ASSUME_TAC THENL
   [MATCH_MP_TAC IN_COMPONENTS_SUBSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN J ==> x IN B /\ x$3 = c` (LABEL_TAC "jl") THENL
   [UNDISCH_TAC `(J:real^3->bool) SUBSET {x | x IN B /\ x$3 = c}` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!x u. x IN J /\ &0 <= u /\ u <= &1
                ==> (Q:real^3->real->real^3) x (sg * u) IN B /\
                    abs(sg * u) <= &1` (LABEL_TAC "inb") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `abs(sg * u) <= &1` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[REAL_ABS_MUL; REAL_MUL_LID] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `x:real^3`; `sg * u`] MOI_S5C_SLAB_FACT) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[]; SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `!x. x IN J ==> (Q:real^3->real->real^3) x (sg * &0) = x` (LABEL_TAC "q0") THENL
   [REWRITE_TAC[REAL_MUL_RZERO] THEN REPEAT STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
      MATCH_MP MOI_S5C_COLLAR_FACTS o check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x u y v. x IN J /\ &0 <= u /\ u <= &1 /\ y IN J /\ &0 <= v /\ v <= &1 /\
              (Q:real^3->real->real^3) x (sg * u) = Q y (sg * v)
              ==> x = y /\ u = v` (LABEL_TAC "inj") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `x:real^3`; `sg * u`; `y:real^3`; `sg * v`] MOI_S5C_CINJ) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `sg * u = sg * v` THEN USE_THEN "sg" (DISJ_CASES_THEN SUBST1_TAC) THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `moi_s5c_collar B c d0 (Q:real^3->real->real^3)` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o el 6 o CONJUNCTS o REWRITE_RULE[moi_s5c_mset] o
      check (MOI_S5C_HEAD "moi_s5c_mset"));
    ALL_TAC] THEN
  SUBGOAL_THEN `compact (B:real^3->bool) /\
                FINITE (components {x:real^3 | x IN B /\ x$3 = c})` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!x u. x IN J /\ (u = &0 \/ u = s)
          ==> (Q:real^3->real->real^3) x (sg * u) IN
              closure {Q x (sg * u) | x IN J /\ &0 < u /\ u < s}`
  (LABEL_TAC "cl") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(SET_RULE `!s t (x:real^3). s SUBSET t /\ x IN s ==> x IN t`) THEN
    EXISTS_TAC `closure {(Q:real^3->real->real^3) x (sg * u) | u | &0 < u /\ u < s}` THEN
    (CONJ_TAC THENL
      [MATCH_MP_TAC SUBSET_CLOSURE THEN REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
       GEN_TAC THEN DISCH_THEN(X_CHOOSE_THEN `v:real` STRIP_ASSUME_TAC) THEN
       MAP_EVERY EXISTS_TAC [`x:real^3`; `v:real`] THEN ASM_REWRITE_TAC[];
       MATCH_MP_TAC MOI_S5C_COLLAR_APPROACH THEN
       MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `K:(real^3->bool)->bool`;
         `FF:real^2->real^3`; `GG:real^3->real^2`; `c:real`; `d0:real`] THEN
       ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
       (ASM_REAL_ARITH_TAC ORELSE ASM_MESON_TAC[])]);
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `c:real`; `d0:real`; `Q:real^3->real->real^3`;
      `J:real^3->bool`; `sg:real`; `&0`; `s:real`] MOI_S5C_SIDE_CONN) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN (USE_THEN "sg" ACCEPT_TAC ORELSE ASM_REAL_ARITH_TAC);
      SIMP_TAC[]];
    FIRST_X_ASSUM(X_CHOOSE_TAC `x0:real^3` o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY] o
      check (fun th -> concl th = `~(J:real^3->bool = {})`)) THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC [`(Q:real^3->real->real^3) x0 (sg * (s / &2))`; `x0:real^3`;
                          `s / &2`] THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    MP_TAC(ISPECL [`B:real^3->bool`; `c:real`; `d0:real`; `Q:real^3->real->real^3`;
      `J:real^3->bool`; `sg:real`; `&0`; `s:real`] MOI_S5C_SIDE_OPEN) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC MOI_S5C_COMPONENT_OPEN_IN THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REPEAT CONJ_TAC THEN (USE_THEN "sg" ACCEPT_TAC ORELSE ASM_REAL_ARITH_TAC);
    MP_TAC(ISPECL [`B:real^3->bool`; `c:real`; `d0:real`; `Q:real^3->real->real^3`;
      `J:real^3->bool`; `sg:real`; `&0`; `s:real`] MOI_S5C_SIDE_COMPACT) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THEN (USE_THEN "sg" ACCEPT_TAC ORELSE ASM_REAL_ARITH_TAC);
    REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `z:real^3` THEN
    DISCH_THEN(X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "inb" (MP_TAC o SPECL [`x:real^3`; `u:real`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; SIMP_TAC[]];
    REWRITE_TAC[EXTENSION; IN_UNION; IN_ELIM_THM; moi_s5c_sec; IN_IMAGE] THEN
    X_GEN_TAC `z:real^3` THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC)) THEN
      ASM_CASES_TAC `u = &0` THENL
       [DISJ2_TAC THEN DISJ1_TAC THEN UNDISCH_TAC `z = (Q:real^3->real->real^3) x (sg * u)` THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
        USE_THEN "q0" (fun th -> ASM_SIMP_TAC[th]);
        ALL_TAC] THEN
      ASM_CASES_TAC `u:real = s` THENL
       [DISJ2_TAC THEN DISJ2_TAC THEN EXISTS_TAC `x:real^3` THEN ASM_MESON_TAC[];
        DISJ1_TAC THEN MAP_EVERY EXISTS_TAC [`x:real^3`; `u:real`] THEN
        ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC];
      DISCH_THEN(DISJ_CASES_THEN2
        (X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC))
        (DISJ_CASES_THEN2 ASSUME_TAC (X_CHOOSE_THEN `x:real^3` STRIP_ASSUME_TAC))) THENL
       [MAP_EVERY EXISTS_TAC [`x:real^3`; `u:real`] THEN ASM_REWRITE_TAC[] THEN
        ASM_REAL_ARITH_TAC;
        MAP_EVERY EXISTS_TAC [`z:real^3`; `&0`] THEN
        REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN TRY ASM_REAL_ARITH_TAC THEN
        CONV_TAC SYM_CONV THEN USE_THEN "q0" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        MAP_EVERY EXISTS_TAC [`x:real^3`; `s:real`] THEN ASM_REWRITE_TAC[] THEN
        ASM_REAL_ARITH_TAC]];
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
    USE_THEN "q0" (fun th -> SUBST1_TAC(SYM(MATCH_MP th (ASSUME `(x:real^3) IN J`)))) THEN
    USE_THEN "cl" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[SUBSET; moi_s5c_sec; FORALL_IN_IMAGE] THEN X_GEN_TAC `x:real^3` THEN
    DISCH_TAC THEN
    USE_THEN "cl" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; IN_ELIM_THM] THEN
    X_GEN_TAC `z:real^3` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real`
      STRIP_ASSUME_TAC)) ASSUME_TAC) THEN
    USE_THEN "inj" (MP_TAC o SPECL [`x:real^3`; `u:real`; `z:real^3`; `&0`]) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN TRY ASM_REAL_ARITH_TAC THEN
      USE_THEN "q0" (fun th -> REWRITE_TAC[MATCH_MP th (ASSUME `(z:real^3) IN J`)]) THEN
      ASM_MESON_TAC[];
      ASM_REAL_ARITH_TAC];
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; IN_ELIM_THM; moi_s5c_sec;
                IN_IMAGE] THEN
    X_GEN_TAC `z:real^3` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real`
      STRIP_ASSUME_TAC)) (X_CHOOSE_THEN `y:real^3` STRIP_ASSUME_TAC)) THEN
    USE_THEN "inj" (MP_TAC o SPECL [`x:real^3`; `u:real`; `y:real^3`; `s:real`]) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN TRY ASM_REAL_ARITH_TAC THEN
      ASM_MESON_TAC[];
      ASM_REAL_ARITH_TAC];
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; moi_s5c_sec; IN_IMAGE] THEN
    X_GEN_TAC `z:real^3` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `y:real^3` STRIP_ASSUME_TAC)) THEN
    USE_THEN "inj" (MP_TAC o SPECL [`z:real^3`; `&0`; `y:real^3`; `s:real`]) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN TRY ASM_REAL_ARITH_TAC THEN
      USE_THEN "q0" (fun th -> REWRITE_TAC[MATCH_MP th (ASSUME `(z:real^3) IN J`)]) THEN
      ASM_MESON_TAC[];
      ASM_REAL_ARITH_TAC];
    REWRITE_TAC[SUBSET; IN_UNION; IN_ELIM_THM; moi_s5c_sec; IN_IMAGE] THEN
    X_GEN_TAC `z:real^3` THEN
    DISCH_THEN(DISJ_CASES_THEN2
      (X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC))
      (X_CHOOSE_THEN `x:real^3` STRIP_ASSUME_TAC)) THENL
     [MAP_EVERY EXISTS_TAC [`x:real^3`; `u:real`] THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC;
      MAP_EVERY EXISTS_TAC [`x:real^3`; `s:real`] THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC]]);;

let MOI_S5C_OPEN_IN_SUB_OPEN = prove
 (`!(a:real^2->bool) u v.
     open_in (subtopology euclidean a) u /\ open v /\ u SUBSET v /\ v SUBSET a
     ==> open u`,
  REPEAT GEN_TAC THEN REWRITE_TAC[OPEN_IN_OPEN] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `w:real^2->bool` STRIP_ASSUME_TAC)
    STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(u:real^2->bool) = w INTER v` SUBST1_TAC THENL
   [ASM SET_TAC[]; ASM_SIMP_TAC[OPEN_INTER]]);;

let MOI_S5C_STRIP_IMAGE = prove
 (`!B K FF GG Q c d0 J sg s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c} /\ (sg = &1 \/ sg = -- &1) /\
     &0 < s /\ s < &1
     ==> connected (IMAGE (GG:real^3->real^2)
                      {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 < u /\ u < s}) /\
         ~(IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < s} = {}) /\
         open_in (subtopology euclidean
                   (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                    interval(--vector[&1;&1]:real^2,vector[&1;&1])))
                 (IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < s}) /\
         closure (IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < s}) SUBSET
           IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < s} UNION IMAGE GG J UNION
           IMAGE GG (moi_s5c_sec Q J (sg * s)) /\
         IMAGE GG J SUBSET closure (IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < s}) /\
         IMAGE GG (moi_s5c_sec Q J (sg * s)) SUBSET
           closure (IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < s}) /\
         DISJOINT (IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < s}) (IMAGE GG J) /\
         DISJOINT (IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < s})
                  (IMAGE GG (moi_s5c_sec Q J (sg * s))) /\
         DISJOINT (IMAGE GG J) (IMAGE GG (moi_s5c_sec Q J (sg * s))) /\
         IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < s} UNION
         IMAGE GG (moi_s5c_sec Q J (sg * s)) SUBSET
           IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < &1} /\
         IMAGE (FF:real^2->real^3)
           (IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < s} UNION IMAGE GG J UNION
            IMAGE GG (moi_s5c_sec Q J (sg * s))) =
         {Q x (sg * u) | x IN J /\ &0 <= u /\ u <= s}`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(fun th -> STRIP_ASSUME_TAC(MATCH_MP MOI_S5C_STRIP_FACTS th) THEN
    MP_TAC th) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "sg") STRIP_ASSUME_TAC)))) THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_MSET_SOME) THEN STRIP_TAC THEN
  ABBREV_TAC `So = {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 < u /\ u < s}` THEN
  ABBREV_TAC `Sc = {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 <= u /\ u <= s}` THEN
  ABBREV_TAC `P3 = moi_s5c_sec (Q:real^3->real->real^3) J (sg * s)` THEN
  FIRST_X_ASSUM(ASSUME_TAC o SYM o check (fun th ->
    concl th = `Sc:real^3->bool = So UNION J UNION P3`)) THEN
  SUBGOAL_THEN `(J:real^3->bool) SUBSET B /\ (P3:real^3->bool) SUBSET B /\
                (So:real^3->bool) SUBSET B` STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`(Sc:real^3->bool) SUBSET B`;
      `So UNION J UNION P3:real^3->bool = Sc`] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `homeomorphism
     (B:real^3->bool,interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                     interval(--vector[&1;&1]:real^2,vector[&1;&1]))
     (GG:real^3->real^2,FF:real^2->real^3)` ASSUME_TAC THENL
   [ASM_MESON_TAC[pl_homeomorphism]; ALL_TAC] THEN
  SUBGOAL_THEN `(GG:real^3->real^2) continuous_on B /\
                (!x y. x IN B /\ y IN B /\ GG x = GG y ==> x = y)` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `homeomorphism
     (B:real^3->bool,interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                     interval(--vector[&1;&1]:real^2,vector[&1;&1]))
     (GG:real^3->real^2,FF:real^2->real^3)` THEN
    REWRITE_TAC[homeomorphism] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!X Y:real^3->bool. X SUBSET B /\ Y SUBSET B /\ DISJOINT X Y
                ==> DISJOINT (IMAGE (GG:real^3->real^2) X) (IMAGE GG Y)`
  (LABEL_TAC "dj") THENL
   [REPEAT STRIP_TAC THEN
    MAP_EVERY UNDISCH_TAC
     [`!x y. x IN B /\ y IN B /\ (GG:real^3->real^2) x = GG y ==> x = y`;
      `(X:real^3->bool) SUBSET B`; `(Y:real^3->bool) SUBSET B`;
      `DISJOINT (X:real^3->bool) Y`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (GG:real^3->real^2) (closure So) SUBSET closure (IMAGE GG So)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC IMAGE_CLOSURE_SUBSET THEN REWRITE_TAC[CLOSED_CLOSURE; CLOSURE_SUBSET] THEN
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `B:real^3->bool` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `Sc:real^3->bool` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC CLOSURE_MINIMAL THEN
    ASM_SIMP_TAC[COMPACT_IMP_CLOSED] THEN
    UNDISCH_TAC `So UNION J UNION P3:real^3->bool = Sc` THEN SET_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `B:real^3->bool` THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[IMAGE_EQ_EMPTY];
    MATCH_MP_TAC HOMEOMORPHISM_IMP_OPEN_MAP THEN
    MAP_EVERY EXISTS_TAC [`FF:real^2->real^3`; `B:real^3->bool`] THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC CLOSURE_MINIMAL THEN CONJ_TAC THENL
     [REWRITE_TAC[GSYM IMAGE_UNION] THEN
      MATCH_MP_TAC IMAGE_SUBSET THEN
      UNDISCH_TAC `So UNION J UNION P3:real^3->bool = Sc` THEN SET_TAC[];
      REWRITE_TAC[GSYM IMAGE_UNION] THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC COMPACT_IMP_CLOSED THEN MATCH_MP_TAC COMPACT_CONTINUOUS_IMAGE THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
      EXISTS_TAC `B:real^3->bool` THEN ASM_REWRITE_TAC[]];
    MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `IMAGE (GG:real^3->real^2) (closure So)` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC IMAGE_SUBSET THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `IMAGE (GG:real^3->real^2) (closure So)` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC IMAGE_SUBSET THEN ASM_REWRITE_TAC[];
    USE_THEN "dj" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    USE_THEN "dj" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    USE_THEN "dj" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[GSYM IMAGE_UNION] THEN MATCH_MP_TAC IMAGE_SUBSET THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[GSYM IMAGE_UNION] THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM IMAGE_o] THEN MATCH_MP_TAC EQ_TRANS THEN
    EXISTS_TAC `IMAGE (\x:real^3. x) Sc` THEN CONJ_TAC THENL
     [MATCH_MP_TAC IMAGE_EQ THEN REWRITE_TAC[o_THM] THEN
      MAP_EVERY UNDISCH_TAC [`(Sc:real^3->bool) SUBSET B`;
        `!y. y IN B ==> (FF:real^2->real^3) ((GG:real^3->real^2) y) = y`] THEN
      SET_TAC[];
      REWRITE_TAC[IMAGE_ID]]]);;

let MOI_S5C_GG_OTUBE = prove
 (`!B K FF GG Q c d0 z.
     moi_s5c_mset B K FF GG Q c d0 /\ z IN B /\ z IN moi_s5c_otube
     ==> (GG:real^3->real^2) z IN
         interval(--vector[&2;&2]:real^2,vector[&2;&2]) DIFF
         interval[--vector[&1;&1]:real^2,vector[&1;&1]]`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_MSET_SOME) THEN STRIP_TAC THEN
  SUBGOAL_THEN `(GG:real^3->real^2) z IN
                interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                interval(--vector[&1;&1]:real^2,vector[&1;&1])` MP_TAC THENL
   [UNDISCH_TAC `pl_homeomorphism
          (B:real^3->bool,interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
             interval(--vector[&1;&1]:real^2,vector[&1;&1]))
          (GG:real^3->real^2,FF:real^2->real^3)` THEN
    REWRITE_TAC[pl_homeomorphism; homeomorphism] THEN
    UNDISCH_TAC `(z:real^3) IN B` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((GG:real^3->real^2) z IN
                  relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
                  relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`
  MP_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(z:real^3) IN moi_s35_ttube` MP_TAC THENL
     [MP_TAC MOI_S5C_OTUBE THEN UNDISCH_TAC `(z:real^3) IN moi_s5c_otube` THEN SET_TAC[];
      ALL_TAC] THEN
    UNDISCH_TAC `DISJOINT
          (IMAGE (FF:real^2->real^3)
             (relative_frontier (interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION
           IMAGE FF (relative_frontier (interval[--vector[&2;&2]:real^2,vector[&2;&2]])))
          moi_s35_ttube` THEN
    SUBGOAL_THEN `(z:real^3) = (FF:real^2->real^3) (GG z)` SUBST1_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `(GG:real^3->real^2) z IN
        relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]) UNION
        relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])` THEN
    SET_TAC[];
    REWRITE_TAC[IN_DIFF; IN_UNION; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO; MOI_S5C_IN_RF1;
                MOI_S5C_IN_RF2] THEN REAL_ARITH_TAC]);;

let MOI_S5C_STRIP_REGION = prove
 (`!B K FF GG Q c d0 J sg s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c} /\ (sg = &1 \/ sg = -- &1) /\
     &0 < s /\ s < &1
     ==> (IMAGE (GG:real^3->real^2)
            {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 < u /\ u < &1} SUBSET
          outside (IMAGE GG J)
          ==> IMAGE GG J SUBSET inside (IMAGE GG (moi_s5c_sec Q J (sg * s))) /\
              IMAGE (FF:real^2->real^3)
                (moi_s5c_rg (IMAGE GG J) (IMAGE GG (moi_s5c_sec Q J (sg * s)))) =
              {Q x (sg * u) | x IN J /\ &0 <= u /\ u <= s}) /\
         (IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < &1} SUBSET inside (IMAGE GG J)
          ==> IMAGE GG (moi_s5c_sec Q J (sg * s)) SUBSET inside (IMAGE GG J) /\
              IMAGE FF (moi_s5c_rg (IMAGE GG (moi_s5c_sec Q J (sg * s))) (IMAGE GG J)) =
              {Q x (sg * u) | x IN J /\ &0 <= u /\ u <= s})`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(fun th -> STRIP_ASSUME_TAC(MATCH_MP MOI_S5C_STRIP_IMAGE th) THEN
    MP_TAC th) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "sg") STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `abs(sg * s) <= &1` ASSUME_TAC THENL
   [USE_THEN "sg" (DISJ_CASES_THEN SUBST1_TAC) THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J:real^3->bool`; `sg * s`] MOI_S5C_SEC_BASIC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J:real^3->bool`; `sg * s`] MOI_S5C_SEC_SQ_ESS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `J:real^3->bool`] MOI_S5C_SQC_BASIC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  ABBREV_TAC `Ho = IMAGE (GG:real^3->real^2)
     {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 < u /\ u < s}` THEN
  ABBREV_TAC `Hh = IMAGE (GG:real^3->real^2)
     {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 < u /\ u < &1}` THEN
  ABBREV_TAC `X = IMAGE (GG:real^3->real^2) J` THEN
  ABBREV_TAC `P = IMAGE (GG:real^3->real^2) (moi_s5c_sec Q J (sg * s))` THEN
  SUBGOAL_THEN `open (Ho:real^2->bool)` ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_OPEN_IN_SUB_OPEN THEN
    MAP_EVERY EXISTS_TAC
     [`interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
       interval(--vector[&1;&1]:real^2,vector[&1;&1])`;
      `interval(--vector[&2;&2]:real^2,vector[&2;&2]) DIFF
       interval[--vector[&1;&1]:real^2,vector[&1;&1]]`] THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC OPEN_DIFF THEN REWRITE_TAC[OPEN_INTERVAL; CLOSED_INTERVAL];
      EXPAND_TAC "Ho" THEN REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; IN_ELIM_THM] THEN
      X_GEN_TAC `z:real^3` THEN
      DISCH_THEN(X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC)) THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOI_S5C_GG_OTUBE THEN
      MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `K:(real^3->bool)->bool`;
        `FF:real^2->real^3`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
        `x:real^3`; `sg * u`] MOI_S5C_SLAB_FACT) THEN
      ANTS_TAC THENL [ALL_TAC; SIMP_TAC[]] THEN
      CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      CONJ_TAC THENL
       [UNDISCH_TAC `(x:real^3) IN J` THEN
        UNDISCH_TAC `(J:real^3->bool) SUBSET B` THEN SET_TAC[];
        ALL_TAC] THEN
      CONJ_TAC THENL
       [UNDISCH_TAC `(x:real^3) IN J` THEN
        UNDISCH_TAC `!x:real^3. x IN J ==> x$3 = c` THEN MESON_TAC[];
        ALL_TAC] THEN
      USE_THEN "sg" (DISJ_CASES_THEN SUBST1_TAC) THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[SUBSET; IN_DIFF; MOI_S5C_IN_SQI; MOI_S5C_IN_SQO] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!U V. pl_sphere 1 U /\ pl_sphere 1 V /\ U SUBSET inside V /\
          Ho SUBSET moi_s5c_rgo U V /\ (U = X /\ V = P \/ U = P /\ V = X)
          ==> IMAGE (FF:real^2->real^3) (moi_s5c_rg U V) =
              {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 <= u /\ u <= s}`
  (LABEL_TAC "core") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "uv"))))) THEN
    MP_TAC(ISPECL [`U:real^2->bool`; `V:real^2->bool`] MOI_S5C_RG_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> let cs = CONJUNCTS th in
      ASSUME_TAC (el 2 cs) THEN ASSUME_TAC (el 6 cs) THEN ASSUME_TAC (el 10 cs)) THEN
    SUBGOAL_THEN `U UNION V:real^2->bool = X UNION P` ASSUME_TAC THENL
     [USE_THEN "uv" MP_TAC THEN SET_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `moi_s5c_rgo U V SUBSET (Ho:real^2->bool)` ASSUME_TAC THENL
     [MATCH_MP_TAC MOI_S5C_CLOPEN_CONNECTED THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MAP_EVERY UNDISCH_TAC
         [`closure Ho SUBSET (Ho UNION X UNION P:real^2->bool)`;
          `DISJOINT (moi_s5c_rgo U V) (U UNION V)`;
          `U UNION V:real^2->bool = X UNION P`] THEN SET_TAC[];
        MAP_EVERY UNDISCH_TAC [`~(Ho:real^2->bool = {})`;
          `Ho SUBSET moi_s5c_rgo U V`] THEN SET_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `moi_s5c_rg U V = Ho UNION X UNION P` SUBST1_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MAP_EVERY UNDISCH_TAC [`moi_s5c_rgo U V SUBSET (Ho:real^2->bool)`;
        `Ho SUBSET moi_s5c_rgo U V`; `U UNION V:real^2->bool = X UNION P`] THEN
      SET_TAC[];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(X:real^2->bool) homeomorphic sphere(vec 0:real^2,&1) /\
                (P:real^2->bool) homeomorphic sphere(vec 0:real^2,&1)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2; ARITH];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(P:real^2->bool = {})` ASSUME_TAC THENL
   [EXPAND_TAC "P" THEN ASM_REWRITE_TAC[IMAGE_EQ_EMPTY]; ALL_TAC] THEN
  CONJ_TAC THEN DISCH_TAC THENL
   [SUBGOAL_THEN `X SUBSET inside (P:real^2->bool)` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`X:real^2->bool`; `P:real^2->bool`] MOI_S5C_JORDAN_NEST) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN `(vec 0:real^2) IN interval(--vector[&1;&1],vector[&1;&1])` MP_TAC THENL
         [REWRITE_TAC[MOI_S5C_IN_SQO; VEC_COMPONENT] THEN REAL_ARITH_TAC; ALL_TAC] THEN
        MAP_EVERY UNDISCH_TAC
         [`interval(--vector[&1;&1],vector[&1;&1]) SUBSET inside (X:real^2->bool)`;
          `interval[--vector[&1;&1],vector[&1;&1]] SUBSET inside (P:real^2->bool)`] THEN
        REWRITE_TAC[GSYM INTERIOR_INTERVAL] THEN
        MP_TAC(ISPEC `interval[--vector[&1;&1]:real^2,vector[&1;&1]]` INTERIOR_SUBSET) THEN
        REWRITE_TAC[INTERIOR_INTERVAL] THEN SET_TAC[];
        ALL_TAC] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPEC `X:real^2->bool` INSIDE_INTER_OUTSIDE) THEN
      MAP_EVERY UNDISCH_TAC [`P SUBSET inside (X:real^2->bool)`;
        `Ho UNION P SUBSET (Hh:real^2->bool)`; `Hh SUBSET outside (X:real^2->bool)`;
        `~(P:real^2->bool = {})`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN USE_THEN "core" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC MOI_S5C_CONN_IN_RGO_OUT THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MAP_EVERY UNDISCH_TAC [`Ho UNION P SUBSET (Hh:real^2->bool)`;
        `Hh SUBSET outside (X:real^2->bool)`] THEN SET_TAC[];
      MAP_EVERY UNDISCH_TAC [`X SUBSET closure (Ho:real^2->bool)`;
        `~(J:real^3->bool = {})`] THEN EXPAND_TAC "X" THEN SET_TAC[]];
    SUBGOAL_THEN `P SUBSET inside (X:real^2->bool)` ASSUME_TAC THENL
     [MAP_EVERY UNDISCH_TAC [`Ho UNION P SUBSET (Hh:real^2->bool)`;
        `Hh SUBSET inside (X:real^2->bool)`] THEN SET_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN USE_THEN "core" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC MOI_S5C_CONN_IN_RGO_IN THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MAP_EVERY UNDISCH_TAC [`Ho UNION P SUBSET (Hh:real^2->bool)`;
        `Hh SUBSET inside (X:real^2->bool)`] THEN SET_TAC[];
      MAP_EVERY UNDISCH_TAC [`X SUBSET closure (Ho:real^2->bool)`;
        `~(J:real^3->bool = {})`] THEN EXPAND_TAC "X" THEN SET_TAC[]]]);;


(* ------------------------------------------------------------------------- *)
(* The arch configuration (abstract): an annulus A above the level c        *)
(* joining two nested planar circles, two collar annuli going down to the  *)
(* level c - h, and the planar disks and annulus closing them; the two     *)
(* pancake spheres and the solid torus region V between them.              *)
(* ------------------------------------------------------------------------- *)

let moi_s5c_arch = new_definition
 `moi_s5c_arch c h (jin:real^2->bool) jout jin' jout' (A:real^3->bool) Cin Cout <=>
    &0 < h /\ abs c <= &1 / &512 /\ h <= &1 / &64 /\
    pl_sphere 1 jin /\ pl_sphere 1 jout /\ jin SUBSET inside jout /\
    pl_sphere 1 jin' /\ pl_sphere 1 jout' /\ jin' SUBSET inside jout' /\
    (!y. max (abs(y$1)) (abs(y$2)) <= &3 / &16 ==> y IN inside jin) /\
    (!y. max (abs(y$1)) (abs(y$2)) <= &3 / &16 ==> y IN inside jin') /\
    jout SUBSET {y | max (abs(y$1)) (abs(y$2)) < &5 / &16} /\
    jout' SUBSET {y | max (abs(y$1)) (abs(y$2)) < &5 / &16} /\
    pl_annulus_with_ends A (IMAGE (moi_s35_lift c) jin) (IMAGE (moi_s35_lift c) jout) /\
    A SUBSET moi_s35_ttube /\ (!x. x IN A ==> c <= x$3) /\
    (!x. x IN A /\ x$3 = c
         ==> x IN IMAGE (moi_s35_lift c) jin UNION IMAGE (moi_s35_lift c) jout) /\
    pl_annulus_with_ends Cin (IMAGE (moi_s35_lift c) jin)
                             (IMAGE (moi_s35_lift (c - h)) jin') /\
    pl_annulus_with_ends Cout (IMAGE (moi_s35_lift c) jout)
                              (IMAGE (moi_s35_lift (c - h)) jout') /\
    Cin SUBSET moi_s5c_otube /\ Cout SUBSET moi_s5c_otube /\
    (!x. x IN Cin ==> c - h <= x$3 /\ x$3 <= c) /\
    (!x. x IN Cout ==> c - h <= x$3 /\ x$3 <= c) /\
    (!x. x IN Cin /\ x$3 = c ==> x IN IMAGE (moi_s35_lift c) jin) /\
    (!x. x IN Cin /\ x$3 = c - h ==> x IN IMAGE (moi_s35_lift (c - h)) jin') /\
    (!x. x IN Cout /\ x$3 = c ==> x IN IMAGE (moi_s35_lift c) jout) /\
    (!x. x IN Cout /\ x$3 = c - h ==> x IN IMAGE (moi_s35_lift (c - h)) jout') /\
    DISJOINT Cin Cout`;;

let MOI_S5C_IN_LIFT = prove
 (`!h (S:real^2->bool) x.
     x IN IMAGE (moi_s35_lift h) S <=> x$3 = h /\ moi_s5c_proj x IN S`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_IMAGE] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `y:real^2` STRIP_ASSUME_TAC) THEN
    ASM_REWRITE_TAC[MOI_S5C_PROJ_LIFT];
    STRIP_TAC THEN EXISTS_TAC `moi_s5c_proj x` THEN ASM_SIMP_TAC[MOI_S5C_PROJ_LIFT]]);;

let MOI_S5C_PLANAR_NEST_FACTS = prove
 (`!j j':real^2->bool.
     pl_sphere 1 j /\ pl_sphere 1 j' /\ j SUBSET inside j'
     ==> DISJOINT j j' /\ DISJOINT j' (j UNION inside j) /\
         j UNION inside j SUBSET inside j' /\ j' SUBSET outside j /\
         DISJOINT j (inside j) /\ DISJOINT j' (inside j')`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(j:real^2->bool) homeomorphic sphere(vec 0:real^2,&1) /\
                (j':real^2->bool) homeomorphic sphere(vec 0:real^2,&1)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2; ARITH];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`j:real^2->bool`; `j':real^2->bool`] MOI_S5C_NESTED_INSIDE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPEC `j:real^2->bool` INSIDE_NO_OVERLAP) THEN
  MP_TAC(ISPEC `j':real^2->bool` INSIDE_NO_OVERLAP) THEN
  MP_TAC(ISPEC `j:real^2->bool` INSIDE_INTER_OUTSIDE) THEN
  MP_TAC(ISPEC `j:real^2->bool` OUTSIDE_NO_OVERLAP) THEN
  UNDISCH_TAC `(j:real^2->bool) SUBSET inside j'` THEN
  UNDISCH_TAC `inside (j:real^2->bool) SUBSET inside j'` THEN
  UNDISCH_TAC `(j':real^2->bool) SUBSET outside j` THEN
  SET_TAC[]);;

let MOI_S5C_ARCH_POINTS = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> (!x:real^3. x IN A ==> c <= x$3) /\
         (!x:real^3. x IN A /\ x$3 = c
                     ==> moi_s5c_proj x IN jin \/ moi_s5c_proj x IN jout) /\
         (!x:real^3. x$3 = c /\ moi_s5c_proj x IN jin ==> x IN A /\ x IN Cin) /\
         (!x:real^3. x$3 = c /\ moi_s5c_proj x IN jout ==> x IN A /\ x IN Cout) /\
         (!x:real^3. x IN Cin ==> c - h <= x$3 /\ x$3 <= c) /\
         (!x:real^3. x IN Cout ==> c - h <= x$3 /\ x$3 <= c) /\
         (!x:real^3. x IN Cin /\ x$3 = c ==> moi_s5c_proj x IN jin) /\
         (!x:real^3. x IN Cin /\ x$3 = c - h ==> moi_s5c_proj x IN jin') /\
         (!x:real^3. x IN Cout /\ x$3 = c ==> moi_s5c_proj x IN jout) /\
         (!x:real^3. x IN Cout /\ x$3 = c - h ==> moi_s5c_proj x IN jout') /\
         (!x:real^3. x$3 = c - h /\ moi_s5c_proj x IN jin' ==> x IN Cin) /\
         (!x:real^3. x$3 = c - h /\ moi_s5c_proj x IN jout' ==> x IN Cout) /\
         (!y. ~(y IN jout /\ (y IN jin \/ y IN inside jin))) /\
         (!y. ~(y IN jout' /\ (y IN jin' \/ y IN inside jin'))) /\
         (!y. y IN jin' \/ y IN inside jin' ==> y IN inside jout') /\
         (!y. y IN jin \/ y IN inside jin ==> y IN inside jout) /\
         (!y. ~(y IN jin /\ y IN jout)) /\ (!y. ~(y IN jin' /\ y IN jout')) /\
         ~(c - h = c) /\
         (!x:real^3. c <= x$3 ==> ~(x$3 = c - h)) /\
         (!x:real^3. c - h <= x$3 /\ x$3 <= c /\ c <= x$3 ==> x$3 = c) /\
         (!x:real^3. x IN Cin ==> ~(x IN Cout))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[moi_s5c_arch] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`jin:real^2->bool`; `jout:real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`jin':real^2->bool`; `jout':real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ANN_ENDS_SUBSET o check (fun th ->
    MOI_S5C_HEAD "pl_annulus_with_ends" th && free_in `A:real^3->bool` (concl th))) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ANN_ENDS_SUBSET o check (fun th ->
    MOI_S5C_HEAD "pl_annulus_with_ends" th && free_in `Cin:real^3->bool` (concl th))) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ANN_ENDS_SUBSET o check (fun th ->
    MOI_S5C_HEAD "pl_annulus_with_ends" th && free_in `Cout:real^3->bool` (concl th))) THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
      is_forall(concl th) && free_in `A:real^3->bool` (concl th) &&
      free_in `jout:real^2->bool` (concl th))) THEN
    ASM_REWRITE_TAC[IN_UNION; MOI_S5C_IN_LIFT];
    REPEAT STRIP_TAC THEN
    MAP_EVERY UNDISCH_TAC [`IMAGE (moi_s35_lift c) jin SUBSET A`;
                           `IMAGE (moi_s35_lift c) jin SUBSET Cin`] THEN
    REWRITE_TAC[SUBSET; MOI_S5C_IN_LIFT] THEN ASM_MESON_TAC[];
    REPEAT STRIP_TAC THEN
    MAP_EVERY UNDISCH_TAC [`IMAGE (moi_s35_lift c) jout SUBSET A`;
                           `IMAGE (moi_s35_lift c) jout SUBSET Cout`] THEN
    REWRITE_TAC[SUBSET; MOI_S5C_IN_LIFT] THEN ASM_MESON_TAC[];
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
      is_forall(concl th) && free_in `Cin:real^3->bool` (concl th) &&
      free_in `jin:real^2->bool` (concl th) &&
      not(free_in `jin':real^2->bool` (concl th)))) THEN
    ASM_REWRITE_TAC[MOI_S5C_IN_LIFT];
    REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
      is_forall(concl th) && free_in `Cin:real^3->bool` (concl th) &&
      free_in `jin':real^2->bool` (concl th))) THEN
    ASM_REWRITE_TAC[MOI_S5C_IN_LIFT];
    REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
      is_forall(concl th) && free_in `Cout:real^3->bool` (concl th) &&
      free_in `jout:real^2->bool` (concl th) &&
      not(free_in `jout':real^2->bool` (concl th)))) THEN
    ASM_REWRITE_TAC[MOI_S5C_IN_LIFT];
    REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
      is_forall(concl th) && free_in `Cout:real^3->bool` (concl th) &&
      free_in `jout':real^2->bool` (concl th))) THEN
    ASM_REWRITE_TAC[MOI_S5C_IN_LIFT];
    UNDISCH_TAC `IMAGE (moi_s35_lift (c - h)) jin' SUBSET Cin` THEN
    REWRITE_TAC[SUBSET; MOI_S5C_IN_LIFT] THEN MESON_TAC[];
    UNDISCH_TAC `IMAGE (moi_s35_lift (c - h)) jout' SUBSET Cout` THEN
    REWRITE_TAC[SUBSET; MOI_S5C_IN_LIFT] THEN MESON_TAC[];
    UNDISCH_TAC `DISJOINT (jout:real^2->bool) (jin UNION inside jin)` THEN SET_TAC[];
    UNDISCH_TAC `DISJOINT (jout':real^2->bool) (jin' UNION inside jin')` THEN SET_TAC[];
    UNDISCH_TAC `jin' UNION inside jin' SUBSET inside (jout':real^2->bool)` THEN SET_TAC[];
    UNDISCH_TAC `jin UNION inside jin SUBSET inside (jout:real^2->bool)` THEN SET_TAC[];
    UNDISCH_TAC `DISJOINT (jin:real^2->bool) jout` THEN SET_TAC[];
    UNDISCH_TAC `DISJOINT (jin':real^2->bool) jout'` THEN SET_TAC[];
    ASM_REAL_ARITH_TAC;
    GEN_TAC THEN ASM_REAL_ARITH_TAC;
    GEN_TAC THEN REAL_ARITH_TAC;
    UNDISCH_TAC `DISJOINT (Cin:real^3->bool) Cout` THEN SET_TAC[]]);;

let MOI_S5C_ARCH_SETS = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> IMAGE (moi_s35_lift c) (jin UNION inside jin) INTER (A UNION Cout) =
           IMAGE (moi_s35_lift c) jin /\
         IMAGE (moi_s35_lift (c - h)) (jout' UNION inside jout') INTER (A UNION Cout) =
           IMAGE (moi_s35_lift (c - h)) jout' /\
         IMAGE (moi_s35_lift c) (jin UNION inside jin) INTER
           IMAGE (moi_s35_lift (c - h)) (jout' UNION inside jout') = {} /\
         IMAGE (moi_s35_lift c) (jin UNION inside jin) INTER Cin =
           IMAGE (moi_s35_lift c) jin /\
         IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin') INTER Cin =
           IMAGE (moi_s35_lift (c - h)) jin' /\
         IMAGE (moi_s35_lift c) (jin UNION inside jin) INTER
           IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin') = {} /\
         A INTER Cout = IMAGE (moi_s35_lift c) jout /\
         A INTER Cin = IMAGE (moi_s35_lift c) jin`,
  REPEAT GEN_TAC THEN DISCH_THEN(MP_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN
  DISCH_THEN(fun th ->
    REWRITE_TAC[EXTENSION; IN_INTER; IN_UNION; NOT_IN_EMPTY; MOI_S5C_IN_LIFT] THEN
    REPEAT CONJ_TAC THEN X_GEN_TAC `x:real^3` THEN MESON_TAC[th]));;

let MOI_S5C_LIFT_DISK = prove
 (`!h j:real^2->bool.
     pl_sphere 1 j
     ==> pl_cell_with_boundary 2 (IMAGE (moi_s35_lift h) (j UNION inside j))
                                 (IMAGE (moi_s35_lift h) j)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC MOI_S5C_LIFT_CELL THEN
  MATCH_MP_TAC MOI_S5C_PLANE_DISK THEN ASM_REWRITE_TAC[]);;

let MOI_S5C_ARCH_SPHERES = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> pl_sphere 2 (IMAGE (moi_s35_lift c) (jin UNION inside jin) UNION (A UNION Cout) UNION
                      IMAGE (moi_s35_lift (c - h)) (jout' UNION inside jout')) /\
         pl_sphere 2 (IMAGE (moi_s35_lift c) (jin UNION inside jin) UNION Cin UNION
                      IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin')) /\
         pl_annulus_with_ends (A UNION Cout) (IMAGE (moi_s35_lift c) jin)
                              (IMAGE (moi_s35_lift (c - h)) jout') /\
         pl_annulus_with_ends (Cin UNION A UNION Cout) (IMAGE (moi_s35_lift (c - h)) jin')
                              (IMAGE (moi_s35_lift (c - h)) jout')`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_SETS) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_arch] o
    check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
  SUBGOAL_THEN `pl_annulus_with_ends (A UNION Cout) (IMAGE (moi_s35_lift c) jin)
                              (IMAGE (moi_s35_lift (c - h)) jout')` ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_ANN_GLUE THEN
    EXISTS_TAC `IMAGE (moi_s35_lift c) jout` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MOI_S5C_SPH3 THEN
    MAP_EVERY EXISTS_TAC [`IMAGE (moi_s35_lift c) jin`;
                          `IMAGE (moi_s35_lift (c - h)) jout'`] THEN
    ASM_SIMP_TAC[MOI_S5C_LIFT_DISK] THEN
    ONCE_REWRITE_TAC[INTER_COMM] THEN ASM_REWRITE_TAC[] THEN
    ONCE_REWRITE_TAC[INTER_COMM] THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC MOI_S5C_SPH3 THEN
    MAP_EVERY EXISTS_TAC [`IMAGE (moi_s35_lift c) jin`;
                          `IMAGE (moi_s35_lift (c - h)) jin'`] THEN
    ASM_SIMP_TAC[MOI_S5C_LIFT_DISK];
    MATCH_MP_TAC MOI_S5C_ANN_GLUE THEN EXISTS_TAC `IMAGE (moi_s35_lift c) jin` THEN
    ASM_SIMP_TAC[MOI_S5C_ANN_SWAP] THEN
    SUBGOAL_THEN `DISJOINT (Cin:real^3->bool) Cout` MP_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `(A:real^3->bool) INTER Cin = IMAGE (moi_s35_lift c) jin` THEN
    SET_TAC[]]);;

let moi_s5c_sig1 = new_definition
 `moi_s5c_sig1 c h (jin:real^2->bool) jout' (A:real^3->bool) Cout =
    IMAGE (moi_s35_lift c) (jin UNION inside jin) UNION (A UNION Cout) UNION
    IMAGE (moi_s35_lift (c - h)) (jout' UNION inside jout')`;;

let moi_s5c_sig2 = new_definition
 `moi_s5c_sig2 c h (jin:real^2->bool) jin' (Cin:real^3->bool) =
    IMAGE (moi_s35_lift c) (jin UNION inside jin) UNION Cin UNION
    IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin')`;;

let MOI_S5C_PROJ_DIST = prove
 (`!x y:real^3. dist(moi_s5c_proj x,moi_s5c_proj y) <= dist(x,y)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dist; NORM_LE; moi_s5c_proj] THEN
  REWRITE_TAC[DOT_2; DOT_3; VECTOR_SUB_COMPONENT; VECTOR_2] THEN
  MP_TAC(SPEC `(x:real^3)$3 - (y:real^3)$3` REAL_LE_SQUARE) THEN REAL_ARITH_TAC);;

let MOI_S5C_FLAT_LEVEL = prove
 (`!(K:real^3->bool) P h z.
     closed K /\ ~(z IN K) /\ z$3 = h /\ moi_s5c_proj z IN P /\ open P
     ==> ?r. &0 < r /\
             !x. x IN ball(z,r)
                 ==> (x IN K UNION IMAGE (moi_s35_lift h) P <=> x$3 = h)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?r1. &0 < r1 /\ !x:real^3. x IN ball(z,r1) ==> ~(x IN K)`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `closed(K:real^3->bool)` THEN REWRITE_TAC[closed; open_def] THEN
    DISCH_THEN(MP_TAC o SPEC `z:real^3`) THEN ASM_REWRITE_TAC[IN_DIFF; IN_UNIV] THEN
    DISCH_THEN(X_CHOOSE_THEN `e:real` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `e:real` THEN ASM_REWRITE_TAC[IN_BALL] THEN
    ASM_MESON_TAC[DIST_SYM];
    ALL_TAC] THEN
  SUBGOAL_THEN `?r2. &0 < r2 /\ !y:real^2. dist(moi_s5c_proj z,y) < r2 ==> y IN P`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `open(P:real^2->bool)` THEN REWRITE_TAC[open_def] THEN
    DISCH_THEN(MP_TAC o SPEC `moi_s5c_proj z`) THEN ASM_REWRITE_TAC[] THEN
    MESON_TAC[DIST_SYM];
    ALL_TAC] THEN
  EXISTS_TAC `min r1 r2` THEN ASM_REWRITE_TAC[REAL_LT_MIN] THEN
  X_GEN_TAC `x:real^3` THEN REWRITE_TAC[IN_BALL; REAL_LT_MIN] THEN STRIP_TAC THEN
  REWRITE_TAC[IN_UNION; MOI_S5C_IN_LIFT] THEN
  SUBGOAL_THEN `~((x:real^3) IN K)` (fun th -> REWRITE_TAC[th]) THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[IN_BALL]; ALL_TAC] THEN
  SUBGOAL_THEN `moi_s5c_proj x IN P` (fun th -> REWRITE_TAC[th]) THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN
  MATCH_MP_TAC REAL_LET_TRANS THEN EXISTS_TAC `dist(z:real^3,x)` THEN
  ASM_REWRITE_TAC[MOI_S5C_PROJ_DIST]);;

let MOI_S5C_SQ_CONVEX_LT = prove
 (`!r. convex {y:real^2 | max (abs(y$1)) (abs(y$2)) < r}`,
  GEN_TAC THEN
  SUBGOAL_THEN `{y:real^2 | max (abs(y$1)) (abs(y$2)) < r} = interval(--vector[r;r],vector[r;r])`
  SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; MOI_S5C_IN_SQO]; REWRITE_TAC[CONVEX_INTERVAL]]);;

let MOI_S5C_SIG2_LEVEL = prove
 (`!c h (jin:real^2->bool) jin' (Cin:real^3->bool).
     &0 < h /\ (!x. x IN Cin ==> c - h <= x$3 /\ x$3 <= c)
     ==> !x. x IN moi_s5c_sig2 c h jin jin' Cin ==> c - h <= x$3 /\ x$3 <= c`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[moi_s5c_sig2; IN_UNION; MOI_S5C_IN_LIFT] THEN
  REPEAT STRIP_TAC THEN ASM_SIMP_TAC[] THEN ASM_REAL_ARITH_TAC);;

let MOI_S5C_SIG1_LEVEL = prove
 (`!c h (jin:real^2->bool) jout' (A:real^3->bool) Cout.
     &0 < h /\ (!x. x IN A ==> c <= x$3) /\
     (!x. x IN Cout ==> c - h <= x$3 /\ x$3 <= c)
     ==> (!x. x IN moi_s5c_sig1 c h jin jout' A Cout ==> c - h <= x$3) /\
         (!x. x IN moi_s5c_sig1 c h jin jout' A Cout /\ c < x$3 ==> x IN A)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[moi_s5c_sig1; IN_UNION; MOI_S5C_IN_LIFT] THEN
  CONJ_TAC THEN X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
  TRY(ASM_REAL_ARITH_TAC THEN NO_TAC) THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
      is_forall(concl th) && free_in `A:real^3->bool` (concl th))) THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
      is_forall(concl th) && free_in `Cout:real^3->bool` (concl th))) THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
      is_forall(concl th) && free_in `Cout:real^3->bool` (concl th))) THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC]);;

let MOI_S5C_HALF_OUT = prove
 (`!s:real^3->bool a.
     bounded s /\ (!x. x IN s ==> x$3 <= a) ==> {x:real^3 | a < x$3} SUBSET outside s`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
  MATCH_MP_TAC UNBOUNDED_DISJOINT_IN_OUTSIDE THEN
  EXISTS_TAC `{x:real^3 | a < x$3}` THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CONVEX_CONNECTED THEN
    REWRITE_TAC[REAL_ARITH `a < x <=> x > a`; CONVEX_HALFSPACE_COMPONENT_GT];
    REWRITE_TAC[BOUNDED_POS; NOT_EXISTS_THM; IN_ELIM_THM] THEN X_GEN_TAC `b:real` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (MP_TAC o SPEC `vector[&0;&0;abs a + b + &1]:real^3`)) THEN
    REWRITE_TAC[VECTOR_3] THEN
    MATCH_MP_TAC(TAUT `a /\ ~b ==> ~(a ==> b)`) THEN CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`vector[&0;&0;abs a + b + &1]:real^3`; `3`] COMPONENT_LE_NORM) THEN
    REWRITE_TAC[DIMINDEX_3; ARITH; VECTOR_3] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_ELIM_THM; NOT_IN_EMPTY] THEN
    ASM_MESON_TAC[REAL_NOT_LT]]);;

let MOI_S5C_HALF_OUT_LOW = prove
 (`!s:real^3->bool a.
