  REPEAT STRIP_TAC THEN REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
  MATCH_MP_TAC UNBOUNDED_DISJOINT_IN_OUTSIDE THEN
  EXISTS_TAC `{x:real^3 | x$3 < a}` THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CONVEX_CONNECTED THEN REWRITE_TAC[CONVEX_HALFSPACE_COMPONENT_LT];
    REWRITE_TAC[BOUNDED_POS; NOT_EXISTS_THM; IN_ELIM_THM] THEN X_GEN_TAC `b:real` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (MP_TAC o SPEC `vector[&0;&0;--(abs a + b + &1)]:real^3`)) THEN
