    MATCH_MP_TAC(TAUT `a /\ ~b ==> ~(a ==> b)`) THEN CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`vector[&0;&0;--(abs a + b + &1)]:real^3`; `3`] COMPONENT_LE_NORM) THEN
    REWRITE_TAC[DIMINDEX_3; ARITH; VECTOR_3] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_ELIM_THM; NOT_IN_EMPTY] THEN
    ASM_MESON_TAC[REAL_NOT_LT]]);;

let MOI_S5C_RAY3 = prove
 (`!(x:real^3) t. (x + t % basis 3)$1 = x$1 /\ (x + t % basis 3)$2 = x$2 /\
                  (x + t % basis 3)$3 = x$3 + t`,
  SIMP_TAC[VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; BASIS_COMPONENT;
           DIMINDEX_3; ARITH] THEN REAL_ARITH_TAC);;

let MOI_S5C_UPPER_NOTUBE = prove
 (`!s:real^3->bool c.
     bounded s /\ abs c < &1 / &32 /\ (!x. x IN s /\ c < x$3 ==> x IN moi_s35_ttube)
     ==> {x | c < x$3 /\ ~(x IN moi_s35_ttube)} SUBSET outside s`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `G = {x:real^3 | c < x$3 /\ ~(x IN moi_s35_ttube)}` THEN
  ABBREV_TAC `C = {x:real^3 | &1 / &32 < x$3}` THEN
  SUBGOAL_THEN `(C:real^3->bool) SUBSET G` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["C"; "G"] THEN
    REWRITE_TAC[SUBSET; IN_ELIM_THM; moi_s35_ttube] THEN GEN_TAC THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `connected (G:real^3->bool)` ASSUME_TAC THENL
   [SUBGOAL_THEN
     `(G:real^3->bool) =
      UNIONS {(C:real^3->bool) UNION
              IMAGE (\t. (x:real^3) + drop t % basis 3) {t:real^1 | &0 <= drop t} |
              x | x IN G}`
    SUBST1_TAC THENL
     [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
       [REWRITE_TAC[SUBSET; IN_UNIONS; IN_ELIM_THM] THEN X_GEN_TAC `x:real^3` THEN
        DISCH_TAC THEN
        EXISTS_TAC `(C:real^3->bool) UNION
                    IMAGE (\t. x + drop t % basis 3) {t:real^1 | &0 <= drop t}` THEN
        CONJ_TAC THENL [EXISTS_TAC `x:real^3` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        REWRITE_TAC[IN_UNION; IN_IMAGE; IN_ELIM_THM] THEN DISJ2_TAC THEN
        EXISTS_TAC `vec 0:real^1` THEN REWRITE_TAC[DROP_VEC; REAL_LE_REFL] THEN
        VECTOR_ARITH_TAC;
        REWRITE_TAC[SUBSET; IN_UNIONS; IN_ELIM_THM] THEN X_GEN_TAC `z:real^3` THEN
        DISCH_THEN(X_CHOOSE_THEN `t:real^3->bool` (CONJUNCTS_THEN2
          (X_CHOOSE_THEN `x:real^3` STRIP_ASSUME_TAC) MP_TAC)) THEN
        ASM_REWRITE_TAC[IN_UNION] THEN STRIP_TAC THENL
         [ASM SET_TAC[]; ALL_TAC] THEN
        UNDISCH_TAC `(z:real^3) IN IMAGE (\t. x + drop t % basis 3) {t:real^1 | &0 <= drop t}` THEN
        REWRITE_TAC[IN_IMAGE; IN_ELIM_THM] THEN
        DISCH_THEN(X_CHOOSE_THEN `v:real^1` STRIP_ASSUME_TAC) THEN
        UNDISCH_TAC `(x:real^3) IN G` THEN EXPAND_TAC "G" THEN
        ASM_REWRITE_TAC[IN_ELIM_THM; moi_s35_ttube; moi_s35_n; MOI_S5C_RAY3] THEN
        UNDISCH_TAC `&0 <= drop v` THEN UNDISCH_TAC `abs c < &1 / &32` THEN
        SPEC_TAC(`drop v`,`w:real`) THEN
        SPEC_TAC(`max (abs((x:real^3)$1)) (abs(x$2))`,`m:real`) THEN
        SPEC_TAC(`(x:real^3)$3`,`a:real`) THEN REPEAT GEN_TAC THEN REAL_ARITH_TAC];
      MATCH_MP_TAC CONNECTED_UNIONS THEN CONJ_TAC THENL
       [REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
        MATCH_MP_TAC CONNECTED_UNION THEN REPEAT CONJ_TAC THENL
         [EXPAND_TAC "C" THEN MATCH_MP_TAC CONVEX_CONNECTED THEN
          REWRITE_TAC[REAL_ARITH `a < x <=> x > a`; CONVEX_HALFSPACE_COMPONENT_GT];
          MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN CONJ_TAC THENL
           [MATCH_MP_TAC CONTINUOUS_ON_ADD THEN REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
            MATCH_MP_TAC CONTINUOUS_ON_VMUL THEN
            REWRITE_TAC[o_DEF; LIFT_DROP; CONTINUOUS_ON_ID; ETA_AX];
            REWRITE_TAC[GSYM IS_INTERVAL_CONNECTED_1; IS_INTERVAL_1; IN_ELIM_THM] THEN
            REAL_ARITH_TAC];
          REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER; IN_IMAGE; IN_ELIM_THM] THEN
          EXISTS_TAC `(x:real^3) + (abs(x$3) + &1) % basis 3` THEN CONJ_TAC THENL
           [EXPAND_TAC "C" THEN REWRITE_TAC[IN_ELIM_THM] THEN
            SIMP_TAC[VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; BASIS_COMPONENT;
                     DIMINDEX_3; ARITH] THEN REAL_ARITH_TAC;
            EXISTS_TAC `lift(abs((x:real^3)$3) + &1)` THEN
            REWRITE_TAC[LIFT_DROP] THEN REAL_ARITH_TAC]];
        REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTERS; FORALL_IN_GSPEC] THEN
        EXISTS_TAC `vector[&0;&0;&1]:real^3` THEN X_GEN_TAC `x:real^3` THEN
        DISCH_TAC THEN REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN EXPAND_TAC "C" THEN
        REWRITE_TAC[IN_ELIM_THM; VECTOR_3] THEN REAL_ARITH_TAC]];
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
  MATCH_MP_TAC UNBOUNDED_DISJOINT_IN_OUTSIDE THEN EXISTS_TAC `G:real^3->bool` THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(MESON[BOUNDED_SUBSET] `!s t:real^3->bool. ~bounded s /\ s SUBSET t ==> ~bounded t`) THEN
    EXISTS_TAC `C:real^3->bool` THEN ASM_REWRITE_TAC[] THEN EXPAND_TAC "C" THEN
    REWRITE_TAC[BOUNDED_POS; NOT_EXISTS_THM; IN_ELIM_THM] THEN X_GEN_TAC `b:real` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (MP_TAC o SPEC `vector[&0;&0;b + &1]:real^3`)) THEN
    REWRITE_TAC[VECTOR_3] THEN
    MATCH_MP_TAC(TAUT `a /\ ~b ==> ~(a ==> b)`) THEN CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`vector[&0;&0;b + &1]:real^3`; `3`] COMPONENT_LE_NORM) THEN
    REWRITE_TAC[DIMINDEX_3; ARITH; VECTOR_3] THEN ASM_REAL_ARITH_TAC;
    EXPAND_TAC "G" THEN REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_ELIM_THM;
                                    NOT_IN_EMPTY] THEN
    ASM_MESON_TAC[]]);;

let MOI_S5C_HALF_BALLS_NONEMPTY = prove
 (`!z:real^3 r. &0 < r
     ==> ~({x | x IN ball(z,r) /\ z$3 < x$3} = {}) /\
         ~({x | x IN ball(z,r) /\ x$3 < z$3} = {})`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM; IN_BALL] THEN CONJ_TAC THENL
   [EXISTS_TAC `(z:real^3) + (r / &2) % basis 3`;
    EXISTS_TAC `(z:real^3) - (r / &2) % basis 3`] THEN
  REWRITE_TAC[NORM_ARITH `dist(z:real^N,z + x) = norm x /\ dist(z,z - x) = norm x`] THEN
  SIMP_TAC[NORM_MUL; NORM_BASIS; DIMINDEX_3; ARITH; VECTOR_ADD_COMPONENT;
           VECTOR_SUB_COMPONENT; VECTOR_MUL_COMPONENT; BASIS_COMPONENT] THEN
  ASM_REAL_ARITH_TAC);;

let MOI_S5C_FLAT_OTHER = prove
 (`!s (z:real^3) r.
     s homeomorphic sphere(vec 0:real^3,&1) /\ z IN s /\ &0 < r /\
     (!x. x IN ball(z,r) ==> (x IN s <=> x$3 = z$3))
     ==> (({x | x IN ball(z,r) /\ z$3 < x$3} SUBSET outside s \/
           {x | x IN ball(z,r) /\ x$3 < z$3} SUBSET inside s)
          ==> {x | x IN ball(z,r) /\ z$3 < x$3} SUBSET outside s /\
              {x | x IN ball(z,r) /\ x$3 < z$3} SUBSET inside s) /\
         (({x | x IN ball(z,r) /\ z$3 < x$3} SUBSET inside s \/
           {x | x IN ball(z,r) /\ x$3 < z$3} SUBSET outside s)
          ==> {x | x IN ball(z,r) /\ z$3 < x$3} SUBSET inside s /\
              {x | x IN ball(z,r) /\ x$3 < z$3} SUBSET outside s)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`s:real^3->bool`; `z:real^3`; `r:real`] MOI_S5C_FLAT_SIDES) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`z:real^3`; `r:real`] MOI_S5C_HALF_BALLS_NONEMPTY) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPEC `s:real^3->bool` INSIDE_INTER_OUTSIDE) THEN
  SET_TAC[]);;

let MOI_S5C_ARCH_FACTS2 = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> moi_s5c_sig1 c h jin jout' A Cout homeomorphic sphere(vec 0:real^3,&1) /\
         moi_s5c_sig2 c h jin jin' Cin homeomorphic sphere(vec 0:real^3,&1) /\
         bounded (moi_s5c_sig1 c h jin jout' A Cout) /\
         bounded (moi_s5c_sig2 c h jin jin' Cin) /\
         (!x. x IN moi_s5c_sig2 c h jin jin' Cin ==> x$3 <= c) /\
         (!x. x IN moi_s5c_sig2 c h jin jin' Cin ==> c - h <= x$3) /\
         (!x. x IN moi_s5c_sig1 c h jin jout' A Cout ==> c - h <= x$3) /\
         (!x. x IN moi_s5c_sig1 c h jin jout' A Cout /\ c < x$3 ==> x IN moi_s35_ttube)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_SPHERES) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_arch] o
    check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
  MP_TAC(ISPECL [`c:real`; `h:real`; `jin:real^2->bool`; `jin':real^2->bool`;
                 `Cin:real^3->bool`] MOI_S5C_SIG2_LEVEL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  MP_TAC(ISPECL [`c:real`; `h:real`; `jin:real^2->bool`; `jout':real^2->bool`;
                 `A:real^3->bool`; `Cout:real^3->bool`] MOI_S5C_SIG1_LEVEL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `2` THEN
    REWRITE_TAC[DIMINDEX_3; ARITH] THEN ASM_REWRITE_TAC[moi_s5c_sig1];
    MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `2` THEN
    REWRITE_TAC[DIMINDEX_3; ARITH] THEN ASM_REWRITE_TAC[moi_s5c_sig2];
    MATCH_MP_TAC COMPACT_IMP_BOUNDED THEN
    MATCH_MP_TAC PL_POLYHEDRON_IMP_COMPACT THEN
    MATCH_MP_TAC MOI_SCD_PL_SPHERE_POLYHEDRON THEN EXISTS_TAC `2` THEN
    ASM_REWRITE_TAC[moi_s5c_sig1];
    MATCH_MP_TAC COMPACT_IMP_BOUNDED THEN
    MATCH_MP_TAC PL_POLYHEDRON_IMP_COMPACT THEN
    MATCH_MP_TAC MOI_SCD_PL_SPHERE_POLYHEDRON THEN EXISTS_TAC `2` THEN
    ASM_REWRITE_TAC[moi_s5c_sig2];
    ASM_MESON_TAC[];
    ASM_MESON_TAC[];
    ASM_MESON_TAC[];
    ASM_MESON_TAC[SUBSET]]);;

let MOI_S5C_LIFT_UNION = prove
 (`!h s t:real^2->bool.
     IMAGE (moi_s35_lift h) (s UNION t) =
     IMAGE (moi_s35_lift h) s UNION IMAGE (moi_s35_lift h) t`,
  REWRITE_TAC[IMAGE_UNION]);;

let MOI_S5C_LIFT_COMPACT = prove
 (`!h s:real^2->bool. compact s ==> compact (IMAGE (moi_s35_lift h) s)`,
  REPEAT STRIP_TAC THEN MP_TAC(SPEC `h:real` MOI_S5C_LIFT_LINEAR) THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC COMPACT_CONTINUOUS_IMAGE THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC CONTINUOUS_ON_ADD THEN REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
  ASM_SIMP_TAC[LINEAR_CONTINUOUS_ON]);;

let MOI_S5C_SPHERE1_COMPACT = prove
 (`!j:real^2->bool. pl_sphere 1 j ==> compact j /\ compact (j UNION inside j)`,
  GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_PLANE_DISK) THEN
  DISCH_THEN(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_PLANE_CELL_FACTS) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC PL_POLYHEDRON_IMP_COMPACT THEN
  MATCH_MP_TAC MOI_SCD_PL_SPHERE_POLYHEDRON THEN EXISTS_TAC `1` THEN
  ASM_REWRITE_TAC[]);;

let MOI_S5C_ARCH_P0 = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> ?r. &0 < r /\
             {x | x IN ball(vector[&0;&0;c],r) /\ x$3 < c} SUBSET
               inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
               inside (moi_s5c_sig2 c h jin jin' Cin)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_FACTS2) THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_arch] o
    check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
  ABBREV_TAC `p0:real^3 = vector[&0;&0;c]` THEN
  SUBGOAL_THEN `(p0:real^3)$3 = c /\ moi_s5c_proj p0 IN inside jin /\
                ~(moi_s5c_proj p0 IN jin) /\ ~(moi_s5c_proj p0 IN jout)`
  STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `moi_s5c_proj p0 = vec 0` SUBST1_TAC THENL
     [EXPAND_TAC "p0" THEN REWRITE_TAC[moi_s5c_proj; CART_EQ; DIMINDEX_2; FORALL_2;
        VECTOR_2; VECTOR_3; VEC_COMPONENT];
      ALL_TAC] THEN
    EXPAND_TAC "p0" THEN REWRITE_TAC[VECTOR_3] THEN
    SUBGOAL_THEN `(vec 0:real^2) IN inside jin` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
        is_forall(concl th) && free_in `jin:real^2->bool` (concl th) &&
        can (find_term ((=) `&3 / &16`)) (concl th))) THEN
      REWRITE_TAC[VEC_COMPONENT] THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`jin:real^2->bool`; `jout:real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `(vec 0:real^2) IN inside jin` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((p0:real^3) IN A) /\ ~(p0 IN Cout) /\ ~(p0 IN Cin)` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_POINTS o
      check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
    MAP_EVERY UNDISCH_TAC [`(p0:real^3)$3 = c`; `~(moi_s5c_proj p0 IN jin)`;
                           `~(moi_s5c_proj p0 IN jout)`] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `S1 = moi_s5c_sig1 c h jin jout' A Cout` THEN
  ABBREV_TAC `S2 = moi_s5c_sig2 c h jin jin' Cin` THEN
  SUBGOAL_THEN `(p0:real^3) IN S1 /\ (p0:real^3) IN S2` STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["S1"; "S2"] THEN
    REWRITE_TAC[moi_s5c_sig1; moi_s5c_sig2; IN_UNION; MOI_S5C_IN_LIFT] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `compact (A:real^3->bool) /\ compact (Cin:real^3->bool) /\
                compact (Cout:real^3->bool) /\
                compact (IMAGE (moi_s35_lift c) jin) /\
                compact (IMAGE (moi_s35_lift (c - h)) (jout' UNION inside jout')) /\
                compact (IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin'))`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM(fun th -> if MOI_S5C_HEAD "pl_annulus_with_ends" th
        then ACCEPT_TAC(CONJUNCT1(MATCH_MP MOI_S5C_ANN_COMPACT th)) else NO_TAC) THEN NO_TAC) THEN
    MATCH_MP_TAC MOI_S5C_LIFT_COMPACT THEN
    FIRST_ASSUM(fun th -> if MOI_S5C_HEAD "pl_sphere" th
        then ACCEPT_TAC(CONJUNCT1(MATCH_MP MOI_S5C_SPHERE1_COMPACT th)) ORELSE
             ACCEPT_TAC(CONJUNCT2(MATCH_MP MOI_S5C_SPHERE1_COMPACT th))
        else NO_TAC);
    ALL_TAC] THEN
  SUBGOAL_THEN `open (inside (jin:real^2->bool))` ASSUME_TAC THENL
   [MATCH_MP_TAC OPEN_INSIDE THEN MATCH_MP_TAC COMPACT_IMP_CLOSED THEN
    FIRST_ASSUM(fun th -> if concl th = `pl_sphere 1 (jin:real^2->bool)`
        then ACCEPT_TAC(CONJUNCT1(MATCH_MP MOI_S5C_SPHERE1_COMPACT th)) else NO_TAC);
    ALL_TAC] THEN
  MP_TAC(ISPECL [`A UNION Cout UNION IMAGE (moi_s35_lift (c - h)) (jout' UNION inside jout') UNION
                  IMAGE (moi_s35_lift c) jin`; `inside (jin:real^2->bool)`; `c:real`;
                 `p0:real^3`] MOI_S5C_FLAT_LEVEL) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC) THEN
      ASM_SIMP_TAC[COMPACT_IMP_CLOSED];
      REWRITE_TAC[IN_UNION; MOI_S5C_IN_LIFT; DE_MORGAN_THM] THEN
      ASM_REWRITE_TAC[] THEN UNDISCH_TAC `&0 < h` THEN REAL_ARITH_TAC];
    SUBGOAL_THEN
     `(S1:real^3->bool) =
      (A UNION Cout UNION IMAGE (moi_s35_lift (c - h)) (jout' UNION inside jout') UNION
       IMAGE (moi_s35_lift c) jin) UNION IMAGE (moi_s35_lift c) (inside jin)`
    (fun th -> REWRITE_TAC[SYM th]) THENL
     [EXPAND_TAC "S1" THEN
      REWRITE_TAC[moi_s5c_sig1; MOI_S5C_LIFT_UNION] THEN SET_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `r1:real` STRIP_ASSUME_TAC)]] THEN
  MP_TAC(ISPECL [`Cin UNION IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin') UNION
                  IMAGE (moi_s35_lift c) jin`; `inside (jin:real^2->bool)`; `c:real`;
                 `p0:real^3`] MOI_S5C_FLAT_LEVEL) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC) THEN
      ASM_SIMP_TAC[COMPACT_IMP_CLOSED];
      REWRITE_TAC[IN_UNION; MOI_S5C_IN_LIFT; DE_MORGAN_THM] THEN
      ASM_REWRITE_TAC[] THEN UNDISCH_TAC `&0 < h` THEN REAL_ARITH_TAC];
    SUBGOAL_THEN
     `(S2:real^3->bool) =
      (Cin UNION IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin') UNION
       IMAGE (moi_s35_lift c) jin) UNION IMAGE (moi_s35_lift c) (inside jin)`
    (fun th -> REWRITE_TAC[SYM th]) THENL
     [EXPAND_TAC "S2" THEN
      REWRITE_TAC[moi_s5c_sig2; MOI_S5C_LIFT_UNION] THEN SET_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `r2:real` STRIP_ASSUME_TAC)]] THEN
  EXISTS_TAC `min (min r1 r2) (&3 / &16)` THEN
  CONJ_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`&0 < r1`; `&0 < r2`] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `r = min (min r1 r2) (&3 / &16)` THEN
  SUBGOAL_THEN `&0 < r /\ r <= r1 /\ r <= r2 /\ r <= &3 / &16` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "r" THEN MAP_EVERY UNDISCH_TAC [`&0 < r1`; `&0 < r2`] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN ball(p0,r) ==> moi_s35_n x < &3 / &16` ASSUME_TAC THENL
   [X_GEN_TAC `x:real^3` THEN REWRITE_TAC[IN_BALL; moi_s35_n; dist] THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`p0 - x:real^3`; `1`] COMPONENT_LE_NORM) THEN
    MP_TAC(ISPECL [`p0 - x:real^3`; `2`] COMPONENT_LE_NORM) THEN
    UNDISCH_TAC `norm(p0 - x:real^3) < r` THEN
    EXPAND_TAC "p0" THEN
    REWRITE_TAC[DIMINDEX_3; ARITH; VECTOR_SUB_COMPONENT; VECTOR_3] THEN
    SPEC_TAC(`norm(vector[&0;&0;c] - x:real^3)`,`nn:real`) THEN GEN_TAC THEN
    UNDISCH_TAC `r <= &3 / &16` THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN ball(p0,r) ==> (x IN S1 <=> x$3 = (p0:real^3)$3) /\
                                               (x IN S2 <=> x$3 = (p0:real^3)$3)`
  ASSUME_TAC THENL
   [X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    UNDISCH_TAC `(x:real^3) IN ball(p0,r)` THEN REWRITE_TAC[IN_BALL] THEN
    MAP_EVERY UNDISCH_TAC [`r <= r1`; `r <= r2`] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `{x | x IN ball(p0,r) /\ (p0:real^3)$3 < x$3} SUBSET outside S1 /\
                {x | x IN ball(p0,r) /\ (p0:real^3)$3 < x$3} SUBSET outside S2`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC SUBSET_TRANS THENL
     [EXISTS_TAC `{x:real^3 | c < x$3 /\ ~(x IN moi_s35_ttube)}` THEN CONJ_TAC THENL
       [REWRITE_TAC[SUBSET; IN_ELIM_THM; moi_s35_ttube; DE_MORGAN_THM] THEN
        X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN CONJ_TAC THENL
         [UNDISCH_TAC `(p0:real^3)$3 < (x:real^3)$3` THEN ASM_REWRITE_TAC[];
          DISJ1_TAC THEN REWRITE_TAC[REAL_NOT_LE] THEN
          FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
            is_forall(concl th) && can (find_term ((=) `moi_s35_n`)) (concl th))) THEN
          FIRST_ASSUM ACCEPT_TAC];
        MATCH_MP_TAC MOI_S5C_UPPER_NOTUBE THEN ASM_REWRITE_TAC[] THEN
        REPEAT CONJ_TAC THEN
        TRY(UNDISCH_TAC `abs c <= &1 / &512` THEN REAL_ARITH_TAC THEN NO_TAC) THEN
        EXPAND_TAC "S1" THEN ASM_REWRITE_TAC[]];
      EXISTS_TAC `{x:real^3 | c < x$3}` THEN CONJ_TAC THENL
       [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
        UNDISCH_TAC `(p0:real^3)$3 < (x:real^3)$3` THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC MOI_S5C_HALF_OUT THEN EXPAND_TAC "S2" THEN ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`S1:real^3->bool`; `p0:real^3`; `r:real`] MOI_S5C_FLAT_OTHER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    TRY(X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th -> is_forall(concl th) &&
          can (find_term ((=) `S1:real^3->bool`)) (concl th) &&
          can (find_term ((=) `S2:real^3->bool`)) (concl th))) THEN
        ASM_REWRITE_TAC[] THEN SIMP_TAC[]);
    DISCH_THEN(MP_TAC o CONJUNCT1) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC] THEN
  MP_TAC(ISPECL [`S2:real^3->bool`; `p0:real^3`; `r:real`] MOI_S5C_FLAT_OTHER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    TRY(X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th -> is_forall(concl th) &&
          can (find_term ((=) `S1:real^3->bool`)) (concl th) &&
          can (find_term ((=) `S2:real^3->bool`)) (concl th))) THEN
        ASM_REWRITE_TAC[] THEN SIMP_TAC[]);
    DISCH_THEN(MP_TAC o CONJUNCT1) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC] THEN
  REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th ->
    can (find_term ((=) `inside:(real^3->bool)->real^3->bool`)) (concl th) &&
    can (find_term ((=) `ball:real^3#real->real^3->bool`)) (concl th) &&
    not(is_forall(concl th))))) THEN
  ASM_REWRITE_TAC[] THEN SET_TAC[]);;

let MOI_S5C_SQANN_CONNECTED = prove
 (`connected (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
              interval(--vector[&1;&1]:real^2,vector[&1;&1]))`,
  SUBGOAL_THEN
   `interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
    interval(--vector[&1;&1]:real^2,vector[&1;&1]) =
    {x:real^2 | max (abs(x$1)) (abs(x$2)) IN {t | &1 <= t /\ t <= &2}}`
  SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; MOI_S5C_IN_SQANN]; ALL_TAC] THEN
  MATCH_MP_TAC MOI_S5C_NBAND_CONNECTED THEN REWRITE_TAC[IN_ELIM_THM] THEN
  CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN EXISTS_TAC `&1` THEN REAL_ARITH_TAC);;

let MOI_S5C_ANN_CONNECTED = prove
 (`!(a:real^N->bool) j0 j1. pl_annulus_with_ends a j0 j1 ==> connected a`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_annulus_with_ends; pl_homeomorphism; homeomorphism] THEN
  STRIP_TAC THEN FIRST_X_ASSUM(SUBST1_TAC o SYM o check (fun th ->
    try rhs(concl th) = `a:real^N->bool` with Failure _ -> false)) THEN
  MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN
  ASM_REWRITE_TAC[MOI_S5C_SQANN_CONNECTED]);;

let MOI_S5C_SPH_SIDES = prove
 (`!s:real^3->bool.
     pl_sphere 2 s
     ==> closure (outside s) SUBSET outside s UNION s /\
         closure (inside s) SUBSET inside s UNION s /\
         (!t. connected t /\ DISJOINT t s /\ ~(t INTER outside s = {})
              ==> t SUBSET outside s) /\
         (!t. connected t /\ DISJOINT t s /\ ~(t INTER inside s = {})
              ==> t SUBSET inside s)`,
  GEN_TAC THEN DISCH_THEN(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_JB_CLOSURE) THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`inside s:real^3->bool`; `outside s:real^3->bool`]
      OPEN_INTER_CLOSURE_EQ_EMPTY) THEN ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
    MP_TAC(ISPECL [`outside s:real^3->bool`; `inside s:real^3->bool`]
      OPEN_INTER_CLOSURE_EQ_EMPTY) THEN ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
    REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`s:real^3->bool`; `t:real^3->bool`] MOI_S5C_CONNECTED_SIDE) THEN
    ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[DISJOINT_SYM] THEN ASM_REWRITE_TAC[] THEN
    ASM SET_TAC[];
    REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`s:real^3->bool`; `t:real^3->bool`] MOI_S5C_CONNECTED_SIDE) THEN
    ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[DISJOINT_SYM] THEN ASM_REWRITE_TAC[] THEN
    ASM SET_TAC[]]);;

let MOI_S5C_LIFT_CONNECTED = prove
 (`!h s:real^2->bool. connected s ==> connected (IMAGE (moi_s35_lift h) s)`,
  REPEAT STRIP_TAC THEN MP_TAC(SPEC `h:real` MOI_S5C_LIFT_LINEAR) THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC CONTINUOUS_ON_ADD THEN REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
  ASM_SIMP_TAC[LINEAR_CONTINUOUS_ON]);;

let MOI_S5C_PLANAR_RG_PARTS = prove
 (`!j j':real^2->bool.
     pl_sphere 1 j /\ pl_sphere 1 j' /\ j SUBSET inside j'
     ==> connected (moi_s5c_rg j j' DIFF j) /\ j' SUBSET moi_s5c_rg j j' DIFF j /\
         j' UNION inside j' = (j UNION inside j) UNION (moi_s5c_rg j j' DIFF j) /\
         DISJOINT (j UNION inside j) (moi_s5c_rg j j' DIFF j) /\
         connected (moi_s5c_rg j j' DIFF (j UNION j')) /\
         moi_s5c_rg j j' DIFF (j UNION j') = inside j' DIFF (j UNION inside j)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_PLANAR_NEST_FACTS) THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_RG_FACTS) THEN
  DISCH_THEN(fun th -> let cs = CONJUNCTS th in
    STRIP_ASSUME_TAC(MATCH_MP MOI_S5C_ANN_PARTS (el 0 cs))) THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  REWRITE_TAC[moi_s5c_rg] THEN ASM SET_TAC[]);;

let MOI_S5C_ARCH_INSIDE21 = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> moi_s5c_sig1 c h jin jout' A Cout SUBSET
           moi_s5c_sig2 c h jin jin' Cin UNION outside (moi_s5c_sig2 c h jin jin' Cin) /\
         A DIFF IMAGE (moi_s35_lift c) jin SUBSET outside (moi_s5c_sig2 c h jin jin' Cin) /\
         Cout SUBSET outside (moi_s5c_sig2 c h jin jin' Cin) /\
         IMAGE (moi_s35_lift (c - h)) (moi_s5c_rg jin' jout' DIFF jin') SUBSET
           outside (moi_s5c_sig2 c h jin jin' Cin) /\
         inside (moi_s5c_sig2 c h jin jin' Cin) SUBSET inside (moi_s5c_sig1 c h jin jout' A Cout)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_FACTS2) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_SPHERES) THEN
  FIRST_ASSUM(X_CHOOSE_THEN `r0:real` STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_P0) THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN DISCH_THEN(LABEL_TAC "pts") THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_arch] o
    check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
  SUBGOAL_THEN `pl_sphere 2 (moi_s5c_sig1 c h jin jout' A Cout) /\
                pl_sphere 2 (moi_s5c_sig2 c h jin jin' Cin)` STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[moi_s5c_sig1; moi_s5c_sig2] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ABBREV_TAC `S1 = moi_s5c_sig1 c h jin jout' A Cout` THEN
  ABBREV_TAC `S2 = moi_s5c_sig2 c h jin jin' Cin` THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_SPH_SIDES o
    check (fun th -> concl th = `pl_sphere 2 (S2:real^3->bool)`)) THEN
  SUBGOAL_THEN `{x:real^3 | c < x$3} SUBSET outside S2` ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_HALF_OUT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `A DIFF (IMAGE (moi_s35_lift c) jin UNION IMAGE (moi_s35_lift c) jout)
              SUBSET {x:real^3 | c < x$3}` ASSUME_TAC THENL
   [REWRITE_TAC[SUBSET; IN_DIFF; IN_UNION; IN_ELIM_THM; MOI_S5C_IN_LIFT] THEN
    X_GEN_TAC `x:real^3` THEN
    USE_THEN "pts" (MP_TAC o SPEC `x:real^3` o CONJUNCT1) THEN
    USE_THEN "pts" (MP_TAC o SPEC `x:real^3` o CONJUNCT1 o CONJUNCT2) THEN
    MP_TAC(REAL_ARITH `!a. c <= a ==> a = c \/ c < a`) THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (moi_s35_lift c) jout SUBSET outside (S2:real^3->bool)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `closure(outside (S2:real^3->bool)) DIFF S2` THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_DIFF] THEN X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
      CONJ_TAC THENL
       [MP_TAC(ISPEC `outside (S2:real^3->bool)` CLOSURE_SUBSET) THEN
        MP_TAC(ISPECL [`A:real^3->bool`; `IMAGE (moi_s35_lift c) jin`;
                       `IMAGE (moi_s35_lift c) jout`] MOI_S5C_ANN_ENDS_CLOSURE) THEN
        ASM_REWRITE_TAC[] THEN
        MP_TAC(ISPECL [`A DIFF (IMAGE (moi_s35_lift c) jin UNION IMAGE (moi_s35_lift c) jout)`;
                       `outside (S2:real^3->bool)`] SUBSET_CLOSURE) THEN
        MAP_EVERY UNDISCH_TAC
         [`A DIFF (IMAGE (moi_s35_lift c) jin UNION IMAGE (moi_s35_lift c) jout)
           SUBSET {x:real^3 | c < x$3}`;
          `{x:real^3 | c < x$3} SUBSET outside S2`;
          `(x:real^3) IN IMAGE (moi_s35_lift c) jout`] THEN
        SET_TAC[];
        EXPAND_TAC "S2" THEN
        REWRITE_TAC[moi_s5c_sig2; IN_UNION; MOI_S5C_IN_LIFT] THEN
        UNDISCH_TAC `(x:real^3) IN IMAGE (moi_s35_lift c) jout` THEN
        REWRITE_TAC[MOI_S5C_IN_LIFT] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "pts" MP_TAC THEN ASM_MESON_TAC[]];
      ASM SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `A DIFF IMAGE (moi_s35_lift c) jin SUBSET outside (S2:real^3->bool)`
  ASSUME_TAC THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `Cout SUBSET outside (S2:real^3->bool)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
      is_forall(concl th) && can (find_term ((=) `outside (S2:real^3->bool)`)) (concl th) &&
      can (find_term ((=) `connected:(real^3->bool)->bool`)) (concl th))) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC MOI_S5C_ANN_CONNECTED THEN
      MAP_EVERY EXISTS_TAC [`IMAGE (moi_s35_lift c) jout`;
                            `IMAGE (moi_s35_lift (c - h)) jout'`] THEN
      ASM_REWRITE_TAC[];
      EXPAND_TAC "S2" THEN
      REWRITE_TAC[moi_s5c_sig2; DISJOINT; EXTENSION; IN_INTER; IN_UNION; NOT_IN_EMPTY;
                  MOI_S5C_IN_LIFT] THEN
      USE_THEN "pts" MP_TAC THEN MESON_TAC[];
      MP_TAC(ISPECL [`Cout:real^3->bool`; `IMAGE (moi_s35_lift c) jout`;
                     `IMAGE (moi_s35_lift (c - h)) jout'`] MOI_S5C_ANN_ENDS_SUBSET) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      SUBGOAL_THEN `~(IMAGE (moi_s35_lift c) jout = {})` MP_TAC THENL
       [REWRITE_TAC[IMAGE_EQ_EMPTY] THEN MATCH_MP_TAC MOI_SCD_PL_SPHERE_NONEMPTY THEN
        EXISTS_TAC `1` THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      UNDISCH_TAC `IMAGE (moi_s35_lift c) jout SUBSET outside (S2:real^3->bool)` THEN
      UNDISCH_TAC `IMAGE (moi_s35_lift c) jout SUBSET Cout` THEN SET_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`jin':real^2->bool`; `jout':real^2->bool`] MOI_S5C_PLANAR_RG_PARTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  SUBGOAL_THEN `IMAGE (moi_s35_lift (c - h)) (moi_s5c_rg jin' jout' DIFF jin') SUBSET
                outside (S2:real^3->bool)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
      is_forall(concl th) && can (find_term ((=) `outside (S2:real^3->bool)`)) (concl th) &&
      can (find_term ((=) `connected:(real^3->bool)->bool`)) (concl th))) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC MOI_S5C_LIFT_CONNECTED THEN ASM_REWRITE_TAC[];
      EXPAND_TAC "S2" THEN
      REWRITE_TAC[moi_s5c_sig2; DISJOINT; EXTENSION; IN_INTER; IN_UNION; NOT_IN_EMPTY;
                  MOI_S5C_IN_LIFT] THEN
      X_GEN_TAC `x:real^3` THEN
      DISCH_THEN(CONJUNCTS_THEN2 (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)
        (DISJ_CASES_THEN2 (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)
        (DISJ_CASES_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))) THENL
       [MAP_EVERY UNDISCH_TAC [`(x:real^3)$3 = c - h`; `(x:real^3)$3 = c`; `&0 < h`] THEN
        REAL_ARITH_TAC;
        USE_THEN "pts" (MP_TAC o SPEC `x:real^3` o el 7 o CONJUNCTS) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_TAC] THEN
        UNDISCH_TAC `moi_s5c_proj x IN jin'` THEN
        UNDISCH_TAC `moi_s5c_proj x IN moi_s5c_rg jin' jout' DIFF jin'` THEN SET_TAC[];
        UNDISCH_TAC `DISJOINT (jin' UNION inside jin') (moi_s5c_rg jin' jout' DIFF jin')` THEN
        UNDISCH_TAC `moi_s5c_proj x IN moi_s5c_rg jin' jout' DIFF jin'` THEN
        UNDISCH_TAC `moi_s5c_proj x IN jin' \/ moi_s5c_proj x IN inside jin'` THEN
        SET_TAC[]];
      MP_TAC(ISPECL [`Cout:real^3->bool`; `IMAGE (moi_s35_lift c) jout`;
                     `IMAGE (moi_s35_lift (c - h)) jout'`] MOI_S5C_ANN_ENDS_SUBSET) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      SUBGOAL_THEN `~(IMAGE (moi_s35_lift (c - h)) jout' = {})` MP_TAC THENL
       [REWRITE_TAC[IMAGE_EQ_EMPTY] THEN MATCH_MP_TAC MOI_SCD_PL_SPHERE_NONEMPTY THEN
        EXISTS_TAC `1` THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      MAP_EVERY UNDISCH_TAC [`Cout SUBSET outside (S2:real^3->bool)`;
        `IMAGE (moi_s35_lift (c - h)) jout' SUBSET Cout`;
        `(jout':real^2->bool) SUBSET moi_s5c_rg jin' jout' DIFF jin'`] THEN
      SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (moi_s35_lift c) (jin UNION inside jin) SUBSET (S2:real^3->bool) /\
                IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin') SUBSET S2`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "S2" THEN REWRITE_TAC[moi_s5c_sig2] THEN SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(S1:real^3->bool) SUBSET S2 UNION outside S2` ASSUME_TAC THENL
   [EXPAND_TAC "S1" THEN REWRITE_TAC[moi_s5c_sig1] THEN
    UNDISCH_TAC `jout' UNION inside jout' =
       (jin' UNION inside jin') UNION (moi_s5c_rg jin' jout' DIFF jin')` THEN
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[MOI_S5C_LIFT_UNION] THEN
    MAP_EVERY UNDISCH_TAC [`Cout SUBSET outside (S2:real^3->bool)`;
      `A DIFF IMAGE (moi_s35_lift c) jin SUBSET outside (S2:real^3->bool)`;
      `IMAGE (moi_s35_lift (c - h)) (moi_s5c_rg jin' jout' DIFF jin') SUBSET
       outside (S2:real^3->bool)`;
      `IMAGE (moi_s35_lift c) (jin UNION inside jin) SUBSET (S2:real^3->bool)`;
      `IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin') SUBSET (S2:real^3->bool)`] THEN
    REWRITE_TAC[MOI_S5C_LIFT_UNION] THEN SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_SPH_SIDES o
    check (fun th -> concl th = `pl_sphere 2 (S1:real^3->bool)`)) THEN
  FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
    is_forall(concl th) && can (find_term ((=) `inside (S1:real^3->bool)`)) (concl th) &&
    can (find_term ((=) `connected:(real^3->bool)->bool`)) (concl th))) THEN
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `pl_sphere 2 (S2:real^3->bool)`
      then ACCEPT_TAC(el 2 (CONJUNCTS(MATCH_MP MOI_S5C_JB_CLOSURE th))) else NO_TAC);
    MP_TAC(ISPEC `S2:real^3->bool` INSIDE_INTER_OUTSIDE) THEN
    MP_TAC(ISPEC `S2:real^3->bool` INSIDE_NO_OVERLAP) THEN
    UNDISCH_TAC `(S1:real^3->bool) SUBSET S2 UNION outside S2` THEN SET_TAC[];
    MP_TAC(ISPECL [`vector[&0;&0;c]:real^3`; `r0:real`] MOI_S5C_HALF_BALLS_NONEMPTY) THEN
    ASM_REWRITE_TAC[VECTOR_3] THEN STRIP_TAC THEN
    UNDISCH_TAC `{x | x IN ball(vector[&0;&0;c],r0) /\ x$3 < c} SUBSET
                 inside (S1:real^3->bool) INTER inside S2` THEN
    UNDISCH_TAC `~({x:real^3 | x IN ball(vector[&0;&0;c],r0) /\ x$3 < c} = {})` THEN
    SET_TAC[]]);;


(* ------------------------------------------------------------------------- *)
(* The arch configuration, part 2: the two sides of the flat pieces of      *)
(* the pancake spheres, and the solid torus region V between them.          *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_ARCH_COMPACTS = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> compact A /\ compact Cin /\ compact Cout /\
         compact (IMAGE (moi_s35_lift c) jin) /\ compact (IMAGE (moi_s35_lift c) jout) /\
         compact (IMAGE (moi_s35_lift (c - h)) jin') /\
         compact (IMAGE (moi_s35_lift (c - h)) jout') /\
         compact (IMAGE (moi_s35_lift c) (jin UNION inside jin)) /\
         compact (IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin')) /\
         compact (IMAGE (moi_s35_lift (c - h)) (jout' UNION inside jout')) /\
         open (inside jin) /\ open (inside jin') /\ open (inside jout') /\
         open (inside jout' DIFF (jin' UNION inside jin'))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[moi_s5c_arch] THEN STRIP_TAC THEN
  SUBGOAL_THEN `!j:real^2->bool. pl_sphere 1 j
                ==> compact j /\ compact (j UNION inside j) /\ open (inside j)`
  ASSUME_TAC THENL
   [GEN_TAC THEN DISCH_THEN(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_SPHERE1_COMPACT) THEN
    ASM_SIMP_TAC[OPEN_INSIDE; COMPACT_IMP_CLOSED];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THEN
  TRY(FIRST_ASSUM(fun th -> if MOI_S5C_HEAD "pl_annulus_with_ends" th &&
        (can (find_term ((=) `A:real^3->bool`)) (concl th) ||
         can (find_term ((=) `Cin:real^3->bool`)) (concl th) ||
         can (find_term ((=) `Cout:real^3->bool`)) (concl th))
      then ACCEPT_TAC(CONJUNCT1(MATCH_MP MOI_S5C_ANN_COMPACT th)) else NO_TAC) THEN NO_TAC) THEN
  TRY(MATCH_MP_TAC MOI_S5C_LIFT_COMPACT THEN ASM_MESON_TAC[] THEN NO_TAC) THEN
  TRY(MATCH_MP_TAC OPEN_DIFF THEN CONJ_TAC THENL
   [ASM_MESON_TAC[]; ASM_MESON_TAC[COMPACT_IMP_CLOSED]] THEN NO_TAC) THEN
  ASM_MESON_TAC[]);;

let MOI_S5C_ARCH_DIN_SIDE = prove
 (`!c h jin jout jin' jout' A Cin Cout z.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout /\
     z IN IMAGE (moi_s35_lift c) (inside jin)
     ==> ?r. &0 < r /\
             (!x. x IN ball(z,r) ==> (x IN moi_s5c_sig1 c h jin jout' A Cout <=> x$3 = c)) /\
             (!x. x IN ball(z,r) ==> (x IN moi_s5c_sig2 c h jin jin' Cin <=> x$3 = c)) /\
             {x | x IN ball(z,r) /\ x$3 < c} SUBSET inside (moi_s5c_sig2 c h jin jin' Cin) /\
             {x | x IN ball(z,r) /\ c < x$3} SUBSET outside (moi_s5c_sig1 c h jin jout' A Cout) /\
             {x | x IN ball(z,r) /\ c < x$3} SUBSET outside (moi_s5c_sig2 c h jin jin' Cin)`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
  REWRITE_TAC[MOI_S5C_IN_LIFT] THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_FACTS2) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_COMPACTS) THEN
  FIRST_ASSUM(ASSUME_TAC o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
    MATCH_MP MOI_S5C_ARCH_INSIDE21) THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_arch] o
    check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
  SUBGOAL_THEN `~(moi_s5c_proj z IN jin) /\ ~(moi_s5c_proj z IN jout)` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`jin:real^2->bool`; `jout:real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `moi_s5c_proj z IN inside jin` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((z:real^3) IN A) /\ ~(z IN Cout) /\ ~(z IN Cin)` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_POINTS o
      check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
    MAP_EVERY UNDISCH_TAC [`(z:real^3)$3 = c`; `~(moi_s5c_proj z IN jin)`;
                           `~(moi_s5c_proj z IN jout)`] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `S1 = moi_s5c_sig1 c h jin jout' A Cout` THEN
  ABBREV_TAC `S2 = moi_s5c_sig2 c h jin jin' Cin` THEN
  SUBGOAL_THEN `(z:real^3) IN S1 /\ (z:real^3) IN S2` STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["S1"; "S2"] THEN
    REWRITE_TAC[moi_s5c_sig1; moi_s5c_sig2; IN_UNION; MOI_S5C_IN_LIFT] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`A UNION Cout UNION IMAGE (moi_s35_lift (c - h)) (jout' UNION inside jout') UNION
                  IMAGE (moi_s35_lift c) jin`; `inside (jin:real^2->bool)`; `c:real`;
                 `z:real^3`] MOI_S5C_FLAT_LEVEL) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC) THEN
      ASM_SIMP_TAC[COMPACT_IMP_CLOSED];
      REWRITE_TAC[IN_UNION; MOI_S5C_IN_LIFT; DE_MORGAN_THM] THEN
      ASM_REWRITE_TAC[] THEN UNDISCH_TAC `&0 < h` THEN REAL_ARITH_TAC];
    SUBGOAL_THEN
     `(S1:real^3->bool) =
      (A UNION Cout UNION IMAGE (moi_s35_lift (c - h)) (jout' UNION inside jout') UNION
       IMAGE (moi_s35_lift c) jin) UNION IMAGE (moi_s35_lift c) (inside jin)`
    (fun th -> REWRITE_TAC[SYM th]) THENL
     [EXPAND_TAC "S1" THEN
      REWRITE_TAC[moi_s5c_sig1; MOI_S5C_LIFT_UNION] THEN SET_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `r1:real` STRIP_ASSUME_TAC)]] THEN
  MP_TAC(ISPECL [`Cin UNION IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin') UNION
                  IMAGE (moi_s35_lift c) jin`; `inside (jin:real^2->bool)`; `c:real`;
                 `z:real^3`] MOI_S5C_FLAT_LEVEL) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC) THEN
      ASM_SIMP_TAC[COMPACT_IMP_CLOSED];
      REWRITE_TAC[IN_UNION; MOI_S5C_IN_LIFT; DE_MORGAN_THM] THEN
      ASM_REWRITE_TAC[] THEN UNDISCH_TAC `&0 < h` THEN REAL_ARITH_TAC];
    SUBGOAL_THEN
     `(S2:real^3->bool) =
      (Cin UNION IMAGE (moi_s35_lift (c - h)) (jin' UNION inside jin') UNION
       IMAGE (moi_s35_lift c) jin) UNION IMAGE (moi_s35_lift c) (inside jin)`
    (fun th -> REWRITE_TAC[SYM th]) THENL
     [EXPAND_TAC "S2" THEN
      REWRITE_TAC[moi_s5c_sig2; MOI_S5C_LIFT_UNION] THEN SET_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `r2:real` STRIP_ASSUME_TAC)]] THEN
  EXISTS_TAC `min r1 r2` THEN
  CONJ_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`&0 < r1`; `&0 < r2`] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `r = min r1 r2` THEN
  SUBGOAL_THEN `&0 < r /\ r <= r1 /\ r <= r2` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "r" THEN MAP_EVERY UNDISCH_TAC [`&0 < r1`; `&0 < r2`] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN ball(z,r) ==> (x IN S1 <=> x$3 = (z:real^3)$3) /\
                                               (x IN S2 <=> x$3 = (z:real^3)$3)`
  ASSUME_TAC THENL
   [X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    UNDISCH_TAC `(x:real^3) IN ball(z,r)` THEN REWRITE_TAC[IN_BALL] THEN
    MAP_EVERY UNDISCH_TAC [`r <= r1`; `r <= r2`] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `{x | x IN ball(z,r) /\ (z:real^3)$3 < x$3} SUBSET outside S2`
  ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `{x:real^3 | c < x$3}` THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
      UNDISCH_TAC `(z:real^3)$3 < (x:real^3)$3` THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC MOI_S5C_HALF_OUT THEN EXPAND_TAC "S2" THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`S2:real^3->bool`; `z:real^3`; `r:real`] MOI_S5C_FLAT_OTHER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    TRY(X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th -> is_forall(concl th) &&
          can (find_term ((=) `S1:real^3->bool`)) (concl th) &&
          can (find_term ((=) `S2:real^3->bool`)) (concl th))) THEN
        ASM_REWRITE_TAC[] THEN SIMP_TAC[]);
    DISCH_THEN(MP_TAC o CONJUNCT1) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC] THEN
  SUBGOAL_THEN `{x | x IN ball(z,r) /\ x$3 < (z:real^3)$3} SUBSET inside S1` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `inside (S2:real^3->bool)` THEN
    CONJ_TAC THENL
     [FIRST_X_ASSUM(fun th -> if can (find_term ((=) `inside (S2:real^3->bool)`)) (concl th) &&
         can (find_term ((=) `ball:real^3#real->real^3->bool`)) (concl th) &&
         not(is_forall(concl th)) then MP_TAC th else NO_TAC) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`S1:real^3->bool`; `z:real^3`; `r:real`] MOI_S5C_FLAT_OTHER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    TRY(X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th -> is_forall(concl th) &&
          can (find_term ((=) `S1:real^3->bool`)) (concl th) &&
          can (find_term ((=) `S2:real^3->bool`)) (concl th))) THEN
        ASM_REWRITE_TAC[] THEN SIMP_TAC[]);
    DISCH_THEN(MP_TAC o CONJUNCT1) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC] THEN
  REPEAT CONJ_TAC THEN
  TRY(X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th -> is_forall(concl th) &&
        can (find_term ((=) `S1:real^3->bool`)) (concl th) &&
        can (find_term ((=) `S2:real^3->bool`)) (concl th))) THEN
      ASM_REWRITE_TAC[] THEN SIMP_TAC[] THEN NO_TAC) THEN
  REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th ->
    (can (find_term ((=) `inside (S2:real^3->bool)`)) (concl th) ||
     can (find_term ((=) `inside (S1:real^3->bool)`)) (concl th) ||
     can (find_term ((=) `outside (S1:real^3->bool)`)) (concl th) ||
     can (find_term ((=) `outside (S2:real^3->bool)`)) (concl th)) &&
    can (find_term ((=) `ball:real^3#real->real^3->bool`)) (concl th) &&
    not(is_forall(concl th))))) THEN
  ASM_REWRITE_TAC[] THEN SET_TAC[]);;

