  ABBREV_TAC `r = min r1 r2` THEN
  SUBGOAL_THEN `&0 < r /\ r <= r1 /\ r <= r2` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "r" THEN MAP_EVERY UNDISCH_TAC [`&0 < r1`; `&0 < r2`] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN ball(z,r) ==> (x IN S1 <=> x$3 = (z:real^3)$3) /\
                                               (x IN S2 <=> x$3 = (z:real^3)$3)`
  ASSUME_TAC THENL
   [X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    UNDISCH_TAC `(x:real^3) IN ball(z,r)` THEN REWRITE_TAC[IN_BALL] THEN
    MAP_EVERY UNDISCH_TAC [`r <= r1`; `r <= r2`] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `{x | x IN ball(z,r) /\ x$3 < (z:real^3)$3} SUBSET outside S1 /\
                {x | x IN ball(z,r) /\ x$3 < (z:real^3)$3} SUBSET outside S2`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `{x:real^3 | x$3 < c - h}` THEN
    (CONJ_TAC THENL
      [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
       UNDISCH_TAC `(x:real^3)$3 < (z:real^3)$3` THEN ASM_REWRITE_TAC[];
       MATCH_MP_TAC MOI_S5C_HALF_OUT_LOW THEN
       MAP_EVERY EXPAND_TAC ["S1"; "S2"] THEN ASM_REWRITE_TAC[]]);
    ALL_TAC] THEN
  MP_TAC(ISPECL [`S2:real^3->bool`; `z:real^3`; `r:real`] MOI_S5C_FLAT_OTHER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    TRY(X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th -> is_forall(concl th) &&
          can (find_term ((=) `S1:real^3->bool`)) (concl th) &&
          can (find_term ((=) `S2:real^3->bool`)) (concl th))) THEN
        ASM_REWRITE_TAC[] THEN SIMP_TAC[]);
    DISCH_THEN(MP_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC] THEN
  REPEAT CONJ_TAC THEN
  TRY(X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th -> is_forall(concl th) &&
        can (find_term ((=) `S1:real^3->bool`)) (concl th) &&
        can (find_term ((=) `S2:real^3->bool`)) (concl th))) THEN
      ASM_REWRITE_TAC[] THEN SIMP_TAC[] THEN NO_TAC) THEN
  REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th ->
    (can (find_term ((=) `inside (S2:real^3->bool)`)) (concl th) ||
     can (find_term ((=) `outside (S1:real^3->bool)`)) (concl th) ||
     can (find_term ((=) `outside (S2:real^3->bool)`)) (concl th)) &&
    can (find_term ((=) `ball:real^3#real->real^3->bool`)) (concl th) &&
    not(is_forall(concl th))))) THEN
  ASM_REWRITE_TAC[] THEN SET_TAC[]);;

let moi_s5c_npl = new_definition
 `moi_s5c_npl h (jin':real^2->bool) jout' = IMAGE (moi_s35_lift h) (moi_s5c_rg jin' jout')`;;

let moi_s5c_tor = new_definition
 `moi_s5c_tor c h (jin':real^2->bool) jout' (A:real^3->bool) Cin Cout =
    A UNION Cin UNION Cout UNION moi_s5c_npl (c - h) jin' jout'`;;

let MOI_S5C_RG_SPLIT = prove
 (`!j j':real^2->bool.
     pl_sphere 1 j /\ pl_sphere 1 j' /\ j SUBSET inside j'
     ==> moi_s5c_rg j j' = (inside j' DIFF (j UNION inside j)) UNION j UNION j' /\
         j' UNION inside j' = (inside j' DIFF (j UNION inside j)) UNION j' UNION
                              (j UNION inside j)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_PLANAR_NEST_FACTS) THEN
  REWRITE_TAC[moi_s5c_rg] THEN ASM SET_TAC[]);;

let MOI_S5C_ARCH_N_SIDE = prove
 (`!c h jin jout jin' jout' A Cin Cout z.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout /\
     z IN IMAGE (moi_s35_lift (c - h)) (inside jout' DIFF (jin' UNION inside jin'))
     ==> ?r. &0 < r /\
             (!x. x IN ball(z,r) ==> (x IN moi_s5c_sig1 c h jin jout' A Cout <=> x$3 = c - h)) /\
             (!x. x IN ball(z,r)
                  ==> (x IN moi_s5c_tor c h jin' jout' A Cin Cout <=> x$3 = c - h)) /\
             ball(z,r) SUBSET outside (moi_s5c_sig2 c h jin jin' Cin) /\
             {x | x IN ball(z,r) /\ c - h < x$3} SUBSET inside (moi_s5c_sig1 c h jin jout' A Cout) /\
             {x | x IN ball(z,r) /\ x$3 < c - h} SUBSET outside (moi_s5c_sig1 c h jin jout' A Cout)`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
  REWRITE_TAC[MOI_S5C_IN_LIFT; IN_DIFF; IN_UNION; DE_MORGAN_THM] THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_FACTS2) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_COMPACTS) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_arch] o
    check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
  SUBGOAL_THEN `~(moi_s5c_proj z IN jout')` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`jin':real^2->bool`; `jout':real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `moi_s5c_proj z IN inside jout'` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((z:real^3) IN A) /\ ~(z IN Cout) /\ ~(z IN Cin)` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_POINTS o
      check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
    MAP_EVERY UNDISCH_TAC [`(z:real^3)$3 = c - h`; `~(moi_s5c_proj z IN jin')`;
                           `~(moi_s5c_proj z IN jout')`] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`jin':real^2->bool`; `jout':real^2->bool`] MOI_S5C_RG_SPLIT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  ABBREV_TAC `S1 = moi_s5c_sig1 c h jin jout' A Cout` THEN
  ABBREV_TAC `S2 = moi_s5c_sig2 c h jin jin' Cin` THEN
  ABBREV_TAC `Tr = moi_s5c_tor c h jin' jout' A Cin Cout` THEN
  ABBREV_TAC `P = inside jout' DIFF (jin' UNION inside (jin':real^2->bool))` THEN
  SUBGOAL_THEN `(z:real^3) IN S1 /\ ~((z:real^3) IN S2)` STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["S1"; "S2"] THEN
    REWRITE_TAC[moi_s5c_sig1; moi_s5c_sig2; IN_UNION; MOI_S5C_IN_LIFT] THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `&0 < h` THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`A UNION Cout UNION IMAGE (moi_s35_lift c) (jin UNION inside jin) UNION
                  IMAGE (moi_s35_lift (c - h)) (jout' UNION jin' UNION inside jin')`;
                 `P:real^2->bool`; `c - h`; `z:real^3`] MOI_S5C_FLAT_LEVEL) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC) THEN
      ASM_SIMP_TAC[COMPACT_IMP_CLOSED] THEN
      ONCE_REWRITE_TAC[MOI_S5C_LIFT_UNION] THEN MATCH_MP_TAC CLOSED_UNION THEN
      ASM_SIMP_TAC[COMPACT_IMP_CLOSED];
      CONJ_TAC THENL
       [REWRITE_TAC[IN_UNION; MOI_S5C_IN_LIFT; DE_MORGAN_THM] THEN
        ASM_REWRITE_TAC[] THEN TRY DISJ1_TAC THEN UNDISCH_TAC `&0 < h` THEN REAL_ARITH_TAC;
        EXPAND_TAC "P" THEN ASM_REWRITE_TAC[IN_DIFF; IN_UNION]]];
    SUBGOAL_THEN
     `(S1:real^3->bool) =
      (A UNION Cout UNION IMAGE (moi_s35_lift c) (jin UNION inside jin) UNION
       IMAGE (moi_s35_lift (c - h)) (jout' UNION jin' UNION inside jin')) UNION
      IMAGE (moi_s35_lift (c - h)) P`
    (fun th -> REWRITE_TAC[SYM th]) THENL
     [EXPAND_TAC "S1" THEN REWRITE_TAC[moi_s5c_sig1] THEN
      REWRITE_TAC[ASSUME `jout' UNION inside jout' =
                          (P:real^2->bool) UNION jout' UNION (jin' UNION inside jin')`] THEN
      REWRITE_TAC[MOI_S5C_LIFT_UNION] THEN SET_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `r1:real` STRIP_ASSUME_TAC)]] THEN
  MP_TAC(ISPECL [`A UNION Cin UNION Cout UNION IMAGE (moi_s35_lift (c - h)) (jin' UNION jout')`;
                 `P:real^2->bool`; `c - h`; `z:real^3`] MOI_S5C_FLAT_LEVEL) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC) THEN
      ASM_SIMP_TAC[COMPACT_IMP_CLOSED] THEN
      REWRITE_TAC[MOI_S5C_LIFT_UNION] THEN MATCH_MP_TAC CLOSED_UNION THEN
      ASM_SIMP_TAC[COMPACT_IMP_CLOSED];
      CONJ_TAC THENL
       [REWRITE_TAC[IN_UNION; MOI_S5C_IN_LIFT; DE_MORGAN_THM] THEN ASM_REWRITE_TAC[];
        EXPAND_TAC "P" THEN ASM_REWRITE_TAC[IN_DIFF; IN_UNION]]];
    SUBGOAL_THEN
     `(Tr:real^3->bool) =
      (A UNION Cin UNION Cout UNION IMAGE (moi_s35_lift (c - h)) (jin' UNION jout')) UNION
      IMAGE (moi_s35_lift (c - h)) P`
    (fun th -> REWRITE_TAC[SYM th]) THENL
     [EXPAND_TAC "Tr" THEN REWRITE_TAC[moi_s5c_tor; moi_s5c_npl] THEN
      REWRITE_TAC[ASSUME `moi_s5c_rg jin' jout' = (P:real^2->bool) UNION jin' UNION jout'`] THEN
      REWRITE_TAC[MOI_S5C_LIFT_UNION] THEN SET_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `r3:real` STRIP_ASSUME_TAC)]] THEN
  SUBGOAL_THEN `?r2. &0 < r2 /\ ball(z:real^3,r2) INTER S2 = {}` STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `closed (S2:real^3->bool)` MP_TAC THENL
     [MATCH_MP_TAC COMPACT_IMP_CLOSED THEN MATCH_MP_TAC BOUNDED_CLOSED_IMP_COMPACT THEN
      ASM_REWRITE_TAC[] THEN EXPAND_TAC "S2" THEN REWRITE_TAC[moi_s5c_sig2] THEN
      REPEAT(MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC) THEN ASM_SIMP_TAC[COMPACT_IMP_CLOSED];
      ALL_TAC] THEN
    REWRITE_TAC[closed; open_def; IN_DIFF; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPEC `z:real^3`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `e:real` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `e:real` THEN ASM_REWRITE_TAC[EXTENSION; IN_INTER; IN_BALL; NOT_IN_EMPTY] THEN
    ASM_MESON_TAC[DIST_SYM];
    ALL_TAC] THEN
  EXISTS_TAC `min r1 (min r2 r3)` THEN
  CONJ_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`&0 < r1`; `&0 < r2`; `&0 < r3`] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `r = min r1 (min r2 r3)` THEN
  SUBGOAL_THEN `&0 < r /\ r <= r1 /\ r <= r2 /\ r <= r3` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "r" THEN MAP_EVERY UNDISCH_TAC [`&0 < r1`; `&0 < r2`; `&0 < r3`] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN ball(z,r) ==> x IN ball(z,r1) /\ x IN ball(z,r2) /\
                                               x IN ball(z,r3)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_BALL] THEN MAP_EVERY UNDISCH_TAC [`r <= r1`; `r <= r2`; `r <= r3`] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN ball(z,r) ==> (x IN S1 <=> x$3 = (z:real^3)$3)`
  ASSUME_TAC THENL
   [X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> is_forall(concl th) &&
      can (find_term ((=) `S1:real^3->bool`)) (concl th))) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{x | x IN ball(z,r) /\ x$3 < (z:real^3)$3} SUBSET outside S1 /\
                {x | x IN ball(z,r) /\ x$3 < (z:real^3)$3} SUBSET outside S2`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `{x:real^3 | x$3 < c - h}` THEN
    (CONJ_TAC THENL
      [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
       UNDISCH_TAC `(x:real^3)$3 < (z:real^3)$3` THEN ASM_REWRITE_TAC[];
       MATCH_MP_TAC MOI_S5C_HALF_OUT_LOW THEN
       MAP_EVERY EXPAND_TAC ["S1"; "S2"] THEN ASM_REWRITE_TAC[]]);
    ALL_TAC] THEN
  MP_TAC(ISPECL [`S1:real^3->bool`; `z:real^3`; `r:real`] MOI_S5C_FLAT_OTHER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXPAND_TAC "S1" THEN ASM_REWRITE_TAC[];
    DISCH_THEN(MP_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC] THEN
  SUBGOAL_THEN `ball(z:real^3,r) SUBSET outside S2` ASSUME_TAC THENL
   [SUBGOAL_THEN `pl_sphere 2 (S2:real^3->bool)` MP_TAC THENL
     [EXPAND_TAC "S2" THEN FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_SPHERES o
        check (MOI_S5C_HEAD "moi_s5c_arch")) THEN SIMP_TAC[moi_s5c_sig2];
      ALL_TAC] THEN
    DISCH_THEN(MP_TAC o el 2 o CONJUNCTS o MATCH_MP MOI_S5C_SPH_SIDES) THEN
    DISCH_THEN MATCH_MP_TAC THEN REWRITE_TAC[CONNECTED_BALL] THEN CONJ_TAC THENL
     [UNDISCH_TAC `ball(z:real^3,r2) INTER S2 = {}` THEN
      MP_TAC(ISPECL [`z:real^3`; `r:real`; `r2:real`] SUBSET_BALL) THEN
      ASM_REWRITE_TAC[] THEN SET_TAC[];
      MP_TAC(MATCH_MP MOI_S5C_HALF_BALLS_NONEMPTY (ASSUME `&0 < r`)) THEN
      UNDISCH_TAC `{x | x IN ball(z,r) /\ x$3 < (z:real^3)$3} SUBSET outside S2` THEN
      SET_TAC[]];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THEN
  TRY(X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th -> is_forall(concl th) &&
        can (find_term ((=) `S1:real^3->bool`)) (concl th) &&
        can (find_term ((=) `ball(z:real^3,r)`)) (concl th))) THEN
      ASM_REWRITE_TAC[] THEN SIMP_TAC[] THEN NO_TAC) THEN
  TRY(X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> is_forall(concl th) &&
        can (find_term ((=) `Tr:real^3->bool`)) (concl th))) THEN
      ASM_MESON_TAC[] THEN NO_TAC) THEN
  REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th ->
    (can (find_term ((=) `inside (S1:real^3->bool)`)) (concl th) ||
     can (find_term ((=) `outside (S1:real^3->bool)`)) (concl th) ||
     can (find_term ((=) `outside (S2:real^3->bool)`)) (concl th)) &&
    can (find_term ((=) `ball:real^3#real->real^3->bool`)) (concl th) &&
    not(is_forall(concl th))))) THEN
  ASM_REWRITE_TAC[] THEN SET_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The arch configuration, part 3: the region V between the pancake         *)
(* spheres (inside sig1, outside sig2) is open, connected and nonempty, it  *)
(* lies in the open tube, misses the torus, and its closure is V UNION tor. *)
(* ------------------------------------------------------------------------- *)

(* Open sets inside closed level or square conditions satisfy the strict   *)
(* conditions.                                                               *)

let MOI_S5C_OPEN_LEVEL_STRICT = prove
 (`!s:real^3->bool a b.
     open s
     ==> ((!x. x IN s ==> a <= x$3) ==> (!x. x IN s ==> a < x$3)) /\
         ((!x. x IN s ==> x$3 <= b) ==> (!x. x IN s ==> x$3 < b))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN CONJ_TAC THEN DISCH_TAC THEN
  X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
  MP_TAC(SPEC `x:real^3` (GEN_REWRITE_RULE I [OPEN_CONTAINS_BALL]
    (ASSUME `open(s:real^3->bool)`))) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `e:real` STRIP_ASSUME_TAC) THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `x - (e / &2) % basis 3:real^3`);
    FIRST_X_ASSUM(MP_TAC o SPEC `x + (e / &2) % basis 3:real^3`)] THEN
  (ANTS_TAC THENL
    [UNDISCH_TAC `ball(x:real^3,e) SUBSET s` THEN REWRITE_TAC[SUBSET] THEN
     DISCH_THEN MATCH_MP_TAC THEN
     REWRITE_TAC[IN_BALL; NORM_ARITH `dist(x:real^N,x - y) = norm y /\
                                      dist(x:real^N,x + y) = norm y`] THEN
     SIMP_TAC[NORM_MUL; NORM_BASIS; DIMINDEX_3; ARITH] THEN
     UNDISCH_TAC `&0 < e` THEN REAL_ARITH_TAC;
     SIMP_TAC[VECTOR_SUB_COMPONENT; VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT;
              BASIS_COMPONENT; DIMINDEX_3; ARITH] THEN
     UNDISCH_TAC `&0 < e` THEN REAL_ARITH_TAC]));;

let MOI_S5C_OPEN_N_STRICT = prove
 (`!s:real^3->bool a.
     open s /\ &0 < a
     ==> ((!x. x IN s ==> moi_s35_n x <= a) ==> (!x. x IN s ==> moi_s35_n x < a)) /\
         ((!x. x IN s ==> a <= moi_s35_n x) ==> (!x. x IN s ==> a < moi_s35_n x))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!x:real^3. x IN s
      ==> ?u. &0 < u /\ u <= &1 / &2 /\
              x + u % vector[x$1; x$2; &0] IN s /\ x - u % vector[x$1; x$2; &0] IN s`
  (LABEL_TAC "sc") THENL
   [X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
    MP_TAC(SPEC `x:real^3` (GEN_REWRITE_RULE I [OPEN_CONTAINS_BALL]
      (ASSUME `open(s:real^3->bool)`))) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `e:real` STRIP_ASSUME_TAC) THEN
    ABBREV_TAC `w = vector[(x:real^3)$1; x$2; &0]:real^3` THEN
    SUBGOAL_THEN `norm(w:real^3) <= norm(x:real^3)` ASSUME_TAC THENL
     [EXPAND_TAC "w" THEN REWRITE_TAC[NORM_LE; DOT_3; VECTOR_3] THEN
      MP_TAC(SPEC `(x:real^3)$3` REAL_LE_SQUARE) THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPEC `x:real^3` NORM_POS_LE) THEN DISCH_TAC THEN
    EXISTS_TAC `min (&1 / &2) (e / (&2 * (norm(x:real^3) + &1)))` THEN
    SUBGOAL_THEN `&0 < e / (&2 * (norm(x:real^3) + &1)) /\
                  e / (&2 * (norm(x:real^3) + &1)) * (norm x + &1) = e / &2`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LT_DIV THEN UNDISCH_TAC `&0 < e` THEN
        UNDISCH_TAC `&0 <= norm(x:real^3)` THEN REAL_ARITH_TAC;
        MATCH_MP_TAC(REAL_FIELD `&0 < n ==> e / (&2 * n) * n = e / &2`) THEN
        UNDISCH_TAC `&0 <= norm(x:real^3)` THEN REAL_ARITH_TAC];
      ALL_TAC] THEN
    ABBREV_TAC `u = min (&1 / &2) (e / (&2 * (norm(x:real^3) + &1)))` THEN
    SUBGOAL_THEN `&0 < u /\ u <= &1 / &2 /\ u * (norm(x:real^3) + &1) < e`
    STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "u" THEN REPEAT CONJ_TAC THENL
       [UNDISCH_TAC `&0 < e / (&2 * (norm(x:real^3) + &1))` THEN REAL_ARITH_TAC;
        REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_LET_TRANS THEN
        EXISTS_TAC `e / (&2 * (norm(x:real^3) + &1)) * (norm x + &1)` THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC REAL_LE_RMUL THEN
          UNDISCH_TAC `&0 <= norm(x:real^3)` THEN REAL_ARITH_TAC;
          ASM_REWRITE_TAC[] THEN UNDISCH_TAC `&0 < e` THEN REAL_ARITH_TAC]];
      ALL_TAC] THEN
    SUBGOAL_THEN `norm(u % w:real^3) < e` ASSUME_TAC THENL
     [REWRITE_TAC[NORM_MUL] THEN
      MATCH_MP_TAC REAL_LET_TRANS THEN EXISTS_TAC `u * (norm(x:real^3) + &1)` THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `abs u = u` SUBST1_TAC THENL
       [UNDISCH_TAC `&0 < u` THEN REAL_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN
      UNDISCH_TAC `norm(w:real^3) <= norm(x:real^3)` THEN UNDISCH_TAC `&0 < u` THEN
      REAL_ARITH_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `ball(x:real^3,e) SUBSET s` THEN REWRITE_TAC[SUBSET] THEN
    DISCH_TAC THEN CONJ_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    REWRITE_TAC[IN_BALL; NORM_ARITH `dist(x:real^N,x - y) = norm y /\
                                     dist(x:real^N,x + y) = norm y`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x:real^3 u. &0 < u /\ u <= &1 / &2
       ==> moi_s35_n (x + u % vector[x$1; x$2; &0]) = (&1 + u) * moi_s35_n x /\
           moi_s35_n (x - u % vector[x$1; x$2; &0]) = (&1 - u) * moi_s35_n x`
  (LABEL_TAC "nn") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[moi_s35_n; VECTOR_ADD_COMPONENT; VECTOR_SUB_COMPONENT;
                VECTOR_MUL_COMPONENT; VECTOR_3] THEN
    REWRITE_TAC[REAL_ARITH `x + u * x = (&1 + u) * x /\ x - u * x = (&1 - u) * x`] THEN
    REWRITE_TAC[REAL_ABS_MUL] THEN
    SUBGOAL_THEN `abs(&1 + u) = &1 + u /\ abs(&1 - u) = &1 - u`
      (fun th -> REWRITE_TAC[th]) THENL
     [MAP_EVERY UNDISCH_TAC [`&0 < u`; `u <= &1 / &2`] THEN REAL_ARITH_TAC; ALL_TAC] THEN
    CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_REAL_MAX_LMUL THEN
    MAP_EVERY UNDISCH_TAC [`&0 < u`; `u <= &1 / &2`] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  CONJ_TAC THEN DISCH_TAC THEN X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
  USE_THEN "sc" (X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC o
    C MATCH_MP (ASSUME `(x:real^3) IN s`)) THEN
  USE_THEN "nn" (STRIP_ASSUME_TAC o C MATCH_MP
    (CONJ (ASSUME `&0 < u`) (ASSUME `u <= &1 / &2`)) o SPECL [`x:real^3`; `u:real`]) THEN
  (SUBGOAL_THEN `&0 <= moi_s35_n x` ASSUME_TAC THENL
    [REWRITE_TAC[moi_s35_n] THEN REAL_ARITH_TAC; ALL_TAC]) THEN
  (SUBGOAL_THEN `&0 <= u * moi_s35_n x /\ &0 < u * a` STRIP_ASSUME_TAC THENL
    [CONJ_TAC THENL [MATCH_MP_TAC REAL_LE_MUL; MATCH_MP_TAC REAL_LT_MUL] THEN
     MAP_EVERY UNDISCH_TAC [`&0 < u`; `&0 <= moi_s35_n x`; `&0 < a`] THEN REAL_ARITH_TAC;
     ALL_TAC]) THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `x + u % vector[(x:real^3)$1; x$2; &0]`);
    FIRST_X_ASSUM(MP_TAC o SPEC `x - u % vector[(x:real^3)$1; x$2; &0]`)] THEN
  ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `moi_s35_n x = a` THEN ASM_REWRITE_TAC[] THEN
  REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th ->
    not(is_forall(concl th)) &&
    not(can (find_term ((=) `s:real^3->bool`)) (concl th))))) THEN
  REAL_ARITH_TAC);;

(* The k-th conjunct (from 0) of the arch configuration.                     *)

let MOI_S5C_ARCH_CONJ (k:int) (th:thm) =
  el k (CONJUNCTS (REWRITE_RULE[moi_s5c_arch] th));;

(* Two PL spheres, the inside of the second in the inside of the first:     *)
(* the second lies in the closed inside of the first; levels of insides.    *)

let MOI_S5C_TWO_SPH_LEVELS = prove
 (`!S1 S2:real^3->bool c h.
     pl_sphere 2 S1 /\ pl_sphere 2 S2 /\ inside S2 SUBSET inside S1 /\
     abs c <= &1 / &512 /\
     (!x. x IN S2 ==> c - h <= x$3 /\ x$3 <= c) /\ (!x. x IN S1 ==> c - h <= x$3) /\
     (!x. x IN S1 /\ c < x$3 ==> x IN moi_s35_ttube)
     ==> S2 SUBSET S1 UNION inside S1 /\
         (!x. x IN inside S2 ==> c - h < x$3 /\ x$3 < c) /\
         (!x. x IN inside S1 ==> c - h < x$3 /\ x$3 < &1 / &32)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP MOI_S5C_JB_CLOSURE (ASSUME `pl_sphere 2 (S1:real^3->bool)`)) THEN
  MP_TAC(MATCH_MP MOI_S5C_JB_CLOSURE (ASSUME `pl_sphere 2 (S2:real^3->bool)`)) THEN
  SUBGOAL_THEN `bounded(S1:real^3->bool) /\ bounded(S2:real^3->bool)` STRIP_ASSUME_TAC THENL
   [MP_TAC(MATCH_MP MOI_S5C_PLSPH_JB (ASSUME `pl_sphere 2 (S1:real^3->bool)`)) THEN
    MP_TAC(MATCH_MP MOI_S5C_PLSPH_JB (ASSUME `pl_sphere 2 (S2:real^3->bool)`)) THEN
    SIMP_TAC[COMPACT_IMP_BOUNDED];
    ALL_TAC] THEN
  DISCH_THEN(STRIP_ASSUME_TAC) THEN DISCH_THEN(STRIP_ASSUME_TAC) THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_UNION] THEN X_GEN_TAC `y:real^3` THEN DISCH_TAC THEN
    ASM_CASES_TAC `(y:real^3) IN S1` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `outside S1 INTER closure(inside S2) = {}:real^3->bool` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`outside S1:real^3->bool`; `inside S2:real^3->bool`]
        OPEN_INTER_CLOSURE_EQ_EMPTY) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      MAP_EVERY UNDISCH_TAC [`inside S2 SUBSET inside (S1:real^3->bool)`;
                             `inside S1 INTER outside S1 = {}:real^3->bool`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    MAP_EVERY UNDISCH_TAC
     [`outside S1 INTER closure(inside S2) = {}:real^3->bool`;
      `S2 SUBSET closure(inside S2:real^3->bool)`; `(y:real^3) IN S2`;
      `~((y:real^3) IN S1)`;
      `inside S1 UNION outside S1 = (:real^3) DIFF S1`] THEN
    SET_TAC[];
    SUBGOAL_THEN `!x:real^3. x IN inside S2 ==> c - h <= x$3 /\ x$3 <= c` ASSUME_TAC THENL
     [X_GEN_TAC `y:real^3` THEN DISCH_TAC THEN
      MP_TAC(ISPECL [`S2:real^3->bool`; `c:real`] MOI_S5C_HALF_OUT) THEN
      MP_TAC(ISPECL [`S2:real^3->bool`; `c - h`] MOI_S5C_HALF_OUT_LOW) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[]; DISCH_TAC] THEN
      ANTS_TAC THENL [ASM_MESON_TAC[]; DISCH_TAC] THEN
      MAP_EVERY UNDISCH_TAC [`(y:real^3) IN inside S2`;
                             `inside S2 INTER outside S2 = {}:real^3->bool`;
                             `{x:real^3 | x$3 < c - h} SUBSET outside S2`;
                             `{x:real^3 | c < x$3} SUBSET outside S2`] THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
      MESON_TAC[REAL_NOT_LT];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`inside S2:real^3->bool`; `c - h`; `c:real`]
      MOI_S5C_OPEN_LEVEL_STRICT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `!x:real^3. x IN inside S2 ==> c - h <= x$3 /\ x$3 <= c` THEN
    MESON_TAC[];
    SUBGOAL_THEN `!x:real^3. x IN S1 ==> x$3 <= &1 / &32` ASSUME_TAC THENL
     [X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
      ASM_CASES_TAC `c < (x:real^3)$3` THENL
       [SUBGOAL_THEN `(x:real^3) IN moi_s35_ttube` MP_TAC THENL
         [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
          REWRITE_TAC[moi_s35_ttube; IN_ELIM_THM] THEN REAL_ARITH_TAC];
        MAP_EVERY UNDISCH_TAC [`~(c < (x:real^3)$3)`; `abs c <= &1 / &512`] THEN
        REAL_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `!x:real^3. x IN inside S1 ==> c - h <= x$3 /\ x$3 <= &1 / &32`
    ASSUME_TAC THENL
     [X_GEN_TAC `y:real^3` THEN DISCH_TAC THEN
      MP_TAC(ISPECL [`S1:real^3->bool`; `&1 / &32`] MOI_S5C_HALF_OUT) THEN
      MP_TAC(ISPECL [`S1:real^3->bool`; `c - h`] MOI_S5C_HALF_OUT_LOW) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[]; DISCH_TAC] THEN
      ANTS_TAC THENL [ASM_MESON_TAC[]; DISCH_TAC] THEN
      MAP_EVERY UNDISCH_TAC [`(y:real^3) IN inside S1`;
                             `inside S1 INTER outside S1 = {}:real^3->bool`;
                             `{x:real^3 | x$3 < c - h} SUBSET outside S1`;
                             `{x:real^3 | &1 / &32 < x$3} SUBSET outside S1`] THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
      MESON_TAC[REAL_NOT_LT];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`inside S1:real^3->bool`; `c - h`; `&1 / &32`]
      MOI_S5C_OPEN_LEVEL_STRICT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `!x:real^3. x IN inside S1 ==> c - h <= x$3 /\ x$3 <= &1 / &32` THEN
    MESON_TAC[]]);;

let MOI_S5C_ARCH_LEVELS = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> moi_s5c_sig2 c h jin jin' Cin SUBSET
           moi_s5c_sig1 c h jin jout' A Cout UNION
           inside (moi_s5c_sig1 c h jin jout' A Cout) /\
         (!x. x IN inside (moi_s5c_sig2 c h jin jin' Cin) ==> c - h < x$3 /\ x$3 < c) /\
         (!x. x IN inside (moi_s5c_sig1 c h jin jout' A Cout)
              ==> c - h < x$3 /\ x$3 < &1 / &32)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC MOI_S5C_TWO_SPH_LEVELS THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_FACTS2) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_INSIDE21) THEN
  MP_TAC(MOI_S5C_ARCH_CONJ 1 (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`)) THEN
  DISCH_TAC THEN ASM_SIMP_TAC[] THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_SPHERES o
    check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
  SIMP_TAC[moi_s5c_sig1; moi_s5c_sig2]);;

let MOI_S5C_N_CONVEX_LT = prove
 (`!r. convex {y:real^3 | moi_s35_n y < r}`,
  GEN_TAC THEN
  SUBGOAL_THEN `{y:real^3 | moi_s35_n y < r} =
                {y | moi_s5c_proj y IN {z:real^2 | max (abs(z$1)) (abs(z$2)) < r}}`
  SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; MOI_S5C_PROJ_FACTS]; ALL_TAC] THEN
  MATCH_MP_TAC CONVEX_LINEAR_PREIMAGE THEN
  REWRITE_TAC[MOI_S5C_PROJ_FACTS; MOI_S5C_SQ_CONVEX_LT]);;

let MOI_S5C_N_RAY = prove
 (`!x:real^3 t.
     &0 <= t ==> moi_s35_n (x + t % vector[x$1; x$2; &0]) = (&1 + t) * moi_s35_n x`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[moi_s35_n; VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; VECTOR_3] THEN
  REWRITE_TAC[REAL_ARITH `x + t * x = (&1 + t) * x`; REAL_ABS_MUL] THEN
  SUBGOAL_THEN `abs(&1 + t) = &1 + t` SUBST1_TAC THENL
   [UNDISCH_TAC `&0 <= t` THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC MOI_S5C_REAL_MAX_LMUL THEN UNDISCH_TAC `&0 <= t` THEN REAL_ARITH_TAC);;

let MOI_S5C_N_LIFT = prove
 (`!h y:real^2. moi_s35_n (moi_s35_lift h y) = max (abs(y$1)) (abs(y$2))`,
  REWRITE_TAC[moi_s35_n; moi_s35_lift; VECTOR_3]);;

let MOI_S5C_PROJ_IN_SQ = prove
 (`!S (x:real^3) r.
     S SUBSET {y:real^2 | max (abs(y$1)) (abs(y$2)) < r} /\ moi_s5c_proj x IN S
     ==> moi_s35_n x < r`,
  REPEAT STRIP_TAC THEN
  ONCE_REWRITE_TAC[GSYM (CONJUNCT2(CONJUNCT2 MOI_S5C_PROJ_FACTS))] THEN
  UNDISCH_TAC `S SUBSET {y:real^2 | max (abs(y$1)) (abs(y$2)) < r}` THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[]);;

(* sig1 lies in the closed square cylinder of radius 5/16.                   *)

let MOI_S5C_ARCH_SIG1_N = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> !x. x IN moi_s5c_sig1 c h jin jout' A Cout ==> moi_s35_n x <= &5 / &16`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN
  MP_TAC(MOI_S5C_ARCH_CONJ 11 (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`)) THEN
  MP_TAC(MOI_S5C_ARCH_CONJ 12 (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`)) THEN
  MP_TAC(MOI_S5C_ARCH_CONJ 14 (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`)) THEN
  MP_TAC(MOI_S5C_ARCH_CONJ 20 (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`)) THEN
  REPEAT DISCH_TAC THEN
  SUBGOAL_THEN `inside jout SUBSET {y:real^2 | max (abs(y$1)) (abs(y$2)) < &5 / &16} /\
                inside jout' SUBSET {y:real^2 | max (abs(y$1)) (abs(y$2)) < &5 / &16}`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC INSIDE_SUBSET_CONVEX THEN
    ASM_REWRITE_TAC[MOI_S5C_SQ_CONVEX_LT];
    ALL_TAC] THEN
  REWRITE_TAC[moi_s5c_sig1; IN_UNION; MOI_S5C_IN_LIFT] THEN
  X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
  (fun (asl,w) -> if exists (fun (_,th) -> concl th = `(x:real^3) IN A`) asl
                  then ALL_TAC (asl,w) else MATCH_MP_TAC REAL_LT_IMP_LE (asl,w)) THENL
   [MATCH_MP_TAC MOI_S5C_PROJ_IN_SQ THEN EXISTS_TAC `inside jout:real^2->bool` THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
      can (find_term ((=) `inside (jout:real^2->bool)`)) (concl th) &&
      is_forall(concl th) &&
      can (find_term ((=) `inside (jin:real^2->bool)`)) (concl th))) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC MOI_S5C_PROJ_IN_SQ THEN EXISTS_TAC `inside jout:real^2->bool` THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
      can (find_term ((=) `inside (jout:real^2->bool)`)) (concl th) &&
      is_forall(concl th) &&
      can (find_term ((=) `inside (jin:real^2->bool)`)) (concl th))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC;
    UNDISCH_TAC `Cout SUBSET moi_s5c_otube` THEN UNDISCH_TAC `(x:real^3) IN Cout` THEN
    REWRITE_TAC[SUBSET; moi_s5c_otube; IN_ELIM_THM] THEN MESON_TAC[];
    MATCH_MP_TAC MOI_S5C_PROJ_IN_SQ THEN EXISTS_TAC `jout':real^2->bool` THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC MOI_S5C_PROJ_IN_SQ THEN EXISTS_TAC `inside jout':real^2->bool` THEN
    ASM_REWRITE_TAC[]] THEN
  UNDISCH_TAC `A SUBSET moi_s35_ttube` THEN UNDISCH_TAC `(x:real^3) IN A` THEN
  REWRITE_TAC[SUBSET; moi_s35_ttube; IN_ELIM_THM] THEN MESON_TAC[]);;

(* Two spheres in the configuration of the arch: inside S1 INTER outside S2  *)
(* lies in the open tube.                                                    *)

let MOI_S5C_TWO_SPH_OTUBE = prove
 (`!S1 S2:real^3->bool c h.
     pl_sphere 2 S1 /\ pl_sphere 2 S2 /\
     &0 < h /\ abs c <= &1 / &512 /\ h <= &1 / &64 /\
     (!x. x IN S1 ==> moi_s35_n x <= &5 / &16) /\
     (!x. x IN S1 /\ c < x$3 ==> x IN moi_s35_ttube) /\
     (!x. x IN inside S1 ==> c - h < x$3 /\ x$3 < &1 / &32) /\
     (!x. x$3 = c /\ moi_s35_n x < &3 / &16 ==> x IN S1) /\
     (!x. x IN S2 /\ c - h < x$3 /\ x$3 < c ==> &3 / &16 < moi_s35_n x) /\
     (?y. y IN inside S2 /\ c - h < y$3 /\ y$3 < c /\ moi_s35_n y < &3 / &16)
     ==> inside S1 INTER outside S2 SUBSET moi_s5c_otube`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "n5")
   (CONJUNCTS_THEN2 (LABEL_TAC "tt") (CONJUNCTS_THEN2 (LABEL_TAC "lev1")
   (CONJUNCTS_THEN2 (LABEL_TAC "c1") (CONJUNCTS_THEN2 (LABEL_TAC "s2n")
     (X_CHOOSE_THEN `y0:real^3` STRIP_ASSUME_TAC))))))))))) THEN
  MP_TAC(MATCH_MP MOI_S5C_JB_CLOSURE (ASSUME `pl_sphere 2 (S1:real^3->bool)`)) THEN
  STRIP_TAC THEN
  MP_TAC(MATCH_MP MOI_S5C_JB_CLOSURE (ASSUME `pl_sphere 2 (S2:real^3->bool)`)) THEN
  STRIP_TAC THEN
  MP_TAC(MATCH_MP MOI_S5C_SPH_SIDES (ASSUME `pl_sphere 2 (S2:real^3->bool)`)) THEN
  DISCH_THEN(LABEL_TAC "sides2" o CONJUNCT2 o CONJUNCT2 o CONJUNCT2) THEN
  SUBGOAL_THEN `bounded(S1:real^3->bool)` ASSUME_TAC THENL
   [MP_TAC(MATCH_MP MOI_S5C_PLSPH_JB (ASSUME `pl_sphere 2 (S1:real^3->bool)`)) THEN
    SIMP_TAC[COMPACT_IMP_BOUNDED];
    ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN inside S1 ==> moi_s35_n x <= &5 / &16` ASSUME_TAC THENL
   [X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN REWRITE_TAC[GSYM REAL_NOT_LT] THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `(x:real^3) IN outside S1` MP_TAC THENL
     [MATCH_MP_TAC MOI_S5C_RAY_OUTSIDE THEN
      EXISTS_TAC `vector[(x:real^3)$1; x$2; &0]:real^3` THEN ASM_REWRITE_TAC[] THEN
      CONJ_TAC THENL
       [REWRITE_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3; VEC_COMPONENT] THEN
        UNDISCH_TAC `&5 / &16 < moi_s35_n x` THEN REWRITE_TAC[moi_s35_n] THEN
        REAL_ARITH_TAC;
        X_GEN_TAC `t:real` THEN DISCH_TAC THEN DISCH_TAC THEN
        USE_THEN "n5" (MP_TAC o C MATCH_MP
          (ASSUME `x + t % vector[(x:real^3)$1; x$2; &0] IN S1`) o
          SPEC `x + t % vector[(x:real^3)$1; x$2; &0]`) THEN
        SIMP_TAC[MOI_S5C_N_RAY; ASSUME `&0 <= t`] THEN
        SUBGOAL_THEN `&0 <= t * moi_s35_n x` MP_TAC THENL
         [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
          REWRITE_TAC[moi_s35_n] THEN REAL_ARITH_TAC;
          ALL_TAC] THEN
        UNDISCH_TAC `&5 / &16 < moi_s35_n x` THEN REAL_ARITH_TAC];
      MAP_EVERY UNDISCH_TAC [`(x:real^3) IN inside S1`;
                             `inside S1 INTER outside S1 = {}:real^3->bool`] THEN
      SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN inside S1 INTER outside S2 ==> &3 / &16 <= moi_s35_n x`
  ASSUME_TAC THENL
   [X_GEN_TAC `x:real^3` THEN REWRITE_TAC[IN_INTER] THEN STRIP_TAC THEN
    REWRITE_TAC[GSYM REAL_NOT_LT] THEN DISCH_TAC THEN
    USE_THEN "lev1" (STRIP_ASSUME_TAC o C MATCH_MP (ASSUME `(x:real^3) IN inside S1`)) THEN
    ASM_CASES_TAC `c < (x:real^3)$3` THENL
     [SUBGOAL_THEN `(x:real^3) IN outside S1` MP_TAC THENL
       [MATCH_MP_TAC MOI_S5C_RAY_OUTSIDE THEN EXISTS_TAC `basis 3:real^3` THEN
        ASM_SIMP_TAC[BASIS_NONZERO; DIMINDEX_3; ARITH] THEN
        X_GEN_TAC `t:real` THEN DISCH_TAC THEN DISCH_TAC THEN
        USE_THEN "tt" (MP_TAC o SPEC `x + t % basis 3:real^3`) THEN
        REWRITE_TAC[moi_s35_ttube; IN_ELIM_THM; moi_s35_n; MOI_S5C_RAY3] THEN
        ASM_REWRITE_TAC[] THEN
        MAP_EVERY UNDISCH_TAC [`&0 <= t`; `c < (x:real^3)$3`;
                               `moi_s35_n x < &3 / &16`] THEN
        REWRITE_TAC[moi_s35_n] THEN REAL_ARITH_TAC;
        MAP_EVERY UNDISCH_TAC [`(x:real^3) IN inside S1`;
                               `inside S1 INTER outside S1 = {}:real^3->bool`] THEN
        SET_TAC[]];
      ALL_TAC] THEN
    ASM_CASES_TAC `(x:real^3)$3 = c` THENL
     [USE_THEN "c1" (MP_TAC o C MATCH_MP
        (CONJ (ASSUME `(x:real^3)$3 = c`) (ASSUME `moi_s35_n x < &3 / &16`))) THEN
      MAP_EVERY UNDISCH_TAC [`(x:real^3) IN inside S1`;
                             `inside S1 UNION outside S1 = (:real^3) DIFF S1`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `{y:real^3 | moi_s35_n y < &3 / &16} INTER {y | y$3 > c - h} INTER
                  {y | y$3 < c} SUBSET inside S2`
    MP_TAC THENL
     [USE_THEN "sides2" MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC CONVEX_CONNECTED THEN
        REPEAT(MATCH_MP_TAC CONVEX_INTER THEN CONJ_TAC) THEN
        REWRITE_TAC[MOI_S5C_N_CONVEX_LT; CONVEX_HALFSPACE_COMPONENT_GT;
                    CONVEX_HALFSPACE_COMPONENT_LT];
        REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_ELIM_THM; NOT_IN_EMPTY] THEN
        X_GEN_TAC `y:real^3` THEN STRIP_TAC THEN
        USE_THEN "s2n" (MP_TAC o SPEC `y:real^3`) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[] THEN UNDISCH_TAC `(y:real^3)$3 > c - h` THEN
          REWRITE_TAC[real_gt];
          UNDISCH_TAC `moi_s35_n y < &3 / &16` THEN REAL_ARITH_TAC];
        REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER; IN_ELIM_THM; real_gt] THEN
        EXISTS_TAC `y0:real^3` THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    REWRITE_TAC[SUBSET; IN_INTER; IN_ELIM_THM; real_gt] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^3`) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MAP_EVERY UNDISCH_TAC [`~(c < (x:real^3)$3)`; `~((x:real^3)$3 = c)`] THEN
      REAL_ARITH_TAC;
      ALL_TAC] THEN
    MAP_EVERY UNDISCH_TAC [`(x:real^3) IN outside S2`;
                           `inside S2 INTER outside S2 = {}:real^3->bool`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `open(inside S1 INTER outside S2:real^3->bool)` ASSUME_TAC THENL
   [MATCH_MP_TAC OPEN_INTER THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN inside S1 INTER outside S2 ==> moi_s35_n x <= &5 / &16`
  ASSUME_TAC THENL
   [X_GEN_TAC `x:real^3` THEN REWRITE_TAC[IN_INTER] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
      concl th = `!x:real^3. x IN inside S1 ==> moi_s35_n x <= &5 / &16`)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP (CONJUNCT1 (MATCH_MP MOI_S5C_OPEN_N_STRICT
    (CONJ (ASSUME `open(inside S1 INTER outside S2:real^3->bool)`)
          (REAL_ARITH `&0 < &5 / &16`))))
    (ASSUME `!x:real^3. x IN inside S1 INTER outside S2 ==> moi_s35_n x <= &5 / &16`)) THEN
  MP_TAC(MATCH_MP (CONJUNCT2 (MATCH_MP MOI_S5C_OPEN_N_STRICT
    (CONJ (ASSUME `open(inside S1 INTER outside S2:real^3->bool)`)
          (REAL_ARITH `&0 < &3 / &16`))))
    (ASSUME `!x:real^3. x IN inside S1 INTER outside S2 ==> &3 / &16 <= moi_s35_n x`)) THEN
  DISCH_THEN(LABEL_TAC "lo") THEN DISCH_THEN(LABEL_TAC "hi") THEN
  REWRITE_TAC[SUBSET; moi_s5c_otube; IN_ELIM_THM] THEN X_GEN_TAC `x:real^3` THEN
  DISCH_TAC THEN
  USE_THEN "lo" (ASSUME_TAC o C MATCH_MP
    (ASSUME `(x:real^3) IN inside S1 INTER outside S2`)) THEN
  USE_THEN "hi" (ASSUME_TAC o C MATCH_MP
    (ASSUME `(x:real^3) IN inside S1 INTER outside S2`)) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "lev1" (MP_TAC o SPEC `x:real^3`) THEN
  ANTS_TAC THENL
   [UNDISCH_TAC `(x:real^3) IN inside S1 INTER outside S2` THEN SET_TAC[]; ALL_TAC] THEN
  MAP_EVERY UNDISCH_TAC [`&0 < h`; `abs c <= &1 / &512`; `h <= &1 / &64`] THEN
  REAL_ARITH_TAC);;

let MOI_S5C_ARCH_V_OTUBE = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
         outside (moi_s5c_sig2 c h jin jin' Cin) SUBSET moi_s5c_otube`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN MATCH_MP_TAC MOI_S5C_TWO_SPH_OTUBE THEN
  EXISTS_TAC `c:real` THEN EXISTS_TAC `h:real` THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_FACTS2) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_LEVELS) THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_SIG1_N) THEN
  FIRST_ASSUM(X_CHOOSE_THEN `r0:real` STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_P0) THEN
  MAP_EVERY (fun k -> MP_TAC(MOI_S5C_ARCH_CONJ k
    (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`))) [0;1;2;9;19] THEN
  REPEAT DISCH_TAC THEN
  SUBGOAL_THEN `pl_sphere 2 (moi_s5c_sig1 c h jin jout' A Cout) /\
                pl_sphere 2 (moi_s5c_sig2 c h jin jin' Cin)` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_SPHERES o
      check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
    SIMP_TAC[moi_s5c_sig1; moi_s5c_sig2];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
    REWRITE_TAC[moi_s5c_sig1; IN_UNION; MOI_S5C_IN_LIFT] THEN
    DISJ1_TAC THEN ASM_REWRITE_TAC[] THEN DISJ2_TAC THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
      can (find_term ((=) `inside (jin:real^2->bool)`)) (concl th) &&
      can (find_term ((=) `&3 / &16`)) (concl th))) THEN
    REWRITE_TAC[MOI_S5C_PROJ_FACTS] THEN
    UNDISCH_TAC `moi_s35_n x < &3 / &16` THEN REAL_ARITH_TAC;
    X_GEN_TAC `x:real^3` THEN
    REWRITE_TAC[moi_s5c_sig2; IN_UNION; MOI_S5C_IN_LIFT] THEN STRIP_TAC THENL
     [UNDISCH_TAC `(x:real^3)$3 = c` THEN UNDISCH_TAC `(x:real^3)$3 < c` THEN
      REAL_ARITH_TAC;
      UNDISCH_TAC `(x:real^3)$3 = c` THEN UNDISCH_TAC `(x:real^3)$3 < c` THEN
      REAL_ARITH_TAC;
      UNDISCH_TAC `Cin SUBSET moi_s5c_otube` THEN UNDISCH_TAC `(x:real^3) IN Cin` THEN
      REWRITE_TAC[SUBSET; moi_s5c_otube; IN_ELIM_THM] THEN MESON_TAC[];
      UNDISCH_TAC `(x:real^3)$3 = c - h` THEN UNDISCH_TAC `c - h < (x:real^3)$3` THEN
      REAL_ARITH_TAC;
      UNDISCH_TAC `(x:real^3)$3 = c - h` THEN UNDISCH_TAC `c - h < (x:real^3)$3` THEN
      REAL_ARITH_TAC];
    EXISTS_TAC `vector[&0; &0; c - min r0 h / &2]:real^3` THEN
    REWRITE_TAC[VECTOR_3; moi_s35_n] THEN
    CONJ_TAC THENL
     [SUBGOAL_THEN `vector[&0; &0; c - min r0 h / &2] IN ball(vector[&0;&0;c]:real^3,r0) /\
                    (vector[&0; &0; c - min r0 h / &2]:real^3)$3 < c` MP_TAC THENL
       [REWRITE_TAC[IN_BALL; dist; VECTOR_3] THEN
        SUBGOAL_THEN `vector[&0;&0;c] - vector[&0; &0; c - min r0 h / &2] =
                      (min r0 h / &2) % basis 3:real^3` SUBST1_TAC THENL
         [SIMP_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3; VECTOR_SUB_COMPONENT;
                   VECTOR_MUL_COMPONENT; BASIS_COMPONENT; ARITH] THEN
          REAL_ARITH_TAC;
          ALL_TAC] THEN
        SIMP_TAC[NORM_MUL; NORM_BASIS; DIMINDEX_3; ARITH] THEN
        MAP_EVERY UNDISCH_TAC [`&0 < r0`; `&0 < h`] THEN REAL_ARITH_TAC;
        ALL_TAC] THEN
      UNDISCH_TAC `{x | x IN ball(vector[&0;&0;c],r0) /\ x$3 < c} SUBSET
                   inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                   inside (moi_s5c_sig2 c h jin jin' Cin)` THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_INTER] THEN MESON_TAC[];
      MAP_EVERY UNDISCH_TAC [`&0 < r0`; `&0 < h`] THEN REAL_ARITH_TAC]]);;

let MOI_S5C_LIFT_UNBOUNDED = prove
 (`!h s:real^2->bool. ~bounded s ==> ~bounded (IMAGE (moi_s35_lift h) s)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[CONTRAPOS_THM] THEN DISCH_TAC THEN
  SUBGOAL_THEN `s = IMAGE moi_s5c_proj (IMAGE (moi_s35_lift h) (s:real^2->bool))`
  SUBST1_TAC THENL
   [REWRITE_TAC[GSYM IMAGE_o; o_DEF; MOI_S5C_PROJ_LIFT; IMAGE_ID]; ALL_TAC] THEN
  MATCH_MP_TAC BOUNDED_LINEAR_IMAGE THEN ASM_REWRITE_TAC[MOI_S5C_PROJ_FACTS]);;

(* Level points over the planar outside of the outer circles are outside    *)
(* the pancake spheres.                                                      *)

let MOI_S5C_ARCH_LIFT_OUT = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> IMAGE (moi_s35_lift c) (outside jout) SUBSET
           outside (moi_s5c_sig1 c h jin jout' A Cout) /\
         IMAGE (moi_s35_lift (c - h)) (outside jout') SUBSET
           outside (moi_s5c_sig1 c h jin jout' A Cout) /\
         IMAGE (moi_s35_lift (c - h)) (outside jout') SUBSET
           outside (moi_s5c_sig2 c h jin jin' Cin)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_FACTS2) THEN
  MAP_EVERY (fun k -> MP_TAC(MOI_S5C_ARCH_CONJ k
    (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`))) [0;4;7] THEN
  REPEAT DISCH_TAC THEN
  SUBGOAL_THEN `connected (IMAGE (moi_s35_lift c) (outside jout)) /\
                ~bounded (IMAGE (moi_s35_lift c) (outside jout)) /\
                connected (IMAGE (moi_s35_lift (c - h)) (outside jout')) /\
                ~bounded (IMAGE (moi_s35_lift (c - h)) (outside jout'))`
  STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `bounded(jout:real^2->bool) /\ bounded(jout':real^2->bool)`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC COMPACT_IMP_BOUNDED THEN
      ASM_MESON_TAC[MOI_S5C_SPHERE1_COMPACT];
      ALL_TAC] THEN
    REPEAT CONJ_TAC THEN
    TRY(MATCH_MP_TAC MOI_S5C_LIFT_CONNECTED THEN MATCH_MP_TAC CONNECTED_OUTSIDE THEN
        ASM_REWRITE_TAC[DIMINDEX_2; LE_REFL] THEN NO_TAC) THEN
    MATCH_MP_TAC MOI_S5C_LIFT_UNBOUNDED THEN MATCH_MP_TAC UNBOUNDED_OUTSIDE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!y:real^2. y IN outside jout ==> ~(y IN jout) /\ ~(y IN inside jout)`
  ASSUME_TAC THENL
   [MP_TAC(ISPEC `jout:real^2->bool` OUTSIDE_NO_OVERLAP) THEN
    MP_TAC(ISPEC `jout:real^2->bool` INSIDE_INTER_OUTSIDE) THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!y:real^2. y IN outside jout' ==> ~(y IN jout') /\ ~(y IN inside jout')`
  ASSUME_TAC THENL
   [MP_TAC(ISPEC `jout':real^2->bool` OUTSIDE_NO_OVERLAP) THEN
    MP_TAC(ISPEC `jout':real^2->bool` INSIDE_INTER_OUTSIDE) THEN SET_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THEN REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
  MATCH_MP_TAC UNBOUNDED_DISJOINT_IN_OUTSIDE THENL
   [EXISTS_TAC `IMAGE (moi_s35_lift c) (outside jout)`;
    EXISTS_TAC `IMAGE (moi_s35_lift (c - h)) (outside jout')`;
    EXISTS_TAC `IMAGE (moi_s35_lift (c - h)) (outside jout')`] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; moi_s5c_sig1; moi_s5c_sig2;
              IN_UNION; MOI_S5C_IN_LIFT] THEN
  X_GEN_TAC `y:real^3` THEN
  ASM_CASES_TAC `(y:real^3)$3 = c` THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `(y:real^3)$3 = c - h` THEN ASM_REWRITE_TAC[] THEN
  (let sg1 = `moi_s5c_sig1 c h jin jout' A Cout`
   and sg2 = `moi_s5c_sig2 c h jin jin' Cin` in
   REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th ->
     free_in `y:real^3` (concl th) ||
     (is_forall(concl th) &&
      not(can (find_term (fun t -> t = sg1 || t = sg2)) (concl th))))))) THEN
  MP_TAC(ASSUME `&0 < h`) THEN MESON_TAC[]);;

(* Set-level position of the torus pieces relative to the pancake spheres.  *)

let MOI_S5C_ARCH_PIECES = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> moi_s5c_tor c h jin' jout' A Cin Cout =
           Cin UNION (A UNION Cout UNION moi_s5c_npl (c - h) jin' jout') /\
         A UNION Cout UNION moi_s5c_npl (c - h) jin' jout' SUBSET
           moi_s5c_sig1 c h jin jout' A Cout /\
         (A UNION Cout UNION moi_s5c_npl (c - h) jin' jout') INTER
           moi_s5c_sig2 c h jin jin' Cin SUBSET
           IMAGE (moi_s35_lift c) jin UNION IMAGE (moi_s35_lift (c - h)) jin' /\
         Cin SUBSET moi_s5c_sig2 c h jin jin' Cin /\
         Cin INTER moi_s5c_sig1 c h jin jout' A Cout SUBSET
           IMAGE (moi_s35_lift c) jin UNION IMAGE (moi_s35_lift (c - h)) jin' /\
         moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin SUBSET
           moi_s5c_tor c h jin' jout' A Cin Cout UNION
           IMAGE (moi_s35_lift c) (inside jin) UNION
           IMAGE (moi_s35_lift (c - h)) (inside jin')`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN
  SUBGOAL_THEN `!y:real^2. ~(y IN jin' /\ y IN inside jin')` ASSUME_TAC THENL
   [MP_TAC(ISPEC `jin':real^2->bool` INSIDE_NO_OVERLAP) THEN SET_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[moi_s5c_tor; moi_s5c_npl; moi_s5c_rg; moi_s5c_sig1; moi_s5c_sig2] THEN
  REWRITE_TAC[SUBSET; EXTENSION; IN_UNION; IN_INTER; IN_DIFF; MOI_S5C_IN_LIFT] THEN
  REPEAT CONJ_TAC THENL
   [MESON_TAC[]; MESON_TAC[]; ALL_TAC; MESON_TAC[]; ALL_TAC; ALL_TAC] THEN
  X_GEN_TAC `x:real^3` THEN
  ASM_CASES_TAC `(x:real^3)$3 = c` THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `(x:real^3)$3 = c - h` THEN ASM_REWRITE_TAC[] THEN
  REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th ->
    free_in `x:real^3` (concl th) || is_forall(concl th) || is_neg(concl th)))) THEN
  MESON_TAC[]);;

(* Closure of the region between two spheres in the arch position.          *)

let MOI_S5C_TWO_SPH_CLOSURE = prove
 (`!S1 S2 Tr D1 D2 K2 E1 E2:real^3->bool.
     pl_sphere 2 S1 /\ pl_sphere 2 S2 /\
     inside S2 SUBSET inside S1 /\ S2 SUBSET S1 UNION inside S1 /\
     Tr = E2 UNION E1 /\ E1 SUBSET S1 /\ E1 INTER S2 SUBSET K2 /\
     E2 SUBSET S2 /\ E2 INTER S1 SUBSET K2 /\ K2 SUBSET closure (E2 DIFF K2) /\
     S1 UNION S2 SUBSET Tr UNION D1 UNION D2 /\
     (!z. z IN D1 UNION D2
          ==> ?r. &0 < r /\ ball(z,r) INTER (inside S1 INTER outside S2) = {})
     ==> open (inside S1 INTER outside S2) /\
         (inside S1 INTER outside S2) INTER Tr = {} /\
         closure (inside S1 INTER outside S2) = (inside S1 INTER outside S2) UNION Tr`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(MATCH_MP MOI_S5C_JB_CLOSURE (ASSUME `pl_sphere 2 (S1:real^3->bool)`)) THEN
  STRIP_TAC THEN
  MP_TAC(MATCH_MP MOI_S5C_JB_CLOSURE (ASSUME `pl_sphere 2 (S2:real^3->bool)`)) THEN
  STRIP_TAC THEN
  MP_TAC(MATCH_MP MOI_S5C_SPH_SIDES (ASSUME `pl_sphere 2 (S1:real^3->bool)`)) THEN
  MP_TAC(MATCH_MP MOI_S5C_SPH_SIDES (ASSUME `pl_sphere 2 (S2:real^3->bool)`)) THEN
  DISCH_THEN(STRIP_ASSUME_TAC) THEN DISCH_THEN(STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `open(inside S1 INTER outside S2:real^3->bool)` ASSUME_TAC THENL
   [MATCH_MP_TAC OPEN_INTER THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPEC `S1:real^3->bool` INSIDE_NO_OVERLAP) THEN
  MP_TAC(ISPEC `S2:real^3->bool` OUTSIDE_NO_OVERLAP) THEN REPEAT DISCH_TAC THEN
  CONJ_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`Tr:real^3->bool = E2 UNION E1`; `E1 SUBSET (S1:real^3->bool)`;
      `E2 SUBSET (S2:real^3->bool)`; `inside S1 INTER S1:real^3->bool = {}`;
      `outside S2 INTER S2:real^3->bool = {}`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_UNION] THEN X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(x:real^3) IN inside S1 UNION S1 /\ (x:real^3) IN outside S2 UNION S2`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [UNDISCH_TAC `closure (inside S1) SUBSET inside S1 UNION (S1:real^3->bool)` THEN
        MP_TAC(MATCH_MP SUBSET_CLOSURE
          (SET_RULE `inside S1 INTER outside S2 SUBSET inside (S1:real^3->bool)`)) THEN
        UNDISCH_TAC `(x:real^3) IN closure (inside S1 INTER outside S2)` THEN SET_TAC[];
        UNDISCH_TAC `closure (outside S2) SUBSET outside S2 UNION (S2:real^3->bool)` THEN
        MP_TAC(MATCH_MP SUBSET_CLOSURE
          (SET_RULE `inside S1 INTER outside S2 SUBSET outside (S2:real^3->bool)`)) THEN
        UNDISCH_TAC `(x:real^3) IN closure (inside S1 INTER outside S2)` THEN SET_TAC[]];
      ALL_TAC] THEN
    ASM_CASES_TAC `(x:real^3) IN S1 UNION S2` THENL
     [DISJ2_TAC THEN
      SUBGOAL_THEN `~((x:real^3) IN D1 UNION D2)` MP_TAC THENL
       [DISCH_TAC THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
          is_forall(concl th) && can (find_term ((=) `ball:real^3#real->real^3->bool`))
          (concl th))) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC) THEN
        MP_TAC(ISPECL [`ball(x:real^3,r)`; `inside S1 INTER outside S2:real^3->bool`]
          OPEN_INTER_CLOSURE_EQ_EMPTY) THEN
        ASM_REWRITE_TAC[OPEN_BALL] THEN
        MP_TAC(ISPECL [`x:real^3`; `r:real`] CENTRE_IN_BALL) THEN ASM_REWRITE_TAC[] THEN
        UNDISCH_TAC `(x:real^3) IN closure (inside S1 INTER outside S2)` THEN SET_TAC[];
        ALL_TAC] THEN
      MAP_EVERY UNDISCH_TAC [`(x:real^3) IN S1 UNION S2`;
                             `S1 UNION S2 SUBSET Tr UNION D1 UNION (D2:real^3->bool)`;
                             `Tr:real^3->bool = E2 UNION E1`] THEN
      SET_TAC[];
      DISJ1_TAC THEN
      MAP_EVERY UNDISCH_TAC [`~((x:real^3) IN S1 UNION S2)`;
                             `(x:real^3) IN inside S1 UNION S1`;
                             `(x:real^3) IN outside S2 UNION S2`] THEN
      SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `E1 DIFF K2 SUBSET closure(inside S1 INTER outside S2:real^3->bool) /\
                E2 DIFF K2 SUBSET closure(inside S1 INTER outside S2:real^3->bool)`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN REWRITE_TAC[SUBSET; IN_DIFF] THEN X_GEN_TAC `y:real^3` THEN STRIP_TAC THENL
     [SUBGOAL_THEN `(y:real^3) IN S1 /\ ~(y IN S2)` STRIP_ASSUME_TAC THENL
       [MAP_EVERY UNDISCH_TAC [`(y:real^3) IN E1`; `~((y:real^3) IN K2)`;
                               `E1 SUBSET (S1:real^3->bool)`;
                               `E1 INTER S2 SUBSET (K2:real^3->bool)`] THEN
        SET_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL [`outside S2:real^3->bool`; `inside S1:real^3->bool`]
        OPEN_INTER_CLOSURE_SUBSET) THEN
      ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[SET_RULE `outside S2 INTER inside S1 = inside S1 INTER outside (S2:real^3->bool)`] THEN
      REWRITE_TAC[SUBSET] THEN
      DISCH_THEN MATCH_MP_TAC THEN REWRITE_TAC[IN_INTER] THEN
      CONJ_TAC THENL
       [MAP_EVERY UNDISCH_TAC
         [`(y:real^3) IN S1`; `~((y:real^3) IN S2)`;
          `inside S2 SUBSET inside (S1:real^3->bool)`;
          `inside S1 INTER S1:real^3->bool = {}`;
          `inside S2 UNION outside S2 = (:real^3) DIFF S2`] THEN
        SET_TAC[];
        UNDISCH_TAC `S1 SUBSET closure(inside S1:real^3->bool)` THEN
        UNDISCH_TAC `(y:real^3) IN S1` THEN SET_TAC[]];
      SUBGOAL_THEN `(y:real^3) IN S2 /\ ~(y IN S1)` STRIP_ASSUME_TAC THENL
       [MAP_EVERY UNDISCH_TAC [`(y:real^3) IN E2`; `~((y:real^3) IN K2)`;
                               `E2 SUBSET (S2:real^3->bool)`;
                               `E2 INTER S1 SUBSET (K2:real^3->bool)`] THEN
        SET_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL [`inside S1:real^3->bool`; `outside S2:real^3->bool`]
        OPEN_INTER_CLOSURE_SUBSET) THEN
      ASM_REWRITE_TAC[] THEN REWRITE_TAC[SUBSET] THEN
      DISCH_THEN MATCH_MP_TAC THEN REWRITE_TAC[IN_INTER] THEN
      CONJ_TAC THENL
       [MAP_EVERY UNDISCH_TAC [`(y:real^3) IN S2`; `~((y:real^3) IN S1)`;
                               `S2 SUBSET S1 UNION inside (S1:real^3->bool)`] THEN
        SET_TAC[];
        UNDISCH_TAC `S2 SUBSET closure(outside S2:real^3->bool)` THEN
        UNDISCH_TAC `(y:real^3) IN S2` THEN SET_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(K2:real^3->bool) SUBSET closure(inside S1 INTER outside S2)` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `closure(E2 DIFF K2:real^3->bool)` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC CLOSURE_MINIMAL THEN
    ASM_REWRITE_TAC[CLOSED_CLOSURE];
    ALL_TAC] THEN
  MP_TAC(ISPEC `inside S1 INTER outside S2:real^3->bool` CLOSURE_SUBSET) THEN
  MAP_EVERY UNDISCH_TAC
   [`Tr:real^3->bool = E2 UNION E1`;
    `E1 DIFF K2 SUBSET closure(inside S1 INTER outside S2:real^3->bool)`;
    `E2 DIFF K2 SUBSET closure(inside S1 INTER outside S2:real^3->bool)`;
    `(K2:real^3->bool) SUBSET closure(inside S1 INTER outside S2)`] THEN
  SET_TAC[]);;

let MOI_S5C_FLAT_MISS = prove
 (`!S1 S2 (z:real^3) r a.
     &0 < r /\ (!x. x IN ball(z,r) ==> (x IN S1 <=> x$3 = a)) /\
     ({x | x IN ball(z,r) /\ x$3 < a} SUBSET inside S2 /\
      {x | x IN ball(z,r) /\ a < x$3} SUBSET outside S1 \/
      {x | x IN ball(z,r) /\ a < x$3} SUBSET inside S2 /\
      {x | x IN ball(z,r) /\ x$3 < a} SUBSET outside S1)
     ==> ball(z,r) INTER (inside S1 INTER outside S2) = {}`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
  REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN X_GEN_TAC `x:real^3` THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `~((x:real^3) IN S1) /\ ~(x IN outside S1) /\ ~(x IN inside S2)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPEC `S1:real^3->bool` INSIDE_NO_OVERLAP) THEN
    MP_TAC(ISPEC `S1:real^3->bool` INSIDE_INTER_OUTSIDE) THEN
    MP_TAC(ISPEC `S2:real^3->bool` INSIDE_INTER_OUTSIDE) THEN
    MAP_EVERY UNDISCH_TAC [`(x:real^3) IN inside S1`; `(x:real^3) IN outside S2`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((x:real^3)$3 = a)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o check (fun th -> is_forall(concl th))) THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^3`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(DISJ_CASES_THEN STRIP_ASSUME_TAC) THEN
  REPEAT(FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o REWRITE_RULE[SUBSET; IN_ELIM_THM] o
    check (fun th -> can (find_term ((=) `ball(z:real^3,r)`)) (concl th) &&
                     not(is_forall(concl th))))) THEN
  ASM_REWRITE_TAC[] THEN
  UNDISCH_TAC `~((x:real^3)$3 = a)` THEN REAL_ARITH_TAC);;

let MOI_S5C_ARCH_V_CLOSURE = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> open (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
               outside (moi_s5c_sig2 c h jin jin' Cin)) /\
         (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
          outside (moi_s5c_sig2 c h jin jin' Cin)) INTER
         moi_s5c_tor c h jin' jout' A Cin Cout = {} /\
         closure (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                  outside (moi_s5c_sig2 c h jin jin' Cin)) =
         (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
          outside (moi_s5c_sig2 c h jin jin' Cin)) UNION
         moi_s5c_tor c h jin' jout' A Cin Cout`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC MOI_S5C_TWO_SPH_CLOSURE THEN
  MAP_EVERY EXISTS_TAC
   [`IMAGE (moi_s35_lift c) (inside jin)`;
    `IMAGE (moi_s35_lift (c - h)) (inside jin')`;
    `IMAGE (moi_s35_lift c) jin UNION IMAGE (moi_s35_lift (c - h)) jin'`;
    `A UNION Cout UNION moi_s5c_npl (c - h) jin' jout'`; `Cin:real^3->bool`] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_PIECES) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_LEVELS) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_INSIDE21) THEN
  SUBGOAL_THEN `pl_sphere 2 (moi_s5c_sig1 c h jin jout' A Cout) /\
                pl_sphere 2 (moi_s5c_sig2 c h jin jin' Cin)` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_SPHERES o
      check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
    SIMP_TAC[moi_s5c_sig1; moi_s5c_sig2];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MP_TAC(MATCH_MP MOI_S5C_ANN_ENDS_CLOSURE (MOI_S5C_ARCH_CONJ 17
      (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`))) THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[IN_UNION] THEN X_GEN_TAC `z:real^3` THEN STRIP_TAC THENL
   [MP_TAC(ISPECL [`c:real`; `h:real`; `jin:real^2->bool`; `jout:real^2->bool`;
                   `jin':real^2->bool`; `jout':real^2->bool`; `A:real^3->bool`;
                   `Cin:real^3->bool`; `Cout:real^3->bool`; `z:real^3`]
      MOI_S5C_ARCH_DIN_SIDE);
    MP_TAC(ISPECL [`c:real`; `h:real`; `jin:real^2->bool`; `jout:real^2->bool`;
                   `jin':real^2->bool`; `jout':real^2->bool`; `A:real^3->bool`;
                   `Cin:real^3->bool`; `Cout:real^3->bool`; `z:real^3`]
      MOI_S5C_ARCH_DIN2_SIDE)] THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `r:real` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MOI_S5C_FLAT_MISS THENL
   [EXISTS_TAC `c:real`; EXISTS_TAC `c - h`] THEN
  ASM_REWRITE_TAC[]);;

(* A bounded open region V, clopen in the complement of a closed set t,     *)
(* whose closure meets t only in a set R with connected complement and in  *)
(* a connected flat piece o3 of t with V on exactly one side, is connected.*)

let MOI_S5C_HALF_BALLS_CONVEX = prove
 (`!z:real^3 r. convex {x | x IN ball(z,r) /\ z$3 < x$3} /\
                convex {x | x IN ball(z,r) /\ x$3 < z$3}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[SET_RULE `{x:real^3 | x IN s /\ P x} = s INTER {x | P x}`] THEN
  CONJ_TAC THEN MATCH_MP_TAC CONVEX_INTER THEN REWRITE_TAC[CONVEX_BALL] THEN
  REWRITE_TAC[REAL_ARITH `(p:real) < x <=> x > p`; CONVEX_HALFSPACE_COMPONENT_GT;
              CONVEX_HALFSPACE_COMPONENT_LT]);;

let MOI_S5C_REGION_CONNECTED = prove
 (`!t V N o3 R:real^3->bool.
     closed t /\ open V /\ bounded V /\ V INTER t = {} /\ closure V SUBSET V UNION t /\
     N SUBSET t /\ o3 SUBSET N /\ connected o3 /\ ~(o3 = {}) /\ moi_s5c_flat t N o3 /\
     (!z. z IN o3
          ==> ?r. &0 < r /\ ball(z,r) INTER t SUBSET N /\
                  ball(z,r) DIFF N = {x | x IN ball(z,r) /\ z$3 < x$3} UNION
                                     {x | x IN ball(z,r) /\ x$3 < z$3} /\
                  {x | x IN ball(z,r) /\ z$3 < x$3} SUBSET V /\
                  {x | x IN ball(z,r) /\ x$3 < z$3} INTER V = {}) /\
     R SUBSET t /\ bounded R /\ connected ((:real^3) DIFF R) /\
     closure V INTER t SUBSET R UNION o3
     ==> connected V /\ ~(V = {})`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 (LABEL_TAC "sides") STRIP_ASSUME_TAC))))))))))) THEN
  (* components of the complement of t through V lie in V *)
  SUBGOAL_THEN `!x:real^3. x IN V ==> connected_component ((:real^3) DIFF t) x SUBSET V`
  (LABEL_TAC "csub") THENL
   [X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
    MATCH_MP_TAC MOI_S5C_CONN_SUB THEN
    EXISTS_TAC `(:real^3) DIFF (t UNION closure V)` THEN
    REWRITE_TAC[CONNECTED_CONNECTED_COMPONENT] THEN REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`(:real^3) DIFF t`; `x:real^3`] CONNECTED_COMPONENT_SUBSET) THEN
      MP_TAC(ISPEC `V:real^3->bool` CLOSURE_SUBSET) THEN
      UNDISCH_TAC `closure V SUBSET V UNION (t:real^3->bool)` THEN SET_TAC[];
      REWRITE_TAC[GSYM closed] THEN MATCH_MP_TAC CLOSED_UNION THEN
      ASM_REWRITE_TAC[CLOSED_CLOSURE];
      ASM_REWRITE_TAC[];
      MP_TAC(ISPEC `V:real^3->bool` CLOSURE_SUBSET) THEN SET_TAC[];
      REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN EXISTS_TAC `x:real^3` THEN
      ASM_REWRITE_TAC[] THEN REWRITE_TAC[IN] THEN
      REWRITE_TAC[CONNECTED_COMPONENT_REFL_EQ] THEN
      REWRITE_TAC[IN_DIFF; IN_UNIV] THEN
      UNDISCH_TAC `V INTER t:real^3->bool = {}` THEN UNDISCH_TAC `(x:real^3) IN V` THEN
      SET_TAC[]];
    ALL_TAC] THEN
  (* every such component has the flat piece in its closure *)
  SUBGOAL_THEN `!x:real^3. x IN V
                  ==> o3 SUBSET closure(connected_component ((:real^3) DIFF t) x)`
  (LABEL_TAC "adj") THENL
   [X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`t:real^3->bool`; `N:real^3->bool`; `o3:real^3->bool`; `x:real^3`]
      MOI_S5C_THETA_ADJ) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(TAUT `~p ==> (p \/ q ==> q)`) THEN
    ABBREV_TAC `C = connected_component ((:real^3) DIFF t) (x:real^3)` THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `C SUBSET (V:real^3->bool) /\ (x:real^3) IN C /\ open C /\
                  frontier C SUBSET (t:real^3->bool)` STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "C" THEN REPEAT CONJ_TAC THENL
       [USE_THEN "csub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[IN] THEN REWRITE_TAC[CONNECTED_COMPONENT_REFL_EQ] THEN
        REWRITE_TAC[IN_DIFF; IN_UNIV] THEN
        UNDISCH_TAC `V INTER t:real^3->bool = {}` THEN UNDISCH_TAC `(x:real^3) IN V` THEN
        SET_TAC[];
        MATCH_MP_TAC OPEN_CONNECTED_COMPONENT THEN
        ASM_REWRITE_TAC[GSYM closed];
        MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `frontier((:real^3) DIFF t)` THEN
        REWRITE_TAC[FRONTIER_OF_CONNECTED_COMPONENT_SUBSET; FRONTIER_COMPLEMENT] THEN
        ASM_SIMP_TAC[FRONTIER_SUBSET_CLOSED]];
      ALL_TAC] THEN
    SUBGOAL_THEN `frontier C SUBSET (R:real^3->bool)` ASSUME_TAC THENL
     [MP_TAC(ISPEC `C:real^3->bool` frontier) THEN
      MP_TAC(MATCH_MP SUBSET_CLOSURE (ASSUME `C SUBSET (V:real^3->bool)`)) THEN
      MAP_EVERY UNDISCH_TAC
       [`frontier C SUBSET (t:real^3->bool)`;
        `closure V INTER t SUBSET R UNION (o3:real^3->bool)`;
        `closure C INTER o3:real^3->bool = {}`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `C = (:real^3) DIFF R` ASSUME_TAC THENL
     [MP_TAC(ISPEC `(:real^3) DIFF R` CONNECTED_CLOPEN) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o SPEC `C:real^3->bool`) THEN
      ANTS_TAC THENL
       [CONJ_TAC THENL
         [MATCH_MP_TAC OPEN_SUBSET THEN ASM_REWRITE_TAC[] THEN
          MAP_EVERY UNDISCH_TAC [`C SUBSET (V:real^3->bool)`;
                                 `V INTER t:real^3->bool = {}`;
                                 `R SUBSET (t:real^3->bool)`] THEN
          SET_TAC[];
          REWRITE_TAC[CLOSED_IN_CLOSED] THEN EXISTS_TAC `closure C:real^3->bool` THEN
          REWRITE_TAC[CLOSED_CLOSURE] THEN
          MP_TAC(ISPEC `C:real^3->bool` CLOSURE_SUBSET) THEN
          MP_TAC(ISPEC `C:real^3->bool` frontier) THEN
          MP_TAC(ISPEC `C:real^3->bool` INTERIOR_OPEN) THEN ASM_REWRITE_TAC[] THEN
          DISCH_THEN SUBST1_TAC THEN
          MAP_EVERY UNDISCH_TAC [`frontier C SUBSET (R:real^3->bool)`;
                                 `C SUBSET (V:real^3->bool)`;
                                 `V INTER t:real^3->bool = {}`;
                                 `R SUBSET (t:real^3->bool)`] THEN
          SET_TAC[]];
        UNDISCH_TAC `(x:real^3) IN C` THEN SET_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `bounded((:real^3) DIFF R)` MP_TAC THENL
     [MATCH_MP_TAC BOUNDED_SUBSET THEN EXISTS_TAC `V:real^3->bool` THEN
      ASM_REWRITE_TAC[] THEN UNDISCH_TAC `C SUBSET (V:real^3->bool)` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[] THEN MATCH_MP_TAC COBOUNDED_IMP_UNBOUNDED THEN
    ASM_REWRITE_TAC[SET_RULE `(:real^3) DIFF ((:real^3) DIFF R) = R`];
    ALL_TAC] THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `z0:real^3` o GEN_REWRITE_RULE I [GSYM MEMBER_NOT_EMPTY]) THEN
  USE_THEN "sides" (X_CHOOSE_THEN `r0:real` STRIP_ASSUME_TAC o
    C MATCH_MP (ASSUME `(z0:real^3) IN o3`)) THEN
  MP_TAC(ISPECL [`z0:real^3`; `r0:real`] MOI_S5C_HALF_BALLS_CONVEX) THEN
  MP_TAC(MATCH_MP (ISPECL [`z0:real^3`; `r0:real`] MOI_S5C_HALF_BALLS_NONEMPTY)
    (ASSUME `&0 < r0`)) THEN
  DISCH_THEN(STRIP_ASSUME_TAC) THEN DISCH_THEN(STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `!x:real^3. x IN V
       ==> {y | y IN ball(z0,r0) /\ z0$3 < y$3} SUBSET
           connected_component ((:real^3) DIFF t) x`
  (LABEL_TAC "u1") THENL
   [X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`t:real^3->bool`; `N:real^3->bool`; `ball(z0:real^3,r0)`;
      `{y:real^3 | y IN ball(z0,r0) /\ z0$3 < y$3}`;
      `{y:real^3 | y IN ball(z0,r0) /\ y$3 < z0$3}`;
      `z0:real^3`; `x:real^3`] MOI_S5C_FLAT_COMPONENT) THEN
    ANTS_TAC THENL
     [ASM_SIMP_TAC[OPEN_BALL; CENTRE_IN_BALL; CONVEX_CONNECTED] THEN
      USE_THEN "adj" (MP_TAC o C MATCH_MP (ASSUME `(x:real^3) IN V`)) THEN
      UNDISCH_TAC `(z0:real^3) IN o3` THEN SET_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `~(q /\ b) ==> (p /\ a \/ q /\ b ==> p)`) THEN STRIP_TAC THEN
    USE_THEN "csub" (MP_TAC o C MATCH_MP (ASSUME `(x:real^3) IN V`)) THEN
    MAP_EVERY UNDISCH_TAC
     [`{y:real^3 | y IN ball(z0,r0) /\ y$3 < z0$3} SUBSET
       connected_component ((:real^3) DIFF t) x`;
      `{x:real^3 | x IN ball(z0,r0) /\ x$3 < z0$3} INTER V = {}`;
      `~({x:real^3 | x IN ball(z0,r0) /\ x$3 < z0$3} = {})`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(V:real^3->bool = {})` ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`{x:real^3 | x IN ball(z0,r0) /\ z0$3 < x$3} SUBSET V`;
      `~({x:real^3 | x IN ball(z0,r0) /\ z0$3 < x$3} = {})`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `x0:real^3` o GEN_REWRITE_RULE I [GSYM MEMBER_NOT_EMPTY]) THEN
  SUBGOAL_THEN `V = connected_component ((:real^3) DIFF t) (x0:real^3)` SUBST1_TAC THENL
   [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET] THEN X_GEN_TAC `y:real^3` THEN DISCH_TAC THEN
      SUBGOAL_THEN `connected_component ((:real^3) DIFF t) (y:real^3) =
                    connected_component ((:real^3) DIFF t) x0`
      MP_TAC THENL
       [MP_TAC(ISPECL [`(:real^3) DIFF t`; `y:real^3`; `x0:real^3`]
          CONNECTED_COMPONENT_OVERLAP) THEN
        MATCH_MP_TAC(TAUT `p ==> (p <=> a /\ b /\ c) ==> c`) THEN
        USE_THEN "u1" (MP_TAC o C MATCH_MP (ASSUME `(y:real^3) IN V`)) THEN
        USE_THEN "u1" (MP_TAC o C MATCH_MP (ASSUME `(x0:real^3) IN V`)) THEN
        UNDISCH_TAC `~({x:real^3 | x IN ball(z0,r0) /\ z0$3 < x$3} = {})` THEN
        SET_TAC[];
        ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[IN] THEN
      REWRITE_TAC[CONNECTED_COMPONENT_REFL_EQ] THEN REWRITE_TAC[IN_DIFF; IN_UNIV] THEN
      UNDISCH_TAC `V INTER t:real^3->bool = {}` THEN UNDISCH_TAC `(y:real^3) IN V` THEN
      SET_TAC[];
      USE_THEN "csub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
    REWRITE_TAC[CONNECTED_CONNECTED_COMPONENT]]);;

(* At points of the open planar annulus N' the region V lies exactly above. *)

let MOI_S5C_ARCH_N_HALVES = prove
 (`!c h jin jout jin' jout' A Cin Cout z.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout /\
     z IN IMAGE (moi_s35_lift (c - h)) (inside jout' DIFF (jin' UNION inside jin'))
     ==> ?r. &0 < r /\
             (!x. x IN ball(z,r)
                  ==> (x IN moi_s5c_npl (c - h) jin' jout' <=> x$3 = z$3)) /\
             ball(z,r) INTER
               (moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin)
               SUBSET moi_s5c_npl (c - h) jin' jout' /\
             {x | x IN ball(z,r) /\ z$3 < x$3} SUBSET
               inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
               outside (moi_s5c_sig2 c h jin jin' Cin) /\
             {x | x IN ball(z,r) /\ x$3 < z$3} INTER
               (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                outside (moi_s5c_sig2 c h jin jin' Cin)) = {}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`c:real`; `h:real`; `jin:real^2->bool`; `jout:real^2->bool`;
                 `jin':real^2->bool`; `jout':real^2->bool`; `A:real^3->bool`;
                 `Cin:real^3->bool`; `Cout:real^3->bool`; `z:real^3`]
    MOI_S5C_ARCH_N_SIDE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `r:real` THEN ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN
  SUBGOAL_THEN `(z:real^3)$3 = c - h` ASSUME_TAC THENL
   [UNDISCH_TAC `(z:real^3) IN IMAGE (moi_s35_lift (c - h))
                   (inside jout' DIFF (jin' UNION inside jin'))` THEN
    SIMP_TAC[MOI_S5C_IN_LIFT];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `!x:real^3. x IN moi_s5c_tor c h jin' jout' A Cin Cout /\ x$3 = c - h
                           ==> x IN moi_s5c_npl (c - h) jin' jout'`
  ASSUME_TAC THENL
   [SUBGOAL_THEN `!y:real^2. y IN jin' ==> ~(y IN inside jin')` ASSUME_TAC THENL
     [MP_TAC(ISPEC `jin':real^2->bool` INSIDE_NO_OVERLAP) THEN SET_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[moi_s5c_tor; moi_s5c_npl; moi_s5c_rg; IN_UNION; MOI_S5C_IN_LIFT;
                IN_DIFF] THEN
    X_GEN_TAC `x:real^3` THEN
    REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th -> is_forall(concl th) &&
       not(can (find_term ((=) `ball(z:real^3,r)`)) (concl th)) &&
       not(can (find_term ((=) `moi_s5c_sig1 c h jin jout' A Cout`)) (concl th)) &&
       not(can (find_term ((=) `moi_s5c_sig2 c h jin jin' Cin`)) (concl th))))) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN ball(z,r)
                  ==> (x IN moi_s5c_npl (c - h) jin' jout' <=> x$3 = c - h)`
  ASSUME_TAC THENL
   [X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN EQ_TAC THENL
     [SIMP_TAC[moi_s5c_npl; MOI_S5C_IN_LIFT];
      DISCH_TAC THEN FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `moi_s5c_npl`)) (concl th))) THEN
      ASM_REWRITE_TAC[] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `moi_s5c_tor`)) (concl th) &&
        can (find_term ((=) `ball(z:real^3,r)`)) (concl th))) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER; IN_UNION] THEN X_GEN_TAC `x:real^3` THEN STRIP_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `moi_s5c_npl`)) (concl th) &&
        can (find_term ((=) `ball(z:real^3,r)`)) (concl th))) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `moi_s5c_sig1`)) (concl th) &&
        can (find_term ((=) `ball(z:real^3,r)`)) (concl th))) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPEC `moi_s5c_sig2 c h jin jin' Cin` OUTSIDE_NO_OVERLAP) THEN
      MAP_EVERY UNDISCH_TAC
       [`(x:real^3) IN ball(z,r)`; `(x:real^3) IN moi_s5c_sig2 c h jin jin' Cin`;
        `ball(z:real^3,r) SUBSET outside (moi_s5c_sig2 c h jin jin' Cin)`] THEN
      SET_TAC[]];
    MAP_EVERY UNDISCH_TAC
     [`{x | x IN ball(z,r) /\ c - h < x$3} SUBSET
       inside (moi_s5c_sig1 c h jin jout' A Cout)`;
      `ball(z:real^3,r) SUBSET outside (moi_s5c_sig2 c h jin jin' Cin)`] THEN
    SET_TAC[];
    MP_TAC(ISPEC `moi_s5c_sig1 c h jin jout' A Cout` INSIDE_INTER_OUTSIDE) THEN
    UNDISCH_TAC `{x | x IN ball(z,r) /\ x$3 < c - h} SUBSET
                 outside (moi_s5c_sig1 c h jin jout' A Cout)` THEN
    SET_TAC[]]);;

let MOI_S5C_LEVEL_BALL_SPLIT = prove
 (`!N (z:real^3) r.
     (!x. x IN ball(z,r) ==> (x IN N <=> x$3 = z$3))
     ==> ball(z,r) DIFF N = {x | x IN ball(z,r) /\ z$3 < x$3} UNION
                            {x | x IN ball(z,r) /\ x$3 < z$3} /\
         ball(z,r) INTER N SUBSET
           closure {x | x IN ball(z,r) /\ z$3 < x$3} INTER
           closure {x | x IN ball(z,r) /\ x$3 < z$3}`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN CONJ_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_DIFF; IN_UNION; IN_ELIM_THM] THEN X_GEN_TAC `x:real^3` THEN
    ASM_CASES_TAC `(x:real^3) IN ball(z,r)` THEN ASM_SIMP_TAC[] THEN REAL_ARITH_TAC;
    REWRITE_TAC[SUBSET; IN_INTER] THEN X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
    MATCH_MP_TAC MOI_S5C_HALFBALL_CLOSURE THEN ASM_MESON_TAC[]]);;

let MOI_S5C_ARCH_V_CONNECTED = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> connected (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                    outside (moi_s5c_sig2 c h jin jin' Cin)) /\
         ~(inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
           outside (moi_s5c_sig2 c h jin jin' Cin) = {})`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC MOI_S5C_REGION_CONNECTED THEN
  MAP_EVERY EXISTS_TAC
   [`moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin`;
    `moi_s5c_npl (c - h) jin' jout'`;
    `IMAGE (moi_s35_lift (c - h)) (inside jout' DIFF (jin' UNION inside jin'))`;
    `Cin UNION A UNION Cout:real^3->bool`] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_PIECES) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_V_CLOSURE) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_COMPACTS) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN
  SUBGOAL_THEN `pl_sphere 2 (moi_s5c_sig1 c h jin jout' A Cout) /\
                pl_sphere 2 (moi_s5c_sig2 c h jin jin' Cin) /\
                pl_annulus_with_ends (Cin UNION A UNION Cout)
                  (IMAGE (moi_s35_lift (c - h)) jin') (IMAGE (moi_s35_lift (c - h)) jout')`
  STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_SPHERES o
      check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
    SIMP_TAC[moi_s5c_sig1; moi_s5c_sig2];
    ALL_TAC] THEN
  SUBGOAL_THEN `pl_sphere 1 (jin':real^2->bool) /\ pl_sphere 1 (jout':real^2->bool) /\
                jin' SUBSET inside jout'` STRIP_ASSUME_TAC THENL
   [MAP_EVERY (fun k -> MP_TAC(MOI_S5C_ARCH_CONJ k
      (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`))) [6;7;8] THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`jin':real^2->bool`; `jout':real^2->bool`] MOI_S5C_RG_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MAP_EVERY (fun k -> ASSUME_TAC(el k (CONJUNCTS th))) [2;3;6]) THEN
  SUBGOAL_THEN `!z. z IN IMAGE (moi_s35_lift (c - h)) (inside jout' DIFF (jin' UNION inside jin'))
       ==> ?r. &0 < r /\
               ball(z,r) INTER
                 (moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin)
                 SUBSET moi_s5c_npl (c - h) jin' jout' /\
               ball(z,r) DIFF moi_s5c_npl (c - h) jin' jout' =
                 {x | x IN ball(z,r) /\ z$3 < x$3} UNION
                 {x | x IN ball(z,r) /\ x$3 < z$3} /\
               ball(z,r) INTER moi_s5c_npl (c - h) jin' jout' SUBSET
                 closure {x | x IN ball(z,r) /\ z$3 < x$3} INTER
                 closure {x | x IN ball(z,r) /\ x$3 < z$3} /\
               {x | x IN ball(z,r) /\ z$3 < x$3} SUBSET
                 inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                 outside (moi_s5c_sig2 c h jin jin' Cin) /\
               {x | x IN ball(z,r) /\ x$3 < z$3} INTER
                 (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                  outside (moi_s5c_sig2 c h jin jin' Cin)) = {}`
  (LABEL_TAC "hv") THENL
   [X_GEN_TAC `z:real^3` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`c:real`; `h:real`; `jin:real^2->bool`; `jout:real^2->bool`;
                   `jin':real^2->bool`; `jout':real^2->bool`; `A:real^3->bool`;
                   `Cin:real^3->bool`; `Cout:real^3->bool`; `z:real^3`]
      MOI_S5C_ARCH_N_HALVES) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `r:real` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC MOI_S5C_LEVEL_BALL_SPLIT THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `compact (moi_s5c_sig1 c h jin jout' A Cout) /\
                compact (moi_s5c_sig2 c h jin jin' Cin) /\
                bounded (inside (moi_s5c_sig1 c h jin jout' A Cout))`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(MATCH_MP MOI_S5C_PLSPH_JB
      (ASSUME `pl_sphere 2 (moi_s5c_sig1 c h jin jout' A Cout)`)) THEN
    MP_TAC(MATCH_MP MOI_S5C_PLSPH_JB
      (ASSUME `pl_sphere 2 (moi_s5c_sig2 c h jin jin' Cin)`)) THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC `moi_s5c_sig1 c h jin jout' A Cout` INSIDE_NO_OVERLAP) THEN
  MP_TAC(ISPEC `moi_s5c_sig2 c h jin jin' Cin` OUTSIDE_NO_OVERLAP) THEN
  REPEAT DISCH_TAC THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CLOSED_UNION THEN ASM_SIMP_TAC[COMPACT_IMP_CLOSED];
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC BOUNDED_SUBSET THEN
    EXISTS_TAC `inside (moi_s5c_sig1 c h jin jout' A Cout)` THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[];
    MAP_EVERY UNDISCH_TAC
     [`inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
       moi_s5c_sig1 c h jin jout' A Cout = {}`;
      `outside (moi_s5c_sig2 c h jin jin' Cin) INTER
       moi_s5c_sig2 c h jin jin' Cin = {}`] THEN
    SET_TAC[];
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY UNDISCH_TAC
     [`A UNION Cout UNION moi_s5c_npl (c - h) jin' jout' SUBSET
       moi_s5c_sig1 c h jin jout' A Cout`;
      `Cin SUBSET moi_s5c_sig2 c h jin jin' Cin`] THEN
    SET_TAC[];
    UNDISCH_TAC `A UNION Cout UNION moi_s5c_npl (c - h) jin' jout' SUBSET
                 moi_s5c_sig1 c h jin jout' A Cout` THEN
    SET_TAC[];
    REWRITE_TAC[moi_s5c_npl; moi_s5c_rg] THEN MATCH_MP_TAC IMAGE_SUBSET THEN
    SET_TAC[];
    MATCH_MP_TAC MOI_S5C_LIFT_CONNECTED THEN
    UNDISCH_TAC `connected (moi_s5c_rgo jin' jout')` THEN REWRITE_TAC[moi_s5c_rgo];
    UNDISCH_TAC `~(moi_s5c_rgo jin' jout' = {})` THEN
    REWRITE_TAC[moi_s5c_rgo; IMAGE_EQ_EMPTY];
    REWRITE_TAC[moi_s5c_flat] THEN X_GEN_TAC `z:real^3` THEN DISCH_TAC THEN
    USE_THEN "hv" (X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC o
      C MATCH_MP (ASSUME `z IN IMAGE (moi_s35_lift (c - h))
                         (inside jout' DIFF (jin' UNION inside jin'))`)) THEN
    MAP_EVERY EXISTS_TAC [`ball(z:real^3,r)`; `{x:real^3 | x IN ball(z,r) /\ z$3 < x$3}`;
                          `{x:real^3 | x IN ball(z,r) /\ x$3 < z$3}`] THEN
    ASM_REWRITE_TAC[OPEN_BALL; CENTRE_IN_BALL] THEN
    MP_TAC(ISPECL [`z:real^3`; `r:real`] MOI_S5C_HALF_BALLS_CONVEX) THEN
    SIMP_TAC[CONVEX_CONNECTED];
    X_GEN_TAC `z:real^3` THEN DISCH_TAC THEN
    USE_THEN "hv" (X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC o
      C MATCH_MP (ASSUME `z IN IMAGE (moi_s35_lift (c - h))
                         (inside jout' DIFF (jin' UNION inside jin'))`)) THEN
    EXISTS_TAC `r:real` THEN ASM_REWRITE_TAC[];
    MAP_EVERY UNDISCH_TAC
     [`A UNION Cout UNION moi_s5c_npl (c - h) jin' jout' SUBSET
       moi_s5c_sig1 c h jin jout' A Cout`;
      `Cin SUBSET moi_s5c_sig2 c h jin jin' Cin`] THEN
    SET_TAC[];
    MATCH_MP_TAC COMPACT_IMP_BOUNDED THEN
    REPEAT(MATCH_MP_TAC COMPACT_UNION THEN CONJ_TAC) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC MOI_S5C_ANN_COMPL_CONNECTED THEN
    MAP_EVERY EXISTS_TAC [`IMAGE (moi_s35_lift (c - h)) jin'`;
                          `IMAGE (moi_s35_lift (c - h)) jout'`] THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `moi_s5c_npl (c - h) jin' jout' SUBSET
                  IMAGE (moi_s35_lift (c - h)) (inside jout' DIFF (jin' UNION inside jin'))
                  UNION Cin UNION Cout` MP_TAC THENL
     [REWRITE_TAC[moi_s5c_npl; SUBSET; MOI_S5C_IN_LIFT; IN_UNION] THEN
      X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
      UNDISCH_TAC `moi_s5c_proj x IN moi_s5c_rg jin' jout'` THEN
      UNDISCH_TAC `moi_s5c_rg jin' jout' = moi_s5c_rgo jin' jout' UNION jin' UNION jout'` THEN
      DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[moi_s5c_rgo; IN_UNION] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    MAP_EVERY UNDISCH_TAC
     [`inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
       moi_s5c_sig1 c h jin jout' A Cout = {}`;
      `outside (moi_s5c_sig2 c h jin jin' Cin) INTER
       moi_s5c_sig2 c h jin jin' Cin = {}`] THEN
    SET_TAC[]]);;

let MOI_S5C_ARCH_V_LEVEL_C = prove
 (`!c h jin jout jin' jout' A Cin Cout x.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout /\
     x IN inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
          outside (moi_s5c_sig2 c h jin jin' Cin) /\ x$3 = c
     ==> moi_s5c_proj x IN inside jout DIFF (jin UNION inside jin)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_LIFT_OUT) THEN
  SUBGOAL_THEN `~((x:real^3) IN moi_s5c_sig1 c h jin jout' A Cout) /\
                ~(x IN outside (moi_s5c_sig1 c h jin jout' A Cout))`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPEC `moi_s5c_sig1 c h jin jout' A Cout` INSIDE_NO_OVERLAP) THEN
    MP_TAC(ISPEC `moi_s5c_sig1 c h jin jout' A Cout` INSIDE_INTER_OUTSIDE) THEN
    UNDISCH_TAC `(x:real^3) IN inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                 outside (moi_s5c_sig2 c h jin jin' Cin)` THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(moi_s5c_proj x IN jin) /\ ~(moi_s5c_proj x IN inside jin) /\
                ~(moi_s5c_proj x IN jout) /\ ~(moi_s5c_proj x IN outside jout)`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN DISCH_TAC THENL
     [UNDISCH_TAC `~((x:real^3) IN moi_s5c_sig1 c h jin jout' A Cout)` THEN
      REWRITE_TAC[moi_s5c_sig1; IN_UNION; MOI_S5C_IN_LIFT] THEN ASM_REWRITE_TAC[];
      UNDISCH_TAC `~((x:real^3) IN moi_s5c_sig1 c h jin jout' A Cout)` THEN
      REWRITE_TAC[moi_s5c_sig1; IN_UNION; MOI_S5C_IN_LIFT] THEN ASM_REWRITE_TAC[];
      UNDISCH_TAC `~((x:real^3) IN moi_s5c_sig1 c h jin jout' A Cout)` THEN
      REWRITE_TAC[moi_s5c_sig1; IN_UNION] THEN
      SUBGOAL_THEN `(x:real^3) IN A` (fun th -> REWRITE_TAC[th]) THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `jout:real^2->bool`)) (concl th) &&
        can (find_term ((=) `Cout:real^3->bool`)) (concl th) &&
        can (find_term ((=) `A:real^3->bool`)) (concl th))) THEN
      ASM_SIMP_TAC[];
      UNDISCH_TAC `~((x:real^3) IN outside (moi_s5c_sig1 c h jin jout' A Cout))` THEN
      REWRITE_TAC[] THEN
      UNDISCH_TAC `IMAGE (moi_s35_lift c) (outside jout) SUBSET
                   outside (moi_s5c_sig1 c h jin jout' A Cout)` THEN
      REWRITE_TAC[SUBSET; MOI_S5C_IN_LIFT] THEN DISCH_THEN MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[IN_DIFF; IN_UNION] THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPEC `jout:real^2->bool` INSIDE_UNION_OUTSIDE) THEN
  UNDISCH_TAC `~(moi_s5c_proj x IN jout)` THEN
  UNDISCH_TAC `~(moi_s5c_proj x IN outside jout)` THEN SET_TAC[]);;

(* Summary of the region V of an arch.                                       *)

let MOI_S5C_ARCH_V = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> open (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
               outside (moi_s5c_sig2 c h jin jin' Cin)) /\
         connected (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                    outside (moi_s5c_sig2 c h jin jin' Cin)) /\
         ~(inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
           outside (moi_s5c_sig2 c h jin jin' Cin) = {}) /\
         inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
         outside (moi_s5c_sig2 c h jin jin' Cin) SUBSET moi_s5c_otube /\
         (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
          outside (moi_s5c_sig2 c h jin jin' Cin)) INTER
         moi_s5c_tor c h jin' jout' A Cin Cout = {} /\
         closure (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                  outside (moi_s5c_sig2 c h jin jin' Cin)) =
         (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
          outside (moi_s5c_sig2 c h jin jin' Cin)) UNION
         moi_s5c_tor c h jin' jout' A Cin Cout /\
         (!x. x IN inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                   outside (moi_s5c_sig2 c h jin jin' Cin) /\ x$3 = c
              ==> moi_s5c_proj x IN inside jout DIFF (jin UNION inside jin)) /\
         (!x. x IN inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                   outside (moi_s5c_sig2 c h jin jin' Cin)
              ==> c - h < x$3)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_V_CLOSURE) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_V_CONNECTED) THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_V_OTUBE) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_LEVELS) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REPEAT STRIP_TAC THEN MATCH_MP_TAC MOI_S5C_ARCH_V_LEVEL_C THEN
    MAP_EVERY EXISTS_TAC [`c:real`; `h:real`; `jin':real^2->bool`; `jout':real^2->bool`;
                          `A:real^3->bool`; `Cin:real^3->bool`; `Cout:real^3->bool`] THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[IN_INTER] THEN ASM_MESON_TAC[]]);;


(* ------------------------------------------------------------------------- *)
(* Tools for building the arch from a middle up region: lifted planar       *)
(* annuli, splitting of square-annulus regions, FF-images of regions.        *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_LIFT_ANN = prove
 (`!h (a:real^2->bool) j0 j1.
     pl_annulus_with_ends a j0 j1
     ==> pl_annulus_with_ends (IMAGE (moi_s35_lift h) a) (IMAGE (moi_s35_lift h) j0)
                              (IMAGE (moi_s35_lift h) j1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC MOI_S5C_ANN_TRANSFER THEN
  EXISTS_TAC `a:real^2->bool` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MOI_S5C_PL_EMBED THEN REPEAT CONJ_TAC THENL
   [ASM_MESON_TAC[MOI_S5C_ANN_COMPACT];
    MP_TAC(SPEC `h:real` MOI_S5C_LIFT_LINEAR) THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC STRIP_ASSUME_TAC) THEN
    MATCH_MP_TAC PL_MAP_ON_AFFINE THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
    ASM_MESON_TAC[MOI_S5C_ANN_POLYHEDRON];
    MESON_TAC[MOI_S5C_LIFT_INJ]]);;

(* Splitting a planar region between nested circles at an intermediate one. *)

let MOI_S5C_RG_UNION = prove
 (`!X M Y:real^2->bool.
     pl_sphere 1 X /\ pl_sphere 1 M /\ pl_sphere 1 Y /\
     X SUBSET inside M /\ M SUBSET inside Y
     ==> moi_s5c_rg X Y = moi_s5c_rg X M UNION moi_s5c_rg M Y /\
         moi_s5c_rg X M INTER moi_s5c_rg M Y = M /\
         X SUBSET inside Y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `M:real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
  MP_TAC(ISPECL [`M:real^2->bool`; `Y:real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
  ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  REWRITE_TAC[moi_s5c_rg] THEN
  REPEAT(POP_ASSUM MP_TAC) THEN SET_TAC[]);;

(* FF-images of planar regions inside the square annulus.                    *)

let MOI_S5C_FF_REGION = prove
 (`!B K FF GG Q c d0 X Y.
     moi_s5c_mset B K FF GG Q c d0 /\
     pl_sphere 1 X /\ pl_sphere 1 Y /\ X SUBSET inside Y /\
     moi_s5c_rg X Y SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                           interval(--vector[&1;&1]:real^2,vector[&1;&1])
     ==> IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y) SUBSET B /\
         compact (IMAGE FF (moi_s5c_rg X Y)) /\
         connected (IMAGE FF (moi_s5c_rgo X Y)) /\
         ~(IMAGE FF (moi_s5c_rgo X Y) = {}) /\
         connected (IMAGE FF (moi_s5c_rg X Y DIFF X)) /\
         connected (IMAGE FF (moi_s5c_rg X Y DIFF Y)) /\
         IMAGE FF (moi_s5c_rg X Y) SUBSET closure (IMAGE FF (moi_s5c_rgo X Y)) /\
         pl_annulus_with_ends (IMAGE FF (moi_s5c_rg X Y)) (IMAGE FF X) (IMAGE FF Y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  FIRST_ASSUM(ASSUME_TAC o CONJUNCT1 o REWRITE_RULE[moi_s5c_mset] o
    check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RG_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (ASSUME_TAC o SYM)
      (CONJUNCTS_THEN2 ASSUME_TAC STRIP_ASSUME_TAC)))))))) THEN
  ABBREV_TAC `A0 = interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                   interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
  SUBGOAL_THEN `moi_s5c_rgo X Y SUBSET moi_s5c_rg X Y` ASSUME_TAC THENL
   [UNDISCH_TAC `moi_s5c_rgo X Y UNION X UNION Y = moi_s5c_rg X Y` THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `closure (moi_s5c_rgo X Y) = moi_s5c_rg X Y` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
     [MATCH_MP_TAC CLOSURE_MINIMAL THEN ASM_SIMP_TAC[COMPACT_IMP_CLOSED];
      MP_TAC(ISPEC `moi_s5c_rgo X Y` CLOSURE_SUBSET) THEN
      MAP_EVERY UNDISCH_TAC [`X UNION Y SUBSET closure (moi_s5c_rgo X Y)`;
                             `moi_s5c_rgo X Y UNION X UNION Y = moi_s5c_rg X Y`] THEN
      SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(FF:real^2->real^3) continuous_on moi_s5c_rg X Y` ASSUME_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `A0:real^2->bool` THEN
    CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `DISJOINT (moi_s5c_rgo X Y) (X UNION Y)` ASSUME_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `connected (moi_s5c_rg X Y DIFF X) /\ connected (moi_s5c_rg X Y DIFF Y)`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC CONNECTED_INTERMEDIATE_CLOSURE THEN
    EXISTS_TAC `moi_s5c_rgo X Y` THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY UNDISCH_TAC [`moi_s5c_rgo X Y UNION X UNION Y = moi_s5c_rg X Y`;
                           `DISJOINT (moi_s5c_rgo X Y) (X UNION Y)`;
                           `closure (moi_s5c_rgo X Y) = moi_s5c_rg X Y`;
                           `X SUBSET inside (Y:real^2->bool)`] THEN
    MP_TAC(ISPEC `Y:real^2->bool` INSIDE_NO_OVERLAP) THEN
    SET_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [UNDISCH_TAC `moi_s5c_rg X Y SUBSET (A0:real^2->bool)` THEN
    UNDISCH_TAC `IMAGE (FF:real^2->real^3) A0 = B` THEN SET_TAC[];
    MATCH_MP_TAC COMPACT_CONTINUOUS_IMAGE THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `moi_s5c_rg X Y` THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[IMAGE_EQ_EMPTY];
    MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `moi_s5c_rg X Y` THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[];
    MATCH_MP_TAC CONNECTED_CONTINUOUS_IMAGE THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `moi_s5c_rg X Y` THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[];
    REWRITE_TAC[SYM(ASSUME `closure (moi_s5c_rgo X Y) = moi_s5c_rg X Y`)] THEN
    MATCH_MP_TAC IMAGE_CLOSURE_SUBSET THEN
    REWRITE_TAC[CLOSED_CLOSURE; CLOSURE_SUBSET] THEN
    REWRITE_TAC[ASSUME `closure (moi_s5c_rgo X Y) = moi_s5c_rg X Y`] THEN
    FIRST_ASSUM ACCEPT_TAC;
    MATCH_MP_TAC MOI_S5C_ANN_TRANSFER THEN
    MAP_EVERY EXISTS_TAC [`moi_s5c_rg X Y`; `GG:real^3->real^2`] THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC MOI_S5C_PLH_RESTRICT THEN
    EXISTS_TAC `A0:real^2->bool` THEN EXISTS_TAC `B:real^3->bool` THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC LOCALLY_POLYHEDRAL_PL_POLYHEDRON THEN
    MATCH_MP_TAC MOI_S5C_ANN_POLYHEDRON THEN
    MAP_EVERY EXISTS_TAC [`X:real^2->bool`; `Y:real^2->bool`] THEN
    FIRST_ASSUM ACCEPT_TAC]);;

let MOI_S5C_RG_IN_A0 = prove
 (`!X Y:real^2->bool.
     pl_sphere 1 X /\ pl_sphere 1 Y /\
     Y SUBSET interval[--vector[&2;&2],vector[&2;&2]] DIFF
              interval(--vector[&1;&1],vector[&1;&1]) /\
     interval[--vector[&1;&1],vector[&1;&1]] SUBSET inside X
     ==> moi_s5c_rg X Y SUBSET interval[--vector[&2;&2],vector[&2;&2]] DIFF
                               interval(--vector[&1;&1],vector[&1;&1])`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `inside Y SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]]`
  ASSUME_TAC THENL
   [MATCH_MP_TAC INSIDE_SUBSET_CONVEX THEN REWRITE_TAC[CONVEX_INTERVAL] THEN
    UNDISCH_TAC `Y SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                 interval(--vector[&1;&1],vector[&1;&1])` THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`--vector[&1;&1]:real^2`; `vector[&1;&1]:real^2`]
    INTERVAL_OPEN_SUBSET_CLOSED) THEN
  REWRITE_TAC[moi_s5c_rg] THEN
  MAP_EVERY UNDISCH_TAC
   [`Y SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
     interval(--vector[&1;&1],vector[&1;&1])`;
    `interval[--vector[&1;&1]:real^2,vector[&1;&1]] SUBSET inside X`;
    `inside Y SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]]`] THEN
  SET_TAC[]);;

let MOI_S5C_HALF_REPARAM = prove
 (`!(Q:real^3->real->real^3) J.
     {Q x (&1 * u) | x IN J /\ &0 < u /\ u < &1} = {Q x t | x IN J /\ &0 < t /\ t < &1} /\
     {Q x (-- &1 * u) | x IN J /\ &0 < u /\ u < &1} =
     {Q x t | x IN J /\ -- &1 < t /\ t < &0}`,
  REPEAT GEN_TAC THEN CONJ_TAC THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN X_GEN_TAC `y:real^3` THEN EQ_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC)) THEN
  EXISTS_TAC `x:real^3` THENL
   [EXISTS_TAC `u:real` THEN ASM_REWRITE_TAC[REAL_MUL_LID];
    EXISTS_TAC `u:real` THEN ASM_REWRITE_TAC[REAL_MUL_LID];
    EXISTS_TAC `-- &1 * u` THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY UNDISCH_TAC [`&0 < u`; `u < &1`] THEN REAL_ARITH_TAC;
    EXISTS_TAC `--u` THEN ASM_REWRITE_TAC[REAL_ARITH `-- &1 * --u = u`] THEN
    MAP_EVERY UNDISCH_TAC [`-- &1 < u`; `u < &0`] THEN REAL_ARITH_TAC]);;

let MOI_S5C_FFGG = prove
 (`!B K FF GG Q c d0 S.
     moi_s5c_mset B K FF GG Q c d0 /\ S SUBSET B
     ==> IMAGE (FF:real^2->real^3) (IMAGE (GG:real^3->real^2) S) = S`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  REWRITE_TAC[GSYM IMAGE_o] THEN
  MATCH_MP_TAC EQ_TRANS THEN EXISTS_TAC `IMAGE (\x:real^3. x) S` THEN CONJ_TAC THENL
   [MATCH_MP_TAC IMAGE_EQ THEN REWRITE_TAC[o_THM] THEN
    UNDISCH_TAC `S SUBSET (B:real^3->bool)` THEN REWRITE_TAC[SUBSET] THEN ASM_MESON_TAC[];
    REWRITE_TAC[IMAGE_ID]]);;

(* Strips of the collar are annuli.                                          *)

let MOI_S5C_STRIP_ANN = prove
 (`!B K FF GG Q c d0 J sg s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c} /\ (sg = &1 \/ sg = -- &1) /\
     &0 < s /\ s < &1
     ==> pl_annulus_with_ends {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 <= u /\ u <= s}
           J (moi_s5c_sec Q J (sg * s)) /\
         (IMAGE (GG:real^3->real^2) {Q x (sg * u) | x IN J /\ &0 < u /\ u < &1} SUBSET
            outside (IMAGE GG J) \/
          IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < &1} SUBSET inside (IMAGE GG J))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))))) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
    MOI_S5C_HALF_SIDES) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(LABEL_TAC "hs")] THEN
  SUBGOAL_THEN
   `IMAGE (GG:real^3->real^2) {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 < u /\ u < &1}
      SUBSET outside (IMAGE GG J) \/
    IMAGE GG {Q x (sg * u) | x IN J /\ &0 < u /\ u < &1} SUBSET inside (IMAGE GG J)`
  ASSUME_TAC THENL
   [REMOVE_THEN "hs" MP_TAC THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN SUBST1_TAC o check (fun th ->
      is_disj(concl th) && can (find_term ((=) `-- &1`)) (concl th) &&
      not(can (find_term ((=) `GG:real^3->real^2`)) (concl th)))) THEN
    REWRITE_TAC[MOI_S5C_HALF_REPARAM] THEN MESON_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
    `sg:real`; `s:real`] MOI_S5C_STRIP_REGION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  SUBGOAL_THEN `abs(sg * s) <= &1` ASSUME_TAC THENL
   [FIRST_X_ASSUM(DISJ_CASES_THEN SUBST1_TAC o check (fun th ->
      is_disj(concl th) && can (find_term ((=) `-- &1`)) (concl th) &&
      not(can (find_term ((=) `GG:real^3->real^2`)) (concl th)))) THEN
    MAP_EVERY UNDISCH_TAC [`&0 < s`; `s < &1`] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
    `sg * s`] MOI_S5C_SEC_BASIC) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
    `&0`] MOI_S5C_SEC_BASIC) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
    `sg * s`] MOI_S5C_SEC_SQ_ESS) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
    `&0`] MOI_S5C_SEC_SQ_ESS) THEN
  ASM_REWRITE_TAC[REAL_ABS_0; REAL_POS] THEN
  DISCH_TAC THEN DISCH_TAC THEN
  DISCH_THEN(STRIP_ASSUME_TAC) THEN DISCH_THEN(STRIP_ASSUME_TAC) THEN
  FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th ->
    concl th = `moi_s5c_sec (Q:real^3->real->real^3) J (&0) = J`)) THEN
  SUBGOAL_THEN `IMAGE (FF:real^2->real^3) (IMAGE (GG:real^3->real^2) J) = J /\
                IMAGE FF (IMAGE GG (moi_s5c_sec (Q:real^3->real->real^3) J (sg * s))) =
                moi_s5c_sec Q J (sg * s)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_FFGG THEN
    MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `K:(real^3->bool)->bool`;
      `Q:real^3->real->real^3`; `c:real`; `d0:real`] THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `J IN components {x:real^3 | x IN B /\ x$3 = c}` THEN
    DISCH_THEN(MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN SET_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th -> is_disj(concl th) &&
    can (find_term ((=) `GG:real^3->real^2`)) (concl th))) THENL
   [FIRST_X_ASSUM(MP_TAC o C MATCH_MP (ASSUME
      `IMAGE (GG:real^3->real^2) {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 < u /\ u < &1}
       SUBSET outside (IMAGE GG J)`) o CONJUNCT1 o check (fun th ->
      is_conj(concl th) && is_imp(lhand(concl th)))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (SUBST1_TAC o SYM)) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `IMAGE (GG:real^3->real^2) J`;
      `IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) J (sg * s))`]
      MOI_S5C_FF_REGION) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOI_S5C_RG_IN_A0 THEN
      ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) J (sg * s))
        SUBSET (interval[--vector[&2;&2],vector[&2;&2]] DIFF
                interval(--vector[&1;&1],vector[&1;&1])) DIFF
               (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]) UNION
                relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))` THEN
      SET_TAC[];
      ASM_SIMP_TAC[]];
    FIRST_X_ASSUM(MP_TAC o C MATCH_MP (ASSUME
      `IMAGE (GG:real^3->real^2) {(Q:real^3->real->real^3) x (sg * u) | x IN J /\ &0 < u /\ u < &1}
       SUBSET inside (IMAGE GG J)`) o CONJUNCT2 o check (fun th ->
      is_conj(concl th) && is_imp(lhand(concl th)))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (SUBST1_TAC o SYM)) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) J (sg * s))`;
      `IMAGE (GG:real^3->real^2) J`]
      MOI_S5C_FF_REGION) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOI_S5C_RG_IN_A0 THEN
      ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `IMAGE (GG:real^3->real^2) J
        SUBSET (interval[--vector[&2;&2],vector[&2;&2]] DIFF
                interval(--vector[&1;&1],vector[&1;&1])) DIFF
               (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]) UNION
                relative_frontier(interval[--vector[&2;&2],vector[&2;&2]]))` THEN
      SET_TAC[];
      ASM_SIMP_TAC[] THEN MESON_TAC[MOI_S5C_ANN_SWAP]]]);;

(* Per-circle facts for the arch: the circle, its section at -s and the     *)
(* downward strip between them.                                              *)

let MOI_S5C_CIRCLE_ARCH = prove
 (`!B K FF GG Q c d0 J s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c} /\ &0 < s /\ s < &1
     ==> pl_sphere 1 (IMAGE moi_s5c_proj J) /\
         J = IMAGE (moi_s35_lift c) (IMAGE moi_s5c_proj J) /\
         (!y. max (abs(y$1)) (abs(y$2)) <= &3 / &16 ==> y IN inside (IMAGE moi_s5c_proj J)) /\
         IMAGE moi_s5c_proj J SUBSET {y:real^2 | max (abs(y$1)) (abs(y$2)) < &5 / &16} /\
         pl_sphere 1 (IMAGE moi_s5c_proj (moi_s5c_sec Q J (-- &1 * s))) /\
         moi_s5c_sec Q J (-- &1 * s) =
           IMAGE (moi_s35_lift (c - s * d0))
             (IMAGE moi_s5c_proj (moi_s5c_sec Q J (-- &1 * s))) /\
         (!y. max (abs(y$1)) (abs(y$2)) <= &3 / &16
              ==> y IN inside (IMAGE moi_s5c_proj (moi_s5c_sec Q J (-- &1 * s)))) /\
         IMAGE moi_s5c_proj (moi_s5c_sec Q J (-- &1 * s)) SUBSET
           {y:real^2 | max (abs(y$1)) (abs(y$2)) < &5 / &16} /\
         pl_annulus_with_ends
           {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J /\ &0 <= u /\ u <= s}
           (IMAGE (moi_s35_lift c) (IMAGE moi_s5c_proj J))
           (IMAGE (moi_s35_lift (c - s * d0))
              (IMAGE moi_s5c_proj (moi_s5c_sec Q J (-- &1 * s)))) /\
         {Q x (-- &1 * u) | x IN J /\ &0 <= u /\ u <= s} SUBSET moi_s5c_otube /\
         (!x. x IN {Q x (-- &1 * u) | x IN J /\ &0 <= u /\ u <= s}
              ==> c - s * d0 <= x$3 /\ x$3 <= c) /\
         (!x. x IN {Q x (-- &1 * u) | x IN J /\ &0 <= u /\ u <= s} /\ x$3 = c
              ==> x IN IMAGE (moi_s35_lift c) (IMAGE moi_s5c_proj J)) /\
         (!x. x IN {Q x (-- &1 * u) | x IN J /\ &0 <= u /\ u <= s} /\ x$3 = c - s * d0
              ==> x IN IMAGE (moi_s35_lift (c - s * d0))
                         (IMAGE moi_s5c_proj (moi_s5c_sec Q J (-- &1 * s))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_COLLAR_FACTS) THEN
  SUBGOAL_THEN `abs(-- &1 * s) <= &1` ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`&0 < s`; `s < &1`] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
    MOI_S5C_CIRCLE_ESS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
    `-- &1 * s`] MOI_S5C_SEC_BASIC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
    `-- &1 * s`] MOI_S5C_SEC_PLANE_ESS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
    `-- &1`; `s:real`] MOI_S5C_STRIP_ANN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o CONJUNCT1)] THEN
  SUBGOAL_THEN `c + (-- &1 * s) * d0 = c - s * d0` (fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th]))
  THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `J SUBSET {x:real^3 | x IN B /\ x$3 = c}` ASSUME_TAC THENL
   [MATCH_MP_TAC IN_COMPONENTS_SUBSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `{x:real^3 | x IN B /\ x$3 = c} SUBSET
                {x | &3 / &16 < moi_s35_n x /\ moi_s35_n x < &5 / &16 /\ x$3 = c}`
  ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
    REWRITE_TAC[moi_s5c_mset] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!x u. x IN J /\ &0 <= u /\ u <= s
                ==> (Q:real^3->real->real^3) x (-- &1 * u) IN B /\
                    (Q x (-- &1 * u))$3 = c - u * d0 /\
                    Q x (-- &1 * u) IN moi_s5c_otube`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `x:real^3`;
      `-- &1 * u`] MOI_S5C_SLAB_FACT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `J SUBSET {x:real^3 | x IN B /\ x$3 = c}` THEN
      UNDISCH_TAC `(x:real^3) IN J` THEN REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
      DISCH_TAC THEN DISCH_THEN(MP_TAC o SPEC `x:real^3`) THEN ASM_REWRITE_TAC[] THEN
      DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
      MAP_EVERY UNDISCH_TAC [`&0 <= u`; `u <= s`; `s < &1`] THEN REAL_ARITH_TAC;
      SIMP_TAC[] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `!u. &0 <= u /\ u <= s ==> &0 <= u * d0 /\ u * d0 <= s * d0`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL; MATCH_MP_TAC REAL_LE_RMUL] THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `&0 < d0` THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  FIRST
   [(REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; IN_ELIM_THM; MOI_S5C_PROJ_FACTS] THEN
     X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
     MAP_EVERY UNDISCH_TAC [`J SUBSET {x:real^3 | x IN B /\ x$3 = c}`;
       `{x:real^3 | x IN B /\ x$3 = c} SUBSET
        {x | &3 / &16 < moi_s35_n x /\ moi_s35_n x < &5 / &16 /\ x$3 = c}`;
       `(x:real^3) IN J`] THEN
     REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]) THEN NO_TAC;
    (REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; IN_ELIM_THM; MOI_S5C_PROJ_FACTS] THEN
     X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
     UNDISCH_TAC `moi_s5c_sec (Q:real^3->real->real^3) J (-- &1 * s) SUBSET moi_s5c_otube` THEN
     UNDISCH_TAC `(x:real^3) IN moi_s5c_sec Q J (-- &1 * s)` THEN
     REWRITE_TAC[SUBSET; moi_s5c_otube; IN_ELIM_THM] THEN MESON_TAC[]) THEN NO_TAC;
    (SUBGOAL_THEN `IMAGE (moi_s35_lift c) (IMAGE moi_s5c_proj J) = J` SUBST1_TAC THENL
      [CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
     SUBGOAL_THEN `IMAGE (moi_s35_lift (c - s * d0))
                    (IMAGE moi_s5c_proj (moi_s5c_sec Q J (-- &1 * s))) =
                   moi_s5c_sec (Q:real^3->real->real^3) J (-- &1 * s)` SUBST1_TAC THENL
      [CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
     FIRST_ASSUM ACCEPT_TAC) THEN NO_TAC;
    (REWRITE_TAC[SUBSET; FORALL_IN_GSPEC] THEN
     MAP_EVERY X_GEN_TAC [`x:real^3`; `u:real`] THEN STRIP_TAC THEN
     FIRST_X_ASSUM(MP_TAC o SPECL [`x:real^3`; `u:real`] o check (fun th ->
       is_forall(concl th) && can (find_term ((=) `moi_s5c_otube`)) (concl th) &&
       can (find_term ((=) `u:real`)) (concl th))) THEN
     ASM_REWRITE_TAC[] THEN SIMP_TAC[]) THEN NO_TAC;
    (REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `z:real^3` THEN
     DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real`
       STRIP_ASSUME_TAC)) ASSUME_TAC) THEN
     FIRST_X_ASSUM(MP_TAC o SPECL [`x:real^3`; `u:real`] o check (fun th ->
       is_forall(concl th) && can (find_term ((=) `moi_s5c_otube`)) (concl th) &&
       can (find_term ((=) `u:real`)) (concl th))) THEN
     ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
     SUBGOAL_THEN `u = &0` SUBST_ALL_TAC THENL
      [UNDISCH_TAC `(z:real^3)$3 = c` THEN ASM_REWRITE_TAC[] THEN
       REWRITE_TAC[REAL_ARITH `c - u * d0 = c <=> u * d0 = &0`; REAL_ENTIRE] THEN
       UNDISCH_TAC `&0 < d0` THEN REAL_ARITH_TAC;
       ALL_TAC] THEN
     ASM_REWRITE_TAC[REAL_MUL_RZERO] THEN
     UNDISCH_TAC `J = IMAGE (moi_s35_lift c) (IMAGE moi_s5c_proj (J:real^3->bool))` THEN
     DISCH_THEN(fun th -> GEN_REWRITE_TAC (RAND_CONV) [SYM th]) THEN
     SUBGOAL_THEN `(Q:real^3->real->real^3) x (&0) = x` SUBST1_TAC THENL
      [FIRST_X_ASSUM MATCH_MP_TAC THEN
       UNDISCH_TAC `J SUBSET {x:real^3 | x IN B /\ x$3 = c}` THEN
       UNDISCH_TAC `(x:real^3) IN J` THEN SET_TAC[];
       ASM_REWRITE_TAC[]]) THEN NO_TAC;
    (REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `z:real^3` THEN
     DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real`
       STRIP_ASSUME_TAC)) ASSUME_TAC) THEN
     FIRST_X_ASSUM(MP_TAC o SPECL [`x:real^3`; `u:real`] o check (fun th ->
       is_forall(concl th) && can (find_term ((=) `moi_s5c_otube`)) (concl th) &&
       can (find_term ((=) `u:real`)) (concl th))) THEN
     ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
     SUBGOAL_THEN `u:real = s` SUBST_ALL_TAC THENL
      [UNDISCH_TAC `(z:real^3)$3 = c - s * d0` THEN ASM_REWRITE_TAC[] THEN
       REWRITE_TAC[REAL_ARITH `c - u * d0 = c - s * d0 <=> u * d0 = s * d0`] THEN
       REWRITE_TAC[REAL_EQ_MUL_RCANCEL] THEN
       UNDISCH_TAC `&0 < d0` THEN REAL_ARITH_TAC;
       ALL_TAC] THEN
     UNDISCH_TAC `moi_s5c_sec Q J (-- &1 * s) =
                  IMAGE (moi_s35_lift (c - s * d0))
                    (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J (-- &1 * s)))` THEN
     DISCH_THEN(fun th -> GEN_REWRITE_TAC (RAND_CONV) [SYM th]) THEN
     ASM_REWRITE_TAC[moi_s5c_sec; IN_IMAGE] THEN EXISTS_TAC `x:real^3` THEN
     ASM_REWRITE_TAC[]) THEN NO_TAC;
    (REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `z:real^3` THEN
     DISCH_THEN(X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC)) THEN
     FIRST_X_ASSUM(MP_TAC o SPECL [`x:real^3`; `u:real`] o check (fun th ->
       is_forall(concl th) && can (find_term ((=) `moi_s5c_otube`)) (concl th) &&
       can (find_term ((=) `u:real`)) (concl th))) THEN
     ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
     FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o check (fun th ->
       is_forall(concl th) && can (find_term ((=) `s * d0`)) (concl th))) THEN
     ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC) THEN NO_TAC]);;

(* The arch configuration built from two nested circles of B joined by an  *)
(* annulus above the level c, with the downward strips to the level c-h.   *)

let MOI_S5C_ARCH_FROM = prove
 (`!B K FF GG Q c d0 J1 J2 A s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J1 IN components {x | x IN B /\ x$3 = c} /\ J2 IN components {x | x IN B /\ x$3 = c} /\
     ~(J1 = J2) /\ &0 < s /\ s < &1 /\
     IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J2) /\
     pl_annulus_with_ends A J1 J2 /\ A SUBSET moi_s35_ttube /\
     (!x. x IN A ==> c <= x$3) /\ (!x. x IN A /\ x$3 = c ==> x IN J1 UNION J2)
     ==> moi_s5c_arch c (s * d0) (IMAGE moi_s5c_proj J1) (IMAGE moi_s5c_proj J2)
           (IMAGE moi_s5c_proj (moi_s5c_sec Q J1 (-- &1 * s)))
           (IMAGE moi_s5c_proj (moi_s5c_sec Q J2 (-- &1 * s)))
           A {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s}
             {Q x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J1:real^3->bool`;
    `s:real`] MOI_S5C_CIRCLE_ARCH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J2:real^3->bool`;
    `s:real`] MOI_S5C_CIRCLE_ARCH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J1:real^3->bool`;
    `J2:real^3->bool`; `-- &1 * s`] MOI_S5C_SEC_PLANE_NEST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MAP_EVERY UNDISCH_TAC [`&0 < s`; `s < &1`] THEN REAL_ARITH_TAC;
    DISCH_TAC] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_COLLAR_FACTS) THEN
  SUBGOAL_THEN `abs c <= &1 / &512 /\ d0 <= &1 / &64` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
    REWRITE_TAC[moi_s5c_mset] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[moi_s5c_arch] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  FIRST
   [(MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[]) THEN NO_TAC;
    (MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `d0:real` THEN ASM_REWRITE_TAC[] THEN
     GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_LID] THEN MATCH_MP_TAC REAL_LE_RMUL THEN
     MAP_EVERY UNDISCH_TAC [`s < &1`; `&0 < d0`] THEN REAL_ARITH_TAC) THEN NO_TAC;
    (FIRST_X_ASSUM(SUBST1_TAC o SYM o
       check (fun th -> concl th =
         `J1 = IMAGE (moi_s35_lift c) (IMAGE moi_s5c_proj (J1:real^3->bool))`)) THEN
     FIRST_X_ASSUM(SUBST1_TAC o SYM o
       check (fun th -> concl th =
         `J2 = IMAGE (moi_s35_lift c) (IMAGE moi_s5c_proj (J2:real^3->bool))`)) THEN
     FIRST_ASSUM ACCEPT_TAC) THEN NO_TAC;
    (REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; IN_ELIM_THM] THEN
     X_GEN_TAC `z:real^3` THEN
     DISCH_THEN(CONJUNCTS_THEN2
       (X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC))
       (X_CHOOSE_THEN `y:real^3` (X_CHOOSE_THEN `v:real` STRIP_ASSUME_TAC))) THEN
     SUBGOAL_THEN `(x:real^3) IN B /\ x$3 = c /\ (y:real^3) IN B /\ y$3 = c`
     STRIP_ASSUME_TAC THENL
      [MP_TAC(ISPECL [`{x:real^3 | x IN B /\ x$3 = c}`; `J1:real^3->bool`]
         IN_COMPONENTS_SUBSET) THEN
       MP_TAC(ISPECL [`{x:real^3 | x IN B /\ x$3 = c}`; `J2:real^3->bool`]
         IN_COMPONENTS_SUBSET) THEN
       ASM_REWRITE_TAC[] THEN
       MAP_EVERY UNDISCH_TAC [`(x:real^3) IN J1`; `(y:real^3) IN J2`] THEN
       REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[];
       ALL_TAC] THEN
     SUBGOAL_THEN `(Q:real^3->real->real^3) x (-- &1 * u) = Q y (-- &1 * v)` ASSUME_TAC THENL
      [MAP_EVERY UNDISCH_TAC [`z = (Q:real^3->real->real^3) x (-- &1 * u)`;
                              `z = (Q:real^3->real->real^3) y (-- &1 * v)`] THEN
       MESON_TAC[];
       ALL_TAC] THEN
     SUBGOAL_THEN `(x:real^3) = y` ASSUME_TAC THENL
      [FIRST_X_ASSUM(MP_TAC o SPECL [`x:real^3`; `-- &1 * u`; `y:real^3`; `-- &1 * v`] o
         check (fun th -> is_forall(concl th) &&
           can (find_term ((=) `(Q:real^3->real->real^3) x' t'`)) (concl th))) THEN
       ASM_REWRITE_TAC[] THEN
       ANTS_TAC THENL
        [MAP_EVERY UNDISCH_TAC [`&0 <= u`; `u <= s`; `&0 <= v`; `v <= s`; `s < &1`] THEN
         REAL_ARITH_TAC;
         SIMP_TAC[]];
       ALL_TAC] THEN
     MP_TAC(ISPECL [`{x:real^3 | x IN B /\ x$3 = c}`; `J1:real^3->bool`; `J2:real^3->bool`]
       COMPONENTS_NONOVERLAP) THEN
     ASM_REWRITE_TAC[] THEN
     MAP_EVERY UNDISCH_TAC [`(x:real^3) IN J1`; `(y:real^3) IN J2`; `(x:real^3) = y`] THEN
     SET_TAC[]) THEN NO_TAC]);;

(* A middle up region given by its two circles, inner Ja and outer Jb in   *)
(* the square-annulus order.                                                 *)

let moi_s5c_mup = new_definition
 `moi_s5c_mup (B:real^3->bool) (FF:real^2->real^3) (GG:real^3->real^2) c Ja Jb <=>
    Ja IN components {x | x IN B /\ x$3 = c} /\ Jb IN components {x | x IN B /\ x$3 = c} /\
    moi_s5c_cons B GG c (IMAGE GG Ja) (IMAGE GG Jb) /\
    moi_s5c_sd FF c (&1) (IMAGE GG Ja) (IMAGE GG Jb)`;;

let MOI_S5C_MUP_FACTS = prove
 (`!B K FF GG Q c d0 Ja Jb.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb
     ==> ~(Ja = Jb) /\
         pl_annulus_with_ends (IMAGE FF (moi_s5c_rg (IMAGE GG Ja) (IMAGE GG Jb))) Ja Jb /\
         IMAGE FF (moi_s5c_rg (IMAGE GG Ja) (IMAGE GG Jb)) SUBSET moi_s35_ttube /\
         IMAGE FF (moi_s5c_rg (IMAGE GG Ja) (IMAGE GG Jb)) SUBSET B /\
         (!x. x IN IMAGE FF (moi_s5c_rg (IMAGE GG Ja) (IMAGE GG Jb)) ==> c <= x$3) /\
         (!x. x IN IMAGE FF (moi_s5c_rg (IMAGE GG Ja) (IMAGE GG Jb)) /\ x$3 = c
              ==> x IN Ja UNION Jb) /\
         (IMAGE moi_s5c_proj Ja SUBSET inside (IMAGE moi_s5c_proj Jb) \/
          IMAGE moi_s5c_proj Jb SUBSET inside (IMAGE moi_s5c_proj Ja))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[moi_s5c_mup] THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  SUBGOAL_THEN `~(Ja:real^3->bool = Jb)` ASSUME_TAC THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    UNDISCH_TAC `moi_s5c_cons B (GG:real^3->real^2) c (IMAGE GG Jb) (IMAGE GG Jb)` THEN
    REWRITE_TAC[moi_s5c_cons] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`]
      MOI_S5C_EXT_ORDER) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `IMAGE (GG:real^3->real^2) Ja`; `IMAGE (GG:real^3->real^2) Jb`] MOI_S5C_REGION_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  SUBGOAL_THEN `IMAGE (FF:real^2->real^3) (IMAGE (GG:real^3->real^2) Ja) = Ja /\
                IMAGE (FF:real^2->real^3) (IMAGE (GG:real^3->real^2) Jb) = Jb`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_FFGG THEN
    MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `K:(real^3->bool)->bool`;
      `Q:real^3->real->real^3`; `c:real`; `d0:real`] THEN
    ASM_REWRITE_TAC[] THENL
     [UNDISCH_TAC `Ja IN components {x:real^3 | x IN B /\ x$3 = c}`;
      UNDISCH_TAC `Jb IN components {x:real^3 | x IN B /\ x$3 = c}`] THEN
    DISCH_THEN(MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN SET_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [UNDISCH_TAC `pl_annulus_with_ends
      (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb)))
      (IMAGE FF (IMAGE GG Ja)) (IMAGE FF (IMAGE GG Jb))` THEN
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_END_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `X1:real^2->bool` (X_CHOOSE_THEN `Ym:real^2->bool`
      (MP_TAC o last o CONJUNCTS))) THEN
    DISCH_THEN(MP_TAC o SPECL [`&1`; `IMAGE (GG:real^3->real^2) Ja`;
                               `IMAGE (GG:real^3->real^2) Jb`]) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`]
      MOI_S5C_ADJ_EXISTS) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Jb:real^3->bool`]
      MOI_S5C_ADJ_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    FIRST_ASSUM ACCEPT_TAC;
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `&1`;
      `IMAGE (GG:real^3->real^2) Ja`; `IMAGE (GG:real^3->real^2) Jb`] MOI_S5C_REGION_SIDE) THEN
    ASM_REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[REAL_MUL_LID; REAL_SUB_LE];
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `IMAGE (GG:real^3->real^2) Ja`; `IMAGE (GG:real^3->real^2) Jb`] MOI_S5C_CONS_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
    MP_TAC(ISPECL [`IMAGE (GG:real^3->real^2) Ja`; `IMAGE (GG:real^3->real^2) Jb`]
      MOI_S5C_RG_EQ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST1_TAC] THEN
    UNDISCH_TAC `moi_s5c_sd (FF:real^2->real^3) c (&1) (IMAGE (GG:real^3->real^2) Ja)
                   (IMAGE GG Jb)` THEN
    REWRITE_TAC[moi_s5c_sd; IMAGE_UNION; IN_UNION] THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3`) THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`]
      MOI_S5C_CIRCLE_ESS) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Jb:real^3->bool`]
      MOI_S5C_CIRCLE_ESS) THEN
    ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
      `Jb:real^3->bool`; `IMAGE moi_s5c_proj (Ja:real^3->bool)`;
      `IMAGE moi_s5c_proj (Jb:real^3->bool)`] MOI_S5C_PLANE_NEST) THEN
    ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; MESON_TAC[]]]);;

let MOI_S5C_MUP_ARCH = prove
 (`!B K FF GG Q c d0 Ja Jb s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     &0 < s /\ s < &1
     ==> (IMAGE moi_s5c_proj Ja SUBSET inside (IMAGE moi_s5c_proj Jb)
          ==> moi_s5c_arch c (s * d0) (IMAGE moi_s5c_proj Ja) (IMAGE moi_s5c_proj Jb)
                (IMAGE moi_s5c_proj (moi_s5c_sec Q Ja (-- &1 * s)))
                (IMAGE moi_s5c_proj (moi_s5c_sec Q Jb (-- &1 * s)))
                (IMAGE FF (moi_s5c_rg (IMAGE GG Ja) (IMAGE GG Jb)))
                {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s}
                {Q x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s}) /\
         (IMAGE moi_s5c_proj Jb SUBSET inside (IMAGE moi_s5c_proj Ja)
          ==> moi_s5c_arch c (s * d0) (IMAGE moi_s5c_proj Jb) (IMAGE moi_s5c_proj Ja)
                (IMAGE moi_s5c_proj (moi_s5c_sec Q Jb (-- &1 * s)))
                (IMAGE moi_s5c_proj (moi_s5c_sec Q Ja (-- &1 * s)))
                (IMAGE FF (moi_s5c_rg (IMAGE GG Ja) (IMAGE GG Jb)))
                {Q x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s}
                {Q x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s})`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mup] o
    check (MOI_S5C_HEAD "moi_s5c_mup")) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
    `Jb:real^3->bool`] MOI_S5C_MUP_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  CONJ_TAC THEN DISCH_TAC THEN MATCH_MP_TAC MOI_S5C_ARCH_FROM THEN
  MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`] THEN
  ASM_REWRITE_TAC[] THEN
  (CONJ_TAC THENL
    [MATCH_MP_TAC MOI_S5C_ANN_SWAP THEN ASM_REWRITE_TAC[];
     ONCE_REWRITE_TAC[UNION_COMM] THEN ASM_REWRITE_TAC[]]));;

let MOI_S5C_GGFF = prove
 (`!B K FF GG Q c d0 S.
     moi_s5c_mset B K FF GG Q c d0 /\
     S SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
              interval(--vector[&1;&1]:real^2,vector[&1;&1])
     ==> IMAGE (GG:real^3->real^2) (IMAGE (FF:real^2->real^3) S) = S`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  REWRITE_TAC[GSYM IMAGE_o] THEN
  MATCH_MP_TAC EQ_TRANS THEN EXISTS_TAC `IMAGE (\x:real^2. x) S` THEN CONJ_TAC THENL
   [MATCH_MP_TAC IMAGE_EQ THEN REWRITE_TAC[o_THM] THEN
    UNDISCH_TAC `S SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                 interval(--vector[&1;&1]:real^2,vector[&1;&1])` THEN
    REWRITE_TAC[SUBSET] THEN ASM_MESON_TAC[];
    REWRITE_TAC[IMAGE_ID]]);;

(* The square-annulus picture of a middle up region and its two downward   *)
(* strips.                                                                   *)

let MOI_S5C_MUP_A0 = prove
 (`!B K FF GG Q c d0 Ja Jb s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     &0 < s /\ s < &1
     ==> pl_sphere 1 (IMAGE (GG:real^3->real^2) Ja) /\ pl_sphere 1 (IMAGE GG Jb) /\
         pl_sphere 1 (IMAGE GG (moi_s5c_sec Q Ja (-- &1 * s))) /\
         pl_sphere 1 (IMAGE GG (moi_s5c_sec Q Jb (-- &1 * s))) /\
         IMAGE GG (moi_s5c_sec Q Ja (-- &1 * s)) SUBSET inside (IMAGE GG Ja) /\
         IMAGE GG Ja SUBSET inside (IMAGE GG Jb) /\
         IMAGE GG Jb SUBSET inside (IMAGE GG (moi_s5c_sec Q Jb (-- &1 * s))) /\
         IMAGE (FF:real^2->real^3)
           (moi_s5c_rg (IMAGE GG (moi_s5c_sec Q Ja (-- &1 * s))) (IMAGE GG Ja)) =
           {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s} /\
         IMAGE FF (moi_s5c_rg (IMAGE GG Jb) (IMAGE GG (moi_s5c_sec Q Jb (-- &1 * s)))) =
           {Q x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s} /\
         IMAGE GG (moi_s5c_sec Q Ja (-- &1 * s)) SUBSET
           (interval[--vector[&2;&2],vector[&2;&2]] DIFF
            interval(--vector[&1;&1],vector[&1;&1])) DIFF
           (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]) UNION
            relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])) /\
         IMAGE GG (moi_s5c_sec Q Jb (-- &1 * s)) SUBSET
           (interval[--vector[&2;&2],vector[&2;&2]] DIFF
            interval(--vector[&1;&1],vector[&1;&1])) DIFF
           (relative_frontier(interval[--vector[&1;&1],vector[&1;&1]]) UNION
            relative_frontier(interval[--vector[&2;&2],vector[&2;&2]])) /\
         interval[--vector[&1;&1],vector[&1;&1]] SUBSET
           inside (IMAGE GG (moi_s5c_sec Q Ja (-- &1 * s))) /\
         interval[--vector[&1;&1],vector[&1;&1]] SUBSET inside (IMAGE GG Ja) /\
         interval[--vector[&1;&1],vector[&1;&1]] SUBSET inside (IMAGE GG Jb)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mup] o
    check (MOI_S5C_HEAD "moi_s5c_mup")) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  SUBGOAL_THEN `abs(-- &1 * s) <= &1` ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`&0 < s`; `s < &1`] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MAP_EVERY (fun (j,t) ->
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; j; t]
      MOI_S5C_SEC_BASIC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[REAL_ABS_0; REAL_POS]; STRIP_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; j; t]
      MOI_S5C_SEC_SQ_ESS) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[REAL_ABS_0; REAL_POS]; DISCH_TAC])
    [`Ja:real^3->bool`,`-- &1 * s`; `Jb:real^3->bool`,`-- &1 * s`;
     `Ja:real^3->bool`,`&0`; `Jb:real^3->bool`,`&0`] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `moi_s5c_sec (Q:real^3->real->real^3) Ja (&0) = Ja`;
                              ASSUME `moi_s5c_sec (Q:real^3->real->real^3) Jb (&0) = Jb`]) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `IMAGE (GG:real^3->real^2) Ja SUBSET inside (IMAGE GG Jb)` ASSUME_TAC THENL
   [UNDISCH_TAC `moi_s5c_cons B (GG:real^3->real^2) c (IMAGE GG Ja) (IMAGE GG Jb)` THEN
    SIMP_TAC[moi_s5c_cons];
    ASM_REWRITE_TAC[]] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`]
    MOI_S5C_ADJ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2
      (X_CHOOSE_TAC `W:real^2->bool`) (K ALL_TAC))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Jb:real^3->bool`]
    MOI_S5C_ADJ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
      (X_CHOOSE_TAC `Z:real^2->bool`))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `IMAGE (GG:real^3->real^2) Ja`; `IMAGE (GG:real^3->real^2) Jb`] MOI_S5C_TYPE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 < u /\ u < &1} SUBSET
    IMAGE (FF:real^2->real^3) (moi_s5c_rgo W (IMAGE (GG:real^3->real^2) Ja))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
      `W:real^2->bool`; `IMAGE (GG:real^3->real^2) Jb`] MOI_S5C_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `-- &1`) THEN REWRITE_TAC[] THEN ASM_REWRITE_TAC[] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 < u /\ u < &1} SUBSET
    IMAGE (FF:real^2->real^3) (moi_s5c_rgo (IMAGE (GG:real^3->real^2) Jb) Z)`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Jb:real^3->bool`;
      `IMAGE (GG:real^3->real^2) Ja`; `Z:real^2->bool`] MOI_S5C_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `-- &1`) THEN REWRITE_TAC[] THEN ASM_REWRITE_TAC[] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (GG:real^3->real^2)
      {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 < u /\ u < &1} SUBSET
    inside (IMAGE GG Ja) /\
    IMAGE (GG:real^3->real^2)
      {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 < u /\ u < &1} SUBSET
    outside (IMAGE GG Jb)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `W:real^2->bool`; `IMAGE (GG:real^3->real^2) Ja`] MOI_S5C_CONS_FACTS) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `IMAGE (GG:real^3->real^2) Jb`; `Z:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
    ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `moi_s5c_rgo W (IMAGE (GG:real^3->real^2) Ja)` THEN CONJ_TAC THENL
       [MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `IMAGE (GG:real^3->real^2)
          (IMAGE (FF:real^2->real^3) (moi_s5c_rgo W (IMAGE (GG:real^3->real^2) Ja)))` THEN
        CONJ_TAC THENL [MATCH_MP_TAC IMAGE_SUBSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MATCH_MP_TAC(SET_RULE `!s t:real^2->bool. s = t ==> s SUBSET t`) THEN MATCH_MP_TAC MOI_S5C_GGFF THEN
        MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `K:(real^3->bool)->bool`;
          `Q:real^3->real->real^3`; `c:real`; `d0:real`] THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[moi_s5c_rgo] THEN SET_TAC[]];
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `moi_s5c_rgo (IMAGE (GG:real^3->real^2) Jb) Z` THEN CONJ_TAC THENL
       [MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `IMAGE (GG:real^3->real^2)
          (IMAGE (FF:real^2->real^3) (moi_s5c_rgo (IMAGE (GG:real^3->real^2) Jb) Z))` THEN
        CONJ_TAC THENL [MATCH_MP_TAC IMAGE_SUBSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MATCH_MP_TAC(SET_RULE `!s t:real^2->bool. s = t ==> s SUBSET t`) THEN MATCH_MP_TAC MOI_S5C_GGFF THEN
        MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `K:(real^3->bool)->bool`;
          `Q:real^3->real->real^3`; `c:real`; `d0:real`] THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[moi_s5c_rgo] THEN
        MP_TAC(ISPEC `IMAGE (GG:real^3->real^2) Jb` INSIDE_UNION_OUTSIDE) THEN
        SET_TAC[]]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
    `-- &1`; `s:real`] MOI_S5C_STRIP_REGION) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Jb:real^3->bool`;
    `-- &1`; `s:real`] MOI_S5C_STRIP_REGION) THEN
  ASM_REWRITE_TAC[] THEN SIMP_TAC[]);;


(* ------------------------------------------------------------------------- *)
(* The descent: a circle of B strictly between the two circles of a         *)
(* middle up region (in the planar order) yields a middle up region with    *)
(* fewer circles between; hence there is one with none.                      *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_VSEG_CONVEX = prove
 (`!q:real^3 a b.
     convex {x:real^3 | x$1 = q$1 /\ x$2 = q$2 /\ a < x$3 /\ x$3 <= b}`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `{x:real^3 | x$1 = (q:real^3)$1 /\ x$2 = q$2 /\ a < x$3 /\ x$3 <= b} =
                {x | basis 1 dot x = q$1} INTER {x | basis 2 dot x = q$2} INTER
                {x | x$3 > a} INTER {x | basis 3 dot x <= b}`
  SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_INTER] THEN
    SIMP_TAC[DOT_BASIS; DIMINDEX_3; ARITH; real_gt];
    REPEAT(MATCH_MP_TAC CONVEX_INTER THEN CONJ_TAC) THEN
    REWRITE_TAC[CONVEX_HYPERPLANE; CONVEX_HALFSPACE_LE; CONVEX_HALFSPACE_COMPONENT_GT]]);;

let MOI_S5C_VERT_DIST = prove
 (`!a b t t'. dist(vector[a;b;t]:real^3,vector[a;b;t']) = abs(t - t')`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dist] THEN
  SUBGOAL_THEN `vector[a;b;t] - vector[a;b;t'] = (t - t') % basis 3:real^3` SUBST1_TAC THENL
   [SIMP_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3; VECTOR_SUB_COMPONENT;
             VECTOR_MUL_COMPONENT; BASIS_COMPONENT; ARITH] THEN REAL_ARITH_TAC;
    SIMP_TAC[NORM_MUL; NORM_BASIS; DIMINDEX_3; ARITH; REAL_MUL_RID]]);;

(* A point of the open planar annulus between the circles at level c lies  *)
(* in V, provided the vertical segment below it down to level c-h misses   *)
(* the collar strips and its planar position is inside the lower outer     *)
(* circle and off the lower inner circle.                                    *)

let MOI_S5C_ARCH_Q_IN_V = prove
 (`!c h jin jout jin' jout' A Cin Cout q.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout /\
     q$3 = c /\ moi_s5c_proj q IN inside jout DIFF (jin UNION inside jin) /\
     (!x. x IN Cin UNION Cout /\ c - h < x$3 /\ x$3 < c
          ==> ~(moi_s5c_proj x = moi_s5c_proj q)) /\
     moi_s5c_proj q IN inside jout' /\ ~(moi_s5c_proj q IN jin')
     ==> q IN inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
              outside (moi_s5c_sig2 c h jin jin' Cin)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_V) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_LEVELS) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_PIECES) THEN
  MP_TAC(MOI_S5C_ARCH_CONJ 0 (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`)) THEN
  DISCH_TAC THEN
  ABBREV_TAC `S = {x:real^3 | x$1 = (q:real^3)$1 /\ x$2 = q$2 /\ c - h < x$3 /\ x$3 <= c}` THEN
  SUBGOAL_THEN `connected (S:real^3->bool) /\ (q:real^3) IN S` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "S" THEN REWRITE_TAC[IN_ELIM_THM] THEN
    SIMP_TAC[CONVEX_CONNECTED; MOI_S5C_VSEG_CONVEX] THEN
    UNDISCH_TAC `&0 < h` THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!x:real^3. x IN S ==> moi_s5c_proj x = moi_s5c_proj q` ASSUME_TAC THENL
   [EXPAND_TAC "S" THEN SIMP_TAC[IN_ELIM_THM; moi_s5c_proj]; ALL_TAC] THEN
  SUBGOAL_THEN `!y:real^2. y IN inside jout ==> ~(y IN jout)` ASSUME_TAC THENL
   [MP_TAC(ISPEC `jout:real^2->bool` INSIDE_NO_OVERLAP) THEN SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `DISJOINT (S:real^3->bool)
                  (moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin)`
  ASSUME_TAC THENL
   [REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
    SUBGOAL_THEN `moi_s5c_proj x = moi_s5c_proj q /\ c - h < (x:real^3)$3 /\ x$3 <= c`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      UNDISCH_TAC `(x:real^3) IN S` THEN EXPAND_TAC "S" THEN SIMP_TAC[IN_ELIM_THM];
      ALL_TAC] THEN
    UNDISCH_TAC `(x:real^3) IN moi_s5c_sig1 c h jin jout' A Cout UNION
                                moi_s5c_sig2 c h jin jin' Cin` THEN
    REWRITE_TAC[moi_s5c_sig1; moi_s5c_sig2; IN_UNION; MOI_S5C_IN_LIFT] THEN
    UNDISCH_TAC `moi_s5c_proj q IN inside jout DIFF (jin UNION inside jin)` THEN
    REWRITE_TAC[IN_DIFF; IN_UNION; DE_MORGAN_THM] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    ASM_CASES_TAC `(x:real^3)$3 = c` THENL
     [ASM_REWRITE_TAC[] THEN
      (let sg1 = `moi_s5c_sig1 c h jin jout' A Cout`
       and sg2 = `moi_s5c_sig2 c h jin jin' Cin` and sS = `S:real^3->bool` in
       REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th -> free_in `x:real^3` (concl th) ||
         (is_forall(concl th) &&
          not(can (find_term (fun t -> t = sg1 || t = sg2 || t = sS)) (concl th))))))) THEN
      MP_TAC(ASSUME `&0 < h`) THEN MP_TAC(ASSUME `~(moi_s5c_proj q IN jin)`) THEN
      MP_TAC(ASSUME `~(moi_s5c_proj q IN inside jin)`) THEN
      MP_TAC(ASSUME `moi_s5c_proj q IN inside jout`) THEN
      MESON_TAC[];
      SUBGOAL_THEN `(x:real^3)$3 < c /\ ~(x$3 = c - h)` STRIP_ASSUME_TAC THENL
       [MAP_EVERY UNDISCH_TAC [`~((x:real^3)$3 = c)`; `(x:real^3)$3 <= c`;
                               `c - h < (x:real^3)$3`] THEN REAL_ARITH_TAC;
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `~((x:real^3) IN A)` ASSUME_TAC THENL
       [DISCH_TAC THEN
        UNDISCH_TAC `!x:real^3. x IN A ==> c <= x$3` THEN
        DISCH_THEN(MP_TAC o SPEC `x:real^3`) THEN ASM_REWRITE_TAC[] THEN
        UNDISCH_TAC `(x:real^3)$3 < c` THEN REAL_ARITH_TAC;
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `Cin UNION Cout:real^3->bool`))
        (concl th))) THEN
      ASM_REWRITE_TAC[IN_UNION] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `!t. moi_s5c_proj (vector[(q:real^3)$1; q$2; t]) = moi_s5c_proj q`
  ASSUME_TAC THENL [REWRITE_TAC[moi_s5c_proj; VECTOR_3]; ALL_TAC] THEN
  SUBGOAL_THEN `!t. &0 < t /\ t <= h ==> vector[(q:real^3)$1; q$2; c - h + t] IN (S:real^3->bool)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN EXPAND_TAC "S" THEN REWRITE_TAC[IN_ELIM_THM; VECTOR_3] THEN
    MAP_EVERY UNDISCH_TAC [`&0 < t`; `t <= h`] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!r. &0 < r
                ==> vector[(q:real^3)$1; q$2; c - h + min r h / &2] IN
                    {x | x IN ball(vector[q$1; q$2; c - h]:real^3,r) /\
                         (vector[q$1; q$2; c - h]:real^3)$3 < x$3} /\
                    vector[q$1; q$2; c - h + min r h / &2] IN (S:real^3->bool)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM; IN_BALL; MOI_S5C_VERT_DIST; VECTOR_3] THEN
      MAP_EVERY UNDISCH_TAC [`&0 < r`; `&0 < h`] THEN REAL_ARITH_TAC;
      FIRST_X_ASSUM MATCH_MP_TAC THEN
      MAP_EVERY UNDISCH_TAC [`&0 < r`; `&0 < h`] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `pl_sphere 2 (moi_s5c_sig2 c h jin jin' Cin)` ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_SPHERES o
      check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
    SIMP_TAC[moi_s5c_sig2];
    ALL_TAC] THEN
  ASM_CASES_TAC `moi_s5c_proj q IN inside jin'` THENL
   [MP_TAC(ISPECL [`c:real`; `h:real`; `jin:real^2->bool`; `jout:real^2->bool`;
                   `jin':real^2->bool`; `jout':real^2->bool`; `A:real^3->bool`;
                   `Cin:real^3->bool`; `Cout:real^3->bool`;
                   `vector[(q:real^3)$1; q$2; c - h]:real^3`] MOI_S5C_ARCH_DIN2_SIDE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[MOI_S5C_IN_LIFT; VECTOR_3]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(S:real^3->bool) SUBSET inside (moi_s5c_sig2 c h jin jin' Cin)` MP_TAC THENL
     [MP_TAC(MATCH_MP MOI_S5C_SPH_SIDES
        (ASSUME `pl_sphere 2 (moi_s5c_sig2 c h jin jin' Cin)`)) THEN
      DISCH_THEN(MATCH_MP_TAC o last o CONJUNCTS) THEN ASM_REWRITE_TAC[] THEN
      CONJ_TAC THENL
       [UNDISCH_TAC `DISJOINT (S:real^3->bool)
          (moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin)` THEN
        SET_TAC[];
        REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
        EXISTS_TAC `vector[(q:real^3)$1; q$2; c - h + min r h / &2]:real^3` THEN
        FIRST_X_ASSUM(MP_TAC o C MATCH_MP (ASSUME `&0 < r`) o check (fun th ->
          is_forall(concl th) && can (find_term ((=) `min`)) (concl th))) THEN
        UNDISCH_TAC `{x | x IN ball(vector[(q:real^3)$1; q$2; c - h]:real^3,r) /\
                          c - h < x$3} SUBSET inside (moi_s5c_sig2 c h jin jin' Cin)` THEN
        REWRITE_TAC[VECTOR_3] THEN SET_TAC[]];
      DISCH_THEN(MP_TAC o SPEC `q:real^3` o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `q:real^3` o check (fun th ->
        is_forall(concl th) &&
        can (find_term ((=) `inside (moi_s5c_sig2 c h jin jin' Cin)`)) (concl th) &&
        not(can (find_term ((=) `S:real^3->bool`)) (concl th)) &&
        not(can (find_term ((=) `ball:real^3#real->real^3->bool`)) (concl th)))) THEN
      ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`c:real`; `h:real`; `jin:real^2->bool`; `jout:real^2->bool`;
                 `jin':real^2->bool`; `jout':real^2->bool`; `A:real^3->bool`;
                 `Cin:real^3->bool`; `Cout:real^3->bool`;
                 `vector[(q:real^3)$1; q$2; c - h]:real^3`] MOI_S5C_ARCH_N_HALVES) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[MOI_S5C_IN_LIFT; VECTOR_3; IN_DIFF; IN_UNION]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(S:real^3->bool) SUBSET inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                         outside (moi_s5c_sig2 c h jin jin' Cin)` MP_TAC THENL
   [MATCH_MP_TAC MOI_S5C_CONN_SUB THEN
    EXISTS_TAC `(:real^3) DIFF
      (moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin UNION
       closure (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                outside (moi_s5c_sig2 c h jin jin' Cin)))` THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[ASSUME `closure (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                                   outside (moi_s5c_sig2 c h jin jin' Cin)) =
                          (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                           outside (moi_s5c_sig2 c h jin jin' Cin)) UNION
                          moi_s5c_tor c h jin' jout' A Cin Cout`] THEN
      MAP_EVERY UNDISCH_TAC
       [`DISJOINT (S:real^3->bool)
          (moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin)`;
        `moi_s5c_tor c h jin' jout' A Cin Cout =
         Cin UNION (A UNION Cout UNION moi_s5c_npl (c - h) jin' jout')`;
        `A UNION Cout UNION moi_s5c_npl (c - h) jin' jout' SUBSET
         moi_s5c_sig1 c h jin jout' A Cout`;
        `Cin SUBSET moi_s5c_sig2 c h jin jin' Cin`] THEN
      SET_TAC[];
      REWRITE_TAC[GSYM closed] THEN
      REPEAT(MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC) THEN
      REWRITE_TAC[CLOSED_CLOSURE] THEN MATCH_MP_TAC COMPACT_IMP_CLOSED THEN
      FIRST_ASSUM(MP_TAC o MATCH_MP MOI_S5C_ARCH_FACTS2 o
        check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
      MESON_TAC[HOMEOMORPHIC_COMPACTNESS; COMPACT_SPHERE];
      FIRST_ASSUM ACCEPT_TAC;
      MP_TAC(ISPEC `inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                    outside (moi_s5c_sig2 c h jin jin' Cin)` CLOSURE_SUBSET) THEN
      SET_TAC[];
      REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
      EXISTS_TAC `vector[(q:real^3)$1; q$2; c - h + min r h / &2]:real^3` THEN
      FIRST_X_ASSUM(MP_TAC o C MATCH_MP (ASSUME `&0 < r`) o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `min`)) (concl th))) THEN
      UNDISCH_TAC `{x | x IN ball(vector[(q:real^3)$1; q$2; c - h]:real^3,r) /\
                        (vector[q$1; q$2; c - h]:real^3)$3 < x$3} SUBSET
                   inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                   outside (moi_s5c_sig2 c h jin jin' Cin)` THEN
      SET_TAC[]];
    REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

let MOI_S5C_PROJ_LIPSCHITZ = prove
 (`!x y:real^3. dist(moi_s5c_proj x,moi_s5c_proj y) <= dist(x,y)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dist] THEN
  SUBGOAL_THEN `moi_s5c_proj x - moi_s5c_proj y = moi_s5c_proj (x - y)` SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC LINEAR_SUB THEN REWRITE_TAC[MOI_S5C_PROJ_FACTS];
    ALL_TAC] THEN
  REWRITE_TAC[NORM_LE; moi_s5c_proj; DOT_2; DOT_3; VECTOR_2] THEN
  MP_TAC(SPEC `(x - y:real^3)$3` REAL_LE_SQUARE) THEN REAL_ARITH_TAC);;

(* Small collar parameters keep the collar images away from a planar point *)
(* off the projection of a compact part of the level set.                   *)

let MOI_S5C_AVOID = prove
 (`!B K FF GG Q c d0 S p.
     moi_s5c_mset B K FF GG Q c d0 /\ S SUBSET {x | x IN B /\ x$3 = c} /\ compact S /\
     ~(p IN IMAGE moi_s5c_proj S)
     ==> ?s0. &0 < s0 /\ s0 < &1 /\
              !x t. x IN S /\ abs t <= s0
                    ==> ~(moi_s5c_proj ((Q:real^3->real->real^3) x t) = p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_COLLAR_FACTS) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_BASIC) THEN
  SUBGOAL_THEN `?e. &0 < e /\ !x. x IN S ==> e <= dist(p,moi_s5c_proj x)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`IMAGE moi_s5c_proj (S:real^3->bool)`; `p:real^2`]
      SEPARATE_POINT_CLOSED) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC COMPACT_IMP_CLOSED THEN
      MATCH_MP_TAC COMPACT_LINEAR_IMAGE THEN ASM_REWRITE_TAC[MOI_S5C_PROJ_FACTS];
      REWRITE_TAC[FORALL_IN_IMAGE] THEN MESON_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\p:real^(3,1)finite_sum. (Q:real^3->real->real^3) (fstcart p) (drop(sndcart p))`;
                 `{x:real^3 | x IN B /\ x$3 = c} PCROSS interval[--vec 1:real^1,vec 1]`]
    COMPACT_UNIFORMLY_CONTINUOUS) THEN
  ANTS_TAC THENL [ASM_SIMP_TAC[COMPACT_PCROSS; COMPACT_INTERVAL]; ALL_TAC] THEN
  REWRITE_TAC[uniformly_continuous_on] THEN DISCH_THEN(MP_TAC o SPEC `e:real`) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `d:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `min (d / &2) (&1 / &2)` THEN
  CONJ_TAC THENL [UNDISCH_TAC `&0 < d` THEN REAL_ARITH_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`x:real^3`; `t:real`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:real^3) IN B /\ x$3 = c` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `S SUBSET {x:real^3 | x IN B /\ x$3 = c}` THEN
    UNDISCH_TAC `(x:real^3) IN S` THEN SET_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`pastecart (x:real^3) (lift(&0))`;
                                `pastecart (x:real^3) (lift t)`]) THEN
  REWRITE_TAC[BETA_THM; FSTCART_PASTECART; SNDCART_PASTECART; LIFT_DROP; PASTECART_IN_PCROSS;
              DIST_PASTECART_CANCEL; DIST_LIFT; IN_ELIM_THM; IN_INTERVAL_1; DROP_NEG;
              DROP_VEC] THEN
  ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [UNDISCH_TAC `abs t <= min (d / &2) (&1 / &2)` THEN UNDISCH_TAC `&0 < d` THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(Q:real^3->real->real^3) x (&0) = x` SUBST1_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`(Q:real^3->real->real^3) x t`; `x:real^3`] MOI_S5C_PROJ_LIPSCHITZ) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
    is_forall(concl th) && can (find_term ((=) `p:real^2`)) (concl th))) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY UNDISCH_TAC [`dist((Q:real^3->real->real^3) x t,x) < e`] THEN
  REWRITE_TAC[DIST_SYM] THEN REAL_ARITH_TAC);;

let MOI_S5C_AVOID_CONSEQ = prove
 (`!B K FF GG Q c d0 J1 J2 s q.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J1 IN components {x | x IN B /\ x$3 = c} /\ J2 IN components {x | x IN B /\ x$3 = c} /\
     &0 < s /\ s < &1 /\
     moi_s5c_proj q IN inside (IMAGE moi_s5c_proj J2) /\
     (!x t. x IN J1 UNION J2 /\ abs t <= s
            ==> ~(moi_s5c_proj ((Q:real^3->real->real^3) x t) = moi_s5c_proj q))
     ==> (!x. x IN {Q x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s} UNION
                   {Q x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}
              ==> ~(moi_s5c_proj x = moi_s5c_proj q)) /\
         moi_s5c_proj q IN inside (IMAGE moi_s5c_proj (moi_s5c_sec Q J2 (-- &1 * s))) /\
         ~(moi_s5c_proj q IN IMAGE moi_s5c_proj (moi_s5c_sec Q J1 (-- &1 * s)))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "av")))))))) THEN
  SUBGOAL_THEN `abs(-- &1 * s) <= s` ASSUME_TAC THENL
   [UNDISCH_TAC `&0 < s` THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `~(moi_s5c_proj q IN IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) /\
    ~(moi_s5c_proj q IN IMAGE moi_s5c_proj (moi_s5c_sec Q J2 (-- &1 * s)))`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[moi_s5c_sec; IN_IMAGE] THEN CONJ_TAC THEN
    DISCH_THEN(X_CHOOSE_THEN `y:real^3` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `x:real^3` STRIP_ASSUME_TAC))) THEN
    USE_THEN "av" (MP_TAC o SPECL [`x:real^3`; `-- &1 * s`]) THEN
    (ANTS_TAC THENL [ASM_REWRITE_TAC[IN_UNION]; ASM_REWRITE_TAC[]]);
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[IN_UNION; IN_ELIM_THM] THEN X_GEN_TAC `z:real^3` THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "av" MATCH_MP_TAC THEN ASM_REWRITE_TAC[IN_UNION] THEN
    MAP_EVERY UNDISCH_TAC [`&0 <= u`; `u <= s`] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPEC `IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))`
    INSIDE_UNION_OUTSIDE) THEN
  REWRITE_TAC[EXTENSION; IN_UNION; IN_DIFF; IN_UNIV] THEN
  DISCH_THEN(MP_TAC o SPEC `moi_s5c_proj q`) THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT `~b ==> (a \/ b ==> a)`) THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J2:real^3->bool`;
    `-- &1 * s`; `moi_s5c_proj`; `\r:real^1. moi_s5c_proj q`] MOI_S5C_PUSH_SEC) THEN
  ASM_REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
  MATCH_MP_TAC(TAUT `a /\ ~b ==> ~(a ==> b)`) THEN CONJ_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MAP_EVERY UNDISCH_TAC [`&0 < s`; `s < &1`] THEN REAL_ARITH_TAC;
      MATCH_MP_TAC LINEAR_CONTINUOUS_ON THEN REWRITE_TAC[MOI_S5C_PROJ_FACTS];
      MATCH_MP_TAC MOI_S5C_PROJ_INJ_LEVEL THEN EXISTS_TAC `c:real` THEN
      UNDISCH_TAC `J2 IN components {x:real^3 | x IN B /\ x$3 = c}` THEN
      DISCH_THEN(MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN SET_TAC[];
      REWRITE_TAC[IN_INTERVAL_1; DROP_VEC] THEN
      MAP_EVERY X_GEN_TAC [`r:real^1`; `x:real^3`] THEN STRIP_TAC THEN
      USE_THEN "av" MATCH_MP_TAC THEN ASM_REWRITE_TAC[IN_UNION] THEN
      REWRITE_TAC[REAL_ABS_MUL; REAL_ABS_NEG; REAL_ABS_NUM; REAL_MUL_LID] THEN
      SUBGOAL_THEN `abs(&1 - drop r) <= &1` MP_TAC THENL
       [MAP_EVERY UNDISCH_TAC [`&0 <= drop r`; `drop r <= &1`] THEN REAL_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `abs s = s` SUBST1_TAC THENL
       [UNDISCH_TAC `&0 < s` THEN REAL_ARITH_TAC; ALL_TAC] THEN
      DISCH_TAC THEN GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_LID] THEN
      MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `&0 < s` THEN REAL_ARITH_TAC];
    MP_TAC(ISPEC `IMAGE moi_s5c_proj (J2:real^3->bool)` INSIDE_INTER_OUTSIDE) THEN
    UNDISCH_TAC `moi_s5c_proj q IN inside (IMAGE moi_s5c_proj (J2:real^3->bool))` THEN
    SET_TAC[]]);;

let moi_s5c_btw = new_definition
 `moi_s5c_btw (B:real^3->bool) c (Ja:real^3->bool) Jb =
    {J | J IN components {x | x IN B /\ x$3 = c} /\ ~(J = Ja) /\ ~(J = Jb) /\
         ((IMAGE moi_s5c_proj Ja SUBSET inside (IMAGE moi_s5c_proj J) /\
           IMAGE moi_s5c_proj J SUBSET inside (IMAGE moi_s5c_proj Jb)) \/
          (IMAGE moi_s5c_proj Jb SUBSET inside (IMAGE moi_s5c_proj J) /\
           IMAGE moi_s5c_proj J SUBSET inside (IMAGE moi_s5c_proj Ja)))}`;;

(* The up region at a circle.                                               *)

let MOI_S5C_UP_AT = prove
 (`!B K FF GG Q c d0 J.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     J IN components {x | x IN B /\ x$3 = c}
     ==> ?X Y. moi_s5c_cons B (GG:real^3->real^2) c X Y /\
               moi_s5c_sd (FF:real^2->real^3) c (&1) X Y /\
               (X = IMAGE GG J \/ Y = IMAGE GG J) /\
               {(Q:real^3->real->real^3) x (&1 * u) | x IN J /\ &0 < u /\ u < &1} SUBSET
               IMAGE FF (moi_s5c_rgo X Y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
    MOI_S5C_ADJ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2
      (X_CHOOSE_TAC `W:real^2->bool`) (X_CHOOSE_TAC `Y:real^2->bool`))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
    `W:real^2->bool`; `Y:real^2->bool`] MOI_S5C_ALT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `&1`) THEN REWRITE_TAC[] THEN
  ASM_CASES_TAC `moi_s5c_sd (FF:real^2->real^3) c (&1) (IMAGE (GG:real^3->real^2) J) Y` THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [MAP_EVERY EXISTS_TAC [`IMAGE (GG:real^3->real^2) J`; `Y:real^2->bool`];
    MAP_EVERY EXISTS_TAC [`W:real^2->bool`; `IMAGE (GG:real^3->real^2) J`]] THEN
  ASM_MESON_TAC[]);;

(* An up region at a circle J other than the two circles of a middle up    *)
(* region shares no end circle with it.                                      *)

let MOI_S5C_UP_OTHER = prove
 (`!B K FF GG Q c d0 Ja Jb J X' Y'.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     J IN components {x | x IN B /\ x$3 = c} /\ ~(J = Ja) /\ ~(J = Jb) /\
     moi_s5c_cons B (GG:real^3->real^2) c X' Y' /\ moi_s5c_sd (FF:real^2->real^3) c (&1) X' Y' /\
     (X' = IMAGE GG J \/ Y' = IMAGE GG J)
     ==> ~(X' = IMAGE GG Ja) /\ ~(X' = IMAGE GG Jb) /\
         ~(Y' = IMAGE GG Ja) /\ ~(Y' = IMAGE GG Jb)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))))))) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mup] o
    check (MOI_S5C_HEAD "moi_s5c_mup")) THEN
  SUBGOAL_THEN `!J1 J2:real^3->bool. J1 IN components {x | x IN B /\ x$3 = c} /\
                   J2 IN components {x | x IN B /\ x$3 = c} /\
                   IMAGE (GG:real^3->real^2) J1 = IMAGE GG J2 ==> J1 = J2`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J1:real^3->bool`]
      MOI_S5C_FFGG) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J2:real^3->bool`]
      MOI_S5C_FFGG) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY (fun t -> MP_TAC(MATCH_MP IN_COMPONENTS_SUBSET (ASSUME t)))
      [`J1 IN components {x:real^3 | x IN B /\ x$3 = c}`;
       `J2 IN components {x:real^3 | x IN B /\ x$3 = c}`] THEN
    REPEAT DISCH_TAC THEN
    SUBGOAL_THEN `(J1:real^3->bool) SUBSET B /\ (J2:real^3->bool) SUBSET B`
    STRIP_ASSUME_TAC THENL
     [MAP_EVERY UNDISCH_TAC [`J1 SUBSET {x:real^3 | x IN B /\ x$3 = c}`;
                             `J2 SUBSET {x:real^3 | x IN B /\ x$3 = c}`] THEN SET_TAC[];
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`]
    MOI_S5C_ADJ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2
      (X_CHOOSE_TAC `W:real^2->bool`) (K ALL_TAC))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Jb:real^3->bool`]
    MOI_S5C_ADJ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
      (X_CHOOSE_TAC `Z:real^2->bool`))))) THEN
  SUBGOAL_THEN `~moi_s5c_sd (FF:real^2->real^3) c (&1) W (IMAGE (GG:real^3->real^2) Ja) /\
                ~moi_s5c_sd FF c (&1) (IMAGE GG Jb) Z` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
        `W:real^2->bool`; `IMAGE (GG:real^3->real^2) Jb`] MOI_S5C_ALT);
      MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Jb:real^3->bool`;
        `IMAGE (GG:real^3->real^2) Ja`; `Z:real^2->bool`] MOI_S5C_ALT)] THEN
    (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]) THEN
    DISCH_THEN(MP_TAC o SPEC `&1`) THEN REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MAP_EVERY (fun (x,y) ->
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; x; y]
      MOI_S5C_CONS_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o last o CONJUNCTS)])
    [`W:real^2->bool`,`IMAGE (GG:real^3->real^2) Ja`;
     `IMAGE (GG:real^3->real^2) Ja`,`IMAGE (GG:real^3->real^2) Jb`;
     `IMAGE (GG:real^3->real^2) Jb`,`Z:real^2->bool`] THEN
  REPEAT CONJ_TAC THEN DISCH_TAC THEN
  FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th -> is_disj(concl th) &&
    can (find_term ((=) `IMAGE (GG:real^3->real^2) J`)) (concl th))) THEN
  ASM_MESON_TAC[]);;

(* Planar nesting: a circle between two circles that are both between a and *)
(* b is itself between a and b.                                              *)

let MOI_S5C_NEST_ASYM = prove
 (`!X Y:real^2->bool.
     pl_sphere 1 X /\ pl_sphere 1 Y /\ X SUBSET inside Y ==> ~(Y SUBSET inside X)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`1`; `Y:real^2->bool`] MOI_SCD_PL_SPHERE_NONEMPTY) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPEC `X:real^2->bool` INSIDE_INTER_OUTSIDE) THEN
  MAP_EVERY UNDISCH_TAC [`(Y:real^2->bool) SUBSET inside X`;
                         `(Y:real^2->bool) SUBSET outside X`] THEN
  SET_TAC[]);;

let MOI_S5C_BTW_PLANAR1 = prove
 (`!a b j j' k:real^2->bool.
     pl_sphere 1 a /\ pl_sphere 1 b /\ pl_sphere 1 j /\ pl_sphere 1 j' /\ pl_sphere 1 k /\
     a SUBSET inside j /\ j' SUBSET inside b /\
     j SUBSET inside k /\ k SUBSET inside j'
     ==> a SUBSET inside k /\ k SUBSET inside b /\ ~(k = a) /\ ~(k = b)`,
  REPEAT STRIP_TAC THENL
   [MP_TAC(ISPECL [`a:real^2->bool`; `j:real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
    MP_TAC(ISPECL [`j:real^2->bool`; `k:real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `(a:real^2->bool) SUBSET inside j` THEN SET_TAC[];
    MP_TAC(ISPECL [`k:real^2->bool`; `j':real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
    MP_TAC(ISPECL [`j':real^2->bool`; `b:real^2->bool`] MOI_S5C_PLANAR_NEST_FACTS) THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `(k:real^2->bool) SUBSET inside j'` THEN SET_TAC[];
    FIRST_X_ASSUM SUBST_ALL_TAC THEN
    MP_TAC(ISPECL [`a:real^2->bool`; `j:real^2->bool`] MOI_S5C_NEST_ASYM) THEN
    ASM_REWRITE_TAC[];
    FIRST_X_ASSUM SUBST_ALL_TAC THEN
    MP_TAC(ISPECL [`j':real^2->bool`; `b:real^2->bool`] MOI_S5C_NEST_ASYM) THEN
    ASM_REWRITE_TAC[]]);;

let MOI_S5C_BTW_PLANAR = prove
 (`!a b j j' k:real^2->bool.
     pl_sphere 1 a /\ pl_sphere 1 b /\ pl_sphere 1 j /\ pl_sphere 1 j' /\ pl_sphere 1 k /\
     a SUBSET inside j /\ j SUBSET inside b /\ a SUBSET inside j' /\ j' SUBSET inside b /\
     ((j SUBSET inside k /\ k SUBSET inside j') \/ (j' SUBSET inside k /\ k SUBSET inside j))
     ==> a SUBSET inside k /\ k SUBSET inside b /\ ~(k = a) /\ ~(k = b)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))))))))) THEN
  STRIP_TAC THENL
   [MATCH_MP_TAC MOI_S5C_BTW_PLANAR1 THEN
    MAP_EVERY EXISTS_TAC [`j:real^2->bool`; `j':real^2->bool`];
    MATCH_MP_TAC MOI_S5C_BTW_PLANAR1 THEN
    MAP_EVERY EXISTS_TAC [`j':real^2->bool`; `j:real^2->bool`]] THEN
  ASM_REWRITE_TAC[]);;

let MOI_S5C_GG_INJ_COMP = prove
 (`!B K FF GG Q c d0 J1 J2.
     moi_s5c_mset B K FF GG Q c d0 /\
     J1 IN components {x | x IN B /\ x$3 = c} /\ J2 IN components {x | x IN B /\ x$3 = c} /\
     IMAGE (GG:real^3->real^2) J1 = IMAGE GG J2
     ==> J1 = J2`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J1:real^3->bool`]
    MOI_S5C_FFGG) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J2:real^3->bool`]
    MOI_S5C_FFGG) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY (fun t -> MP_TAC(MATCH_MP IN_COMPONENTS_SUBSET (ASSUME t)))
    [`J1 IN components {x:real^3 | x IN B /\ x$3 = c}`;
     `J2 IN components {x:real^3 | x IN B /\ x$3 = c}`] THEN
  REPEAT DISCH_TAC THEN
  SUBGOAL_THEN `(J1:real^3->bool) SUBSET B /\ (J2:real^3->bool) SUBSET B`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`J1 SUBSET {x:real^3 | x IN B /\ x$3 = c}`;
                           `J2 SUBSET {x:real^3 | x IN B /\ x$3 = c}`] THEN SET_TAC[];
    ASM_MESON_TAC[]]);;

(* The up region at a circle J meeting a region V (with the stated         *)
(* properties of the arch region) lies in the closure of V and is a middle *)
(* up region whose circles differ from those of the original one.          *)

let MOI_S5C_UP_IN_V_GEN = prove
 (`!B K FF GG Q c d0 Ja Jb J q V t.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     J IN components {x | x IN B /\ x$3 = c} /\ ~(J = Ja) /\ ~(J = Jb) /\
     q IN J /\ q IN V /\
     open V /\ V SUBSET moi_s5c_otube /\ closed t /\ V INTER t = {} /\
     closure V SUBSET V UNION t /\
     (!x. x IN t /\ c < x$3
          ==> x IN IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE GG Ja) (IMAGE GG Jb)))
     ==> ?J1' J2'. moi_s5c_mup B FF GG c J1' J2' /\ (J1' = J \/ J2' = J) /\
                   ~(J1' = Ja) /\ ~(J1' = Jb) /\ ~(J2' = Ja) /\ ~(J2' = Jb) /\
                   IMAGE FF (moi_s5c_rg (IMAGE (GG:real^3->real^2) J1') (IMAGE GG J2'))
                     SUBSET closure V`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "tA")))))))))))))) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_COLLAR_FACTS) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`]
    MOI_S5C_UP_AT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `X:real^2->bool` (X_CHOOSE_THEN `Y:real^2->bool`
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
    `Jb:real^3->bool`; `J:real^3->bool`; `X:real^2->bool`; `Y:real^2->bool`]
    MOI_S5C_UP_OTHER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_REGION_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RGO_SIDE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o CONJUNCT1)] THEN
  (* the open region meets V *)
  SUBGOAL_THEN `~(IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y) INTER V = {})` ASSUME_TAC THENL
   [MP_TAC(SPEC `q:real^3` (GEN_REWRITE_RULE I [OPEN_CONTAINS_BALL]
      (ASSUME `open(V:real^3->bool)`))) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `e:real` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(q:real^3) IN B /\ q$3 = c` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `J IN components {x:real^3 | x IN B /\ x$3 = c}` THEN
      DISCH_THEN(MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
      UNDISCH_TAC `(q:real^3) IN J` THEN SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `q:real^3`;
      `&1`; `&0`; `&1`; `&0`] MOI_S5C_COLLAR_APPROACH) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_MUL_RZERO] THEN
    SUBGOAL_THEN `(Q:real^3->real->real^3) q (&0) = q` SUBST1_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[CLOSURE_APPROACHABLE] THEN DISCH_THEN(MP_TAC o SPEC `e:real`) THEN
    ASM_REWRITE_TAC[IN_ELIM_THM] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:real^3` (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC) ASSUME_TAC)) THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN EXISTS_TAC `y:real^3` THEN
    CONJ_TAC THENL
     [UNDISCH_TAC `{(Q:real^3->real->real^3) x (&1 * u) | x IN J /\ &0 < u /\ u < &1} SUBSET
                   IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y)` THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`q:real^3`; `u:real`] THEN ASM_REWRITE_TAC[];
      UNDISCH_TAC `ball(q:real^3,e) SUBSET V` THEN REWRITE_TAC[SUBSET; IN_BALL] THEN
      DISCH_THEN MATCH_MP_TAC THEN ONCE_REWRITE_TAC[DIST_SYM] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mup] o
    check (MOI_S5C_HEAD "moi_s5c_mup")) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `IMAGE (GG:real^3->real^2) Ja`; `IMAGE (GG:real^3->real^2) Jb`]
    MOI_S5C_REGION_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o CONJUNCT1)] THEN
  SUBGOAL_THEN `IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y) INTER t = {}` ASSUME_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN X_GEN_TAC `z:real^3` THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `c < (z:real^3)$3` ASSUME_TAC THENL
     [UNDISCH_TAC `moi_s5c_sd (FF:real^2->real^3) c (&1) X Y` THEN
      REWRITE_TAC[moi_s5c_sd] THEN DISCH_THEN(MP_TAC o SPEC `z:real^3`) THEN
      ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "tA" (MP_TAC o SPEC `z:real^3`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `X:real^2->bool`; `Y:real^2->bool`;
      `IMAGE (GG:real^3->real^2) Ja`; `IMAGE (GG:real^3->real^2) Jb`]
      MOI_S5C_CONS_DISJOINT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `(z:real^3) IN IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y)` THEN
    UNDISCH_TAC `(z:real^3) IN IMAGE (FF:real^2->real^3)
                   (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb))` THEN
    REWRITE_TAC[IN_IMAGE; DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(X_CHOOSE_THEN `p':real^2` STRIP_ASSUME_TAC) THEN
    DISCH_THEN(X_CHOOSE_THEN `p:real^2` STRIP_ASSUME_TAC) THEN
    DISCH_THEN(MP_TAC o SPEC `p:real^2`) THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `p:real^2 = p'` (fun th -> ASM_REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `(p:real^2) IN interval[--vector[&2;&2],vector[&2;&2]] DIFF
                    interval(--vector[&1;&1],vector[&1;&1]) /\
      (p':real^2) IN interval[--vector[&2;&2],vector[&2;&2]] DIFF
                     interval(--vector[&1;&1],vector[&1;&1])`
    STRIP_ASSUME_TAC THENL
     [MAP_EVERY UNDISCH_TAC
       [`moi_s5c_rgo X Y SUBSET
         interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
         interval(--vector[&1;&1]:real^2,vector[&1;&1])`;
        `moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb) SUBSET
         interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
         interval(--vector[&1;&1]:real^2,vector[&1;&1])`;
        `(p:real^2) IN moi_s5c_rgo X Y`;
        `(p':real^2) IN moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb)`] THEN
      SET_TAC[];
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y) SUBSET V` ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_CONN_SUB THEN
    EXISTS_TAC `(:real^3) DIFF (t UNION closure V)` THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      MP_TAC(ISPEC `V:real^3->bool` CLOSURE_SUBSET) THEN
      MAP_EVERY UNDISCH_TAC
       [`IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y) INTER t = {}`;
        `closure V SUBSET V UNION (t:real^3->bool)`] THEN
      SET_TAC[];
      REWRITE_TAC[GSYM closed] THEN MATCH_MP_TAC CLOSED_UNION THEN
      ASM_REWRITE_TAC[CLOSED_CLOSURE];
      FIRST_ASSUM ACCEPT_TAC;
      MP_TAC(ISPEC `V:real^3->bool` CLOSURE_SUBSET) THEN SET_TAC[];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (FF:real^2->real^3) (moi_s5c_rg X Y) SUBSET closure V` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `closure(IMAGE (FF:real^2->real^3) (moi_s5c_rgo X Y))` THEN
    ASM_SIMP_TAC[SUBSET_CLOSURE];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(X = relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) /\
                ~(Y = relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_END_NOT_TTUBE) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(TAUT `p ==> ((a \/ b) ==> ~p) ==> ~a /\ ~b`) THEN
    MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `closure V:real^3->bool` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `closure moi_s5c_otube` THEN
    ASM_SIMP_TAC[SUBSET_CLOSURE; MOI_S5C_TUBES];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_CONS_CIRCLES) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `J1':real^3->bool` STRIP_ASSUME_TAC)
    (X_CHOOSE_THEN `J2':real^3->bool` STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`J1':real^3->bool`; `J2':real^3->bool`] THEN
  FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th -> concl th =
    `X = IMAGE (GG:real^3->real^2) J1'`)) THEN
  FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th -> concl th =
    `Y = IMAGE (GG:real^3->real^2) J2'`)) THEN
  ASM_REWRITE_TAC[moi_s5c_mup] THEN
  SUBGOAL_THEN `!J3 J4:real^3->bool. J3 IN components {x | x IN B /\ x$3 = c} /\
                   J4 IN components {x | x IN B /\ x$3 = c}
                   ==> (IMAGE (GG:real^3->real^2) J3 = IMAGE GG J4 <=> J3 = J4)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN MATCH_MP_TAC MOI_S5C_GG_INJ_COMP THEN
      MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] THEN
      ASM_REWRITE_TAC[];
      SIMP_TAC[]];
    ALL_TAC] THEN
  RULE_ASSUM_TAC(fun th -> try MATCH_MP (MESON[]
    `(!J3 J4. P J3 /\ P J4 ==> (f J3 = f J4 <=> J3 = J4)) ==>
     (!J3 J4. P J3 /\ P J4 ==> (f J3 = f J4 <=> J3 = J4))`) th with Failure _ -> th) THEN
  REPEAT CONJ_TAC THEN
  TRY(FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th -> is_disj(concl th) &&
    can (find_term ((=) `IMAGE (GG:real^3->real^2) J`)) (concl th)))) THEN
  ASM_MESON_TAC[]);;

(* Term abbreviations (OCaml level) for the descent.                         *)

(* Facts about the arch region V used in the descent.                        *)

let MOI_S5C_ARCH_GEN_HYPS = prove
 (`!c h jin jout jin' jout' A Cin Cout.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout
     ==> open (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
               outside (moi_s5c_sig2 c h jin jin' Cin)) /\
         inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
         outside (moi_s5c_sig2 c h jin jin' Cin) SUBSET moi_s5c_otube /\
         closed (moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin) /\
         (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
          outside (moi_s5c_sig2 c h jin jin' Cin)) INTER
         (moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin) = {} /\
         closure (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                  outside (moi_s5c_sig2 c h jin jin' Cin)) SUBSET
         (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
          outside (moi_s5c_sig2 c h jin jin' Cin)) UNION
         (moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin) /\
         (!x. x IN moi_s5c_sig1 c h jin jout' A Cout UNION moi_s5c_sig2 c h jin jin' Cin /\
              c < x$3 ==> x IN A)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_V) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_PIECES) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_FACTS2) THEN
  MP_TAC(MOI_S5C_ARCH_CONJ 0 (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`)) THEN
  MP_TAC(MOI_S5C_ARCH_CONJ 15 (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`)) THEN
  MP_TAC(MOI_S5C_ARCH_CONJ 22 (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`)) THEN
  REPEAT DISCH_TAC THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC THEN MATCH_MP_TAC COMPACT_IMP_CLOSED THEN
    ASM_MESON_TAC[HOMEOMORPHIC_COMPACTNESS; COMPACT_SPHERE];
    MP_TAC(ISPEC `moi_s5c_sig1 c h jin jout' A Cout` INSIDE_NO_OVERLAP) THEN
    MP_TAC(ISPEC `moi_s5c_sig2 c h jin jin' Cin` OUTSIDE_NO_OVERLAP) THEN SET_TAC[];
    MAP_EVERY UNDISCH_TAC
     [`moi_s5c_tor c h jin' jout' A Cin Cout =
       Cin UNION (A UNION Cout UNION moi_s5c_npl (c - h) jin' jout')`;
      `A UNION Cout UNION moi_s5c_npl (c - h) jin' jout' SUBSET
       moi_s5c_sig1 c h jin jout' A Cout`;
      `Cin SUBSET moi_s5c_sig2 c h jin jin' Cin`] THEN
    SET_TAC[];
    X_GEN_TAC `x:real^3` THEN REWRITE_TAC[IN_UNION] THEN STRIP_TAC THENL
     [MP_TAC(ISPECL [`c:real`; `h:real`; `jin:real^2->bool`; `jout':real^2->bool`;
                     `A:real^3->bool`; `Cout:real^3->bool`] MOI_S5C_SIG1_LEVEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(MATCH_MP_TAC o CONJUNCT2)] THEN
      ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `moi_s5c_sig2 c h jin jin' Cin`))
          (concl th) &&
        can (find_term ((=) `(x:real^3)$3 <= c`)) (concl th))) THEN
      ASM_REWRITE_TAC[] THEN UNDISCH_TAC `c < (x:real^3)$3` THEN REAL_ARITH_TAC]]);;

let MOI_S5C_ARCH_CLOSURE_LEVEL = prove
 (`!c h jin jout jin' jout' A Cin Cout x.
     moi_s5c_arch c h jin jout jin' jout' A Cin Cout /\
     x IN closure (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                   outside (moi_s5c_sig2 c h jin jin' Cin)) /\ x$3 = c
     ==> x IN IMAGE (moi_s35_lift c) jin \/ x IN IMAGE (moi_s35_lift c) jout \/
         moi_s5c_proj x IN inside jout DIFF (jin UNION inside jin)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_V) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_POINTS) THEN
  MAP_EVERY (fun k -> MP_TAC(MOI_S5C_ARCH_CONJ k
    (ASSUME `moi_s5c_arch c h jin jout jin' jout' A Cin Cout`))) [16;23;25] THEN
  REPEAT DISCH_TAC THEN
  UNDISCH_TAC `(x:real^3) IN closure (inside (moi_s5c_sig1 c h jin jout' A Cout) INTER
                                    outside (moi_s5c_sig2 c h jin jin' Cin))` THEN
  ASM_REWRITE_TAC[IN_UNION; moi_s5c_tor; moi_s5c_npl; MOI_S5C_IN_LIFT] THEN
  STRIP_TAC THEN
  FIRST
   [(DISJ2_TAC THEN DISJ2_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
     ASM_REWRITE_TAC[IN_INTER]) THEN NO_TAC;
    (FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
       is_forall(concl th) && can (find_term ((=) `A:real^3->bool`)) (concl th) &&
       can (find_term ((=) `IMAGE (moi_s35_lift c) jout`)) (concl th))) THEN
     ASM_REWRITE_TAC[IN_UNION; MOI_S5C_IN_LIFT] THEN MESON_TAC[]) THEN NO_TAC;
    (FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
       is_forall(concl th) && can (find_term ((=) `Cin:real^3->bool`)) (concl th) &&
       can (find_term ((=) `IMAGE (moi_s35_lift c) jin`)) (concl th) &&
       not(can (find_term ((=) `A:real^3->bool`)) (concl th)))) THEN
     ASM_REWRITE_TAC[MOI_S5C_IN_LIFT] THEN MESON_TAC[]) THEN NO_TAC;
    (FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
       is_forall(concl th) && can (find_term ((=) `Cout:real^3->bool`)) (concl th) &&
       can (find_term ((=) `IMAGE (moi_s35_lift c) jout`)) (concl th) &&
       not(can (find_term ((=) `A:real^3->bool`)) (concl th)))) THEN
     ASM_REWRITE_TAC[MOI_S5C_IN_LIFT] THEN MESON_TAC[]) THEN NO_TAC;
    (UNDISCH_TAC `(x:real^3)$3 = c` THEN ASM_REWRITE_TAC[] THEN
     UNDISCH_TAC `~(c - h = c)` THEN REAL_ARITH_TAC) THEN NO_TAC]);;

let MOI_S5C_TSIG1 =
  `moi_s5c_sig1 c (s * d0) (IMAGE moi_s5c_proj (J1:real^3->bool))
     (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))
     (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb)))
     {Q x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}`;;

let MOI_S5C_TSIG2 =
  `moi_s5c_sig2 c (s * d0) (IMAGE moi_s5c_proj (J1:real^3->bool))
     (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s)))
     {Q x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s}`;;

let MOI_S5C_TV = mk_binop `(INTER):(real^3->bool)->(real^3->bool)->(real^3->bool)`
  (mk_comb(`inside:(real^3->bool)->(real^3->bool)`,MOI_S5C_TSIG1))
  (mk_comb(`outside:(real^3->bool)->(real^3->bool)`,MOI_S5C_TSIG2));;

let MOI_S5C_TT = mk_binop `(UNION):(real^3->bool)->(real^3->bool)->(real^3->bool)`
  MOI_S5C_TSIG1 MOI_S5C_TSIG2;;

let MOI_S5C_DESCENT_GEN = prove
 (`!B K FF GG Q c d0 Ja Jb J1 J2 J.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     (J1 = Ja /\ J2 = Jb \/ J1 = Jb /\ J2 = Ja) /\
     IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J2) /\
     J IN components {x | x IN B /\ x$3 = c} /\ ~(J = Ja) /\ ~(J = Jb) /\
     IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J) /\
     IMAGE moi_s5c_proj J SUBSET inside (IMAGE moi_s5c_proj J2)
     ==> ?Ja' Jb'. moi_s5c_mup B FF GG c Ja' Jb' /\
                   moi_s5c_btw B c Ja' Jb' PSUBSET moi_s5c_btw B c Ja Jb`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))))))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
    `Jb:real^3->bool`] MOI_S5C_MUP_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC (K ALL_TAC))))))) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mup] o
    check (MOI_S5C_HEAD "moi_s5c_mup")) THEN
