          is_disj(concl th) && can (find_term ((=) `J1':real^3->bool`)) (concl th))) THEN
        REWRITE_TAC[]];
      ASM_REWRITE_TAC[] THEN CONV_TAC TAUT]]);;

let MOI_S5C_DESCENT = prove
 (`!B K FF GG Q c d0 Ja Jb J.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     J IN moi_s5c_btw B c Ja Jb
     ==> ?Ja' Jb'. moi_s5c_mup B FF GG c Ja' Jb' /\
                   moi_s5c_btw B c Ja' Jb' PSUBSET moi_s5c_btw B c Ja Jb`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `(J:real^3->bool) IN moi_s5c_btw B c Ja Jb` THEN
  GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [moi_s5c_btw] THEN
  REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN MATCH_MP_TAC MOI_S5C_DESCENT_GEN THENL
   [MAP_EVERY EXISTS_TAC [`K:(real^3->bool)->bool`; `Q:real^3->real->real^3`; `d0:real`;
                          `Ja:real^3->bool`; `Jb:real^3->bool`; `J:real^3->bool`];
    MAP_EVERY EXISTS_TAC [`K:(real^3->bool)->bool`; `Q:real^3->real->real^3`; `d0:real`;
                          `Jb:real^3->bool`; `Ja:real^3->bool`; `J:real^3->bool`]] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `inside (IMAGE moi_s5c_proj (J:real^3->bool))` THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mup] o
    check (MOI_S5C_HEAD "moi_s5c_mup")) THEN
  MAP_EVERY (fun t ->
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; t]
      MOI_S5C_CIRCLE_ESS) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC])
    [`Ja:real^3->bool`; `Jb:real^3->bool`; `J:real^3->bool`] THEN
  FIRST
   [MP_TAC(ISPECL [`IMAGE moi_s5c_proj (J:real^3->bool)`; `IMAGE moi_s5c_proj (Jb:real^3->bool)`]
      MOI_S5C_PLANAR_NEST_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; SET_TAC[]] THEN NO_TAC;
    MP_TAC(ISPECL [`IMAGE moi_s5c_proj (J:real^3->bool)`; `IMAGE moi_s5c_proj (Ja:real^3->bool)`]
      MOI_S5C_PLANAR_NEST_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; SET_TAC[]] THEN NO_TAC]);;

let MOI_S5C_MIN_MUP = prove
 (`!B K FF GG Q c d0.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c
     ==> ?Ja Jb. moi_s5c_mup B FF GG c Ja Jb /\ moi_s5c_btw B c Ja Jb = {}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?n Ja Jb. moi_s5c_mup B (FF:real^2->real^3) (GG:real^3->real^2) c Ja Jb /\
                          CARD(moi_s5c_btw B c Ja Jb) = n`
  MP_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_MIDDLE_UP) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `X:real^2->bool` (X_CHOOSE_THEN `Y:real^2->bool`
      STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_CONS_CIRCLES) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `Ja:real^3->bool` STRIP_ASSUME_TAC)
      (X_CHOOSE_THEN `Jb:real^3->bool` STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`CARD(moi_s5c_btw B c (Ja:real^3->bool) Jb)`;
                          `Ja:real^3->bool`; `Jb:real^3->bool`] THEN
    REWRITE_TAC[moi_s5c_mup] THEN
    UNDISCH_TAC `moi_s5c_cons B (GG:real^3->real^2) c X Y` THEN
    UNDISCH_TAC `moi_s5c_sd (FF:real^2->real^3) c (&1) X Y` THEN
    ASM_REWRITE_TAC[] THEN SIMP_TAC[];
    ALL_TAC] THEN
  GEN_REWRITE_TAC LAND_CONV [num_WOP] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (CONJUNCTS_THEN2
    (X_CHOOSE_THEN `Ja:real^3->bool` (X_CHOOSE_THEN `Jb:real^3->bool` STRIP_ASSUME_TAC))
    ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`Ja:real^3->bool`; `Jb:real^3->bool`] THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[EXTENSION; NOT_IN_EMPTY] THEN X_GEN_TAC `J:real^3->bool` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
    `Jb:real^3->bool`; `J:real^3->bool`] MOI_S5C_DESCENT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `Ja':real^3->bool` (X_CHOOSE_THEN `Jb':real^3->bool`
    STRIP_ASSUME_TAC)) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `CARD(moi_s5c_btw B c (Ja':real^3->bool) Jb')`) THEN
  REWRITE_TAC[NOT_IMP; NOT_FORALL_THM] THEN CONJ_TAC THENL
   [UNDISCH_TAC `CARD(moi_s5c_btw B c (Ja:real^3->bool) Jb) = n` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN MATCH_MP_TAC CARD_PSUBSET THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `components {x:real^3 | x IN B /\ x$3 = c}` THEN CONJ_TAC THENL
     [FIRST_ASSUM(MP_TAC o check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
      REWRITE_TAC[moi_s5c_mset] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[moi_s5c_btw; SUBSET; IN_ELIM_THM] THEN SIMP_TAC[]];
    MAP_EVERY EXISTS_TAC [`Ja':real^3->bool`; `Jb':real^3->bool`] THEN
    ASM_REWRITE_TAC[]]);;


(* ------------------------------------------------------------------------- *)
(* The minimal arch: the planar annulus N' meets B only in the two          *)
(* sections, the square-annulus decomposition B = B_in + Rem + B_out, and   *)
(* the region V misses B.                                                    *)
(* ------------------------------------------------------------------------- *)

(* Points of B at a slab level lie on sections of the circles.              *)

let MOI_S5C_LEVEL_SECS = prove
 (`!B K FF GG Q c d0 z t.
     moi_s5c_mset B K FF GG Q c d0 /\ z IN B /\ abs t <= &1 /\ z$3 = c + t * d0
     ==> ?J. J IN components {x | x IN B /\ x$3 = c} /\ z IN moi_s5c_sec Q J t`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_COLLAR_FACTS) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `z:real^3` o check (fun th ->
    is_forall(concl th) && can (find_term ((=) `abs((z:real^3)$3 - c) <= d0`)) (concl th))) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[REAL_ARITH `(c + t * d0) - c = t * d0`; REAL_ABS_MUL] THEN
    SUBGOAL_THEN `abs d0 = d0` SUBST1_TAC THENL
     [UNDISCH_TAC `&0 < d0` THEN REAL_ARITH_TAC; ALL_TAC] THEN
    GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_LID] THEN MATCH_MP_TAC REAL_LE_RMUL THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `&0 < d0` THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:real^3` (X_CHOOSE_THEN `t':real` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `t':real = t` SUBST_ALL_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPECL [`x:real^3`; `t':real`] o check (fun th ->
      is_forall(concl th) && can (find_term ((=) `c + t * d0`)) (concl th) &&
      not(can (find_term ((=) `abs((z:real^3)$3 - c) <= d0`)) (concl th)))) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    UNDISCH_TAC `(z:real^3)$3 = c + t * d0` THEN
    UNDISCH_TAC `z = (Q:real^3->real->real^3) x t'` THEN DISCH_THEN SUBST1_TAC THEN
    ASM_REWRITE_TAC[REAL_ARITH `c + a = c + b <=> a = b`; REAL_EQ_MUL_RCANCEL] THEN
    UNDISCH_TAC `&0 < d0` THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  EXISTS_TAC `connected_component {x:real^3 | x IN B /\ x$3 = c} x` THEN CONJ_TAC THENL
   [REWRITE_TAC[components; IN_ELIM_THM] THEN EXISTS_TAC `x:real^3` THEN
    ASM_REWRITE_TAC[IN_ELIM_THM];
    REWRITE_TAC[moi_s5c_sec; IN_IMAGE] THEN EXISTS_TAC `x:real^3` THEN
    ASM_REWRITE_TAC[] THEN GEN_REWRITE_TAC I [IN] THEN
    REWRITE_TAC[CONNECTED_COMPONENT_REFL_EQ] THEN ASM_REWRITE_TAC[IN_ELIM_THM]]);;

let MOI_S5C_TJ1S =
  `IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) (J1:real^3->bool) (-- &1 * s))`;;
let MOI_S5C_TJ2S =
  `IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) (J2:real^3->bool) (-- &1 * s))`;;

(* With no circle between, the planar annulus N' at level c - s d0 meets B *)
(* only in the two sections.                                                 *)

let MOI_S5C_NPL_B = prove
 (`!B K FF GG Q c d0 Ja Jb J1 J2 s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     moi_s5c_btw B c Ja Jb = {} /\
     (J1 = Ja /\ J2 = Jb \/ J1 = Jb /\ J2 = Ja) /\
     IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J2) /\ &0 < s /\ s < &1
     ==> moi_s5c_npl (c - s * d0)
           (IMAGE moi_s5c_proj (moi_s5c_sec Q J1 (-- &1 * s)))
           (IMAGE moi_s5c_proj (moi_s5c_sec Q J2 (-- &1 * s))) INTER B =
         moi_s5c_sec Q J1 (-- &1 * s) UNION moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
    `Jb:real^3->bool`] MOI_S5C_MUP_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o CONJUNCT1)] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mup] o
    check (MOI_S5C_HEAD "moi_s5c_mup")) THEN
  SUBGOAL_THEN `J1 IN components {x:real^3 | x IN B /\ x$3 = c} /\
                J2 IN components {x:real^3 | x IN B /\ x$3 = c} /\ ~(J1 = J2)`
  STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(DISJ_CASES_THEN (CONJUNCTS_THEN SUBST1_TAC) o check (fun th ->
      is_disj(concl th) && can (find_term ((=) `J1:real^3->bool`)) (concl th))) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!J. J IN components {x:real^3 | x IN B /\ x$3 = c} /\ ~(J = J1) /\ ~(J = J2)
        ==> ~(IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J) /\
              IMAGE moi_s5c_proj J SUBSET inside (IMAGE moi_s5c_proj J2))`
  (LABEL_TAC "nb") THENL
   [X_GEN_TAC `J:real^3->bool` THEN STRIP_TAC THEN
    UNDISCH_TAC `moi_s5c_btw B c Ja Jb = {}` THEN
    REWRITE_TAC[EXTENSION; NOT_IN_EMPTY] THEN DISCH_THEN(MP_TAC o SPEC `J:real^3->bool`) THEN
    REWRITE_TAC[moi_s5c_btw; IN_ELIM_THM] THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN (CONJUNCTS_THEN SUBST_ALL_TAC) o check (fun th ->
      is_disj(concl th) && can (find_term ((=) `J1:real^3->bool`)) (concl th))) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC TAUT;
    ALL_TAC] THEN
  SUBGOAL_THEN `abs(-- &1 * s) <= &1 /\ c + (-- &1 * s) * d0 = c - s * d0`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`&0 < s`; `s < &1`] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MAP_EVERY (fun t ->
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; t; `-- &1 * s`]
      MOI_S5C_SEC_BASIC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC])
    [`J1:real^3->bool`; `J2:real^3->bool`] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `c + (-- &1 * s) * d0 = c - s * d0`]) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J1:real^3->bool`;
    `J2:real^3->bool`; `-- &1 * s`] MOI_S5C_SEC_PLANE_NEST) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  MP_TAC(ISPECL [`IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))`;
                 `IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))`]
    MOI_S5C_RG_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> ASSUME_TAC(el 6 (CONJUNCTS th))) THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER; IN_UNION; moi_s5c_npl; MOI_S5C_IN_LIFT] THEN
    X_GEN_TAC `z:real^3` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `z:real^3`;
      `-- &1 * s`] MOI_S5C_LEVEL_SECS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `J:real^3->bool` STRIP_ASSUME_TAC) THEN
    ASM_CASES_TAC `J:real^3->bool = J1` THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_CASES_TAC `J:real^3->bool = J2` THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[] THEN
    SUBGOAL_THEN `moi_s5c_proj z IN IMAGE moi_s5c_proj
                    (moi_s5c_sec (Q:real^3->real->real^3) J (-- &1 * s))` ASSUME_TAC THENL
     [MATCH_MP_TAC FUN_IN_IMAGE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
      `-- &1 * s`] MOI_S5C_SEC_BASIC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
    MAP_EVERY (fun t ->
      MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; t]
        MOI_S5C_CIRCLE_ESS) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC])
      [`J:real^3->bool`; `J1:real^3->bool`; `J2:real^3->bool`] THEN
    UNDISCH_TAC `moi_s5c_proj z IN moi_s5c_rg (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))` THEN
    REWRITE_TAC[moi_s5c_rg; IN_DIFF; IN_UNION] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
      `J1:real^3->bool`; `IMAGE moi_s5c_proj (J:real^3->bool)`;
      `IMAGE moi_s5c_proj (J1:real^3->bool)`] MOI_S5C_PLANE_NEST) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_TAC o last o CONJUNCTS) THENL
     [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
        `J1:real^3->bool`; `-- &1 * s`] MOI_S5C_SEC_PLANE_NEST) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `moi_s5c_proj z IN IMAGE moi_s5c_proj
                     (moi_s5c_sec (Q:real^3->real->real^3) J (-- &1 * s))` THEN
      UNDISCH_TAC `~(moi_s5c_proj z IN inside (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))))` THEN SET_TAC[];
      ALL_TAC] THEN
    USE_THEN "nb" (MP_TAC o SPEC `J:real^3->bool`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[] THEN DISCH_TAC] THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
      `J2:real^3->bool`; `IMAGE moi_s5c_proj (J:real^3->bool)`;
      `IMAGE moi_s5c_proj (J2:real^3->bool)`] MOI_S5C_PLANE_NEST) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o last o CONJUNCTS) THEN ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J2:real^3->bool`;
      `J:real^3->bool`; `-- &1 * s`] MOI_S5C_SEC_PLANE_NEST) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[] THEN DISCH_TAC] THEN
    MP_TAC(ISPECL [`(IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))`;
      `IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J (-- &1 * s))`]
      MOI_S5C_PLANAR_NEST_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
    MAP_EVERY UNDISCH_TAC
     [`DISJOINT (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J (-- &1 * s)))
                ((IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) UNION inside (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))))`;
      `moi_s5c_proj z IN IMAGE moi_s5c_proj
         (moi_s5c_sec (Q:real^3->real->real^3) J (-- &1 * s))`;
      `moi_s5c_proj z IN (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) \/ moi_s5c_proj z IN inside (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))`] THEN
    SET_TAC[];
    REWRITE_TAC[SUBSET; IN_INTER; IN_UNION; moi_s5c_npl] THEN X_GEN_TAC `z:real^3` THEN
    DISCH_TAC THEN CONJ_TAC THENL
     [SUBGOAL_THEN `moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s) UNION
                    moi_s5c_sec Q J2 (-- &1 * s) SUBSET
                    IMAGE (moi_s35_lift (c - s * d0)) (moi_s5c_rg (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))))` MP_TAC THENL
       [MATCH_MP_TAC(SET_RULE `!a b c d:real^3->bool.
          a = c /\ b = d /\ c UNION d SUBSET e ==> a UNION b SUBSET e`) THEN
        MAP_EVERY EXISTS_TAC [`IMAGE (moi_s35_lift (c - s * d0)) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s)))`;
                              `IMAGE (moi_s35_lift (c - s * d0)) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))`] THEN
        REPEAT CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
          REWRITE_TAC[GSYM IMAGE_UNION] THEN MATCH_MP_TAC IMAGE_SUBSET THEN
          UNDISCH_TAC `moi_s5c_rg (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) =
                       moi_s5c_rgo (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) UNION
                       (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) UNION (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))` THEN
          SET_TAC[]];
        UNDISCH_TAC `(z:real^3) IN moi_s5c_sec Q J1 (-- &1 * s) \/
                     z IN moi_s5c_sec Q J2 (-- &1 * s)` THEN
        SET_TAC[]];
      MAP_EVERY UNDISCH_TAC
       [`moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s) SUBSET B`;
        `moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s) SUBSET B`;
        `(z:real^3) IN moi_s5c_sec Q J1 (-- &1 * s) \/
         z IN moi_s5c_sec Q J2 (-- &1 * s)`] THEN
      SET_TAC[]]]);;

let MOI_S5C_FF_INJ_OPS = prove
 (`!B K FF GG Q c d0 S S2.
     moi_s5c_mset B K FF GG Q c d0 /\
     S SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
              interval(--vector[&1;&1]:real^2,vector[&1;&1]) /\
     S2 SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
              interval(--vector[&1;&1]:real^2,vector[&1;&1])
     ==> IMAGE (FF:real^2->real^3) S INTER IMAGE FF S2 = IMAGE FF (S INTER S2) /\
         IMAGE FF S DIFF IMAGE FF S2 = IMAGE FF (S DIFF S2)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  SUBGOAL_THEN `!x y:real^2. x IN S UNION S2 /\ y IN S UNION S2 /\
                  (FF:real^2->real^3) x = FF y ==> x = y` ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(AP_TERM `GG:real^3->real^2` th)) THEN
    SUBGOAL_THEN `(x:real^2) IN interval[--vector[&2;&2],vector[&2;&2]] DIFF
                                interval(--vector[&1;&1],vector[&1;&1]) /\
                  (y:real^2) IN interval[--vector[&2;&2],vector[&2;&2]] DIFF
                                interval(--vector[&1;&1],vector[&1;&1])`
    STRIP_ASSUME_TAC THENL
     [MAP_EVERY UNDISCH_TAC
       [`(x:real^2) IN S UNION S2`; `(y:real^2) IN S UNION S2`;
        `S SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                  interval(--vector[&1;&1]:real^2,vector[&1;&1])`;
        `S2 SUBSET interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF
                   interval(--vector[&1;&1]:real^2,vector[&1;&1])`] THEN
      SET_TAC[];
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  CONJ_TAC THEN CONV_TAC SYM_CONV THENL
   [MATCH_MP_TAC(SET_RULE
     `!f:real^2->real^3 s t.
        (!x y. x IN s /\ y IN t /\ f x = f y ==> x = y)
        ==> IMAGE f (s INTER t) = IMAGE f s INTER IMAGE f t`);
    MATCH_MP_TAC IMAGE_DIFF_INJ] THEN
  REPEAT STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[IN_UNION]);;

let MOI_S5C_RG_R1R2 = prove
 (`moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))
              (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) =
   interval[--vector[&2;&2],vector[&2;&2]] DIFF interval(--vector[&1;&1],vector[&1;&1])`,
  MP_TAC(SPEC `&1` MOI_S5C_SQ_JORDAN) THEN MP_TAC(SPEC `&2` MOI_S5C_SQ_JORDAN) THEN
  REWRITE_TAC[REAL_OF_NUM_LT; ARITH] THEN REPEAT STRIP_TAC THEN
  ASM_REWRITE_TAC[moi_s5c_rg; EXTENSION; IN_UNION; IN_DIFF; MOI_S5C_IN_RF2; MOI_S5C_IN_SQO;
                  MOI_S5C_IN_SQI] THEN
  REAL_ARITH_TAC);;

(* The square-annulus decomposition of B along the two sections.           *)

let MOI_S5C_MUP_DECOMP = prove
 (`!B K FF GG Q c d0 Ja Jb s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     &0 < s /\ s < &1
     ==> B = IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))) UNION IMAGE FF (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))) UNION
             IMAGE FF (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))) /\
         IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))) INTER IMAGE FF (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))) = (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) /\
         IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))) INTER IMAGE FF (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))) = (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)) /\
         IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))) INTER IMAGE FF (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))) = {} /\
         IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))) =
           {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s} UNION IMAGE FF (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE (GG:real^3->real^2) Jb)) UNION {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s} /\
         pl_annulus_with_ends (IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) (IMAGE FF (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) /\
         pl_annulus_with_ends (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)) /\
         pl_annulus_with_ends (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)) (IMAGE FF (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))) /\
         connected (IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))) DIFF (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) /\
         connected (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))) DIFF (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) /\
         connected (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))) DIFF ((moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))) /\
         ~(IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))) DIFF ((moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) = {}) /\
         IMAGE (FF:real^2->real^3) (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) SUBSET IMAGE FF (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))) DIFF (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) /\
         IMAGE (FF:real^2->real^3) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) SUBSET IMAGE FF (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))) DIFF (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)) /\
         compact (IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) /\
         compact (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) /\
         compact (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_MSET_FACTS) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
    `Jb:real^3->bool`; `s:real`] MOI_S5C_MUP_A0) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(SPEC `&1` MOI_S5C_SQ_JORDAN) THEN MP_TAC(SPEC `&2` MOI_S5C_SQ_JORDAN) THEN
  REWRITE_TAC[REAL_OF_NUM_LT; ARITH] THEN
  DISCH_THEN(STRIP_ASSUME_TAC) THEN DISCH_THEN(STRIP_ASSUME_TAC) THEN
  (* nesting of the four circles *)
  SUBGOAL_THEN `(relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) SUBSET inside (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) /\ (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) SUBSET inside (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) /\ (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) SUBSET inside (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `interval[--vector[&1;&1]:real^2,vector[&1;&1]]` THEN
      ASM_SIMP_TAC[RELATIVE_FRONTIER_SUBSET; CLOSED_INTERVAL];
      MP_TAC(ISPECL [`(IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))`; `(IMAGE (GG:real^3->real^2) Ja)`] MOI_S5C_PLANAR_NEST_FACTS) THEN
      MP_TAC(ISPECL [`(IMAGE (GG:real^3->real^2) Ja)`; `(IMAGE (GG:real^3->real^2) Jb)`] MOI_S5C_PLANAR_NEST_FACTS) THEN
      MP_TAC(ISPECL [`(IMAGE (GG:real^3->real^2) Jb)`; `(IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))`] MOI_S5C_PLANAR_NEST_FACTS) THEN
      ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `(IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) SUBSET inside (IMAGE (GG:real^3->real^2) Ja)` THEN SET_TAC[];
      ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `(IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1])) DIFF ((relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))` THEN
      REWRITE_TAC[SUBSET; IN_DIFF; IN_UNION; MOI_S5C_IN_SQANN; MOI_S5C_IN_RF2;
                  MOI_S5C_IN_RF1; MOI_S5C_IN_SQO] THEN
      MESON_TAC[REAL_LT_LE]];
    ALL_TAC] THEN
  SUBGOAL_THEN `pl_sphere 1 (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) /\ pl_sphere 1 (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) /\ inside (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) = interval(--vector[&1;&1],vector[&1;&1]) /\
                inside (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) = interval(--vector[&2;&2],vector[&2;&2])` STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(IMAGE (GG:real^3->real^2) Ja) SUBSET inside (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) /\ (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) SUBSET inside (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) /\ (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) SUBSET inside (IMAGE (GG:real^3->real^2) Jb)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(IMAGE (GG:real^3->real^2) Ja)`; `(IMAGE (GG:real^3->real^2) Jb)`] MOI_S5C_PLANAR_NEST_FACTS) THEN
    MP_TAC(ISPECL [`(IMAGE (GG:real^3->real^2) Jb)`; `(IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))`] MOI_S5C_PLANAR_NEST_FACTS) THEN
    MP_TAC(ISPECL [`(IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))`; `(relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`] MOI_S5C_PLANAR_NEST_FACTS) THEN
    MP_TAC(ISPECL [`(IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))`; `(IMAGE (GG:real^3->real^2) Ja)`] MOI_S5C_PLANAR_NEST_FACTS) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY UNDISCH_TAC [`(IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) SUBSET inside (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))`; `(IMAGE (GG:real^3->real^2) Ja) SUBSET inside (IMAGE (GG:real^3->real^2) Jb)`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`(relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))`; `(IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))`; `(relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`] MOI_S5C_RG_UNION) THEN
