    SUBGOAL_THEN `(moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)) = IMAGE (FF:real^2->real^3) ((IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) UNION (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))` SUBST1_TAC THENL
     [REWRITE_TAC[IMAGE_UNION] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(fun th -> GEN_REWRITE_TAC (RAND_CONV o LAND_CONV) [th]) THEN
    UNDISCH_TAC `moi_s5c_rgo (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) = moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) DIFF ((IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) UNION (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
    GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [SYM(ASSUME `IMAGE (FF:real^2->real^3) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) = (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))`)] THEN
    FIRST_ASSUM(fun th -> GEN_REWRITE_TAC RAND_CONV [th]) THEN MATCH_MP_TAC IMAGE_SUBSET THEN
    UNDISCH_TAC `moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) = moi_s5c_rgo (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) UNION (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))` THEN
    UNDISCH_TAC `(IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1])) DIFF ((relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))` THEN SET_TAC[];
    GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [SYM(ASSUME `IMAGE (FF:real^2->real^3) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) = (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))`)] THEN
    FIRST_ASSUM(fun th -> GEN_REWRITE_TAC RAND_CONV [th]) THEN MATCH_MP_TAC IMAGE_SUBSET THEN
    UNDISCH_TAC `moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) = moi_s5c_rgo (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) UNION (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) UNION (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))` THEN
    UNDISCH_TAC `(IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1])) DIFF ((relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))` THEN SET_TAC[];
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;


(* A connected set missing the frontier of an open set V, with a point     *)
(* outside V, misses V.                                                      *)

let MOI_S5C_CONN_MISS_V = prove
 (`!D V TT p:real^3.
     connected D /\ D INTER TT = {} /\ closure V = V UNION TT /\ open V /\
     p IN D /\ ~(p IN V)
     ==> D INTER V = {}`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(SET_RULE `!d v w:real^3->bool. d SUBSET w /\ w INTER v = {} ==> d INTER v = {}`) THEN
  EXISTS_TAC `(:real^3) DIFF closure V` THEN
  CONJ_TAC THENL [ALL_TAC; MP_TAC(ISPEC `V:real^3->bool` CLOSURE_SUBSET) THEN SET_TAC[]] THEN
  MATCH_MP_TAC MOI_S5C_CONN_SUB THEN EXISTS_TAC `V:real^3->bool` THEN
  ASM_REWRITE_TAC[GSYM closed; CLOSED_CLOSURE] THEN REPEAT CONJ_TAC THENL
   [UNDISCH_TAC `closure V = V UNION (TT:real^3->bool)` THEN
    UNDISCH_TAC `D INTER TT:real^3->bool = {}` THEN SET_TAC[];
    MP_TAC(ISPEC `V:real^3->bool` CLOSURE_SUBSET) THEN SET_TAC[];
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER; IN_DIFF; IN_UNIV] THEN
    EXISTS_TAC `p:real^3` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `closure V = V UNION (TT:real^3->bool)` THEN
    UNDISCH_TAC `D INTER TT:real^3->bool = {}` THEN
    UNDISCH_TAC `(p:real^3) IN D` THEN UNDISCH_TAC `~((p:real^3) IN V)` THEN SET_TAC[]]);;

(* The torus of the minimal arch is Rem UNION N', and V misses B.            *)

let MOI_S5C_MIN_TOR_VB = prove
 (`!B K FF GG Q c d0 Ja Jb J1 J2 s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     moi_s5c_btw B c Ja Jb = {} /\
     (J1 = Ja /\ J2 = Jb \/ J1 = Jb /\ J2 = Ja) /\
     IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J2) /\ &0 < s /\ s < &1
     ==> (moi_s5c_tor c (s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb))) {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s} {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}) = IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))) UNION (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) /\
         (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) INTER B = (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)) /\
         (inside (moi_s5c_sig1 c (s * d0) (IMAGE moi_s5c_proj (J1:real^3->bool)) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb))) {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}) INTER outside (moi_s5c_sig2 c (s * d0) (IMAGE moi_s5c_proj (J1:real^3->bool)) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s})) INTER B = {}`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
    `Jb:real^3->bool`; `s:real`] MOI_S5C_MUP_DECOMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  FIRST_X_ASSUM(ASSUME_TAC o SYM o check (fun th ->
    is_eq(concl th) && lhs(concl th) = `B:real^3->bool`)) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
    `Jb:real^3->bool`; `J1:real^3->bool`; `J2:real^3->bool`; `s:real`] MOI_S5C_NPL_B) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  SUBGOAL_THEN `(moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)) = (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)) /\
                {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s} UNION {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s} = {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s} UNION {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s}` STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(DISJ_CASES_THEN (CONJUNCTS_THEN SUBST1_TAC) o check (fun th ->
      is_disj(concl th) && can (find_term ((=) `J1:real^3->bool`)) (concl th))) THEN
    REWRITE_TAC[] THEN CONJ_TAC THEN MATCH_ACCEPT_TAC UNION_COMM;
    ALL_TAC] THEN
  SUBGOAL_THEN `(moi_s5c_tor c (s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb))) {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s} {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}) = IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))) UNION (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))))` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[moi_s5c_tor] THEN
    UNDISCH_TAC `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s} UNION {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s} = {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s} UNION {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s}` THEN
    MOI_S5C_ABS_SET_TAC
     [`{(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s}`;
      `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}`;
      `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s}`;
      `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s}`;
      `IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb))`;
      `moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))`];
    ALL_TAC] THEN
  SUBGOAL_THEN `(moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) INTER B = (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))` ASSUME_TAC THENL
   [MATCH_MP_TAC EQ_TRANS THEN EXISTS_TAC `(moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))` THEN
