    FIRST_X_ASSUM(DISJ_CASES_THEN (CONJUNCTS_THEN SUBST_ALL_TAC) o check (fun th ->
      is_disj(concl th) && can (find_term ((=) `J1:real^3->bool`)) (concl th))) THEN
    ASM_SIMP_TAC[];
    ALL_TAC] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP MOI_S5C_ARCH_V) THEN
  SUBGOAL_THEN `~(IMAGE (FF:real^2->real^3) (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) = {}) /\ ~(IMAGE (FF:real^2->real^3) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])) = {}) /\
                DISJOINT (IMAGE (FF:real^2->real^3) (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) UNION IMAGE (FF:real^2->real^3) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))) moi_s35_ttube`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[IMAGE_EQ_EMPTY; CONJ_ASSOC] THEN CONJ_TAC THENL
     [MP_TAC(SPEC `&1` MOI_S5C_SQ_JORDAN) THEN MP_TAC(SPEC `&2` MOI_S5C_SQ_JORDAN) THEN
      REWRITE_TAC[REAL_OF_NUM_LT; ARITH] THEN MESON_TAC[MOI_SCD_PL_SPHERE_NONEMPTY];
      FIRST_ASSUM(MP_TAC o check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
