    ALL_TAC] THEN
  SUBGOAL_THEN `(inside (moi_s5c_sig1 c (s * d0) (IMAGE moi_s5c_proj (J1:real^3->bool)) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb))) {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}) INTER outside (moi_s5c_sig2 c (s * d0) (IMAGE moi_s5c_proj (J1:real^3->bool)) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s})) SUBSET moi_s35_ttube` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `moi_s5c_otube` THEN
    ASM_REWRITE_TAC[MOI_S5C_OTUBE];
    ALL_TAC] THEN
  SUBGOAL_THEN `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))) DIFF (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) INTER (moi_s5c_tor c (s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb))) {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s} {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}) = {} /\
