(* ------------------------------------------------------------------------- *)
(* A triangulation of a UNION N (the kept part a of B and a planar           *)
(* polyhedron N at a level c' meeting a along k') with no vertex at level c. *)
(* ------------------------------------------------------------------------- *)

(* The clopen part k' of the level set of E UNION a at c' (as in the         *)
(* proof of MOI_S5C_SPLIT_COMPLEX).                                          *)

let MOI_S5C_LEV_CLOPEN = prove
 (`!E a k' c' s:real^3->bool.
     closed E /\ closed a /\ E INTER a = k' /\
     open_in (subtopology euclidean {x | x IN E UNION a /\ x$3 = c'}) k' /\
     connected s /\ s SUBSET {x | x IN E UNION a /\ x$3 = c'} /\ ~(s INTER k' = {})
     ==> s SUBSET k'`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [OPEN_IN_OPEN]) THEN
  DISCH_THEN(X_CHOOSE_THEN `ow:real^3->bool` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`s:real^3->bool`; `E INTER a:real^3->bool`;
     `{x:real^3 | x IN E UNION a /\ x$3 = c'} DIFF ow`] MOI_S5C_CONN_TWO_CLOSED) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[CLOSED_INTER] THEN CONJ_TAC THENL
     [MATCH_MP_TAC CLOSED_DIFF THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `{x:real^3 | x IN E UNION a /\ x$3 = c'} =
                    (E UNION a) INTER {x | x$3 = c'}` SUBST1_TAC THENL
       [SET_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC CLOSED_INTER THEN
      ASM_SIMP_TAC[CLOSED_UNION; CLOSED_STANDARD_HYPERPLANE];
      ALL_TAC] THEN
    UNDISCH_TAC `E INTER a:real^3->bool = k'` THEN
    UNDISCH_TAC `k':real^3->bool = {x | x IN E UNION a /\ x$3 = c'} INTER ow` THEN
    UNDISCH_TAC `(s:real^3->bool) SUBSET {x | x IN E UNION a /\ x$3 = c'}` THEN
    SET_TAC[];
    ALL_TAC] THEN
  UNDISCH_TAC `E INTER a:real^3->bool = k'` THEN
  UNDISCH_TAC `k':real^3->bool = {x | x IN E UNION a /\ x$3 = c'} INTER ow` THEN
  UNDISCH_TAC `~(s INTER k':real^3->bool = {})` THEN
  SET_TAC[]);;

(* Every point of k' lies in a simplex of L inside k'.                      *)

let MOI_S5C_KCOVER = prove
 (`!(L:(real^3->bool)->bool) E a k' c'.
     simplicial_complex L /\ UNIONS L = E UNION a /\ closed E /\ closed a /\
     E INTER a = k' /\ (!x. x IN k' ==> x$3 = c') /\
     open_in (subtopology euclidean {x | x IN E UNION a /\ x$3 = c'}) k' /\
     (!s. s IN L ==> (!x. x IN s ==> x$3 <= c') \/ (!x. x IN s ==> c' <= x$3))
     ==> !x. x IN k' ==> ?s. s IN L /\ x IN s /\ s SUBSET k'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`L:(real^3->bool)->bool`; `c':real`] MOI_S5C_CUT_LEVEL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `x:real^3`) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [ALL_TAC; ASM_SIMP_TAC[]] THEN
    UNDISCH_TAC `(x:real^3) IN k'` THEN
    UNDISCH_TAC `E INTER a:real^3->bool = k'` THEN
    UNDISCH_TAC `UNIONS L:real^3->bool = E UNION a` THEN SET_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:real^3->bool` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `s:real^3->bool` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MOI_S5C_LEV_CLOPEN THEN
  MAP_EVERY EXISTS_TAC [`E:real^3->bool`; `a:real^3->bool`; `c':real`] THEN
  ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [ASM_MESON_TAC[simplicial_complex; SIMPLEX_IMP_CONVEX; CONVEX_CONNECTED];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [ALL_TAC;
    UNDISCH_TAC `(x:real^3) IN k'` THEN UNDISCH_TAC `(x:real^3) IN s` THEN
    SET_TAC[]] THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `y:real^3` THEN DISCH_TAC THEN
  ASM_SIMP_TAC[] THEN
  UNDISCH_TAC `UNIONS L:real^3->bool = E UNION a` THEN
  UNDISCH_TAC `(y:real^3) IN s` THEN UNDISCH_TAC `(s:real^3->bool) IN L` THEN
  SET_TAC[]);;

(* A simplex of a complex is the hull of finitely many vertices of it.     *)

let MOI_S5C_SC_HULL = prove
 (`!(L:(real^N->bool)->bool) s.
     simplicial_complex L /\ s IN L
     ==> ?V. FINITE V /\ s = convex hull V /\ !v. v IN V ==> {v} IN L`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?n. n simplex (s:real^N->bool)` MP_TAC THENL
   [ASM_MESON_TAC[simplicial_complex]; ALL_TAC] THEN
  REWRITE_TAC[simplex; LEFT_IMP_EXISTS_THM] THEN
  MAP_EVERY X_GEN_TAC [`n:int`; `V:real^N->bool`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (K ALL_TAC) SUBST_ALL_TAC)) THEN
  EXISTS_TAC `V:real^N->bool` THEN ASM_SIMP_TAC[AFFINE_INDEPENDENT_IMP_FINITE] THEN
  X_GEN_TAC `v:real^N` THEN DISCH_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
    GEN_REWRITE_RULE I [simplicial_complex]) THEN
  EXISTS_TAC `convex hull V:real^N->bool` THEN ASM_REWRITE_TAC[] THEN
  ASM_SIMP_TAC[FACE_OF_CONVEX_HULL_AFFINE_INDEPENDENT] THEN
  EXISTS_TAC `{v:real^N}` THEN ASM_REWRITE_TAC[CONVEX_HULL_SING; SING_SUBSET]);;

(* Merging a complex l' on a (each simplex on one side of the level c') with *)
(* a complex t on the flat N (at level c'), when a INTER N = k' is clopen in *)
(* the level set of a and the simplices of l' inside k' belong to t.        *)

let MOI_S5C_TP_MERGE = prove
 (`!(l':(real^3->bool)->bool) t k' a N c'.
     simplicial_complex l' /\ simplicial_complex t /\
     UNIONS l' = a /\ UNIONS t = N /\ a INTER N = k' /\
     (!x. x IN N ==> x$3 = c') /\
     (!s. s IN l' ==> (!x. x IN s ==> x$3 <= c') \/ (!x. x IN s ==> c' <= x$3)) /\
     (!s. s IN l' /\ ~(s = {}) /\ s SUBSET k' ==> s IN t) /\
     (!s. connected s /\ s SUBSET {x | x IN a /\ x$3 = c'} /\ ~(s INTER k' = {})
          ==> s SUBSET k')
     ==> simplicial_complex (l' UNION t)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "sides") (CONJUNCTS_THEN2 (LABEL_TAC "kt")
       (LABEL_TAC "lev"))))))))) THEN
  SUBGOAL_THEN
   `!s tau:real^3->bool. s IN l' /\ tau IN t
        ==> (s INTER tau) face_of s /\ (s INTER tau) face_of tau`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `convex(s:real^3->bool)` ASSUME_TAC THENL
     [ASM_MESON_TAC[simplicial_complex; SIMPLEX_IMP_CONVEX]; ALL_TAC] THEN
    ABBREV_TAC `F0 = (s:real^3->bool) INTER {x | x$3 = c'}` THEN
    SUBGOAL_THEN `(F0:real^3->bool) face_of s` ASSUME_TAC THENL
     [EXPAND_TAC "F0" THEN
      SUBGOAL_THEN `{x:real^3 | x$3 = c'} = {x | basis 3 dot x = c'}` SUBST1_TAC THENL
       [SIMP_TAC[DOT_BASIS; DIMINDEX_3; ARITH]; ALL_TAC] THEN
      USE_THEN "sides" (DISJ_CASES_TAC o C MATCH_MP (ASSUME `(s:real^3->bool) IN l'`)) THENL
       [MATCH_MP_TAC FACE_OF_INTER_SUPPORTING_HYPERPLANE_LE;
        MATCH_MP_TAC FACE_OF_INTER_SUPPORTING_HYPERPLANE_GE] THEN
      ASM_SIMP_TAC[DOT_BASIS; DIMINDEX_3; ARITH; real_ge];
      ALL_TAC] THEN
    SUBGOAL_THEN `(s:real^3->bool) SUBSET a /\ (tau:real^3->bool) SUBSET N`
    STRIP_ASSUME_TAC THENL
     [MAP_EVERY UNDISCH_TAC
       [`UNIONS l':real^3->bool = a`; `UNIONS t:real^3->bool = N`;
        `(s:real^3->bool) IN l'`; `(tau:real^3->bool) IN t`] THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `s INTER tau:real^3->bool = F0 INTER tau` SUBST1_TAC THENL
     [EXPAND_TAC "F0" THEN
      MAP_EVERY UNDISCH_TAC
       [`(tau:real^3->bool) SUBSET N`; `!x:real^3. x IN N ==> x$3 = c'`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `F0 INTER k':real^3->bool = {}` THENL
     [SUBGOAL_THEN `F0 INTER tau:real^3->bool = {}` SUBST1_TAC THENL
       [MAP_EVERY UNDISCH_TAC
         [`F0 INTER k':real^3->bool = {}`; `(F0:real^3->bool) face_of s`;
          `(s:real^3->bool) SUBSET a`; `(tau:real^3->bool) SUBSET N`;
          `a INTER N:real^3->bool = k'`] THEN
        REWRITE_TAC[face_of] THEN SET_TAC[];
        REWRITE_TAC[EMPTY_FACE_OF]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(F0:real^3->bool) SUBSET k'` ASSUME_TAC THENL
     [USE_THEN "lev" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MATCH_MP_TAC CONVEX_CONNECTED THEN ASM_MESON_TAC[FACE_OF_IMP_CONVEX];
        EXPAND_TAC "F0" THEN UNDISCH_TAC `(s:real^3->bool) SUBSET a` THEN SET_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(F0:real^3->bool) IN t` ASSUME_TAC THENL
     [USE_THEN "kt" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[simplicial_complex];
        UNDISCH_TAC `~(F0 INTER k':real^3->bool = {})` THEN SET_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(F0 INTER tau:real^3->bool) face_of F0 /\ (F0 INTER tau) face_of tau`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[simplicial_complex]; ALL_TAC] THEN
    ASM_MESON_TAC[FACE_OF_TRANS];
    ALL_TAC] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o GEN_REWRITE_RULE I [simplicial_complex] o check (fun th ->
    concl th = `simplicial_complex (l':(real^3->bool)->bool)`)) THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o GEN_REWRITE_RULE I [simplicial_complex] o check (fun th ->
    concl th = `simplicial_complex (t:(real^3->bool)->bool)`)) THEN
  REWRITE_TAC[simplicial_complex; IN_UNION; FINITE_UNION] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [ASM_MESON_TAC[];
    ASM_MESON_TAC[];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST [ASM_SIMP_TAC[] THEN NO_TAC;
           ONCE_REWRITE_TAC[INTER_COMM] THEN ASM_SIMP_TAC[] THEN NO_TAC]]);;

(* A triangulation of the polyhedron N whose restriction to k' subdivides   *)
(* a given complex fk on k'.                                                 *)

let MOI_S5C_TP_REFINE = prove
 (`!N (fk:(real^3->bool)->bool) k'.
     pl_polyhedron N /\ simplicial_complex fk /\ UNIONS fk = k' /\ k' SUBSET N /\
     ~(k' = {})
     ==> ?t. simplicial_complex t /\ UNIONS t = N /\
             (!s. s IN {s | s IN t /\ s SUBSET k'} ==> ?u. u IN fk /\ s SUBSET u) /\
             (!u. u IN fk ==> ?e. e SUBSET {s | s IN t /\ s SUBSET k'} /\ u = UNIONS e) /\
             UNIONS {s | s IN t /\ s SUBSET k'} = k'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [pl_polyhedron]) THEN
  DISCH_THEN(X_CHOOSE_THEN `cN:(real^3->bool)->bool` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPEC `cN UNION fk:(real^3->bool)->bool` POLYTOPES_SIMPLICIAL_REFINEMENT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[FINITE_UNION; IN_UNION] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[simplicial_complex];
      ASM_MESON_TAC[simplicial_complex; SIMPLEX_IMP_POLYTOPE]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `t:(real^3->bool)->bool`
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "cov")))) THEN
  EXISTS_TAC `t:(real^3->bool)->bool` THEN
  SUBGOAL_THEN `UNIONS t:real^3->bool = N` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[UNIONS_UNION] THEN
    MAP_EVERY UNDISCH_TAC [`UNIONS fk:real^3->bool = k'`; `k':real^3->bool SUBSET N`;
                           `N:real^3->bool = UNIONS cN`] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:real^3->bool. u IN fk
       ==> ?e. e SUBSET {s | s IN t /\ s SUBSET k'} /\ u = UNIONS e`
  ASSUME_TAC THENL
   [X_GEN_TAC `u:real^3->bool` THEN DISCH_TAC THEN
    USE_THEN "cov" (MP_TAC o SPEC `u:real^3->bool`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[IN_UNION]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `e:(real^3->bool)->bool` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `e:(real^3->bool)->bool` THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY UNDISCH_TAC
     [`(e:(real^3->bool)->bool) SUBSET t`; `u:real^3->bool = UNIONS e`;
      `(u:real^3->bool) IN fk`; `UNIONS fk:real^3->bool = k'`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `UNIONS {s | s IN t /\ s SUBSET k'} = k':real^3->bool` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL [SET_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `UNIONS fk:real^3->bool = k'` THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    GEN_REWRITE_TAC I [SUBSET] THEN REWRITE_TAC[IN_UNIONS] THEN
    X_GEN_TAC `x:real^3` THEN
    DISCH_THEN(X_CHOOSE_THEN `u:real^3->bool` STRIP_ASSUME_TAC) THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `u:real^3->bool` o check (fun th ->
      is_forall(concl th) && can (find_term ((=) `fk:(real^3->bool)->bool`)) (concl th) &&
      can (find_term ((=) `UNIONS:((real^3->bool)->bool)->real^3->bool`)) (concl th))) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `e:(real^3->bool)->bool` STRIP_ASSUME_TAC) THEN
    UNDISCH_TAC `(x:real^3) IN u` THEN ASM_REWRITE_TAC[IN_UNIONS] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:real^3->bool` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w:real^3->bool` THEN ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  X_GEN_TAC `s:real^3->bool` THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
  ASM_CASES_TAC `s:real^3->bool = {}` THENL
   [UNDISCH_TAC `~(k':real^3->bool = {})` THEN
    UNDISCH_TAC `UNIONS fk:real^3->bool = k'` THEN
    ASM_REWRITE_TAC[EMPTY_SUBSET] THEN SET_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC MOI_PLT_SIMPLEX_IN_COVER THEN
  EXISTS_TAC `t:(real^3->bool)->bool` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `k':real^3->bool` THEN
  ASM_REWRITE_TAC[] THEN
  UNDISCH_TAC `UNIONS fk:real^3->bool = k'` THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  REWRITE_TAC[SUBSET; IN_UNIONS; IN_ELIM_THM] THEN
  X_GEN_TAC `x:real^3` THEN
  DISCH_THEN(X_CHOOSE_THEN `u:real^3->bool` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `u:real^3->bool` THEN ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real^3->bool` o check (fun th ->
    is_forall(concl th) && can (find_term ((=) `fk:(real^3->bool)->bool`)) (concl th) &&
    can (find_term ((=) `UNIONS:((real^3->bool)->bool)->real^3->bool`)) (concl th))) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:(real^3->bool)->bool` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `e:(real^3->bool)->bool` THEN ASM_REWRITE_TAC[] THEN ASM SET_TAC[]);;

(* Extending a subdivision tk of the subcomplex fk of La to a subdivision of *)
(* La, with the new cone points chosen off the level c.                      *)

let MOI_S5C_TP_EXTEND = prove
 (`!(La:(real^3->bool)->bool) fk tk c.
     simplicial_complex La /\ simplicial_complex fk /\ fk SUBSET La /\
     simplicial_complex tk /\ UNIONS tk = UNIONS fk /\
     (!s. s IN tk ==> ?u. u IN fk /\ s SUBSET u) /\
     (!u. u IN fk ==> ?e. e SUBSET tk /\ u = UNIONS e) /\
     (!v. {v} IN La ==> ~(v$3 = c)) /\
     (!x. x IN UNIONS tk ==> ~(x$3 = c))
     ==> ?l'. simplicial_complex l' /\ UNIONS l' = UNIONS La /\
              (!s. s IN l' ==> ?u. u IN La /\ s SUBSET u) /\
              (!s. s IN l' /\ ~(s = {}) /\ s SUBSET UNIONS fk ==> s IN tk) /\
              (!v. {v} IN l' ==> ~(v$3 = c))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!u:real^3->bool. u IN La /\ ~(u = {})
       ==> (@z:real^3. z IN relative_interior u /\ ~(z$3 = c)) IN relative_interior u /\
           ~((@z:real^3. z IN relative_interior u /\ ~(z$3 = c))$3 = c)`
  (LABEL_TAC "zf") THENL
   [X_GEN_TAC `u:real^3->bool` THEN STRIP_TAC THEN
    CONV_TAC SELECT_CONV THEN MATCH_MP_TAC MOI_S5C_RI_OFF_LEVEL THEN CONJ_TAC THENL
     [ASM_MESON_TAC[simplicial_complex; SIMPLEX_IMP_CONVEX]; ALL_TAC] THEN
    MP_TAC(ISPECL [`La:(real^3->bool)->bool`; `u:real^3->bool`] MOI_S5C_SC_VERTEX) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`La:(real^3->bool)->bool`; `fk:(real^3->bool)->bool`;
                 `tk:(real^3->bool)->bool`;
                 `\u:real^3->bool. @z:real^3. z IN relative_interior u /\ ~(z$3 = c)`;
                 `\s:real^3->bool. ?V. FINITE V /\ s = convex hull V /\
                                       !v:real^3. v IN V ==> ~(v$3 = c)`]
    MOI_S5C_EXTEND_POINTED) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [X_GEN_TAC `u:real^3->bool` THEN STRIP_TAC THEN
      USE_THEN "zf" (MP_TAC o SPEC `u:real^3->bool`) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        UNDISCH_TAC `~DISJOINT u (UNIONS fk:real^3->bool)` THEN SET_TAC[];
        SIMP_TAC[]];
      X_GEN_TAC `s:real^3->bool` THEN DISCH_TAC THEN
      MP_TAC(ISPECL [`tk:(real^3->bool)->bool`; `s:real^3->bool`] MOI_S5C_SC_HULL) THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN
      X_GEN_TAC `V:real^3->bool` THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `v:real^3` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `UNIONS tk:real^3->bool`)) (concl th) &&
        not (can (find_term ((=) `UNIONS fk:real^3->bool`)) (concl th)))) THEN
      REWRITE_TAC[IN_UNIONS] THEN EXISTS_TAC `{v:real^3}` THEN
      ASM_SIMP_TAC[IN_SING];
      X_GEN_TAC `u:real^3->bool` THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`La:(real^3->bool)->bool`; `u:real^3->bool`] MOI_S5C_SC_HULL) THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN
      X_GEN_TAC `V:real^3->bool` THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[];
      MAP_EVERY X_GEN_TAC [`u:real^3->bool`; `s:real^3->bool`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `V:real^3->bool` STRIP_ASSUME_TAC))))) THEN
      USE_THEN "zf" (MP_TAC o SPEC `u:real^3->bool`) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        UNDISCH_TAC `~DISJOINT u (UNIONS fk:real^3->bool)` THEN SET_TAC[];
        ALL_TAC] THEN
      ABBREV_TAC `z = @z:real^3. z IN relative_interior u /\ ~(z$3 = c)` THEN
      STRIP_TAC THEN EXISTS_TAC `(z:real^3) INSERT V` THEN
      ASM_REWRITE_TAC[FINITE_INSERT; FORALL_IN_INSERT] THEN
      ONCE_REWRITE_TAC[HULL_INSERT] THEN REWRITE_TAC[HULL_HULL]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `l':(real^3->bool)->bool` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `l':(real^3->bool)->bool` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `v:real^3` THEN DISCH_TAC THEN
  SUBGOAL_THEN `?V:real^3->bool. FINITE V /\ {v} = convex hull V /\
                                 (!w. w IN V ==> ~(w$3 = c))`
  (X_CHOOSE_THEN `V:real^3->bool` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?w:real^3. w IN V` STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[MEMBER_NOT_EMPTY] THEN DISCH_TAC THEN
    UNDISCH_TAC `{v:real^3} = convex hull V` THEN
    ASM_REWRITE_TAC[CONVEX_HULL_EMPTY] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(w:real^3) = v` (fun th -> ASM_MESON_TAC[th]) THEN
  MP_TAC(ISPECL [`convex:(real^3->bool)->bool`; `V:real^3->bool`] HULL_SUBSET) THEN
  UNDISCH_TAC `{v:real^3} = convex hull V` THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  UNDISCH_TAC `(w:real^3) IN V` THEN SET_TAC[]);;

(* The triangulation of a UNION N: cut K at c', keep the part on a, refine  *)
(* the flat N together with the cut complex on k', extend, and merge.       *)

let MOI_S5C_TRIANG_PLANAR = prove
 (`!(K:(real^3->bool)->bool) E a k' N c c'.
     simplicial_complex K /\ UNIONS K = E UNION a /\ ~(c' = c) /\
     (!v. {v} IN K ==> ~(v$3 = c) /\ ~(v$3 = c')) /\
     closed E /\ closed a /\ E INTER a = k' /\ ~(k' = {}) /\
     (!x. x IN k' ==> x$3 = c') /\
     open_in (subtopology euclidean {x | x IN E UNION a /\ x$3 = c'}) k' /\
     pl_polyhedron N /\ (!x. x IN N ==> x$3 = c') /\ a INTER N = k'
     ==> ?L. FINITE L /\ simplicial_complex L /\ UNIONS L = a UNION N /\
             !v. {v} IN L ==> ~(v$3 = c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`K:(real^3->bool)->bool`; `c:real`; `c':real`] MOI_S5C_CUT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `L0:(real^3->bool)->bool` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `UNIONS L0:real^3->bool = E UNION a` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`L0:(real^3->bool)->bool`; `E:real^3->bool`; `a:real^3->bool`;
                 `k':real^3->bool`; `c':real`] MOI_S5C_SPLIT_COMPLEX) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`L0:(real^3->bool)->bool`; `E:real^3->bool`; `a:real^3->bool`;
                 `k':real^3->bool`; `c':real`] MOI_S5C_KCOVER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  ABBREV_TAC `La = {s:real^3->bool | s IN L0 /\ s SUBSET a}` THEN
  ABBREV_TAC `fk = {s:real^3->bool | s IN L0 /\ s SUBSET k'}` THEN
  SUBGOAL_THEN `simplicial_complex (La:(real^3->bool)->bool) /\
                simplicial_complex (fk:(real^3->bool)->bool) /\
                fk SUBSET La /\ UNIONS fk = k' /\ k' SUBSET N /\ k' SUBSET a`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["La"; "fk"] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC MOI_S5C_SUBCOMPLEX_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC MOI_S5C_SUBCOMPLEX_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
      UNDISCH_TAC `E INTER a:real^3->bool = k'` THEN SET_TAC[];
      MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
       [REWRITE_TAC[SUBSET; IN_UNIONS; IN_ELIM_THM] THEN MESON_TAC[]; ALL_TAC] THEN
      GEN_REWRITE_TAC I [SUBSET] THEN REWRITE_TAC[IN_UNIONS; IN_ELIM_THM] THEN
      X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `L0:(real^3->bool)->bool`)) (concl th) &&
        can (find_term ((=) `k':real^3->bool`)) (concl th))) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[];
      UNDISCH_TAC `a INTER N:real^3->bool = k'` THEN SET_TAC[];
      UNDISCH_TAC `E INTER a:real^3->bool = k'` THEN SET_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`N:real^3->bool`; `fk:(real^3->bool)->bool`; `k':real^3->bool`]
    MOI_S5C_TP_REFINE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `t:(real^3->bool)->bool` STRIP_ASSUME_TAC) THEN
  ABBREV_TAC `tk = {s:real^3->bool | s IN t /\ s SUBSET k'}` THEN
  MP_TAC(ISPECL [`La:(real^3->bool)->bool`; `fk:(real^3->bool)->bool`;
                 `tk:(real^3->bool)->bool`; `c:real`] MOI_S5C_TP_EXTEND) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [EXPAND_TAC "tk" THEN MATCH_MP_TAC MOI_S5C_SUBCOMPLEX_SUBSET THEN
      FIRST_ASSUM ACCEPT_TAC;
      EXPAND_TAC "La" THEN REWRITE_TAC[IN_ELIM_THM] THEN ASM_MESON_TAC[];
      X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN
      SUBGOAL_THEN `(x:real^3)$3 = c'` (fun th -> ASM_REWRITE_TAC[th]) THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `l':(real^3->bool)->bool` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `l' UNION t:(real^3->bool)->bool` THEN
  SUBGOAL_THEN `simplicial_complex (l' UNION t:(real^3->bool)->bool)` ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_TP_MERGE THEN
    MAP_EVERY EXISTS_TAC [`k':real^3->bool`; `a:real^3->bool`; `N:real^3->bool`;
                          `c':real`] THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [X_GEN_TAC `s:real^3->bool` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `s:real^3->bool` o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `La:(real^3->bool)->bool`)) (concl th) &&
        is_exists(snd(dest_imp(snd(dest_forall(concl th))))))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:real^3->bool` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(u:real^3->bool) IN L0` ASSUME_TAC THENL
       [UNDISCH_TAC `(u:real^3->bool) IN La` THEN EXPAND_TAC "La" THEN
        SIMP_TAC[IN_ELIM_THM];
        ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o C MATCH_MP (ASSUME `(u:real^3->bool) IN L0`) o check (fun th ->
        is_forall(concl th) && can (find_term ((=) `L0:(real^3->bool)->bool`)) (concl th) &&
        can (find_term ((=) `c':real`)) (concl th) &&
        is_disj(snd(dest_imp(snd(dest_forall(concl th))))))) THEN
      UNDISCH_TAC `(s:real^3->bool) SUBSET u` THEN REWRITE_TAC[SUBSET] THEN MESON_TAC[];
      X_GEN_TAC `s:real^3->bool` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(s:real^3->bool) IN tk` MP_TAC THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      EXPAND_TAC "tk" THEN SIMP_TAC[IN_ELIM_THM];
      X_GEN_TAC `s:real^3->bool` THEN STRIP_TAC THEN
      MATCH_MP_TAC MOI_S5C_LEV_CLOPEN THEN
      MAP_EVERY EXISTS_TAC [`E:real^3->bool`; `a:real^3->bool`; `c':real`] THEN
      ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `(s:real^3->bool) SUBSET {x | x IN a /\ x$3 = c'}` THEN SET_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[UNIONS_UNION] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[simplicial_complex]; ALL_TAC] THEN
  X_GEN_TAC `v:real^3` THEN REWRITE_TAC[IN_UNION] THEN STRIP_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:real^3)$3 = c'` (fun th -> ASM_REWRITE_TAC[th]) THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN
  UNDISCH_TAC `UNIONS t:real^3->bool = N` THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  REWRITE_TAC[IN_UNIONS] THEN EXISTS_TAC `{v:real^3}` THEN ASM_REWRITE_TAC[IN_SING]);;

(* ------------------------------------------------------------------------- *)
(* The model output for the minimal middle up region: the sets.             *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_MINTRO_TAC : tactic =
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))))));;

(* The decomposition facts, with the equation for B reversed.              *)

let MOI_S5C_MDECOMP_TAC : tactic =
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `s:real`] MOI_S5C_MUP_DECOMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  FIRST_X_ASSUM(ASSUME_TAC o SYM o check (fun th ->
    is_eq(concl th) && lhs(concl th) = `B:real^3->bool`));;

(* The two sections of J1, J2 are those of Ja, Jb.                          *)

let MOI_S5C_M_S12 = prove
 (`!B K FF GG Q c d0 Ja Jb J1 J2 s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\ moi_s5c_btw B c Ja Jb = {} /\ (J1 = Ja /\ J2 = Jb \/ J1 = Jb /\ J2 = Ja) /\ IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J2) /\ &0 < s /\ s < &1
     ==> (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)) = (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)) /\
         {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s} UNION {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s} = {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s} UNION {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s} /\
         IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s)) SUBSET inside (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) /\
         pl_sphere 1 (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) /\ pl_sphere 1 (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) /\
         (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s)) = IMAGE (moi_s35_lift (c - s * d0)) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) /\
         (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)) = IMAGE (moi_s35_lift (c - s * d0)) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))`,
  MOI_S5C_MINTRO_TAC THEN
  SUBGOAL_THEN `J1 IN components {x:real^3 | x IN B /\ x$3 = c} /\
                J2 IN components {x:real^3 | x IN B /\ x$3 = c} /\ ~(J1 = J2)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
      `Jb:real^3->bool`] MOI_S5C_MUP_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o CONJUNCT1)] THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mup] o
      check (MOI_S5C_HEAD "moi_s5c_mup")) THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN (CONJUNCTS_THEN SUBST1_TAC) o check (fun th ->
      is_disj(concl th) && can (find_term ((=) `J1:real^3->bool`)) (concl th))) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `abs(-- &1 * s) <= &1 /\ c + (-- &1 * s) * d0 = c - s * d0`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`&0 < s`; `s < &1`] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MAP_EVERY (fun t ->
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; t; `-- &1 * s`]
      MOI_S5C_SEC_BASIC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC])
    [`J1:real^3->bool`; `J2:real^3->bool`] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J1:real^3->bool`;
    `J2:real^3->bool`; `-- &1 * s`] MOI_S5C_SEC_PLANE_NEST) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `moi_s35_lift (c - s * d0) = moi_s35_lift (c + (-- &1 * s) * d0)`
  SUBST1_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  FIRST_X_ASSUM(DISJ_CASES_THEN (CONJUNCTS_THEN SUBST1_TAC) o check (fun th ->
    is_disj(concl th) && can (find_term ((=) `J1:real^3->bool`)) (concl th))) THEN
  SET_TAC[]);;

(* The set algebra of the output: B INTER B' = B_in UNION B_out, the       *)
(* intersections along kk0, compactness and the punctured pieces.           *)

let MOI_S5C_M_SETS = prove
 (`!B K FF GG Q c d0 Ja Jb J1 J2 s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\ moi_s5c_btw B c Ja Jb = {} /\ (J1 = Ja /\ J2 = Jb \/ J1 = Jb /\ J2 = Ja) /\ IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J2) /\ &0 < s /\ s < &1
     ==> B INTER ((IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))) = (IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))) /\
         ((IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) = B /\
