     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\ moi_s5c_btw B c Ja Jb = {} /\ (J1 = Ja /\ J2 = Jb \/ J1 = Jb /\ J2 = Ja) /\ IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J2) /\ &0 < s /\ s < &1
     ==> moi_s5c_arch c (s * d0) (IMAGE moi_s5c_proj J1) (IMAGE moi_s5c_proj J2)
           (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb))) {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s} {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}`,
  MOI_S5C_MINTRO_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `s:real`] MOI_S5C_MUP_ARCH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(DISJ_CASES_THEN (CONJUNCTS_THEN SUBST_ALL_TAC) o check (fun th ->
    is_disj(concl th) && can (find_term ((=) `J1:real^3->bool`)) (concl th))) THEN
  ASM_SIMP_TAC[]);;

(* B' is an annulus with the ends of B.                                     *)

let MOI_S5C_M_ANN = prove
 (`!B K FF GG Q c d0 Ja Jb J1 J2 s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\ moi_s5c_btw B c Ja Jb = {} /\ (J1 = Ja /\ J2 = Jb \/ J1 = Jb /\ J2 = Ja) /\ IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J2) /\ &0 < s /\ s < &1
     ==> pl_annulus_with_ends ((IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))) (IMAGE (FF:real^2->real^3) (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))) (IMAGE (FF:real^2->real^3) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))`,
  MOI_S5C_MINTRO_TAC THEN MOI_S5C_MDECOMP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `J1:real^3->bool`; `J2:real^3->bool`; `s:real`] MOI_S5C_M_SETS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `J1:real^3->bool`; `J2:real^3->bool`; `s:real`] MOI_S5C_M_S12) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  SUBGOAL_THEN `pl_annulus_with_ends (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))`; `IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))`]
      MOI_S5C_RG_FACTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o MATCH_MP (SPEC `c - s * d0` MOI_S5C_LIFT_ANN) o CONJUNCT1) THEN
    REWRITE_TAC[GSYM moi_s5c_npl] THEN
    UNDISCH_TAC `(moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s)) = IMAGE (moi_s35_lift (c - s * d0)) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s)))` THEN
    DISCH_THEN(fun th -> GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [SYM th]) THEN
    UNDISCH_TAC `(moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)) = IMAGE (moi_s35_lift (c - s * d0)) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))` THEN
    DISCH_THEN(fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [SYM th]) THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN (CONJUNCTS_THEN SUBST1_TAC) o check (fun th ->
      is_disj(concl th) && can (find_term ((=) `J1:real^3->bool`)) (concl th))) THEN
    REWRITE_TAC[] THEN MESON_TAC[MOI_S5C_ANN_SWAP];
    ALL_TAC] THEN
  REPEAT(FIRST_X_ASSUM(K ALL_TAC o check (fun th -> is_eq(concl th) &&
    (lhs(concl th) = `(moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))` || lhs(concl th) = `(moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))`)))) THEN
  SUBGOAL_THEN `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) INTER (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) = (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) /\ ((IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))))) INTER (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))) = (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`(IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))) = B`; `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) INTER (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) = (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))`;
      `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) INTER (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))) = (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))`; `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) INTER (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))) = {}`;
      `(moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) INTER B = ((moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))`] THEN
    MOI_S5C_ABS_SET_TAC [`(IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))))`; `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))))`; `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))`; `(moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))))`; `(moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))`; `(moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))`];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`(IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))))`; `IMAGE (FF:real^2->real^3) (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))`; `(moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))`; `(moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))))`; `(moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))`] MOI_S5C_ANN_GLUE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_TAC] THEN
  MP_TAC(ISPECL [`(IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))))`; `IMAGE (FF:real^2->real^3) (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))`; `(moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))`; `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))`; `IMAGE (FF:real^2->real^3) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`]
    MOI_S5C_ANN_GLUE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; REWRITE_TAC[UNION_ASSOC]]);;

(* The tubes.                                                                *)

let MOI_S5C_M_TUBE = prove
 (`!B K FF GG Q c d0 Ja Jb J1 J2 s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\ moi_s5c_btw B c Ja Jb = {} /\ (J1 = Ja /\ J2 = Jb \/ J1 = Jb /\ J2 = Ja) /\ IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J2) /\ &0 < s /\ s < &1
     ==> ((IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))) SUBSET interior moi_s35_stube /\ (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) SUBSET moi_s35_ttube /\
         (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) SUBSET moi_s5c_otube`,
  MOI_S5C_MINTRO_TAC THEN MOI_S5C_MDECOMP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `J1:real^3->bool`; `J2:real^3->bool`; `s:real`] MOI_S5C_M_ARCH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `J1:real^3->bool`; `J2:real^3->bool`; `s:real`] MOI_S5C_M_S12) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> ASSUME_TAC(el 1 (CONJUNCTS th))) THEN
  SUBGOAL_THEN `(moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) SUBSET moi_s5c_otube` ASSUME_TAC THENL
   [REWRITE_TAC[SUBSET; moi_s5c_npl; MOI_S5C_IN_LIFT; moi_s5c_otube; IN_ELIM_THM;
                moi_s5c_rg; IN_DIFF; IN_UNION] THEN
    X_GEN_TAC `x:real^3` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
    REWRITE_TAC[GSYM(el 2 (CONJUNCTS MOI_S5C_PROJ_FACTS))] THEN
    REPEAT CONJ_TAC THENL
     [ONCE_REWRITE_TAC[GSYM REAL_NOT_LE] THEN DISCH_TAC THEN
      UNDISCH_TAC `~(moi_s5c_proj x IN inside (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))))` THEN
      REWRITE_TAC[] THEN
      FIRST_ASSUM(MATCH_MP_TAC o MOI_S5C_ARCH_CONJ 10 o check (MOI_S5C_HEAD "moi_s5c_arch")) THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN `moi_s5c_proj x IN {y:real^2 | max (abs(y$1)) (abs(y$2)) < &5 / &16}`
      MP_TAC THENL [ALL_TAC; REWRITE_TAC[IN_ELIM_THM]] THEN
      FIRST_X_ASSUM(DISJ_CASES_TAC o check (is_disj o concl)) THENL
       [FIRST_ASSUM(MP_TAC o MOI_S5C_ARCH_CONJ 12 o check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
        UNDISCH_TAC `moi_s5c_proj x IN IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))` THEN SET_TAC[];
        SUBGOAL_THEN `inside (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))) SUBSET
                      {y:real^2 | max (abs(y$1)) (abs(y$2)) < &5 / &16}` MP_TAC THENL
         [MATCH_MP_TAC INSIDE_SUBSET_CONVEX THEN REWRITE_TAC[MOI_S5C_SQ_CONVEX_LT] THEN
          FIRST_ASSUM(ACCEPT_TAC o MOI_S5C_ARCH_CONJ 12 o check (MOI_S5C_HEAD "moi_s5c_arch"));
          UNDISCH_TAC `moi_s5c_proj x IN inside (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))` THEN
          SET_TAC[]]];
      FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mset] o
        check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
      FIRST_ASSUM(MP_TAC o MOI_S5C_ARCH_CONJ 0 o check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
      FIRST_ASSUM(MP_TAC o MOI_S5C_ARCH_CONJ 2 o check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
      MAP_EVERY UNDISCH_TAC [`abs c <= &1 / &512`; `(x:real^3)$3 = c - s * d0`] THEN
      REAL_ARITH_TAC];
    ALL_TAC] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mset] o
    check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[UNION_SUBSET] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `B:real^3->bool` THEN
      ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))) = B` THEN SET_TAC[];
      MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `moi_s5c_otube` THEN
