      EXISTS_TAC `moi_s35_ttube` THEN REWRITE_TAC[MOI_S5C_OTUBE; MOI_S5C_TUBES];
      MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `B:real^3->bool` THEN
      ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))) = B` THEN SET_TAC[]];
    FIRST_ASSUM(MP_TAC o MOI_S5C_ARCH_CONJ 14 o check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
    FIRST_ASSUM(MP_TAC o MOI_S5C_ARCH_CONJ 19 o check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
    FIRST_ASSUM(MP_TAC o MOI_S5C_ARCH_CONJ 20 o check (MOI_S5C_HEAD "moi_s5c_arch")) THEN
    MP_TAC MOI_S5C_OTUBE THEN
    UNDISCH_TAC `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s} UNION {(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s} = {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s} UNION {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s}` THEN
    UNDISCH_TAC `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) = {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s} UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb))) UNION {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s}` THEN
    MOI_S5C_ABS_SET_TAC [`(IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))))`; `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s}`; `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s}`; `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s}`; `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}`; `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb)))`;
                         `moi_s5c_otube`; `moi_s35_ttube`];
    FIRST_ASSUM ACCEPT_TAC]);;

(* Flatness of N' off kk0: a ball around each point meets N' exactly in its *)
(* level, misses B and lies in the open tube.                               *)

let MOI_S5C_M_FLAT = prove
 (`!B K FF GG Q c d0 Ja Jb J1 J2 s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\ moi_s5c_btw B c Ja Jb = {} /\ (J1 = Ja /\ J2 = Jb \/ J1 = Jb /\ J2 = Ja) /\ IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J2) /\ &0 < s /\ s < &1
     ==> !z. z IN (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) DIFF ((moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))
             ==> ?r. &0 < r /\ ball(z,r) SUBSET moi_s5c_otube /\ ball(z,r) INTER B = {} /\
                     !x. x IN ball(z,r) ==> (x IN (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) <=> x$3 = z$3)`,
  MOI_S5C_MINTRO_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `J1:real^3->bool`; `J2:real^3->bool`; `s:real`] MOI_S5C_M_SETS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `J1:real^3->bool`; `J2:real^3->bool`; `s:real`] MOI_S5C_M_TUBE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `J1:real^3->bool`; `J2:real^3->bool`; `s:real`] MOI_S5C_M_ARCH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  X_GEN_TAC `z:real^3` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`c:real`; `s * d0`; `IMAGE moi_s5c_proj (J1:real^3->bool)`;
    `IMAGE moi_s5c_proj (J2:real^3->bool)`; `IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))`;
    `IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))`; `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Ja) (IMAGE GG Jb)))`; `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN J1 /\ &0 <= u /\ u <= s}`; `{(Q:real^3->real->real^3) x (-- &1 * u) | x IN J2 /\ &0 <= u /\ u <= s}`; `z:real^3`]
    MOI_S5C_ARCH_N_HALVES) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    UNDISCH_TAC `(z:real^3) IN (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) DIFF ((moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))` THEN ASM_REWRITE_TAC[moi_s5c_rgo];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r1:real` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (K ALL_TAC)))) THEN
  SUBGOAL_THEN `~((z:real^3) IN B) /\ (z:real^3) IN moi_s5c_otube` STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`(z:real^3) IN (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) DIFF ((moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))`; `(moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) INTER B = ((moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))`;
      `(moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) SUBSET moi_s5c_otube`] THEN
    MOI_S5C_ABS_SET_TAC [`(moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s))))`; `((moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))`; `moi_s5c_otube`];
    ALL_TAC] THEN
  SUBGOAL_THEN `?r2. &0 < r2 /\ ball(z:real^3,r2) INTER B = {}` STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `open ((:real^3) DIFF B)` MP_TAC THENL
     [REWRITE_TAC[GSYM closed] THEN MATCH_MP_TAC COMPACT_IMP_CLOSED THEN
