      ALL_TAC] THEN
    REWRITE_TAC[OPEN_CONTAINS_BALL] THEN DISCH_THEN(MP_TAC o SPEC `z:real^3`) THEN
    ASM_REWRITE_TAC[IN_DIFF; IN_UNIV] THEN MATCH_MP_TAC MONO_EXISTS THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?r3. &0 < r3 /\ ball(z:real^3,r3) SUBSET moi_s5c_otube`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(CONJUNCT1 MOI_S5C_OTUBE) THEN REWRITE_TAC[OPEN_CONTAINS_BALL] THEN
    DISCH_THEN(MP_TAC o SPEC `z:real^3`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `min r1 (min r2 r3)` THEN
  SUBGOAL_THEN `ball(z:real^3,min r1 (min r2 r3)) SUBSET ball(z,r1) /\
                ball(z:real^3,min r1 (min r2 r3)) SUBSET ball(z,r2) /\
                ball(z:real^3,min r1 (min r2 r3)) SUBSET ball(z,r3)`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC SUBSET_BALL THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`&0 < r1`; `&0 < r2`; `&0 < r3`] THEN REAL_ARITH_TAC;
    MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `ball(z:real^3,r3)` THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(SET_RULE
     `!s t u:real^3->bool. s SUBSET t /\ t INTER u = {} ==> s INTER u = {}`) THEN
    EXISTS_TAC `ball(z:real^3,r2)` THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real^3` THEN DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    MATCH_MP_TAC(REWRITE_RULE[SUBSET]
      (ASSUME `ball(z:real^3,min r1 (min r2 r3)) SUBSET ball(z,r1)`)) THEN
    FIRST_ASSUM ACCEPT_TAC]);;

