let MOI_S5C_LIFT_POLYHEDRON = prove
 (`!h (S:real^2->bool). pl_polyhedron S ==> pl_polyhedron (IMAGE (moi_s35_lift h) S)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC PL_POLYHEDRON_PL_IMAGE THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `h:real` MOI_S5C_LIFT_LINEAR) THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC PL_MAP_ON_AFFINE THEN ASM_SIMP_TAC[LOCALLY_POLYHEDRAL_PL_POLYHEDRON]);;

let MOI_S5C_ANN_POLYHEDRON = prove
 (`!(a:real^N->bool) j0 j1. pl_annulus_with_ends a j0 j1 ==> pl_polyhedron a`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pl_annulus_with_ends; pl_homeomorphism; homeomorphism] THEN
  STRIP_TAC THEN
  FIRST_X_ASSUM(SUBST1_TAC o SYM o check (fun th ->
    is_eq(concl th) && rhs(concl th) = `a:real^N->bool`)) THEN
  MATCH_MP_TAC PL_POLYHEDRON_PL_IMAGE THEN ASM_REWRITE_TAC[MOI_S5C_SQANN_POLYHEDRON]);;

(* kk0 is relatively open in the level set of B at c - s d0.               *)

let MOI_S5C_M_KKOPEN = prove
 (`!B K FF GG Q c d0 Ja Jb J1 J2 s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\ moi_s5c_btw B c Ja Jb = {} /\ (J1 = Ja /\ J2 = Jb \/ J1 = Jb /\ J2 = Ja) /\ IMAGE moi_s5c_proj J1 SUBSET inside (IMAGE moi_s5c_proj J2) /\ &0 < s /\ s < &1
     ==> open_in (subtopology euclidean {x | x IN B /\ x$3 = c - s * d0}) ((moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)) UNION (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))`,
  MOI_S5C_MINTRO_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mup] o
    check (MOI_S5C_HEAD "moi_s5c_mup")) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
    `Jb:real^3->bool`] MOI_S5C_MUP_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o CONJUNCT1)] THEN
  SUBGOAL_THEN `abs(-- &1 * s) <= &1 /\ c + (-- &1 * s) * d0 = c - s * d0`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`&0 < s`; `s < &1`] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mset] o
    check (MOI_S5C_HEAD "moi_s5c_mset")) THEN
  SUBGOAL_THEN
   `!J. J IN components {x:real^3 | x IN B /\ x$3 = c}
        ==> moi_s5c_sec (Q:real^3->real->real^3) J (-- &1 * s) SUBSET B /\
            (!z. z IN moi_s5c_sec Q J (-- &1 * s) ==> z$3 = c - s * d0) /\
            compact (moi_s5c_sec Q J (-- &1 * s))`
  (LABEL_TAC "secs") THENL
   [X_GEN_TAC `J:real^3->bool` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
      `-- &1 * s`] MOI_S5C_SEC_BASIC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MAP_EVERY (fun k -> ASSUME_TAC(el k (CONJUNCTS th))) [0;1;3]) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
   `O0 = UNIONS {moi_s5c_sec (Q:real^3->real->real^3) J (-- &1 * s) | J |
