                 ~(J = Ja) /\ ~(J = Jb)}` THEN
  SUBGOAL_THEN `closed (O0:real^3->bool)` ASSUME_TAC THENL
   [EXPAND_TAC "O0" THEN MATCH_MP_TAC CLOSED_UNIONS THEN CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_SUBSET THEN
      EXISTS_TAC `IMAGE (\J. moi_s5c_sec (Q:real^3->real->real^3) J (-- &1 * s))
                        (components {x:real^3 | x IN B /\ x$3 = c})` THEN
      CONJ_TAC THENL [MATCH_MP_TAC FINITE_IMAGE THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_IMAGE] THEN MESON_TAC[];
      REWRITE_TAC[FORALL_IN_GSPEC] THEN REPEAT STRIP_TAC THEN
      MATCH_MP_TAC COMPACT_IMP_CLOSED THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[OPEN_IN_OPEN] THEN EXISTS_TAC `(:real^3) DIFF O0` THEN
  CONJ_TAC THENL [REWRITE_TAC[GSYM closed] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_INTER; IN_DIFF; IN_UNIV; IN_ELIM_THM; IN_UNION] THEN
  X_GEN_TAC `z:real^3` THEN EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `?Jz. Jz IN components {x:real^3 | x IN B /\ x$3 = c} /\
                       (Jz = Ja \/ Jz = Jb) /\
                       z IN moi_s5c_sec (Q:real^3->real->real^3) Jz (-- &1 * s)`
    (X_CHOOSE_THEN `Jz:real^3->bool` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))) THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "secs" (MP_TAC o SPEC `Jz:real^3->bool`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      UNDISCH_TAC `z IN moi_s5c_sec (Q:real^3->real->real^3) Jz (-- &1 * s)` THEN
      SET_TAC[];
      USE_THEN "secs" (MP_TAC o SPEC `Jz:real^3->bool`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(MATCH_MP_TAC o CONJUNCT1 o CONJUNCT2) THEN FIRST_ASSUM ACCEPT_TAC;
      EXPAND_TAC "O0" THEN REWRITE_TAC[IN_UNIONS; IN_ELIM_THM] THEN
      DISCH_THEN(X_CHOOSE_THEN `t:real^3->bool` (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `J:real^3->bool` STRIP_ASSUME_TAC) ASSUME_TAC)) THEN
      MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
        `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
        `Jz:real^3->bool`; `J:real^3->bool`; `-- &1 * s`; `-- &1 * s`] MOI_S5C_SEC_DISJ) THEN
      ANTS_TAC THENL
