      SUBGOAL_THEN `(Ja:real^3->bool) SUBSET (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) /\ (Jb:real^3->bool) SUBSET (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))))`
      STRIP_ASSUME_TAC THENL
       [UNDISCH_TAC `{x | x IN (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) /\ x$3 = c} = Ja UNION Jb` THEN SET_TAC[];
        ALL_TAC] THEN
      MAP_EVERY UNDISCH_TAC [`(Ja:real^3->bool) SUBSET (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))))`;
                             `(Jb:real^3->bool) SUBSET (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))))`; `(x:real^3) IN J`] THEN
      SET_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `J:real^3->bool` STRIP_ASSUME_TAC) THEN
      FIRST_X_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[DE_MORGAN_THM] o check (fun th ->
        is_neg(concl th) && is_disj(dest_neg(concl th)))) THEN
      SUBGOAL_THEN `(x:real^3) IN B /\ x$3 = c` STRIP_ASSUME_TAC THENL
       [UNDISCH_TAC `UNIONS CC = {x:real^3 | x IN B /\ x$3 = c}` THEN
        UNDISCH_TAC `(x:real^3) IN J` THEN UNDISCH_TAC `(J:real^3->bool) IN CC` THEN
        SET_TAC[];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `~((x:real^3) IN Ja) /\ ~((x:real^3) IN Jb)` STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN DISCH_TAC THENL
         [FIRST_X_ASSUM(MP_TAC o SPECL [`J:real^3->bool`; `Ja:real^3->bool`] o check
            (fun th -> is_forall(concl th) && can (find_term ((=) `CC:(real^3->bool)->bool`)) (concl th))) THEN
          ASM_REWRITE_TAC[] THEN
          MAP_EVERY UNDISCH_TAC [`(x:real^3) IN J`; `(x:real^3) IN Ja`] THEN SET_TAC[];
          FIRST_X_ASSUM(MP_TAC o SPECL [`J:real^3->bool`; `Jb:real^3->bool`] o check
            (fun th -> is_forall(concl th) && can (find_term ((=) `CC:(real^3->bool)->bool`)) (concl th))) THEN
          ASM_REWRITE_TAC[] THEN
          MAP_EVERY UNDISCH_TAC [`(x:real^3) IN J`; `(x:real^3) IN Jb`] THEN SET_TAC[]];
        ALL_TAC] THEN
      UNDISCH_TAC `{x | x IN (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) /\ x$3 = c} = Ja UNION Jb` THEN
      UNDISCH_TAC `B INTER ((IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))) = (IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))` THEN
      UNDISCH_TAC `((IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))))) = B` THEN
      MAP_EVERY UNDISCH_TAC [`(x:real^3) IN B`; `(x:real^3)$3 = c`;
                             `~((x:real^3) IN Ja)`; `~((x:real^3) IN Jb)`] THEN
      MOI_S5C_ABS_SET_TAC [`((IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]])))))`; `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))))`; `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))`; `(IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s)))))`]];
    ALL_TAC] THEN
  SUBGOAL_THEN `components {x | x IN ((IMAGE (FF:real^2->real^3) (moi_s5c_rg (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) UNION (moi_s5c_npl (c - s * d0) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J1 (-- &1 * s))) (IMAGE moi_s5c_proj (moi_s5c_sec (Q:real^3->real->real^3) J2 (-- &1 * s)))) UNION (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))))) /\ x$3 = c} = CC DIFF {Ja, Jb:real^3->bool}`
  ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOI_S5C_COMPONENTS_SUBUNION THEN
    EXISTS_TAC `{x:real^3 | x IN B /\ x$3 = c}` THEN ASM_REWRITE_TAC[] THEN SET_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC CARD_PSUBSET THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[PSUBSET; EXTENSION] THEN CONJ_TAC THENL [SET_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `Ja:real^3->bool`) THEN
  ASM_REWRITE_TAC[IN_DIFF; IN_INSERT]);;

(* ------------------------------------------------------------------------- *)
(* The model output, part 4: the two clauses of B'.                         *)
(* ------------------------------------------------------------------------- *)

(* A circle P in the open region between X and Y whose inside meets that   *)
(* of X separates X from Y.                                                 *)

let MOI_S5C_IN_RGO_NEST = prove
 (`!X Y P:real^2->bool.
     pl_sphere 1 X /\ pl_sphere 1 Y /\ pl_sphere 1 P /\ X SUBSET inside Y /\
     P SUBSET moi_s5c_rgo X Y /\ ~(inside X INTER inside P = {})
     ==> X SUBSET inside P /\ P SUBSET inside Y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RG_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MAP_EVERY (fun k -> ASSUME_TAC(el k (CONJUNCTS th))) [8;9;10]) THEN
  CONJ_TAC THENL
   [ALL_TAC;
    MAP_EVERY UNDISCH_TAC [`P SUBSET moi_s5c_rgo X Y`; `moi_s5c_rgo X Y SUBSET inside Y`] THEN
    SET_TAC[]] THEN
  SUBGOAL_THEN `(X:real^2->bool) homeomorphic sphere(vec 0:real^2,&1) /\
                (P:real^2->bool) homeomorphic sphere(vec 0:real^2,&1)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_PL_SPHERE_HOMEO THEN EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `P:real^2->bool`] MOI_S5C_JORDAN_NEST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MAP_EVERY UNDISCH_TAC [`P SUBSET moi_s5c_rgo X Y`;
                           `DISJOINT (moi_s5c_rgo X Y) (X UNION Y)`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPEC `X:real^2->bool` INSIDE_INTER_OUTSIDE) THEN
  SUBGOAL_THEN `~(P:real^2->bool = {})` MP_TAC THENL
   [ASM_MESON_TAC[MOI_SCD_PL_SPHERE_NONEMPTY]; ALL_TAC] THEN
  MAP_EVERY UNDISCH_TAC [`P SUBSET moi_s5c_rgo X Y`; `moi_s5c_rgo X Y SUBSET outside X`;
                         `(P:real^2->bool) SUBSET inside X`] THEN
  SET_TAC[]);;

(* The origin lies inside every extended circle.                            *)

let MOI_S5C_EXT_ORIGIN = prove
 (`!B K FF GG Q c d0 W.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_ext B (GG:real^3->real^2) c W
     ==> vec 0 IN inside W`,
  REPEAT GEN_TAC THEN REWRITE_TAC[moi_s5c_ext] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
  STRIP_TAC THENL
   [MP_TAC(SPEC `&1` MOI_S5C_SQ_JORDAN) THEN REWRITE_TAC[REAL_OF_NUM_LT; ARITH] THEN
    DISCH_THEN(MP_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[MOI_S5C_IN_SQO; VEC_COMPONENT] THEN REAL_ARITH_TAC;
    MP_TAC(SPEC `&2` MOI_S5C_SQ_JORDAN) THEN REWRITE_TAC[REAL_OF_NUM_LT; ARITH] THEN
    DISCH_THEN(MP_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[MOI_S5C_IN_SQO; VEC_COMPONENT] THEN REAL_ARITH_TAC;
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
      `&0`] MOI_S5C_SEC_SQ_ESS) THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `J:real^3->bool`;
      `&0`] MOI_S5C_SEC_BASIC) THEN
    ASM_REWRITE_TAC[REAL_ABS_NUM; REAL_POS] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[last(CONJUNCTS th)]) THEN
    MATCH_MP_TAC(SET_RULE `!x s t:real^2->bool. x IN s ==> s SUBSET t ==> x IN t`) THEN
    REWRITE_TAC[MOI_S5C_IN_SQI; VEC_COMPONENT] THEN REAL_ARITH_TAC]);;

(* The down neighbour of Ja: the region D_A = FF(rg W GJa) on the other    *)
(* side of Ja contains the strip of Ja, and D_A minus the open strip is the *)
(* connected FF(rg W Pa).                                                   *)

let MOI_S5C_NB_LEFT = prove
 (`!B K FF GG Q c d0 Ja Jb s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     &0 < s /\ s < &1
     ==> ?W. moi_s5c_cons B GG c W (IMAGE (GG:real^3->real^2) Ja) /\
             moi_s5c_sd FF c (-- &1) W (IMAGE (GG:real^3->real^2) Ja) /\
             {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s} SUBSET IMAGE (FF:real^2->real^3) (moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja)) /\
             IMAGE (FF:real^2->real^3) (moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja)) DIFF ({(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s} DIFF (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) =
               IMAGE (FF:real^2->real^3) (moi_s5c_rg W (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))) /\
             connected (IMAGE (FF:real^2->real^3) (moi_s5c_rg W (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `s:real`] MOI_S5C_MUP_A0) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mup] o
    check (MOI_S5C_HEAD "moi_s5c_mup")) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_EXT_ORDER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(LABEL_TAC "eo" o CONJUNCT1)] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_CONS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `(IMAGE (GG:real^3->real^2) Ja)` o CONJUNCT2) THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[moi_s5c_ext] THEN DISJ2_TAC THEN DISJ2_TAC THEN
      EXISTS_TAC `Ja:real^3->bool` THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN
      MP_TAC(ISPEC `(IMAGE (GG:real^3->real^2) Ja)` INSIDE_NO_OVERLAP) THEN
      MP_TAC(SPEC `&1` MOI_S5C_SQ_JORDAN) THEN REWRITE_TAC[REAL_OF_NUM_LT; ARITH] THEN
      DISCH_THEN(ASSUME_TAC o CONJUNCT1) THEN
      SUBGOAL_THEN `(relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) SUBSET interval[--vector[&1;&1],vector[&1;&1]] /\ ~((relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]])) = {})`
      MP_TAC THENL
       [CONJ_TAC THENL
         [SIMP_TAC[RELATIVE_FRONTIER_SUBSET; CLOSED_INTERVAL];
          ASM_MESON_TAC[MOI_SCD_PL_SPHERE_NONEMPTY]];
        ALL_TAC] THEN
      UNDISCH_TAC `interval[--vector[&1;&1],vector[&1;&1]] SUBSET inside (IMAGE (GG:real^3->real^2) Ja)` THEN
      ASM_REWRITE_TAC[] THEN SET_TAC[]];
    DISCH_THEN(X_CHOOSE_TAC `W:real^2->bool`)] THEN
  EXISTS_TAC `W:real^2->bool` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `W:real^2->bool`;
    `(IMAGE (GG:real^3->real^2) Ja)`] MOI_S5C_CONS_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MAP_EVERY (fun k -> ASSUME_TAC(el k (CONJUNCTS th))) [0;2;3]) THEN
  SUBGOAL_THEN `W SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1])) /\ (IMAGE (GG:real^3->real^2) Ja) SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1])) /\ moi_s5c_ext B (GG:real^3->real^2) c W`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `moi_s5c_cons B (GG:real^3->real^2) c W (IMAGE (GG:real^3->real^2) Ja)` THEN
    REWRITE_TAC[moi_s5c_cons] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THEN USE_THEN "eo" (fun th -> ASM_MESON_TAC[th]);
    ALL_TAC] THEN
  MP_TAC(ISPECL [`W:real^2->bool`; `(IMAGE (GG:real^3->real^2) Ja)`] MOI_S5C_RG_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o el 6 o CONJUNCTS) THEN DISCH_TAC THEN
  SUBGOAL_THEN `moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja) SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1])) /\
                moi_s5c_rgo W (IMAGE (GG:real^3->real^2) Ja) SUBSET moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja) /\
                (IMAGE (GG:real^3->real^2) Ja) SUBSET moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja)` STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja) = moi_s5c_rgo W (IMAGE (GG:real^3->real^2) Ja) UNION W UNION (IMAGE (GG:real^3->real^2) Ja)`;
      `moi_s5c_rgo W (IMAGE (GG:real^3->real^2) Ja) SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1]))`; `W SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1]))`; `(IMAGE (GG:real^3->real^2) Ja) SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1]))`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  (* the side of W GJa *)
  SUBGOAL_THEN `~(moi_s5c_sd (FF:real^2->real^3) c (-- &1) (IMAGE (GG:real^3->real^2) Ja) (IMAGE (GG:real^3->real^2) Jb))` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(IMAGE (GG:real^3->real^2) Ja)`; `(IMAGE (GG:real^3->real^2) Jb)`] MOI_S5C_RG_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o el 3 o CONJUNCTS) THEN
