     (?k0. k0 IN components X /\
           !k. k IN components X /\ ~(k = k0) ==> k SUBSET moi_s35_ttube) /\
     X' SUBSET X UNION T0 /\ T0 SUBSET moi_s35_ttube /\ ~(X' = {}) /\
     (!k. k IN components X ==> connected (k INTER X'))
     ==> moi_s5c_clause X'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `k0:real^3->bool` STRIP_ASSUME_TAC)
    STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[moi_s5c_clause] THEN
  SUBGOAL_THEN `X DIFF k0 SUBSET moi_s35_ttube` ASSUME_TAC THENL
   [REWRITE_TAC[SUBSET; IN_DIFF] THEN X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?k. k IN components X /\ (x:real^3) IN k` STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPEC `X:real^3->bool` UNIONS_COMPONENTS) THEN
      UNDISCH_TAC `(x:real^3) IN X` THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~(k:real^3->bool = k0)` ASSUME_TAC THENL
     [DISCH_TAC THEN UNDISCH_TAC `~((x:real^3) IN k0)` THEN
      UNDISCH_TAC `(x:real^3) IN k` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(k:real^3->bool) SUBSET moi_s35_ttube` MP_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      UNDISCH_TAC `(x:real^3) IN k` THEN SET_TAC[]];
    ALL_TAC] THEN
  ASM_CASES_TAC `k0 INTER X':real^3->bool = {}` THENL
   [SUBGOAL_THEN `(X':real^3->bool) SUBSET moi_s35_ttube` ASSUME_TAC THENL
     [MAP_EVERY UNDISCH_TAC
       [`k0 INTER X':real^3->bool = {}`; `X' SUBSET X UNION T0:real^3->bool`;
        `T0 SUBSET moi_s35_ttube`; `X DIFF k0 SUBSET moi_s35_ttube`] THEN SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPEC `X':real^3->bool` COMPONENTS_EQ_EMPTY) THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN MATCH_MP_TAC MONO_EXISTS THEN
    X_GEN_TAC `k1:real^3->bool` THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `k:real^3->bool` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`X':real^3->bool`; `k:real^3->bool`] IN_COMPONENTS_SUBSET) THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `(X':real^3->bool) SUBSET moi_s35_ttube` THEN
    SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`X':real^3->bool`; `k0 INTER X':real^3->bool`]
    EXISTS_COMPONENT_SUPERSET) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[] THEN SET_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `k1:real^3->bool` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `k:real^3->bool` THEN STRIP_TAC THEN
  SUBGOAL_THEN `k INTER k1:real^3->bool = {}` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`X':real^3->bool`; `k:real^3->bool`; `k1:real^3->bool`]
      COMPONENTS_NONOVERLAP) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`X':real^3->bool`; `k:real^3->bool`] IN_COMPONENTS_SUBSET) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY UNDISCH_TAC
   [`k INTER k1:real^3->bool = {}`; `k0 INTER X' SUBSET (k1:real^3->bool)`;
    `X' SUBSET X UNION T0:real^3->bool`; `T0 SUBSET moi_s35_ttube`;
    `X DIFF k0 SUBSET moi_s35_ttube`] THEN
  SET_TAC[]);;

(* The region between two consecutive extended circles lies in A0.        *)

let MOI_S5C_CONS_RG_A0 = prove
 (`!B K FF GG Q c d0 X Y.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_cons B (GG:real^3->real^2) c X Y
     ==> moi_s5c_rg X Y SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1]))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `X:real^2->bool`;
    `Y:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MAP_EVERY (fun k -> ASSUME_TAC(el k (CONJUNCTS th))) [0;1;2;3]) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_EXT_ORDER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ASSUME_TAC o CONJUNCT1)] THEN
  SUBGOAL_THEN `X SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1])) /\ Y SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1]))` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `moi_s5c_cons B (GG:real^3->real^2) c X Y` THEN
    REWRITE_TAC[moi_s5c_cons] THEN STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RG_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o el 6 o CONJUNCTS) THEN
  MAP_EVERY UNDISCH_TAC
   [`moi_s5c_rgo X Y SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1]))`; `X SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1]))`; `Y SUBSET (interval[--vector[&2;&2]:real^2,vector[&2;&2]] DIFF interval(--vector[&1;&1]:real^2,vector[&1;&1]))`] THEN
  SET_TAC[]);;

(* The two down neighbour regions of the minimal middle up region.          *)

let MOI_S5C_M_NB = prove
 (`!B K FF GG Q c d0 Ja Jb s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     &0 < s /\ s < &1
     ==> ?W Z. moi_s5c_cons B GG c W (IMAGE (GG:real^3->real^2) Ja) /\ moi_s5c_cons B GG c (IMAGE (GG:real^3->real^2) Jb) Z /\
               {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s} SUBSET (IMAGE (FF:real^2->real^3) (moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja))) /\ {(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s} SUBSET (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Jb) Z)) /\
               (IMAGE (FF:real^2->real^3) (moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja))) DIFF ({(Q:real^3->real->real^3) x (-- &1 * u) | x IN Ja /\ &0 <= u /\ u <= s} DIFF (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))) = IMAGE (FF:real^2->real^3) (moi_s5c_rg W (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s)))) /\
               connected (IMAGE (FF:real^2->real^3) (moi_s5c_rg W (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Ja (-- &1 * s))))) /\
               (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Jb) Z)) DIFF ({(Q:real^3->real->real^3) x (-- &1 * u) | x IN Jb /\ &0 <= u /\ u <= s} DIFF (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) = IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) Z) /\
               connected (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) (moi_s5c_sec (Q:real^3->real->real^3) Jb (-- &1 * s))) Z)) /\
               (IMAGE (FF:real^2->real^3) (moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja))) IN components {x:real^3 | x IN B /\ x$3 <= c} /\ (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Jb) Z)) IN components {x:real^3 | x IN B /\ x$3 <= c} /\
               (IMAGE (FF:real^2->real^3) (moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja))) INTER (IMAGE (FF:real^2->real^3) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Jb) Z)) = {}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `s:real`] MOI_S5C_NB_LEFT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:real^2->bool` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `s:real`] MOI_S5C_NB_RIGHT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Z:real^2->bool` STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`W:real^2->bool`; `Z:real^2->bool`] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `{x:real^3 | x IN B /\ x$3 <= c} = {x:real^3 | x IN B /\ &0 <= -- &1 * (x$3 - c)}` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `-- &1`]
    MOI_S5C_SIDE_COMPONENTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[IN_ELIM_THM] THEN CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`W:real^2->bool`; `(IMAGE (GG:real^3->real^2) Ja)`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`(IMAGE (GG:real^3->real^2) Jb)`; `Z:real^2->bool`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `s:real`] MOI_S5C_MUP_A0) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  SUBGOAL_THEN `~((IMAGE (GG:real^3->real^2) Ja) = Z)` ASSUME_TAC THENL
   [DISCH_TAC THEN
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `(IMAGE (GG:real^3->real^2) Jb)`;
      `Z:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(MP_TAC o el 2 o CONJUNCTS)] THEN
    UNDISCH_TAC `(IMAGE (GG:real^3->real^2) Ja) = Z` THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    DISCH_TAC THEN
    MP_TAC(ISPECL [`(IMAGE (GG:real^3->real^2) Ja)`; `(IMAGE (GG:real^3->real^2) Jb)`] MOI_S5C_NEST_ASYM) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `-- &1`;
    `W:real^2->bool`; `(IMAGE (GG:real^3->real^2) Ja)`; `(IMAGE (GG:real^3->real^2) Jb)`; `Z:real^2->bool`] MOI_S5C_SIDE_DISJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
    `moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja)`; `moi_s5c_rg (IMAGE (GG:real^3->real^2) Jb) Z`] MOI_S5C_FF_INJ_OPS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN MATCH_MP_TAC MOI_S5C_CONS_RG_A0 THEN
    MAP_EVERY EXISTS_TAC [`B:real^3->bool`; `K:(real^3->bool)->bool`;
      `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`;
      `c:real`; `d0:real`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(SUBST1_TAC o CONJUNCT1)] THEN
  UNDISCH_TAC `DISJOINT (moi_s5c_rg W (IMAGE (GG:real^3->real^2) Ja)) (moi_s5c_rg (IMAGE (GG:real^3->real^2) Jb) Z)` THEN
  REWRITE_TAC[DISJOINT] THEN DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[IMAGE_CLAUSES]);;

(* The two ends of a consecutive pair lie in its region.                    *)

let MOI_S5C_CONS_RG_ENDS = prove
 (`!B K FF GG Q c d0 X Y.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\
     moi_s5c_cons B (GG:real^3->real^2) c X Y
     ==> X SUBSET moi_s5c_rg X Y /\ Y SUBSET moi_s5c_rg X Y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `X:real^2->bool`;
    `Y:real^2->bool`] MOI_S5C_CONS_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MAP_EVERY (fun k -> ASSUME_TAC(el k (CONJUNCTS th))) [0;1;2]) THEN
  MP_TAC(ISPECL [`X:real^2->bool`; `Y:real^2->bool`] MOI_S5C_RG_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o el 6 o CONJUNCTS) THEN SET_TAC[]);;

(* A circle does not lie inside itself.                                     *)

let MOI_S5C_NOT_SELF_INSIDE = prove
 (`!X:real^2->bool. pl_sphere 1 X ==> ~(X SUBSET inside X)`,
  REPEAT STRIP_TAC THEN MP_TAC(ISPEC `X:real^2->bool` INSIDE_NO_OVERLAP) THEN
  SUBGOAL_THEN `~(X:real^2->bool = {})` MP_TAC THENL
   [ASM_MESON_TAC[MOI_SCD_PL_SPHERE_NONEMPTY]; ALL_TAC] THEN
  UNDISCH_TAC `(X:real^2->bool) SUBSET inside X` THEN SET_TAC[]);;

(* There is a third circle: otherwise both outer regions of B would be down *)
(* regions containing a boundary circle, against the lower clause of B.     *)

let MOI_S5C_M_THIRD = prove
 (`!B K FF GG Q c d0 Ja Jb s.
     moi_s5c_mset B K FF GG Q c d0 /\ moi_s5c_hyp B c /\ moi_s5c_mup B FF GG c Ja Jb /\
     &0 < s /\ s < &1
     ==> ?J. J IN components {x:real^3 | x IN B /\ x$3 = c} /\ ~(J = Ja) /\ ~(J = Jb)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `s:real`] MOI_S5C_M_NB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:real^2->bool` (X_CHOOSE_THEN `Z:real^2->bool`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`; `Jb:real^3->bool`; `s:real`] MOI_S5C_MUP_A0) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; STRIP_TAC] THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[moi_s5c_mup] o
    check (MOI_S5C_HEAD "moi_s5c_mup")) THEN
  MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
  DISCH_THEN(LABEL_TAC "two" o REWRITE_RULE[NOT_EXISTS_THM]) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`; `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_EXT_ORDER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> LABEL_TAC "self" (el 3 (CONJUNCTS th))) THEN
  SUBGOAL_THEN `W = (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `W:real^2->bool`;
      `(IMAGE (GG:real^3->real^2) Ja)`] MOI_S5C_CONS_ENDS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(el 2 (CONJUNCTS th))) THEN
    ASM_CASES_TAC `W = (relative_frontier(interval[--vector[&1;&1]:real^2,vector[&1;&1]]))` THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `J:real^3->bool` STRIP_ASSUME_TAC) THEN
    USE_THEN "two" (MP_TAC o SPEC `J:real^3->bool`) THEN
    REWRITE_TAC[ASSUME `J IN components {x:real^3 | x IN B /\ x$3 = c}`] THEN
    CONJ_TAC THEN DISCH_THEN SUBST_ALL_TAC THEN
    UNDISCH_TAC `moi_s5c_cons B (GG:real^3->real^2) c W (IMAGE (GG:real^3->real^2) Ja)` THEN
    ASM_REWRITE_TAC[moi_s5c_cons] THEN STRIP_TAC THENL
     [MP_TAC(ISPEC `(IMAGE (GG:real^3->real^2) Ja)` MOI_S5C_NOT_SELF_INSIDE) THEN ASM_REWRITE_TAC[];
      MP_TAC(ISPECL [`(IMAGE (GG:real^3->real^2) Ja)`; `(IMAGE (GG:real^3->real^2) Jb)`] MOI_S5C_NEST_ASYM) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `Z = (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `(IMAGE (GG:real^3->real^2) Jb)`;
      `Z:real^2->bool`] MOI_S5C_CONS_ENDS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(el 3 (CONJUNCTS th))) THEN
    ASM_CASES_TAC `Z = (relative_frontier(interval[--vector[&2;&2]:real^2,vector[&2;&2]]))` THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `J:real^3->bool` STRIP_ASSUME_TAC) THEN
    USE_THEN "two" (MP_TAC o SPEC `J:real^3->bool`) THEN
    REWRITE_TAC[ASSUME `J IN components {x:real^3 | x IN B /\ x$3 = c}`] THEN
    CONJ_TAC THEN DISCH_THEN SUBST_ALL_TAC THEN
    UNDISCH_TAC `moi_s5c_cons B (GG:real^3->real^2) c (IMAGE (GG:real^3->real^2) Jb) Z` THEN
    ASM_REWRITE_TAC[moi_s5c_cons] THEN STRIP_TAC THENL
     [MP_TAC(ISPECL [`(IMAGE (GG:real^3->real^2) Ja)`; `(IMAGE (GG:real^3->real^2) Jb)`] MOI_S5C_NEST_ASYM) THEN ASM_REWRITE_TAC[];
