    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`; `Ja:real^3->bool`;
    `Jb:real^3->bool`] MOI_S5C_MUP_FACTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(MP_TAC o last o CONJUNCTS)] THEN
  STRIP_TAC THENL
   [MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `Ja:real^3->bool`; `Jb:real^3->bool`; `Ja:real^3->bool`; `Jb:real^3->bool`;
      `&1 / &2`] MOI_S5C_MODEL_J);
    MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
      `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`;
      `Ja:real^3->bool`; `Jb:real^3->bool`; `Jb:real^3->bool`; `Ja:real^3->bool`;
      `&1 / &2`] MOI_S5C_MODEL_J)] THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The main theorem MOI_S5C_ANNULUS_SWAP_SPLIT.  From the model             *)
(* construction (MOI_S5C_MODEL), the caps (MOI_S5C_CAPS), Schoenflies and   *)
(* the theta argument: the annulus swap step of Moise 35.1 Lemma 3 (p.251), *)
(* with MOI_SCH3_SPHERE_SPLIT as an antecedent.                             *)
(* ------------------------------------------------------------------------- *)

let MOI_S5C_INJ_TAC (x:term) (y:term) : tactic =
  USE_THEN "inj" (MP_TAC o SPECL [x; y]) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; SIMP_TAC[]];;

let MOI_S5C_ANNULUS_SWAP_SPLIT = prove
 (mk_imp(MOI_SCH3_SPHERE_SPLIT, MOI_S35_ANNULUS_SWAP),
  DISCH_THEN(LABEL_TAC "split") THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sch3")
    (CONJUNCTS_THEN2 (LABEL_TAC "lem1") (LABEL_TAC "slab"))) THEN
  MAP_EVERY X_GEN_TAC [`phi:real^3->real^3`; `xa:real^3->bool`; `xb:real^3->bool`;
    `ww:real^3->bool`; `b:real^3->bool`; `b0:real^3->bool`; `b1:real^3->bool`;
    `c:real`] THEN
  STRIP_TAC THEN
  REMOVE_THEN "lem1" (MP_TAC o SPECL [`phi:real^3->real^3`; `xa:real^3->bool`;
    `xb:real^3->bool`; `ww:real^3->bool`; `b:real^3->bool`; `b0:real^3->bool`;
    `b1:real^3->bool`; `c:real`] o C MP (ISPEC `(:3)` MOISE_273)) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  USE_THEN "slab" (MP_TAC o SPECL [`phi:real^3->real^3`; `xa:real^3->bool`;
    `xb:real^3->bool`; `ww:real^3->bool`; `b:real^3->bool`; `b0:real^3->bool`;
    `b1:real^3->bool`; `c:real`] o MATCH_MP MOI_S5C_SETUP) THEN
  ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `B = {x | x IN moi_s35_dom /\ (phi:real^3->real^3) x IN b}` THEN
  DISCH_THEN(X_CHOOSE_THEN `K:(real^3->bool)->bool` (X_CHOOSE_THEN `FF:real^2->real^3`
   (X_CHOOSE_THEN `GG:real^3->real^2` (X_CHOOSE_THEN `Q:real^3->real->real^3`
   (X_CHOOSE_THEN `d0:real` (X_CHOOSE_THEN `psi:real^3->real^3` STRIP_ASSUME_TAC)))))) THEN
  MP_TAC(ISPECL [`B:real^3->bool`; `K:(real^3->bool)->bool`; `FF:real^2->real^3`;
    `GG:real^3->real^2`; `Q:real^3->real->real^3`; `c:real`; `d0:real`] MOI_S5C_MODEL) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `B':real^3->bool` (X_CHOOSE_THEN `Rem:real^3->bool`
   (X_CHOOSE_THEN `N':real^3->bool` (X_CHOOSE_THEN `U:real^3->bool`
   (X_CHOOSE_THEN `kk0:real^3->bool` MP_TAC))))) THEN
  REWRITE_TAC[moi_s5c_out] THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o REWRITE_RULE[moi_s35_edge_conf] o check
    (MOI_S5C_HEAD "moi_s35_edge_conf")) THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`phi:real^3->real^3`; `b:real^3->bool`] MOI_S5C_B_SUB) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `B SUBSET moi_s35_dom /\ B' SUBSET moi_s35_dom /\
                interior moi_s35_stube SUBSET moi_s35_dom /\
                moi_s5c_otube SUBSET moi_s5c_u /\ moi_s5c_otube SUBSET moi_s35_ttube /\
                moi_s35_ttube SUBSET moi_s5c_u /\
                moi_s35_ttube SUBSET interior moi_s35_stube`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`B SUBSET interior moi_s35_stube`;
                           `B' SUBSET interior moi_s35_stube`] THEN
    MP_TAC MOI_S5C_TUBES THEN MP_TAC MOI_S5C_OTUBE THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP MOI_S5C_PL_BALL_3_FILL (ASSUME `pl_ball 3 (xb:real^3->bool)`)) THEN
  ABBREV_TAC `S:real^3->bool = frontier xb` THEN STRIP_TAC THEN
  USE_THEN "split" (MP_TAC o SPECL [`S:real^3->bool`; `b:real^3->bool`; `b0:real^3->bool`;
    `b1:real^3->bool`] o MATCH_MP MOI_S5C_CAPS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `D0:real^3->bool` (X_CHOOSE_THEN `D1:real^3->bool`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `pl_polyhedron(B':real^3->bool) /\ compact (B':real^3->bool)`
  STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `pl_polyhedron(B':real^3->bool)` ASSUME_TAC THENL
     [REWRITE_TAC[PL_POLYHEDRON_EQ_SIMPLICIAL_COMPLEX] THEN
      EXISTS_TAC `L:(real^3->bool)->bool` THEN ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[PL_POLYHEDRON_IMP_COMPACT]];
    ALL_TAC] THEN
  SUBGOAL_THEN `!X Y:real^3->bool. X SUBSET moi_s35_dom /\ Y SUBSET moi_s35_dom
     ==> IMAGE (phi:real^3->real^3) X INTER IMAGE phi Y = IMAGE phi (X INTER Y) /\
         IMAGE phi X DIFF IMAGE phi Y = IMAGE phi (X DIFF Y) /\
         (IMAGE phi X SUBSET IMAGE phi Y <=> X SUBSET Y) /\
         (!x. x IN moi_s35_dom ==> (phi x IN IMAGE phi X <=> x IN X))`
  (LABEL_TAC "inj") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC MOI_S5C_IMAGE_INJ_OPS THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`B':real^3->bool`; `phi:real^3->real^3`] MOI_S5C_PL_EMBED) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC PL_MAP_ON_SUBSET THEN EXISTS_TAC `moi_s35_dom` THEN
      ASM_SIMP_TAC[LOCALLY_POLYHEDRAL_PL_POLYHEDRON];
      UNDISCH_TAC `B' SUBSET moi_s35_dom` THEN
      MP_TAC(ASSUME `!x y. x IN moi_s35_dom /\ y IN moi_s35_dom /\
                           (phi:real^3->real^3) x = phi y ==> x = y`) THEN
      SET_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `psi':real^3->real^3`) THEN
  ABBREV_TAC `b' = IMAGE (phi:real^3->real^3) B'` THEN
  SUBGOAL_THEN `pl_annulus_with_ends (b':real^3->bool) b0 b1` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`B':real^3->bool`;
      `IMAGE (FF:real^2->real^3) (relative_frontier
          (interval[--vector[&1;&1]:real^2,vector[&1;&1]]))`;
      `IMAGE (FF:real^2->real^3) (relative_frontier
          (interval[--vector[&2;&2]:real^2,vector[&2;&2]]))`;
      `b':real^3->bool`; `phi:real^3->real^3`; `psi':real^3->real^3`]
      MOI_S5C_ANN_TRANSFER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP MOI_S5C_CELL_COMPACT2 (ASSUME `pl_cell_with_boundary 2 (D0:real^3->bool) b0`)) THEN
  MP_TAC(MATCH_MP MOI_S5C_CELL_COMPACT2 (ASSUME `pl_cell_with_boundary 2 (D1:real^3->bool) b1`)) THEN
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `D0 INTER IMAGE (phi:real^3->real^3) moi_s35_ttube = {} /\
                D1 INTER IMAGE (phi:real^3->real^3) moi_s35_ttube = {}`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`S:real^3->bool = D0 UNION b UNION D1`;
      `S INTER IMAGE (phi:real^3->real^3) moi_s35_ttube SUBSET b`;
      `D0 INTER b:real^3->bool = b0`; `D1 INTER b:real^3->bool = b1`;
      `DISJOINT (b0 UNION b1) (IMAGE (phi:real^3->real^3) moi_s35_ttube)`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `closure U SUBSET moi_s35_ttube /\ bounded (U:real^3->bool)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC MOI_S5C_TUBES THEN MP_TAC MOI_S5C_OTUBE THEN REPEAT STRIP_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `closure moi_s5c_otube` THEN
      ASM_SIMP_TAC[SUBSET_CLOSURE];
      MATCH_MP_TAC BOUNDED_SUBSET THEN EXISTS_TAC `moi_s35_ttube` THEN
      ASM_REWRITE_TAC[] THEN ASM SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (phi:real^3->real^3) Rem SUBSET IMAGE phi moi_s35_ttube /\
    IMAGE (phi:real^3->real^3) N' SUBSET IMAGE phi moi_s35_ttube /\
    IMAGE (phi:real^3->real^3) (closure U) SUBSET IMAGE phi moi_s35_ttube /\
    closure U SUBSET moi_s35_dom /\ Rem SUBSET moi_s35_dom /\ N' SUBSET moi_s35_dom /\
    B INTER B' SUBSET moi_s35_dom /\ kk0 SUBSET moi_s35_dom /\ U SUBSET moi_s35_dom /\
    U SUBSET closure U`
  STRIP_ASSUME_TAC THENL
   [MP_TAC MOI_S5C_TUBES THEN MP_TAC MOI_S5C_OTUBE THEN REPEAT STRIP_TAC THEN
    TRY(MATCH_MP_TAC IMAGE_SUBSET) THEN
    MAP_EVERY UNDISCH_TAC
     [`Rem SUBSET moi_s35_ttube`; `N' SUBSET moi_s5c_otube`; `U SUBSET moi_s5c_otube`;
      `closure U SUBSET moi_s35_ttube`; `B SUBSET moi_s35_dom`;
      `(B INTER B') INTER Rem:real^3->bool = kk0`] THEN
    MP_TAC(ISPEC `U:real^3->bool` CLOSURE_SUBSET) THEN
    MAP_EVERY UNDISCH_TAC
     [`moi_s5c_otube SUBSET moi_s35_ttube`; `moi_s35_ttube SUBSET interior moi_s35_stube`;
      `interior moi_s35_stube SUBSET moi_s35_dom`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (phi:real^3->real^3) (B INTER B') UNION IMAGE phi Rem = b /\
    IMAGE (phi:real^3->real^3) (B INTER B') UNION IMAGE phi N' = b'`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [UNDISCH_TAC `IMAGE (phi:real^3->real^3) B = b` THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN
      UNDISCH_TAC `(B INTER B') UNION Rem:real^3->bool = B` THEN
      DISCH_THEN(fun th -> GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [SYM th]) THEN
      REWRITE_TAC[IMAGE_UNION];
      UNDISCH_TAC `IMAGE (phi:real^3->real^3) B' = b'` THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN
      UNDISCH_TAC `(B INTER B') UNION N':real^3->bool = B'` THEN
      DISCH_THEN(fun th -> GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [SYM th]) THEN
      REWRITE_TAC[IMAGE_UNION]];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP MOI_S5C_ANN_ENDS_SUBSET (ASSUME
    `pl_annulus_with_ends (b':real^3->bool) b0 b1`)) THEN STRIP_TAC THEN
  SUBGOAL_THEN `D0 INTER IMAGE (phi:real^3->real^3) N' = {} /\
                D1 INTER IMAGE (phi:real^3->real^3) N' = {} /\
                D0 INTER IMAGE (phi:real^3->real^3) Rem = {} /\
                D1 INTER IMAGE (phi:real^3->real^3) Rem = {}`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`D0 INTER IMAGE (phi:real^3->real^3) moi_s35_ttube = {}`;
      `D1 INTER IMAGE (phi:real^3->real^3) moi_s35_ttube = {}`;
      `IMAGE (phi:real^3->real^3) N' SUBSET IMAGE phi moi_s35_ttube`;
      `IMAGE (phi:real^3->real^3) Rem SUBSET IMAGE phi moi_s35_ttube`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (phi:real^3->real^3) (B INTER B') SUBSET b` ASSUME_TAC THENL
   [UNDISCH_TAC `IMAGE (phi:real^3->real^3) (B INTER B') UNION IMAGE phi Rem = b` THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `D0 INTER b':real^3->bool = b0` ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`IMAGE (phi:real^3->real^3) (B INTER B') UNION IMAGE phi N' = b'`;
      `D0 INTER b:real^3->bool = b0`;
      `D0 INTER IMAGE (phi:real^3->real^3) N' = {}`;
      `IMAGE (phi:real^3->real^3) (B INTER B') SUBSET b`;
      `b0 SUBSET (D0:real^3->bool)`; `b0 SUBSET (b':real^3->bool)`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `D1 INTER b':real^3->bool = b1` ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`IMAGE (phi:real^3->real^3) (B INTER B') UNION IMAGE phi N' = b'`;
      `D1 INTER b:real^3->bool = b1`;
      `D1 INTER IMAGE (phi:real^3->real^3) N' = {}`;
      `IMAGE (phi:real^3->real^3) (B INTER B') SUBSET b`;
      `b1 SUBSET (D1:real^3->bool)`; `b1 SUBSET (b':real^3->bool)`] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `pl_sphere 2 (D0 UNION b' UNION D1:real^3->bool)` ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_SPH3 THEN
    MAP_EVERY EXISTS_TAC [`b0:real^3->bool`; `b1:real^3->bool`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  ABBREV_TAC `S':real^3->bool = D0 UNION b' UNION D1` THEN
  SUBGOAL_THEN `pl_ball 3 (S' UNION inside S':real^3->bool) /\
                frontier (S' UNION inside S':real^3->bool) = S'`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "sch3" (MP_TAC o REWRITE_RULE[PL_SCHOENFLIES_3_STATEMENT]) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC MOI_S5C_FILL_FRONTIER THEN
      REWRITE_TAC[DIMINDEX_3; ARITH] THEN
      ASM_SIMP_TAC[MOI_S5C_PLSPH_JB]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(phi:real^3->real^3) continuous_on moi_s35_dom` ASSUME_TAC THENL
   [ASM_SIMP_TAC[PL_MAP_ON_IMP_CONTINUOUS_ON]; ALL_TAC] THEN
  SUBGOAL_THEN
   `compact (IMAGE (phi:real^3->real^3) (B INTER B')) /\
    compact (IMAGE (phi:real^3->real^3) Rem) /\
    compact (IMAGE (phi:real^3->real^3) N') /\
    compact (IMAGE (phi:real^3->real^3) (closure U))`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC COMPACT_CONTINUOUS_IMAGE THEN
    ASM_REWRITE_TAC[COMPACT_CLOSURE] THEN MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
    EXISTS_TAC `moi_s35_dom` THEN ASM_REWRITE_TAC[UNION_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `closure (IMAGE (phi:real^3->real^3) U) =
    IMAGE phi U UNION IMAGE phi Rem UNION IMAGE phi N'`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`phi:real^3->real^3`; `U:real^3->bool`] MOI_S5C_PHI_CLOSURE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    UNDISCH_TAC `closure U = U UNION Rem UNION N':real^3->bool` THEN
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[IMAGE_UNION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(S' UNION inside S') DIFF closure (IMAGE (phi:real^3->real^3) U) =
    (S UNION inside S) DIFF closure (IMAGE phi U)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC MOI_S5C_THETA_APPLY THEN
    MAP_EVERY EXISTS_TAC
     [`D0 UNION IMAGE (phi:real^3->real^3) (B INTER B') UNION D1`;
      `IMAGE (phi:real^3->real^3) Rem`; `IMAGE (phi:real^3->real^3) N'`;
      `IMAGE (phi:real^3->real^3) kk0`] THEN
    SUBGOAL_THEN
     `IMAGE (phi:real^3->real^3) Rem DIFF IMAGE phi kk0 = IMAGE phi (Rem DIFF kk0) /\
      IMAGE (phi:real^3->real^3) N' DIFF IMAGE phi kk0 = IMAGE phi (N' DIFF kk0) /\
      IMAGE (phi:real^3->real^3) Rem INTER IMAGE phi N' = IMAGE phi (Rem INTER N') /\
      IMAGE (phi:real^3->real^3) (B INTER B') INTER IMAGE phi Rem =
      IMAGE phi ((B INTER B') INTER Rem) /\
      IMAGE (phi:real^3->real^3) (B INTER B') INTER IMAGE phi N' =
      IMAGE phi ((B INTER B') INTER N') /\
      IMAGE (phi:real^3->real^3) U INTER IMAGE phi B = IMAGE phi (U INTER B) /\
      IMAGE (phi:real^3->real^3) U INTER IMAGE phi N' = IMAGE phi (U INTER N')`
    (fun th -> REWRITE_TAC[th] THEN STRIP_ASSUME_TAC th) THENL
     [REPEAT CONJ_TAC THENL
       [MOI_S5C_INJ_TAC `Rem:real^3->bool` `kk0:real^3->bool`;
        MOI_S5C_INJ_TAC `N':real^3->bool` `kk0:real^3->bool`;
        MOI_S5C_INJ_TAC `Rem:real^3->bool` `N':real^3->bool`;
        MOI_S5C_INJ_TAC `B INTER B':real^3->bool` `Rem:real^3->bool`;
        MOI_S5C_INJ_TAC `B INTER B':real^3->bool` `N':real^3->bool`;
        MOI_S5C_INJ_TAC `U:real^3->bool` `B:real^3->bool`;
        MOI_S5C_INJ_TAC `U:real^3->bool` `N':real^3->bool`];
      ALL_TAC] THEN
    SUBGOAL_THEN `IMAGE (phi:real^3->real^3) U INTER S = {}` ASSUME_TAC THENL
     [SUBGOAL_THEN `IMAGE (phi:real^3->real^3) U SUBSET IMAGE phi moi_s35_ttube`
      MP_TAC THENL
       [MATCH_MP_TAC IMAGE_SUBSET THEN
        MAP_EVERY UNDISCH_TAC [`U SUBSET moi_s5c_otube`;
                               `moi_s5c_otube SUBSET moi_s35_ttube`] THEN
        SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `IMAGE (phi:real^3->real^3) U INTER IMAGE phi B = {}` MP_TAC THENL
       [REWRITE_TAC[ASSUME
          `IMAGE (phi:real^3->real^3) U INTER IMAGE phi B = IMAGE phi (U INTER B)`;
          ASSUME `U INTER B:real^3->bool = {}`; IMAGE_CLAUSES];
        ALL_TAC] THEN
      MAP_EVERY UNDISCH_TAC
       [`S INTER IMAGE (phi:real^3->real^3) moi_s35_ttube SUBSET b`;
        `IMAGE (phi:real^3->real^3) B = b`] THEN
      SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `IMAGE (phi:real^3->real^3) U INTER IMAGE phi N' = {}` ASSUME_TAC THENL
     [REWRITE_TAC[ASSUME
        `IMAGE (phi:real^3->real^3) U INTER IMAGE phi N' = IMAGE phi (U INTER N')`] THEN
      SUBGOAL_THEN `U INTER N':real^3->bool = {}` (fun th -> REWRITE_TAC[th; IMAGE_CLAUSES]) THEN
      UNDISCH_TAC `U INTER (Rem UNION N'):real^3->bool = {}` THEN SET_TAC[];
      ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      MAP_EVERY UNDISCH_TAC
       [`S:real^3->bool = D0 UNION b UNION D1`;
        `IMAGE (phi:real^3->real^3) (B INTER B') UNION IMAGE phi Rem = b`] THEN
      MOI_S5C_ABS_SET_TAC [`IMAGE (phi:real^3->real^3) (B INTER B')`;
                           `IMAGE (phi:real^3->real^3) Rem`];
      MAP_EVERY UNDISCH_TAC
       [`D0 UNION b' UNION D1:real^3->bool = S'`;
        `IMAGE (phi:real^3->real^3) (B INTER B') UNION IMAGE phi N' = b'`] THEN
      MOI_S5C_ABS_SET_TAC [`IMAGE (phi:real^3->real^3) (B INTER B')`;
                           `IMAGE (phi:real^3->real^3) N'`];
      REPEAT(MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC) THEN
      MATCH_MP_TAC COMPACT_IMP_CLOSED THEN FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC COMPACT_IMP_CLOSED THEN FIRST_ASSUM ACCEPT_TAC;
