   [FIRST_ASSUM(MP_TAC o SPEC `&3 / &16` o check (fun th -> is_forall(concl th) && free_in `moi_s35_sq` (concl th) && free_in `cW:real^3->bool` (concl th))) THEN REWRITE_TAC[] THEN
    UNDISCH_TAC `IMAGE (phi:real^3->real^3) (moi_s35_sq (&3 / &16) c) SUBSET interior xb` THEN
    MOI_S5C_ABS_SET_TAC [`IMAGE (phi:real^3->real^3) (moi_s35_sq (&3 / &16) c)`;
                         `interior (xb:real^3->bool)`];
    MATCH_MP_TAC INTERIOR_MAXIMAL THEN CONJ_TAC THENL
     [MP_TAC(ISPEC `xb:real^3->bool` INTERIOR_SUBSET) THEN
      UNDISCH_TAC `(S' UNION inside S') DIFF cW = (S UNION inside S) DIFF (cW:real^3->bool)` THEN
      UNDISCH_TAC `xb:real^3->bool = S UNION inside S` THEN
      MOI_S5C_ABS_SET_TAC [`interior (xb:real^3->bool)`; `inside (S:real^3->bool)`;
                           `inside (S':real^3->bool)`];
      MATCH_MP_TAC OPEN_DIFF THEN ASM_REWRITE_TAC[OPEN_INTERIOR]]];
    FIRST_ASSUM(MP_TAC o SPEC `&5 / &16` o check (fun th -> is_forall(concl th) && free_in `moi_s35_sq` (concl th) && free_in `cW:real^3->bool` (concl th))) THEN REWRITE_TAC[] THEN
  UNDISCH_TAC `DISJOINT (IMAGE (phi:real^3->real^3) (moi_s35_sq (&5 / &16) c)) xb` THEN
  UNDISCH_TAC `(S' UNION inside S') SUBSET (S UNION inside S) UNION (cW:real^3->bool)` THEN
  UNDISCH_TAC `xb:real^3->bool = S UNION inside S` THEN
  MOI_S5C_ABS_SET_TAC [`IMAGE (phi:real^3->real^3) (moi_s35_sq (&5 / &16) c)`;
                       `inside (S:real^3->bool)`; `inside (S':real^3->bool)`];
    MP_TAC(REWRITE_RULE[moi_s5c_clause] (ASSUME `moi_s5c_clause {x | x IN B' /\ x$3 <= c}`)) THEN
  REWRITE_TAC[];
    MP_TAC(REWRITE_RULE[moi_s5c_clause] (ASSUME `moi_s5c_clause {x | x IN B' /\ c <= x$3}`)) THEN
  REWRITE_TAC[];
    EXISTS_TAC `L:(real^3->bool)->bool` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    EXISTS_TAC `closure U:real^3->bool` THEN REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[COMPACT_CLOSURE];
    MP_TAC MOI_S5C_TUBES THEN UNDISCH_TAC `closure U SUBSET moi_s35_ttube` THEN SET_TAC[];
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_UNION; NOT_IN_EMPTY; moi_s35_sq;
                IN_ELIM_THM] THEN
    X_GEN_TAC `x:real^3` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real^3` o check (fun th -> is_forall(concl th) &&
      free_in `closure (U:real^3->bool)` (concl th) && free_in `moi_s35_n` (concl th))) THEN
    ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
    REWRITE_TAC[ASSUME `IMAGE (phi:real^3->real^3) (closure U) = cW`] THEN
    FIRST_ASSUM ACCEPT_TAC]]);;

